window.SIDX=window.SIDX||{};window.SIDX["nicao"]={"title": "四分比丘尼鈔", "entries": [{"v": "卷上", "o": "南山五大部之四　唐·道宣律師　述　三卷（上、中、下，各分上下）", "t": "本書是南山五大部中的第四部，由唐代道宣律師撰述。全書分為上、中、下三卷，每一卷又各分上、下兩部分。", "i": "u01", "n": 1, "s": "卷首"}, {"v": "卷上", "o": "底本：《卍新纂大日本續藏經》第40冊 No.724（X40n0724）", "t": "本譯文所依據的底本，是《卍新纂大日本續藏經》第40冊所收的第724號典籍（編號 X40n0724）。", "i": "u02", "n": 2, "s": "卷首"}, {"v": "卷上", "o": "No. 724-A 四分律比丘尼鈔卷上(并序)", "t": "No. 724-A《四分律比丘尼鈔》上卷（附序文）", "i": "u03", "n": 3, "s": "卷首"}, {"v": "卷上", "o": "No. 724-A 四分律比丘尼鈔卷上", "t": "No. 724-A：《四分律比丘尼鈔》卷上", "i": "u04", "n": 4, "s": "卷首"}, {"v": "卷上", "o": "終南山沙門釋　道宣　述", "t": "終南山的沙門釋道宣撰述。", "i": "u05", "n": 5, "s": "卷首"}, {"v": "卷上", "o": "原夫別解脫戒，始制鹿野之初；毗尼法藏，終被鶴林之後。窯治七眾，藻鏡四依；慈風扇於五天，德音播於三界。繇是坦羣類之夷途，拯含靈之弱喪，為四生之標幟，作六趣之舟航者也。", "t": "推究起來，別解脫戒最初制定於鹿野苑初轉法輪之時；毗尼法藏則一直覆被到佛陀涅槃的鶴林之後。它像窯灶燒陶、爐冶鑄器那樣陶冶鑄就七眾弟子，像明鏡那樣照察四依聖賢；慈悲之風吹遍五天竺，德音遠播於三界。因此，它為眾生鋪平平坦的大道，拯救那些迷失而不知歸返的含靈眾生（如自幼離家、忘失歸途之人），作為四生眾生的標幟，作為六趣眾生的舟航。", "i": "u06", "n": 6, "s": "卷首"}, {"v": "卷上", "o": "時有愛道一人，舍夷五百，宿樹芳因，嘉聲遠著，深明業果，玅達苦空，迺能厭惡生死，訶毀家法，憑仗尊親，請佛求度。葢大聖玄鑒，知有自行之功，闕無弘傳之利，故逆止於內心，恐將生於外結。姨母情樂道門，愛重福田之服，自毀髮容，瞻戀祇桓之室，殷勤三請，佛遂許之。", "t": "當時有大愛道一人，與舍夷（釋種）的五百位女子，宿世已植下芬芳的善因，美好的聲譽遠近昭著，深深明白業因與果報，妙達苦與空之理，因而能夠厭惡生死、訶責毀棄居家之法，憑仗尊貴的親屬（佛陀），向佛陀請求出家得度。大聖佛陀玄深鑒照，知道她們雖有自行修證之功，卻欠缺弘傳正法之利，所以預先在內心遮止此事、不肯應允，所顧慮的是恐怕此舉會招致外來的譏嫌與繫縛。姨母一心欣樂佛道之門，愛重能生福田的袈裟，自行剃髮毀形，瞻望眷戀祇桓精舍，殷勤地三次請求，佛陀終於允許了。", "i": "u06-2", "n": 7, "s": "卷首"}, {"v": "卷上", "o": "正法理合千年，度尼減其五百；阿難憂泣，請度出家；佛令遵崇八敬，虔奉三尊；愛道聞持，正法弗墜。", "t": "正法原本理應住世千年，只因度尼出家，便減少了五百年。阿難（聞此）憂傷悲泣，仍代她們請求出家；佛陀便令她們遵崇八敬法，虔誠奉事三寶。大愛道聽聞受持，正法因而沒有墜失。", "i": "u06-3", "n": 8, "s": "卷首"}, {"v": "卷上", "o": "洎如來晦跡，慧日潛暉，女人戒德，漸將訛替，逢緣起障，解境生迷，遂有明暗異途，昇沈殊趣。故知浮海棄囊，巨壑終為難渡；涉途毀足，長路實不易行。若非精翫護持，戒品理難牢固。", "t": "等到如來隱晦蹤跡、智慧之日潛藏光輝之後，女眾的戒德漸漸訛謬衰替，遇到事緣便生起障礙，對境界的領解產生迷惑，於是有了明與暗的不同道路、上升與下沉的各異趣向。由此可知：渡海卻丟棄浮囊，巨大的海壑終究難以橫渡；趕路卻毀傷雙足，漫長的路途實在不容易行走。若不是精心研習、護持，戒品按理難以牢固。", "i": "u06-4", "n": 9, "s": "卷首"}, {"v": "卷上", "o": "余忝預道門，早承師訓，自慨庸識闇短，冥若夜遊，竭愚不已，稍染毫藤。每一事可觀，輒再詳心首，施身口之關鑰，識持犯之龜鏡，務存至簡，逐事省功。", "t": "我愧忝身列佛門，早年承受師長的教誨，自嘆見識平庸、昏暗淺短，如同在黑夜中行走。我不斷竭盡這點愚鈍之力，漸漸動筆蘸墨，寫在藤紙上；每遇到一件值得採錄的事，總要一再在心中審慎斟酌。此書為身口二業安設關防鎖鑰，作為使人認清持戒與犯戒的龜鏡。內容力求極其簡要，隨事節省功夫。", "i": "u06-5", "n": 10, "s": "卷首"}, {"v": "卷上", "o": "恐大本難通，勞而寡效，故制之以限分，遵之以積漸，猶天地二化，始合於自然；齊魯二變，終臻於至道。", "t": "因為恐怕根本大部的律典難以通曉，費力而收效甚少，所以用一定的分量加以裁制，讓人依循著逐步漸進。這就好比天地二氣的化育，起初便與自然相合；齊國一變而至於魯，魯國一變而至於道，歷經兩變，最終才達到至道。", "i": "u06-6", "n": 11, "s": "卷首"}, {"v": "卷上", "o": "若文義俱辨，復非鈔者所明；今輒研覈諸篇，撮其樞要，立章三十，勒成三卷。今所撰者，用《四分》為宗；斯文不具，更將諸部補闕；易簡為義，兼以人語會通；餘之不盡，文露可尋。", "t": "若要文與義都一一詳辨，那就不是作鈔的人所要闡明的了。如今我便研核諸篇，撮取其中的樞要，立為三十章，編定成三卷。現在所撰述的，以《四分律》為宗；這部律文若有不完備之處，就再取其他諸部律來補足缺闕。以簡易為宗旨，並兼用平易通俗的當代語言加以會通。其餘未能說盡的地方，原文俱在，可以自行尋檢。", "i": "u06-7", "n": 12, "s": "卷首"}, {"v": "卷上", "o": "篇目", "t": "各篇的目錄。", "i": "u07", "n": 13, "s": "卷首"}, {"v": "卷上", "o": "卷上之上：勸學篇第一、釋聚篇第二、結界篇第三、集眾篇第四、足數篇第五、受欲篇第六、十戒篇第七、學戒篇第八、畜眾篇第九", "t": "卷上之上：勸學篇第一、釋聚篇第二、結界篇第三、集眾篇第四、足數篇第五、受欲篇第六、十戒篇第七、學戒篇第八、畜眾篇第九。", "i": "u08", "n": 14, "s": "卷首"}, {"v": "卷上", "o": "卷上之下：具戒篇第十、六念篇第十一、受衣篇第十二、受盋篇第十三、淨施篇第十四、說戒篇第十五", "t": "卷上之下所收的篇章為：具戒篇第十、六念篇第十一、受衣篇第十二、受缽篇第十三、淨施篇第十四、說戒篇第十五。", "i": "u09", "n": 15, "s": "卷首"}, {"v": "卷上", "o": "卷中之上：安居篇第十六、受日篇第十七、自恣篇第十八、師徒篇第十九、致敬篇第二十、隨戒篇第二十一", "t": "卷中之上：安居篇第十六、受日篇第十七、自恣篇第十八、師徒篇第十九、致敬篇第二十、隨戒篇第二十一。", "i": "u10", "n": 16, "s": "卷首"}, {"v": "卷上", "o": "卷中之下：隨戒篇之餘", "t": "卷中之下：隨戒篇的其餘部分。", "i": "u11", "n": 17, "s": "卷首"}, {"v": "卷上", "o": "卷下之上：匡眾篇第二十二、翻淨篇第二十三、受藥篇第二十四、訃請篇第二十五、屆寺篇第二十六、懺悔篇第二十七", "t": "卷下之上所收錄的篇目為：〈匡眾篇〉第二十二、〈翻淨篇〉第二十三、〈受藥篇〉第二十四、〈訃請篇〉第二十五、〈屆寺篇〉第二十六、〈懺悔篇〉第二十七。", "i": "u12", "n": 18, "s": "卷首"}, {"v": "卷上", "o": "卷下之下：懺悔篇之餘、送終篇第二十八、二衣篇第二十九、雜要篇第三十", "t": "卷下之下：懺悔篇的其餘部分、送終篇第二十八、二衣篇第二十九、雜要篇第三十。", "i": "u13", "n": 19, "s": "卷首"}, {"v": "卷上", "o": "終南山沙門釋　道宣　述", "t": "由終南山的沙門釋道宣撰述。", "i": "u14", "n": 20, "s": "卷首"}, {"v": "卷上", "o": "○勸學篇第一", "t": "○勸勉修學篇第一", "i": "u15", "n": 21, "s": "第1篇　勸學"}, {"v": "卷上", "o": "此篇大門有三：一、順益，二、違損，三、業報。", "t": "這一篇的大綱分為三門：第一是「順益」，即隨順持戒所得的利益；第二是「違損」，即違犯戒律所招的損害；第三是「業報」，即持戒與犯戒所感得的善惡業果報應。", "i": "u16", "n": 22, "s": "第1篇　勸學"}, {"v": "卷上", "o": "第一順益者，《涅槃》云：「欲見佛性，證大涅槃，必須深心修持淨戒；若持是經而毀淨戒，是魔眷屬，非我弟子，我亦不聽受持是經。」", "t": "第一，隨順持戒的利益。《涅槃經》說：想要明見佛性、證得大涅槃，必須以深切殷重之心修持淨戒；倘若受持這部經卻毀犯淨戒，這人便是魔的眷屬，不是我的弟子，我也不允許他受持這部經。", "i": "u17", "n": 23, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《月燈三昧》云：「雖有色族及多聞，若無戒智猶禽獸；雖處卑下少聞見，能持淨戒名勝士。」", "t": "《月燈三昧經》說：雖然有端正的容貌、高貴的種姓，又博學多聞，若沒有戒與智慧，仍舊如同禽獸；雖然地位卑微低下、所聞所見不多，只要能受持淨戒，就稱為尊勝之士。", "i": "u17-2", "n": 24, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《華嚴經》云：「具足受持威儀教法，行六和敬，善御大眾，心無憂悔，順佛正法，不違其教，是故能令三寶不斷，法得久住。」又云：「戒是無上菩提本，應當具足持淨戒；若能堅持於淨戒，是則如來所讚歎。」", "t": "《華嚴經》說：具足受持威儀的教法，奉行六和敬，善於統領大眾，心中沒有憂惱悔恨，隨順佛的正法，不違背佛的教誡，因此能使三寶相續不斷，正法得以久住。又說：戒是無上菩提的根本，應當具足受持淨戒；若能堅持淨戒，這樣的人就是如來所讚歎的。", "i": "u17-3", "n": 25, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《持法經》云：「持二百五十戒者，現世可得阿羅漢、辟支佛涅槃。」\n《大智度論》云：「若求大利，當堅持戒，如惜重寶，如護身命。以戒是一切善法住處，持戒之人壽終之時，風刀解身，筋脈斷絕，心不怖畏。」", "t": "《持法經》說：受持二百五十戒的人，現世便能證得阿羅漢、辟支佛的涅槃。\n《大智度論》說：若想求得大利益，應當堅固持戒，如同愛惜貴重的珍寶，如同護惜自身的性命，因為戒是一切善法的安住之處。持戒的人在壽命終了之時，即使風大如刀割解身體、筋脈斷絕，心中也不恐怖畏懼。", "i": "u17-4", "n": 26, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《地持》云：「三十二相無差別因，皆由持戒所得；若不持戒，尚不得下賤人身，況復大人相報！」", "t": "《地持經》說：三十二相並沒有各自不同的因，全都是由於持戒而獲得的；若不持戒，連下賤的人身尚且得不到，更何況是大人相的果報呢？", "i": "u17-5", "n": 27, "s": "第1篇　勸學"}, {"v": "卷上", "o": "此律云：「持律之人得五種功德：一、戒品牢固，二、善勝諸怨，三、眾中決斷無畏，四、所有疑悔善能開解，五、善能持毗尼，令正法久住。」", "t": "《四分律》說：持律的人能得到五種功德：一、所受持的戒法堅固牢靠，不為毀犯所動搖；二、善能勝伏各種怨敵；三、在大眾中裁決斷事，無所畏懼；四、對於一切疑惑悔恨，都能善巧開解釋除；五、善能受持毗尼，使正法久住於世。", "i": "u17-6", "n": 28, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《十誦》云：「佛法幾時住世？」答：「隨清淨比丘說戒法不壞，名法住世。」\n《成實論》云：「道品樓觀，以戒為柱；禪定心城，以戒為郭。要佩戒印，得入善眾。」\n《五百問事》云：「若持戒者，即見法身；若護法者，便為護佛。如半月說戒，即見我也。", "t": "《十誦律》說：問：佛法能住世多久？答：只要清淨比丘說戒之法不壞失，就名為正法住世。\n《成實論》說：道品的樓閣，以戒作為支柱；禪定的心城，以戒作為外郭城牆；必須佩帶戒印，才能進入善人之眾。\n《五百問事經》說：若能持戒，就是見到法身；若能護法，便是護佛；就像每半月說戒，就是見到我一樣。", "i": "u17-7", "n": 29, "s": "第1篇　勸學"}, {"v": "卷上", "o": "第二違損者，《大品經》云：「我若不持戒，當墮三惡道中，尚不得下賤人身，況得成就眾生、淨佛國土、一切種智！」\n《薩遮尼犍經》云：「若不持戒，乃至不得疥癩野干身，何況當得功德之身！」", "t": "第二、違戒的損患。\n《大品經》說：「我如果不持戒，將來會墮入三惡道中，連下賤的人身尚且得不到，何況能成就眾生、清淨佛國土、證得一切種智呢？」\n《薩遮尼犍經》說：「若不持戒，甚至連長滿疥癩的野干身都得不到，何況能獲得功德之身？」", "i": "u18", "n": 30, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《梵網經》云：「若佛子，信心出家，受佛淨戒，故起心毀犯其戒者，不得受一切檀越供養，亦不得國王地上行，不得飲國王水；五千大鬼常遮其前，鬼言：『大賊！』入房舍、城邑、宅中，鬼復掃其脚跡，一切世人罵言：『佛法中賊！』一切眾生眼不欲見，犯戒人畜生無異，木頭無別。」", "t": "《梵網經》說：「若佛子以信心出家、受了佛的淨戒，卻故意起心毀犯所受的戒，這樣的人不得接受一切施主的供養，也不得在國王的土地上行走，不得飲用國王的水；五千大鬼常擋在他前面，鬼稱他為『大賊』；他進入房舍、城邑、住宅之中，鬼又掃去他的腳跡；一切世人都罵他是『佛法中的賊』，一切眾生都不願看他一眼。犯戒的人與畜生沒有差別，與木頭沒有兩樣。」", "i": "u18-2", "n": 31, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《涅槃經》云：「樂好衣服，縱逸嬉戲，奴為比丘，婢為比丘尼，不樂不淨觀，毀謗毗尼，互用三寶物等，是名法滅盡相。」\n《佛三昧經》云：「犯四重禁，虗受信施，過殺八萬四千父母等罪。」", "t": "《涅槃經》說：「喜好華美的衣服，放縱安逸、嬉戲玩樂，奴僕出家作比丘、婢女出家作比丘尼，不樂修不淨觀，毀謗毗尼，三寶之物彼此挪用等，這些就名為法滅盡的相狀。」\n《佛三昧經》說：犯四重禁而白白接受信施，罪過超過殺害八萬四千父母等罪。", "i": "u18-3", "n": 32, "s": "第1篇　勸學"}, {"v": "卷上", "o": "此律云：「有五種疾滅正法：一、有比丘不誦律，喜忘文句，復教他人，文既不具，其義有闕；二、為僧中勝人上座，一國所宗，而多不持戒，但修不善，後生倣習，放捨戒行；三、有比丘持法、持律、持摩夷，不教道俗，便即命終，令法斷絕；四、比丘難可教授，不受善語，餘善比丘捨置；五、共相罵詈，互求長短，疾滅正法。」", "t": "本律說：有五種事能使正法迅速滅沒：一、有比丘不誦習律，容易忘失文句，又去教導他人；文句既然不完整，義理也就有所缺漏。二、身為僧中的殊勝人物、上座，為一國之人所宗仰，卻大多不持戒，只作不善之事，後輩仿效學習，也放捨了戒行。三、有比丘能持法、持律、持摩夷論藏，卻不教導道俗二眾便命終了，使法斷絕。四、有比丘難以教授，不接受善言勸諫，其餘善比丘便捨棄他、不予理會。五、彼此互相辱罵，互找對方的長短過失，這樣就使正法迅速滅沒。", "i": "u18-4", "n": 33, "s": "第1篇　勸學"}, {"v": "卷上", "o": "又：「破戒之人有五過失：一、自害，二、為智者所訶，三、惡名流布，四、命終生悔，五、死墮惡道。」\n又：「上座不學戒，亦不讚歎戒，有餘比丘樂學戒者，不能以時勸讚；我見如是上座過失，故不讚歎，恐餘人習傚，長夜受苦。」", "t": "又，破戒的人有五種過失：一、自己害自己；二、被有智慧的人訶責；三、惡名流布；四、臨命終時生起悔恨；五、死後墮入惡道。\n又，佛說：「若上座自己不學戒，也不讚歎戒；對於其他樂於學戒的比丘，他也不能適時加以勸勉讚歎。我見到這樣的上座有這種過失，所以不讚歎他，是怕其餘的人仿效他，長夜受苦。」", "i": "u18-5", "n": 34, "s": "第1篇　勸學"}, {"v": "卷上", "o": "《十誦》云：「有諸比丘廢學毗尼，便讀修多羅、阿毗曇，世尊種種訶責。」\n《五分律》：「諸比丘不誦羯磨，不得受具足戒。」\n《善見》云：「若不解律，但解經論，不得度沙彌、作依止師。", "t": "《十誦律》說：有些比丘廢棄了毗尼的學習，便去讀誦修多羅經藏、阿毗曇論藏，世尊以種種言詞訶責他們。\n《五分律》說：諸比丘若不誦羯磨，不得為人授具足戒。\n《善見律》說：若不通解律，只通解經、論，就不得度沙彌，也不得作依止師。", "i": "u18-6", "n": 35, "s": "第1篇　勸學"}, {"v": "卷上", "o": "第三業報犯罪輕重者，經云：「佛告目連：若比丘、比丘尼無慚愧心，輕慢佛語，犯眾學戒，如四天王天壽五百歲，墮泥犂中，於人間數九百千歲。", "t": "第三是業報，說明所犯罪過輕重所感的果報。經中說：佛告訴目連：「若有比丘、比丘尼沒有慚愧心，輕慢佛語，犯了眾學戒，便墮入泥犁地獄，獄中壽量如同四天王天的五百歲，換算成人間的歲數，是九百千歲。」", "i": "u19", "n": 36, "s": "第1篇　勸學"}, {"v": "卷上", "o": "佛告目連：若無慚愧心，輕慢佛語，犯波羅提提舍尼戒，如三十三天壽千歲，墮泥犂中，於人間數三億六十千歲。", "t": "佛告訴目連：「若沒有慚愧心，輕慢佛語，犯了波羅提提舍尼戒，墮入泥犁地獄的壽量如同三十三天的一千歲，換算成人間的歲數，是三億六十千歲。」", "i": "u19-2", "n": 37, "s": "第1篇　勸學"}, {"v": "卷上", "o": "佛告目連：若無慚愧心，輕慢佛語，犯波逸提，如夜摩天壽二千歲，墮泥犂中，於人間數二十一億四十千歲。", "t": "佛告訴目連：「若沒有慚愧心，輕慢佛語，犯了波逸提罪，墮入泥犁地獄的壽量如同夜摩天的二千歲，換算成人間的歲數，是二十一億四十千歲。」", "i": "u19-3", "n": 38, "s": "第1篇　勸學"}, {"v": "卷上", "o": "佛告目連：若無慚愧心，輕慢佛語，犯偷蘭遮，如兜率天壽四千歲，墮泥犂中，於人間數五十億六十千歲。", "t": "佛告訴目連：「若沒有慚愧心，輕慢佛語，犯了偷蘭遮罪，墮入泥犁地獄的壽量如同兜率天的四千歲，換算成人間的歲數，是五十億六十千歲。」", "i": "u19-4", "n": 39, "s": "第1篇　勸學"}, {"v": "卷上", "o": "佛告目連：若無慚愧心，輕慢佛語，犯僧伽婆尸沙，如不憍樂天壽八千歲，墮泥犂中，於人間數二百三十億四十千歲。", "t": "佛告訴目連：「若沒有慚愧心，輕慢佛語，犯了僧伽婆尸沙罪，墮入泥犁地獄的壽量如同不憍樂天的八千歲，換算成人間的歲數，是二百三十億四十千歲。」", "i": "u19-5", "n": 40, "s": "第1篇　勸學"}, {"v": "卷上", "o": "佛告目連：若無慚愧心，輕慢佛語，犯波羅夷，如大自在天壽十六千歲，墮泥犂中，於人間數九百二十一億六十千歲。」", "t": "佛告訴目連：「若沒有慚愧心，輕慢佛語，犯了波羅夷罪，墮入泥犁地獄的壽量如同大自在天的一萬六千歲，換算成人間的歲數，是九百二十一億六十千歲。」", "i": "u19-6", "n": 41, "s": "第1篇　勸學"}, {"v": "卷上", "o": "總計僧尼於五篇七聚罪，且篇別單一罪論之，如人間日月歲數，合有一千二百六十一億五十千歲墮泥犂中。聖教不許，特須敬順，宜修方便，檢察身口，勗志專崇，高慕前聖，不得自怠，輕慢佛語。故經曰：「正法住，正法滅。」意在茲乎。", "t": "總計比丘、比丘尼在五篇七聚的罪中，姑且就每一篇各只犯一條罪來計算，按人間的日、月、年數換算，合計要在泥犁地獄中受苦一千二百六十一億五十千歲。聖教既然不許如此輕慢毀犯，就必須格外恭敬順從；應當修習種種方便加行，檢點省察身業與口業，勉勵心志，專心崇尚、深切仰慕前代聖者，不可自己懈怠而輕慢佛語。所以經中說「正法住、正法滅」，意旨正在於此啊！", "i": "u19-7", "n": 42, "s": "第1篇　勸學"}, {"v": "卷上", "o": "○釋聚篇第二", "t": "第二篇，解說罪的聚類。", "i": "u20", "n": 43, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "此篇大門有七：一、波羅夷，二、僧伽婆尸沙，三、偷蘭遮，四、波逸提，五、波羅提提舍尼，六、突吉羅，七、惡說。", "t": "本篇的大綱分為七門：第一是波羅夷，第二是僧伽婆尸沙，第三是偷蘭遮，第四是波逸提，第五是波羅提提舍尼，第六是突吉羅，第七是惡說。", "i": "u21", "n": 44, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第一波羅夷者，《十誦》云：「謂墮不如意處。」《婆論》釋云：「猶與魔鬬，以犯此戒，便墮負處。」《阿毗䟦律》云：「夷者，秦言劫功德也。」釋云：「波羅夷者，譬如斷人頭，不可復起也；若犯此戒，不復成比丘尼。」此但從行法非用為名；又「無餘」者，此從眾法絕分為名，故偈云：「諸作惡行者，猶如彼死屍，眾所不容受，以是當持戒。", "t": "第一篇是波羅夷。《十誦律》說：波羅夷意為「墮不如意處」，即墮落到不可意的境地。《婆論》解釋說：好比與魔王交戰，因為犯了這條戒，便落到戰敗的一方。《阿毗跋律》說：「夷」這個字，用秦地漢語來說，就是劫奪功德的意思。解釋說：波羅夷，譬如砍斷了人的頭，不可能再活過來；若犯了這條戒，就不再成其為比丘尼。這只是就「行法非用」而立名，意謂犯此戒者於修行聖道之法中已不復堪用；又稱為「無餘」，則是就「眾法絕分」而立名，意謂在僧眾作法中已無分參與。所以偈頌說：凡是造作惡行的人，就像那具死屍，僧眾無法容納接受，因此應當持戒。", "i": "u22", "n": 45, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第二名僧伽婆尸沙者，《婆論》云：「僧伽者名僧，婆尸沙者名殘。若犯此罪，垢纏行者，非全淨用，有殘之罪，由僧除滅，故名僧殘。」《母論》云：「如人為他所斫，殘有咽喉，故名為殘。", "t": "第二個名稱是「僧伽婆尸沙」。《婆論》說：「僧伽」是「僧」的意思，「婆尸沙」是「殘」的意思。如果犯了這一罪，罪垢纏縛著犯戒的人，使他不再具有完全清淨的功用，但仍留有殘餘；這殘餘之罪須由僧團作法才能除滅，所以稱為「僧殘」。《母論》說：好比人被他人砍斫，還殘留著咽喉未斷，所以名為「殘」。", "i": "u23", "n": 46, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第三偷蘭遮者，《見論》云：「偷蘭名為大，遮言障善道，體是鄙穢。」此從不善以立名。", "t": "第三是偷蘭遮。《善見論》說：「偷蘭」的意思是「大」，「遮」是說障礙善道。這罪的體性鄙陋污穢，這是依不善之體來安立名稱的。", "i": "u24", "n": 47, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第四波逸提者，《十誦》云：「墮在燒煑覆障地獄，故名墮。」尼薩耆者，《出要律儀》云：「尼薩耆者，舊翻為捨墮。」《聲論》云：「尼翻為盡，薩耆為捨，此云盡捨：捨財、捨罪、捨心，具此三捨，故云盡捨。", "t": "第四是波逸提。《十誦律》說：犯此罪的人會墮落在燒煮覆障的地獄中，所以名為「墮」。至於「尼薩耆」，《出要律儀》說：「尼薩耆」舊時譯為「捨墮」。《聲論》說：「尼」譯為「盡」，「薩耆」譯為「捨」。這裡便譯作「盡捨」；也就是捨財、捨罪、捨心，具備這三種捨，所以稱為「盡捨」。", "i": "u25", "n": 48, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第五波羅提提舍尼者，義翻云「向彼悔」，從對治境以立其名。《明了論》云：「翻為各對應說，謂對人說所作罪也。", "t": "第五類「波羅提提舍尼」，依意義翻譯稱為「向彼悔」，也就是向對方悔過；這個名稱是就著對治罪過時所面對的對象，即接受悔過的人，而安立的。《明了論》說：譯為「各對應說」，意思是對著人陳說自己所犯的罪。", "i": "u26", "n": 49, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第六突吉羅者，《見論》云：「突者惡也，吉羅者作也。」此律云「式叉迦羅尼」者，翻為「應當學」。《見論》云：「式叉者學，迦羅尼應當作，名為學應當作也。」義云：西域語例，故云「學應當作」；若依此方，應云「應當學」。\n《婆論》問曰：「何故此篇獨名『應當學』？」答：「餘戒易持而罪重，犯懺是難；此戒難持，罪輕而易犯，當順心學，不結罪名，故云『應當學』。」\n又西僧云：「翻為守戒。」此罪微細，持之極難，故隨順當守以立其名。《十誦》云：「以天眼見犯戒比丘，如駛雨下。」豈非精翫在心，名為守戒也。", "t": "第六是突吉羅。《善見論》說：「突」是惡的意思，「吉羅」是作的意思。本部《四分律》說：「式叉迦羅尼」，翻譯為「應當學」。《善見論》說：「式叉」是學，「迦羅尼」是應當作，合起來就叫作「學應當作」。依義理來說：這是按西域的語法次序，所以說成「學應當作」；若依此土的語法，就應該說成「應當學」。\n《薩婆多論》問：為什麼唯獨這一篇名為「應當學」？答：其餘各篇的戒容易持守，可是罪重，一旦犯了，懺悔出罪很困難；這一篇的戒難以持守，罪卻輕，很容易違犯，所以應當隨順所學、用心修學，而不另外結立罪名，因此稱為「應當學」。\n又有西域僧人說：這個詞翻譯為「守戒」。因為這類罪極為微細，要持守不犯非常困難，所以就「隨順所學、應當守護」的意思來安立它的名稱。《十誦律》說：以天眼看見犯戒的比丘，像急雨一般紛紛墮落。這難道不是說，必須專精研習、存之於心，才叫作「守戒」嗎？", "i": "u27", "n": 50, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "第七惡說者，初以身名惡作，口名惡說，故突吉羅復加一惡說，合有七也。", "t": "第七是「惡說」：原本依身業所犯而立的名稱是「惡作」，依口業所犯而立的名稱是「惡說」；所以在名為「惡作」的突吉羅之外，再加上一個「惡說」，合起來共有七聚。", "i": "u28", "n": 51, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "問曰：諸經律中，或名尸羅，或名戒，或名毗尼，或名律，或名波羅提木叉，或名解脫，既有多種，云何取別耶？", "t": "問：在諸部經律之中，有時稱為「尸羅」，有時稱為「戒」，有時稱為「毗尼」，有時稱為「律」，有時稱為「波羅提木叉」，有時稱為「解脫」；既然有這麼多種名稱，該如何區別呢？", "i": "uGAP01-1", "n": 52, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "答曰：若廢名談體，體即是一，總不出戒；戒是防非止惡為義，所以諸名竝欲防非，齊兼止惡，故攝別歸總，莫過於戒，故經云「戒定慧」也，此據三學行法以立總也。", "t": "答：如果捨開名稱來談本體，本體其實只有一個，總歸不出「戒」的範圍。「戒」以防非止惡為義，因此上述各種名稱都是要防備過非，也都兼有止息惡行的意思；所以把各種別名歸攝到總名，沒有比「戒」更貼切的了，因此經中說「戒、定、慧」。這是依據三學的修行法門來建立總稱。", "i": "uGAP01-2", "n": 53, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "若廢體談名，名則有別。言毗尼者，謂西梵正音，此翻為滅，然滅非毗尼，謂能滅諸過，故名滅，此從功行以立其名。", "t": "如果捨開本體來談名稱，那麼名稱之間就有差別了。所謂「毗尼」，是西域梵語的正確音讀，這裏翻譯為「滅」；然而「滅」並不是毗尼一詞的本義，只是說它能滅除種種過失，所以才稱為「滅」，這是從它的功用行持來立名的。", "i": "uGAP01-3", "n": 54, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言律者，法也，法有楷模，能詮輕重，疏染淨，故名為法，就能詮之教以立其名。", "t": "所謂「律」，就是「法」；法具有楷模準則，能夠闡明罪過的輕重、辨析疏通染污與清淨，所以稱為「法」，這是就「能詮顯的教法」來立名的。", "i": "uGAP01-4", "n": 55, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "此上二種，竝從能治行以立名也。\n此下尸羅及與木叉，皆從所詮之行以立其名。", "t": "以上這兩種名稱，都是從「能對治之行」來立名的。以下「尸羅」與「木叉」這兩種，則都是從「教法所詮顯之行」來立名的。", "i": "uGAP01-5", "n": 56, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言尸羅者，《智論》云：「秦言性善，謂體是善，非惡、無記。」亦名為戒，戒有防非之功，亦有善因之義，此從善因以立名。", "t": "所謂「尸羅」，《智論》說，秦語意為「性善」，意思是說它的本體是善，既不是惡，也不是無記；這也稱為「戒」，因為戒有防備過非的功用，同時也具有善因的意義，這是從善因來立名的。", "i": "uGAP01-6", "n": 57, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言波羅提木叉者，此云「處處解脫」，謂身口七支非一，名為「處處」，果名為「解脫」，隨分得脫，即是果義，此從果善以立名。", "t": "所謂「波羅提木叉」，這裏譯為「處處解脫」。因為身、口七支不止一處，所以稱為「處處」；所證之果稱為「解脫」。隨著各分持守而獲得解脫，這就是「果」的意義，這是從果善來立名的。", "i": "uGAP01-7", "n": 58, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "雖因果竝論，然防非中，要生善義強，故以戒攝別，用為宗極；由有戒故，久助資成，便招世間、出世間多種樂果，故名戒也。", "t": "雖然把善因與善果一併論述，然而在防備過非之中，要以生發善法的意義最為強烈，所以用「戒」來統攝各種別名，作為宗旨要極。由於有戒的緣故，長久資助、成就善行，便能招感世間與出世間的多種樂果，所以稱為「戒」。", "i": "uGAP01-8", "n": 59, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "若欲互攝，隨以何名，皆有互攝之義：如戒是防非止惡，即是滅惡義；戒有楷模，能詮輕重，即是法義；法義既成，便是性善；性善既成，便為因義；因義招生，即攝果義；餘名互起，亦皆如此。", "t": "如果要論彼此含攝，那麼隨便舉哪一個名稱，都具有互相含攝的意義。例如，戒是防非止惡，這就是滅惡的意義；戒具有楷模準則，能闡明輕重，這就是法的意義；法的意義既已成立，便是性善；性善既已成立，便成為善因的意義；善因的意義能招感生起善果，也就含攝了果報的意義。其餘各個名稱互相融通生起，也都是如此。", "i": "uGAP01-9", "n": 60, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "上明因果二名，復有受、隨兩義。言受戒者，謂創發要期，納法在心，名之為受；有懸防之能，又名為戒。", "t": "以上闡明了因與果這兩種名稱，此外還有「受」與「隨」兩種意義。所謂「受戒」，是指初次發起要期誓願，將戒法領納在心中，這就稱為「受」；因為它具有預先防非的功能，所以又稱為「戒」。", "i": "uGAP01-10", "n": 61, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "二、隨戒者，謂持心後起，義順於前，名之為隨；隨有防非之功，亦名為戒。隨有兩種：一是精持不犯，二犯已能悔。若對精持不犯，便具止、作二持；若對犯已能悔，即辨止、作二犯。", "t": "第二，「隨戒」，是指護持之心在受戒之後生起，行義順從於先前所受之戒，這就稱為「隨」；因為隨行護持有防備過非的功用，所以也稱為「戒」。「隨」有兩種：第一是精勤護持而不違犯，第二是違犯之後能夠懺悔。如果對應「精勤護持而不違犯」來說，就具備了止持、作持這兩種「持」；如果對應「違犯之後能夠懺悔」來說，就要辨明止犯、作犯這兩種「犯」。", "i": "uGAP01-11", "n": 62, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "所言止持者，如受戒已，止不作惡，即名為持，持由止生，故名止持。", "t": "所謂「止持」，例如受戒之後，制止自己不造作惡行，這就稱為「持」；這個「持」是由「止」而產生的，所以稱為「止持」。", "i": "uGAP01-12", "n": 63, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言作持者，謂動身口，戒意離非，順本所受，不犯前過，號之為持，持由作生，故名作持。", "t": "所謂「作持」，是指發動身、口去行持，並約束意念遠離過非，順從原本所受的戒法，不違犯前面所說的過失，這就稱為「持」；這個「持」是由「作」而產生的，所以稱為「作持」。", "i": "uGAP01-13", "n": 64, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言止犯者，謂止不修善，違本所受，名之為犯，犯由止成，故名止犯；此則止犯翻前作持也。", "t": "所謂「止犯」，是指停止而不去修習善法，違背了原本所受的戒法，這就稱為「犯」；這個「犯」是由「止」而構成的，所以稱為「止犯」。這就是「止犯」與前面的「作持」恰恰相反。", "i": "uGAP01-14", "n": 65, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "言作犯者，謂動身口，造作前非，違本要期，名之為犯，犯由作成，故名作犯；翻前止持也。", "t": "所謂「作犯」，是指發動身、口去造作前面所說的過非，違背了原本的要期誓願，這就稱為「犯」；這個「犯」是由「作」而構成的，所以稱為「作犯」，這與前面的「止持」恰恰相反。", "i": "uGAP01-15", "n": 66, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "故二持翻兩犯，二犯翻二持，逆順不相妨，善惡體相違。", "t": "因此，二持與兩犯相對反，二犯也與二持相對反；違逆與順從互不妨礙，善與惡的本體本來就互相違背。", "i": "uGAP01-16", "n": 67, "s": "第2篇　釋聚"}, {"v": "卷上", "o": "○結界篇第三", "t": "第三篇：結界。", "i": "u29", "n": 68, "s": "第3篇　結界"}, {"v": "卷上", "o": "此篇大門有三：一、定量，二、大界，三、戒場。", "t": "這一篇的大綱分為三門：第一是定量，即確定結界的大小限量；第二是大界；第三是戒場。", "i": "u30", "n": 69, "s": "第3篇　結界"}, {"v": "卷上", "o": "第一定量者，《婆論》云：「尼大界者，唯得一拘盧舍。」《見論》云：「戒場極小，下至容二十一人便得，減則不聽。", "t": "第一，確定界的量度大小。《薩婆多論》說：比丘尼的大界，只准有一拘盧舍的範圍。《善見論》說：戒場最小的限度，下至能容納二十一人就可以成立，比這更小就不許了。", "i": "u31", "n": 70, "s": "第3篇　結界"}, {"v": "卷上", "o": "第二大界有六種：一、簡緣，二、立相，三、唱形，四、集僧，五、辨欲，六、作法。", "t": "第二、結大界，分為六項：一是揀辨結界的因緣，二是確立界相，三是唱說界形，四是集合僧眾，五是辨明結界時不得受欲，六是正式作法。", "i": "u32", "n": 71, "s": "第3篇　結界"}, {"v": "卷上", "o": "第一簡緣者，問曰：「界中有河，得合結否？」答：「常有橋船得。」問曰：「一標得作兩相否？」答：「一肘已上作相者得。", "t": "第一是「簡緣」，也就是先審察、揀別結界時的種種條件。\n問：所要結的界當中有一條河流過，可以連河一併合結成同一個大界嗎？\n答：只要河上經常有橋梁或船隻可供往來，就可以。\n問：同一個界標，可以兼作兩處的界相嗎？\n答：標物有一肘以上，用它來作界相，就可以。", "i": "u33", "n": 72, "s": "第3篇　結界"}, {"v": "卷上", "o": "第二立相者，若依此律，界相不定：若東方有山稱山，有壍、艸𧂐、汪水、糞聚、釘杙、空地等，竝得作相。然空相一種，結竟即須題記，令後來尼識知界相，行法者無疑。", "t": "第二、設立界相。若依《四分律》，界相並不固定：東方若有山，就唱稱為「山」；有壕溝、草堆、積水窪、糞堆、釘入地中的木樁、空地等，都可以用作界相。不過其中「空地」這一種相，結界完成後就必須隨即題寫記錄下來，使後來的比丘尼能認識界相，作法的人也不致生疑。", "i": "u34", "n": 73, "s": "第3篇　結界"}, {"v": "卷上", "o": "《見論》云：「界形有五：一、方，二、圓，三、鼓形，四、半月，五、三角。」", "t": "《善見論》說：界的形狀有五種：一是方形，二是圓形，三是鼓形，四是半月形，五是三角形。", "i": "u34-2", "n": 74, "s": "第3篇　結界"}, {"v": "卷上", "o": "義云：若先無相，隨前所列者立之亦得。今時結者，多是空地、四方城邑，隨相唱之；然須識過，後便得唱結，謂前學未達，後學未明。", "t": "依義理說：若原先沒有可作標識的相，隨前面所列的那些種類設立一個，也是可以的。現今結界的，多是在空地或四方的城邑之中，就隨著當地的相狀來唱說。然而必須先認清其中的過失，然後才可以唱相結界；因為先學的人尚未通達，後學的人尚未明白。", "i": "u34-3", "n": 75, "s": "第3篇　結界"}, {"v": "卷上", "o": "若唱方相，須容舛錯：如從牆外唱云「從東南角至西南角」乃至一周訖，寺南門外便成別眾，以唱界從牆基直過門限外，便成界內，儻寺中閉戶作羯磨，門限外有人，不喚盡集，豈非別眾？", "t": "若唱方形的界相，難免會有差錯：例如沿著牆外唱說「從東南角到西南角」，乃至這樣繞行一周完畢；如此一來，寺院南門外一帶便會造成別眾。因為所唱的界相是從牆基直線通過去，門檻以外的地方就成了界內；倘若寺中關起門來作羯磨，門檻外那塊已屬界內的地方有比丘尼在，卻不招呼她們全部集合，豈不是別眾？", "i": "u34-4", "n": 76, "s": "第3篇　結界"}, {"v": "卷上", "o": "若從牆內唱，復有破夏、離衣之過：以界隨牆內起，今既傍牆直唱，門限內地便成界外，寺中作法，有人說欲至門限內，須有所作，又來入界，豈非別眾？若破夏、離衣者，有人在界安居，明相未出，至限邊，未還之頃，明相已出，便是界外，豈非破夏、離衣？", "t": "若沿著牆內唱，又有破夏與離衣的過失。因為界相是隨牆的內側起算，如今既是傍著牆內直線唱過去，門檻以內的地方就成了界外。寺中作法時，有人（身在界外）已託人傳達了「說欲」，之後走到門檻以內那塊已屬界外的地方，又因有事要辦而回到界內，這豈不是別眾？至於破夏、離衣：有人在界內安居，天亮明相尚未現起時走到門檻邊，還沒來得及返回，明相就已現起，人便已在界外，這豈不是破了安居、又成離衣？", "i": "u34-5", "n": 77, "s": "第3篇　結界"}, {"v": "卷上", "o": "既知不易，不得籠通直唱，儻有斯謬，令他一生虗過。", "t": "既然知道這並不容易，就不可以籠統含糊地直線唱過去。倘若有這樣的錯謬，會使別人一生白白空過。", "i": "u34-6", "n": 78, "s": "第3篇　結界"}, {"v": "卷上", "o": "第三唱形者，《五分律》云：「不唱方相，結不成。」此律云：「使舊住人唱。」義云：未唱之前，親自按行，識知處所，屏處暗誦，勿令對眾致有謇錯。先須從東南角為始，故律云「東方有山稱山」，此亦何定，隨穩便而唱，未要指東為式。僧中差一人唱，被差人起，禮僧足已，至僧中立唱云。", "t": "第三，唱說界形。《五分律》說：「不唱方相，結不成。」——不唱說四方的界相，結界就不能成立。《四分律》說：「使舊住人唱。」——要讓久住當地的人來唱。依義理來說：在唱相之前，先親自巡行查看，認清界相所在的處所，再到僻靜處默默背誦熟練，免得當眾唱時結巴出錯。起首須從東南角開始，所以律中說「東方有山稱山」——東方有山，就稱山為界相。但這也沒有定準，隨哪裡穩當方便就從哪裡唱起，不必硬指東方作為定式。在僧眾中差派一人唱相；被差派的人起身，頂禮僧眾之足後，走到大眾中間站定，唱說：", "i": "u35", "n": 79, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！我舊住比丘尼，今為僧唱四方大界相：從寺院大牆東南角內角，傍牆西下，至南門東頰北土楞；從此屈曲，至南門西頰北土楞；從此傍牆西出，至西南角內角；從此傍牆北出，至西北角內角；從此傍牆東出，至東北角內角；從此傍牆南出，還至東南角內角。是為大界相，一周訖。", "t": "諸位大姊僧眾請聽：我是本寺舊住的比丘尼，現在為僧團唱誦四方大界的界相。從寺院大牆東南角的內角開始，沿著牆向西行，到南門東側門垛北端的土稜角；從這裡曲折轉彎，到南門西側門垛北端的土稜角；從這裡沿牆向西行，到西南角的內角；從這裡沿牆向北行，到西北角的內角；從這裡沿牆向東行，到東北角的內角；從這裡沿牆向南行，回到東南角的內角。這就是大界的界相。唱誦一周完畢。", "i": "u36", "n": 80, "s": "第3篇　結界"}, {"v": "卷上", "o": "若有俗家侵入寺腹，或牆壍尖斜，或寺多門，竝須一一屈曲，隨地形唱；若橫牆隔礙者，當須唱「穿牆直過」便得。", "t": "如果有俗家的房舍侵入寺院腹地，或者圍牆、壕塹尖突斜曲，或者寺院開有多座門，都必須逐一隨著地形的形狀轉折彎曲地唱明界相。如果有橫向的牆隔在中間造成阻礙，就應當唱「穿牆直過」，也就是唱明界相穿過牆身直線通過，這樣就可以了。", "i": "u37", "n": 81, "s": "第3篇　結界"}, {"v": "卷上", "o": "第四集僧者，若標相狹、自然寬者，應盡自然界六十三步集；若標相寬、自然狹者，亦盡標內集。一則深防，二《僧祇》有文。若標內外有僧界者，兩不相妨，不須集僧；若有作法界者，但令寺尼莫出自然界，餘自然界通結亦得。", "t": "第四，集合僧眾：如果所立標相的範圍比自然界狹小，應當把自然界六十三步範圍內的比丘尼全部集合；如果標相的範圍比自然界寬大，也要把標相以內的比丘尼一併集合。這樣要求，一是為了深加防範過失，二是《僧祇律》中有明文可據。如果標相之內或之外有比丘僧的界，僧尼二部之界互不妨礙，不必召集比丘僧眾。如果另有已依作法結成的界，只要讓寺中的比丘尼不走出自然界之外，其餘自然界的範圍一併通結在內，也是可以的。", "i": "u38", "n": 82, "s": "第3篇　結界"}, {"v": "卷上", "o": "第五辨欲者，問曰：「結界何為不得受欲？」答曰：「具三義故，不得受欲：一、結界是眾同之本，理宜急制；二、自然界弱，不勝羯磨，故《僧祇》云『非羯磨地，不得作僧事』；三、令知界畔，護夏、護衣、宿食、別眾等過。", "t": "第五項，辨明受欲的問題。\n問：結界的時候，為什麼不可以受欲，也就是接受缺席者託人傳達的同意？\n答：因為有三個理由，所以不得受欲：\n第一，結界是僧眾和合共住的根本，按理應當從嚴禁制，不開許受欲。\n第二，未經作法結成的自然界力量薄弱，承受不了羯磨，所以《僧祇律》說，不是經過作法結成的羯磨地，就不得舉行僧眾法事。\n第三，要讓大家都知道界線的邊際，以防護破夏、離衣，以及在界內留宿食物、別眾等過失。", "i": "u39", "n": 83, "s": "第3篇　結界"}, {"v": "卷上", "o": "第六作法者。", "t": "第六，作法。", "i": "u40", "n": 84, "s": "第3篇　結界"}, {"v": "卷上", "o": "上座問：「僧集和合否？」答曰：「僧集和合。」又問云：「未受具戒者出。」答云：「已出。」又問云：「僧今和合，何所作為？」答云：「結大界羯磨。", "t": "上座問：「僧眾都集合了嗎？是否和合？」回答說：「僧眾已集合，也已和合。」上座又問：「未受具足戒的人出去了嗎？」回答說：「已經出去了。」上座又問：「僧眾現在既已和合，要作什麼事？」回答說：「作結大界的羯磨。」", "i": "u41", "n": 85, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方大界相。若僧時到，僧忍聽，僧今於此四方相內結大界，同一住處，同一說戒。白如是。", "t": "諸位大姊僧眾請聽：這個住處的比丘尼，已唱明了四方大界的界相。如果僧眾的時機已到，請僧眾聽許：僧眾現在就在這四方界相之內結成大界，同為一個住處、同一場說戒。白告就是這樣。", "i": "u42", "n": 86, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方大界相。僧今於此四方相內結大界，同一住處，同一說戒。誰諸大姉忍僧今於此四方相內結大界、同一住處、同一說者，默然；誰不忍者，說。僧已忍於此四方相內同一住處、同一說戒、結大界竟，僧忍默然故，是事如是持。", "t": "諸位大姊，僧團請聽！此住處的比丘尼已唱說了四方大界的界相。僧團現在就在這四方界相之內結成大界，作為同一住處、同一說戒。諸位大姊當中，凡是認可僧團現在於這四方界相之內結成大界、作為同一住處、同一說戒的，就請默然不語；不認可的，就請說出來。僧團已經認可：在這四方界相之內，以同一住處、同一說戒，結成大界完畢。由於僧團認可而默然無語的緣故，這件事就如此認定，依此奉行。", "i": "u43", "n": 87, "s": "第3篇　結界"}, {"v": "卷上", "o": "第三戒場者，別有五節：一、竪標，二、立圖，三、擇非，四、唱結，五、解界。", "t": "第三是戒場的部分，另外分為五節：一、豎立標相；二、繪製圖樣；三、揀辨錯誤的作法；四、唱相結界；五、解除界。", "i": "u44", "n": 88, "s": "第3篇　結界"}, {"v": "卷上", "o": "第一竪標者，若安戒場結者，應竪三標：第一重者，戒場外一肘自然內畔安一標，此是戒場相；第二重標者，戒場外次一肘自然外畔安一標，此是大界內相；第三重者，大界外相周帀安標，此是大界外相也。若安石、釘橛，竝得作相，先唱內標為首，然後第二、第三次第結之。其大界牆基無比寺連者，不問寬狹，竝得作相；若有寺牆相連，或內安戒場者，其二界牆基必須尺八已上，方得為相，故律云「應留中間地」，恐兩界涉也。", "t": "第一是豎標。如果要安設戒場來結界，應當豎立三重標相。第一重：在戒場外一肘寬的自然地的內側邊緣安一個標，這就是戒場的界相。第二重標：接著在戒場外這一肘自然地的外側邊緣安一個標，這就是大界的內相。第三重：沿著大界的外相周繞一圈安標，這就是大界的外相。無論是安放石塊、釘子或木橛，都可以用作界相。唱相時先以最內一重的標作為開頭，然後第二重、第三重依先後次序結界。\n至於大界的牆基，如果沒有鄰近寺院的牆與它相連，那麼不論牆基是寬是窄，都可以用作界相；如果有寺牆相連，或者在大界內安設戒場，那麼這兩界所依的牆基就必須有一尺八寸以上的寬度，才能用作界相。所以律中說「應留中間地」，就是必須留出中間的空地，唯恐兩個界互相涉入重疊。", "i": "u45", "n": 89, "s": "第3篇　結界"}, {"v": "卷上", "o": "第二立圖者，上來達法者無疑，猶恐新學之徒未能曉會，故略以畫圖，冀補規路，按圖行事，庶免矛盾耳。", "t": "第二是繪立圖樣。以上所說的作法，通達律法的人自然沒有疑惑；但仍怕初學的人未能明白領會，所以簡略地畫出圖樣，希望藉此補助他們依循的規範門徑，照著圖樣行事，以避免前後牴觸矛盾。", "i": "u46", "n": 90, "s": "第3篇　結界"}, {"v": "卷上", "o": "今依此圖，便有三相。若唱大界外相，必須在外唱之，周帀屈曲，一如前說；若在牆內唱者，西南兩面自然地邊，即與大界內相共合，便不分彼此之異。若無戒場者，得從內唱大界內相。", "t": "現在依照這幅圖，就有三種界相。如果要唱大界的外相，必須在牆外唱，繞行一周、曲折而行，完全如前面所說。如果在牆內唱，南、西兩面自然地的邊沿就會與大界內相重合，便分不出彼此的差別。如果沒有戒場，可以從牆內唱大界的內相。", "i": "u47", "n": 91, "s": "第3篇　結界"}, {"v": "卷上", "o": "東北二邊有小牆者，應傍小牆東南角外唱，穿小牆西入，還傍大界南牆內至西南角，還傍大界內西牆直北，穿小牆過，然後屈曲唱之。", "t": "東北兩邊有小牆的，應當傍著小牆東南角的外側起唱，穿過小牆向西進入，再沿著大界南牆內側走到西南角，再沿著大界西牆內側直向北，穿過小牆，然後再一路曲折地唱出界相。", "i": "u47-2", "n": 92, "s": "第3篇　結界"}, {"v": "卷上", "o": "戒場外自然地，東北兩邊即用小牆為自然空地，西南兩邊即用一肘繩標外為自然地。若大界內先無相者，應豎標杙，以繩連之：當於戒場東南角，離大界南牆尺八，傍小牆基下釘一大杙；直至西牆，離西大牆內尺八地，又釘一杙；直北至小牆基下，復釘一杙，亦令遠大牆一尺八寸，仍以繩連此三標外為自然地。", "t": "戒場外的自然地：東北兩邊就用小牆作為自然空地；西南兩邊就用一肘繩標的外側作為自然地。如果大界內原先沒有界相，應當豎立標樁，用繩子連接起來：在戒場東南角、離大界南牆一尺八寸、傍著小牆基腳的地方，釘下一支大木樁；由此直向西牆，在離西邊大牆內側一尺八寸的地方再釘一支樁；再直向北到小牆基腳處又釘一支樁，同樣讓它離大牆一尺八寸；然後用繩子連接這三個標樁，這三標之外就是自然地。", "i": "u47-3", "n": 93, "s": "第3篇　結界"}, {"v": "卷上", "o": "其戒場相者，東北兩面，即以小牆內畔為戒場相；西南兩邊，即用繩標。\n久固不壞者，人在自然地內，不妨戒場內得成法事，以識知界相故；若破壞無者，後客尼來，不知界畔，客可來去不定，恐破僧法事。", "t": "至於戒場相：東北兩面就用小牆的內側邊沿作為戒場相；西南兩邊就用繩子作標記。之所以要經久堅固不壞，是因為：界相既然清楚可辨，人站在自然地內，並不妨礙戒場內成就法事；如果繩標破壞不存，後來的客比丘尼來時就不知道界的邊畔，客尼可能來去不定，恐怕破壞僧眾的法事。", "i": "u47-4", "n": 94, "s": "第3篇　結界"}, {"v": "卷上", "o": "若大界牆基闊二尺已上者，唱此一肘自然地，縮入大界牆內，為穩審故，以界是色法，入實無妨。計一肘自然地，尺殘有二寸，便是界體，足標兩相。", "t": "如果大界牆基寬二尺以上，唱相時把這一肘自然地縮入大界牆內，更為穩妥可靠，因為界是物質性的色法，入於實體之中並無妨礙。算起來，一肘的自然地是一尺八寸，二尺的牆基還剩二寸，這二寸便是界體，足以標示兩相。", "i": "u47-5", "n": 95, "s": "第3篇　結界"}, {"v": "卷上", "o": "上來所列，聊寄一物作此界相，未必如圖，至時稱事，任補茲處；於戒場門亦應屈曲唱出，恐文繁不述。", "t": "以上所列，只是姑且借一件事物來作這些界相，未必與圖相同；到時依實際情形，隨意補充這部分。在戒場門處，也應當曲折唱出界相，怕文字繁瑣，就不詳述了。", "i": "u47-6", "n": 96, "s": "第3篇　結界"}, {"v": "卷上", "o": "第三擇非者，若結二界，應先結戒場，後結大界，《五分》亦然。若先結大界，當捨已，更前結戒場，後結大界。《母論》云：「外處不結大界，直結小界者，亦不得受具。", "t": "第三節「擇非」，即辨明錯誤的做法：如果要結這兩種界，應當先結戒場，後結大界；《五分律》也是這樣說。倘若已經先結了大界，就應當先捨去已結的大界，再重新先結戒場，然後才結大界。《母論》說：外圍不結大界，卻直接只結小界的，也不得受具足戒。", "i": "u48", "n": 97, "s": "第3篇　結界"}, {"v": "卷上", "o": "第四唱結者，若欲唱結，各當界為之，不得彼此遙作；使自然界尼盡集戒場所，令一舊住比丘尼起，具修威儀，立唱云。", "t": "第四、唱相結界：如果要唱界相、作結界羯磨，戒場與大界必須各自在該界的處所進行，不能站在這一界遙為另一界作法。要使自然界內的比丘尼全部集合到戒場的處所，然後令一位本處舊住的比丘尼起身，整肅威儀，站立唱念說：", "i": "u49", "n": 98, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！我舊住比丘尼，今為僧唱戒場四方小界相：從東南角內標，傍繩西下，至西南角內標；從此傍繩北下，至西北角內標；從此傍小牆東下，至東北角內標；從此南下，還至東南角內標。此是戒場相，一周訖。", "t": "諸位大姊僧眾請聽：我這位舊住比丘尼，現在為僧眾唱說戒場四方小界的界相：從東南角的內標開始，沿著標繩向西行，到西南角的內標；從這裡沿著標繩向北行，到西北角的內標；從這裡沿著小牆向東行，到東北角的內標；從這裡向南行，回到東南角的內標。這就是戒場的界相。唱相一周完畢。", "i": "u50", "n": 99, "s": "第3篇　結界"}, {"v": "卷上", "o": "上座問：「僧集和合否？」答云：「已集和合。」又問：「未受具戒者出。」答云：「未受具戒者已出。」又問：「僧今和合，何所作為？」答曰：「結戒場羯磨。", "t": "上座問：「僧眾都集合、和合了嗎？」答：「已經集合、和合了。」又問：「還未受具足戒的人出去了沒有？」答：「未受具足戒的人已經出去了。」又問：「僧眾現在和合，要做什麼事？」答：「作結戒場的羯磨。」", "i": "u51", "n": 100, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方小界相。若僧時到，僧忍聽，僧今於此四方小界相內結戒場。白如是。", "t": "各位大姊，請僧眾聽：本住處的比丘尼已唱明了四方小界的界相。如果僧眾認為時機已到，請僧眾聽許：僧眾現在就在這四方小界相之內結成戒場。白告就是這樣。", "i": "u52", "n": 101, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方小界相。僧今於此四方小界相內結戒場。誰諸大姉忍僧今於此四方小界相內結戒場者，默然；誰不忍者，說。僧已忍，僧今於此四方小界相內結戒場竟，僧忍默然故，是事如是持。", "t": "各位大姊，請僧眾聽著！本住處的比丘尼已唱明四方小界的界相，僧眾現在就在這四方小界相之內結成戒場。諸位大姊當中，誰贊同僧眾現在在這四方小界相之內結戒場的，就默然不語；不贊同的，請說出來。僧眾已經認可。僧眾現在在這四方小界相之內結戒場，已經完成。由於僧眾認可而默然的緣故，這件事就如此認定、如此受持。", "i": "u53", "n": 102, "s": "第3篇　結界"}, {"v": "卷上", "o": "次結大界者，有三重：一、唱內相，二、唱外相，三、唱竟總結。先唱內相云。", "t": "其次，結大界有三個步驟：第一，唱報大界的內相；第二，唱報外相；第三，唱報完畢後作總結。先唱報內相，說道：", "i": "u54", "n": 103, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！我舊住比丘尼，今為僧唱四方大界內相：從小牆東南角，穿小牆西出，傍大牆內，至西南角內角；從此傍大牆北下，穿小牆直過，至小牆西北角外角；從此傍小牆東下，至小牆東北角外角；從此傍小牆南下，還至小牆東南角外角。此是大界內相，一周訖。", "t": "諸位大姊，請僧眾聽我說：我是舊住此處的比丘尼，現在為僧眾唱說四方大界內側的界相。從小牆的東南角開始，向西穿過小牆出來，沿著大牆的內側，走到西南角的內角；從這裡沿著大牆向北走，筆直穿過小牆，到達小牆西北角的外角；從這裡沿著小牆向東走，到達小牆東北角的外角；從這裡沿著小牆向南走，回到小牆東南角的外角。這就是大界內側的界相，繞行一周到此完畢。", "i": "u55", "n": 104, "s": "第3篇　結界"}, {"v": "卷上", "o": "次唱外相者，應從寺院外牆東南角外角為始。", "t": "其次唱報大界的外相時，應當從寺院外牆東南角的外側轉角開始。", "i": "u56", "n": 105, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！我舊住比丘尼，今為僧唱四方大界相：從寺院外牆東南角外角，傍牆直至南門東頰外土楞；隨屈曲西出，至門西頰外土楞；從此西下，至西南角外角；從此北下，至西北角外角；從此東下，至東北角外角；從此南下，還至東南角外角。此是大界外相，一周訖。", "t": "各位大姊僧眾請聽：我是舊住此處的比丘尼，現在為僧眾唱說四方大界的界相。從寺院外牆東南角的外角起，沿著牆一直走到南門東側門柱外的土楞；順著曲折處向西繞出，到南門西側門柱外的土楞；從這裡向西行，到西南角的外角；從這裡向北行，到西北角的外角；從這裡向東行，到東北角的外角；從這裡向南行，回到東南角的外角。這就是大界的外相，唱示一周完畢。", "i": "u57", "n": 106, "s": "第3篇　結界"}, {"v": "卷上", "o": "第三唱已總結云：「此為外相，彼為內相，此是大界內外相，各三周訖。」唱已，應告僧云：「已唱大界內外相竟。」眾僧應作羯磨，唱尼然後復座。", "t": "第三，唱完之後作總結，這樣說：「這是外相，那是內相，這就是大界的內相與外相，內外各唱三遍完畢。」唱完之後，應向僧眾報告說：「大界的內外相已經唱完了。」僧眾接著應當作羯磨，唱相的比丘尼隨後回到自己的座位。", "i": "u58", "n": 107, "s": "第3篇　結界"}, {"v": "卷上", "o": "上座問：「僧集和合否？」答云：「僧集和合。」又問：「未受具戒者出。」答云：「已出。」又問：「僧今和合，何所作為？」答云：「結大界羯磨。", "t": "上座問：「僧眾集合了嗎？和合了嗎？」答：「僧眾已集合，並且和合。」又問：「尚未受具足戒的人出去了嗎？」答：「已經出去了。」又問：「僧眾現在和合，要做什麼事？」答：「作結大界的羯磨。」", "i": "u59", "n": 108, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方大界相。若僧時到，僧忍聽，僧今於此四方相內結大界，同一住處，同一說戒。白如是。", "t": "各位大姊，請僧眾聽我說：這個住處的比丘尼，已經宣告了四方大界的界相。如果僧團認為時機已到，請僧團同意，聽我宣告：僧團現在就在這四方界相之內結成大界，作為同一個住處、共同舉行說戒的範圍。以上就是我的宣告。", "i": "u60", "n": 109, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼唱四方大界相。僧今於此四方相內結大界，同一住處，同一說戒。誰諸大姉忍僧今於此四方相內結大界、同一住處、同一說戒者，默然；誰不忍者，說。僧已忍於此四方相內同一住處、同一說戒、結大界竟，僧忍默然故，是事如是持。", "t": "各位大姊僧眾請聽：本住處的比丘尼，已經唱說了四方大界的界相。僧眾現在就在這四方界相之內結成大界，共住同一界內、同作布薩誦戒。各位大姊當中，凡認可僧眾現在在這四方界相之內結大界、共住同一界內、同作布薩誦戒的，就默然不語；不認可的，就開口說出。僧眾已經認可，在這四方界相之內，以共住同一界內、同作布薩誦戒而結大界，已經完成。由於僧眾認可而默然的緣故，這件事就這樣受持奉行。", "i": "u61", "n": 110, "s": "第3篇　結界"}, {"v": "卷上", "o": "第五解界者，先解無戒場大界法。", "t": "第五是解界。先說明解除沒有戒場的大界的方法。", "i": "u62", "n": 111, "s": "第3篇　結界"}, {"v": "卷上", "o": "上座問：「僧集和合否？」答云：「僧集和合。」又問：「未受具戒者出。」答云：「已出。」又問：「不來諸比丘尼說欲否？」答云：「說欲訖。」又問：「僧今和合，何所作為？」答：「解大界羯磨。", "t": "上座問：「僧眾都集合、和合了嗎？」答：「僧眾已集合、和合。」又問：「未受具足戒的人出去了嗎？」答：「已經出去了。」又問：「未到場的諸位比丘尼，都說欲了嗎？」答：「已經轉達完畢。」又問：「僧眾現在和合，要作什麼事？」答：「作解大界的羯磨。」", "i": "u63", "n": 112, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼同一住處，同一說戒。若僧時到，僧忍聽，今解界。白如是。", "t": "各位大姊，請僧眾聽著：這個住處的比丘尼們，同屬一個住處、同一說戒。如果僧眾認為時機已到，請僧眾認可聽許：現在解除界。以上就是這樣的稟白。", "i": "u64", "n": 113, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！此住處比丘尼同一住處，同一說戒，今解界。誰說大姉忍僧同一住處、同一說戒、解界者，默然；誰不忍者，說。僧已忍同一住處、同一說戒、解界竟，僧忍默然故，是事如是持。", "t": "各位大姊，僧團請聽：這個住處的比丘尼，本是同一住處、同一說戒的，現在要解除這個界。哪位大姊贊同僧團解除這同一住處、同一說戒的界，就請保持沉默；不贊同的，請說出來。僧團已經認可，這同一住處、同一說戒的界已經解除完畢。由於僧團默然認可的緣故，這件事就這樣確定奉行。", "i": "u65", "n": 114, "s": "第3篇　結界"}, {"v": "卷上", "o": "若有戒場，先解大界，後解戒場，上座問答隨事別稱，不同受戒一答得作眾多羯磨。次解戒場者，正解戒場時，還須在戒場內，不得在大界遙解。律無解文，今準難事解界，但翻結為解，理通文順。", "t": "如果這個住處設有戒場，就先解大界，然後才解戒場。上座的問話與答話，必須隨各件所作之事分別稱說其名目，不像受戒時，一次回答就能接著做眾多羯磨。\n其次說到解戒場：正式解戒場的時候，人仍必須在戒場之內，不得站在大界中遠遠地解。律中沒有解戒場的羯磨文，現在比照律中因難事而解界的文句，只把結界的文翻轉成解界，這樣義理上說得通，文句也順。", "i": "u66", "n": 115, "s": "第3篇　結界"}, {"v": "卷上", "o": "問：「僧今和合，何所作為？」答：「解戒場羯磨。", "t": "問：僧眾現在已經和合集會，要作什麼事？答：作解除戒場的羯磨。", "i": "u67", "n": 116, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！僧集此處解戒場。若僧時到，僧忍聽，今解戒場。白如是。", "t": "諸位大姊，請僧眾聽：僧眾聚集在此處，要解除戒場。如果僧眾認為時機已到，請僧眾聽許：現在解除戒場。我的稟白就是這樣。", "i": "u68", "n": 117, "s": "第3篇　結界"}, {"v": "卷上", "o": "大姉僧聽！僧集此處解戒場。誰諸大姉忍僧集此處解戒場者，默然；誰不忍者，說。僧已忍集此處解戒場竟，僧忍默然故，是事如是持。", "t": "諸位大姊，請僧眾聽著：僧眾集合在這裡解除戒場。諸位大姊當中，凡是認可僧眾集合在此解除戒場的，就保持沉默；不認可的，就說出來。僧眾已經認可了，集合在此解除戒場的事已經完成。由於僧眾認可而默然的緣故，這件事就這樣確定、這樣受持。", "i": "u69", "n": 118, "s": "第3篇　結界"}, {"v": "卷上", "o": "此律：「治故伽藍，不失淨地；若疑，應捨已更結。」《見論》云：「依相結已，後失界相，界亦不失。」《小法滅盡經》云：「劫火起時，曾作伽藍所，不為火焚，乃至金剛界為土臺也。」假令惡心解界，亦不失。", "t": "本《四分律》說：修治舊有的僧伽藍，並不會失去原先結成的淨地；若對淨地所在心存懷疑，就應先捨掉，再重新結。《善見律毘婆沙》說：依標相結界之後，日後即使標相消失，界也仍然不失。《小法滅盡經》說：劫末大火生起時，曾經作過僧伽藍的地方不會被火焚燒，乃至火燒到金剛輪際，該處仍存留為一座土臺。假使有人懷著惡心作解界的羯磨，界也同樣不會失去。", "i": "u70", "n": 119, "s": "第3篇　結界"}, {"v": "卷上", "o": "○集眾篇第四", "t": "第四篇　召集僧眾", "i": "u71", "n": 120, "s": "第4篇　集眾"}, {"v": "卷上", "o": "此篇大門有三：一、鳴穉，二、集僧，三、分齊。", "t": "本篇大分為三門：一是敲響犍稚，二是集合僧眾，三是分齊。", "i": "u72", "n": 121, "s": "第4篇　集眾"}, {"v": "卷上", "o": "第一鳴穉者，《五分》初打三通，後因他請，方有長打。《付法藏經》云：「長打，意存濟苦。」《增一阿含經》云：「若打鐘時，一切惡道諸苦竝停。」又說二偈：\n「除五百億劫，生死之重罪，降伏魔力冤，除結盡無餘。\n露地擊犍穉，比丘聞當集，諸欲聞法人，度流生死海，聞此玅響音，盡當雲集此。」", "t": "第一是鳴稚，即敲響犍稚。《五分律》說，最初只打三通，後來因為他人的請求，才有了歷時較久的「長打」。《付法藏經》說：長打的用意在於救濟受苦的眾生。《增一阿含經》說：打鐘的時候，一切惡道的種種痛苦都一齊停息；又說了兩首偈頌：「除滅五百億劫生死的重罪，降伏魔力這個怨敵，斷盡煩惱結使而無剩餘。在露天空地上敲擊犍稚，比丘們聽到就應當集合；凡是想聽聞正法、度脫生死流轉大海的人，聽到這美妙的聲響，都應當如雲一般聚集到這裡來。」", "i": "u73", "n": 122, "s": "第4篇　集眾"}, {"v": "卷上", "o": "既知如此，維那將欲鳴穉，先具威儀，禮十方佛已，至誠為物，召集十方賢聖之意，然後漸漸生槌，令從微至著，不得麤心大打，驚動眾心。", "t": "既然知道情形如此，維那將要敲犍稚時，先要具足威儀，禮拜十方諸佛之後，以至誠的心為眾生著想，存著召集十方賢聖的心意，然後漸漸起槌敲擊，使聲音從微小到洪大，不可用粗率的心大力敲打，驚動眾人的心。", "i": "u73-2", "n": 123, "s": "第4篇　集眾"}, {"v": "卷上", "o": "《西傳》云：「時至，應臂吒犍穉。」臂吒者，此云打；犍穉者，此云所打之木，或用檀、桐木等；彼無鐘磬，故多打木集人也。", "t": "西方印度的傳述說：時候到了，應當「臂吒犍稚」。「臂吒」，這裡譯為「打」；「犍稚」，這裡譯為「所打的木頭」，或用檀木、桐木等做成。因為那裡沒有鐘、磬，所以大多敲木頭來集合眾人。", "i": "u73-3", "n": 124, "s": "第4篇　集眾"}, {"v": "卷上", "o": "《五分》：「布薩不時集，妨行道。」佛言：「唱時至，若打犍穉，若打鼓、吹螺，使舊住沙彌、淨人；不得多打，應打三通；在處多不得徧聞，高處唱之；猶不知集，應更相語知集；若無沙彌、淨人，比丘亦得打。」", "t": "《五分律》記載：布薩時僧眾不按時集合，妨礙修行。佛說：唱言「時至」，或打犍稚，或打鼓、吹螺，讓舊住的沙彌、淨人去做；不應多打，應打三通。若住處多，聲音無法普遍聽到，就到高處唱告；若仍不知道要集合，就應彼此轉告，使大家都知道集合。若沒有沙彌、淨人，比丘也可以打。", "i": "u73-4", "n": 125, "s": "第4篇　集眾"}, {"v": "卷上", "o": "《十誦》云：「居士請僧，自於寺內鳴穉，乃至白時至；及送食女人，亦自鳴穉。」\n此律：「若唱時到，亦言沙彌、白衣為之。", "t": "《十誦律》說：居士請僧時，自己在寺院內敲犍稚，乃至稟白「時至」；送食物來的女人，也自己敲犍稚。《四分律》說到唱「時到」，也說是由沙彌、白衣來做。", "i": "u73-5", "n": 126, "s": "第4篇　集眾"}, {"v": "卷上", "o": "第二集僧者，此有二種：第一、若作法界攝僧，盡須界內集，除說欲不犯。第二、若自然界，則有二節：一、可分別聚落，謂城外村坊、邊夷城邑，人民稀尠，可得分別，隨義立名也；即準《十誦》：於無僧坊聚落中，初作僧坊，未結界相，隨聚落界，是僧坊界，下文「齊行來處，此內不得別眾」，此應是可分別聚落也；此律聚落界取其院相。二、不可分別聚落者，謂中華之處，人民繁多，不可分別，隨義立名也；即準《僧祇》：若城邑聚落界分不可知者，用五肘弓，七弓種一樹，齊七樹相去，使異眾相見，不犯別眾，各得成就，此應是不可分別聚落也。義準相通，計七樹六間，總有六十三步。", "t": "第二是集僧，這有兩種情形。第一，若是依羯磨作法所結的界，凡此界所攝的僧眾，全都必須在界內集合，除了已說欲、託人代達同意的人不犯。第二，若是自然形成、非作法所結的界，又分兩節。\n一、可分別的聚落：指城外的村莊坊里、邊遠夷地的城邑，人民稀少，界域可以分辨清楚，這是隨其意義而安立的名稱。就依《十誦律》所說：在沒有僧坊的聚落中，最初建造僧坊，還未結定界相時，便隨聚落的界作為僧坊的界。《十誦》下文說「齊行來處」，以人們往來所及之處為界，在這範圍之內不得別眾。這應當就是可分別的聚落。《四分律》所明的聚落界，則取院落的相狀為界。\n二、不可分別的聚落：指中華之地，人民眾多，界域無法分辨，這也是隨其意義而安立的名稱。就依《摩訶僧祇律》所說：若城邑、聚落的界域分際無法得知，就用五肘長的弓來量，每隔七弓種一棵樹；以相隔七棵樹的距離為準，使不同的僧眾彼此相見而不犯別眾，各自的法事都能成就。這應當就是不可分別的聚落。依義理準用，這個量度是通用的：七棵樹之間共有六個間隔，合計六十三步。", "i": "u74", "n": 127, "s": "第4篇　集眾"}, {"v": "卷上", "o": "第三分齊者，此總明僧有四種：一、四人僧者，極少說戒、捨墮者是；二、五人僧者，謂極少邊地受具、自恣者是；三、十人僧者，謂極少中國受戒者是；四、二十僧者，謂極少懺僧殘、出罪者是。\n義云：前之四僧，各據自行為言，竝須清淨，如已犯小罪，不應羯磨故。若據眾法，則有二種：若為說戒、懺罪，必須清淨，以有犯者不得說戒、不得聞戒、不得向犯者懺悔、犯者不得受他懺悔；若為受戒生善門者，未必取體，但使三根相淨，令前人起尊仰心，便成受具。故律云：「弟子雖知和尚犯重，而不知『向如是人邊受戒不得』，亦開成受。」當知但取相淨。", "t": "第三是分齊，即僧數的界限：這裡總括說明僧有四種。一、四人僧：最少四人，就能作說戒、捨墮罪的懺悔等事。二、五人僧：最少五人，就能在邊遠地區授具足戒、作自恣等事。三、十人僧：最少十人，才能在中國，即中印度佛法興盛之地，授具足戒。四、二十人僧：最少二十人，才能作懺除僧殘罪的出罪羯磨。\n依義理說：前面這四種僧，若各就自身的行持來說，都必須清淨，例如已犯小罪的人，就不應作羯磨。若就僧眾作法來說，則有兩類：若是為了說戒、懺罪，就必須清淨，因為有犯的人不得說戒、不得聽戒，清淨者不得向有犯的人懺悔，有犯的人不得接受別人的懺悔；若是為了受戒，屬於生善這一門的，就不一定要求僧眾本身實際清淨，只要就見、聞、疑三根看來外相清淨，能使受戒的人生起尊重景仰之心，便成就受具足戒。所以律中說：「弟子雖然知道和尚犯了重罪，卻不知道向這樣的人受戒是不得戒的，也開許他成就受戒。」由此可知，只取外相清淨。", "i": "u75", "n": 128, "s": "第4篇　集眾"}, {"v": "卷上", "o": "○足數篇第五", "t": "○第五篇：足數。", "i": "u76", "n": 129, "s": "第5篇　足數"}, {"v": "卷上", "o": "此篇大門有二：一、擇眾，二、簡相。", "t": "本篇大綱分為兩部分：一是揀擇眾僧，二是簡別相狀。", "i": "u77", "n": 130, "s": "第5篇　足數"}, {"v": "卷上", "o": "第一擇眾者，", "t": "第一門是揀擇人眾。", "i": "uGAP02-1", "n": 131, "s": "第5篇　足數"}, {"v": "卷上", "o": "十誦》云：「有十一人不足僧數，謂睡眠比丘，若聞白已睡者得成，未白已前不足數；亂語人、憒閙人、入定人、瘂人、聾人、具二人、狂人、亂心人、病壞心人、樹上比丘等，竝不足數。」", "t": "《十誦律》說有十一種人不能充足僧數：所謂睡眠的比丘——若聽聞白告之後才睡著，羯磨仍得成就；在白告之前就睡著的，則不足僧數。其餘言語雜亂的人、昏亂喧鬧的人、入定的人、瘂人、聾人、瘂聾兼具的人、癲狂的人、心識錯亂的人、因病而心識敗壞的人、在樹上的比丘等，都不足僧數。", "i": "uGAP02-2", "n": 132, "s": "第5篇　足數"}, {"v": "卷上", "o": "伽論》云：「有三人不足數：重病人、邊地人、癡鈍人等，受戒、自恣一切不成足數。」", "t": "《薩婆多部毘尼摩得勒伽》說有三種人不足數：重病人、邊地人、癡鈍人等，受戒、自恣等一切法事都不能以他們充足僧數。", "i": "uGAP02-3", "n": 133, "s": "第5篇　足數"}, {"v": "卷上", "o": "僧祇》云：「有七人不足數，謂和尚足十，授戒不成；若與欲人、若隔障、若半覆半露中間隔障、若半覆半露伸手不相及、露地不相及，乃至行作羯磨坐則犯別住、坐臥互乖亦爾。」\n義加醉尼，亦不足數；《十誦》白衣，亦不足數；《婆論》亦不足數。", "t": "《僧祇律》說有七種人不足數：和尚若被算入十人之內，授戒便不成；以及與欲（託人送欲而不在場）的人、有隔障的人、半覆半露而中間有隔障的、半覆半露而伸手不相及的、露地伸手不相及的；乃至僧眾行進而作羯磨時，坐著的人便犯別住（與僧乖隔）；坐與臥的威儀互相乖違，也是一樣。依義理推加，醉酒的比丘尼也不足數。《十誦律》說白衣也不足數，《薩婆多毘尼毘婆沙》也說不足數。", "i": "uGAP02-4", "n": 134, "s": "第5篇　足數"}, {"v": "卷上", "o": "此律有二十八人不足數：謂為比丘作羯磨，比丘尼，及式叉、沙彌、沙彌尼、十三難、三舉、已擯、應擯等，此二十二人，由非類故不足；別住、戒場上、神足在空、隱沒、離見聞處，此等五人，雖是同類，由與僧居相中是乖，故不足數；為羯磨人，由為僧量，故不足數；和尚一人，不足受戒羯磨，為他所量故。", "t": "《四分律》說有二十八種人不能充足僧數：為比丘作羯磨時，比丘尼以及式叉摩那、沙彌、沙彌尼、十三難人、三舉人、已擯人、應擯人等，這二十二種人由於不是同類，所以不能足數。別住在另一處（界）的人、在戒場上的人、以神足通在空中的人、身形隱沒不現的人、離見聞處的人，這五種人雖是同類，但由於與僧眾共住的相狀有所乖違，所以不能足數。僧眾為他作羯磨的那個人（即羯磨的對象），由於是被僧眾審量的對象，所以不能足數。和尚這一種人不能充足受戒羯磨的人數，因為他是被他人所審量的對象。", "i": "uGAP02-5", "n": 135, "s": "第5篇　足數"}, {"v": "卷上", "o": "訶責、擯出、依止、遮不至白衣家等四人，得應一切羯磨；摩那埵、本日治、出罪等三人，及《十誦》中行本日治竟、行摩那埵竟，合有五人，不足前摩那埵等三種羯磨，得應餘法事用。", "t": "受訶責、擯出、依止、遮不至白衣家等四種羯磨處分的人，仍得充足一切羯磨的僧數。行摩那埵、行本日治、出罪等三種人，以及《十誦律》中行本日治已竟、行摩那埵已竟的二種人，合共五種人，不能充足前面摩那埵等三種羯磨的人數，但仍得充足其餘法事的僧數。", "i": "uGAP02-6", "n": 136, "s": "第5篇　足數"}, {"v": "卷上", "o": "義云：十三難等，若未自言已前，同僧法事，竝得成就；若雖自言，當作法時無人知者，亦成僧事，由相不違，辨得前事故。此律云：「不得以天眼觀他淨穢，應以肉眼看也。」《十誦》云：「若犯重人、賊詐作比丘、本白衣時破戒人等，若言過後，羯磨不成；若不言者，一切法成。」乃至：「亦不聽天眼看他持犯。」", "t": "按義而言：十三難人等，在尚未自己陳說之前，參與僧眾的法事都能成就；即使已經自己陳說，在作法當時若無人知道，也仍然成就僧事。這是由於外相上沒有乖違，因而能成辦前面所說法事的緣故。所以《四分律》說：不許用天眼去觀察別人的清淨或污穢，應當用肉眼來看。《十誦律》說：像犯了重罪的人、詐冒比丘的賊住者、原本還是白衣時就已破戒的人等，如果先前已自說了過失，之後作羯磨就不能成就；如果不曾自說，一切法事都能成就。乃至也不允許用天眼去察看別人持戒、犯戒的情形。", "i": "uGAP02-7", "n": 137, "s": "第5篇　足數"}, {"v": "卷上", "o": "義云：自言者，要告前人云「我犯淫盜等」，令前人了了知解，方為自言。若雖不自言，然眾竝知是犯重、十三難人等，舉國知聞，眾人共悉，此等諸人，不待自言，亦不足數，假令同界不喚無過。", "t": "按義而言：所謂「自言」，必須是告訴對方說「我犯了淫、盜等罪」，使對方清清楚楚地知曉理解，才算是「自言」。如果雖然沒有自言，然而大眾都知道他是犯重罪、具十三難等的人，全國都知道、人人都清楚，這些人就不必等他們自言，也同樣不能算入僧數；即使同在同一結界之內，不召喚他來參加，也沒有過失。", "i": "uGAP02-8", "n": 138, "s": "第5篇　足數"}, {"v": "卷上", "o": "若爾，何故律云竝要自言，又不應以天眼觀他淨穢耶？」", "t": "問：既然如此，為什麼律中說一概都要犯者自言，又說不應以天眼觀察別人的清淨污穢呢？", "i": "uGAP02-9", "n": 139, "s": "第5篇　足數"}, {"v": "卷上", "o": "答：「律要自言者，據不知者論；今既知犯，豈待自言？又不許天眼觀，應以肉眼看，我還以肉眼看，不用天眼觀，何為得足數？」\n故《婆論》云：「犯重比丘，眾僧知犯，不須自言及以現前，直爾滅擯驅出。」", "t": "答：律中要求自言，是就大眾不知情的情況說的。如今既已知道他犯戒，哪裡還用得著等他自言？又，律中不許用天眼觀，應當用肉眼看。我如今還是用肉眼看的，並沒有用天眼去觀察，這樣的人為什麼還能算入僧數呢？所以《薩婆多毘尼毘婆沙》說：犯了重罪的比丘，眾僧既已知道他犯戒，就不需要他自言，也不需要他現前在場，直接予以滅擯、驅逐出去。", "i": "uGAP02-10", "n": 140, "s": "第5篇　足數"}, {"v": "卷上", "o": "義云：若審知有此犯重人，其人兇惡，不可揀出，秉法之人，若在露地作法，必令眾僧肩膝相拄，周帀而坐，不得間隔好人、單行而坐，伸手之外，便成別眾。若行此法，宜可密為，不得向說，前人若知，反成礙法。若在堂內覆障處作法者，雖好惡相參，法成無過。今時末法，犯者極多，恐法難辨，故別標記。", "t": "按義而言：如果確知有這樣的犯重之人，而那人兇惡，無法把他排除出去，那麼主持羯磨的人如果在露天無遮蔽的地方作法，務必讓眾僧肩靠著肩、膝碰著膝，周匝緊密圍坐，中間不得有間隔；若清淨好人排成單行而坐，超出伸手可及的範圍之外，就成了別眾。若要施行這個辦法，應當秘密進行，不可向那名犯重者說明；他若知道了，反而會障礙法事。如果在堂屋內等有覆蓋遮障的地方作法，即使好人與惡人混雜在一起，法事也能成就，沒有過失。如今末法時代，犯戒的人極多，恐怕法事難以成辦，所以特別標記出來。", "i": "uGAP02-11", "n": 141, "s": "第5篇　足數"}, {"v": "卷上", "o": "第二簡相者，夫論眾法，但取外淨，不論內染，但令相順，心違便成法事。故律云：「見如法羯磨，而心不同，得成如法。」準此，取相，不論心非。\n若欲秉法，問和，待答人坐竟，然後為之；為濟被治，許立得成；若乞受戒、懺悔等，坐乞彌善，雖無正文，義準應得。唯有二人立秉得成：一、威儀師，為僧所使，不得輒坐；二、半月說戒，眾大難聞，開立說戒。自餘一切，竝須坐秉也。如律云：「為眾大，開作轉輪高座說戒。」未必立說得成，舊開立說戒者，良恐不成。若依此說，但開威儀師一人得立秉法，餘者不成。\n《五分》云：「病人背羯磨。」佛言：「犯別眾。", "t": "第二門是簡別外相。凡是僧眾作法，只取外表的清淨，不論內心的染污；只要外相隨順一致，縱使內心相違，法事也能成就。所以《四分律》說：「見到如法的羯磨，心裡雖不認同，羯磨仍成就為如法。」依此可知，只取外相，不論內心是否認許。\n若要秉法作法，應先問僧和合，等待回答，待眾人坐定之後，才開始作法。為了成辦被治罰者的羯磨，准許他站立，法事也能成就。至於乞求受戒、乞求懺悔等的人，坐著乞求更好；雖然沒有明文開許站立而乞，依義理推準，也應當是可以的。\n只有兩種人站著秉法能夠成就：一是威儀師，他為僧所差使，不得擅自坐下；二是半月說戒時，因僧眾龐大、難以聽聞，開許站著說戒。除此之外，一切都必須坐著秉法。如律中所說，因僧眾人多，開許作轉輪高座說戒；由此看來，站著說戒未必就能成就。舊來開許站著說戒的主張，實在恐怕不能成事。若依這個說法，就只開許威儀師一人可以站著秉法，其餘的都不成就。\n《五分律》說：病人背向羯磨，佛說這樣犯了別眾。", "i": "u78", "n": 142, "s": "第5篇　足數"}, {"v": "卷上", "o": "○受欲篇第六", "t": "○ 第六篇　受欲：接受不能到場者所囑授的欲，代為向僧眾傳達其同意並聲明其清淨。", "i": "u79", "n": 143, "s": "第6篇　受欲"}, {"v": "卷上", "o": "此篇大門有二：一、欲緣，二、說法。", "t": "本篇大分為兩門：一是「欲緣」，即得以託人轉達自己同意而與欲的因緣條件；二是「說法」，即宣說與欲的作法。", "i": "u80", "n": 144, "s": "第6篇　受欲"}, {"v": "卷上", "o": "第一欲緣者，義云：若有犯戒、非法緣等，以事非故，不合與欲；故律云：「若為佛、法、僧、塔、看病、病人等，是正緣開也。」今時尼眾，輕慢說戒，不敬羯磨，聞道眾集作法，則生怠惰心；受戲論、造作非法，則身輕奮勇；致令說欲者多，眾集者少。又無病稱病，不欲言欲，不淨言淨，令他傳妄，對眾而說，隨僧多少，一一尼邊，皆獲三提；所傳之人，知而妄告，亦得三罪。\n問：「無病既不合說欲，得成法事否？」答：「成，前人自有妄語之罪。", "t": "第一是「欲緣」，即可以與欲的因緣。依義理判釋說：若是為了犯戒之事、非法的因緣等，由於事情本身不正當，就不該為此而與欲，也就是託人向僧中傳達自己的同意與清淨。所以《四分律》說：若是為了佛事、法事、僧事、塔事、看護病人、自己患病等，這些才是正當的因緣，才開許與欲。\n現今的尼眾輕慢說戒，不敬重羯磨法事，一聽說大眾集合要作法，就生起懈怠懶惰的心；至於聽受戲論、造作非法的事，卻身體輕快、奮勇積極。以致說欲託人的人多，真正到大眾中集合的人少。而且沒有病卻聲稱有病，心裡並不願意卻口說與欲，自身不清淨卻說清淨，讓別人把這些妄語傳到僧中，對著大眾宣說。這樣，隨著僧眾人數的多少，那妄說欲的人在僧中每一位尼邊，各結三個波逸提罪；代為傳達的人明知不實卻妄加宣告，也同樣得三個罪。\n問：沒有病既然不該說欲，那麼這樣說欲，法事還能成就嗎？\n答：能成就，只是那位託欲的本人自己犯下妄語之罪。", "i": "u81", "n": 145, "s": "第6篇　受欲"}, {"v": "卷上", "o": "第二說法者，此律正說欲文不牒其事，今時著者，乃是古人所加，不安無失。", "t": "第二是說明說欲的作法。《四分律》中正式宣說與欲的文句，並不具體標明所為的是哪一件事；現今有人在欲辭裡加寫事名的，那是古人所添加的，不加上也沒有過失。", "i": "u82", "n": 146, "s": "第6篇　受欲"}, {"v": "卷上", "o": "大姉一心念！我某甲比丘尼，如法僧事，與欲清淨。", "t": "大姊，請專一心念聽我說：我某甲比丘尼，就僧團如法辦理的法事，在此把我的同意託付給你，並自陳戒行清淨。", "i": "u83", "n": 147, "s": "第6篇　受欲"}, {"v": "卷上", "o": "次明轉欲兼他法，謂受他欲已，自有緣事不得往者，須轉與他，佛云開之。問：「得幾度轉？」答：「依《母論》，得七反轉。", "t": "接著說明轉欲、兼帶他人之欲的作法：所謂已經接受他人所託的欲，自己卻另有因緣事務無法前往僧中，就必須把這份欲轉交給另一人，佛說開許這樣作。問：可以轉幾次？答：依《毘尼母論》，最多可以轉七次。", "i": "u84", "n": 148, "s": "第6篇　受欲"}, {"v": "卷上", "o": "大姉一心念！我某甲比丘尼，受某甲比丘尼欲清淨；彼及我身，如法僧事，與欲清淨。", "t": "大姊，請專心聽我說：我某甲比丘尼，已領受某甲比丘尼所託付的欲與清淨，即對僧事的同意委託與戒行清淨的自陳。她與我自身，對於如法的僧事，一併交付欲與清淨。", "i": "u85", "n": 149, "s": "第6篇　受欲"}, {"v": "卷上", "o": "問：「欲與清淨，同異云何？」答：「欲應羯磨，清淨應說戒；若說戒之時，二俱須牒。」\n此律：「若重病人，不能廣說者，聽若言『我說欲』，若言『與我說欲』，若言『為我說欲』，若現身相等，竝成欲。」\n問：「餘說可解，若為現相？」答：「《五分》云：『病人不能口說，聽現身相與清淨欲：若舉手、舉指、搖頭，乃至舉眼，得名清淨。』」\n對眾法。", "t": "問：「欲」與「清淨」這兩者，是相同還是有別？\n答：「欲」是對應羯磨而給的，「清淨」是對應說戒而給的；若是在說戒的時候，這兩者都必須一併陳說。《四分律》說：病重的人若不能完整地廣說欲詞，聽許他只說「我表明與欲」，或說「請替我傳達與欲」，或說「請為我傳達與欲」，或者用身體動作示意等，這些都成就與欲。\n問：其餘幾種用言語表達的方式可以理解，那麼以身體動作示意的「現身相」是怎樣的情形呢？\n答：《五分律》說：病人不能開口說話，聽許他用身體動作示意來給與清淨與欲；例如舉手、舉手指、搖頭，乃至抬起眼睛，都算得名為清淨。\n向僧眾陳說的方法。", "i": "u86", "n": 150, "s": "第6篇　受欲"}, {"v": "卷上", "o": "大姉僧聽！某甲比丘尼，我受彼欲清淨；彼如法僧事，與欲清淨。", "t": "大姊僧眾請聽：某甲比丘尼，我已領受了她的欲與清淨；她對如法的僧事，交付欲與清淨。", "i": "u87", "n": 151, "s": "第6篇　受欲"}, {"v": "卷上", "o": "若受他欲已，不得住者，對僧說云。", "t": "如果已經接受了他人的與欲委託，自己卻不能留在僧眾當中，就應當對僧眾這樣說：", "i": "u88", "n": 152, "s": "第6篇　受欲"}, {"v": "卷上", "o": "大姉僧聽！我某甲比丘尼，彼某甲比丘尼，我受彼欲清淨；彼及我身，如法僧事，與欲清淨。", "t": "諸位大姊，請僧眾聽我說：我某甲比丘尼，那位某甲比丘尼，我已接受了她託付的欲與清淨。她和我自身，對於僧團如法的事務，一併交付欲與清淨。", "i": "u89", "n": 153, "s": "第6篇　受欲"}, {"v": "卷上", "o": "若自有緣，說付僧者。", "t": "如果自己有緣事，要將自己的欲與清淨陳說託付給僧眾，就這樣說：", "i": "u90", "n": 154, "s": "第6篇　受欲"}, {"v": "卷上", "o": "大姉僧聽！我某甲比丘尼，如法僧事，與欲清淨。", "t": "諸位大姊，請僧團聽我說：我某甲比丘尼，對於如法的僧團事務，在此交付我的同意，並表明自身清淨。", "i": "u91", "n": 155, "s": "第6篇　受欲"}, {"v": "卷上", "o": "問：「對僧說欲，音聲閙亂，一時總說者，得成以否？」答：「若有難逼，定應得成；除此，良恐非法不成，故《五分》、《僧祇》令至僧中稱名字說，若不如是，一一不成。」\n問：「欲人多、坐人少，得成法否？」答：「此律不了，餘部恐不成，故《僧祇》云：『與欲人若多，作布薩，得越毗尼罪。』《五分》云：『聽多人集，持欲人來少。』」\n問：「睡眠、忘誤不說者，得成否？」答：「此律：受欲人若睡眠、入定、忘誤不說，皆成；若故不說，法成得罪。」\n問：「與欲已，前事訖不來，犯別眾否？」答：「不犯，以我情和至僧，不關欲緣事也。", "t": "問：在僧中稟說所受之欲時，由於人聲喧鬧雜亂，便把眾人的欲一次總合說完，這樣能成立嗎？\n答：若有危難緊迫，必定應當能成立；除此以外，實在恐怕不如法而不能成立。所以《五分律》與《摩訶僧祇律》都要求持欲的人到僧中，稱與欲者的名字而說，若不這樣做，每一人的欲都不成立。\n問：與欲的人多，在場就坐的人少，這樣作法能成立嗎？\n答：《四分律》對此沒有明白判定，依其他部律恐怕不能成立。所以《摩訶僧祇律》說：與欲的人若多於現前集坐的人，作布薩就得越毘尼罪。《五分律》說「聽多人集，持欲人來少」，也就是聽許親自到場聚集的人多，所代持的欲少。\n問：受欲的人睡著、遺忘或失誤而沒有稟說，能成立嗎？\n答：《四分律》說：受欲的人若睡著、入定、遺忘、失誤而沒有說，都算成立；若是故意不說，作法雖成立，本人卻得罪。\n問：已經與欲之後，先前的事務辦完就不來僧中，這樣犯別眾嗎？\n答：不犯。因為我和合僧事的心意已經傳達到僧中，並不關涉當初與欲的那件緣事。", "i": "u92", "n": 156, "s": "第6篇　受欲"}, {"v": "卷上", "o": "○十戒篇第七", "t": "第七篇　十戒。", "i": "u93", "n": 157, "s": "第7篇　十戒"}, {"v": "卷上", "o": "此篇大門有十：一、釋名，二、出家，三、受戒，四、受衣，五、說淨，六、捨墮，七、說戒，八、安居，九、受日，十、自恣。", "t": "這一篇的大綱共有十門：第一是解釋名稱，第二是出家，第三是受戒，第四是受衣，第五是說淨，第六是捨墮，第七是說戒，第八是安居，第九是受日，第十是自恣。", "i": "u94", "n": 158, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第一釋名者，《耶舍傳》云：「沙彌者，註云『勞之小者，以修道勞也』；又翻為息慈，謂息世染之情，以慈濟萬物也；又創入佛法，俗情猶存，故須息惡行慈也。", "t": "第一、解釋名稱。《耶舍傳》說到「沙彌」，注解說是「勞之小者」，也就是勤勞修道者中的年少者，因為修道即是勤勞之事。又翻譯為「息慈」，意思是止息世間染污的情執，以慈悲救濟一切眾生。又因為剛進入佛法，世俗的情習仍然存在，所以必須止息惡行、修行慈心。", "i": "u95", "n": 159, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第二出家者，《僧祇》云：「一日一夜出家修梵行，離六百六千六十歲三途苦。」《本緣經》云：「一日一夜出家故，二十劫不墮三惡道。」《五百問事》云：「父母、王法不聽，盜度犯重。」《見論》云：「求度不得，欲燒寺者，聽不白父母，得度出家。」此律：「不白父母，私度巧師兒出家，佛言：『自今已去，若度出家者，應作單白和僧，使知為成。』」問答無過失。\n立出家者眼見耳不聞處，作形同單白和僧云。", "t": "第二是出家。《摩訶僧祇律》說：哪怕只有一日一夜出家修梵行，也能免除六百六千六十歲的三惡道苦。《本緣經》說：由於一日一夜出家的緣故，二十劫中不墮三惡道。《五百問事》說：父母不允許、或國王法令不允許的人，若私自偷度他出家，度他的人犯重罪。《善見律毘婆沙》說：有人請求剃度卻得不到允許，揚言要焚燒寺院，遇到這種情形，開許不稟白父母就度他出家。本律（《四分律》）記載：有比丘未告知這孩子的父母，就私自度巧匠的兒子出家。佛說：從今以後，若要度人出家，應當作單白和合僧眾，使僧眾都知道，這樣度人出家才算成就。如此的問答便沒有過失。\n接著讓求出家的人站在僧眾看得見他、而他聽不到僧眾羯磨聲音的地方，作「形同單白」和合僧眾，這樣說：", "i": "u96", "n": 160, "s": "第7篇　十戒"}, {"v": "卷上", "o": "僧今和合，何所作為？」答：「作形同單白羯磨。", "t": "問：僧眾如今已和合集會，要做什麼事呢？答：作形同單白羯磨。", "i": "u97", "n": 161, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉僧聽！是某甲從比丘尼某甲求剃髮。若僧時到，僧忍聽，某甲從比丘尼某甲剃髮。白如是。", "t": "各位大姊僧眾請聽：這位某甲向比丘尼某甲請求剃髮。如果僧眾認為時機已到，就請僧眾同意聽許：由比丘尼某甲為某甲剃髮。我的稟白就是這樣。", "i": "u98", "n": 162, "s": "第7篇　十戒"}, {"v": "卷上", "o": "次請和尚云。", "t": "接著迎請和尚尼，這樣說：", "i": "u99", "n": 163, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！我某甲，今請大姉為和尚；願大姉為我作和尚，我依大姉故，得剃髮出家，慈愍故。", "t": "大姊，請專心憶念：我某甲，現在請求大姊作我的和尚。懇願大姊為我擔任和尚。我依止大姊的緣故，得以剃髮出家。願您慈悲憐愍我。", "i": "u100", "n": 164, "s": "第7篇　十戒"}, {"v": "卷上", "o": "次請阿闍棃云。", "t": "接著啟請阿闍梨，這樣說：", "i": "u101", "n": 165, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！我某甲，今請大姉為阿闍棃；願大姉為我作阿闍棃，我依大姉故，得剃髮出家，慈愍故。", "t": "大姊請專心繫念：我某甲，現在禮請大姊作我的阿闍梨。懇願大姊為我擔任阿闍梨，我依止大姊的緣故，得以剃髮出家，惟願大姊慈悲憐愍我。", "i": "u102", "n": 166, "s": "第7篇　十戒"}, {"v": "卷上", "o": "二師竝答言：「好。", "t": "和尚與阿闍梨這兩位師父都回答說：「好。」", "i": "u103", "n": 167, "s": "第7篇　十戒"}, {"v": "卷上", "o": "婆論》云：「若先請和尚，受十戒時和尚不現前，亦得十戒；若聞知死，受戒不得；若不聞死，受戒得成。」闍棃應同清淨士。", "t": "《薩婆多論》說：如果事先已請定和尚，受十戒時和尚不在現場，也能得十戒；但若已聽說和尚死了，受戒就不得成就；若沒有聽說和尚去世，受戒仍能成就。阿闍梨也應比照相同，同樣須是清淨之士（清淨的人）。", "i": "u104", "n": 168, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《度人經》云：「於落髮處，香湯灑地，周圍七尺內，四角懸旛，安一小座擬出家者坐，復施二勝座擬二師坐。欲出家者，著本俗服，拜辭父母尊親訖，口說偈云：『流轉三界中，恩愛不能脫；棄恩入無為，真實報恩者。』」", "t": "《度人經》說：在剃髮的處所，用香湯灑地，周圍七尺的範圍之內，四角懸掛幡；安放一個小座位，準備給出家的人坐；再設兩個較為殊勝的座位，準備給兩位師父（和尚與阿闍梨）坐。要出家的人穿著原來的俗家衣服，向父母尊長親眷禮拜辭別完畢，口中說偈：「在三界中流轉，恩愛的繫縛擺脫不了；捨棄恩愛而進入無為涅槃，才是真正報恩的人。」", "i": "u104-2", "n": 169, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《見論》云：「應以香湯洗浴，除白衣氣。」", "t": "《善見論》說：應當用香湯沐浴，除去白衣（在家人）的氣味。", "i": "u104-3", "n": 170, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《度人經》云：「仍著出家衣，止得著泥洹僧及僧祇支，未得著安陀會。入道場時，應來至和尚前長跪，和尚應生兒想，不得生惡賤心；弟子於師，應生父想。和尚為種種說法，誡其心已，來向闍棃前坐。」", "t": "《度人經》說：接著換上出家人的衣服，但只可以穿泥洹僧（內衣、裙）和僧祇支（掩腋衣），還不能穿安陀會（五條衣）。進入道場時，應當走到和尚面前長跪。和尚應當對他生起如同自己兒子一般的想法，不可生起厭惡輕賤的心；弟子對師父則應生起如同父親一般的想法。和尚為他作種種說法、教誡他的心之後，他就來到阿闍梨面前坐下。", "i": "u104-4", "n": 171, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《善見》云：「以香水灌頂，讚云：『善哉大丈夫！能了世無常，捨俗趣泥洹，希有難思議！』敬禮十方佛竟，說偈云：『歸依大世尊，能度三有苦，亦願諸眾生，普入無為樂。』」", "t": "《善見論》說：用香水灌頂，讚歎說：「好啊，大丈夫！能了知世間無常，捨離世俗、趣向涅槃，稀有得難以思議！」敬禮十方諸佛完畢，再說偈：「歸依偉大的世尊，他能度脫三有（三界）的苦；也願一切眾生，普遍同入無為涅槃之樂。」", "i": "u104-5", "n": 172, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《度人經》云：「為剃髮時，傍人為誦出家唄云：『毀形守志節，割愛無所親，棄家弘聖道，願度一切人。』與剃髮時，當頂留三五周羅髮，來至和尚前長跪，和尚問言：『今為汝除去頂髮，許否？』答云：『好。』然後和尚為著袈裟。」", "t": "《度人經》說：為他剃髮的時候，旁邊的人為他誦出家唄讚：「毀壞形好而守持志節，割捨情愛而無所親戀，捨離家庭弘揚聖道，願度脫一切人。」替他剃髮時，要在頭頂留下三、五縷「周羅髮」（頂上所留的小髻髮），然後來到和尚面前長跪。和尚問道：「現在為你剃去頂上的頭髮，你同意嗎？」回答說：「好。」然後和尚為他披上袈裟。", "i": "u104-6", "n": 173, "s": "第7篇　十戒"}, {"v": "卷上", "o": "當正著袈裟時，《善見論》說偈云：「大哉解脫服，無相福田衣，披奉如戒行，廣度諸眾生。」", "t": "正當披上袈裟的時候，《善見論》說要誦偈：「偉大啊，這解脫之服！是無相的福田衣；披戴奉持、依戒而行，廣度一切眾生。」", "i": "u104-7", "n": 174, "s": "第7篇　十戒"}, {"v": "卷上", "o": "《度人經》云：「禮佛訖，行道三帀，誦自慶偈云：『遇哉值佛者，何人誰不喜，福願與時會，我今獲法利。』又禮大眾及二師己在下行坐，受六親拜賀，出家離俗竟，心懷歡喜，父母諸親皆為作禮，悅其道意。」", "t": "《度人經》說：禮佛完畢，繞行三匝，誦自我慶幸的偈：「有幸啊，能值遇佛陀的人！有誰不歡喜呢？福德與誓願在此時會遇，我如今獲得了法的利益。」又禮拜大眾及兩位師父之後，自己在下行末位坐下，接受六親眷屬的禮拜祝賀。出家離俗既已完成，心中滿懷歡喜；父母和諸位親眷都向他行禮，隨喜他向道的心意。", "i": "u104-8", "n": 175, "s": "第7篇　十戒"}, {"v": "卷上", "o": "應中前剃髮最好。《母論》云：「髮剃、著袈裟已，然後受三歸、五戒等。", "t": "剃髮應當在正午之前進行最好。《毘尼母論》說：剃了髮、披上袈裟之後，然後才受三歸、五戒等。", "i": "u104-9", "n": 176, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第三受戒者，先集僧已，受戒人著見處離聞已，作法同單白，令僧知其得法，問僧云。", "t": "第三是受戒。先把僧眾集合起來，將受戒人安置在僧眾看得見她、她卻聽不到作法聲音的地方，然後作「法同單白」羯磨，讓僧眾都知道她領受出家之法。接著問僧眾說：", "i": "u105", "n": 177, "s": "第7篇　十戒"}, {"v": "卷上", "o": "僧今和合，何所作為？」答：「作法同單白羯磨。", "t": "「僧眾現在和合集會，要作什麼事？」回答：「作『法同單白羯磨』」，即宣告令她成為法同沙彌尼的單白。", "i": "u106", "n": 178, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉僧聽！是某甲從比丘尼某甲出家。若僧時到，僧忍聽，某甲從比丘尼某甲出家。白如是。", "t": "各位大姊僧眾請聽：這位某甲，要跟從比丘尼某甲出家。如果僧眾認為時機已到，就請僧眾聽許認可：某甲跟從比丘尼某甲出家。我的稟白就是這樣。", "i": "u107", "n": 179, "s": "第7篇　十戒"}, {"v": "卷上", "o": "五分》、《十誦》先受五戒，然後受十戒。《善見》云：「當令禮僧足，往阿闍棃所，禮已長跪合掌，教云：『汝當隨我語，授汝三歸。』答云：『爾。』」\n義云：文中不言在僧前受，計理別處為受應得；然欲生行者善心，當對僧受最好，亦須問其遮難，以有難者不得受戒，問難之緣，大同下〈具戒〉中說。", "t": "《五分律》和《十誦律》都說，要先受五戒，然後才受十戒。《善見論》說：應當叫她禮拜僧眾的足，然後到阿闍梨那裡；禮拜完了，長跪合掌，阿闍梨教導她說：「你應當跟著我的話說，我傳授你三歸依。」她回答說：「是。」就義理推論說：論文並沒有說一定要在僧眾面前受，按理推究，在別的地方為她傳授，應該也是可以得戒的；然而為了引發修行人的善心，還是對著僧眾受最好。也必須問她有沒有遮難，因為有難的人不得受戒。問難的種種情形，大致與下面具足戒中所說的相同。", "i": "u108", "n": 180, "s": "第7篇　十戒"}, {"v": "卷上", "o": "我某甲，歸依佛，歸依法，歸依僧，我今隨佛出家，某甲為和尚，如來、至真、等正覺是我世尊。", "t": "「我某甲，歸依佛、歸依法、歸依僧。我現在跟隨佛陀出家，以某甲為和尚尼。如來、至真、等正覺，是我的世尊。」", "i": "u109", "n": 181, "s": "第7篇　十戒"}, {"v": "卷上", "o": "我某甲，歸依佛竟，歸依法竟，歸依僧竟，我今隨佛出家已，某甲為和尚，如來、至真、等正覺是我世尊。", "t": "「我某甲，歸依佛已完成，歸依法已完成，歸依僧已完成。我如今已跟隨佛陀出家，以某甲為和尚尼。如來、至真、等正覺，是我的世尊。」", "i": "u110", "n": 182, "s": "第7篇　十戒"}, {"v": "卷上", "o": "既受戒已，應為說戒相。", "t": "受戒完畢之後，就應當為她宣說戒相。", "i": "u111", "n": 183, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不殺生，是沙彌尼戒，能持否。", "t": "盡此一生都不殺害眾生，這是沙彌尼戒，妳能受持嗎？", "i": "u112", "n": 184, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不偷盜，是沙彌尼戒，能持否。", "t": "盡此一生都不偷盜，這是沙彌尼戒，妳能持守嗎？", "i": "u113", "n": 185, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不淫，是沙彌尼戒，能持否。", "t": "終此一生都不行淫欲，這是沙彌尼戒，妳能持守嗎？", "i": "u114", "n": 186, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不妄語，是沙彌尼戒，能持否。", "t": "盡此一生都不說虛妄不實的話，這是沙彌尼戒，妳能持守嗎？", "i": "u115", "n": 187, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不飲酒，是沙彌尼戒，能持否。", "t": "盡此一生都不飲酒，這是沙彌尼戒，妳能受持嗎？", "i": "u116", "n": 188, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不著華鬘、香油塗身，是沙彌尼戒，能持否。", "t": "盡此一生，都不佩戴花鬘、不以香油塗抹身體，這是沙彌尼戒，妳能受持嗎？", "i": "u117", "n": 189, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不歌舞倡伎、故往觀聽，是沙彌尼戒，能持否。", "t": "盡此一生，都不唱歌、跳舞、演奏伎樂，也不特意前往觀看、聆聽這類歌舞表演，這是沙彌尼戒，妳能持守嗎？", "i": "u118", "n": 190, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不高廣大牀上坐，是沙彌尼戒，能持否。", "t": "盡此一生，都不在高、寬、大的床座上坐，這是沙彌尼戒，妳能持守嗎？", "i": "u119", "n": 191, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不非時食，是沙彌尼戒，能持否。", "t": "終此一生都不非時食，也就是從日中之後直到次日天亮之前都不進食，這是沙彌尼戒，妳能受持嗎？", "i": "u120", "n": 192, "s": "第7篇　十戒"}, {"v": "卷上", "o": "盡形壽不捉生像金銀寶物，是沙彌尼戒，能持否。", "t": "盡此一生都不拿取金銀等珍寶財物，這是沙彌尼戒，妳能受持嗎？", "i": "u121", "n": 193, "s": "第7篇　十戒"}, {"v": "卷上", "o": "告云。", "t": "戒師告訴她說：", "i": "u122", "n": 194, "s": "第7篇　十戒"}, {"v": "卷上", "o": "是沙彌尼十戒，盡形壽不得犯，能持否。", "t": "以上這十條就是沙彌尼的十戒，盡此一生都不可以違犯，妳能受持嗎？", "i": "u123", "n": 195, "s": "第7篇　十戒"}, {"v": "卷上", "o": "既知戒相已，應為說出家功德，高於須彌，深於巨海，傍若無邊，廣於虗空。又為說六念等法，大同僧尼，由制通沙彌尼；至第三念時云。", "t": "她既然已經了知戒相之後，就應當為她宣說出家的功德：比須彌山更高，比大海更深，橫向延展如同沒有邊際，比虛空還要廣大。又要為她宣說六念等法，內容大致與僧眾、尼眾相同，因為這項制法也通用於沙彌尼。說到第三念時，就這樣說：", "i": "u124", "n": 196, "s": "第7篇　十戒"}, {"v": "卷上", "o": "我今年若干歲，某年某月某日某時，受得沙彌尼十戒。", "t": "我今年若干歲；是在某年某月某日某時，領受了沙彌尼十戒的。", "i": "u125", "n": 197, "s": "第7篇　十戒"}, {"v": "卷上", "o": "此律：「當以生年為次第，若生年等者，應以出家年為次第。」二俱須知，餘所未知，當問和尚、闍梨。", "t": "本部《四分律》規定：沙彌尼應當依出生的年歲來排定長幼次第；如果出生年歲相同，就應依出家的年資來排定次第。出生年歲與出家年資這兩項，自己都必須清楚知道。其餘還不明白的事，應當去請問和尚尼與阿闍梨尼。", "i": "u126", "n": 198, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第四受衣盋者，由隨道要務，竝加持故，法衣被身，以遮外也；應器資食，以充內也。內外不持，皆結其犯。\n《僧祇》：「五眾衣盋恒常隨身，違者出界結罪。」\n《婆論》云：「沙彌尼受十戒已，應具上下二衣：一當鬱多羅僧，二當安陀會。手執上衣，隨對一大尼、式叉、沙彌尼前皆得。」說云。", "t": "第四、受衣缽：這是因為衣缽是隨順修道的緊要資具，全都必須作法受持。法衣披在身上，用以遮護於外；缽盛受飲食，用以充實於內。內外二物若不作法受持，都各會結成犯戒之罪。《僧祇律》說：五類出家人的衣缽必須恒常隨身，違反的人一出界外便結罪。《婆論》說：沙彌尼受了十戒之後，應當備齊上、下二衣：一件充當鬱多羅僧，一件充當安陀會。手裡拿著上衣，隨意面對一位比丘尼、式叉摩那或沙彌尼，在她面前都可以宣說：", "i": "u127", "n": 199, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！我沙彌尼某甲，此縵鬱多羅僧應量作，今受持。", "t": "大姊，請專心繫念聽我說：我沙彌尼某甲，這件不割截成田相條葉的縵鬱多羅僧上衣，是依照規定的尺寸裁製的，我現在受持它。", "i": "u128", "n": 200, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！我沙彌尼某甲，此縵鬱多羅僧，先受持，今捨。」\n受盋云。", "t": "「大姊請專心憶念：我沙彌尼某甲，這件縵鬱多羅僧，先前已受持，現在捨去。」接著受持缽時說：", "i": "u129", "n": 201, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！我沙彌尼某甲，此盋多羅應量器，今受持。", "t": "「大姊，請一心專注聽我陳說：我沙彌尼某甲，這只鉢多羅，也就是應量器，我現在受持它。」", "i": "u130", "n": 202, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第五說淨者，若得長衣、盋、藥，竝同下尼法，唯改罪名為別，竝號吉羅。", "t": "第五是說淨：如果得到長衣、長缽、長藥，作法都與下文比丘尼的說淨法相同，只是把其中的罪名加以改換，以示區別，一律稱作突吉羅。", "i": "u131", "n": 203, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第六明捨墮，通界內外得，以無別眾過；若犯五篇，同名吉羅；初篇四重，應當滅𢷤，自下四篇，懺淨依本。", "t": "第六，說明捨墮，即尼薩耆波逸提罪的捨財懺悔法：不論在界內或界外都可以作法，因為沙彌尼不入僧數，沒有別眾的過失。沙彌尼若犯了五篇中的罪，一律名為突吉羅。其中初篇的四條重罪，應當滅擯，逐出僧團；初篇以下的四篇罪，則依本法懺悔清淨。", "i": "u132", "n": 204, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第七說戒者，通別有二：通如尼說；別則不同，沙彌尼等半月亦合別集一處說戒，為末世行希，故略而不述，若具說者，反成蚩弄，徒盈卷軸，儻有不羣，冀詳鈔也。\n《愛道尼經》云：「應為沙彌尼等說五德、十數，名福田，為良為美，依之得福，盡可成佛。云何為五？一者、發心離俗，懷佩道故；二者、毀其形好，應法服故；三者、委棄身命，導崇道故；四者、永割親愛，無適莫故；五者、志求大乘，為度人故。」爾時世尊為說偈言：「毀形守志節，割愛無所親，棄家弘聖道，願度一切人；五德超世務，名曰最福田，供養獲永安，其福第一尊。」\n《僧祇》十數云：「一者、一切眾生皆依食故，二者、名色，三者、痛痒想，四者、四諦，五者、五陰，六者、六入，七者、七覺意，八者、八正道，九者、九眾生居，十者、十一切入。」\n式叉尼對首說戒：「大姉一心念！十方眾僧說戒日，式叉摩那某甲清淨。", "t": "第七、說戒。這有「通」與「別」兩種情形：共通的部分，如比丘尼說戒法中所說；別異的部分則與大尼不同——沙彌尼等人每半月也應當另外聚集在一處說戒。只因末世能如此實行的人稀少，所以這裡省略而不加敘述；若全部詳說，反而成為被人譏笑的話柄，白白填滿篇幅。倘若有不隨流俗的出眾之人，希望他詳查鈔文。\n《愛道尼經》說：應當為沙彌尼等人宣說五德與十數。這樣的人名為福田，是良善、是美好；依止他們便能獲得福報，究竟都能成佛。\n什麼是五德呢？第一、發心捨離世俗，因為心中懷藏佩持著道的緣故；第二、毀壞形貌的相好，因為要與法服相應的緣故；第三、委棄身命，因為趣向尊崇於道的緣故；第四、永遠割捨親愛之情，沒有偏親偏疏的緣故；第五、立志追求大乘，為了度脫眾人的緣故。\n那時世尊為他們說偈：毀壞形貌的相好而守持志向節操，割捨親愛而無所偏親，捨離家庭而弘揚聖道，發願度脫一切人。具足這五德而超越世俗事務，便名為最上的福田；供養這樣的人能獲得永遠的安樂，其福德最為第一尊貴。\n《僧祇律》所說的十數是：第一、一切眾生都依飲食而存活；第二、名色；第三、痛痒想，即苦、樂、捨三種受；第四、四諦；第五、五陰；第六、六入；第七、七覺意；第八、八正道；第九、九眾生居；第十、十一切入。\n式叉摩那尼以對首法向一位大尼說戒：「大姊，請專心憶念：今天是十方眾僧說戒的日子，我式叉摩那某甲清淨。」", "i": "u133", "n": 205, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第八安居者，《十誦》制五眾安居、受日；此律〈遊行戒〉中，三眾竝結有罪。", "t": "第八，安居。《十誦律》規定五眾都須安居，並都有受日之法，即安居中因事出界時作法請假；《四分律》則在禁止遊行的戒條中，對式叉摩那、沙彌、沙彌尼這下三眾也都結判突吉羅罪。", "i": "u134", "n": 206, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第九受日者，準尼七日法說；不爾，直白當眾大尼、式叉尼、沙彌等，出界亦得。", "t": "第九是受日，即安居中請假出界之法：依準比丘尼的七日法，照那樣的詞句陳說作法；若不這樣作法，就直接向現前大眾中的大比丘尼、乃至式叉摩那尼、沙彌等稟白，如此告白後出界也獲開許。", "i": "u135", "n": 207, "s": "第7篇　十戒"}, {"v": "卷上", "o": "第十自恣者，通行尼自恣已，五德尼喚式叉尼、沙彌尼來入僧中，五德尼對前受自恣。", "t": "第十是自恣：通用的做法是，比丘尼眾自恣完畢之後，由具足受自恣五德的比丘尼呼喚式叉摩那尼和沙彌尼進入僧眾當中，這位五德尼當著她們的面接受她們的自恣。", "i": "u136", "n": 208, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！今眾僧自恣日，我式叉摩那亦自恣，若有見、聞、疑罪，大姉長老哀愍故語我，我若見罪，當如法懺悔。", "t": "大姊請一心繫念：今天是眾僧自恣的日子，我式叉摩那也自恣。如果您看見、聽說或懷疑我有罪過，請大姊長老慈悲哀愍，告訴我；我若見到自己的罪過，應當如法懺悔。", "i": "u137", "n": 209, "s": "第7篇　十戒"}, {"v": "卷上", "o": "若別自恣，則不須此，對首自恣云。", "t": "如果式叉摩那、沙彌尼不隨大僧眾，而是各別自行作自恣，就不必用上面那段文句，改用對首（面對一位大尼）自恣的方式說：", "i": "u138", "n": 210, "s": "第7篇　十戒"}, {"v": "卷上", "o": "大姉一心念！今是眾僧自恣日，我式叉摩那尼某甲清淨。", "t": "大姊請一心憶念：今天是眾僧自恣的日子，我式叉摩那尼某甲清淨。", "i": "u139", "n": 211, "s": "第7篇　十戒"}, {"v": "卷上", "o": "沙彌尼類說可知。不清淨者，發露懺已自恣。\n《母論》云：「沙彌等常逐二師讀誦經，一切僧中所有作者，皆不得違。」\n《婆論》云：「沙彌尼等不為三寶利益緣掘地者，犯罪；此律〈大尼戒〉後，結突吉羅。」\n《五分》云：「若罰沙彌尼，先語其師，師亦不應作非法助沙彌尼。若治罰，應作種種苦使：掃地、除糞、摙石、治階道等。若不為和尚、阿闍棃及餘人作使，應語如法供給和尚、眾僧作使，次第應作。不應遮不與僧中利養，此是施主物，應與。」\n此律：「次第與房舍、臥具，若不愛護，不應與；若利養，隨次與。」\n自餘法用，具如五部律、《三千威儀》說，但不得說罪體輕重。師僧指事教持，不犯；師僧不教，竝結有罪；不取師語，亦結有犯。", "t": "沙彌尼的自恣說法，照上面的文句類推就可以明白。若是有罪而不清淨的，須先發露懺悔，然後才自恣。\n《毘尼母論》說：沙彌等應常跟隨和尚、阿闍梨二師讀誦經法，僧中一切所應作的事，都不得違背。《薩婆多論》說：沙彌尼等若不是為了對三寶有利益的因緣而掘地，就犯罪。本律則在比丘尼掘地戒之後的結罪文中，對她們結突吉羅罪。\n《五分律》說：若要處罰沙彌尼，應先告知她的師父；師父也不可用不如法的方式袒護沙彌尼。若要治罰，應派她做種種苦役：掃地、清除糞穢、搬運石頭、修治臺階道路等。若她不肯為和尚、阿闍梨及其他人服役，就應告訴她：「要如法供給和尚與眾僧，輪到的差使應按次第去做。」不應遮止而不給她們僧中的利養，因為這是施主布施之物，應當給與。\n本律說：按次第分給房舍臥具，若她不知愛惜愛護，就不應給；至於利養，也隨僧次分給。其餘的行法事用，詳如五部律與《三千威儀》所說。\n只是不得為她們宣說罪體的輕重；師長僧眾就具體事相指點、教導她們守持，這樣就不算違犯。師僧若不教導，都同樣結罪；沙彌尼不聽從師長的話，也結有犯。", "i": "u140", "n": 212, "s": "第7篇　十戒"}, {"v": "卷上", "o": "○學戒篇第八", "t": "第八篇　學戒。", "i": "u141", "n": 213, "s": "第8篇　學戒"}, {"v": "卷上", "o": "此篇大門有五：一、翻名，二、乞戒，三、秉法，四、六法，五、行法。", "t": "這一篇的大綱共分五門：一是翻名，二是乞戒，三是秉法，四是六法，五是行法。", "i": "u142", "n": 214, "s": "第8篇　學戒"}, {"v": "卷上", "o": "第一翻名者，式叉義翻為學，摩那為法，故名為學法尼也。", "t": "第一項是翻譯名稱：「式叉」依義譯為「學」，「摩那」譯為「法」，所以稱為「學法尼」。", "i": "u143", "n": 215, "s": "第8篇　學戒"}, {"v": "卷上", "o": "第二乞戒者，此律云：聽十八童女二歲學戒，當如是與：沙彌尼應詣僧中，具修威儀，作如是乞云。", "t": "第二是乞戒。本律說：聽許十八歲的童女用兩年時間學戒，應當依這樣的方式授予。沙彌尼應前往尼僧眾中，具足修持威儀，作這樣的乞求說：", "i": "u144", "n": 216, "s": "第8篇　學戒"}, {"v": "卷上", "o": "大姉僧聽！我沙彌尼某甲，今從眾僧乞二歲學戒，和尚尼某甲。願僧與我二歲學戒，和尚尼某甲，慈愍故。", "t": "各位大姊，請僧眾聽我說：我沙彌尼某甲，現在向僧眾乞求兩年的學戒，以某甲比丘尼為和尚尼。願僧眾慈悲憐愍我，賜給我兩年的學戒，以某甲比丘尼為和尚尼。", "i": "u145", "n": 217, "s": "第8篇　學戒"}, {"v": "卷上", "o": "第三秉法者，沙彌尼應離聞著見處已，尼眾中當作羯磨和僧云。", "t": "第三、秉行羯磨法：沙彌尼應離開聽得見作法音聲的聞處，站到尼眾看得見她的見處之後，尼眾當中應作羯磨，先向僧眾問和說：", "i": "u146", "n": 218, "s": "第8篇　學戒"}, {"v": "卷上", "o": "僧今和合，何所作為？」答云：「受二歲學戒羯磨。", "t": "問：「僧眾現在已經和合集會，是要做什麼事？」答：「是授與二歲學戒的羯磨。」", "i": "u147", "n": 219, "s": "第8篇　學戒"}, {"v": "卷上", "o": "大姉僧聽！彼沙彌尼某甲，今從眾僧乞二歲學戒，和尚尼某甲。若僧時到，僧忍聽，與沙彌尼某甲二歲學戒，和尚尼某甲。白如是。", "t": "諸位大姊，僧團請聽：那位沙彌尼某甲，現在向僧眾乞求授予兩年的學戒，和尚尼是某甲。如果僧團認為時機已到，請僧團忍可聽許：僧團授予沙彌尼某甲兩年學戒，和尚尼是某甲。以上如此宣告。", "i": "u148", "n": 220, "s": "第8篇　學戒"}, {"v": "卷上", "o": "大姉僧聽！彼沙彌尼某甲，今從眾僧乞二歲學戒，和尚尼某甲。僧今與沙彌尼某甲二歲學戒，和尚尼某甲。誰諸大姉忍僧與沙彌尼某甲二歲學戒、和尚尼某甲者，默然；誰不忍者，說。", "t": "諸位大姊，請僧眾聽著：那位沙彌尼某甲，現在向僧眾乞求兩年的學戒，她的和尚尼是某甲。僧眾現在要授予沙彌尼某甲兩年的學戒，和尚尼是某甲。諸位大姊當中，凡是認可僧眾授予沙彌尼某甲兩年學戒、和尚尼為某甲的，就保持沉默；不認可的，請說出來。", "i": "u149", "n": 221, "s": "第8篇　學戒"}, {"v": "卷上", "o": "僧已忍，與沙彌尼某甲二歲學戒竟，和尚尼某甲。僧忍默然故，是事如是持。", "t": "僧眾已經認可，授予沙彌尼某甲兩年學戒法已經完成，和尚尼是某甲。由於僧眾認可而保持靜默的緣故，這件事就這樣成立，應當如此奉行。", "i": "u150", "n": 222, "s": "第8篇　學戒"}, {"v": "卷上", "o": "第四六法者，此律云：次當喚來入眾，為說六法名字：「某甲諦聽！如來、無所著、等正覺說六法，不得犯。", "t": "第四，宣說六法。《四分律》說：接著應當把她喚進僧眾當中，為她宣說六法的名目：「某甲，專心聽著！如來、無所著、等正覺宣說了六法，妳不得違犯。」", "i": "u151", "n": 223, "s": "第8篇　學戒"}, {"v": "卷上", "o": "一、不得淫欲法。若式叉摩那行淫欲法，非式叉摩那，非釋種女；若與染心男子身相觸，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第一，不得行淫欲之法。如果式叉摩那行了淫欲之法，就不再是式叉摩那，也不再是釋迦種姓的女弟子；如果與心懷淫欲的男子身體相接觸，戒行就有了虧缺，應當重新為她授戒。你在這當中，盡此一生都不得違犯，能受持嗎？", "i": "u152", "n": 224, "s": "第8篇　學戒"}, {"v": "卷上", "o": "二、不得偷盜，乃至艸葉。若式叉摩那取人五錢、若過五錢，若自取、教人取，若自斫、若教人斫，若埋壞色，非式叉摩那，非釋種女；若取減五錢，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第二、不得偷盜，乃至一根草、一片葉也不得偷取。如果式叉摩那拿取他人財物，價值五錢或超過五錢，不管是自己拿取或教人拿取、自己砍斫（如砍伐他人的樹木）或教人砍斫，或把他人財物埋藏起來、或改變它的顏色（使它失去原貌而據為己有），她就不再是式叉摩那，也不再是釋種女了。如果所取的不滿五錢，便是所受的戒有所虧缺，應當重新為她授與學戒。你在這當中，終此一生都不得違犯，能受持嗎？", "i": "u153", "n": 225, "s": "第8篇　學戒"}, {"v": "卷上", "o": "三、不得故斷人命，乃至蟻子。若式叉摩那故自手斷人命，求刀授與人，教死、讚死，若非藥、墮胎、厭禱呪術，自作、教人作，非式叉摩那，非釋種女；若斷畜生不能變化命者，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第三，不得故意斷人的性命，下至螞蟻也不可殺。如果式叉摩那故意親手斷人命；或為他人求取刀子而交給他，教唆他去死、讚歎死亡；或給與足以害命的毒藥等非藥之物，或使人墮胎，或以魘魅禱祠、咒術等邪法害人致死——無論是自己動手作，或是教別人去作，她就不再是式叉摩那，也不再是釋迦佛門下的女弟子。如果殺死不能變化形體的畜生，便是戒有虧缺，應當重新為她授與六法之戒。你在這一條當中，盡此一生都不得違犯，你能受持嗎？", "i": "u154", "n": 226, "s": "第8篇　學戒"}, {"v": "卷上", "o": "四、不得妄語，乃至戲笑。若式叉摩那不真實、非己有，自稱言『我得上人法，得禪、解脫、得三昧、正受，得須陀洹果乃至阿羅漢果』，言『天來、龍來、鬼來供養我』，非式叉摩那，非釋種女；若於眾中故作妄語，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第四、不得妄語，乃至開玩笑也不可以。如果式叉摩那所說不真實、並非自己實際證得，卻自稱說：「我證得上人法，證得禪定、解脫，證得三昧、正受，證得須陀洹果乃至阿羅漢果」，或說「天來、龍來、鬼來供養我」——這樣她就不再是式叉摩那，也不再是釋種女。若在大眾之中故意說妄語，便是戒有虧缺，應當重新為她授戒。妳在此戒之中，盡此一生都不得違犯，能受持嗎？", "i": "u155", "n": 227, "s": "第8篇　學戒"}, {"v": "卷上", "o": "五、不得非時食。若式叉摩那非時食，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第五、不得非時食。如果式叉摩那在非時進食，便是缺戒，應當重新為她授戒。你在這條戒上，盡此一生都不得違犯，能受持嗎？", "i": "u156", "n": 228, "s": "第8篇　學戒"}, {"v": "卷上", "o": "六、不得飲酒。若式叉摩那飲酒，缺戒，應更與戒。汝是中盡形壽不得犯，能持否。", "t": "第六、不得飲酒。如果式叉摩那飲了酒，所受的戒法便有缺損，應當重新為她授戒。你在這當中，盡此一生都不得違犯，能受持嗎？", "i": "u157", "n": 229, "s": "第8篇　學戒"}, {"v": "卷上", "o": "第五行法者，式叉摩那具學三法：一、學根本，謂前四重是；二、學法，謂染心男子相觸、盜人四錢、斷畜生命、小妄語、非時食、飲酒，此是六法體；三、學行法，謂一切大尼戒行，竝須具學。若於學法中犯者，更與二年羯磨；犯根本，滅擯；犯餘行，但名缺行，於教不制，直令改悔。若滿二年已，犯學法者，更與二年。此律：式叉摩那，一切大尼戒法應學，除自手取食；無沙彌尼者不犯，得授食與他。\n《僧祇》云：式叉尼應學十八法：一、在大尼下，沙彌上坐。二、式叉尼不淨食，大尼淨；大尼不淨食，式叉尼亦不淨。三、大尼得與式叉尼二宿；式叉尼得與沙彌尼二宿。四、式叉尼得與大尼授食，除火淨、五生種、取金銀；自從沙彌尼受食。五、大尼不得為說七聚罪名。六、得語云：「不淫、殺、妄語」，如是等憶持。七、式叉尼布薩日。八、至自恣日，入僧中長跪合掌云。", "t": "第五，行法。式叉摩那必須具足修學三種法：一是「學根本」，就是前面所說的四條重戒；二是「學法」，就是與有染心的男子身體相觸、盜取他人四錢、斷畜生的命、小妄語、非時食、飲酒，這六項就是六法之體；三是「學行法」，就是一切大尼的戒行都必須具足修學。\n若在學法之中有所違犯，就要重新為她作二年學戒的羯磨；若犯了根本重戒，就予以滅擯；若犯了其餘的行法，只叫作「缺行」，制教中並未制定重與二年學戒的處分，只令她改悔即可。若已滿二年之後才違犯學法，也要再給她二年。\n《四分律》說：式叉摩那對一切比丘尼的戒法都應當學，只有自己親手拿取食物一項除外；若沒有沙彌尼為她授食，她自手取食就不算犯；她也可以把食物授給他人。\n《僧祇律》說：式叉尼應學十八法。第一，坐在大尼之下、沙彌之上。第二，式叉尼不淨的食物，對大尼而言是淨的；大尼不淨的食物，對式叉尼也是不淨。第三，大尼可以與式叉尼同宿兩夜，式叉尼可以與沙彌尼同宿兩夜。第四，式叉尼可以把食物授給大尼，但作火淨、為五種生種作淨、取金銀這三件事除外（她不得作）；她自己則從沙彌尼那裡受食。第五，大尼不得為她宣說七聚罪的名稱。第六，可以告訴她說：「不淫、不殺、不妄語」，這些都要憶念受持。第七，是關於式叉尼在布薩日的作法。第八，到了自恣日，要進入僧眾中，長跪合掌這樣說：", "i": "u158", "n": 230, "s": "第8篇　學戒"}, {"v": "卷上", "o": "阿闍棃耶僧！我某甲清淨，僧憶持。", "t": "「諸位阿闍梨、僧眾！我某甲清淨，請僧眾憶念記持。」", "i": "u159", "n": 231, "s": "第8篇　學戒"}, {"v": "卷上", "o": "三說已而去。第九、第十、第十一、第十二，謂後四波羅夷，犯者更從始學。第十三，十七僧殘已下，若犯，一一作吉羅悔。餘如彼說。", "t": "式叉摩那把這番話說完三遍，就退下離去。第九、第十、第十一、第十二這四條，指的是比丘尼八條波羅夷中的後四條；犯了其中任何一條，就要從頭重新學起。第十三條：十七條僧殘戒以及更輕的以下諸戒，若犯了其中任何一條，就一一當作突吉羅罪來懺悔。其餘各條，都依照《僧祇律》所說。", "i": "u160", "n": 232, "s": "第8篇　學戒"}, {"v": "卷上", "o": "問：受法，為對面、遙授耶？答：諸部不同。今依《四分》，令此沙彌尼入眾，從僧三乞已，應往離聞處、著見處已，比丘尼為羯磨授。準此《四分》，遙者得。若依《十誦》，入眾對面為授。乃諸部不同，弗可互用，當部自行，不得捨此就彼。", "t": "問：受法時，是當面授與，還是遙距授與呢？\n答：各部律典規定不同。現今依據《四分律》，讓這名沙彌尼進入眾中，向僧眾三次乞求之後，應前往聽不見音聲、但仍在眼界所見之處，再由比丘尼為她作羯磨授法。準照《四分律》這項規定，遙距授法是可以成辦的。若是依據《十誦律》，則是讓她進入眾中當面為她授法。這是各部律制不同的地方，不可互相混用；應當依本部律制各自遵行，不得捨棄本部而遷就他部。", "i": "uGAP03-1", "n": 233, "s": "第8篇　學戒"}, {"v": "卷上", "o": "問：學戒不滿二年，得戒否？答：不得。何意得知？如持六法垂滿二年，隨缺一戒，更與二年，故知不得。又《僧祇》云：「若尼受學不滿與受具，得提。學戒要滿二歲。」《十誦》云：「六法者，練心地，試看大戒受緣；二年者，練身也，試知有胎無胎。」故臨受對眾問云：「二歲學六法否？」《五分》等羯磨文中，皆言「二歲學戒滿」。", "t": "問：學戒未滿二年，能得戒嗎？\n答：不能得戒。怎麼知道呢？例如受持六法快滿二年時，只要缺犯其中任何一戒，便須重新再給二年學戒，由此可知不能得戒。又《僧祇律》說：「若比丘尼為受學未滿二年者授具足戒，犯波逸提；學戒必須滿二歲。」《十誦律》說：「六法是用來磨練心地，試驗觀察受大戒的因緣；二年是用來考驗身體，試驗得知有胎無胎。」因此，臨到受戒時要對眾詢問：「二年間是否已修學六法？」《五分律》等各部律的羯磨文中，也都說「二歲學戒已滿」。", "i": "uGAP03-2", "n": 234, "s": "第8篇　學戒"}, {"v": "卷上", "o": "義云：今時多有無識之人，公然許他不滿，便與授具。若不滿得戒，何故《僧祇》、十、五律等皆結師罪，又《五分》等皆羯磨文中言滿？今時師眾，俱知不滿，輒違聖教，妄言道滿，便事不應法，法豈得成？若勒年滿，定知得戒；若凡情妄授，儻不得戒，豈非誤他一生虗過，罪資累劫？既非難逼，有何忽迫，強違聖意，抑令早受？或有妄引文解，言：「不受十戒，尚自得成；準此不滿二歲，何容不許？」今解不同：彼是開通，律有誠文；此是制法，聖教便禁。開制不同，何得相準？六法是制，不得不行；十戒開法，逆順無違。斯則開制矛盾，陞沈有隔，非直妄判之過，偏顯無知；亦乃冐授之失，殃及自他耳。", "t": "依義而論：現今常有無知之人，公然准許他人學戒未滿便為其授具足戒。如果未滿就能得戒，為什麼《僧祇律》及《十〔誦〕、五〔分〕律》等都判授戒師有罪呢？又《五分律》等都在羯磨文中明言已滿，現今的師長與大眾明明都知道未滿，卻擅自違背聖教，妄稱已滿，如此行事不合律法，羯磨法豈能成就？若嚴格要求年滿，定能確定得戒；若順從凡情妄行授戒，萬一不得戒，豈不是耽誤他人一生虛度，自己也招致累劫的罪報？既然不是遭遇災難逼迫，有什麼急迫之處，竟要勉強違背聖意，硬要讓她提早受戒呢？還有人妄加援引律文來解釋，說：「未受十戒，尚且得以成戒；比照這一點，學戒不滿二歲，怎麼反倒不准許？」如今的解釋與此不同：前者屬於開緣通融，律典中有明確的條文；後者屬於制法，聖教明令禁止。開緣與遮制性質不同，怎能互相援引比照？六法是制法，不能不遵行；十戒屬於開法，無論順受與否都不相違。如此將開緣與遮制弄得自相矛盾，得戒與否更有升沉之隔；這不只是妄自判定的過失格外顯出無知，更是冒濫授戒的罪失，禍殃將波及自己與他人啊！", "i": "uGAP03-3", "n": 235, "s": "第8篇　學戒"}, {"v": "卷上", "o": "此律云：不知得戒相，造非法，與學制法；若已曾嫁者，年十歲已上，與二歲學，不須十八也。", "t": "本律（《四分律》）說：由於不知得戒之相，造作非法之事，因此為她們授與學法、制定此法；若是已經出嫁的女子，年滿十歲以上，就授與二年學法，不必等到十八歲。", "i": "uGAP03-4", "n": 236, "s": "第8篇　學戒"}, {"v": "卷上", "o": "問：何意小年曾嫁，便與六法耶？答：《婆論》云：「年十二者，得受具戒，為夫家所使，經忍眾苦，加厭本事，意志成就。」《僧祇》亦然。", "t": "問：為什麼年紀雖小但曾經出嫁，便授與六法呢？\n答：《婆論》說：「年滿十二歲者，可以受具足戒；因為她曾受夫家役使，歷經並忍受種種苦楚，加上厭離世俗居家之事，心志已經成熟。」《僧祇律》也是這樣說。", "i": "uGAP03-5", "n": 237, "s": "第8篇　學戒"}, {"v": "卷上", "o": "義云：式叉尼不得與大尼為伴，以戒未滿故；自不得與沙彌為伴，以非同類故。若一大尼兼一式叉尼，若二式叉尼兼一沙彌尼，得共為伴，餘人不合。", "t": "依義而論：式叉尼不得與大尼作伴，因為她學戒尚未滿二年的緣故；也不得與沙彌〔尼〕作伴，因為不是同類的緣故。若是一位大尼加上一位式叉尼，或是二位式叉尼加上一位沙彌尼，就可以共同作伴；其餘的人都不合規定。", "i": "uGAP03-6", "n": 238, "s": "第8篇　學戒"}, {"v": "卷上", "o": "沙彌尼雜戒文》云：不得共優婆夷相看形體大笑，又不得僻處倮形自弄身體，亦不得照鏡、摩面、畫眉。受經時，當與長老尼共行，去座六尺長跪；問義時，當識句逗。師若訶責，即自悔過，不得覆藏，不得自理，不得惡眼視師等。", "t": "《沙彌尼雜戒文》說：「不得與優婆夷互相觀看形體而大笑；又不得在偏僻處裸露身體、自行撫弄身體；也不得照鏡、摩拭臉面、畫眉。領受經教時，應當與長老尼同行，距離座位六尺而長跪；請問經義時，應當辨識句讀。師長若加訶責，便應立即自行悔過，不得隱瞞覆藏，不得為自己辯理，也不得用惡狠的眼神瞪視師長等。」", "i": "uGAP03-7", "n": 239, "s": "第8篇　學戒"}, {"v": "卷上", "o": "○畜眾篇第九", "t": "○畜眾篇第九", "i": "u161", "n": 240, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "此篇大門有二：一、畜意，二、制乞。", "t": "本篇大分為兩門：一是「畜意」，說明畜養徒眾的意旨；二是「制乞」，制定必須向僧眾乞求聽許的作法。", "i": "u162", "n": 241, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "第一畜意者，此律云：尼十二歲，欲度人受具足戒者，應白二羯磨，請僧聽許已，然後得度，否者犯提。若受他依止、式叉尼等，犯吉羅。若和尚尼無德，僧止其度人，捨畜眾羯磨。若得羯磨已，一年中得一大尼、一六法尼、一沙彌尼、一依止人，更不得多；隔一年已，更欲度者，還如前法，與衣食及法，更不須重與羯磨。", "t": "第一門是說明畜養徒眾的意旨。《四分律》說：比丘尼受具足戒已滿十二年，想要度人、為人授具足戒的，應當先向僧眾乞求，由僧眾作白二羯磨聽許，得到允許之後才可以度人；若不先乞得許可就度人受具，便犯波逸提。至於未經許可而接受他人前來依止，或度式叉摩那尼等，則犯突吉羅。倘若和尚尼沒有德行，僧眾便制止她度人，為她作捨畜眾羯磨。已經得到羯磨許可之後，一年之中只能度一位比丘尼、一位學六法的式叉摩那尼、一位沙彌尼，以及接受一位依止人，不得超過這個數目。間隔一年之後，若還想再度人，仍照前面的做法供給衣服、飲食並教授法義，不必再重新作羯磨。", "i": "u163", "n": 242, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "第二制乞者，其度沙彌尼、式叉尼、大尼戒，竝須乞，以年年度弟子犯罪故，捨畜眾法等。乞：比丘尼度尼，應具修威儀，禮僧足，長跪合掌乞云。", "t": "第二、制定乞求聽許之法：無論度沙彌尼、度式叉尼，或授大尼具足戒，都必須向尼僧乞求聽許。這是因為未乞聽許而年年剃度弟子便會犯罪，以及先前所得的畜眾法可能已經捨失等緣故。乞求之法：比丘尼要度尼時，應當整飭威儀，頂禮尼僧足，長跪合掌，這樣乞求說：", "i": "u164", "n": 243, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "大姉僧聽！我比丘尼某甲，今求眾僧，乞度人受具足戒。願僧聽我度人受具足戒，慈愍故。", "t": "諸位大姊僧眾，請聽我說：我比丘尼某甲，現在向僧眾乞求准許我剃度弟子、讓他們受具足戒。願僧眾慈悲憐愍，允許我剃度弟子受具足戒。", "i": "u165", "n": 244, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "僧作法時，問：「僧今和合，何所作為？」答云：「與畜眾羯磨。", "t": "僧團舉行正式作法時，先問：「僧眾如今已和合集會，要進行什麼事？」回答說：「授予她畜眾羯磨。」", "i": "u166", "n": 245, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "大姉僧聽！此比丘尼某甲，今從眾僧，乞授人具足戒。若僧時到，僧忍聽，僧今與比丘尼某甲，授人具足戒。白如是。", "t": "各位大姊，請僧眾聽：這位比丘尼某甲，現在向僧眾乞求准許她為人傳授具足戒。如果僧眾認為時機已到，請僧眾認可聽許：僧眾現在就准許比丘尼某甲為人傳授具足戒。以上便是這樣禀白。", "i": "u167", "n": 246, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "大姉僧聽！此比丘尼某甲，今從眾僧，乞授人具足戒。僧今與比丘尼某甲，授人具足戒。誰諸大姉忍僧與比丘尼某甲授人具足戒者，默然；誰不忍者，說。僧已忍，與比丘尼某甲授人具足戒竟。僧忍默然故，是事如是持。", "t": "諸位大姊，請僧眾垂聽：這位比丘尼某甲，如今向眾僧乞求准許她為他人授具足戒。僧眾現在就給予比丘尼某甲為他人授具足戒的許可。諸位大姊當中，凡是認可僧眾給予比丘尼某甲為他人授具足戒的，請保持默然；不認可的，請開口說出來。僧眾已經認可給予比丘尼某甲為他人授具足戒的許可，作法至此完畢。由於僧眾以默然表示認可的緣故，這件事就這樣確定，應當如此受持。", "i": "u168", "n": 247, "s": "第9篇　畜眾"}, {"v": "卷上", "o": "○具戒篇第十", "t": "第十篇：具足戒。", "i": "u169", "n": 248, "s": "第10篇　具戒"}, {"v": "卷上", "o": "此篇大門有五：一、由藉，二、本法，三、至僧，四、戒相，五、退捨。", "t": "這一篇的大綱分為五門：第一是「由藉」，即受戒所依憑的前提；第二是「本法」，即先在尼僧中受本法的作法；第三是「至僧」，即前往比丘大僧之中正受具足戒；第四是「戒相」，即所受戒的相狀；第五是「退捨」，即退失與捨戒。", "i": "u170", "n": 249, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第一由藉者，義云：若欲受具，先受十戒、六法，然後受具。故律云：「若不受十戒，得戒，而眾僧得罪。」故《十誦》云：「若未度出家，便與受大戒，得戒不？」佛答言：「得戒，而眾僧得罪。」《婆論》云：「所以佛制受十戒者，為染習佛法故。」六法制意如別。", "t": "第一是「由藉」，即受具足戒的前置憑藉。依義理說：若想受具足戒，必須先受十戒與六法，然後才受具足戒。所以《四分律》說：沒有先受十戒就受具足戒，受戒的人仍然得戒，但僧眾卻結罪。因此《十誦律》記載：問：還沒有度他出家，就直接為他授大戒，這樣能得戒嗎？佛答：能得戒，但僧眾結罪。《婆論》說：佛之所以制定要先受十戒，是為了讓受戒的人先熏染、修習佛法。至於制定六法的用意，如別處所說。", "i": "u171", "n": 250, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第二本法者，此有十種：一、請師，二、戒緣，三、安置，四、白差，五、出問，六、白喚，七、乞戒，八、白和，九、問難，十、正受。", "t": "第二是本法。這一部分共有十項：一是請師；二是戒緣；三是安置；四是白差；五是出問；六是白喚；七是乞戒；八是白和；九是問難；十是正受。", "i": "u172", "n": 251, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第一請師者，若欲受具，三師、七證要請方得。故《佛阿毗曇》中，二阿闍棃竝有請文，七證義況。先明請和尚法。所以須請者，以和尚得戒根本，若無此人，闕於教授，進道莫由，理必須請。《見論》云：以不請故，多造非法，師訶責之，反云：「誰請大德為我和尚？」佛因制之：若不請，不得與受。此律請師，不云僧屏，計此三師得戒根本，預前三兩月請，何傷大理？今時多在眾中請者，此依《十誦》、《僧祇》也。當具威儀，至和尚前長跪住。阿闍棃教云：「所以須請者，此師是發戒根本，若不請者，無由得戒，汝當段重心請。計此請文，出自汝口，由汝不解，故我教汝，當一心承我教。」答言：「爾。", "t": "第一是請師。想要受具足戒，三師與七位尊證師都必須經過啟請才行。所以《佛阿毗曇經》中，兩位阿闍梨都有啟請的文句；至於七位尊證師，依義理比況類推，也同樣應當啟請。\n先說明請和尚的方法。之所以必須啟請，是因為和尚是得戒的根本；若沒有這個人，就缺少了教導，要進修道業也無從依循，按理必須啟請。《善見論》說：由於沒有啟請的緣故，弟子多造非法之事，師父訶責他時，他反而說：「誰請大德作我的和尚了？」佛陀因此制定：若不啟請，就不得為他授戒。\n《四分律》說到請師，並沒有指明是在僧眾中或屏處私下啟請。考量這三師是得戒的根本，提前三、兩個月去啟請，對大體義理又有什麼妨礙呢？現今大多在僧眾當中啟請，這是依《十誦律》與《僧祇律》的做法。\n應當整肅威儀，走到和尚面前，長跪而住。阿闍梨教導她說：「之所以必須啟請，是因為這位師父是引發你得戒的根本，若不啟請，就無從得戒，你應當以至誠鄭重的心去啟請。按理這段請詞應當出自你自己口中，只因你不了解，所以我才教你，你應當一心領受我的教導。」她回答說：「是的」。", "i": "u173", "n": 252, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉一心念！我某甲，今請阿姨為和尚。願阿姨為我作和尚，我依阿姨故，得受具足戒，慈愍故。", "t": "大姊，請您專一心念、聽我陳說：我某甲，現在恭請阿姨您作我的和尚。祈願阿姨為我擔任和尚，我依止阿姨的緣故，得以受具足戒；唯願阿姨慈悲憐愍我。", "i": "u174", "n": 253, "s": "第10篇　具戒"}, {"v": "卷上", "o": "僧祇》云：「次第眾中三請已，和尚應語言：『發汝喜心。』」此律答云：「可爾。」或云：「教授汝。」或云：「汝莫放逸。」答云：「頂戴持。」若欲請者，至戒師前，和尚教云：「羯磨阿闍棃者，是受戒正緣，若無此人秉法，則大地塵沙法無由得生，故須起殷重心於戒師所。」如是種種教化已，然後請云。", "t": "《摩訶僧祇律》說：受戒者在尼眾中依次三請完畢後，和尚尼應當對她說：「我令你生起歡喜心。」《四分律》中，和尚尼則回答說：「可以。」或說：「我教導你。」或說：「你不可放逸。」受戒者便回答：「我頂戴奉行。」若要接著禮請羯磨師，受戒者就到戒師面前，由和尚尼教導她說：「羯磨阿闍梨是受戒的正緣。如果沒有這個人秉持羯磨作法，那麼像大地上的微塵、沙粒那樣多的戒法，就無從生起。所以必須對戒師生起殷重懇切的心。」像這樣種種教誡開導之後，才禮請說：", "i": "u175", "n": 254, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉一心念！我某甲，今請阿姨為羯磨阿闍棃。願阿姨為我作羯磨阿闍棃，我依阿姨故，得受具足戒，慈愍故。", "t": "大姊，請您一心專注聽我陳說：我某甲，現在懇請阿姨您擔任羯磨阿闍梨。願阿姨為我作羯磨阿闍梨，我依憑阿姨的緣故，得以受具足戒，願您慈悲憐愍我。", "i": "u176", "n": 255, "s": "第10篇　具戒"}, {"v": "卷上", "o": "次請威儀師阿闍棃云：「由此威儀師為汝引導，今至僧中，發汝具戒，緣起竝由此師，故須起段重意請。", "t": "其次禮請威儀師阿闍梨，和尚教導她說：「由於這位威儀師為你作引導，使你得以進到僧眾當中，發起你的具足戒；得戒因緣的生起，全都由於這位師父，所以你必須生起殷重誠懇的心意來啟請。」", "i": "u177", "n": 256, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉一心念！我某甲，今請阿姨為威儀阿闍棃。願阿姨為我作威儀阿闍棃，我依阿姨故，得受具足戒，慈愍故。", "t": "大姊，請您專心一意地憶念：我某甲，現在恭請阿姨擔任威儀阿闍梨。祈願阿姨為我作威儀阿闍梨，我依止阿姨的緣故，得以受具足戒。懇請您慈悲憐愍我。", "i": "u178", "n": 257, "s": "第10篇　具戒"}, {"v": "卷上", "o": "問：何故律中喚和尚等為阿姨？答：佛在世時，大愛道尼是佛姨母，諸尼因是得戒，遂學佛語，皆喚阿姨、尼阿摩等。《善見》云：「尼，女也；摩者，母也。」義準重尼，故稱之。然「阿」非梵語，漢地所稱；「女」通大小，「母」者耆年，如世人喚其阿母，義亦相類。", "t": "問：為什麼律中把和尚尼等稱作「阿姨」呢？答：佛在世時，大愛道比丘尼是佛的姨母，諸比丘尼因她而得受戒，於是效學佛陀的用語，都稱她們為「阿姨」「尼阿摩」等。《善見律毘婆沙》說：「尼」是女的意思，「摩」是母的意思；依義推求，這是為了敬重比丘尼（視之如母），所以才這樣稱呼。不過「阿」字並不是梵語，而是漢地的稱法：「女」通於年少年長，「母」則指年長的人，就像世人稱自己的母親為「阿母」，意思也相類似。", "i": "u179", "n": 258, "s": "第10篇　具戒"}, {"v": "卷上", "o": "《僧祇》云：「和尚尼欲授人具戒，應先求比丘尼，不得臨時選眾；若不可者，當求半許，若過半許而作法。」義云：若和尚犯重，羯磨師知，不成受戒，以所牒非比丘尼用。十師互相知，亦不成受；了了知非，則不應羯磨。下至知有四人清淨者，得成僧用。", "t": "《摩訶僧祇律》說：和尚尼要為人授具足戒，應當事先覓求比丘尼，不得臨時才在眾中挑選；若做不到，就應求得半數左右、或超過半數，然後作法。依義理說：如果和尚尼犯了波羅夷重罪，而羯磨師知情，受戒就不成就，因為羯磨文中所牒舉的和尚尼已不是比丘尼。若十師之間彼此明知對方犯了重罪，受戒也不成就；既然清楚知道不如法，就不應作羯磨。最低限度，只要知道其中有四人是清淨的，就能成就僧的作法之用。", "i": "u179-2", "n": 259, "s": "第10篇　具戒"}, {"v": "卷上", "o": "故《伽論》云：「邊地五人持律者授；若十人處，五人受戒得，比丘得可訶罪。」受戒人不知和尚是賊住，依彼出家受具足，得戒否？答：得戒，僧犯吉羅。", "t": "所以《伽論》說：邊遠地區由五位持律者授戒即可；若在具足十人的地方只用五人授戒，受戒的人仍得戒，但授戒的比丘僧眾得可呵責之罪。問：受戒的人不知道自己的和尚是「賊住」（冒充比丘混住僧中者），依他出家受具足戒，能得戒嗎？答：能得戒，僧眾則犯突吉羅罪。", "i": "u179-3", "n": 260, "s": "第10篇　具戒"}, {"v": "卷上", "o": "此律：大僧和尚十夏，尼和尚十二夏；大僧和尚開九夏，而得小罪。二種闍棃，大僧五夏已上，尼六夏已上，方得成授；餘師隨夏大小竝得。《五百問事》云：「比丘五臘不滿度弟子，知非而度，犯提；弟子不知是非，得戒。」", "t": "依《四分律》，比丘的和尚要滿十夏，比丘尼的和尚要滿十二夏；比丘和尚則開許九夏者擔任，但得小罪。羯磨、教授（屏處問遮難、教威儀）二種阿闍梨，比丘須五夏以上、比丘尼須六夏以上，才能擔任授戒之師；其餘諸師（尊證師）則不論夏臘大小，都可以擔任。《五百問事經》說：比丘不滿五臘便度弟子，明知不如法卻仍然度人，犯波逸提；弟子若不知是非，仍得戒。", "i": "u179-4", "n": 261, "s": "第10篇　具戒"}, {"v": "卷上", "o": "問：緒方僧尼情識闇鈍，不間戒律，貪求徒弟，白讀羯磨為人受戒，得成已否？答：不成，反結無知不學之罪。故此律遣上座誦羯磨，或報云「誦」，或云「先誦後忘」，遂稽留受戒事，故須要誦方得。", "t": "問：各方僧尼心識昏昧、愚昧遲鈍，不通達戒律，貪求徒弟，只是照著文本念讀羯磨而為人授戒，這樣能成就嗎？答：不成就，反而結犯無知、不學之罪。所以《四分律》中派遣上座背誦羯磨，有人回報說能誦，有人說先前誦過、後來忘了，因而耽擱了受戒之事；可見必須能背誦才行。", "i": "u179-5", "n": 262, "s": "第10篇　具戒"}, {"v": "卷上", "o": "《五分》：「諸比丘不誦羯磨，不得受具戒。」義云：末法時訛，多有斯謬，故引文證，願依時誦。", "t": "《五分律》說：諸比丘不能背誦羯磨，就不得為人授具足戒。依義理說：末法時代風氣訛濫，多有這類錯謬，所以引律文為證，希望大家能按時誦習羯磨文。", "i": "u179-6", "n": 263, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第二發戒緣者，義云：所發之戒，乃有無量，隨境總論，要而言之，不過情與非情，依正兩報，有無二諦，滅理、涅槃，佛說聖教、文字、經卷、形像、塔廟，地、水、火、風、虗空、識等，六塵萬境，法界等緣，不可具陳。", "t": "第二、發戒緣：依義理來說，所發起的戒有無量之多，隨著所緣之境總括來論，簡要而言，不外乎有情與非情、依報與正報這兩種果報、有與無二諦、寂滅之理與涅槃、佛陀所說的聖教、文字與經卷、形像與塔廟，以及地、水、火、風、虛空、識等，乃至六塵、萬境、法界等諸緣，實在無法一一詳盡陳述。", "i": "uGAP04-1", "n": 264, "s": "第10篇　具戒"}, {"v": "卷上", "o": "何以故？由不受故，則於一一眾生，莫問凡聖，起塵沙等惡；今翻為善，則成塵沙等戒。故《善生經》云：「眾生無邊，戒亦無邊。」", "t": "為什麼呢？因為沒有受戒的緣故，便會對每一個眾生，不論凡夫還是聖者，生起如塵沙般無數的惡業；如今回轉為善，就成為如塵沙般無數的戒。因此《善生經》說：「眾生無邊，戒也無邊。」", "i": "uGAP04-2", "n": 265, "s": "第10篇　具戒"}, {"v": "卷上", "o": "婆論》云：「於非眾生上，亦得無量戒善功德。如十方世界所有大地，下至水際、空界已來，若傷如微塵，竝得其罪；由受戒故成善。且如壞一艸葉，始從萌芽，一一華葉得爾罪；今翻爾罪，得若干戒。」故《善生經》云：「大地無量，戒亦無量。」乃至虗空有盜損之義，故《善生經》：「虗空無邊，戒亦無邊。」", "t": "《婆論》說：「在非眾生上，同樣能獲得無量的戒善功德。如同十方世界所有的大地，向下直達水際、空界之內，只要損傷如微塵般大小，全都會招致罪過；由於受戒的緣故，這一切便轉成為善。」譬如損壞一株草葉，從剛剛萌芽開始，上面的每一朵花、每一片葉，都會招致這許多的罪；如今回轉這許多的罪，便獲得同等數量的戒。因此《善生經》說：「大地無量，戒也無量。」乃至於虛空也有被盜取、損壞之義，因此《善生經》說：「虛空無邊，戒也無邊。」", "i": "uGAP04-3", "n": 266, "s": "第10篇　具戒"}, {"v": "卷上", "o": "婆論》云：「新受戒人，與佛齊功。」以此推之，出家之士，真是善法功德之聚，位尊人天，良由於此。不論持者，假令毀戒，亦得無邊戒利。何以知之？故《十輪》云：「破戒比丘雖是死人，是戒餘力，能大利益人天道俗，猶如牛黃、麝香等。」佛即說偈云：「薝蔔華雖萎，勝於一切華；破戒諸比丘，猶勝諸外道。」是故行者，受戒毀禁，尚得功德，況當清淨於法奉持，則難思議！", "t": "《婆論》說：「新近受戒的人，與佛陀功德齊等。」依此推論，出家之士真是善法與功德的聚集之處，在人天之中地位尊貴，確實是由於這個緣故。暫且不論謹嚴持戒的人，縱使是毀犯戒律的人，也仍然能獲得無邊的戒律利益。怎麼知道是這樣呢？《十輪》就說：「破戒比丘雖然已經是死人，但這戒的餘力，仍能大大利益人天與僧俗大眾，就如同牛黃、麝香等一樣。」佛陀隨即說偈言：「薝蔔花雖然枯萎，依然勝過一切花朵；破戒的諸位比丘，依然勝過一切外道。」因此，修行人受戒之後即使毀犯禁戒，尚且能獲得功德，更何況能保持清淨、依法奉持，那功德就更加不可思議了！", "i": "uGAP04-4", "n": 267, "s": "第10篇　具戒"}, {"v": "卷上", "o": "汝當緣念如上諸境。\n知所緣境已，次為廣開心懷，令彼受者增益道志，應語云：「族姓女諦聽！當發上品心，得上品戒；若發中、下心，得中、下戒。假令道成四果，是戒猶是中、下。何名上品？若言為正向泥洹故，為趣三解脫門故，為成三聚戒故，為令法久住故，為救眾生諸苦惱故，為求佛道度眾生故。如是如是，真佛弟子，得佛淨戒。」必須知者於受戒前一一提授，使心心相續，了法明淨，方得為受。", "t": "你應當緣念上述這些境界。了解所緣之境以後，接著為那位受戒者廣開心懷，使她增益向道之志，應當對她說：「族姓女諦聽！應當發起上品心，才能獲得上品戒；如果發起中、下品心，便只獲得中、下品戒，即使修道成就四果，這戒依然只是中、下品。什麼叫做上品呢？就是說：為了正向泥洹、為了趣向三解脫門、為了成就三聚戒、為了讓正法久住、為了救拔眾生種種苦惱、為了追求佛道並度化眾生。像這樣、像這樣，才是真正的佛弟子，才能獲得佛的清淨戒。」必須由通曉法義的人在受戒之前，逐一提點講授，使她心念相續不斷，對戒法理解明晰清淨，這樣才可以為她授戒。", "i": "uGAP04-5", "n": 268, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第三安置者，此律云：當安欲受戒人，置眼見、耳不聞處立；若安見聞俱離處及界外者，不名受戒。故《五分》云：以起過，聽安戒場外眼見處。", "t": "第三、安置受戒人：《四分律》說：應當把將要受戒的人，安置在僧眾眼睛看得見他、他卻聽不到僧中作法聲音的地方站著。如果安置在既看不見、也聽不到的地方，或者結界之外，就不算是受戒。所以《五分律》說：因為曾發生過失，佛聽許把受戒人安置在戒場之外、眼睛看得見的地方。", "i": "u180", "n": 269, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第四單白者，此應差威儀師屏問遮難。此律：由界外脫衣看故，令受者慚耻，稽留受戒，佛言：「不得露形看，當差人屏問遮難。」《伽論》云：「受具戒時，不問遮道法，得戒，僧得吉羅。」此律云：戒師當問：「眾中誰為某甲作教授師？」答云：「某甲能。」戒師問僧云：「僧今和合，何所作為？」答：「差教授師單白羯磨。」作此答，止得作一法；若答云「受大戒羯磨」者，後不須和僧，縱更受，亦不須和，以一答通多人故。", "t": "第四、單白。這裡應當差派威儀師，即教授師，到隱蔽處詢問遮難。本部《四分律》記載：由於曾把將受戒的人帶到界外，脫去衣服查看，使受戒者慚愧羞恥，耽擱了受戒之事。佛說：不得使受戒者裸露形體供人查看，應當差派一人到隱蔽處詢問遮難。《摩得勒伽論》說：受具足戒時，若不詢問遮障聖道的難事，受戒者仍得戒，眾僧則犯突吉羅罪。\n《四分律》又說：戒師應當問大眾：「眾中誰能為某甲作教授師？」回答說：「我某甲能。」戒師再問僧眾：「僧眾現在和合集會，要作什麼事？」回答：「差教授師單白羯磨。」若作這樣的回答，就只能作這一項法事；若回答「受大戒羯磨」，此後就不必再作和僧的問答，縱使接著再為其他人授戒，也不必再問，因為一次回答可以通攝多人的緣故。", "i": "u181", "n": 270, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！彼某甲，從和尚尼某甲，求受具足戒。若僧時到，僧忍聽，某甲為教授師。白如是。", "t": "諸位大姊僧眾請聽：那位某甲，以和尚尼某甲為和尚，請求受具足戒。如果僧眾作法的時機已到，請僧眾認可聽許：差派某甲為教授師。我如此稟白。", "i": "u182", "n": 271, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第五出眾問難者，所以須問耶？恐其覩眾生怖，有無差互，言辭舛錯，答容不實；屏處怖微，令得審定。然此十三難，不問不得戒，若有而不問，亦不成受，故律文自制後，不問不得戒。", "t": "第五是出眾問難。為什麼必須問呢？因為怕她見到大眾而心生怖畏，答「有」答「無」顛倒錯亂、言辭舛誤，回答的內容可能不實在；在屏隱之處怖畏輕微，才能讓她審慎確實地作答。然而這十三難，不問就不得戒；如果她實有難事而不問，受戒也同樣不能成就。所以律文自從制立此法之後便明定：不問就不得戒。", "i": "uGAP05-1", "n": 272, "s": "第10篇　具戒"}, {"v": "卷上", "o": "又問難之體，必須分析文句，令識相輕重，不得直問言：「汝不犯邊罪否？」不知「邊罪」意是何罪等，自非明律灼然，何能達此？若不委問，恐是十三難。沙彌尼、式叉尼是白衣時，曾受八戒，隨破一重，皆不發戒，自非懇惻重懺得證，何得輒授？既有斯謬，委具問之。", "t": "再說，問難的要領，必須把文句逐一剖析說明，讓她認識各項的相狀與輕重，不可以直接就問：「妳沒有犯邊罪吧？」她根本不知道「邊罪」的意思是指什麼罪等等。若不是對律明白透徹的人，怎能通達這些？如果不詳加詢問，就怕她正是十三難所攝的人。沙彌尼、式叉尼還是在家人時，若曾受過八戒，只要破了其中任何一條重戒，就都發不起戒體；除非懇切至誠地殷重懺悔、得到罪滅的證驗，否則怎能隨便就為她授戒？既然有這樣的錯謬，就要詳盡周全地一一問明。", "i": "uGAP05-2", "n": 273, "s": "第10篇　具戒"}, {"v": "卷上", "o": "今正出眾問難，威儀師當起，禮僧足已，至行者所，坐，語受者：「汝坐！」令大敷坐具，為舒張已，在伸手內。若依《五分》云：應安慰云：「汝莫怖畏，須臾持汝著高勝處。」", "t": "現在正式出眾問難：威儀師應當起身，頂禮僧眾之足後，走到受戒者所在之處坐下，對受戒者說：「妳坐。」並讓她把坐具完全展開鋪好。坐具鋪好之後，二人相對而坐，在彼此伸手可及的距離之內。若依《五分律》所說，應當安慰她說：「妳不要怖畏，過一會兒就要把妳安置到尊高殊勝的地位上。」", "i": "uGAP05-3", "n": 274, "s": "第10篇　具戒"}, {"v": "卷上", "o": "應取衣鉢，種種誘訓。執五條已，語云：「此是安陀會。」指身所著：「此是鬱多羅僧。」執大衣已：「此是僧伽棃。汝身著者，僧祇支；汝所披者，此是覆肩衣。一切九十六種外道，無此衣名，今故示汝。」并執鉢已，語云：「此是鉢多羅。此衣鉢，是汝有否？」答云：「是。」", "t": "接著應取過衣缽，用種種方式引導教導她：拿起五條衣後說：「這是安陀會。」又指自己身上所穿的說：「這是鬱多羅僧。」拿起大衣後說：「這是僧伽棃。妳身上穿的這件是僧祇支，妳所披的這件是覆肩衣。一切九十六種外道都沒有這樣的衣名，如今特地指示給妳。」再拿起缽說：「這是缽多羅。這些衣和缽是妳所有的嗎？」她回答：「是。」", "i": "uGAP05-4", "n": 275, "s": "第10篇　具戒"}, {"v": "卷上", "o": "威儀師為襆衣鉢已，語言：「善女人諦聽！今是至誠時、實語時，我今問汝，隨問答我。若不實者，當言不實；若實，當言實。所以如此者，由無始已來，多有妄語，欺誑凡聖，致使沈溺生死；今欲捨虗妄、證真實，故令汝實答。我今問遮難，答若不實，徒自費功，浪受無益。」", "t": "威儀師替她把衣缽包裹收好之後，對她說：「善女人，仔細聽著！現在是至誠的時刻、說真實語的時刻。我現在問妳，妳隨我所問而回答我：不實在的，就應當說不實在；實在的，就應當說實在。」之所以要這樣做，是因為無始以來多有妄語，欺誑凡夫與聖人，致使自己沉溺生死；如今想要捨棄虛妄、證得真實，所以要妳據實回答。接著說：「我現在要問妳遮難。妳回答若不實在，只是白白耗費功夫，徒然受戒也毫無益處。」", "i": "uGAP05-5", "n": 276, "s": "第10篇　具戒"}, {"v": "卷上", "o": "一、「汝不犯邊罪否？」應語云：「計汝應不識何謂邊罪。以曾受戒，行淫、盜五錢、殺人、自稱得聖，犯此罪者，必不得戒。或曾受五戒、八戒、十戒，犯四重已，或受大戒，犯八重已，還俗訖，今重來者，名邊罪人等，或白衣、沙彌尼時，造重業，竝十三難攝。汝不犯此否？」答言：「不。」", "t": "第一問：「妳沒有犯過邊罪嗎？」應當先對她說：「想來妳應該不知道什麼叫邊罪。就是曾經受過戒，卻行淫、偷盜五錢、殺人、自稱證得聖果；犯了這些罪的人，必定不能得戒。或者曾經受過五戒、八戒、十戒而犯了四重罪，或者受了大戒而犯了八重罪，之後還俗，如今又重新回來求受戒的，都叫做邊罪人等。又或者還是在家人時、沙彌尼時造了重業，這些也都攝屬十三難。妳沒有犯這些嗎？」她答：「沒有。」", "i": "uGAP05-6", "n": 277, "s": "第10篇　具戒"}, {"v": "卷上", "o": "二、「汝不白衣時，汙他淨戒比丘否？」答言：「不。」\n三、「汝不白衣時及沙彌時，盜聽他說戒、羯磨、眾僧法事否？」答言：「不。」\n四、「汝不破內外道否？」謂曾作外道，來求受戒，還作外道，今復重來否？答言：「不。」\n五、「汝不是黃門否？」答言：「不。」\n六、「汝不殺父否？」答言：「不。」\n七、「汝不殺母否？」答言：「不。」\n八、「汝不殺阿羅漢否？」答言：「不。」\n九、「汝不破僧否？」答言：「不。」\n十、「汝不惡心出佛身血不？」答言：「不。」\n十一、「汝非非人否？」答言：「不。」\n十二、「汝非畜生否？」答言：「不。」\n十三、「汝非身挾男女二形否？」答言：「不。」", "t": "第二問：「妳還是在家人時，沒有敗壞持淨戒比丘的梵行嗎？」答：「沒有。」第三問：「妳還是在家人時以及沙彌尼時，沒有偷聽僧眾說戒、作羯磨等法事嗎？」答：「沒有。」第四問：「妳不是破內外道的人嗎？就是曾經做過外道，來求受戒，後來又回去做外道，如今又重來求受戒，妳有這種情形嗎？」答：「沒有。」第五問：「妳不是黃門嗎？」答：「不是。」第六問：「妳沒有殺父嗎？」答：「沒有。」第七問：「妳沒有殺母嗎？」答：「沒有。」第八問：「妳沒有殺阿羅漢嗎？」答：「沒有。」第九問：「妳沒有破僧嗎？」答：「沒有。」第十問：「妳沒有以惡心出佛身血嗎？」答：「沒有。」第十一問：「妳不是非人嗎？」答：「不是。」第十二問：「妳不是畜生嗎？」答：「不是。」第十三問：「妳不是身上兼具男女二形的人嗎？」答：「不是。」", "i": "uGAP05-7", "n": 278, "s": "第10篇　具戒"}, {"v": "卷上", "o": "問已，應語言：「女妹！汝已道無，今更問汝諸遮妨義。」而遮事非一，文中略問十六，自餘受法廣明，皆言不應，不論得否；今以義準，有得不得，若不自稱字、不稱和尚尼字、年歲不滿、衣盋不具等，定不得戒，自外可知。", "t": "問完之後，應當對她說：「妹妹！妳已經說了沒有這些難。現在再問妳各種遮止妨礙受戒的事。」遮事不止一項，這段文中只是大略問十六項，其餘的在受戒法中廣泛說明；那些文都只說不許如此，並沒有討論能不能得戒。現在依義理來衡量，其中有能得戒的，也有不能得戒的：像不自稱自己的名字、不稱和尚尼的名字、年歲不滿、衣缽不具足等，決定不得戒；其餘的可以依此推知。", "i": "uGAP05-8", "n": 279, "s": "第10篇　具戒"}, {"v": "卷上", "o": "汝字何等？」答言：「某甲。」「和尚尼字誰？」答言：「某甲。」「年歲滿否？」答言：「滿。」「衣盋具否？」答言：「具。」「汝父母聽、夫主聽否？」答言：「聽。」「汝非負債否？」答言：「不。」「汝非婢否？」答言：「不。」「汝是女人否？」答言：「是女人。」「有如是病：癩、癰疽、白癩、乾消、顛狂、二形、二道、小大常漏、大小便涕唾常流，汝有如是諸病否？」答言：「無。」", "t": "於是問：「妳叫什麼名字？」答：「某甲。」「妳的和尚尼叫什麼名字？」答：「某甲。」「年歲滿了沒有？」答：「滿了。」「衣缽具足了沒有？」答：「具足。」「妳的父母、夫主准許了嗎？」答：「准許了。」「妳沒有欠債嗎？」答：「沒有。」「妳不是婢女嗎？」答：「不是。」「妳是女人嗎？」答：「是女人。」「有這樣的病：癩、癰疽、白癩、形體枯瘦的乾消病、癲狂、二形、二道、大小便常漏失、大小便及鼻涕口水常流不止。妳有這些病嗎？」答：「沒有。」", "i": "uGAP05-9", "n": 280, "s": "第10篇　具戒"}, {"v": "卷上", "o": "伽論》云：「聾人不聞羯磨，不得戒；聞者得，何以故？由無遮難故。」", "t": "《伽論》說：聾人聽不到羯磨就不得戒，聽得到的就得戒。為什麼呢？因為耳聾並不屬於遮難的緣故。", "i": "uGAP05-10", "n": 281, "s": "第10篇　具戒"}, {"v": "卷上", "o": "又當語言：「如我今問汝事，僧中亦當如是問；如汝向者答我，眾僧中亦如是答，更莫改變。」應教起立，為正著七條，令威儀齊整，著履，揲坐具安臂上，襆衣置手中已，語言：「我僧中為汝通信，若大眾許可，我當舉手招汝，汝可即來。」答言：「爾。」", "t": "又應當對她說：「像我現在問妳的這些事，到了僧眾中也會這樣問；妳剛才怎樣回答我，在僧眾中也要那樣回答，不要再改變。」接著教她站起來，替她把七條衣穿端正，使威儀整齊，穿上鞋子，把坐具摺好放在手臂上，把包好的衣放在她手中，然後對她說：「我到僧眾中替妳通報。如果大眾許可，我就舉手招呼妳，妳就立刻過來。」她答：「好。」", "i": "uGAP05-11", "n": 282, "s": "第10篇　具戒"}, {"v": "卷上", "o": "若依《五分》，教著衣時，密如法觀看無病不；如是種種方便看之。若不相識人，不應雲霧暗中受。《五百問事》云：「要須燈燭照之。", "t": "若依《五分律》，在教她穿衣的時候，要私下不著痕跡地如法察看，看她有沒有病患，像這樣用種種方便去觀察她。如果是不相識的人，不應在雲霧昏暗之中為她授戒。《五百問事》說：必須用燈燭照明。", "i": "uGAP05-12", "n": 283, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第六單白喚入眾者，彼教授師還攝威儀，來至僧中，如常威儀，相去伸手及處立，當作白云。", "t": "第六、以單白羯磨召喚受戒人進入僧眾：那位教授師回來，重新收攝威儀，來到僧眾當中，依照平常的威儀規矩，站在與僧眾相距伸手可及的地方，應當這樣作白說：", "i": "u183", "n": 284, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！彼某甲，從和尚尼某甲，求受具足戒。若僧時到，僧忍聽，我已問竟，聽將來。白如是。", "t": "大姊僧團請聽：那位某甲，依止和尚尼某甲，前來請求受具足戒。如果僧團認為時機已到，僧團忍可聽許：我已經問完了，請允許把她帶進來。我就這樣稟白。", "i": "u184", "n": 285, "s": "第10篇　具戒"}, {"v": "卷上", "o": "白已，勿出僧中，於堂門限內立，待舉手喚言：「某甲來！」彼來已，至僧中時，常為捉衣盋，教正衣服，四面禮僧竟。", "t": "作完單白之後，教授師不要走出僧眾之外，應站在堂門門檻的內側等候，舉手召喚說：「某甲，來！」等她過來、進入僧眾中之後，教授師要一直替她拿著衣缽，教她把衣服整理端正，再讓她向四面的僧眾禮拜；禮拜完畢。", "i": "u185", "n": 286, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第七正乞戒，威儀師教至羯磨師前，兩膝著地，合掌，衣盋付戒師已，安慰其心，懇惻至誠，仰憑清眾，求哀乞戒。戒師語言：「此之戒法，非人不得，故六道之中，唯人得受。彼天主常作念言：『何時得受具戒？』由報障故，不得受戒。汝今生人道中，無諸遮難，當發增上善心乞戒，須臾之間，便入三乘聖人僧寶之位，難可校量。但乞戒由汝自心發言，不從他出，既是勝玅之法，若不曉其方軌，則階漸無由可證，故佛教我為汝引導，汝當一一逐我言教。", "t": "第七，正式乞求受戒。威儀師教導受戒者來到羯磨師面前，兩膝跪地、合掌；威儀師把衣缽交付戒師後，安慰她的心，使她懇切至誠，仰望依憑清淨的僧眾，哀求乞受戒法。戒師對她說：「這戒法，不是人就得不到，所以六道之中，只有人能夠受。那位天主常常這樣想：『什麼時候才能受具足戒呢？』但由於所受果報的障礙，他無法受戒。你如今生在人道之中，又沒有種種遮法、難法，應當發起增上的善心來乞戒，短短片刻之間，就能進入三乘聖人僧寶的位次，這是難以計量比擬的。只是乞戒必須由你自己內心發出言語，不能出自他人之口。這既然是殊勝微妙的法，如果不明白它的方法軌則，那麼就無從循著階次證入了。所以佛教導我來為你引導，你應當一句一句跟著我所教的話來說。」", "i": "u186", "n": 287, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！我某甲，從和尚尼某甲，求受具足戒。我某甲，今從眾僧，乞受具足戒，和尚尼某甲。願僧拔濟我，慈愍故。", "t": "諸位大姊僧，請聽！我某甲，依從和尚尼某甲，請求受具足戒。我某甲，現在向眾僧乞求受具足戒，和尚尼是某甲。願僧眾出於慈悲憐愍，拔苦濟度我。", "i": "u187", "n": 288, "s": "第10篇　具戒"}, {"v": "卷上", "o": "威儀師教已，依本坐。", "t": "威儀師教完乞戒的話之後，就回到自己原來的座位坐下。", "i": "u188", "n": 289, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第八戒師單白和僧問難者，戒師當白云。", "t": "第八，戒師作單白向僧眾宣告、徵得僧眾同意，以便詢問遮難：戒師應當這樣白告：", "i": "u189", "n": 290, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！此某甲，從和尚尼某甲，求受具足戒。此某甲，今從僧，乞受具足戒，和尚尼某甲。若僧時到，僧忍聽，我問諸難事。白如是。", "t": "各位大姊僧眾請聽：這位某甲，依和尚尼某甲求受具足戒。這位某甲現在向僧眾乞求受具足戒，和尚尼是某甲。如果僧眾時機已到、僧眾忍可聽許，我就要詢問她各種障難之事。以上如此禀白。", "i": "u190", "n": 291, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第九正明對眾問難者，應取其衣盋，一一提示言：「此安陀會、鬱多羅僧、伽棃衣及盋，此衣盋若借來者不得戒，實是汝物否？」答言：「是。」應語言：「善女人聽！今是至誠時、實語時，我今問汝，當隨實答。所以言真實者，故《僧祇》云：『汝若不實答，欺誑諸天、魔、梵、沙門、婆羅門、諸天世人，亦欺誑如來及以眾僧，自得大罪。』今問十三難，還同上威儀師所問，而眾僧恐屏處有濫，故對眾一一問汝，汝還一一依威儀師所問，一一答我。」答云：「爾。", "t": "第九，正式說明當眾問難。戒師應取過她的衣與缽，逐件指給她看，說：「這是安陀會衣、鬱多羅僧衣、僧伽梨衣，以及缽。這些衣缽如果是借來的，就不能得戒。它們確實是你自己的東西嗎？」她回答說：「是的。」\n接著應當對她說：「善女人，聽著：現在是至誠的時刻、說真實語的時刻。我現在問你，你應當依真實回答。」之所以要求真實回答，是因為《僧祇律》說：「你如果不依實回答，就是欺誑諸天、魔、梵、沙門、婆羅門、諸天與世人，也欺誑如來以及眾僧，自己得大罪。」\n「現在所要問的十三難，和先前威儀師所問的相同；只是眾僧恐怕在屏處詢問時有所混濫，所以要當著大眾一一問你，你也要一一依照威儀師先前所問的，逐條回答我。」她回答說：「是的。」", "i": "u191", "n": 292, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第十正受戒者，若答無遮難，堪為正受。將欲受戒，先勗心懷，令生上品意。", "t": "第十、正受戒：如果受戒者回答沒有遮難，便堪任正式受戒。將要受戒時，應先勉勵她的心懷，使她生起上品的心意。", "i": "uGAP06-1", "n": 293, "s": "第10篇　具戒"}, {"v": "卷上", "o": "戒師語言：「善女人！汝遮難竝無，眾僧同共隨喜，當與汝戒。但戒善廣大，亘周法界，當起上品心，得上品戒。何等上品？故前緣起云：為趣泥洹果，向三解脫門，成就三聚淨戒，令正法久住，此是上品。", "t": "戒師對她說：「善女人，你完全沒有遮難，眾僧都一同隨喜，將會授與你戒法。只是戒法的善德廣大，橫亙遍及整個法界，你應當生起上品的心，才能得到上品的戒。什麼是上品呢？所以前面的緣起說：『為了趣向泥洹果，朝向三解脫門，成就三聚淨戒，使正法長久住世。』這就是上品。", "i": "uGAP06-2", "n": 294, "s": "第10篇　具戒"}, {"v": "卷上", "o": "智度論》云：『下持戒生人，中持戒生六欲天，上持戒生色、無色天。又下清淨持戒得阿羅漢道，中清淨持戒得辟支佛道，上清淨持戒得佛道。』", "t": "《智度論》說：『下品持戒生在人道，中品持戒生在六欲天，上品持戒生在色界、無色界天。又，下品清淨持戒證得阿羅漢道，中品清淨持戒證得辟支佛道，上品清淨持戒證得佛道。』", "i": "uGAP06-3", "n": 295, "s": "第10篇　具戒"}, {"v": "卷上", "o": "當廣開汝懷！所以爾者，塵沙戒法，注汝身中，不以報得狹小而得受也；當作虗空器量之身，徧周法界。一切凡聖、依正兩報，無問自他等境，皆發塵沙等戒，汝當願納此法。", "t": "你應當大大敞開胸懷。之所以要這樣，是因為如塵沙般無量的戒法將注入你的身中，不是憑藉果報所得的狹小身量就能領受的。你應當將自身觀想成猶如虛空般寬廣器量的身軀，遍滿法界，對一切凡夫與聖者的依報、正報兩種果報，不論是自身或他人等境界，全都從中發起如塵沙般無量的戒法；你應當發願領納這份戒法。", "i": "uGAP06-4", "n": 296, "s": "第10篇　具戒"}, {"v": "卷上", "o": "又此戒法，若是有色者，入汝身時，如天崩地陷之聲；由是非色法故，令汝不覺，汝當起驚悚之意，勿得懈慢。", "t": "又，這份戒法如果是有形色的法，在進入你的身中時，會有如同天崩地陷般的聲響；正因為它是非色法的緣故，才讓你察覺不到。你應當生起敬畏悚動的心意，切勿懈怠輕慢。", "i": "uGAP06-5", "n": 297, "s": "第10篇　具戒"}, {"v": "卷上", "o": "今為汝作羯磨，發此塵沙戒善。所以法界善戒而得用羯磨發者，汝不聞外道仙人用呪術之力，尚能移山鎮海、迴天轉日，豈況如來六道之師所說聖教法中之上，而無此力？今白三羯磨，世尊口出，我傳佛教，發汝戒體，汝須知之。」", "t": "現在為你舉行羯磨，來發起這如塵沙般無量的戒善。遍及法界的善戒之所以能夠用羯磨來發起，你難道沒聽過嗎？外道仙人運用咒術的力量，尚且能夠移山鎮海、迴天轉日，更何況如來是六道眾生的導師，他所宣說的聖教在諸法之中最為至上，哪裡會沒有這種力量呢？如今這白三羯磨的法詞，是由世尊親口宣說，我傳達佛陀的教法，藉此發起你的戒體，你必須明白這一點。」", "i": "uGAP06-6", "n": 298, "s": "第10篇　具戒"}, {"v": "卷上", "o": "正作法前，白云：「眾僧慈悲，布施某甲戒。」作此語已，應四向顧望，勿令入睡眠、亂語、非法、別眾等坐，若有，即須喚令正坐，向羯磨師一心聽說。", "t": "在正式作法之前，戒師先向眾僧作白說：「祈請眾僧慈悲，布施某甲戒法。」說完這句話後，應當向四方環顧察看，不可讓與會者陷入睡眠、隨意亂語，或以不如法、別眾等方式就座。如果發現有這種情況，就必須招呼她們端正坐好，面向羯磨師一心諦聽宣說。", "i": "uGAP06-7", "n": 299, "s": "第10篇　具戒"}, {"v": "卷上", "o": "十誦》云：「證他受戒，各各入定、亂語、戲笑，不知羯磨成否？」佛言：「不成。」若作羯磨者，應分別之：「是第一羯磨」，第二、第三亦如是。莫餘覺、餘思惟，應起敬重憶念，違者吉羅。", "t": "《十誦律》說：「為他人見證受戒時，眾人各自入定、亂語、戲笑，不知這樣作的羯磨是否成就？」佛陀說：「不成就。」若是主持作羯磨的人，應當分別宣明「這是第一羯磨」，第二番、第三番羯磨也應照這樣分別宣告。與會眾人不可生起其他念頭與雜想，應當懷抱敬重之心並專心憶念，違犯者得吉羅罪。", "i": "uGAP06-8", "n": 300, "s": "第10篇　具戒"}, {"v": "卷上", "o": "又《文殊問經》云：「四眾於何時不得作聲，或身、口、木石及諸餘聲？」佛告文殊：「於六時中不得作聲：一、禮佛時，二、聽法時，三、眾和合時，四、乞食時，五、正食時，六、大小便時。」", "t": "又，《文殊問經》說：「四眾弟子在什麼時候不得發出聲音，無論是身體、口舌、木石碰撞，或是其他各種聲響？」佛陀告訴文殊：「在六種時候不得發出聲音：一、禮佛時，二、聽法時，三、大眾和合時，四、乞食時，五、正食時，六、大小便時。」", "i": "uGAP06-9", "n": 301, "s": "第10篇　具戒"}, {"v": "卷上", "o": "如是誡已，然後白云。", "t": "像這樣告誡完畢之後，接著才作白宣告。", "i": "uGAP06-10", "n": 302, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！此某甲，從和尚尼某甲，求受具足戒。此某甲，今從僧乞受具足戒，和尚尼某甲。某甲自說清淨，無諸難事，年歲已滿，五衣盋具。若僧時到，僧忍聽，僧今授某甲具足戒，和尚尼某甲。白如是。", "t": "諸位大姊僧眾請聽：這位某甲，依止和尚尼某甲，求受具足戒；這位某甲，現在向僧團乞求受具足戒，和尚尼是某甲。某甲自己陳說清淨，沒有各種障難之事，年齡已滿，五衣與缽都已具足。若僧團時機已到，請僧團忍可聽許：僧團現在就授與某甲具足戒，和尚尼是某甲。以上如此白告。", "i": "u192", "n": 303, "s": "第10篇　具戒"}, {"v": "卷上", "o": "白已，問僧成就否；乃至三番，亦一一問之。此《僧祇》文。準此，僧中知法者答云：「成就。」次作羯磨云。", "t": "戒師作完白之後，要問僧眾：「成就否？」乃至白到第三遍，每一遍也都一一這樣問。這是《摩訶僧祇律》的文。依準此文，應由僧眾中通曉律法的人回答：「成就。」接著才作羯磨，說道：", "i": "u193", "n": 304, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大姉僧聽！此某甲，從和尚尼某甲，求受具足戒。此某甲，今從僧乞受具足戒，和尚尼某甲。某甲自說清淨，無諸難事，年歲已滿，五衣盋具。僧今授某甲具足戒，和尚尼某甲。誰諸大姉忍僧與某甲受具足戒、和尚尼某甲者，默然；誰不忍者，說。僧已忍，與某甲受具足戒竟，和尚尼某甲。僧忍默然故，是事如是持。", "t": "各位大姊僧眾請聽：這位某甲，依和尚尼某甲求受具足戒；這位某甲現在向僧眾乞求受具足戒，和尚尼是某甲。某甲自己說她清淨，沒有種種障難之事，年齡已滿，五衣和缽都已齊備。僧眾現在授給某甲具足戒，和尚尼是某甲。各位大姊當中，凡是同意僧眾授給某甲具足戒、以某甲為和尚尼的，就請默然；不同意的，請說出來。僧眾已經同意，授給某甲具足戒完畢，和尚尼是某甲。由於僧眾默然同意的緣故，這件事就這樣確定，就這樣奉持。", "i": "u194", "n": 305, "s": "第10篇　具戒"}, {"v": "卷上", "o": "此律云：若有八難、餘緣、天陰暗等，當二、三人一時作羯磨，然不得加四，以同別眾故；無難者不得授。", "t": "本部《四分律》說：若有八難或其餘因緣，例如天色陰暗等情況，可以為二人、三人同時一起作羯磨授戒；但不得增加到四人，因為那就等同於「別眾」的緣故。若沒有這些難緣，就不可以這樣授戒。", "i": "u195", "n": 306, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第三至僧受者，此律：作本法已，即日應往僧中求受大戒，違者犯罪。就中略有十問答。", "t": "第三，到比丘僧中受戒。依《四分律》規定：在尼僧中作完本法之後，當天就應該前往比丘僧中，求受具足大戒；違犯的人便結罪。就這一節，大略列出十個問答。", "i": "u196", "n": 307, "s": "第10篇　具戒"}, {"v": "卷上", "o": "一、問：僧至尼寺受戒成否？答：若依《薩婆多師資傳》說，此不如法，不成受戒；如端正女人，此是難故，猶不許請僧來至尼寺受戒，此既非難，何容得開。", "t": "一、問：僧眾到尼寺來授戒，受戒能否成就？\n答：若依《薩婆多師資傳》所傳的說法，這樣做不合律法，受戒不能成就。譬如容貌端正的女人，那確實是有危難的情形，尚且仍不許請僧眾來到尼寺為她授戒；如今這種情況既然沒有危難，哪裡可以開許呢？", "i": "u197", "n": 308, "s": "第10篇　具戒"}, {"v": "卷上", "o": "二、問：寄尼寺外俗家結界成受戒否？答：律亦無文，然容可通，仍非法，得小罪，無妨戒成。", "t": "第二問：借用尼寺以外的俗人住宅來結界受戒，這樣受戒能否成就？答：律中也沒有明文規定，然而按理或許可以通融；只是這樣的作法仍屬非法，會犯小罪，不過並不妨礙受戒成就。", "i": "u198", "n": 309, "s": "第10篇　具戒"}, {"v": "卷上", "o": "三、問：本法尼名作何等？答：律名「比丘尼」也。", "t": "第三問：已在尼僧中作過本法羯磨的受戒人，該用什麼名稱來稱呼她？答：律中就稱她為「比丘尼」。", "i": "u199", "n": 310, "s": "第10篇　具戒"}, {"v": "卷上", "o": "四、問：尼在僧寺，得作本法否？答：如《明了論》云：「僧界內為尼立界作法，理得無過。", "t": "第四問：比丘尼可以在比丘僧的寺院裡作本法，也就是先在尼僧中作的授戒羯磨嗎？答：如《明了論》所說，在比丘僧所結的界內為比丘尼另結一個界來作法，按理是可行的，沒有過失。", "i": "u200", "n": 311, "s": "第10篇　具戒"}, {"v": "卷上", "o": "五、問：留髮白衣與受具足，得戒否？答：有得、不得。\n問：云何有得？答：得者，謂志求出家，厭世俗情，王難不聽落髮出家，具此意者，得戒不疑。故《婆論》問云：「不除髮，得戒否？」答：「得，但非威儀。」又《伽論》問云：「若白衣為和尚，與白衣受具足戒，得戒否？」答：「得戒，僧犯吉羅。」", "t": "第五問：留著頭髮的在家人，為他授具足戒，他能得戒嗎？答：有得戒的，也有不得戒的。問：怎樣的情形是得戒？答：所謂得戒，是指那種志願求出家、厭離世俗情染的人，只因王法的障難，不獲准剃髮出家；具備這樣心意的人，得戒是無可懷疑的。所以《薩婆多論》中問說：不剃除頭髮而受戒，得戒嗎？答：得戒，只是不合出家的威儀。又《摩得勒伽論》中問說：若在家人作和尚，為在家人授具足戒，受者得戒嗎？答：得戒，但僧眾犯突吉羅罪。", "i": "u201", "n": 312, "s": "第10篇　具戒"}, {"v": "卷上", "o": "又《十誦》波離問云：「若男子作女威儀、女相、女形制已，如男子法受戒，得戒否？」佛言：「得戒，眾僧得罪。」女人作男子威儀，得戒亦然。《五百問事》云：「壇上師僧或著俗服，或犯禁戒，若受戒人知是非法，不得；不知者得。若弟子著俗服，當時不知者得。」", "t": "又《十誦律》中優波離問說：若男子作出女人的舉止威儀、女人的相狀，把自己裝扮成女人的形貌之後，仍依男子的受戒法受戒，得戒嗎？佛說：得戒，但眾僧得罪。女人作出男子的威儀而受戒，得戒的情形也是一樣。《五百問事經》說：戒壇上的師僧，有的穿著在家俗服，有的犯了禁戒；如果受戒的人知道這是非法，就不得戒；不知道的，仍得戒。若是弟子穿著俗服，當時不知這情形的，也得戒。", "i": "u201-2", "n": 313, "s": "第10篇　具戒"}, {"v": "卷上", "o": "問：云何不得戒？答：數見邊方尼，妄行戒律，見有誠文，無問善惡，遂即雷同，總與授戒。觸事無知，專習非法，紡績機織，俗務是常，長眉高髻，綺染恒式。師有貪利門徒之心，弟子有偷形避伇之意；所以僧不揀弟子好惡，得利便授，弟子不擇師行是非，苟求資蔭。永惟斯理，俗禮尚自不成，況出世清虗，何容得就？", "t": "問：怎樣的情形不得戒？答：我屢次見到邊遠地區的比丘尼胡亂施行戒法：見到有這樣的明文可據，就不管求受的人是善是惡，一概不加區別地全都給她們授戒，凡遇行事一概無知，專門習行非法的做法。紡紗織布這類世俗事務成了她們的日常；畫長眉、梳高髻、穿著綺羅彩染的衣飾成了慣常的樣式。作師父的存著貪圖門徒利養的心，作弟子的存著假冒出家形相、藉以逃避徭役的念頭。所以僧眾不揀擇弟子的好壞，有利可得就給授戒；弟子也不揀擇師父行持的是非，只是苟且求取資養與庇蔭。深長地思惟這個道理：這種情形，就連世俗的禮法尚且不能成立，何況出世間清淨無為之道，哪裡容許這樣成就？", "i": "u201-3", "n": 314, "s": "第10篇　具戒"}, {"v": "卷上", "o": "故此律宗要，出家相具，應剃髮、著袈裟，與出家人同；若著俗服、外道服、眾莊嚴具、裸形等，竝不名出家受具足戒。", "t": "所以本律的宗旨要求出家之相必須具足：應當剃除頭髮、穿著袈裟，與出家人相同。若穿著俗人的衣服、外道的衣服、佩戴種種莊嚴飾物、裸體無衣等，都不名為出家受具足戒。", "i": "u201-4", "n": 315, "s": "第10篇　具戒"}, {"v": "卷上", "o": "若受戒人不自稱名、不稱和尚名、說乞而不乞、若眠、醉、狂、瞋恚、無心受戒，或心不當境，或境不當心，或心境俱不相應，竝名非法，不名受戒。前後無違，方名辨事。", "t": "又若受戒的人不自稱自己的名字、不稱和尚的名字、口中說著乞戒的話卻不是真正的乞求，或在睡眠、酒醉、癲狂、瞋恚之中而沒有受戒的心念，或能受之心與所對之境不相稱，或所對之境與能受之心不相稱，或心與境兩者都不相應，這些都叫非法，不名為受戒。從前到後都沒有違失，才叫作成辦了受戒之事。", "i": "u201-5", "n": 316, "s": "第10篇　具戒"}, {"v": "卷上", "o": "今兩述宗，取捨任從。然諸經律，竝令落髮同僧，出家異俗，輒依論開，良恐非然；又論非宗要，宜就律儀。", "t": "如今把律與論兩家的宗旨都陳述出來，取捨聽任各人。然而諸多經律都教人剃落鬚髮，與僧眾相同地出家、與世俗有別；若動輒依論典的開許而行，恐怕不妥。何況論典並非本宗所宗的綱要，應當依從律中的規制。", "i": "u201-6", "n": 317, "s": "第10篇　具戒"}, {"v": "卷上", "o": "六、問：有人尼中作本法竟，將三兩尼送受戒人往僧寺，得否？答：依此律不得。故律云：「比丘尼僧應將受戒者，至大僧中。」既言是僧，云何許別？又受戒已，由勸言：「二部僧具足滿。」《僧祇》亦云：「尼受大戒，合二十眾。」又《五分》：「彼和尚、闍棃，須集十尼僧往比丘僧中乞戒。」故知僧、尼各須十人。", "t": "第六問：有人在尼眾中作完本法之後，只帶三、兩位比丘尼送受戒的人前往比丘僧寺受戒，這樣可以嗎？\n答：依本律是不可以的。律文說：「比丘尼僧應將受戒者至大僧中」，即比丘尼僧應把受戒的人帶到比丘僧中。既然說的是「僧」，怎能容許只由少數幾人個別前往呢？再者，受戒完畢之後的勸誡文中也說「二部僧具足滿」，就是比丘、比丘尼二部僧眾都必須足數。《僧祇律》也說，比丘尼受大戒須二部僧合共二十人。《五分律》又說，那邊的和尚尼、阿闍梨尼必須集合十位比丘尼僧，前往比丘僧中乞戒。由此可知，比丘僧與比丘尼僧各須十人。", "i": "u202", "n": 318, "s": "第10篇　具戒"}, {"v": "卷上", "o": "七、問：尼僧至僧寺受戒，須結界否？答：此之羯磨，二眾所秉，非界無以攝人，非界無以羯磨，各集本部重結穩審。又如尼懺僧殘，二眾各須結界。亦有諸師不立者，良恐誤也。若欲作法，尼僧盡集自然界內，令本法尼在自然界外。正結作時，不得對僧作法，須離聞處，遙見無妨。故律下文：「不應對尼作羯磨。", "t": "第七問：比丘尼僧前往比丘僧寺受戒，需要結界嗎？\n答：這個羯磨是僧、尼二部共同秉法的，沒有界就無從攝集人眾，沒有界就無從作羯磨。所以二部各自集合本部成員、重新結界，才穩妥審慎。又如比丘尼懺除僧殘罪時，二部僧也各自必須結界。也有一些律師主張不立此結界法，這恐怕是錯誤的。若要作結界法，尼僧全體集合在自然界之內，讓本法尼留在自然界之外。正式結界作法的時候，尼眾不可當著比丘僧眾作法，必須在僧眾聽不到聲音的地方，彼此遠遠望見則無妨。所以《四分律》下文說：僧眾不應當著比丘尼的面作羯磨。", "i": "u203", "n": 319, "s": "第10篇　具戒"}, {"v": "卷上", "o": "八、問：尼至僧寺，若為安置？答：應在二部僧中，長鋪兩席，使中間空容二、三尺許，令伸手相及。本法尼多者，總在離聞、著見處，一一喚來，入眾乞戒；受得戒已，在尼下行坐。", "t": "第八問：尼眾來到比丘僧寺，應當如何安置她們？\n答：應當在比丘、比丘尼二部眾之中，鋪設兩道長席，讓兩席中間空出二、三尺左右的距離，使雙方伸出手來仍能彼此相及。若本法尼人數眾多，就全部安排在聽不見作法聲音、卻仍看得見眾僧的地方，然後一個一個喚她們前來，進入眾中乞求受戒；得戒之後，便坐到尼眾的下首去。", "i": "u204", "n": 320, "s": "第10篇　具戒"}, {"v": "卷上", "o": "九、問：若為請師？答：比丘尼僧令闍棃將引受者，入禮僧已，教在戒師前，長跪請師言。", "t": "第九問：應當如何請師？答：比丘尼僧團指派阿闍棃引領受戒者進入大僧眾中；受戒者禮拜僧眾之後，阿闍棃再教她在戒師面前長跪，這樣啟請戒師說：", "i": "u205", "n": 321, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大德憶念！我某甲，今請大德為羯磨阿闍棃。願大德為我作羯磨阿闍棃，我依大德故，得受具足戒，慈愍故。", "t": "「請大德垂聽憶念：我某甲，現在請大德擔任羯磨阿闍梨。祈願大德為我擔任羯磨阿闍梨，我因依靠大德的緣故，得以受具足戒。懇請大德慈悲憐愍。」", "i": "u206", "n": 322, "s": "第10篇　具戒"}, {"v": "卷上", "o": "十、問：若為乞戒？答：威儀師教云。", "t": "第十問：應當怎樣乞求受戒？答：由威儀師教導她說：", "i": "u207", "n": 323, "s": "第10篇　具戒"}, {"v": "卷上", "o": "大德僧聽！我某甲，從和尚尼某甲，求受具足戒。我某甲，今從眾僧，乞受具足戒，和尚尼某甲。願僧救濟我，慈愍故。", "t": "「大德僧眾請聽：我某甲，依止和尚尼某甲，求受具足戒。我某甲，現在向僧眾乞求受具足戒。和尚尼是某甲。願僧眾慈悲憐愍，救拔濟度我。」", "i": "u208", "n": 324, "s": "第10篇　具戒"}, {"v": "卷上", "o": "威儀師復本坐已，大僧闍棃然後作法。問遮難已，又問：「汝學戒清淨否？」答：「學戒清淨。」更問餘尼等：「知此人學戒清淨否？」尼和尚答云：「學戒清淨。」然後僧作羯磨。", "t": "威儀師回到自己原本的座位坐好之後，比丘僧中的阿闍梨這才開始作法。他問完遮難之後，又問受戒者：「你學戒清淨嗎？」受戒者答：「學戒清淨。」接著再問其餘的尼眾：「你們知道這個人學戒是否清淨？」尼和尚回答說：「學戒清淨。」然後比丘僧才為她作羯磨。", "i": "u209", "n": 325, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第四戒相者，若據理論，當隨師具學，何獨此八？但為初受，未知輕重，遇緣便犯，因制八根本，若毀，不任僧用；餘篇枝條，懺便復淨。「族姓女聽！如來、無所著、至真等正學說八波羅夷法：比丘尼犯一一波羅夷，非比丘尼，非釋種女。", "t": "第四是戒相。若依道理來說，受戒之後本應跟隨師父把戒法全部學完，為什麼只說這八條呢？只是因為初受戒的人還不知道戒條的輕重，遇到境緣就會違犯，因此才規定在受戒時先宣說這八條根本戒；一旦毀犯，便不堪再為僧眾所用，不能再算入僧數之中。其餘各篇的戒只是枝條，犯了之後懺悔便恢復清淨。\n「族姓女，聽著！如來、無所著、至真、等正覺〔原作『等正學』〕宣說八波羅夷法：比丘尼若犯了其中任何一條波羅夷，就不是比丘尼，也不是釋種之女。」", "i": "u210", "n": 326, "s": "第10篇　具戒"}, {"v": "卷上", "o": "一、女人一切不得犯婬，作不淨行。若比丘尼犯不淨行，行婬欲法，乃至共畜生，彼非比丘尼，非釋種女。爾時世尊為說譬喻：猶如有人，截其頭，終不還活；比丘尼亦復如是，犯波羅夷已，還不成比丘尼行。汝是中盡形壽不得作，能持否。", "t": "一、女人，一概不得犯淫、做出不淨的行為。如果比丘尼犯了不淨行、行淫欲之事，乃至與畜生行淫，她就不是比丘尼，也不是釋種女。當時世尊為此說了一則譬喻：「就像有人被截斷了頭，終究不會再活過來；比丘尼也是如此，犯了波羅夷之後，就無法再成就比丘尼的行持。」妳在這件事上終身都不得去做，能持守嗎？", "i": "u211", "n": 327, "s": "第10篇　具戒"}, {"v": "卷上", "o": "二、一切不得作盜，下至艸葉。若比丘尼盜人五錢，若過五錢，若自取，若教人取，若自斷，若教人斷，若自斫，若教人斫，若燒、若埋、若壞色者，彼非比丘尼，非釋種女。譬如斷多羅樹心，終不復更生長；比丘尼犯波羅夷已，如是終不還成比丘尼行。汝是中盡行壽不得作，能持否。", "t": "第二，一切偷盜都不可以做，小到乃至一片草葉也不可偷。如果比丘尼偷取他人價值五錢、或超過五錢的財物；或是自己拿取、或教人拿取；或是自己砍斷、或教人砍斷；或是自己砍斫、或教人砍斫；或是燒毀、或是掩埋、或是毀壞物品的色澤——她就不再是比丘尼，也不再是釋種女。譬如截斷了多羅樹的樹心，它終究不會再繼續生長；比丘尼犯了波羅夷之後也是這樣，終究不能再成就比丘尼的行持。你在這當中，盡此一生都不可以做這樣的事，能持守嗎？", "i": "u212", "n": 328, "s": "第10篇　具戒"}, {"v": "卷上", "o": "三、一切不得故斷眾生命，下至蟻子。若比丘尼故自手斷人命，持刀授與人，教死、歎死、勸死，與人非藥，若墮人胎、厭禱、呪詛殺，自作方便，若教人作，彼非比丘尼，非釋種女。譬如鍼鼻缺，不堪復用；比丘尼亦如是，犯波羅夷已，不復還成比丘尼行。汝是中盡形壽不得作，能持否。", "t": "第三、任何情況下都不得故意斷絕眾生的生命，下至螞蟻也不得殺害。比丘尼若是故意親手斷絕他人性命、持刀交給別人、教人去死、稱讚死亡、勸人尋死、給人致命毒藥、使人墮胎、以厭魅禱祝或咒詛之法殺人，無論是自己施設殺害的方法，或是教唆他人去作，她就不再是比丘尼，不再是釋迦種族之女。就像針孔缺損，就不能再使用；比丘尼也是如此，犯了波羅夷罪之後，就不能再回復比丘尼的身分。你在這一條戒中，應當盡形壽不可違犯，能守持嗎？", "i": "u213", "n": 329, "s": "第10篇　具戒"}, {"v": "卷上", "o": "四、一切不得妄語，乃至戲笑。若比丘尼非真實、非己有，自言：「我得上人法，得禪、得解脫、得三昧正受，得須陀洹果、斯陀含果、阿那含果、阿羅漢果，天來、龍來、鬼神來供養我。」彼非比丘尼，非釋種女。譬如大石破為二分，終不還合；比丘尼亦如是，犯波羅夷已，不可還成比丘尼行。汝是中盡形壽不得作，能持否。", "t": "第四、一切都不得說妄語，乃至開玩笑也不得說。比丘尼如果所說不實、自己並未真正證得，妄自宣稱：我證得了過人之法，得到了禪定、得到了解脫、得到了三昧正受，證得了須陀洹果、斯陀含果、阿那含果、阿羅漢果，天人前來、龍前來、鬼神前來供養我，她就不再是比丘尼，不再是釋迦族的女弟子。就像大石頭斷裂破成兩半，終究不可能再復合；比丘尼也是如此，犯了波羅夷重罪之後，終究不能再恢復比丘尼的戒行。你在這一條戒中，盡此一生直到命終都不得違犯，能守持嗎？", "i": "u214", "n": 330, "s": "第10篇　具戒"}, {"v": "卷上", "o": "五、不得身相觸，乃至共畜生。若比丘尼有染心，與染心男子身相觸，從腋已下、膝已上，若捉、若摩、若牽、若推、若逆摩、若順摩、若舉、若下、若捉、若捺，彼非比丘尼，非釋種女。汝是中盡形壽不得作，能持否。", "t": "五、不得身體相互接觸，乃至與畜生身體接觸。如果比丘尼懷有愛染之心，與懷有愛染之心的男子在腋部以下、膝蓋以上的部位身體相互接觸，無論是抓握、撫摸、牽拉、推動、逆向撫摸、順向撫摸、舉起、放下、抓握，還是按壓，她就不是比丘尼，也不是釋種女。妳在這件事上盡此一生不得去做，能持守嗎？", "i": "u215", "n": 331, "s": "第10篇　具戒"}, {"v": "卷上", "o": "六、不得八事，乃至共畜生。若比丘尼受染汙心男子捉手、捉衣、入屏處、共立、共語、共行、共期、身相近，犯此八事，彼非比丘尼，非釋種女。汝是中盡形壽不得犯，能持否。", "t": "六、不得犯這八件事，甚至連對象是畜生也不可以。如果比丘尼〔懷有染污心〕，接受懷有染污心的男子捉她的手、拉她的衣，又與他進入隱蔽處、一同站立、一同交談、一同行走、彼此相約幽會、身體相互倚近，犯了這八件事，她就不再是比丘尼，也不再是釋種女。妳在這當中，盡此一生都不得違犯，能持守嗎？", "i": "u216", "n": 332, "s": "第10篇　具戒"}, {"v": "卷上", "o": "七、不得覆藏他重罪，乃至突吉羅惡說。若比丘尼知他比丘尼犯波羅夷罪，若不自舉、不向僧說、若不語眾多人，後於異時，此比丘尼若罷道、滅𢷤、若遮不共事、若入外道，後便作是說：「我先知有如是事。」彼非比丘尼，非釋種女，覆藏重罪故。汝是中盡形壽不得犯，能持否。", "t": "七、不得隱瞞他人的重罪，乃至突吉羅、惡說。如果有比丘尼知道另一位比丘尼犯了波羅夷罪，卻不親自舉發、不向僧團說明，也不告訴許多人；後來在別的時候，那位犯罪的比丘尼如果還俗、遭滅擯、被禁止參與共同事務，或加入外道，知情的這位比丘尼事後便這樣說：「我早先就知道有這樣的事。」那麼她就不是比丘尼，也不是釋種女，這是因為她隱瞞了重罪。在這件事上，妳終身不得違犯，能夠持守嗎？", "i": "u217", "n": 333, "s": "第10篇　具戒"}, {"v": "卷上", "o": "八、不得隨順被舉比丘語，乃至守園人及沙彌。若比丘尼知比丘為僧所舉，如法、如毗尼、如佛所制，不隨順、不懺悔，僧未與作共住，而隨順是比丘。諸比丘諫是比丘尼言：「妹知否？今僧舉此比丘，如法、如律、如佛所制，不隨順、不懺悔，僧未與作共住，汝莫隨順是比丘。」諸比丘諫是比丘尼時，堅持不捨，是比丘尼當三諫捨此事故，乃至三諫捨者善；不捨者，彼非比丘尼，非釋種女，由隨順故。汝是中盡形壽不得犯，能持否。", "t": "八、不得聽從被僧團舉罪的比丘的話，乃至守園人與沙彌的話，也同樣不得聽從。如果比丘尼明知某位比丘已被僧團舉罪，而僧團這項處分是如法、如毗尼、如佛所制定的；這位比丘不順從、不懺悔，僧團也還沒有讓他恢復共住，她卻仍去隨順這位比丘。諸位比丘尼便勸諫這位比丘尼說：「妹妹，你知道嗎？如今僧團舉罪這位比丘，是如法、如律、如佛所制定的；他不順從、不懺悔，僧團還沒有讓他恢復共住，你不要隨順這位比丘。」諸位比丘尼這樣勸諫她時，她仍堅持不肯捨棄。應當三次勸諫這位比丘尼，使她捨棄這件事；乃至經過三次勸諫，肯捨棄的很好；不肯捨棄的，她就不是比丘尼，不是釋種女，這是由於隨順他的緣故。你在這一條上，盡此一生都不得違犯，能受持嗎？", "i": "u218", "n": 334, "s": "第10篇　具戒"}, {"v": "卷上", "o": "次當為說四依法，防外道故，說此四，應語云：「族姓女諦聽！如來、無所著、至真等正覺說四依法，比丘尼依此得出家、受具戒、成比丘尼法。", "t": "接下來應當為她宣說四依法。這是為了防範外道的緣故，所以才宣說這四種依法。應當這樣對她說：「族姓女，專心聽！如來、無所著、至真、等正覺宣說四依法，比丘尼依靠這四法，得以出家、受具足戒，成就比丘尼之法。」", "i": "u219", "n": 335, "s": "第10篇　具戒"}, {"v": "卷上", "o": "一、依糞掃衣，比丘尼依是得出家、受具足戒、成比丘尼。汝是中盡形壽能持否？若得長利，檀越施衣、割截衣等，得受。", "t": "第一、依糞掃衣，也就是拾取他人丟棄的破布縫成的衣服：比丘尼依靠這樣的衣，得以出家、受具足戒，成為比丘尼。你在這件事上，盡此一生能不能受持？如果得到額外的利養，例如施主布施的衣、割截布片縫成的衣等，都可以接受。", "i": "u220", "n": 336, "s": "第10篇　具戒"}, {"v": "卷上", "o": "二、依乞食，比丘尼依是得出家、受具足戒、成比丘尼。汝是中盡形壽能持否？若得長利，若僧差食、若檀越送食、月八日食、十五日食、月初日食、若僧常食、檀越請食，得受。", "t": "第二、依靠乞食。比丘尼依此乞食，得以出家、受具足戒，成為比丘尼。你在這方面，盡此一生能夠受持嗎？如果得到額外的利養，不論是僧團依序差派的飲食、施主送來的飲食、每月八日的飲食、十五日的飲食、月初一日的飲食，或是僧團常設的飲食、施主迎請應供的飲食，都可以接受。", "i": "u221", "n": 337, "s": "第10篇　具戒"}, {"v": "卷上", "o": "三、樹下坐，比丘尼依是得出家、受具足戒、成比丘尼。汝是中盡形壽能持否？若得長利，若別房、尖頭屋、小房、石室、兩房一戶，得受。", "t": "第三、樹下坐，即以樹下作為坐臥的住處。比丘尼依此樹下坐，得以出家、受具足戒，成為比丘尼。你在這一項上，盡此一生都能受持嗎？如果得到額外的利養，不論是單獨別用的房舍、尖頂的屋舍、小房、石室、兩間房共用一個門戶的屋舍，都可以接受。", "i": "u222", "n": 338, "s": "第10篇　具戒"}, {"v": "卷上", "o": "四、依腐爛藥，比丘尼依此得出家、受具足戒、成比丘尼。汝是中盡形壽能持否？若得長利，酥、油、生酥、蜜、石蜜，得受。", "t": "第四、依腐爛藥。比丘尼依靠這一項，得以出家、受具足戒，成為比丘尼。你在這當中，盡此一生能不能奉持？如果得到額外的利養，如酥、油、生酥、蜂蜜、石蜜，也可以接受。", "i": "u223", "n": 339, "s": "第10篇　具戒"}, {"v": "卷上", "o": "汝已受戒竟，白四羯磨如法成就，得處所，和尚如法，阿闍梨如法，二部僧具足滿。汝當善受教法，應當勸生作福、治塔，供養佛法僧、和尚、阿闍棃。若一切如法教授，不得違逆，應學問、誦經、勤求方便，於佛法中得須陀洹果、斯陀含果、阿那含果、阿羅漢果。汝始發心出家，功不唐捐，果報不絕。餘所未知，當問和尚、阿闍棃。\n義云：先教誦六念，受持衣盋、坐具等。若作式叉尼時說淨長衣鉢者，應更請施主，總持說淨；若犯長財，竝捨，作突吉羅懺，然後說淨。又二時中請和尚教誡說法，具如下章說。", "t": "你已經受戒完畢：白四羯磨已如法成就，受戒的處所也已成就，和尚如法，阿闍梨如法，二部僧人數都已具足圓滿。你應當好好領受教法，應當勸化造福、修治佛塔，供養佛、法、僧以及和尚、阿闍梨。凡是一切如法的教授，都不得違逆。應當學習請問、讀誦經典，精勤尋求修道的方便，在佛法中證得須陀洹果、斯陀含果、阿那含果、阿羅漢果。你從最初發心出家起，功夫不會白費，果報也不會斷絕。其餘還不知道的，應當請問和尚、阿闍梨。\n依義解說：先教她誦習六念，並作法受持衣、缽、坐具等。如果在作式叉摩那（正學女）期間，已經對長衣、長缽作過說淨的，現在應重新請定施主，把那些衣缽一總重新說淨。如果曾犯了畜長財的過失，就要把長財全部捨出，作突吉羅的懺悔，然後再作說淨。又，在二時之中，都應請和尚教誡、說法，詳細內容如下章所說。", "i": "u224", "n": 340, "s": "第10篇　具戒"}, {"v": "卷上", "o": "第五遇緣退捨者，此律云：「若不樂淨行者，開聽捨戒去。若欲留五戒者，應言：『我作優婆夷。』若欲留十戒者，應言：『我作沙彌尼。』若欲全捨者，應言：『我作在家白衣。願大姉憶知我是白衣。』」《婆論》云：「若無出家人，可對捨，隨對一白衣、外道等前，但使情相領解，一捨便成，不須至三。」《增一阿含經》云：「開比丘七反捨戒，過者非法。」諸解竝許出家受具。然尼開捨戒還家，無文得許重來出家受戒，為女人志弱，不堪弘道；初尚不許，何容輒開後度？今時尼眾不學問者，多昏於志趣，妄行禪法，道言：「信施難消。」遂被惡人化令捨戒。大僧容可再歸，尼論一捨不還，無辜自墜，失於大利。故律云：「若有捨戒者，於佛法為死。」實由不解，致流昏俗也。永言此事，深可痛心。", "t": "第五，遇到因緣而退心捨戒的情形。《四分律》說：如果不樂於修清淨梵行，就開許聽任她捨戒離去。若想保留五戒，應說「我作優婆夷」；若想保留十戒，應說「我作沙彌尼」；若想連這些也全部捨盡，應說「我作在家白衣，願大姊憶知我是白衣」。\n《薩婆多論》說：如果沒有出家人可以作為面對面捨戒的對象，隨便在一位白衣或外道等人面前捨也可以，只要對方心裡領會明白所說的意思，說一遍捨戒便成就，不必說到三遍。\n《增一阿含經》說：開許比丘七次捨戒，超過七次就不如法。諸家的解釋都許可比丘捨戒之後再出家受具足戒。然而比丘尼雖然開許捨戒還家，卻沒有任何律文允許她重新回來出家受戒。因為女人意志薄弱，不能擔當弘揚佛道，當初尚且不許女人出家，哪裡會輕易開許日後再度剃度呢？\n當今尼眾不學習、不請教的人很多，對自己的志向趣向昏昧不明，胡亂修習禪法，聲稱信施難以消受，於是被惡人勸化，教她們捨戒。比丘捨戒後或許還可以再回來，說到比丘尼，一捨就不能再回來了。平白無故地讓自己墜落，喪失了出家的大利益。所以《四分律》說：如果有捨戒的人，在佛法中就等同於死亡。這實在是由於不通解律制，才致使她們流落沉迷於世俗。長歎此事，深深令人痛心。", "i": "u225", "n": 341, "s": "第10篇　具戒"}, {"v": "卷上", "o": "○六念篇第十一", "t": "○第十一篇：六念", "i": "u226", "n": 342, "s": "第11篇　六念"}, {"v": "卷上", "o": "第一念知日月大小法者，若是白月，應云：「今朝白月大，一日」乃至「十五日」，以白月一向大故，不須云小；若是黑月，便通大小：黑月大者，應云：「今朝黑月大，一日」乃至「十五日」，黑月小者：「今朝黑月小，一日」乃至「十四日」。此謂識去布薩日遠近，又防俗問故。解云：若入聚落，先知日月數等。", "t": "第一念，是了知日數與月的大小的方法。如果是白月，就應當說：「今天是白月大月第一日。」依此類推，一直念到第十五日；因為白月一律是大月，所以不必說「小」。如果是黑月，就兼有大月與小月兩種：黑月是大月時，應當說：「今天是黑月大月第一日。」依此類推，念到第十五日；黑月是小月時，就說：「今天是黑月小月第一日。」依此類推，念到第十四日。這樣作念，是要認清距離布薩日的遠近，同時也防備俗人問起日期。所以解釋說：「若要進入村落，應先知道月的大小與日數等。」", "i": "u227", "n": 343, "s": "第11篇　六念"}, {"v": "卷上", "o": "第二念知食處法者，全不受請者，應云：「我今不受請，自食己食」，或云：「食僧常食，不受請」，或云：「乞食，不受請」。若受請無供養者，應云：「我今自食，無請處」，或云：「我今食僧常食，無請處」，或云：「乞食，無請處」。若受請不背者，應云：「今有請處，念當自往。」若受請有背緣者，應云：「今有某緣，得背請。」若受多請者，應對人捨云：「今日有多請處，自受一請，餘者施與大姉，在某處。」若無人對，依《十誦》，依親里住尼，心念捨云：「我某甲，今朝檀越施我五正食，迴施比丘尼某甲，檀越於我不計，我得自恣食。", "t": "第二、憶念知道自己飲食處所的方法：如果完全不接受邀請的，應該念說：「我現在不接受邀請，自己吃自己的食物。」或者說：「我吃僧團的常食，不接受邀請。」或者說：「我乞食，不接受邀請。」如果受了請，卻沒有得到供養的，應該念說：「我現在自己吃，沒有受請的地方。」或者說：「我現在吃僧團的常食，沒有受請的地方。」或者說：「我乞食，沒有受請的地方。」如果受了請而不背棄這邀請的，應該念說：「今天有受請的地方，我打算親自前往。」如果受了請，而有可以背請（放棄赴請）的因緣的，應該念說：「今天有某某因緣，可以背請。」如果受了多處邀請的，應當對著人把多餘的請捨掉，念說：「今天有多處受請的地方，我自己接受其中一處，其餘的布施給大姉您，受請的地點在某某處。」如果沒有人可以相對作法，就依《十誦律》所說，依親里而住的比丘尼，以心念的方式捨請，念說：「我某某，今天施主布施我五種正食，我轉施給比丘尼某某；施主不再把我算在受供之列，我就可以隨意飲食。」", "i": "u228", "n": 344, "s": "第11篇　六念"}, {"v": "卷上", "o": "第三念知夏大小法者，若初受戒者，應云：「我於某年歲次在某，日月在一尺木若干影時，受具足戒，我今無夏。」後若有夏，隨夏多少稱之。", "t": "第三念，是知道自己夏臘多少的方法。如果是剛受戒的人，應當這樣說：「我在某年、干支歲次某某、某月某日，一尺高的木桿所量得的日影長若干的那個時刻，受了具足戒；我現在還沒有夏臘。」以後如果有了夏臘，就隨自己夏數的多少來稱說。", "i": "u229", "n": 345, "s": "第11篇　六念"}, {"v": "卷上", "o": "第四念知衣盋法者，若衣盋具受者，應云：「我五衣、盋具足受持。」若長衣、盋、藥等求說者，應云：「念當說淨。」犯長者，應云：「今有長財，念當說淨。", "t": "第四、憶念了知衣缽的方法：如果五衣和缽都已具足受持，就應當說：「我的五衣和鉢都已具足受持。」如果有超量的衣、缽、藥等，想要為它們作說淨的，就應當說：「我心裡記著：應當為這些長物作說淨。」如果已經犯了畜長的過失，就應當說：「我現在有超量的財物，心裡記著應當為它作說淨。」", "i": "u230", "n": 346, "s": "第11篇　六念"}, {"v": "卷上", "o": "第五念知別眾食法者，若有別眾者，云：「今有某緣，得別眾食。」或病、迦提月等。若無緣者，應云：「念不別眾食。", "t": "第五念，是了知別眾食的方法。如果有別眾食的情形，就說：「我今天有某種因緣，得以別眾食。」例如生病、迦提月等。如果沒有因緣，就應該說：「我當留意，不別眾食。」", "i": "u231", "n": 347, "s": "第11篇　六念"}, {"v": "卷上", "o": "第六念知病之有無法者，若有病：「念當療治。」無者，應云：「隨眾行道。", "t": "第六念，是知道自己有病或無病的方法：如果有病，就應當說：「我打算去療治。」如果沒有病，就應當說：「我隨大眾一起修行辦道。」", "i": "u232", "n": 348, "s": "第11篇　六念"}, {"v": "卷上", "o": "○受衣篇第十二", "t": "第十二篇　受衣", "i": "u233", "n": 349, "s": "第12篇　受衣"}, {"v": "卷上", "o": "此篇大門一十有七：一、制聽，二、功能，三、釋名，四、財如，五、體如，六、色如，七、量如，八、條數，九、隄數，十、重數，十一、作法，十二、受法，十三、捨法，十四、得失，十五、補浣，十六、敬護，十七、坐具。", "t": "這一篇大分為十七門：一、佛制規定必須畜用、違犯便結罪，與隨緣開許畜用、畜用與否都沒有過失；二、功能；三、解釋名稱；四、財物如法；五、衣體如法；六、顏色如法；七、尺寸如法；八、衣條的數目；九、橫堤的數目；十、衣的層數；十一、裁製的方法；十二、受持的方法；十三、捨去的方法；十四、得與失；十五、縫補與洗滌；十六、恭敬護持；十七、坐具。", "i": "u234", "n": 350, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第一制聽者，所以名制者，謂五衣、六物，佛制令畜，違便得罪；所以言聽者，謂一切長衣及百一供身具等，隨報開聽，違順無過。", "t": "第一門辨明「制」與「聽」。之所以名為「制」，是指比丘尼受持的五衣與六物，佛陀制定必須蓄備，違背佛制而不蓄備便得罪。之所以名為「聽」，是指一切多餘的長衣以及百一供身具等種種資身用具，隨各人果報身的所需而開許聽任，不蓄或蓄用都沒有過失。", "i": "u235", "n": 351, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第二功能者，婆論云：欲現未曾有法故，一切九十六種外道無此衣名，為異外道故。智論云：佛聖弟子住於中道故，制著三衣；不同外道裸身無恥，白衣多貪故重著也。", "t": "第二是功能。《婆論》說：這是為了顯現前所未有的法；一切九十六種外道都沒有這樣的衣名，是為了與外道有別。《智論》說：佛的聖弟子安住於中道，所以制令穿著三衣，既不像外道那樣裸身無恥，也不像在家人那樣因貪欲多而層層穿著。", "i": "u236", "n": 352, "s": "第12篇　受衣"}, {"v": "卷上", "o": "分別功德論云：為三時故，制有三衣：冬則著重，夏則著輕，春則著中；亦障諸蟲故。此律：寒故制著三衣，又為三世如來竝著如是衣。義云：為調三毒因緣故，制三衣。華嚴經云：著袈裟者，捨離三毒也。", "t": "《分別功德論》說：為了三季的緣故，制有三衣——冬天穿厚重的，夏天穿輕薄的，春天穿適中的；也為了遮蔽各種蟲類。本律說：因為寒冷，所以制令穿著三衣；又因為三世如來都穿著這樣的衣。依義理說：為了調伏三毒的因緣，所以制立三衣。《華嚴經》說：穿著袈裟的人能捨離三毒。", "i": "u236-2", "n": 353, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大悲經云：但使性是沙門，汙沙門行；形是沙門，被袈裟者，於彌勒佛乃至樓至佛所，得入涅槃，無有遺餘。", "t": "《大悲經》說：只要體性上還是沙門，卻污損了沙門的行持，外形上是沙門、披著袈裟的人，在彌勒佛乃至樓至佛那裡，都能得入涅槃，沒有一個被遺漏。", "i": "u236-3", "n": 354, "s": "第12篇　受衣"}, {"v": "卷上", "o": "悲華經云：如來於寶藏佛所發願：「成佛時，我袈裟有五功德：一者、入我法中，或犯重、邪見等四眾，於一念中，敬心尊重，必於三乘受記；二者、天龍人鬼，若能恭敬此人袈裟少分，即得三乘不退；", "t": "《悲華經》說：如來在寶藏佛處發願：我成佛時，我的袈裟有五種功德。一者，入我法中的四眾弟子，即使犯了重罪、起了邪見等，只要在一念之間以恭敬心尊重袈裟，必定能在三乘中得授記。二者，天、龍、人、鬼若能恭敬這個人身上袈裟的一小部分，就能在三乘中得不退轉。", "i": "u236-4", "n": 355, "s": "第12篇　受衣"}, {"v": "卷上", "o": "三者、有鬼神、諸人得袈裟乃至四寸，飲食充足；四者、若眾生共相違反，念袈裟力，尋生悲心；五者、若在兵陣，持少分恭敬尊重，常得勝他。若我袈裟無此五力，則欺十方佛。」", "t": "三者，若有鬼神與諸人得到袈裟，乃至只有四寸，飲食就能充足。四者，若眾生彼此互相違逆衝突，憶念袈裟的力量，隨即生起悲心。五者，若在戰陣之中持著袈裟的一小部分，恭敬尊重，就常能勝過對方。假使我的袈裟沒有這五種力用，那就是欺誑十方諸佛。", "i": "u236-5", "n": 356, "s": "第12篇　受衣"}, {"v": "卷上", "o": "僧祇云：僧尼有戒德，俗人索破袈裟段欲禳災者，得與小者。伽論：僧尼等破壞三衣、盋，犯自性偷蘭遮；但是衣、盋，不問受持、不受，皆不得壞滅，亦不應破滅補衣、賣之、雜用，皆犯前罪。", "t": "《僧祇律》說：有戒德的比丘、比丘尼，若在家人索取破舊袈裟的布片，想用來禳除災禍，可以給小片的。《伽論》說：比丘、比丘尼等破壞三衣與缽，犯自性偷蘭遮罪。只要是衣、缽，不論已受持或未受持，都不得毀壞；也不應拆破它、拿去補綴其他衣物、變賣，或挪作其他雜用，以上各項都犯前面所說的自性偷蘭遮罪。", "i": "u236-6", "n": 357, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第三釋衣名者，此律云：聽刀割壞，成沙門衣，不為怨賊所劫，作安陀會襯身著，鬱多羅僧、僧伽梨入眾時著。然此衣名，諸部竝無正翻，今以義推，略知指歸。慧上經云：五條者，名中著衣；七條者，名上著衣；大衣者，名眾集衣。義云：大衣者，名雜衣，以條數多故；若從用立名，入王宮聚落衣。七條者，名中價衣；從用為名，入眾衣。五條者，下著衣；從用為名，道行作務衣。", "t": "第三，解釋三衣的名稱。《四分律》說：佛聽許用刀割截破壞布料，做成沙門的衣，不會被怨賊劫奪；又聽許做安陀會五條衣貼身穿著，鬱多羅僧七條衣、僧伽梨大衣則在入眾時穿著。然而這些衣的名稱，各部律中都沒有正式的意譯，現在依義理推求，大略可知它們的意旨所在。《慧上經》說：五條衣名叫「中著衣」，七條衣名叫「上著衣」，大衣名叫「眾集衣」。依義理解釋說：大衣又叫「雜衣」，因為它條數多的緣故。如果就用途來立名，大衣稱為「入王宮聚落衣」；七條衣名叫「中價衣」，就用途立名則稱「入眾衣」；五條衣名叫「下著衣」，就用途立名則稱「道行作務衣」，也就是行路、做事時穿的衣。", "i": "u237", "n": 358, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第四財如者，謂非四邪，及自手興生、出舉、販博得財，竝不如法，受亦不成。故律云：不以邪命、激發得、現相得、犯捨墮衣等，竝不得作三衣。", "t": "第四、「財如」：是指衣財不得來自四種邪命，也不得是自己親手經營生利、放貸取息、販賣交易所得的財物；這些都不如法，用這樣的衣財來受持三衣，受法也不能成立。所以《四分律》說：凡邪命所得的衣、激發人心令施所得的衣、詐現異相所得的衣，以及犯捨墮罪的衣等，都不得用作三衣。", "i": "u238", "n": 359, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第五體如者，義云：要須厚重者得；若細薄生疎露體，乃至綾羅、綿繡、文綺衣等，竝不成受。僧祇云：一切生疎、毛髮、樹皮、艸衣等，不成受。五百問云：生絹不作三衣，若不現身者得。", "t": "第五、衣體如法：依義理說，衣料必須厚實，才能如法受持；若是細薄、未經煮練而織得稀疏，或是衣料透明、會露出身體，乃至綾、羅、絲綿、刺繡、有紋彩的綺等衣料，受持都不成就。《僧祇律》說：一切未經煮練而織得稀疏的衣、毛髮衣、樹皮衣、草衣等，受持都不成就。《五百問論》說：未經煮練的生絹不得作三衣；如果不會露出身體，就可以。", "i": "u239", "n": 360, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第六色如者，此律云：上色染衣不得畜，當壞作袈裟色。十誦云：一切青、黃、赤、白、黑五種純大色衣不得著，除其納衣。婆論云：五大色衣不成作三衣，又紫艸、柰皮、地黃、紅緋染色、黃櫨木等，皆不如法色。", "t": "第六、色如，即顏色如法。本律說：用上等鮮豔之色染成的衣不得蓄留，應當染壞，改成袈裟色。《十誦律》說：一切純用青、黃、赤、白、黑五種大色的衣都不得穿著，只有碎布補綴成的衲衣例外。《薩婆多論》說：五大色的衣不能作成三衣。又，紫草、柰樹皮、地黃、紅緋染色、黃櫨木等所染出的顏色，都是不如法色。", "i": "u240", "n": 361, "s": "第12篇　受衣"}, {"v": "卷上", "o": "若五大色衣三點淨，得作餘衣著，謂紺、黑、青。得早、木蘭，一切得受；純青、淺青、碧等，點淨得作衣裏用；若赤、白、黃不純大色者，亦得。若不如法色染訖，更以如法色覆成受持。文殊問經云：色衣不太赤、不太黃、不太黑、不太白，清淨如法色，三法服及與餘衣，皆如是色。", "t": "若是五大色的衣，作三點淨之後，可以作成三衣以外的餘衣穿著；點淨所用的就是紺、黑、青三色。若是皂色、木蘭色，則一切衣都可受持。純青、淺青、碧等色，點淨之後可以用作衣的襯裡。赤、白、黃三色，只要不是純正的大色，也可以這樣用。如果已用不如法的顏色染過，再用如法的顏色覆蓋重染，就能成就受持。《文殊問經》說：染色的衣不太赤、不太黃、不太黑、不太白，這就是清淨如法的顏色；三種法衣以及其餘的衣，都要用這樣的顏色。", "i": "u240-2", "n": 362, "s": "第12篇　受衣"}, {"v": "卷上", "o": "義云：作淨法者，用前紺、黑、青，於四角頭隨意作一點。僧祇云：極大如四指，極小如豌豆。見論：如麻子大。僧祇云：不得竝作，或一、三、五、七、九等，不得如華形作；若浣褻泥汙，即名淨。若新僧伽梨，趣一角頭作，乃至一切衣新時亦爾。若眾多破段衣一處合補者，一處作淨。青者，謂銅青；黑者，謂雜泥等染；木蘭者，謂果汁等。", "t": "依義而言：作點淨的方法，是用前面所說的紺、黑、青三色，在衣的四個角上任選一處作一個點。《僧祇律》說：點最大如四指寬，最小如豌豆。《善見論》說如麻子那麼大。《僧祇律》又說：不得成雙併排地作點，可作一點、三點、五點、七點、九點等單數點；也不得排成花朵的形狀。衣服若經洗滌、穿舊或沾染泥污，就已算是作淨了。若是新作的僧伽梨大衣，任取一個角頭上作點；乃至一切衣，在新製成時也都如此。若是把許多破碎布片合補在一處，只在一處作淨就可以。所謂青，是指銅青；所謂黑，是指用雜泥等染成的色；所謂木蘭，是指用果汁等染成的色。", "i": "u240-3", "n": 363, "s": "第12篇　受衣"}, {"v": "卷上", "o": "義云：蜀地有木蘭樹皮，其色赤黑，然復鮮明，可以為染，微有香氣；關東、并州亦有木蘭樹子，堪為數珠，兼得為染，其色稍黑；京內諸山亦有，求之者希。", "t": "依義而言：蜀地有木蘭樹，樹皮的顏色赤黑，而且鮮明，可以用來染色，微微帶有香氣。關東、并州也有木蘭樹，其果實可以作念珠，也可以用來染色，染出的顏色稍偏黑。京城一帶的諸山也有，只是去尋求的人很少。", "i": "u240-4", "n": 364, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第七量如者，此律云：五條長四肘，廣二肘；大衣、七條各長五肘，廣三肘；若極小者，長四肘，廣二肘半，竝名如法。若過此分齊，亦得受持，以可截故。若過量外者，應說淨；否者，犯捨。義云：說時應在受持後，以法衣外為長故。", "t": "第七是「量如」，即衣的尺寸合乎律制。《四分律》說：五條衣長四肘、寬二肘；大衣與七條衣各長五肘、寬三肘。若是極小的尺寸，長四肘、寬二肘半，也都稱為如法。若超過這個尺寸限度，仍然可以受持，因為多出的部分能夠截去。若衣上仍有超出法定量度之外的多餘部分，就應當對這多餘部分說淨；不這樣做，便犯捨墮罪。依義理說：說淨應當在受持之後進行，因為已受持的法衣以外的部分，才算作長衣。", "i": "u241", "n": 365, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第八條數者，此律：大衣從九條乃至十九條等，若過是數，亦應畜。七條、五條，名自楷定。婆論云：僧伽梨三品：九條、十一、十三，是下品；十五、十七、十九，是中品；二十一、二十三、二十五，名上品。", "t": "第八是條數：《四分律》說，大衣從九條乃至十九條等；若超過這個條數，也聽許畜用。至於七條衣和五條衣，名稱本身就固定了條數。《薩婆多論》說：僧伽梨大衣分為三品——九條、十一條、十三條是下品；十五條、十七條、十九條是中品；二十一條、二十三條、二十五條是上品。", "i": "u242", "n": 366, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第九隄數者，此律不了，今依婆論云：大衣下者，兩長一短；上者，四長一短，竝名如法。若互增減者，成受持，著用得小罪。", "t": "第九是堤數，即每條衣中長段、短段的數目。這一點《四分律》說得不明確，現在依《薩婆多毘尼毘婆沙》所說：大衣下品的，每條作「兩長一短」，即兩段長、一段短；上品的，每條作「四長一短」，即四段長、一段短，這些都稱為如法。如果把長、短的段數互相增減，受持仍然成立，但穿著使用便犯小罪。", "i": "u243", "n": 367, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十重數者，此律云：大衣新者兩重，餘二衣一重；故者，隨意多少作。", "t": "第十是衣的層數：《四分律》說：新做的大衣僧伽梨要用兩層布，其餘七條衣與五條衣這兩種用一層布；這三衣若是舊衣，則隨自己的意思，要用多少層來做都可以。", "i": "u244", "n": 368, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十一作法者，此律云：大衣、七條要須割截，五條得襵葉作。五分云：若染縵衣作條，又縫葉著衣，或襵作衣葉，或半向上、半向下作葉，一切突吉羅。阿難奉教作衣，左條左靡，右條右靡，中條葉兩向靡。若得衣不足，乃至一長一短作；猶少者，聽帖葉作；乃至不足，聽作縵安多會。僧祗云：作葉極廣四指，極狹如𪍿麥，不得橫葉相當。縫衣，後時宣脫，應作馬齒縫；衣上下破，應安緣，要須却刺。十誦云：佛教比丘施䩙紐，前去緣四指施䩙，後去緣八指施紐，應作是法。又却刺者，是佛所許，如法畜用；直縫者不得，是世人衣，為異俗故，又為防外道故。此律但云縫僧伽棃，不論却刺，用十誦者好。三千威儀云：三衣令帖四角。此律：應安䩙紐，肩上帖障垢膩處。", "t": "第十一、作法：《四分律》說：大衣與七條衣必須割截布料縫成，五條衣則可以用「襵葉」的方式作，就著整幅衣料摺襵出條葉的相狀。\n《五分律》說：若把沒有條葉的整幅縵衣染出條相，或把另裁的布葉縫綴在衣上，或摺襵布料作出衣葉，或把衣葉一半朝上、一半朝下地作，這一切都犯突吉羅罪。阿難遵照佛的教導作衣：左邊各條的葉向左傾倒，右邊各條的葉向右傾倒，中間一條的葉則向左右兩邊傾倒。如果所得的衣料不足，就依次減降，乃至只作一長一短；若還是太少，聽許用帖葉的方式作，把另裁的布葉貼縫在整幅衣上；乃至連這樣也不夠，就聽許作縵安陀會，即整幅沒有條葉的下衣。\n《僧祇律》說：作衣葉，最寬四指，最窄如穬麥粒；不得讓各條橫向的葉縫平齊相對。縫成的衣，日子久了容易綻開脫線，所以應當作馬齒縫。衣的上下端破損，應當安上緣邊，而且必須用卻刺的回針倒縫法。\n《十誦律》說：佛教導比丘安設䩙與紐，即衣上扣合用的鉤與襻，前面離衣緣四指處安䩙，後面離衣緣八指處安紐，應當照這樣作。又，卻刺是佛所聽許的，這樣縫的衣才可如法畜用；直縫的則不許，因為那是世人衣服的作法，為的是與世俗有別，也為了防範外道。本律只說「縫僧伽梨」，不曾論及卻刺，採用《十誦律》的規定較好。\n《三千威儀》說：三衣要在四角貼布。本律說：應當安設䩙、紐；肩上要貼布，遮住沾染垢膩的地方。", "i": "u245", "n": 369, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十二受法者，此律但云三衣應受持，而無受文；今依十誦明其受法。大衣者，隨其條數多少稱之。今且受十五條文，餘者準說可知。", "t": "第十二是受持的作法。《四分律》只說三衣應當受持，卻沒有記載受持時所念的文句，現在依《十誦律》來說明受持的作法。大衣要隨著它條數的多少，稱說相應的條數；這裡先舉出受持十五條衣的文句為例，其餘各種條數的，比照這樣的說法就可以明白了。", "i": "u246", "n": 370, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此僧伽棃十五條衣受，三長一短割截衣持。」\n受七條。", "t": "「大姊，請專心聽我說：我比丘尼某甲，現在受這件僧伽梨十五條衣，作為三長一短的割截衣來受持。」\n接著是受持七條衣的作法文。", "i": "u247", "n": 371, "s": "第12篇　受衣"}, {"v": "卷上", "o": "人姉一心念！我比丘尼某甲，此鬱多羅僧七條衣受，兩長一短割截衣持。」 \n受五條。", "t": "「大姊，請專一心念：我比丘尼某甲，這件鬱多羅僧七條衣，我今領受；每條兩長一短、割截縫成的衣，我今受持。」\n受五條衣的文：", "i": "u248", "n": 372, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此安陀會五條衣受，一長一短割截衣持。」\n受縵條衣文云。", "t": "「大姊，請一心專注憶念：我比丘尼某甲，領受這件安陀會五條衣，作為一長一短割截而成的衣受持。」\n領受縵條衣的作法文說：", "i": "u249", "n": 373, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此縵僧伽棃受持。", "t": "大姊請專心憶念：我比丘尼某甲，這件縵僧伽梨，我現在受持。", "i": "u250", "n": 374, "s": "第12篇　受衣"}, {"v": "卷上", "o": "此律五條開屈葉者，應云「屈葉衣持」；若帖葉作者，應云「帖葉衣持」。帖時開一邊、刺一邊，令似割截衣；若兩邊俱刺者，但同縵衣法。", "t": "《四分律》開許五條衣以屈襵作葉的方式製作，受衣時就應說「屈葉衣持」，表示作為屈葉衣來受持；若是貼縫衣葉作成的，就應說「帖葉衣持」，表示作為帖葉衣來受持。貼葉時，要留一邊不縫、只縫另一邊，使它看起來像割截衣；如果兩邊都縫合，那就只與縵衣的受法相同了。", "i": "u251", "n": 375, "s": "第12篇　受衣"}, {"v": "卷上", "o": "受僧祇支文。", "t": "受持僧祇支衣時所用的作法文詞。", "i": "u252", "n": 376, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，是衣厥修羅受，長四肘，廣二肘半，是厥修羅衣持。", "t": "大姊，請專心憶念：我比丘尼某甲，這件厥修羅衣，我現在領受；長四肘、寬二肘半；這件厥修羅衣，我現在受持。", "i": "u253", "n": 377, "s": "第12篇　受衣"}, {"v": "卷上", "o": "僧祇支者，長四磔手，廣二磔手半，互減、互過者提；覆肩衣義準亦然。義云：僧祇支者，此云上狹下廣衣；云厥修羅者，此西國方言不同，故翻譯有二，設互牒二文，於理無乖；或量己身大小作之。受時但云「僧祇支應量作」，合受持。尼本為露胸膊行，為世人譏慢，故佛制畜祇支、覆肩二衣。", "t": "僧祇支長四磔手、寬二磔手半；無論不足或超過這個尺寸，都犯波逸提。覆肩衣依義理類推，也同樣如此。《義鈔》說：「僧祇支」，這裡譯為「上窄下寬的衣」；至於稱它為「厥修羅」，這是因為印度各地方言不同，所以翻譯出來有兩個名稱。即使在受持文中交互使用這兩個名稱，於理也無違背。或者按照自己身體的大小來製作；受的時候只說「僧祇支應量作」，就可以受持。比丘尼原本因為袒露胸部和手臂行走，被世間人譏笑輕慢，所以佛陀規定她們蓄持僧祇支與覆肩衣這兩種衣。", "i": "u254", "n": 378, "s": "第12篇　受衣"}, {"v": "卷上", "o": "受覆肩衣文。", "t": "受持覆肩衣的作法文。", "i": "u255", "n": 379, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此是覆肩衣如法作，今受持。", "t": "大姊，請專心憶念：我比丘尼某甲，這件是如法製作的覆肩衣，現在受持。", "i": "u256", "n": 380, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十三捨衣法者，本律無文，今依僧祇捨云。", "t": "第十三、捨衣的方法：本部《四分律》中沒有捨衣的明文，現在依照《摩訶僧祇律》的作法來捨，文中這樣說：", "i": "u257", "n": 381, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此僧伽棃是我五衣數，先受持，今捨。", "t": "大姊，請專心聽我說：我比丘尼某甲，這件僧伽梨是我五衣之一，先前已受持，現在捨去。", "i": "u258", "n": 382, "s": "第12篇　受衣"}, {"v": "卷上", "o": "若一時受捨，越毗尼。", "t": "若將多衣一併受持或一併捨去，則犯越毗尼罪。", "i": "u259", "n": 383, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，是衣厥修羅如法作，先受持，今捨。", "t": "大姊，請一心專注聽我陳說：我比丘尼某甲，這件厥修羅衣是如法製作的，先前已受持，現在捨去。", "i": "u260", "n": 384, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，是覆肩衣如法作，先受持，今捨。", "t": "大姊，請一心專注聽我陳說：我比丘尼某甲，這件覆肩衣是如法製作的，先前已受持，現在捨去。", "i": "u261", "n": 385, "s": "第12篇　受衣"}, {"v": "卷上", "o": "又依五分云。", "t": "另外又依《五分律》說：", "i": "u262", "n": 386, "s": "第12篇　受衣"}, {"v": "卷上", "o": "我比丘尼某甲，此僧伽棃若干條，今捨。", "t": "「我比丘尼某甲，此僧伽棃若干條，今捨。」意思是：我比丘尼某甲，這件僧伽梨大衣有若干條，現在捨去對它的受持。", "i": "u263", "n": 387, "s": "第12篇　受衣"}, {"v": "卷上", "o": "下二衣類說可解。僧祇云：若至他家，忘不持三衣去，到彼憶已，應遙捨之；捨竟，應權借俗人衣被，作淨安鈎紐受。義云：知比丘有僧尼長衣，借受彌善；欲還應捨，到本處已，更受舊衣，不犯捨墮。十誦云：借衣離宿，但懺提罪，不復須捨。", "t": "其餘下二衣，即鬱多羅僧與安陀會，其捨詞比照上文類推陳說即可明白。《摩訶僧祇律》說：如果要到別人家去，忘了帶三衣就出門，到了那家才想起來，這時應當遙對三衣作法，捨去它們的受持。捨完之後，應當權宜借用俗人的衣服或被褥，先作淨、安上鉤與紐，再作法受持。鈔主依義理補充說：若知道比丘那裡有比丘或比丘尼的長衣，能借來受持就更好。要回去時，應當先捨去借來受持的衣；回到本處之後，再重新受持原來的舊衣，這樣就不犯捨墮罪。《十誦律》說：借來的衣受持之後，若人與衣相離而過夜，只須懺悔波逸提罪，不必再作捨衣法。", "i": "u264", "n": 388, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十四得失者，五分云：諸比丘不捨先受持衣，更受餘衣者，成受，先三衣說淨者亦成；由不捨故，但犯小罪。此律：若失想、燒想、賊奪想、水漂想，則失受持；得者還須更受，以忘失故，無捨罪。若道逢難緣，不得會衣者，不失受持。婆論云：三衣不受持，有壞威儀、缺衣二罪。若本說淨，今作三衣，即失本淨法。又捨此衣，更受餘衣，前衣即須說淨；否者，過十日犯長。婆論云：若三衣破，不問孔大小，但使緣不斷，不失受持；尼祇支、覆肩衣義準此說。", "t": "第十四，受持法的失與得。《五分律》說：諸比丘沒有先捨去原先受持的衣，就又受持別的衣，這新的受持仍然成立；把原先受持的三衣改作說淨的，說淨也同樣成立。只是因為沒有先作捨法，所以犯一個小罪。《四分律》說：若生起衣已失落想、衣被火燒想、衣被賊奪走想、衣被水漂走想，受持之法就失去；日後若再取得那件衣，必須重新作受持法。由於已作衣已失落等想的緣故，所以不犯捨墮罪。若在路上遇到危難等因緣，無法到衣的所在處與衣相會，受持之法則不失去。《薩婆多論》說：三衣不作法受持，有破壞威儀與缺少三衣這兩種罪。若衣本來已作過說淨，現在拿來作三衣受持，原先的說淨法就失去。又，若捨去此衣而改受其他的衣，先前那件衣就必須說淨；否則超過十日，便犯長衣罪。《薩婆多論》又說：三衣若破損，不論破孔大小，只要衣緣沒有斷裂，就不失受持。比丘尼的祇支衣與覆肩衣，依義理也比照這裡所說的辦理。", "i": "u265", "n": 389, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十五補浣者，十誦云：以小段物補衣，若却刺者，不須說淨、點淨；若直縫者，段段須說；否者，段段得二罪，謂不說淨、不點淨也。見論云：若衣欲破，未穿壞者，或一條、二條，應先以物補，後割却故者，不失受。三衣背處欲破，當轉著兩邊，先相連著，後以刀破開，然後却刺緣，不失受持。袈裟若大減却，若小物裨，亦不失受；若浣增色，亦不失受。此律：三衣壞，隨孔大小方圓補治。", "t": "第十五是補衣與洗浣。《十誦律》說：用小塊布補衣，如果是用「卻刺」縫上的，就不必作說淨和點淨；如果是用「直縫」縫上的，那麼每一塊補布都必須說淨，否則每一塊各得兩項罪，就是不說淨與不點淨的罪。\n《善見論》說：如果衣將要破而尚未穿孔損壞，不論是一條、兩條如此，都應先用布補上，然後割除舊破的部分，這樣不失受持。三衣背部將要破時，應當把它轉移到兩邊去：先縫合接連，再用刀割開，然後以卻刺縫好衣緣，也不失受持。袈裟如果太大而割去多餘的部分，或太小而用小塊布補添，也都不失受持。若是洗浣，或是加染使色澤加深，也都不失受持。本律（《四分律》）說：三衣破損時，隨破孔的大小與方圓形狀加以修補。", "i": "u266", "n": 390, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十六敬護者，十誦云：護三衣如自皮，鉢如己眼。著大衣者，不得摙木、石、土、艸，掃地、敷具等，又不得脚躡、敷坐臥上，及襯身著；若不持三衣入聚落俗人處，犯吉羅。", "t": "第十六是敬護。《十誦律》說：愛護三衣要如同愛護自己的皮膚，愛護缽要如同愛護自己的眼睛。穿著大衣的人，不得搬運木材、石頭、泥土、草，不得掃地、鋪設坐具臥具等；也不得用腳踩踏大衣、把它鋪在坐處臥處上，以及貼身當襯衣穿。若不帶三衣進入聚落在家人處，犯突吉羅罪。", "i": "u267", "n": 391, "s": "第12篇　受衣"}, {"v": "卷上", "o": "遺教三昧經云：比丘行時，僧伽棃、袈裟、衣、鉢、鍚杖等，當與身俱，不得去身六尺。五百問事云：不能著大衣入聚落，但持著肩上行，無犯。", "t": "《遺教三昧經》說：比丘行走時，僧伽梨、袈裟衣、缽、錫杖等應當隨身，不得離開身體六尺以外。《五百問事經》說：若不能穿著大衣進入聚落，只要把大衣持放在肩上行走，就不犯。", "i": "u267-2", "n": 392, "s": "第12篇　受衣"}, {"v": "卷上", "o": "僧祇云：敬三衣如塔。若入聚落，必須帶紐行；若無紐者，用鍼綴；無鍼者，下至手捉。若無紐，隨入家家得越心悔；有而不著，亦越毗尼。披時當通肩披，齊兩角，左手捉時，不得手中出角頭如羊耳。律中：至佛前、上座所，竝令偏袒。經中：通肩披衣，五百世中入鐵甲地獄。", "t": "《僧祇律》說：恭敬三衣如同恭敬佛塔。若要進入聚落，必須繫帶扣紐而行；沒有鉤紐的，就用針把衣綴住；連針也沒有的，至少也要用手捉住衣。若衣上沒有鉤紐，隨著進入每一家，都得一個「越心悔」罪，只須責心懺悔；有鉤紐卻不扣上，也得「越毗尼」罪。披衣時應當通肩披，使兩角齊平；用左手捉衣時，不得讓衣角頭從手中露出來，像羊耳朵那樣。律中規定：到佛前、上座處，都要偏袒右肩；經中則說：在佛前、上座處通肩披衣，五百世中墮入鐵甲地獄。", "i": "u267-3", "n": 393, "s": "第12篇　受衣"}, {"v": "卷上", "o": "五分云：得四褺大衣枕之。中阿含經多處有文：開枕大衣，臥七條中。", "t": "《五分律》說：可以把大衣摺成四疊當作枕頭來枕。《中阿含經》多處有文，開許枕著大衣、睡臥在七條衣中。", "i": "u267-4", "n": 394, "s": "第12篇　受衣"}, {"v": "卷上", "o": "三千威儀經云：不著泥洹僧，不得著僧祇支；如是重重，乃至最上著僧伽棃。故知三衣得上下重著也。", "t": "《三千威儀經》說：不穿泥洹僧下裙，就不得穿僧祇支；這樣一層層上去，直到最上面穿僧伽梨。由此可知，三衣是可以上下重疊穿著的。", "i": "u267-5", "n": 395, "s": "第12篇　受衣"}, {"v": "卷上", "o": "五分云：若出村，為艸木鈎衣破裂，塵入葉中，聽為護衣故，聚落外反著衣；下數壞，聽倒著衣，上下安鈎紐及帶；雨時不應倒著。", "t": "《五分律》說：若出村時，衣被草木鉤住而破裂、塵土進入衣葉之中，聽許為了護衣的緣故，在聚落外把衣反過來穿；衣的下擺屢屢損壞，聽許把衣上下顛倒著穿，並在上下都安上鉤紐和帶子；下雨時則不應倒著穿。", "i": "u267-6", "n": 396, "s": "第12篇　受衣"}, {"v": "卷上", "o": "此律：尼不著祇支入白衣舍，提。毗尼母及此律：袈裟不得簾牀及脚躡。三千威儀經云：三衣在下地，身不得高牀處坐。", "t": "《四分律》說：比丘尼不穿祇支進入在家人家中，犯波逸提罪。《毗尼母論》與本律都說：袈裟不得垂掛遮蔽床沿，也不得用腳踩踏。《三千威儀經》說：三衣放在下面地上時，身體不得坐在高處的床上。", "i": "u267-7", "n": 397, "s": "第12篇　受衣"}, {"v": "卷上", "o": "決正二部毗尼論云：若著大衣入村，不得禮拜師僧、上座等。五百問事云：無中衣時，得著大衣上講、禮拜；小衣不近身淨潔，無七條者，五條亦得著入眾食及禮拜。不著三衣食，犯罪；十誦亦然。", "t": "《決正二部毗尼論》說：若穿著大衣進入村中，不得禮拜師父、僧眾、上座等。《五百問事經》說：沒有中衣時，可以穿著大衣登上講席、作禮拜。小衣不貼身穿而潔淨的，在沒有七條衣的情況下，五條衣也可以穿著進入僧眾中受食及禮拜。不穿三衣而受食，犯罪；《十誦律》也這樣說。", "i": "u267-8", "n": 398, "s": "第12篇　受衣"}, {"v": "卷上", "o": "第十七坐具法，此律：長佛二磔手，廣一磔手半，廣長更增各半磔手。五分云：佛一磔手，長二尺。義云：四分坐具，總長五尺，廣四尺。僧祇云：互減、過皆提。五分云：須帖四角，不帖則已。此律：若減量作，若疊作兩重，竝得。婆論云：今用敷臥具上。見論云：令受持，不合說淨。不出受文，今義出之。", "t": "第十七，坐具尼師壇的規定。《四分律》說：坐具長為佛的二磔手，寬為一磔手半；長與寬又各再增加半磔手。《五分律》說：佛的一磔手長二尺。依義推算：《四分律》所定的坐具，總長五尺、寬四尺。\n《僧祇律》說：長、寬任一方面不足或超過規定尺寸，都犯波逸提罪。《五分律》說：四角應當貼補，不貼也可以。本律說：若做得比規定尺寸小，或摺疊成兩重，都可以。《薩婆多論》說：現在是把坐具鋪在臥具上面使用。《善見論》說：坐具應當受持，不該說淨。該論沒有列出受持的文句，鈔主如今依義理擬出。", "i": "u268", "n": 399, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此尼師壇應量作，今受持。」 \n捨文。", "t": "「大姊，請專心憶念！我比丘尼某甲，這件坐具是依照規定尺寸做成的，如今我正式接受、持用它。」以下是捨除坐具的作法文。", "i": "u269", "n": 400, "s": "第12篇　受衣"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此尼師壇，本受持，今捨。", "t": "大姊，請專心聽我說：我比丘尼某甲，這件尼師壇原本已受持，現在捨去。", "i": "u270", "n": 401, "s": "第12篇　受衣"}, {"v": "卷上", "o": "十誦：不應受單尼師壇，得提；離宿犯吉。伽論云：不須捨墮，亦不須離宿。母論云：護尼師壇如護身。賢愚經云：舍利弗以尼師壇著左肩上，入眾降邪道。鼻柰耶經云：亦著肩上入眾坐禪。義云：今時多安左臂上，隨方所宜，想亦無過。", "t": "《十誦律》說：不應該受持單層的尼師壇坐具，受持單層坐具的，得波逸提罪；讓坐具離開自己而過夜，則犯突吉羅。《摩得勒伽論》說：坐具不必依捨墮法處理，也不須像三衣那樣防離宿。《毗尼母論》說：守護坐具，要像守護自己的身體一樣。《賢愚經》說：舍利弗把坐具放在左肩上，進入大眾之中，降伏外道。《鼻奈耶經》也說：把坐具放在肩上，進入大眾中坐禪。依義理判定說：當時僧尼大多把坐具安放在左臂上，隨順各地所適宜的做法，想來也沒有過失。", "i": "u271", "n": 402, "s": "第12篇　受衣"}, {"v": "卷上", "o": "○受盋篇第十三", "t": "第十三篇：受持缽。", "i": "u272", "n": 403, "s": "第13篇　受盋"}, {"v": "卷上", "o": "此篇大門有七：一、制意，二、體如，三、色如，四、量如，五、受捨，六、失法，七、護法。", "t": "這一篇的大綱分為七門：一、制定的用意；二、缽體材質如法；三、顏色如法；四、容量如法；五、受持與捨；六、失去受持的情況；七、護持缽的方法。", "i": "u273", "n": 404, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第一制意者，僧祇云：盋是出家人器，非俗人所宜。十誦云：盋是恒沙諸佛標誌，不得惡用。中含經云：盋名應器。婆論云：見一肆上好盋，圓正可愛。律師云：佛初出世，眾僧無盋，佛勅帝釋令天工匠作十萬盋，在世間肆上，盋者天盋，非是人造。", "t": "第一、制定的用意。《僧祇律》說：缽是出家人的器具，不是在家人所宜使用的。《十誦律》說：缽是恆河沙數諸佛的標誌，不得作不正當的使用。《中阿含經》說：缽名為「應器」。《薩婆多論》說：曾見到一家店舖上有一個好缽，外形圓整端正，令人喜愛。論中的律師說：佛最初出世時，眾僧沒有缽，佛便敕令帝釋，命天上的工匠造了十萬個缽，留在世間；店舖上的那些缽，就是天上的缽，並不是人所造的。", "i": "u274", "n": 405, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第二體如者，此律大意有二：一謂泥，二謂鐵。五分云：用白銅盋及外道木盋等，此是外道法，若畜得偷蘭遮。十誦云：石亦不得作盋。義云：今時僧尼亦有畜瓷盋，義判同石；又畜夾紵盋、揩瓦油盋，竝是非法，毀破無罪。", "t": "第二是「體如」，指缽的材質必須如法。本律大要說缽體只有兩種：一是泥瓦缽，二是鐵缽。《五分律》說：使用白銅缽以及外道所用的木缽等，這是外道之法，若畜用就得偷蘭遮罪。《十誦律》說：石頭也不許用來作缽。依義理說：現今僧尼也有畜用瓷缽的；依義判定，瓷缽與石缽相同，一樣不得畜用。另外又有畜用夾紵缽、揩瓦缽、油缽的，這些都屬於非法之器，將它們毀壞打破也不犯罪。", "i": "u275", "n": 406, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第三色如者，此律云：應熏色。僧祇：熏作孔雀咽色、鴿色者，如法。", "t": "第三，缽的顏色須如法：《四分律》說，缽應當加以熏治，熏出顏色。《摩訶僧祇律》說，把缽熏成孔雀頸部的顏色，或熏成鴿子的顏色，就是如法的。", "i": "u276", "n": 407, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第四量如者，此律：大盋受三斗，小者斗半，中器可知。母論云：若不滿斗半，及過三斗者，不成受持。義云：此之升斗，諸方用各不定，未可準定，將古類今，上盋受一斗，下者五升，中者可知。然佛初出世，人形姝大，所食亦多，故限五升以為楷定；今經像季，人形漸小，若定行斯，良恐非用。故五分云：「隨方國土，雖是我語，不為清淨者，不行無過；雖非我語，於餘方清淨者，不得不行。」又盋名應器，須應其身大小，準食之，故下律云：量腹而食，度身而衣，趣足而已。不得見有此判，遂畜小小之者。若不滿四升已上，定不得受；僧盋不滿五升已上，定不成持。數見尼等受持四升已下，故別標記。", "t": "第四，容量如法。本部《四分律》說：大缽容受三斗，小的容受一斗半，中缽的容量可以類推而知。《毘尼母論》說：如果不滿一斗半，或者超過三斗，就不能成就受持。\n依義理說：這裡所講的升、斗，各地方的用法各不相同，不能拿來當作確定的標準。用古時的斗量比類現今，上缽容受一斗，下缽五升，中缽可以類推而知。然而佛最初出世時，人的身形高大，所吃的也多，所以限定下缽五升作為標準。如今已歷經像法末季，人的身形漸漸變小，如果一定照這個標準施行，實在恐怕不合用。所以《五分律》說：隨順各方國土的情形，雖是我所說的，若在當地不被認為清淨，不實行也沒有過失；雖不是我所說的，若在其餘地方被認為清淨，就不能不實行。\n又，缽名叫「應器」，必須相應於自己身形的大小，以食量為準。所以下文律中說：估量腹中食量而吃，度量身形而穿衣，只求足夠就好。\n但不可見到有這樣的判釋，就畜用小小的缽。尼缽容量若不滿四升，決定不得受持；僧缽若不滿五升，決定不成受持。因為屢次見到尼眾等受持四升以下的缽，所以特別標明記出。", "i": "u277", "n": 408, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第五受捨，此律無文，依十誦受云。", "t": "第五是受持與捨。《四分律》中沒有這方面的明文，因此依《十誦律》，受持時說：", "i": "u278", "n": 409, "s": "第13篇　受盋"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此盋多羅應量器，今受持。」 \n捨云。", "t": "大姊，請專心聽我說：我比丘尼某甲，這只缽多羅，也就是合乎規定容量的應量器，我現在受持它。解除受持時則說：", "i": "u279", "n": 410, "s": "第13篇　受盋"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，此盋多羅應量器，先受持，今捨。", "t": "「大姊，請專心一意聽我陳說：我比丘尼某甲，這個鉢多羅是合乎定量的食器，先前已受持，現在捨去。」", "i": "u280", "n": 411, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第六失法者，五百問事云：若一日都不用盋食，犯墮，病重者開；若出界經宿，不失受持。見論云：若先受持盋穿如粟米，即失受持；若以鐵屑塞已，更須受之。若買他盋，未還直，不成受；其主雖言「但受持」，亦不成受，若過日亦不犯長。若買他盋，度價竟，盋主熏已，報比丘尼知，不往取，過日犯捨；若餘人知熏竟，傅向比丘尼說，聞語不往取，過日無犯。此律：盋盂孔罅，食入中，但洗餘食不出，無犯。問：但畜一盋，不加受法，過日犯捨否？答：不犯。由是制畜，事同三衣，但犯不受小罪；若有二盋，一須受持，一須說淨，不爾犯捨墮。", "t": "第六，失法，即受持失效的情形。《五百問事》說：如果一整天都不曾用缽進食，就犯墮罪；病重的人則開許不用。如果缽出了界外、在外過了一夜，受持也不會失去。《善見論》說：先前已作法受持的缽，若穿孔小如粟米，受持當下就失去；即使用鐵屑把孔塞補好了，也必須重新作法受持。如果買別人的缽，價錢還沒有付清，受持不能成立；即使缽主說「你只管受持吧」，受持也仍然不能成立；這樣就算過了十日，也不犯畜長缽的罪。如果買別人的缽，價錢已經付清，缽主把缽熏好之後通知了比丘尼，比丘尼知道卻不去取，過了十日就犯捨墮。若是其他的人知道缽已熏好，轉告比丘尼，比丘尼聽了這話而不去取，即使過了十日也不犯。《四分律》說：缽、盂的孔洞裂縫裡嵌進了食物，只要清洗過，殘留的食物洗不出來，也不犯。\n問：只畜一個缽，不作法受持，過了十日會犯捨墮嗎？\n答：不犯。因為缽是佛制必須畜備的物品，情形與三衣相同，只犯沒有作法受持的小罪。如果有兩個缽，一個必須作法受持，另一個必須說淨；不這樣做，就犯捨墮。", "i": "u281", "n": 412, "s": "第13篇　受盋"}, {"v": "卷上", "o": "第七護法，此律：所行之處，衣盋俱行，如飛鳥羽翮隨身。母論云：至乞食時，各自作盋絡，或盋自持之。僧祇云：不得用灰土洗令色脫，當取樹葉汁洗。三千威儀云：洗盋當用澡豆、皁莢二種為淨。僧祇云：不得臨危處洗盋；先洗師盋，後洗己盋；不得持己盋中殘水瀉師盋中，乃至浣染衣亦爾，勿以師衣共己衣漬之。母論云：不應盋內洗手，敬之如目。五分云：護盋如眼睛；洗盋聽去地一尺，瓦盋離地五六寸許，宜好處安置。僧祇云：惡心破盋，偷蘭遮。五百問事云：不得覆壁上，應巾裹懸璧上。", "t": "第七、護持缽的方法。《四分律》說：無論走到哪裡，衣和缽都要隨身帶著，就像飛鳥的羽翼總是隨著身體一樣。《毘尼母論》說：到了乞食的時候，應各自製作缽絡（盛缽的網袋）來裝缽，或者自己手持著缽。《僧祇律》說：不可以用灰土洗缽，以免缽的顏色脫落；應當取樹葉的汁來洗。《三千威儀》說：洗缽應當用澡豆、皂莢這兩種清潔用品來洗淨。《僧祇律》說：不可在危險的地方洗缽；要先洗師父的缽，再洗自己的缽；不可把自己缽中剩下的水倒入師父的缽中；乃至洗衣、染衣也是一樣，不要把師父的衣服和自己的衣服浸在一起。《毘尼母論》說：不應該在缽內洗手，要像愛護自己的眼睛一樣恭敬地護持缽。《五分律》說：護缽要像護眼睛一樣；洗缽時允許離地一尺，瓦缽則離地五六寸左右，應當安置在妥當的地方。《僧祇律》說：以惡意打破缽，犯偷蘭遮罪。《五百問事》說：不可把缽倒扣在牆上，應該用布巾包裹好，懸掛在牆壁上。", "i": "u282", "n": 413, "s": "第13篇　受盋"}, {"v": "卷上", "o": "○淨施篇第十四", "t": "第十四篇：淨施。", "i": "u283", "n": 414, "s": "第14篇　淨施"}, {"v": "卷上", "o": "此篇大門有五：一、施主，二、請法，三、說淨，四、存亡，五、失法。", "t": "這一篇大分為五門：一是施主，二是請法，三是說淨，四是存亡，五是失法。", "i": "u284", "n": 415, "s": "第14篇　淨施"}, {"v": "卷上", "o": "第一施主者，有二：一、展轉，二、真實。真實希，故不論；今且明展轉法。於中簡別對施，有五：一、衣，二、藥，三、盋，四、寶，五、穀米。前三施主，依僧祇、善見，於五眾中隨得一人作展轉施主；後二竝以俗人為淨主。涅槃經云：雖聽受畜錢寶等物，要須淨施篤信檀越。婆論云：先求一知法白衣為淨主。五分云：有四種人不為展轉淨施主：一、不讚歎人，二、不與人好名稱，三、應淨施五眾，四、不得與白衣。婆論云：應相前人持戒、多聞、有德而作施主。後得物時，於一比丘尼邊，稱施主名說淨。僧祇、十誦、五分等：竝不得對施主而說，亦不應令前人知，直別處對一人說。", "t": "第一是施主。施主有兩種：一是展轉淨施主，二是真實淨施主。真實淨施的情形稀少，所以不加討論，現在先說明展轉淨施的作法。其中再作簡別：對人作淨施的物品有五類，一是衣，二是藥，三是缽，四是寶物，五是穀米。前三類的施主，依《僧祇律》與《善見論》，在五眾之中隨得一人，便可作為展轉淨施主；後兩類則都以在家人為淨主。《涅槃經》說：雖然聽許接受、蓄存錢寶等物，但必須淨施給篤信的檀越。《薩婆多論》說：先尋求一位知法的在家人作淨主。《五分律》說：有四種人不作展轉淨施主，一是不讚歎他人的人，二是不給他人好名聲的人，三是應當淨施給五眾，四是不得淨施給在家人。《薩婆多論》說：應當觀察對方是否持戒、多聞、有德行，這樣的人才請來作施主；以後得到物品時，就在某一位比丘尼面前，稱念施主的名字而說淨。《僧祇律》《十誦律》《五分律》等都說：不得對著施主本人說淨，也不應讓那位施主知道，只須在別處對著另一人說。", "i": "u285", "n": 416, "s": "第14篇　淨施"}, {"v": "卷上", "o": "第二請法者，應具修威儀，至一五眾大德名聞者前，陳本淨意，然後請云。", "t": "第二是請法：應當整肅威儀，到出家五眾中一位自己知其名字的大德面前，陳述自己作淨施的本意，然後啟請說：", "i": "u286", "n": 417, "s": "第14篇　淨施"}, {"v": "卷上", "o": "大姉一心念！我比丘尼某甲，今請大姉為衣、藥、盋展轉淨施主，願大姉為我作衣、藥、盋展轉淨施主。慈愍故。", "t": "大姊，請您一心專注憶念。我比丘尼某甲，現在恭請大姊作為衣、藥、缽的展轉淨施主。懇願大姊慈悲憐愍，為我擔任衣、藥、缽的展轉淨施主。", "i": "u287", "n": 418, "s": "第14篇　淨施"}, {"v": "卷上", "o": "請下三眾，不須云大德、大姉等，直語言。", "t": "如果所要請的是下三眾，就不必稱「大德」「大姉」這一類尊稱，直接這樣說：", "i": "u288", "n": 419, "s": "第14篇　淨施"}, {"v": "卷上", "o": "我今請式叉摩那等為展轉淨施主，幸願作之。", "t": "我現在請式叉摩那等，作為展轉淨施主，希望您答應擔任。", "i": "u289", "n": 420, "s": "第14篇　淨施"}, {"v": "卷上", "o": "次錢寶施主者，婆論云：先求一知法白衣，語言解知；若不解，教令知解。至白衣所，語云：「比丘尼法，不得畜錢、寶、粟等，今以檀越為淨施主，後得錢寶，盡施檀越。」前人報云：「好。", "t": "其次，關於錢財寶物的淨施主：《薩婆多論》說，先要找一位懂得律法的在家人，向他說明，使他明白；如果他不明白，就教導他，使他明白。然後到那位在家人面前，這樣說：「依比丘尼的律法，不可以積蓄金錢、寶物、穀粟等物，現在我以檀越您作為淨施主，日後凡是得到的金錢寶物，全都布施給檀越您。」那位在家人回答說：「好。」", "i": "u290", "n": 421, "s": "第14篇　淨施"}, {"v": "卷上", "o": "第三說淨者，見論云：所說之物眾多散落者，併束相著，然後說之。此律：應至比丘尼前，手捉衣云。", "t": "第三，說淨。《善見論》說：所要說淨的物品如果數量眾多、散落各處，應先把它們收攏捆成一束，使彼此相靠，然後再作說淨。依《四分律》，應當到一位比丘尼面前，手裡拿著衣，這樣說：", "i": "u291", "n": 422, "s": "第14篇　淨施"}, {"v": "卷上", "o": "大姉一心念！此是某甲長衣，未作淨，為淨故，施與大姉，為展轉淨故。", "t": "「大姊，請專心聽我說：這是我某甲的長衣，還沒有作淨；為了作淨的緣故，我把它淨施給大姊，這是為了作展轉淨的緣故。」", "i": "u292", "n": 423, "s": "第14篇　淨施"}, {"v": "卷上", "o": "長老一心念！汝有此長衣，未作淨，為淨故與我，我今受之。汝施與誰？」 \n「施與某甲。", "t": "受淨者回答說：「長老，請一心專注憶念：你有這件尚未作淨的長衣，為了作淨而交給我，我現在接受了。你要施給誰？」衣主回答：「施給某甲。」", "i": "u293", "n": 424, "s": "第14篇　淨施"}, {"v": "卷上", "o": "長老一心念！汝有是長衣，未作淨，為淨故施與我，我今受之，汝與某甲是衣，某甲己物，汝為某甲故善護持，著用隨因緣。", "t": "「長老，請專心聽我說：你有這件長衣，還沒有作淨；為了作淨的緣故，你把它布施給我，我現在接受了。你已把它布施給某甲，這件衣便是某甲自己的物品了。你要替某甲好好守護保管，穿著使用則隨因緣而定。」", "i": "u294", "n": 425, "s": "第14篇　淨施"}, {"v": "卷上", "o": "婆論云：錢寶、穀米等，竝同長衣，十日說淨。此律云：當持至優婆夷若守園人所，告云。", "t": "《薩婆多論》說：錢財、寶物、穀米等，都與長衣一樣，須在十日之內說淨。《四分律》說：應當把這些財物拿到優婆夷或守園人那裡，告訴他說：", "i": "u295", "n": 426, "s": "第14篇　淨施"}, {"v": "卷上", "o": "此是我物，所不應，汝當知之。」即名說淨。", "t": "「這是我的東西，是（依律）我所不應蓄持的，你應當知道這件事。」這樣一說，就叫做「說淨」。", "i": "u296", "n": 427, "s": "第14篇　淨施"}, {"v": "卷上", "o": "五分云：心念說淨，直云如是捨故受新，十日一易，文不明了，今義準出之。有難獨住尼，具修威儀，手捉衣云。", "t": "《五分律》說到心念說淨，只說「就這樣捨掉舊的、換受新的，每十天更換一次」，文句說得不明白，現在依律義推準，把作法擬寫出來。有難緣或獨自居住的比丘尼，應整肅威儀，手裡拿著衣說：", "i": "u297", "n": 428, "s": "第14篇　淨施"}, {"v": "卷上", "o": "我比丘尼某甲，此是長衣，淨施與某甲。」 \n「我比丘尼某甲，從某甲取還。", "t": "先作淨施時說：「我比丘尼某甲，這件是長衣，現在將它淨施給某甲。」\n日後要取回時，再說：「我比丘尼某甲，從某甲那裡把這件衣取回來。」", "i": "u298", "n": 429, "s": "第14篇　淨施"}, {"v": "卷上", "o": "我比丘尼某甲，此是長衣，淨施與某甲，隨彼取用。", "t": "我比丘尼某甲，這件是多餘的長衣，現在作淨施給某甲，任由他取去使用。", "i": "u299", "n": 430, "s": "第14篇　淨施"}, {"v": "卷上", "o": "第四存亡者，僧祗云：施主齊三由旬內，知某存亡。五分云：施主知在道以否。婆論云：施主若至異國，更求淨施主。", "t": "第四、關於施主的存亡：《僧祇律》說：施主要在與說淨者自身相距三由旬的範圍之內，以便能得知這位淨施主是生是死。《五分律》說：要知道施主是否已罷道還俗。《薩婆多論》說：施主如果到了別的國家，就要另外尋求淨施主。", "i": "u300", "n": 431, "s": "第14篇　淨施"}, {"v": "卷上", "o": "第五失法者，婆論云：若死，更求施主；除錢寶、糓米等，自外一切長財，盡五眾邊作淨。義準錢寶等俗人淨主存亡同前。此律：若忘不說淨，或賊奪、失想等難，多日不犯長；若失五日，後時憶得，更經五日說淨，亦得；若得衣十日，至第十日冥忘不說，後時憶得，即須當日說淨，不爾犯捨墮。十誦云：忘後五日得所忘衣，更得十日說淨。婆論云：若說淨財寶及以衣財，若人貸之，後時寶還寶、錢還錢，乃至衣財相當還者，不須說淨；不相當者，更須說之。若補衣物，不滿尺六、狹八寸者，亦犯長故。婆論云：若先不應量衣，此衣盡捨，作突吉羅懺。母論云：惡比丘尼不說淨者，入手即犯，不須至十日。婆論云：若得新鞾，應令白衣著行五七步，即是淨。五分：得新履，令淨人著行七步。", "t": "第五項是「失法」，即說淨之法失效的情形。《婆論》說：淨施主若死了，就要另求淨施主。除了錢、寶、穀、米等以外，其餘一切長財，都須向五眾中的任一人作淨施。依義理推斷：錢寶等既是以俗人為淨施主，那麼這些俗人淨主或存或亡的處理，就與前面所說相同。\n《四分律》說：若因忘記而沒有說淨，或遭盜賊搶奪、生起「已經失去」之想等障難，縱使經過多日，也不犯畜長之罪。若忘失已過五日，後來才想起，再經過五日說淨也可以；若得衣已滿十日，到第十日當夜昏昧忘記而未說淨，後來想起時，就必須在想起的當天說淨，不然便犯捨墮罪。《十誦律》說：忘失之後五日又取回所忘失的衣，可再得十日的期限說淨。\n《婆論》說：已說淨的財寶以及衣財，若有人借去，日後歸還時，借寶的還寶、借錢的還錢，乃至衣財也以相當之物歸還的，不須重新說淨；若所歸還的與原物不相當，就須重新說淨。即使是補衣用的布料，長不滿一尺六寸、寬不滿八寸的，也犯畜長之罪；所以《婆論》說：若原本是不合應量尺寸的衣，這些衣也全都須捨出，然後作突吉羅的懺悔。《母論》說：惡比丘尼不說淨的，衣一入手就犯，不必等到十日。《婆論》說：若得到新靴，應讓白衣穿著走五步或七步，就算是淨了。《五分律》說：得到新鞋，要令淨人穿著走七步。", "i": "u301", "n": 432, "s": "第14篇　淨施"}, {"v": "卷上", "o": "○說戒篇第十五", "t": "第十五篇：說戒", "i": "u302", "n": 433, "s": "第15篇　說戒"}, {"v": "卷上", "o": "此篇大門有六：一、時節，二、緣集，三、儀式，四、差使，五、客舊，六、略說。", "t": "本篇的大綱分為六門：第一是說戒的時節；第二是集眾的因緣；第三是說戒的儀式；第四是差遣使者，即差派尼眾的使者前往比丘僧中，求請教授尼的人；第五是客尼與舊住尼；第六是略說戒。", "i": "u303", "n": 434, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第一時節者，有五：一、十四、十五、十六日。二、食後；僧祇云：食前亦得布薩，而不得晨起布薩，得罪，以後來比丘尼不聞故。伽論云：何布薩？謂捨諸惡不善法，證得白法，究竟梵行；又半月自觀犯與不犯，清淨身口，名布薩也。三、若晝若夜，亦得說戒。四、增減。五、非時。下二希，故不述。", "t": "第一，說戒的時節，共有五項：\n一、十四日、十五日、十六日。\n二、用餐之後。《僧祇律》說：用餐之前也可以作布薩，但不可以在清晨剛起來的時候就作布薩，那樣做會犯罪，因為後來才到的比丘尼就聽不到了。《摩得勒伽論》說：什麼叫布薩？就是捨棄種種惡不善法，證得清淨善法，使梵行究竟圓滿；再者，每半個月自己省察有犯戒與沒有犯戒，使身業、口業清淨，這就名為布薩。\n三、不論白天或夜晚，也都可以說戒。\n四、增減。\n五、非時。\n後面這兩項因為情形罕見，所以不加敘述。", "i": "u304", "n": 435, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第二緣集者，五分云：布薩不時集，妨行道，佛令作時節，使知事維那晨起白僧。", "t": "第二門是「緣集」，即集眾的因緣。《五分律》說：布薩時不按時集合，妨礙了修行道業，佛於是令訂定布薩的時間，並叫掌管事務的維那早晨起來向僧眾宣告。", "i": "u305", "n": 436, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！今白月某日、黑月某日，眾僧和合，在某時某處說戒，白僧令知。", "t": "「大姊僧眾請聽：今天是白月第某日，或黑月第某日；僧眾和合，在某時、某處說戒。」維那如此白告僧眾，令大眾知悉。", "i": "u306", "n": 437, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第三儀式者，今此一門，此律不足，兼取諸部補闕。此律云：若至說戒日，上座應勅諸尼、沙彌尼等，使掃灑佛塔、僧院，高下處令泥治平正，辨諸名華、五三槃名香、陽一二銅盂。今時多用食器盋等盛湯，此非生善之義。冬月無華可得者，諸繒綵華亦得。說戒當徧布其席，及門限外亦鋪其席，擬脫鞾履。", "t": "第三、儀式：\n這一門的內容，《四分律》記載不足，因此兼取其他各部律典來補充缺漏。《四分律》說：「如果到了說戒日，上座應當吩咐諸位比丘尼、沙彌尼等，使她們清掃灑淨佛塔與僧院，高低不平之處要令人用泥抹治平整，備辦各種名花三、五盤，以及盛名香湯的銅盂一、二個。」現今多數人使用食器、缽等來盛裝香湯，這並非能生起善心敬信的做法。冬天若沒有鮮花可得，各種絲綢彩花也可以。說戒時應當遍地鋪好坐席，門檻外面也要鋪設席子，預備在那裡脫放靴鞋。", "i": "uGAP07", "n": 438, "s": "第15篇　說戒"}, {"v": "卷上", "o": "若鳴鐘集僧，不簡沙彌尼等，竝來入堂受籌，以此律戒序開沙彌尼得聽，若依餘部，不得者多。十誦云：行籌者，為檀越問僧不知頭數，佛今行籌；不知沙彌數，亦令行籌。若人施布薩物，沙彌亦得取分，雖不往布薩羯磨處，由受籌故亦得分；此律為受供行籌，則通沙彌也。籌極短竝五指，極長一肘，極麤不過小指，細不減筯。", "t": "若鳴鐘集合僧眾，不排除沙彌尼等，都要一起進入說戒堂受籌，因為《四分律》的〈戒序〉開許沙彌尼可以聽戒；若依照其他各部律典，不許聽戒的居多。《十誦律》說：「行籌這件事，是因為施主詢問僧眾人數而不知頭數，佛陀便令行籌；不知沙彌人數時，也令行籌。若有人布施布薩所用之物，沙彌也可領取一份；即使不前往布薩羯磨的處所，因為受過籌的緣故，也能分得一份。」《四分律》中為了接受供養而行籌，也就通於沙彌了。籌木的尺寸：最短為併攏五指的寬度，最長為一肘，最粗不超過小指，最細也不得細於筷子。", "i": "uGAP07-2", "n": 439, "s": "第15篇　說戒"}, {"v": "卷上", "o": "初入堂時，先偏袒右肩，脫去鞾履，合掌作禮；若恐人閙，不及一一作禮，但俛身側入，依次坐。近數見僧尼，及至俗家齋上，僧尼在牀上禮佛；尋討一切經律，及問西國諸德，竝無此禮，直是怠惰安身，不存敬意，反招自累，何成覓福？如臣拜君，豈得居牀？人王尚自不許，法王寧容輙開！故三千威儀經云：比丘不得座上作禮。", "t": "剛進入戒堂時，應先偏袒右肩，脫去靴鞋，合掌作禮；如果擔心人多喧鬧，來不及一一作禮，只要彎腰側身進入，按照次序坐下即可。近來屢次見到僧尼，乃至到俗人家赴齋時，僧尼竟然坐在坐牀上禮佛。遍查一切經律，並詢問來自西國的諸位大德，都沒有這種禮法。這純粹是懶惰圖自身安逸，不存敬意，反而招致自身的罪累，哪裡算得上是求福呢？如同臣子拜見君王，豈能坐在坐牀上？世間人王尚且不允許，法王豈容隨意開許？因此《三千威儀經》說：「比丘不可以在座位上行禮。」", "i": "uGAP07-3", "n": 440, "s": "第15篇　說戒"}, {"v": "卷上", "o": "初入堂時，說偈云：「持戒清淨如滿月，身口皎潔無瑕穢，大眾和合無違諍，爾乃可得同布薩。」說此偈已，各依次坐。年少尼起行香湯、淨水，眾大時令三五尼助行；行時，各須偏袒右肩，脫去鞾履，具修威儀。維那先取香湯洗手浴籌，至打靜處；維那自浴亦得，今時多使上座自浴籌，此非敬儀。當浴籌時，僧各說偈云：「羅漢聖僧集，凡夫眾和合，香湯浴淨籌，布薩度眾生。」", "t": "剛進入戒堂時，要誦說這首偈頌：\n「持戒清淨宛如滿月，身口皎潔毫無瑕穢；大眾和合沒有違逆紛爭，如此才能共同行布薩。」\n說完這首偈頌後，各自按照次序坐下。年少的比丘尼起身巡行分送香湯與淨水；大眾人數眾多時，應令三、五位比丘尼協助巡行。巡行時各自都必須偏袒右肩，脫去靴鞋，威儀齊整。維那先取香湯洗手、洗浴籌木，然後走到打靜（擊槌止靜）之處；籌由維那自己洗浴也可以。現今多數地方卻讓上座親自洗浴籌木，這不合恭敬的儀則。正當洗浴籌木時，僧眾各自誦說這首偈頌：\n「阿羅漢聖僧聚集，凡夫僧眾和合；以香湯洗浴淨籌，舉行布薩以度脫眾生。」", "i": "uGAP07-4", "n": 441, "s": "第15篇　說戒"}, {"v": "卷上", "o": "說此偈已，令年少尼行香湯、淨水；先行淨水，兼行淨巾拭手令乾。正承水時，復說偈云：「八功德水淨諸塵，盥掌去垢心無染，執持禁戒無缺犯，一切眾生亦如是。」行香湯時，復說偈云：「香水熏沐澡諸垢，法身具足五分充，般若圓照解脫滿，羣生同會法界融。」承香湯水時，不得漱口吐地，數見故別標記。", "t": "說完這首偈頌後，令年少比丘尼巡行分送香湯與淨水。先傳行淨水，同時傳送淨巾，將手擦乾。正當捧手接水時，又誦說這首偈頌：\n「以八功德水洗淨諸般塵垢，洗掌去垢而內心無染；執持禁戒沒有缺漏違犯，願一切眾生也都能如此。」\n傳行香湯時，又誦說這首偈頌：\n「以香水熏沐洗除諸般污垢，願法身具足、五分法身充盈，般若智慧圓照、解脫功德圓滿，一切眾生共同會歸、融通於法界。」\n領受香湯與淨水時，不可以拿來漱口後吐在地上；因為屢次見到這種情況，所以特地標明記錄下來。", "i": "uGAP07-5", "n": 442, "s": "第15篇　說戒"}, {"v": "卷上", "o": "維那浴籌已，右手執槌，至打靜處立，徐緩打一下已，安手放槌，勿令作聲，然後唱云。", "t": "維那洗浴完籌木之後，右手拿著木槌，走到打靜的地方站立，緩慢平穩地敲擊一下後，安穩地放手放下木槌，不要讓它發出聲響，然後唱道：", "i": "uGAP07-6", "n": 443, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！眾中誰小，小者收護。", "t": "大姊僧眾請聽：大眾之中誰的戒臘最小？就由那位最小的負責「收護」，也就是收攝保管辦事的各項用具，並且監護整場法事。", "i": "u307", "n": 444, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！外有清淨大沙門入。", "t": "大姊僧眾請聽：在堂外已受具足戒的清淨大沙門，請進來。", "i": "u308", "n": 445, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！眾中小者已收護，外清淨大沙門已入，內外寂靜，無諸難事，堪可行籌，廣作布薩。我比丘尼某甲，為僧行籌，作布薩事。僧當一心念作布薩，願上、中、下座，各次第如法受籌。", "t": "大姊僧眾請聽：僧眾中戒臘最淺的，已經收攝眾具、守護法事；外面清淨的具戒比丘尼也已進入。內外都已寂靜，沒有種種障難之事，足以行籌，得以完整誦說戒本而作布薩。我比丘尼某甲，為僧眾行籌，辦理布薩的事務。僧眾應當一心專注地舉行布薩，願上、中、下座，各自依次如法地領受籌。", "i": "u309", "n": 446, "s": "第15篇　說戒"}, {"v": "卷上", "o": "說竟，維那來至上座前，長跪授籌與上座，即鴈行長跪合掌，一切僧亦隨上座儀式。正取籌時，當說偈云：「金剛無礙解脫籌，難得難遇如今果；我今歡喜頂戴受，一切眾生亦如是。」欲還籌時，復說偈云：「具足清淨受此籌，具足清淨還此籌；堅固喜捨無缺犯，一切眾生亦如是。」說已，即付與他，還復本座。如是展轉至大尼訖，維那來至打靜處立，收籌者付上座數，維那自數亦得。數已，打靜唱云。", "t": "維那唱說完畢，便走到上座面前，長跪著把籌交給上座。上座與大眾隨即如雁行般依次長跪合掌，全眾都依照上座的儀式進行。\n正在取籌的時候，應當說偈：「這如金剛般無礙解脫的籌，難得難遇，如今我已得此果；我現在歡喜地頂戴領受，願一切眾生也都如此。」要交還籌的時候，再說偈：「我戒行具足清淨，領受這支籌；我戒行具足清淨，交還這支籌；持戒堅固、歡喜捨施，沒有缺犯；願一切眾生也都如此。」說完就把籌交給下一位，自己回到本座。\n就這樣依次輾轉傳遞，直到所有大尼都受籌、還籌完畢。維那走到擊槌止靜的地方站定，收籌的人把籌交給上座，由上座計數；維那自己計數也可以。數完之後，擊槌止靜，唱言：", "i": "u310", "n": 447, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！次行式叉摩那尼、沙彌尼籌。", "t": "各位大姊僧眾請聽：接下來要分發籌枝給式叉摩那尼和沙彌尼。", "i": "u311", "n": 448, "s": "第15篇　說戒"}, {"v": "卷上", "o": "三說已，往式叉尼等所行訖，收取，付與上座數竟，維那總取，還至打靜處立，唱云。", "t": "這樣唱說三遍之後，便前往式叉摩那尼等所在的地方行籌；行籌完畢，把籌收回，交給上座計數。數完之後，維那把所有的籌一併收齊，回到擊槌止靜的位置站定，唱言道：", "i": "u312", "n": 449, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！此一住處，一說戒，比丘尼若干人，式叉摩那若干人，沙彌尼若干人，都合若干人，各清淨出家，和合說戒。上順佛教，中報四恩，下為含識，各誦經中清淨玅偈。", "t": "諸位大姊僧眾請聽：在這同一個住處裡，共同作同一說戒。與會的比丘尼有若干人，式叉摩那有若干人，沙彌尼有若干人，總共合計若干人。大家各自都是清淨出家，如今和合共聚說戒。這樣上則隨順佛陀的教法，中則報答四恩，下則為含識眾生。請各自誦念經中的清淨妙偈。", "i": "u313", "n": 450, "s": "第15篇　說戒"}, {"v": "卷上", "o": "眾僧一時合掌說偈云。", "t": "全體僧眾同時合掌，誦說偈頌道：", "i": "u314", "n": 451, "s": "第15篇　說戒"}, {"v": "卷上", "o": "清淨如滿月，清淨得布薩，身口業清淨，爾乃應布薩。", "t": "清淨如同滿月一般，清淨的人才堪能作布薩；身業、口業都清淨，這樣的人才堪能與眾同作布薩。", "i": "u315", "n": 452, "s": "第15篇　說戒"}, {"v": "卷上", "o": "彼維那舉籌已，至上座前，禮三拜已，白上座云。", "t": "那位維那把籌收起放好之後，來到上座面前，向上座頂禮三拜，然後稟白上座說：", "i": "u316", "n": 453, "s": "第15篇　說戒"}, {"v": "卷上", "o": "眾僧和合，請大姉為眾誦律。", "t": "大眾僧和合一致，恭請大姊為大眾誦出戒本。", "i": "u317", "n": 454, "s": "第15篇　說戒"}, {"v": "卷上", "o": "若上座自說者，語云：「此戒法正當某甲說，某甲自誦。」維那依上座已，即須唱之。若辭不堪者，告云：「此說戒任當某甲，但為自身老弱，言辭濁惡，恐延時惱僧，更為請眾中能誦者說。」維那更禮一拜已，當起至第二上座前，還依前問無異；若第二上座不堪者，直請能誦，不勞展轉至下。故僧祇云：若上座、若次座應誦，不能者，差能誦者說。若差得者，打靜唱云。", "t": "如果上座自己要誦說，就回答說：「這戒法正應由某甲來誦說，某甲自己誦。」維那依上座這樣的答覆之後，就應當唱告。如果上座推辭說不能勝任，就告知說：「這次說戒本該由某甲擔當，只是因為自身年老體弱，言語粗濁不清，恐怕拖延時間、擾惱大眾，請再為我在大眾中禮請能誦戒的人來誦說。」維那再禮一拜之後，應起身到第二上座面前，仍照先前那樣請問，沒有差別。如果第二上座也不能勝任，就直接禮請能誦戒的人，不必依次輾轉請問到下面各位。所以《僧祇律》說：上座或次座應當誦戒，若不能誦，就差派能誦的人來誦說。若已差定了人選，維那就敲擊靜椎令大眾肅靜，然後唱告說：", "i": "u318", "n": 455, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！僧差律師某甲為僧誦戒，梵音某甲，律師陞高座。", "t": "大姊僧眾請聽：僧團已差派律師某甲，為僧眾誦戒；擔任梵音唱誦的是某甲。請律師登上高座。", "i": "u319", "n": 456, "s": "第15篇　說戒"}, {"v": "卷上", "o": "僧既差已，律師應起，具修威儀，至僧中，大鋪坐具，四向禮拜僧已，長跪白云。", "t": "僧眾既然已經差定，受差的律師就應當起身，周全地整肅威儀，走到僧眾當中，把坐具寬寬地鋪展開來，向四面的僧眾一一禮拜；禮拜完畢，長跪稟白說：", "i": "u320", "n": 457, "s": "第15篇　說戒"}, {"v": "卷上", "o": "我比丘尼某甲，稽首和南，敬白眾僧：僧差誦律，恐有錯誤，願同誦者，弘垂指授。", "t": "我比丘尼某甲，叩首敬禮，恭敬稟白僧眾：僧團差派我誦說戒律，恐怕會有錯誤，希望同樣能誦律的人，廣為垂賜指點教授。", "i": "u321", "n": 458, "s": "第15篇　說戒"}, {"v": "卷上", "o": "白已，更設一拜，然後陞座。香水餘殘，維那左右灑之，應留中間空處，擬人來往；香華亦爾，令旋旋散。散華時，各說偈云。", "t": "這樣稟白之後，再行一拜，然後登上高座。用剩的香水，由維那往左右兩旁灑去，但應留出中間的空處，預備人員往來通行；香與花也同樣照這樣處理，讓人緩緩地、依次散灑。散花的時候，各自說偈道：", "i": "u322", "n": 459, "s": "第15篇　說戒"}, {"v": "卷上", "o": "散華莊嚴淨光明，莊嚴寶華以為帳，散眾寶華徧十方，供養一切諸如來。", "t": "散下的花作為莊嚴，清淨而光明；用莊嚴的寶花結成花帳；把種種寶花散遍十方，供養一切諸如來。", "i": "u323", "n": 460, "s": "第15篇　說戒"}, {"v": "卷上", "o": "說已，維那打靜，令小者供養，好聲者梵唄；作梵時，應誦「稽首禮諸佛」兩行偈。至行香說偈時，僧一時合掌說云。", "t": "偈頌說完之後，維那擊響法器、示意大眾肅靜，叫下座年少者去辦供養的事，並由嗓音好的人唱梵唄。作梵唄的時候，應誦「稽首禮諸佛」起首的那兩行四句偈。到了行香、要說偈的時候，全體僧眾同時合掌，這樣說：", "i": "u324", "n": 461, "s": "第15篇　說戒"}, {"v": "卷上", "o": "戒香定香解脫香，光明雲臺徧法界，供養十方無量佛，見聞普熏證寂滅。", "t": "戒香、定香、解脫香，\n光明的雲臺遍滿法界，\n供養十方無量的諸佛，\n凡見到、聞到的人都普遍受到熏染，證得寂滅。", "i": "u325", "n": 462, "s": "第15篇　說戒"}, {"v": "卷上", "o": "供養雖竟，維那仍須立住。彼戒師誦至未受具者出，則戒師應且住誦，令式叉尼、沙彌尼出。式叉尼等應具修威儀，來至僧前，禮三拜已，長跪住，取上座教勅。上座當告諸式叉摩那、沙彌尼等：「汝等年未充，行未滿，不堪進入羯磨僧數，同聽說戒；待至年充行滿，受具戒竟，然後得預說戒。汝等各還本處，靜念唱誦，不得散亂。」然後方便，更設一拜，依次而出；若式叉尼等別說戒堂，則不須此。戒師唱不來者說欲，維那答云：「說欲已。」若無欲人者，應答云：「此處無說欲人。", "t": "供養雖然完畢，維那仍須站立著。那位戒師誦到「未受具者出」，也就是未受具足戒的人退出這一句時，就應暫停誦念，讓式叉摩那尼、沙彌尼出去。式叉摩那尼等應具足威儀，來到僧眾面前，頂禮三拜之後，長跪而住，聽受上座的教誡。上座應當告訴諸位式叉摩那、沙彌尼等：「你們年齡尚未滿足，學行尚未圓滿，不能進入羯磨僧數之中，一同聽誦戒法；等到年齡滿足、學行圓滿，受完具足戒之後，才能參與說戒。你們各自回到本處，靜心憶念唱誦，不得散亂。」然後她們隨宜再拜一拜，依序退出。如果式叉摩那尼等另有說戒堂，就不需要這一套作法。戒師唱念「不來者說欲」，要未到場的人由受託者代為傳達與欲；維那回答「說欲已」，表示與欲已傳達完畢；如果沒有與欲的人，就應回答「此處無說欲人」。", "i": "u326", "n": 463, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第四差使者，見論云：初為女人鈍根故，盡聽尼僧往僧寺受教；後為人譏嫌故，僧往尼寺教誡尼僧。當於說戒日僧集時，索欲，問僧云。", "t": "第四，差派使者。《善見論》說：起初因為女人根性遲鈍，所以聽許尼眾全都前往比丘寺院接受教誡；後來因為受到世人譏嫌，所以改為比丘前往尼寺教誡。尼眾應當在說戒日大眾集合的時候，先徵索未到者託人代達的與欲，然後問僧說：", "i": "u327", "n": 464, "s": "第15篇　說戒"}, {"v": "卷上", "o": "僧今和合，何所作為？」答云：「差求教授人羯磨。", "t": "問：「僧眾現在已經和合集會，要作什麼事呢？」答：「作差派前往求請教授師之人的羯磨。」", "i": "u328", "n": 465, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！若僧時到，僧忍聽。今差比丘尼某甲，為比丘尼僧故，半月往比丘僧中，求教授尼人。白如是。", "t": "諸位大姊，請僧眾聽著！如果僧眾作法的時機已到，請僧眾和心忍可聽許：現在差派比丘尼某甲，為了比丘尼僧眾的緣故，每半個月前往比丘僧團之中，求請教授比丘尼的人。以上的稟白就是這樣。", "i": "u329", "n": 466, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！僧今差比丘尼某甲，為比丘尼僧故，半月往比丘僧中，求教授尼人。誰諸大姉忍『僧差比丘尼某甲，為比丘尼僧故，半月往比丘僧中，求教授尼人』者默然，誰不忍者說。僧已忍『差比丘尼某甲，為比丘尼僧故，半月往比丘僧中，求教授已人』竟。僧忍默然故，是事如是持。", "t": "各位大姊僧眾請聽！僧團現在差派比丘尼某甲，為了比丘尼僧團的緣故，每半個月前往比丘僧團當中，求請教授尼眾的人。諸位大姊之中，誰贊同僧團差派比丘尼某甲，為了比丘尼僧團的緣故，每半個月前往比丘僧團當中，求請教授尼眾的人，就請默然不作聲；誰不贊同，就請說出來。僧團已經認可，差派比丘尼某甲，為了比丘尼僧團的緣故，每半個月前往比丘僧團當中，求請教授尼眾的人，這件差派已經完成。僧團既已認可而默然的緣故，這件事就如此確定下來，照著奉行。", "i": "u330", "n": 467, "s": "第15篇　說戒"}, {"v": "卷上", "o": "此律：羯磨差一人已，自外口差二人為伴，往僧中。四分、十誦云：尼若囑時，應囑主人僧無病、有智慧、明戒律者。大僧於布薩日，應預差一人，擬受尼囑人，房前設一獨坐牀；尼若來時，應佛殿前立，餘僧見者，示尼囑授人處。此尼至房前，比丘應詣牀坐已，將一比丘為伴，使尼禮三拜已，曲身合掌云。", "t": "本部《四分律》中，以羯磨正式差派一人之後，另外再用口頭差派二人作為同伴，一同前往比丘僧中。《四分律》《十誦律》說：尼眾要託付請求時，應當託付給寺中作主人的比丘，而且這位比丘必須是無病、有智慧、通達戒律的人。比丘僧在布薩說戒日，應預先差定一人，準備接受尼眾的囑託；在這位受囑比丘的房前，安放一張單人坐的床座。尼眾來時，應先站在佛殿前；其餘比丘看見了，就為尼指出接受囑託那位比丘的所在之處。這位尼來到房前時，那位比丘應走到床座前坐下，並帶一位比丘作陪，然後讓尼頂禮三拜；拜畢，尼俯身合掌說：", "i": "u331", "n": 468, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大德一心念！某寺尼眾和合，半月頂禮比丘僧足，求請教授尼人。", "t": "「大德請專心聽我陳白：某寺的比丘尼僧眾和合集會，每半月頂禮比丘僧眾的足下，求請一位教授比丘尼的人。」", "i": "u332", "n": 469, "s": "第15篇　說戒"}, {"v": "卷上", "o": "比丘受尼囑已，語云：「今夜說戒時，為諮請眾僧，未知有否；然尼眾等為欲別請，為依僧次請？」隨尼所答為請。又告：「明日早來，問其可否。」使尼答云：「爾。」更設一拜便歸。\n僧祇云：尼入僧寺，當在門屋下先白比丘，比丘當量儀得所；若尼賢善，自入無事，著衣服具者，聽入；反此，不聽。尼明日來時，如前儀式，告云：「昨夜僧集之時，具傳所請，無有教誡尼人，又無善說法者；雖然，上座有勅，語諸尼眾：『當勤精進，如法行道，謹慎莫放逸！』」使尼合掌云：「頂戴持。」便禮已而退。至本寺時，即須鳴鐘集僧，不來者說欲。尼皆來集堂內，依次立住。所差尼人至上座頭立，打靜說白云。", "t": "比丘接受了尼的囑請之後，對她說：「今晚說戒的時候，我會替你們向大眾僧諮問請求，只是還不曉得有沒有這樣的人。不過，你們尼眾是要別請某一位特定的人，還是依照僧中的次第輪請呢？」隨後就按尼所回答的方式替她們去請。比丘又告訴她：「明天早些來，問一問究竟可行與否。」使者尼回答說：「好。」再行一拜，便回去了。\n《僧祇律》說：尼要進入比丘寺院時，應當先在門屋下稟白比丘；比丘應當衡量她的威儀舉止是否得宜：如果這位尼賢良善順，讓她自己進去也不會有什麼問題，而且衣服穿著齊備，就准她進入；反之便不准。\n第二天尼來的時候，仍照前面的儀式，比丘告訴她說：「昨夜僧眾集會時，我已把你們所請求的事完整傳達了，僧中沒有能教誡尼的人，也沒有善於說法的人。雖然如此，上座有教敕，要我轉告諸尼眾：應當勤加精進，如法行道，謹慎自持，不要放逸。」使者尼合掌說：「頂戴受持。」禮拜之後便辭退離去。回到本寺時，就要立刻鳴鐘集合尼眾，不能前來的人要說欲。尼眾都聚集到堂內，依序站定。受差遣的那位尼走到上座前站定，打靜之後，作白。", "i": "u333", "n": 470, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！僧差我比丘尼某甲，往比丘僧中，請教授尼人；而僧無教授已人，亦無善說法者；雖然，上座有勅，語諸尼眾：『當勤精進，如法行道，謹慎莫放逸。", "t": "各位大姊僧眾請聽：僧團差派我比丘尼某甲，前往比丘僧中，求請能教授尼眾的人。然而比丘僧中沒有能教授尼眾的人，也沒有善於說法的人。雖然如此，上座仍有教敕，要轉告各位尼眾：應當勤加精進，如法行道，謹慎不放逸。", "i": "u334", "n": 471, "s": "第15篇　說戒"}, {"v": "卷上", "o": "諸尼眾等一時合掌云：「頂戴持。」出五分、十誦、僧祇。今時多行此略法，由廣法難故不出也。此律：若比丘僧盡病，應遣信行禮拜問訊；若別眾、眾不滿，亦遣使問訊；若尼僧病、眾不滿，亦禮拜問訊。義云：若僧尼各五人以上，僧中二十夏者，得行此廣略二法；僧若不足，但應禮拜問訊便罷。\n次說戒師問僧云。", "t": "全體尼眾一起合掌說：「頂戴持。」這句「頂戴持」的答法出自《五分律》《十誦律》《僧祇律》。現今大多採用這個略法，由於廣法繁難，所以這裡就不再列出了。\n《四分律》說：如果比丘僧全體都患病，尼眾應派遣使者前往禮拜問訊；如果比丘僧未能全數聚集、或人數不足，也一樣派使者去問訊；如果比丘尼僧患病、或人數不足，也同樣只是派人前往禮拜問訊。\n依義推論：比丘僧與比丘尼僧各有五人以上，並且比丘僧中有戒臘滿二十夏的比丘，才可以行這廣、略二種法。若比丘僧這方面條件不足，就只應禮拜問訊，到此為止。\n接著，說戒師問僧眾說：", "i": "u335", "n": 472, "s": "第15篇　說戒"}, {"v": "卷上", "o": "僧今和合，何所作為？」維那答云：「說戒羯磨。", "t": "「僧眾現在已經和合集會，要作什麼事呢？」維那回答說：「作說戒羯磨。」", "i": "u336", "n": 473, "s": "第15篇　說戒"}, {"v": "卷上", "o": "戒師待維那坐已，然後作白，以未坐時便有坐立不同，豈非別眾等過？若說戒竟，維那鳴鐘三下，使外人知說戒竟。時梵師誦律序下偈作唄云。", "t": "說戒師要等維那坐下之後，才作白宣告。因為維那還未坐下時，大眾之中便有坐著與站著的差別，這豈不就是「別眾」等過失嗎？說戒結束後，維那敲鐘三下，讓外面的人知道說戒已經完畢；這時，梵唄師便以梵唄唱誦律藏序偈末後的那首偈頌，唱道：", "i": "u337", "n": 474, "s": "第15篇　說戒"}, {"v": "卷上", "o": "神仙五通人，造設於呪術，為彼慚愧者，攝諸不慚愧。如來立禁戒，半月半月說，已說戒利益，稽首禮諸佛。", "t": "得五神通的仙人，尚且造作施設咒術，為護念那些有慚愧心的人，攝伏一切無慚無愧的人；如來制定禁戒，每半月誦說一次。如今已宣說了戒的利益，我稽首頂禮諸佛。", "i": "u338", "n": 475, "s": "第15篇　說戒"}, {"v": "卷上", "o": "伽論云：不得作半唄，作半唄者吉羅。戒師下座已，至僧中禮謝云：「小比丘尼某甲，稽首和南，敬謝眾僧：僧差誦律，三業不勤，多有舛錯，願眾慈悲，布施歡喜。", "t": "《伽論》說：不可以只作『半唄』，即唄讚時只唱偈頌的一半；作半唄的人，犯突吉羅罪。戒師從高座下來後，走到僧眾當中禮拜謝過，說道：「小比丘尼某甲，叩首敬禮，恭敬地向大眾僧謝過：僧團差派我誦律，我身口意三業不夠精勤，多有差錯，祈願大眾慈悲，施與歡喜。」", "i": "u339", "n": 476, "s": "第15篇　說戒"}, {"v": "卷上", "o": "說已，眾僧即應各說自慶偈云。", "t": "說完這番話後，全體尼眾就應當各自誦說自我慶幸的偈頌，說道：", "i": "u340", "n": 477, "s": "第15篇　說戒"}, {"v": "卷上", "o": "諸佛出世第一快，聞法奉行安隱快，大眾和合寂滅快，眾生離苦解脫快。", "t": "諸佛出現於世，是第一的快樂。聽聞正法而依教奉行，是安穩的快樂。大眾和合，是寂滅的快樂。眾生脫離痛苦，是解脫的快樂。", "i": "u341", "n": 478, "s": "第15篇　說戒"}, {"v": "卷上", "o": "俱舍論說偈云。", "t": "《俱舍論》中的偈頌說：", "i": "u342", "n": 479, "s": "第15篇　說戒"}, {"v": "卷上", "o": "諸佛出現樂，說正法亦樂，大眾和合樂，聚集出家樂。", "t": "諸佛出現於世，是快樂的；宣說正法，也是快樂的；大眾和合，是快樂的；出家眾聚集在一起，是快樂的。", "i": "u343", "n": 480, "s": "第15篇　說戒"}, {"v": "卷上", "o": "然後唱三歸禮散。", "t": "接著唱誦三歸依，行禮之後便解散。", "i": "u344", "n": 481, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第五客舊者，問：界外客尼，欲得聞戒，得入以否？答：此律客舊中開聽。若客尼入時，至說戒處，不得先到餘房，恐破他說戒。未誦序、唱「是中清淨否」來，客尼隨次入，作禮已，依行坐聽。誦戒師若見客來，即須止誦；不止者，客尼訶停。待客尼坐已，依次為誦。若已說序竟，乃至說戒已，當入僧中，四向禮僧已，長跪住，一人告清淨云。", "t": "第五，關於客尼與舊住尼。\n問：從結界之外來的客尼想要聽誦戒，可以進入嗎？\n答：《四分律》在客舊的文中已作開許，聽任她們進入。客尼進來的時候，應直接到說戒的處所，不得先到其他房舍去，以免破壞他人的說戒。若誦戒師還沒有誦到戒經序中唱問「是中清淨否」——在場大眾是否清淨——的地方，這時到來的客尼就依次進入，行禮之後，按自己的班次坐下聽誦戒。戒師若看見客尼到來，就必須停止誦戒；若不停止，客尼可以出言訶止，使他停下。等客尼坐定之後，再按次第為她們誦戒。如果已經誦完戒經序，乃至說戒已經結束，客尼就應當進入僧眾當中，向四面的僧眾頂禮，然後長跪而住，由其中一人稟告清淨說：", "i": "u345", "n": 482, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！比丘尼某甲等若干人，竝清淨。", "t": "各位大姊僧眾請聽：比丘尼某甲等共若干人，都是清淨的。", "i": "u346", "n": 483, "s": "第15篇　說戒"}, {"v": "卷上", "o": "告已隨次坐，戒師依說。若不清淨者，一一別告云。", "t": "稟告清淨完畢後，來客比丘尼便依序入座，誦戒師照原來的次第接著誦戒。若其中有犯罪尚未懺悔而不清淨的，就須逐一各別發露稟告說：", "i": "u347", "n": 484, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉僧聽！比丘尼某甲，犯某罪，為逼說戒，未得懺悔，後當如法懺。", "t": "諸位大姊僧眾請聽：比丘尼某甲犯了某罪，因為說戒的時間緊迫，還未能懺悔，之後定當如法懺悔。", "i": "u348", "n": 485, "s": "第15篇　說戒"}, {"v": "卷上", "o": "說已，依前住文續次為說。若客尼來多及等者，縱說戒訖，皆令主人從頭更誦；不誦者，如法治。律云：等多更為說。\n問：說戒至半，不說欲得起出否？答：有緣，要須說欲得去。若眾中無能誦得戒者，至布薩日，依前儀式，直差一人說法、誦經、諸教誡等便散。母論云：若鈍根無知，不得就餘寺說者，下至說一偈云。", "t": "宣告完畢後，戒師就依照先前停下來的戒文，接著按次序為她們誦下去。如果來的客尼人數比舊住尼多，或與舊住尼相等，即使說戒已經誦完，也都要令作為主人的舊住尼從頭重新誦一遍；不重誦的，依律處治。《四分律》說：客尼人數相等或更多時，就要重新為她們誦說。\n問：說戒誦到一半，不說欲，可以起身出去嗎？\n答：有要事因緣時，必須先說欲，然後才可以離去。\n如果眾中沒有人能誦戒，到了布薩日，就依照前面的儀式，直接差派一人說法、誦經，作種種教誡等，然後便解散。《毘尼母論》說：如果根性遲鈍、愚昧無知，又不能到別的寺院聽聞說戒，那麼至少也要誦一首偈，說道：", "i": "u349", "n": 486, "s": "第15篇　說戒"}, {"v": "卷上", "o": "諸惡莫作，諸善奉行，自淨其意，是諸佛教，和南聖眾。", "t": "「諸惡莫作，諸善奉行，自淨其意，是諸佛教。」意思是：一切惡都不要做，一切善都要奉行，自己淨化自己的心念，這就是一切諸佛的教誨。接著稱念「和南聖眾」，向聖眾恭敬禮拜。", "i": "u350", "n": 487, "s": "第15篇　說戒"}, {"v": "卷上", "o": "如是作已，方得散去，不合不說。若於說戒座上憶得罪者，即須心念發露云。", "t": "像這樣做完之後，才可以散去，不可以什麼都不誦說就散。如果在說戒的座位上想起自己曾犯了罪，就必須立即以心念的方式發露，念道：", "i": "u351", "n": 488, "s": "第15篇　說戒"}, {"v": "卷上", "o": "我比丘尼某甲，犯某罪，待說戒竟，當如法懺。", "t": "「我比丘尼某甲，犯了某罪。等說戒結束之後，我應當如法懺悔。」", "i": "u352", "n": 489, "s": "第15篇　說戒"}, {"v": "卷上", "o": "作如是已，便得聽戒。若犯有疑者，應念云。", "t": "這樣心念發露之後，便可以聽誦戒了。如果是對某件事是否犯戒存有疑惑，應當這樣心念說：", "i": "u353", "n": 490, "s": "第15篇　說戒"}, {"v": "卷上", "o": "我比丘尼某甲，於某事上疑，待說戒後，當決了懺。", "t": "我比丘尼某甲，對某件事是否犯戒心存疑惑。等說戒結束之後，定當查明決斷，然後懺悔。", "i": "u354", "n": 491, "s": "第15篇　說戒"}, {"v": "卷上", "o": "若於未說戒憶得罪者，應說懺已，方得聞戒法。", "t": "如果是在還沒有開始誦戒之前就想起自己犯了罪，那就必須先把所犯的罪發露說出、懺悔完畢，然後才可以聽聞戒法。", "i": "u355", "n": 492, "s": "第15篇　說戒"}, {"v": "卷上", "o": "第六略說者，此律：若有八難，王、賊、水、火、病人、非人、惡蟲難等，或大眾集、牀座少、多病、天雨、鬬諍、說戒夜久，如是等緣，皆聽略說。戒師當量難緣遠近，觀時早晚：難若遠，則為說三篇已，餘者略却；若近，及病、寒熱等緣，當為說序已，餘者便略。云何略耶？說戒序已，問清淨竟，應言。", "t": "第六、略說戒。《四分律》中說：若有八種危難——王難、賊難、水難、火難、病難、人難、非人難、惡蟲難等；或者大眾集會而床座不足、多人患病、天降雨、發生鬥諍、說戒時夜已深，像這樣的種種因緣，都開許略說戒。\n說戒師應當衡量難緣的遠近，觀察時間的早晚：危難若還遠，就為大眾誦說前三篇，誦完之後，其餘的便省略不說；若危難已逼近，以及有疾病、寒冷酷熱等因緣，就只為大眾誦說戒序，誦完之後，其餘的便省略不說。怎樣略說呢？誦完說戒序、問過清淨之後，應當這樣說：", "i": "u356", "n": 493, "s": "第15篇　說戒"}, {"v": "卷上", "o": "諸大姉！是八波羅夷法，僧常聞。」乃至「諸大姉！是七滅諍法，僧常聞。", "t": "「諸位大姊！這八條波羅夷法，僧眾平時都已聽聞。」如此一直略說到最後：「諸位大姊！這七條滅諍法，僧眾平時都已聽聞。」", "i": "u357", "n": 494, "s": "第15篇　說戒"}, {"v": "卷上", "o": "已下必須廣說；若難卒至，即說序已，云：「餘者僧常聞。」若序不得說者，應云：「某日布薩說戒時，眾僧各正身、口、意，謹慎莫放逸！」若眾主善能御眾者，每至盛夏、盛冬，恐僧老弱患寒熱者，當為略說；平旦僧集時，維那白：「說戒日，天時盛熱、大寒，恐僧疲弊，大眾宜可早集，當為略說，勿假託因緣，自生厭怠。」若作如是秉眾，亦名善御大眾，心無憂悔。五分：欲作羯磨，僧不可和，當於說戒前作，以說戒是正制，僧不敢散。", "t": "這以下的戒文，就必須完整地誦說。如果難緣突然到來，就在誦完戒序之後說：「其餘的部分，僧眾平常都已聽聞。」如果連戒序也來不及誦說，就應當說：「今天是某日布薩說戒之時，眾僧各自端正身、口、意，謹慎不放逸。」\n如果眾主善於統領大眾，那麼每到盛夏、隆冬時節，顧慮僧眾中年老體弱的人受不了酷熱嚴寒，就應當為大家簡略地說戒。清晨僧眾集合的時候，維那稟白說：「今天是說戒日，天氣酷熱或嚴寒，恐怕僧眾疲憊困頓，大眾應當早些集合，今天將為大家略說戒。不要假託這些因緣作藉口，自己生起厭煩懈怠之心。」能這樣秉法統理僧眾，也叫做善於統領大眾，心中沒有憂慮悔恨。\n《五分律》說：想要作羯磨而僧眾難以和合齊集時，應當在說戒之前作；因為說戒是正制必行的法事，僧眾不敢散去。", "i": "u358", "n": 495, "s": "第15篇　說戒"}, {"v": "卷上", "o": "次明別人法者，若隨所住處，二人已上，至說戒日，還掃灑處所，具布薩調度，一如前式，待客尼來；若四人以上，即須廣說，二三人以下，各相向說云。", "t": "接下來說明別人法：不論住在哪一個住處，只要有二人以上，到了說戒日，仍舊要將處所灑掃乾淨，備辦布薩所需的各項器具，完全依照前面的規格，等候客尼前來。若人數達到四人以上，就必須廣說戒本；若是二、三人以下，就彼此面對面這樣說：", "i": "u359", "n": 496, "s": "第15篇　說戒"}, {"v": "卷上", "o": "大姉一心念！今僧十五日說戒，我比丘尼某甲清淨。", "t": "「大姊請專心憶念：今天是僧團十五日說戒的日子，我比丘尼某甲清淨。」", "i": "u360", "n": 497, "s": "第15篇　說戒"}, {"v": "卷上", "o": "若對二尼，應云「二姉一心念」，餘語同前。若一人者，應云：「今僧十五日說戒，我比丘尼某甲清淨。", "t": "如果面對的是兩位尼眾，就應該說「二姉一心念」，即請兩位姊姊一心專注憶念，其餘的文句與前面所說的相同。如果只有自己一人，就作心念布薩，須心念口言，也就是自己口中陳說，不對他人，應該說：「今僧十五日說戒，我比丘尼某甲清淨。」即今天僧團十五日說戒，我比丘尼某甲清淨。", "i": "u361", "n": 498, "s": "第15篇　說戒"}, {"v": "卷中", "o": "終南山沙門釋　道宣　述", "t": "終南山的沙門釋道宣撰述。", "i": "u362", "n": 1, "s": "第15篇　說戒（續）"}, {"v": "卷中", "o": "○安居篇第十六", "t": "第十六篇：安居。", "i": "u363", "n": 2, "s": "第16篇　安居"}, {"v": "卷中", "o": "此篇大門有八：一、制意，二、結時，三、夏閏，四、對首，五、心念，六、忘成，七、及界，八、移夏。", "t": "本篇大門有八：一制意、二結時、三夏閏、四對首、五心念、六忘成、七及界、八移夏。", "i": "u364", "n": 3, "s": "第16篇　安居"}, {"v": "卷中", "o": "第一制意者，此律通制三時，意存愍物；又偏約夏月，情在三過：一、無事遊行，妨修道業；二、損傷物命，違慈實深；三、所為既非，招世譏謗。防茲三咎，故制安居。", "t": "第一門、制定安居的用意：本律通制三時不得無事遊行，本意在於憐愍眾生；又特別就夏月而言，制意所慮在於三種過失：一、沒有正事而到處遊行，妨礙修習道業；二、損傷眾生物命，違背慈悲實為深重；三、所作所為既然不正當，便招致世人的譏嫌毀謗。為了防範這三種過咎，所以制定安居。", "i": "u365", "n": 4, "s": "第16篇　安居"}, {"v": "卷中", "o": "第二結時者，此律雖云前、中、後三時，若據結文，正自有二：謂四月十六結者，是前；十七日已去，迄至五月十六日來，皆稱於後；唯一日為前，二十九日為後。此律：大僧不結前安居，吉；尼不結前，同吉；不結後，提；不依大僧安居，亦提。", "t": "第二、結安居的時間：本律雖然說有前、中、後三個時段，但若依據結安居的文辭來看，其實只有兩種，也就是四月十六日結安居的稱為「前」，從十七日以後一直到五月十六日為止，都稱為「後」；只有一天屬於前安居，二十九天屬於後安居。本律規定：大僧若不結前安居，犯突吉羅；比丘尼不結前安居，同樣犯突吉羅；若不結後安居，犯波逸提；不依止大僧而安居，也犯波逸提。", "i": "uGAP08-1", "n": 5, "s": "第16篇　安居"}, {"v": "卷中", "o": "明了論云：無五過處得安居：一、太遠聚落，求須難得；二、太近城市，妨修道業；三、多有蟻蚊，自他兩損；四、無可依人（依人須具五德：一、求聞令聞，二、已聞令清淨，三、能決疑網，四、通道達俗無滯，五、除邪見、得正見）；五、無施主供給藥食。有此五過，不可安居。", "t": "《明了論》說：在沒有五種過患的地方才可以安居：一、距離村落太遠，所需的資具難以求得；二、距離城市太近，妨礙修習道業；三、多有螞蟻、蚊蟲，對自己與眾生雙方都有損害；四、沒有可以依止的人；所依止的人必須具備五種德行：一、有人求聞佛法時能使其聽聞，二、對已經聽聞的法義能使其清淨無誤，三、能決斷心中的種種疑惑，四、通達道法與世俗人情而無所滯礙，五、能破除邪見而獲得正見；五、沒有施主供給醫藥與飲食。只要有這五種過患，就不可在此安居。", "i": "uGAP08-2", "n": 6, "s": "第16篇　安居"}, {"v": "卷中", "o": "僧祇云：若親里請尼者，先教請比丘；不肎者，不得受請。", "t": "《摩訶僧祇律》說：如果親戚鄉里邀請比丘尼，比丘尼應當先教他們去邀請比丘；若對方不肯，就不得接受邀請。", "i": "uGAP08-3", "n": 7, "s": "第16篇　安居"}, {"v": "卷中", "o": "見論云：尼依比丘住處，半由旬得安居，過者不得。前夏檀越為尼請比丘來，而尼已安居竟，乃至後夏初，比丘有緣事不來，當更請餘比丘來；若不得來，應去；路有難事者，得安居。若初安居竟，比丘有緣事去，尼後方知，已結安居者不得移去，得住無罪；若夏竟，不得無比丘處自恣，應覓作法。", "t": "《善見論》說：比丘尼依止比丘住處在半由旬以內，才可以安居；超過半由旬就不可以。如果前安居時，施主為比丘尼邀請比丘前來，而比丘尼已經結安居完畢，直到後安居開始時，那位比丘卻因有緣事而沒來，就應當再另請其他比丘前來；如果還是請不到人來，比丘尼就應當離開；若道路上有危難情事，則可以在原處安居。如果起初結安居完畢後，比丘因有緣事而離開，比丘尼後來才知道，那麼已經結好安居的比丘尼不可遷移離開，可以住下而無罪。如果安居結束時，不得在沒有比丘的地方行自恣，應當另覓有比丘之處作自恣法。", "i": "uGAP08-4", "n": 8, "s": "第16篇　安居"}, {"v": "卷中", "o": "僧祇云：雖在一比丘處安居，至半月時，亦應請問布薩，無者，三由旬內有僧通結取故。", "t": "《摩訶僧祇律》又說：即使只在一位比丘的住處安居，到了半月時也應當向他請問布薩；若當地沒有比丘，由於在三由旬以內有比丘僧眾時可以連通結界攝取，所以應當連通結界。", "i": "uGAP08-5", "n": 9, "s": "第16篇　安居"}, {"v": "卷中", "o": "五分云：有比丘自不持律，不依持律人安居，夏中生疑，又無問處，乃至佛言：「依持律處安居。若房舍迮者，聽近持律師七日往還處，於中遙依安居，有疑往問。」", "t": "《五分律》說：有比丘自己不能熟持律法，又不依止持律之人安居，夏安居期間心生疑惑，又沒有可以請教的地方，乃至佛陀說：「應當依止在有持律者的地方安居。如果當地房舍狹窄，允許在距離持律師七日可以往返的附近處所，於其中遙遙依止持律師而安居，有疑問就前往請教。」", "i": "uGAP08-6", "n": 10, "s": "第16篇　安居"}, {"v": "卷中", "o": "此律：不依廣誦二部律師，得提。", "t": "本律規定：不依止廣誦二部律的律師，犯波逸提。", "i": "uGAP08-7", "n": 11, "s": "第16篇　安居"}, {"v": "卷中", "o": "義云：大僧丈夫，尚令依律師處住，有疑皆須往問，譬如嬰兒，無時暫離乳母，恐生罪累，自溺長津。今時尼眾，觸事無知，動乖法式，志性昏滯，好染俗風，孤遊自在，不承戒律；或伽藍偏僻，獨處邊荒；或憒閙城隍，無僧迥立。所以舉動不仁，行步失禮，八敬罕自無聞，三業唯加蜂蠆，敬俗倒為闍棃，慢僧反為師弟。靜言此事，良用愾然。", "t": "就義理來說：大僧身為大丈夫，尚且要求他們依止在律師的住處，凡有疑問都必須前往請教，就好比嬰兒沒有一時能暫離乳母一般，唯恐招致罪業牽累，使自己沉溺在漫長的苦津之中。然而現今的比丘尼眾，遇事一無所知，動輒違背法式；志性昏昧遲鈍，喜好沾染世俗風氣，獨自遊行、放任自在，不肯承稟戒律；有的寺院地處偏僻，獨自居住在邊遠荒涼之地；有的身處喧鬧的城市之中，沒有比丘僧眾而孤立自處。因此舉止有失仁德，行步失去禮儀，對八敬法幾乎毫無所聞，身、口、意三業加諸於人的，唯獨如同毒蜂、蠍子一般；恭敬世俗之人，反倒尊奉其為阿闍梨；輕慢大僧，反倒視之為弟子輩。靜心細思這些事，實在令人深感慨嘆。", "i": "uGAP08-8", "n": 12, "s": "第16篇　安居"}, {"v": "卷中", "o": "第三、夏閏者。若閏五月、六月，定百二十日安居。若閏四月者，從四月十六日至閏月一日結者，竝四月住；若閏月二日已後結者，漸漸轉少，以越閏月故；若五月一日迄至十六日結者，皆三月住。若閏七月，從四月十六日及五月一日結者，盡三月住，由未至閏故；若五月二日已後結者，皆四月住，由九十日未滿，含閏月故。", "t": "第三、關於夏安居遇到閏月的問題：如果閏五月或閏六月，安居就固定為一百二十天。如果閏四月：從四月十六日到閏四月初一之間結安居的，都住四個月；從閏四月初二以後結安居的，住的日數就逐漸減少，因為已經越過部分閏月的緣故；從五月一日到五月十六日結安居的，都住三個月。如果閏七月：從四月十六日以及五月一日結安居的，都住滿三個月，因為安居期滿時還沒有到閏月的緣故；從五月二日以後結安居的，都住四個月，因為九十天還未滿，安居期已包含閏月的緣故。", "i": "u366", "n": 13, "s": "第16篇　安居"}, {"v": "卷中", "o": "第四、對首。具修威儀，至一尼前云。", "t": "第四，對首作法：應當整肅、具足威儀，走到一位比丘尼的面前，這樣說：", "i": "u367", "n": 14, "s": "第16篇　安居"}, {"v": "卷中", "o": "大姉一心念！我比丘尼某甲，依某僧伽藍，前三月夏安居，房舍破修治故。", "t": "大姊，請專心憶念：我比丘尼某甲，依止某某僧伽藍，結為期三個月的前安居，因為房舍破損須加修治的緣故。", "i": "u368", "n": 15, "s": "第16篇　安居"}, {"v": "卷中", "o": "五分》、《十誦》：前人報云：「汝莫放逸。」答云：「受持。」又，義問云：「依誰持律？」答云：「某律師。」告云：「有疑當往問。」答云：「爾。」若依村落、山間、樹下安居者，即須改前伽藍，又除「房舍破修治」等語，直云。", "t": "依《五分律》與《十誦律》，所對的那位尼眾回應說：「汝莫放逸。」作法的人答說：「受持。」鈔主又依律意增補此問，由對方問道：「依誰持律？」作法的人答說：「某律師。」對方告知說：「有疑當往問。」作法的人答說：「爾。」如果是依村落、山間、樹下安居的，就必須改換前面詞句中的「僧伽藍」，並且除去「房舍破修治」等語，直接說：", "i": "u369", "n": 16, "s": "第16篇　安居"}, {"v": "卷中", "o": "大姉一心念！我比丘尼某甲，今依某村家，前三月夏安居。", "t": "大姊，請專心一意聽著：我比丘尼某甲，現在依止某村的某戶人家，結前安居，為期三個月。", "i": "u370", "n": 17, "s": "第16篇　安居"}, {"v": "卷中", "o": "或有人云「依皇帝聚落安居」，或云「依法界安居」，此皆不成，反結無知不學之罪。問：所以寺中令修治房舍耶？答：僧房修治，用通三世：前人料理，今人受用；今人修補，以擬當來；若不修治，三世不續。後安居者云。", "t": "有人說「依皇帝聚落安居」，是籠統標舉皇帝所轄的國土聚落這類大範圍作為安居的所依；也有人說「依法界安居」，是以抽象的法界作為所依。二者都沒有依實際住處的名稱牒入，這樣的安居都不成立，反而結成無知與不學的罪過。\n問：為什麼在寺院中安居，要規定修治房舍呢？\n答：僧房的修治，功用貫通三世：前人整治經營，今人得以受用；今人加以修補，是為了留給將來的人使用。如果不修治，過去、現在、未來三世的相續就斷絕了。\n若是結後安居的人，就說：", "i": "u371", "n": 18, "s": "第16篇　安居"}, {"v": "卷中", "o": "大姉一心念！我比丘尼某甲，依某僧伽藍，後三月夏安居，房舍破修治故。", "t": "「大姊，請專心聽我陳說：我比丘尼某甲，依止某僧伽藍，結後三個月的夏安居，因為房舍破損、須加修補整治的緣故。」", "i": "u372", "n": 19, "s": "第16篇　安居"}, {"v": "卷中", "o": "第五、心念者。計尼不合心念，今依《十誦》，饑儉時開尼依親獨住，所以偏出此文。具修威儀，至佛前云。", "t": "第五是心念法。按理說來，比丘尼不應該用心念的方式安居；現在依據《十誦律》，在饑荒歉收的時候，開許比丘尼依附親屬而獨自居住，所以才特別列出這段作法之文。應當把威儀整備齊全，到佛像前這樣說：", "i": "u373", "n": 20, "s": "第16篇　安居"}, {"v": "卷中", "o": "若比丘尼某甲，今依某聚落某家，前三月夏安居。", "t": "「我比丘尼某甲，現在依止某聚落中的某戶人家，結前三個月的夏安居。」", "i": "u374", "n": 21, "s": "第16篇　安居"}, {"v": "卷中", "o": "第六、忘成者。此律，忘不心念，若為安居故來，便成安居。義云：既言「為來」者，舊住之人，良恐不開；若舊住人要此期夏，忽忘不說，亦須量行。若外來尼不為益事者，此便不成。", "t": "第六種是「忘成」，即忘記作法而安居仍得成就。《四分律》說：忘記而沒有作心念安居的宣告，只要是為了安居而來，就成就安居。依義理推論說：既然律文說的是「為來」，著重在一個「來」字，指的是從外而來的人，那麼原本就住在這裡的人，實在深恐不在開許之列。如果舊住的人事先已立下要期，要在此處度過這一夏，只是一時忘記而沒有宣說，也應當斟酌實際情形來處理。若是外來的比丘尼，並不是為了安居這一有益之事而來，這樣就不能成就安居。", "i": "u375", "n": 22, "s": "第16篇　安居"}, {"v": "卷中", "o": "第七、及界者。此律云：一、一脚入界，二、雙脚入界，三、一脚入園，四、雙脚入園，東方明相若出亦開；外來者，不說得成。", "t": "第七種是「及界」，即及時趕到界內。《四分律》說：一、一隻腳已踏進界內；二、兩隻腳都已踏進界內；三、一隻腳已踏進僧伽藍園內，即寺院的園地；四、兩隻腳都已踏進僧伽藍園內。在這四種情形下，東方若已現出破曉的明相，也開許從外處趕來的人，即使沒有作法陳說安居，安居仍然成就。", "i": "u376", "n": 23, "s": "第16篇　安居"}, {"v": "卷中", "o": "第八、移夏者。此律難有二種，謂命、梵二難也。", "t": "第八，移夏，即遷移安居的處所。本部《四分律》中說，危難有兩種，就是命難與梵行難。", "i": "u377", "n": 24, "s": "第16篇　安居"}, {"v": "卷中", "o": "一、命難者，謂鬼神、賊等及惡獸、毒蟲，不得如意飲食、醫藥及隨意使人，若安居住此，便則斷命，故律云：「我在此住，必為我命作留難。」佛皆聽去。", "t": "一是命難：指鬼神、盜賊等，以及惡獸、毒蟲，或得不到如意的飲食、醫藥和可隨意使喚的人。若在此安居住下去，便會斷送性命。所以律中說：「我住在這裡，必定會危及我的性命。」佛都聽許離去。", "i": "u377-2", "n": 25, "s": "第16篇　安居"}, {"v": "卷中", "o": "二、梵難者，謂被男子誘調，畏犯重戒，佛亦聽去。", "t": "二是梵行難：指被男子引誘調戲，怕犯重戒，佛也聽許離去。", "i": "u377-3", "n": 26, "s": "第16篇　安居"}, {"v": "卷中", "o": "若至彼結成者，從初去日，即須勤覓安身處；若住處未得已來，雖曾經宿，不破安居，以非故心輕慢意也；反前不成。若得住處，夏法隨食，於彼無緣不得出界，恐破夏也；若本處無難，亦不得來，由已結成故。", "t": "若到彼處要結成安居，從最初離開的那天起，就必須勤懇尋找安身之處。在尚未找到住處的期間，即使曾經在外過夜，也不破安居，因為不是出於故意輕慢的心；反之，若出於故意輕慢而不勤覓住處，安居便不成。若已找到住處，安居之法便隨身延續到彼處，沒有因緣不得出界，以免破夏。若原本住處已無危難，也不得返回原處，因為安居已在新處結成的緣故。", "i": "u377-4", "n": 27, "s": "第16篇　安居"}, {"v": "卷中", "o": "此律，俗家安居，見有二難，當白檀越求移去，若聽不聽，但應自去。若依餘部，不云得夏；今準《母論》得夏，故論云：「移夏不破安居也。」", "t": "本部律中說：在俗人家中安居，見到這兩種危難，應當稟白檀越，請求遷移離去；無論檀越聽許與否，都應自行離去。若依其餘諸部律，並不說如此移夏能得夏；如今準依《毗尼母論》則得夏，因為論中說：「移夏並不破壞安居。」", "i": "u377-5", "n": 28, "s": "第16篇　安居"}, {"v": "卷中", "o": "問：遇緣出界經宿，忘不受日，得夏否？答：諸部竝無文斷，唯《五百問事》云：「夏中忘不受七日出界，憶即悔者得；一坐中不得過三悔，不成歲。」", "t": "問：遇到事緣出界，在外過夜，忘了受日法，還能得夏嗎？\n答：諸部律都沒有明文判定，只有《五百問事經》說：「夏安居中忘了受七日法而出界，想起來就立即懺悔的，可以得夏；但一個安居期中，這類懺悔不得超過三次，超過三次便不算這一夏。」", "i": "u377-6", "n": 29, "s": "第16篇　安居"}, {"v": "卷中", "o": "問：遇緣出界，忽值水陸道斷諸難，不及本界，失夏以否？答：諸部亦無文斷，古昔大德校量三藏，義開得夏：若為三寶益事、友已大事，不及界者開；自餘悠悠無益之事，破夏不疑。", "t": "問：遇到事緣出界，忽然碰上水路、陸路斷絕等種種危難，來不及回到本界，會失夏嗎？\n答：諸部律也沒有明文判定。古昔大德考校衡量三藏的義理，開許得夏。若是為利益三寶的事，以及自己的大事，而來不及趕回本界的，開許得夏；其餘悠悠閒散、無益的事，破夏是毫無疑問的。", "i": "u377-7", "n": 30, "s": "第16篇　安居"}, {"v": "卷中", "o": "○受日篇第十七", "t": "○第十七篇：受日", "i": "u378", "n": 31, "s": "第17篇　受日"}, {"v": "卷中", "o": "此篇大門有六：一、受緣，二、互用，三、受法，四、得重，五、逢難，六、五利。", "t": "本篇的大綱分為六門：一是受日的事緣；二是所受日限的互相挪用；三是受日的作法；四是能否重複受日；五是出界之後遇上了難緣；六是五利，即迦提月所開的五種利益。", "i": "u379", "n": 32, "s": "第17篇　受日"}, {"v": "卷中", "o": "第一、受緣者。此律云：凡受日之緣，要為三寶利益大事、檀越請喚生善滅惡，得去。《十誦》云：「為誰受日？為七眾受，並為生善滅惡應去。」若遣使、不遣使，俱得受；若中路聞死、反戒、入外道眾、八難事絕，皆不應去。《僧祇》：若為私己求覓衣鉢、藥草等，悉成受日；義云：貧者應開，富者宜禁。若病重不堪受日，直去不破夏，故律云：不得隨意及看病人等，得去無犯。若為治生覓利，假託貴勝乞穀麥等，或受雇撿校經像、營造佛盆，或悠悠請喚、心不段重，或為一緣受日、遂歷眾事，或即事不實、虗搆外緣，如是無益之事，並不合受日。既不合受，妄數為夏，無德自大，冐受信施，計滿犯重；《見論》云：「自長己夏，受施犯重。」《五百問事》：破戒治生得財造佛，尚不免地獄，何況得福。", "t": "第一門是受日的緣由。《四分律》說：凡是受日出界的緣由，必須是為了三寶利益的大事、施主的請喚，能生善滅惡的事，才可以去。\n《十誦律》說：問：為誰受日？答：為七眾弟子而受，而且都必須是為了生善滅惡，才應當去。不論對方派人來請，或沒有派人來請，都可以受日。如果在半路上聽說對方已經死了、已經捨戒還俗了、已加入外道眾中，或者對方遇上王難、賊難、水難、火難等八難，以致所要辦的事已經斷絕，就都不應該去。\n《僧祇律》說：即使是為了自己私人求覓衣、缽、藥草等事，也都能成就受日。依義理判定：貧困的人應當開許，富裕的人則應禁止。\n如果是自己病重，不堪作受日法，直接離去也不破夏。所以律中說：得不到合意的飲食醫藥，以及沒有人看病等情況，都可以離去，不犯破夏。\n若是為了經營生計、謀求財利，假託權貴的名義去乞求穀麥等物；或是受人僱用，去督理經像的造作、營造供佛的盆供；或者只是泛泛悠悠的請喚，心中並不殷重懇切；或者為了一樁事受日出界，卻接著去承辦種種其他事務；或者所說的事由根本不實，只是虛構外在的藉口——像這些無益的事，都不合受日。既然不合受日，卻妄自把這樣的安居算作一夏，自己無德而妄自尊大，冒濫接受信眾的布施，按所受財物計值，滿五錢就犯波羅夷重罪。\n《善見論》說：自己虛增自己的夏臘，以此接受信施，犯波羅夷重罪。\n《五百問事》說：破戒經營生計所得的財物，拿來造佛像，尚且不免地獄之苦，何況還說能得福呢？", "i": "u380", "n": 33, "s": "第17篇　受日"}, {"v": "卷中", "o": "第二、互用者。問：得互用否？答：《十誦》云：受七日到聚落，七日未盡，所作事未竟，還來至本處，佛言：「有殘夜在，應白已去。」義云：謂本事上得白已餘用，非謂異事上得；若總為三寶事受日者，得將互用，如為營佛事，得法、僧上用，以俱有受日緣故。若有大益私營經像，或當僧次請及捨請等，成受緣；然捨請須問本主，聽者得成。", "t": "第二門是「互用」。\n問：所受日數可以互相挪用嗎？\n答：《十誦律》說：受了七日法前往聚落，七日還沒有用完，所辦的事還沒有辦完，就返回本處。佛說：還有剩餘的夜數在，應當白告之後再去。依義理判定說：這是說就原來所受的那件事，白告之後可以使用剩餘的日數，並不是說換作別的事也可以這樣使用。如果受日時本是總為三寶之事而受的，就可以拿來互相挪用：例如為營辦佛事而受日，也可以用在法事、僧事上，因為這三者同樣都具有受日的因緣。若有大的利益，自行營辦寫經、造像之事，或輪到自己接受施主依僧中次第輪值而作的供請，以及接受他人捨讓的供請等，也都構成受日的因緣。但接受這種捨讓的供請，必須先請問原施主，得到他的聽許才算成立。", "i": "u381", "n": 34, "s": "第17篇　受日"}, {"v": "卷中", "o": "第三、受法者。", "t": "第三項是受日的作法。", "i": "u382", "n": 35, "s": "第17篇　受日"}, {"v": "卷中", "o": "大姉一心念！我比丘尼某甲，今受七日法出界外，為某事故，還來此中安居，白大姉知。", "t": "「大姊請專心一意聽我稟白：我比丘尼某甲，現在受持七日法，要走出界外，是為了某事的緣故；之後仍要回到這裡安居。特此稟白大姊，讓大姊知悉。」", "i": "u383", "n": 36, "s": "第17篇　受日"}, {"v": "卷中", "o": "此對首法，律中唯有受名，無其受文，相傳義說，唯得六夜在外，至第七日必須還也。若依界安居，不得戒場上受日，以非要心本處故；又二界各別，然不得互用。若依戒場安居亦然，互宿亦不得。問：尼得羯磨受日否？答：諸教並無文開。故《僧祇》：尼安居中，無求聽羯磨法，佛事、僧事而遊行，故知尼無也。義云：為尼是女弱，不許孤遊；若當延日在外，恐難逼臨危，可懼之甚！所以聖意知時禁防，不在出限。今有諸德，猶順人情，義開羯磨；敬惟斯理，良恐非然。假令事益雖多在外，或為王臣請喚，非七日可了，寧可數受七日；七日不辦，同難直去，無犯。", "t": "這個對首受日法，律中只有「受日」的名稱，並沒有受法的文句，是歷代相傳、依義理擬說而成的。受日者只准在外過六夜，到第七天就必須回來。如果是依大界安居，不得在戒場上受日，因為戒場不是當初立誓安居的本處；而且大界與戒場二界各別，所以不得互相通用。若是依戒場安居，也同樣不得在大界上受日；在兩界互相過夜也不可以。\n問：比丘尼可以用羯磨法受日嗎？答：諸部律教都沒有明文開許。《僧祇律》中，比丘尼在安居期間，並沒有為佛事、僧事而外出遊行所用的「求聽羯磨」法，由此可知尼眾沒有羯磨受日。依義理推論說：因為尼眾是女眾、體弱，不許獨自遠行；如果延長時日在外，恐怕遭難事逼迫、面臨危險，極為可怕。所以佛陀的心意，是深知時宜而加以禁制防範，並不開許尼眾超過期限在外。現今有些大德卻仍隨順人情，依義理開許尼眾作羯磨受日；敬謹思惟這個道理，實在恐怕不是這樣。假使在外所辦的利益之事雖多，或是受到國王、大臣的請喚，不是七天所能辦完的，也寧可多次受七日法；若七天仍辦不成，就比照遇到難緣的情形，逕直前去，沒有違犯。", "i": "u384", "n": 37, "s": "第17篇　受日"}, {"v": "卷中", "o": "第四、得重者。問：得重受日否？答：觀其文意，但為生善利益事，得重不疑；《明了論》亦開重受七日。《十誦》不許者，為部別不同。大唐波頗三藏亦開重受，西域大德來者，皆不聞單受之法。", "t": "第四、得重：\n問：受日可以重複受嗎？\n答：考察律文的意旨，只要是為了生善、利益的事，重複受日毫無疑問是可以的。《明了論》也開許重複受七日法；《十誦律》之所以不許重受，是因為部派不同、律制有別的緣故。大唐的波頗三藏法師也開許重複受日；凡從西域前來的大德，都不曾聽說過只許受一次的「單受」之法。", "i": "u385", "n": 38, "s": "第17篇　受日"}, {"v": "卷中", "o": "第五、逢難者。律：受七日出界，為父母、兄弟、姉妹、故二、私通、生善滅惡緣等，至意留住過日，得夏；若難息，即須急還，不得停住，免破夏疑。《僧祇》云：「夏中和僧去，在道不得遷迴，當直去，至彼和了即還。」故知停住，寧不破夏。", "t": "第五、遇到留難的情形。《四分律》說：受七日法出界外，若是為了父母、兄弟、姊妹、出家前的配偶、舊日有私通關係的人，以及生善滅惡等因緣而去，這些人誠心殷勤地挽留，以致超過了七日的期限，仍然成就安居。但若留難的因緣已經止息，就必須趕快返回，不得停留，以免有破夏之疑。《摩訶僧祇律》說：安居期間為了調和僧眾的諍事而出界，在路上不得迂迴耽擱，應當直接前往該處，到了那裡把事情調和完畢，就立即返回。由此可知，停留不走，難道還能不破夏嗎？", "i": "u386", "n": 39, "s": "第17篇　受日"}, {"v": "卷中", "o": "第六、五利者。此律：七月十六日夏罷已，至八月十五日已來，名迦提月，此翻名功德月，以夏坐有勞，開受五利潤益。比丘尼五利是何？一、得背請；二、得別眾食；三、得食前食後至別家，不須囑授；四、得畜長衣不說淨；五、得離三衣宿。《見論》云：四月十六日結者得五利，十七日已去不得，名賞前罰後也。《僧祇》：有五種人不得安居衣：一、被舉人，二、破夏人，三、罷道人，四、死人，五、不囑授人。破夏有十種過失：一、為諸佛所訶，二、為諸天、世人所訶，三、破夏，四、得罪，五、不得受功德衣，六、不得五事利，七、不得攝施，八、不得安居衣，九、惡名流布，十、後悔入地獄。", "t": "第六是「五利」。依《四分律》，從七月十六日夏安居結束以後，直到八月十五日為止，這段期間稱為迦提月，漢譯名為「功德月」。因為結夏安居三個月辛勞，所以開許受用五種利益，來潤益比丘尼。這五利是哪些呢？一是可以背請，即捨下先前已受的請食，另赴他處受食；二是可以別眾食，即與僧眾分開而另行聚食；三是食前或食後到別人家去，不必先向另一位比丘尼囑授；四是可以蓄存三衣以外多餘的長衣，不必作說淨；五是可以離開三衣在外過夜。《善見論》說：四月十六日結前安居的人得這五利，四月十七日以後才結夏的人就不得，這叫作「賞前罰後」——獎賞先安居的人，罰抑後安居的人。《僧祇律》說：有五種人不得分得安居衣，一是被僧作了舉羯磨的被舉人，二是破夏的人，三是罷道還俗的人，四是已死的人，五是離去時沒有囑託別人代取自己衣分的不囑授人。破夏有十種過失：一是被諸佛訶責，二是被諸天與世人訶責，三是破夏，四是犯戒而招致罪過，五是不能受功德衣，六是不得五事之利，七是不能攝受檀越的布施，八是不得安居衣，九是惡名流布，十是事後悔恨而墮入地獄。", "i": "u387", "n": 40, "s": "第17篇　受日"}, {"v": "卷中", "o": "○自恣篇第十八", "t": "第十八篇：自恣。", "i": "u388", "n": 41, "s": "第18篇　自恣"}, {"v": "卷中", "o": "此篇大門有十：一、制意，二、時節，三、集僧，四、差使，五、簡人，六、秉法，七、五德，八、自恣，九、略法，十、雜法。", "t": "本篇的大綱分為十門：一是說明制定自恣的用意，二是自恣的時節，三是集合僧眾，四是差派使者（前往比丘僧中說自恣），五是簡選人選，六是主持作法，七是「五德」，八是自恣的作法，九是略自恣法，十是其他雜法。", "i": "u389", "n": 42, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第一、制意者。夫九旬修道，精練身心，人多迷己，不自見過，理宜仰憑清眾，垂慈誨示，縱宣己罪，恣僧治舉，內彰無私隱，外現有純淨，故曰自恣也。", "t": "第一，制立自恣的用意：在九十天中修道，精勤淬鍊身心；然而人大多對自己迷惑無知，看不見自身的過失，按理應當仰仗清淨僧眾，請他們慈悲地教誨指示。自己毫無保留地發露罪過，任由僧眾舉罪、處治；這樣對內彰顯自己對罪過全無私自覆藏，對外呈現一片純淨，所以稱為「自恣」。", "i": "u390", "n": 43, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第二、時節者。此律：七月十四日、十五日並得自恣，又急施衣戒中十六日亦得自恣，此則三時為。又叉不知何時自恣，佛聽大食、小食上，上座應白。", "t": "第二，時節：本部《四分律》說七月十四日、十五日都可以自恣；又「急施衣戒」中，十六日也可以自恣，如此便有三個可以自恣的日子。又，若不知道該在哪一天自恣，佛允許在大食或小食的時候，應由上座作白宣告。", "i": "u391", "n": 44, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！今白月十五日，眾僧集某處自恣。", "t": "「大姊僧眾請聽：今天是白月十五日，大眾僧集合在某處舉行自恣。」", "i": "u392", "n": 45, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第三、集僧者。義云：要五人已上，方得白差自恣。若破夏、不安居人，雖不得夏，以舉罪義同，理必依眾，恣僧治舉。此律：若後安居人從前安居者自恣，仍須待日滿得還。乃至沙彌尼等，亦須盡集，以治舉義同，待僧唱出，方可得去。", "t": "第三、集僧。依義理說，必須五人以上，才可以作白差派受自恣人，行僧法自恣。至於破夏以及沒有安居的人，雖然不能算得這一年的夏臘，但因為舉罪的意義相同，按理也必須依止僧眾，任由僧眾治罰舉罪。本律說：若是後安居的人，跟隨前安居的人自恣，仍必須等到自己的安居日數圓滿，才可以離去。乃至沙彌尼等人也必須全部集合，因為治罰舉罪的意義對她們同樣適用；要等到僧中唱令未受具足戒者退出之後，才可以離去。", "i": "u393", "n": 46, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第四、差使者。此律：「比丘尼夏安居竟，比丘僧夏安居竟，聽差一比丘尼為僧故，往大僧中說自恣。」《十誦》云：應差二勦了知法尼往僧中。當作白和僧。", "t": "第四、差派使者。《四分律》說：比丘尼僧夏安居圓滿，比丘僧夏安居也圓滿時，聽許差派一位比丘尼，代表尼僧前往比丘大僧中陳請自恣。《十誦律》說：應當差派兩位精明幹練、通曉律法的比丘尼前往比丘僧中；差派時應當先作稟白，問僧和合。", "i": "u394", "n": 47, "s": "第18篇　自恣"}, {"v": "卷中", "o": "僧今和合，何所作為？」答：「差比丘尼某甲，往僧中說三事自恣羯磨。", "t": "問：僧眾如今已經和合集會，要作什麼事？答：要作的是差派比丘尼某甲前往比丘僧中、宣說三事自恣的羯磨。", "i": "u395", "n": 48, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！若僧時到，僧忍聽，僧差比丘尼某甲，為比丘尼僧故，往大僧中，說三事自恣見、聞、疑。白如是。", "t": "諸位大姊僧眾請聽：如果僧團的時機已到，請僧眾聽許——僧團差派比丘尼某甲，為了比丘尼僧團的緣故，前往比丘僧團當中，陳說見、聞、疑這三事的自恣。以上的白告就是這樣。", "i": "u396", "n": 49, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！今差比丘尼某甲，為比丘尼僧故，往大僧中，說三事自恣見、聞、疑。誰諸大姉忍僧差比丘尼某甲，為比丘尼僧故，往大僧中，說三事自恣見、聞、疑者默然，誰不忍者說。僧已忍差比丘尼某甲，為比丘尼僧故，往大僧中，說三事自恣見、聞、疑竟。僧忍默然故，是事如是持。", "t": "諸位大姊僧眾請聽：現在差派比丘尼某甲，為了比丘尼僧團的緣故，前往比丘僧團中，宣說見、聞、疑三事自恣。諸位大姊當中，凡同意僧團差派比丘尼某甲為比丘尼僧團前往比丘僧團中宣說見、聞、疑三事自恣的，請保持沉默；不同意的，請說出來。僧團已經同意，差派比丘尼某甲為比丘尼僧團前往比丘僧團中宣說見、聞、疑三事自恣一事已辦畢。由於僧團同意而默然的緣故，這件事就這樣決定奉行。", "i": "u397", "n": 50, "s": "第18篇　自恣"}, {"v": "卷中", "o": "又應口差二三人尼為伴，往大僧中，禮僧足已，曲身合掌云。", "t": "此外，還應當以口頭指派兩三位比丘尼作為同伴，陪同前往比丘僧眾之中。到了僧中，頂禮僧足之後，躬身合掌說道：", "i": "u398", "n": 51, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大德僧聽！比丘尼僧夏安居竟，比丘僧夏安居竟，比丘尼僧說三事自恣見、聞、疑。大德僧慈愍故語我，我若見罪，當如法懺悔。", "t": "大德僧眾請聽：比丘尼僧眾的夏安居已經結束，比丘僧眾的夏安居也已經結束。比丘尼僧眾在此就見、聞、疑三事陳請自恣。懇請大德僧眾慈悲憐愍，把過失告知我；我若見到自己有罪過，定當如法懺悔。", "i": "u399", "n": 52, "s": "第18篇　自恣"}, {"v": "卷中", "o": "尼說已，大僧良久默然。上座應勑尼云：「大眾上下，各並默然，不云見罪，良由尼眾內禁三業，外無三事，內外清淨，並無缺犯。各應如法精勤行道，謹慎莫放逸，如法自恣！比丘尼當傳此教，告眾令知。」使尼答云：「爾，頂戴持。」更設三拜已，便還。當於明日尼僧自恣時，鳴稚集尼僧已，不來者說欲，尼僧等各依行立，被差尼在上座頭立，宣大僧教云。", "t": "使者比丘尼說完之後，比丘僧眾沉默良久，上座這時應當教敕這位比丘尼說：「大眾從上座到下座，全都默然，沒有人說見到你們有罪。這實在是由於尼眾對內禁攝身、口、意三業，對外沒有見、聞、疑三事的過犯，內外清淨，都沒有缺失毀犯。你們各人應當如法精勤行道，謹慎而不放逸，如法自恣。你這位比丘尼應當把這番教敕傳回去，告知大眾，讓大家都知道。」使者比丘尼回答說：「是的，我恭敬頂戴受持。」接著又行三拜，然後返回。\n應當在第二天尼僧自恣的時候，敲擊犍稚集合尼僧；集合完畢，不能前來的人要託人代為說欲。尼僧們各自依行列次第站好，被差遣的比丘尼站在上座席的前端，宣說比丘僧團的教敕說：", "i": "u400", "n": 53, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！僧差我比丘尼某甲，往大僧中，說三事見、聞、疑。大眾上下，並皆默然，不云見罪，良由眾眾內禁三業，外無三事，內外清淨，並無缺犯。各應如法精勤行道，謹慎莫放逸，如法自恣。", "t": "「各位大姊僧請聽：僧團差派我比丘尼某甲，前往大僧中，陳說見、聞、疑三事。大僧的大眾從上座到下座全都默然，沒有說見到罪過。這實在是因為你們大眾在內能禁攝身、口、意三業，對外沒有見、聞、疑三事，內外清淨，都沒有毀缺違犯。各位應當如法精勤修行，謹慎，不要放逸，如法進行自恣。」", "i": "u401", "n": 54, "s": "第18篇　自恣"}, {"v": "卷中", "o": "宣已，諸尼一時合掌頂上，各云：「頂戴持！」然後尼僧安庠自恣。律云：「大僧十四日自恣，已僧十五日自恣。」此二眾相依，故局日時。若大僧病、別眾、眾不和、眾不滿等，尼應遣使問訊大僧；若尼眾病乃至不滿，亦須問訊大僧。問：尼眾不知，所以須問訊大僧耶？答：若知不和，便能為其和解。", "t": "被差的尼宣讀完大僧的教示後，全體尼眾同時合掌高舉到頭頂，各自說「恭敬頂戴受持」，然後尼僧才安詳有序地進行自恣。\n《四分律》說：大僧在十四日自恣，尼僧在十五日自恣。這是因為二眾互相依待的緣故，所以限定自恣的日期。如果大僧一方有病緣、別眾不齊集、僧眾不和合、僧數不滿等情形，尼眾應派遣使者前去問候大僧；如果尼眾自己有病，乃至人數不滿等情形，也同樣必須派人去問候大僧。\n問：是因為尼眾不知道大僧那邊的情形，所以才必須派人去問訊大僧嗎？\n答：若得知大僧有不和合的情況，就能為他們調解，使他們和合。", "i": "u402", "n": 55, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第五、簡人者。此律，要具二種五德，方堪自恣。初五德：一、不愛，二、不恚，三、不怖，四、不癡，五、知自恣、不自恣。第二五德者：一、知時不以非時，二、真實不以虗妄，三、利益不以損滅，四、柔輭不以麤獷，五、慈心不以瞋恚。若不具此二五德，舉不知時，恐惱眾僧，反成自累。《五分》云：要差二人已上，乃至多人。《三千威儀》云：「要差二人，為僧自恣竟，五德自相向出罪，不得求餘人自恣竟，以餘人僧不差故。」《僧祇》、《十誦》云：差有德者作。", "t": "第五、簡選人。《四分律》要求，必須具備兩組五德，才堪能擔任自恣人。第一組五德：一、不因貪愛而偏私；二、不因瞋恚而偏私；三、不因怖畏而偏私；四、不因愚癡而偏私；五、知道什麼是自恣、什麼不是自恣。第二組五德：一、把握時機，不在不合時宜的時候；二、真實，不虛妄；三、利益，不損減；四、柔軟，不粗暴；五、慈心，不瞋恚。如果不具備這兩組五德，舉發罪過時不知時機，恐怕惱亂僧眾，反而連累自己。《五分律》說：要差二人以上，乃至多人。《三千威儀》說：要差二人；為僧眾作完自恣後，兩位五德彼此面對面，互相發露罪過；不得另找其他人來完成自己的自恣，因為其他人未經僧眾差遣。《摩訶僧祇律》與《十誦律》說：要差派有德者來擔任自恣人。", "i": "u403", "n": 56, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第六、秉法者。未差五德前，先須行香湯、淨水、行籌、唱數，一依前說戒法；問，改「說戒」語，加「自恣」詞，然後差其五德。上座秉法，秉法時不須喚五德尼立，恐成別眾。問：「僧集和合否？」答曰：「僧集和合。」又問：「未受具戒者出？」答云：「未受具戒者已出。」又問：「不來比丘尼說欲？」若有說欲者，應云。", "t": "第六，主持作法：在還沒有差派五德人之前，必須先分送香湯與淨水、行籌並唱報人數，一切都依照前面說戒的做法；只是其中的問答用語，要把說戒的詞句改掉，換上自恣的詞句。然後才差派五德人，由上座主持作法。主持作法時，不必喚五德尼站起來，恐怕會構成別眾。問：僧眾集合了沒有？和合了沒有？答：僧眾已集合、和合。又問：未受具足戒的人出去了沒有？答：未受具足戒的人已經出去了。又問：沒有來的比丘尼，有人代為說欲嗎？如果有代說欲的人，應當這樣說：", "i": "u404", "n": 57, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！比丘尼某甲，我受彼欲自恣，彼如法僧事，與欲自恣。", "t": "各位大姊僧請聽：未到場的比丘尼某甲，我已接受她所託付的欲（同意）與自恣；她對於僧團如法辦理的事務，給予同意並託付自恣（由我代為轉達）。", "i": "u405", "n": 58, "s": "第18篇　自恣"}, {"v": "卷中", "o": "今時多有依說戒法說欲。若受欲尼本房內受他說欲者，對僧不得改正，還令問本房取彼尼自恣；若持欲尼對僧錯說者，得臨座改正。成有邊方不學律者，自恣時有病緣等不許他說欲，此迷愚甚矣。", "t": "現今許多人照抄說戒法的詞句來說欲。如果受欲的比丘尼在本房內接受的是對方依說戒法所說的欲，那麼她在僧眾面前不得改正，仍須叫她回本房去問，重新取得那位比丘尼的自恣之欲。如果持欲的比丘尼是在僧眾面前說錯了，則可以在座位上當場改正，說欲便算成立。有些邊遠地區不學律的人，自恣時若有生病等因緣，竟不許託人說欲，這真是迷惑愚癡到了極點。", "i": "u406", "n": 59, "s": "第18篇　自恣"}, {"v": "卷中", "o": "又問：「僧今和合，何所作為？」答：「自恣差人羯磨。」又問：「眾中誰能為僧作五德自恣人？」答云：「某甲能。", "t": "接著又問：「僧眾現在和合集會，要作什麼事？」答：「要作自恣差人的羯磨。」又問：「大眾之中，誰能為僧眾擔任具足五德的自恣人？」回答說：「某甲能。」", "i": "u407", "n": 60, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！若僧時到，僧忍聽，僧差比丘尼某甲、某甲，為僧作受自恣人。白如是。", "t": "各位大姊，請僧眾聽我說。如果僧眾認為時機已經到了，就請僧眾聽許：僧眾差派比丘尼某甲、某甲，為僧眾擔任接受自恣的人。以上的宣告就是這樣。", "i": "u408", "n": 61, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！差比丘尼某甲、某甲，為僧作受自恣人。誰諸大姉忍僧差比丘尼某甲、某甲，為僧作受自恣人者默然，誰不忍者說。僧已忍差比丘尼某甲、某甲，為僧作受自恣人竟。僧忍默然故，是事如是持。", "t": "各位大姊僧眾請聽：僧團差遣比丘尼某甲、某甲，為僧眾擔任接受自恣的人。諸位大姊當中，凡是同意僧團差遣比丘尼某甲、某甲為僧眾擔任接受自恣人的，就保持沉默；不同意的，就說出來。僧團已經同意，差遣比丘尼某甲、某甲為僧眾擔任接受自恣人的事已經完成。由於僧眾認可而默然無異議的緣故，這件事就這樣確定遵行。", "i": "u409", "n": 62, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第七、五德法者。僧既差已，即從座起，至上座前禮足跪住；若在露地，應在伸手相及內，自作白和僧云。", "t": "第七、五德的作法：僧團差派完畢之後，受差的五德就從座位起身，走到上座面前，頂禮上座的雙足，長跪而住。如果是在露天空地舉行，跪的位置應當在與僧眾伸手可以相及的範圍之內，然後自己作白，向僧眾宣告和合自恣，說：", "i": "u410", "n": 63, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！今日眾僧自恣。若僧時到，僧忍聽，和合自恣。白如是。", "t": "大姊僧眾請聽！今天僧眾舉行自恣。如果僧眾認為時機已到，請僧眾忍可聽許：大眾和合一致，共同舉行自恣。以上就是這樣白告。", "i": "u411", "n": 64, "s": "第18篇　自恣"}, {"v": "卷中", "o": "次明行草法者：《五分》云：好泥地，布草座而自恣，並須偏袒右肩、兩膝著地、合掌。自恣前，覓輭淨草，隨僧多少，人別一剪，置上座前；五德取草行之，從上座至下座，人付一剪訖，五德亦須一剪，自一手執，往至本座處，然後敷地。若大眾多，令年少尼三五人助行。訖，五德至上座前白云：「一切僧就草坐，偏袒右肩，長跪合掌，如法自恣。」白已，僧皆警䇿，依唱儀式。《增一經》：如來亦同僧坐於草座，告諸比丘：「汝等各就草座，我欲受歲」等，廣如彼說。", "t": "其次說明分發草座的方法。《五分律》說：應當把地面用泥好好塗治平整，在上面鋪草作為座位而作自恣；並且都必須袒露右肩、雙膝著地、合掌自恣。事先要尋覓柔軟潔淨的草，依僧眾人數多少，每人一把，放置在上座前面。由五德取草分發，從上座依次到下座，每人交付一把；發完之後，五德自己也須留一把，自己一手拿著，走到自己原本的座位處，然後鋪在地上。如果大眾人數多，就令年少比丘尼三、五人協助分發。分發完畢，五德到上座前白告說：「一切僧眾就草座而坐，袒露右肩，長跪合掌，如法自恣。」白告之後，僧眾都警策身心，依照所宣布的儀式而行。《增一阿含經》中，如來也同樣與僧眾坐在草座上，告訴諸比丘說：「你們各自就草座而坐，我要在安居圓滿、自恣之後，受增一歲的法臘。」等等，詳細內容如該經所說。", "i": "u412", "n": 65, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第八、自恣法者。其一五德來至上座前，大敷坐具長跪；第二五德尼至次座前立。眾僧行間兩邊，並須敷長延大席，令不汙五德尼足。若上座見五德來就，即整衣服，長跪，偏袒右肩，合掌；一切僧亦爾，然後說云。", "t": "第八，正對僧眾作自恣的作法：兩位受差的五德尼當中，第一位來到上座面前，把坐具完全展開鋪好，兩膝著地、上身挺直地跪著；第二位五德尼則走到上座之下的次座面前站著。大眾座位的行列之間，兩邊都必須鋪上長長的大席，以免沾污五德尼的雙足。若上座看見五德尼來到跟前，就整理好衣服，兩膝著地、上身挺直地跪著，袒露右肩、合掌，其餘一切尼眾也都照上座這樣做。然後上座這樣說：", "i": "u413", "n": 66, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉一心念！眾僧今日自恣，我比丘尼某甲亦自恣。若見、聞、疑罪，大姉長老哀愍故語我；我若見罪，當如法懺悔。", "t": "大姊請一心憶念：大眾僧今天舉行自恣，我比丘尼某甲也一同自恣。如果您見到、聽到或懷疑我犯了罪過，請大姊長老出於哀愍而告訴我；我若見到自己確實有罪，必定如法懺悔。", "i": "u414", "n": 67, "s": "第18篇　自恣"}, {"v": "卷中", "o": "上座說已，復本而坐。此初五德尼翻至第三上座前立，彼第二五德尼受懺同前，如是展轉，乃至下座。律開病尼隨身所安自恣。《僧祇》云：二五德各至本座坐處，自相向出罪，不得待僧竟。《十誦》云：眾僧說已，五德至上座前，告云：「僧一心自恣竟！」然後禮敬而退。", "t": "上座說完之後，回到原來的座位坐下。這時第一位五德尼轉往第三位上座前站立；那位第二位五德尼則接受次座者的自恣陳罪，作法與前面相同。就這樣依次輪替，一直到最下座為止。《四分律》開許生病的比丘尼，隨順自己身體所安適的姿勢自恣。《僧祇律》說：兩位五德尼各自回到自己本座的位置，彼此面對面，互相作自恣出罪，不可以等到大眾都自恣完畢了才作自己的自恣。《十誦律》說：大眾都說完之後，五德尼到上座前稟告說：「僧眾已一心自恣完畢。」然後禮拜致敬而退下。", "i": "u415", "n": 68, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第九、略說者。此律，若有八難、餘緣，同前說戒中，並許略自恣，令五德作白云。", "t": "第九，略說自恣法：依《四分律》，若遇到與前面說戒一節所列相同的八種危難及其餘緣故，都開許以簡略的方式作自恣，應令五德尼作白說：", "i": "u416", "n": 69, "s": "第18篇　自恣"}, {"v": "卷中", "o": "大姉僧聽！若僧時到，僧忍聽，今為難故，僧各各三語自恣。白如是。", "t": "各位大姊，僧眾請聽！如果僧眾認為時機已到，請僧眾認可聽許：現在因為有危難的緣故，僧眾每人各自說三遍自恣詞來作自恣。以上便是宣告。", "i": "u417", "n": 70, "s": "第18篇　自恣"}, {"v": "卷中", "o": "作白已，眾僧一時相向，各三說已便散。今時尼眾，或有小語自恣，或五德尼各一時受他自恣，此並非法，故律云：「不得竊語自恣、閙亂自恣。」令一一次第從上座自恣，大語分明，使僧盡聞。上明六人已上法。若限五人，其法稍別：以男內總有五尼，則不合說欲，先問病，總集一處，白羯磨差一五德竟，又差一人，不得雙牒二人，以所為兩人不入僧數故；假令六人已上作法，無其難事，亦不得雙牒二人一時作羯磨。至自恣時，一五德同僧坐，一五德展轉取自恣；若事總了，二五德尼自相向說，餘法同前。若界內唯有四尼已下，止得對首自恣，不合眾法。對首云。", "t": "作白之後，大眾同時互相面對面，各自三說完畢，便解散。現今的尼眾中，有的低聲小語地自恣，或五德尼各自同時接受他人的自恣，這些都不如法。所以律中規定：不得竊竊私語地自恣，不得吵鬧雜亂地自恣；要一個一個依次從上座開始自恣，大聲說得清楚分明，使全僧眾都聽得到。\n以上說明的是六人以上的作法。若只有五位尼，作法稍有不同。因為界內總共只有五位尼，就不可以說欲。先問明病尼的情況，把大眾全部集合在一處，作白羯磨差派一位五德尼之後，再差派另一人；不可在一次羯磨中同時牒名差派兩人，因為這兩位作為羯磨所為對象的人不計入僧數。假使六人以上作法，沒有上述人數不足的困難，也不可以在一次羯磨中同時牒名差派兩人。\n到自恣時，一位五德尼與僧眾同坐，另一位五德尼則展轉依次接受眾人的自恣。等到全部完畢，兩位五德尼再互相面對面陳說自恣。其餘作法與前面相同。若界內只有四位尼以下，只能作對首自恣，不合用僧法自恣。對首時這樣說：", "i": "u418", "n": 71, "s": "第18篇　自恣"}, {"v": "卷中", "o": "諸大姉一心念！今日眾僧自恣，我比丘尼某甲清淨。", "t": "諸位大姊請專心憶念：今天僧眾舉行自恣，我比丘尼某甲是清淨的。", "i": "u419", "n": 72, "s": "第18篇　自恣"}, {"v": "卷中", "o": "餘下三人，互說如前。若二人相對，云「大姉一心念」，不須云「諸大姉」等。若依《十誦》，饑儉從親里獨住尼，心念云。", "t": "其餘三人也如前一樣互相對說。若是二人相對自恣，就說「大姊請一心專念」，不必說「諸位大姊」這類表示多數的稱呼。如果依《十誦律》，饑荒歉收時投靠親屬而獨自居住的尼，就以心念法自恣，念道：", "i": "u420", "n": 73, "s": "第18篇　自恣"}, {"v": "卷中", "o": "今日眾僧自恣，我比丘尼某甲清淨。", "t": "「今天僧眾舉行自恣，我比丘尼某甲清淨。」", "i": "u421", "n": 74, "s": "第18篇　自恣"}, {"v": "卷中", "o": "第十、雜法者。問：所以對僧云「見罪」、對首云「清淨」者？答：對僧治舉義足，故云「見罪」得懺；別人攝治不盡，故云「清淨」，舉心應僧。若僧及別人自恣已，更有客來，少則告清淨等，多更為說；若二人作法已，更有三人來，應作僧法自恣；若二尼來，還同對首。若四人已下，犯提乃至吉羅，並須懺己自恣；若犯初二篇，屏對一尼發露已自恣。《僧祇》云：「不得此界安居，餘處自恣。」此律：前安居人自恣竟，分夏衣，後安居人得同受物，仍待日滿得還。安居竟不去，犯罪。", "t": "第十、雜法。\n問：為什麼對僧眾自恣時說「見罪」，對首自恣時卻只說「清淨」呢？\n答：對著僧眾，治罰、舉罪的意義具足，所以說「見罪」，得以如法懺悔；對著個別的人自恣，攝受治罰的作用不夠周全，所以只說「清淨」，但內心舉罪發露之意，仍與對僧自恣時相同。\n不論是僧眾自恣或對首自恣，作完之後又有客尼前來：來的人數少，就只告說清淨等即可；人數多，就要重新作自恣。若原本二人已作法完畢，又來了三人，共成五人，就應改作僧法自恣；若只來二尼，連前共成四人，仍舊同於對首法。\n四人以下，若犯波逸提乃至突吉羅，都必須先懺悔完畢，然後才自恣；若犯的是波羅夷、僧殘這前二篇重罪，就在屏處對一位比丘尼發露之後，再自恣。\n《僧祇律》說：不得在此界安居，卻到別處自恣。\n此律（《四分律》）說：前安居的人自恣完畢、分配夏安居所得的衣物時，後安居的人也可以一同受取衣物，但仍須等到自己安居日數圓滿，才可以回去。安居結束卻不離去，就犯罪。", "i": "u422", "n": 75, "s": "第18篇　自恣"}, {"v": "卷中", "o": "○師徒篇第十九", "t": "第十九篇：師徒。", "i": "u423", "n": 76, "s": "第19篇　師徒"}, {"v": "卷中", "o": "此篇大門一十有三：一、師徒名，二、依止意，三、免依止，四、合依止，五、通行法，六、白事法，七、請經法，八、報恩法，九、無師法，十、簡師德，十一、請師法，十二、師攝法，十三、訶懺法。", "t": "本篇大分為十三門：第一是師徒的名義，第二是依止的用意，第三是得免依止，第四是應當依止，第五是通用的行法，第六是稟白事情之法，第七是請師傳授經法之法，第八是報答師恩之法，第九是無師時的作法，第十是揀擇師父的德行，第十一是請人為師之法，第十二是師父攝受弟子之法，第十三是訶責與懺悔之法。", "i": "u424", "n": 77, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第一、師徒名者。問：何名為師、和尚、闍梨者？答：《見論》云：「無罪見罪訶責，是名我師；共於善法中教授令知，是我闍棃。」義云：和尚，此云知有罪、知無罪，是名和尚，故此律云：「我犯、不犯，師不知也。」又，義云：「和尚」者，為力生；「闍棃」者，為正行；「弟子」者，學在我後為弟，解從我生為子。", "t": "第一門，解釋「師」與「徒」的名稱。\n問：什麼樣的人叫做「師」？什麼樣的人叫做「和尚」、「闍梨」？\n答：《善見論》說：「無罪見罪，訶責，是名我師。」意思是：自己看不出有罪，他卻能見出罪來而加以訶責，這樣的人就叫做我的「師」。論中又說：「共於善法中教授令知，是我闍梨。」意思是：他與我一同在善法之中，教授教導而使我明白知解，這樣的人就是我的「闍梨」。\n依義理而解說：「和尚」，漢語譯為「知有罪、知無罪」，能明了什麼是有罪、什麼是無罪，這才叫做和尚。所以《四分律》中，弟子訶責和尚說：「我犯不犯，師不知也。」——我犯了戒還是沒有犯，師父竟然都不知道。這是從反面責難：師父若不知弟子犯與不犯，便不成其為和尚。\n又有一種義解說：「和尚」是「力生」的意思，弟子的道力由他而生；「闍梨」是「正行」的意思，能糾正弟子的行為。至於「弟子」，是就師而言：修學在我之後，所以稱為「弟」；知解從我而生，所以稱為「子」。", "i": "u425", "n": 78, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第二、依止意者。《尸迦羅越六方禮經》：弟子事師，當具五意：一、當敬難之，二、當念其恩，三、所有言教隨之，四、報恩不厭，五、從後稱譽。師教弟子亦有五意：一、當令疾知，二、令勝他人弟子，三、令知不忘，四、有諸疑難悉為開解，五、欲令弟子智慧勝師。《正法念經》云：「若畏師持戒，名下持戒。」《僧祇》：師度弟子者，不得為供給自己故度人出家，得罪；當使彼人因我度故，修諸善法，得成道果。《佛藏經》云：五夏已前，於人受學律藏；五夏已後，具知應學無我人法。《見論》云：「云何學律？謂讀誦、解義也。」此律云：「和尚畜弟子，當如兒想；弟子看和尚，當如父想。」義云：如兒想看者，須具四意：一、匠成訓誨，二、慈念，三、矜愛，四、攝受以衣食。如父看者，還具四心：一、親愛，二、敬順，三、畏難，四、尊重敬養，如臣子之事君父也。故律云：「如是展轉相敬、相重、瞻待，令正法便得久住增益。", "t": "第二，依止的用意。《尸迦羅越六方禮經》說：弟子事奉師父，應當具備五種心意：一、應當恭敬而心存敬畏；二、應當憶念師父的恩德；三、師父所有的言語教誡，都隨順遵行；四、報答師恩而不厭倦；五、在師父背後稱揚讚譽他。師父教導弟子，也有五種心意：一、要使弟子迅速明白所學；二、要使弟子勝過別人的弟子；三、要使弟子所學的都能記住不忘；四、弟子有種種疑難，全都為他開解釋疑；五、希望弟子的智慧超過師父。\n《正法念處經》說：若只是因為畏懼師父而持戒，這叫做下品持戒。\n《僧祇律》說：身為師父而度弟子的人，不得為了供給自己所需而度人出家，這樣做是有罪的；應當使那個人因為我度他出家的緣故，修習種種善法，得以成就道果。\n《佛藏經》說：五夏、即五個安居年以前，要依人受學律藏；五夏以後，既已具足通達律藏，就應當進一步修學無我、無人之法。《善見論》說：怎樣叫做學律呢？就是讀誦律文、理解其中的義理。\n《四分律》說：和尚收畜弟子，應當把弟子當作兒子想；弟子看待和尚，應當把和尚當作父親想。就義理而言：把弟子當兒子看待，須具備四種心意：一是雕琢造就、教訓誨導；二是慈心繫念；三是憐惜愛護；四是以衣食攝受供給。把和尚當父親看待，也同樣具備四種心：一是親近愛敬；二是恭敬順從；三是敬畏而不敢輕慢；四是尊重恭敬供養，就像臣子事奉君主、兒子事奉父親一樣。所以《四分律》說：如此師徒彼此互相恭敬、互相尊重、互相照顧看待，就能使正法久住世間而增益廣大。", "i": "u426", "n": 79, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第三、得免依止。總有八人，此律有六，餘部有二。此律：一、樂靜，二、守護住處，三、病，四、看病，五、滿六夏已上，六、自有智行，住處更無勝己。七、饑儉無食處，《十誦》云：「若恐飢餓死者，當在日日見和尚處住；恐不爾者，若十五日，若一月，若二由旬半，若至自恣時來見和尚八、行道稱意處，《五分》云：「諸比丘各勤行道，無人與作依止，當於眾中上座大德心生依止，敬如師住。", "t": "第三，可以免除依止的，總共有八種人：《四分律》明六種，其餘部派的律另有二種。\n本律的六種是：一、喜愛寂靜獨處修行的人；二、守護住處的人；三、自己有病的人；四、看護病人的人；五、戒臘已滿六夏以上的人；六、自己有智慧德行，而所住的處所再沒有勝過自己的人。\n第七，是饑荒歉收、沒有食物的住處。《十誦律》說：如果擔心會餓死，就應當住在每天都能見到和尚的地方；若擔心無法如此，那就或隔十五日、或隔一個月、或相隔兩個半由旬、或到自恣的時候，前來拜見和尚。\n第八，是行道稱心如意的住處。《五分律》說：比丘們各自精勤修道，沒有人可以為他們作依止師，這時應當對僧眾中的上座大德，在心裡生起依止之心，恭敬他如同自己的師父一般而住。", "i": "u427", "n": 80, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第四、合依止。總有十人。此律云：一、和尚命終，二、知休道，三、和尚決意出界，四、和尚捨畜眾，五、弟子緣離他方，六、弟子不樂住處、更求勝緣，七、未滿六夏。八、不諳教網，故律云：「若愚癡無智慧，盡形依止他。」《十誦》云：「雖受戒多歲，不知五法者，盡形依止他：一、不知犯，二、不知不犯，三、不知輕，四、不知重，五、不廣誦戒通利。」《母論》云：「百臘不知法者，應從十臘知法者依止。」《僧祇》有四：「不善知法，不善知毗尼，不能自立，不能立他，盡形依止。」九、或愚或智，愚謂性戾癡慢，數犯眾罪；智謂犯已即知，依法懺洗，志非貞正，依止於他。十、不誦戒本，《母論》云：「不誦戒人，若故不誦，若先誦後忘，若鈍根誦不能得，此三種人不得離依止。」《十誦》云：「不誦戒有四過：一、不得畜弟子，二、不得離依止，三、不得作和尚，四、不得作阿闍棃。", "t": "第四，應當依止師長的，總共有十種人。《四分律》說：一、和尚命終；二、得知和尚已罷道還俗；三、和尚決意離開本界他往；四、和尚捨棄攝畜徒眾；五、弟子因事緣離開，前往他方；六、弟子不喜歡所住之處，另求更殊勝的因緣；七、戒臘未滿六夏；八、不通曉教法綱網。所以律中說：若是愚癡而沒有智慧的人，就要終身依止他人。《十誦律》說：雖然受戒已經多年，若不知五法的，仍須終身依止他人：一、不知道什麼是犯戒；二、不知道什麼是不犯戒；三、不知道罪輕；四、不知道罪重；五、不能廣誦戒本而通達流利。《毗尼母論》說：即使已有一百戒臘卻不知法的人，也應向只有十戒臘而知法的人求依止。《摩訶僧祇律》說有四種：不善了知法、不善了知毗尼、不能自己安立於法而獨立如法修行、也不能安立他人而教導成就，這樣的人須終身依止他人。第九、或是愚癡、或是有智的人：愚癡，是指性情乖戾、愚癡憍慢，屢屢犯下眾多罪過；有智，是指犯了以後隨即知道，依法懺悔洗除；這兩種人志向都不堅貞端正，所以仍須依止他人。第十、不誦戒本的人。《毗尼母論》說：不誦戒的人，或是故意不誦，或是先前誦過後來忘失，或是根性鈍劣、想誦也誦不來，這三種人都不得離開依止。《十誦律》說：不誦戒有四種過失：一、不得畜養弟子；二、不得離開依止；三、不得作和尚；四、不得作阿闍梨。", "i": "u428", "n": 81, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第五、通行法者。此律，師及弟子有七種通行法：一、眾僧與師作治罰，弟子相料理，令和尚順從於僧；設作，令如法，不違逆；求除罪，令僧疾與解罪。二、若和尚犯僧殘，弟子當如法勸化，令其發露，為集僧作覆藏、六夜、出罪等。三、和尚得病，弟子當瞻視，若令餘人看，乃至差若命終。四、和尚不樂住處，弟子當自移。五、和尚有疑，弟子當以法、以律教除。六、和尚若惡見，弟子教令捨惡見、住善見。七、弟子當以二事將護，謂法及衣食。《僧祇》云：和尚、闍棃有非法事，弟子不得麤語如教誡法，應輭語諫師云：「應作是，不應作是。」若和尚不受語者，弟子應捨遠去；若是依止師者，當持衣鉢出界一宿，當還。《五分》云：若師犯僧殘，求僧乞羯磨，弟子應掃灑敷座、集僧、求羯磨師等。", "t": "第五是通行法。《四分律》中說，師長與弟子之間有七種彼此共同應行的法：\n一、僧眾對師父作治罰羯磨時，弟子應當從中協助料理，使和尚順從僧眾；僧眾若仍作了治罰，就要使僧眾的作法如法，使和尚不違逆抗拒，並替他求請除罪，使僧眾趕快為他解除罪罰。\n二、如果和尚犯了僧殘罪，弟子應當如法勸導教化，使他發露罪過，並替他召集僧眾，辦理覆藏、六夜、出罪等羯磨。\n三、和尚生病時，弟子應當親自看護照料，或請別人代為看護，直到病癒，或直到命終為止。\n四、和尚不喜歡這個住處時，弟子應當自己移離，遷往他處。\n五、和尚有疑惑時，弟子應當依法依律教導，替他解除疑惑。\n六、和尚若生起惡見，弟子應勸導他捨棄惡見，安住在善見上。\n七、弟子應當用兩件事扶持照護師父，就是法與衣食。\n《僧祇律》說：和尚、阿闍梨有不如法的事，弟子不可以粗言厲語，像師長教誡弟子那樣說話，應當用柔和的言語勸諫師父說：「這個應該做，那個不應該做。」如果和尚不接受勸諫，弟子就應當捨離他而遠去。若是不接受勸諫的是依止阿闍梨，弟子就應當持著衣缽走出界外過一夜，然後再回來。\n《五分律》說：如果師父犯了僧殘罪，要向僧眾乞求羯磨，弟子應當為他打掃灑水、鋪設座位、召集僧眾、訪求羯磨師等。", "i": "u429", "n": 82, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第六、白事法者。此律云：凡有所作，並須白師令知。白時，具修威儀，長跪合掌云：「尊憶念！弟子某，為某因緣故，須到某處，同伴某甲，白尊令知。」師應量宜，謂同伴如、去處如、營事如，方始聽去；若一事乖違，便不合放。而同伴之人，必須明解律教，持戒灼然，老少相兼，堪始聽去。《五分》云：欲行，預前二三日白師令知；唯除大小便、用楊枝不白。《十誦》云：一切所作事，皆須白師；唯除禮佛法僧、大小便、嚼楊枝三種不白。《僧祇》云：不白師得取與半條線、半食等，若約一條線而不白，得罪；若不能一一白師者，當通白亦得。《見論》：弟子從師行，不得遠師七步。《沙彌威儀》云：弟子隨師行，不得以足蹈師影。復有五事：一、不過歷人家，二、不得止住道與人語，三、不得左右顧視，四、當低頭隨師後，五、到檀越家，當住一面，師教坐應坐。", "t": "第六、稟白事項之法。《四分律》說：凡有所作，都必須稟白師父，讓師父知道。稟白時要具足威儀，長跪合掌，這樣說：「請尊者垂念：弟子某，為了某事的緣故，必須前往某處，同行的人是某甲，特此稟白尊者，讓您知道。」師父應當斟酌是否適宜：同伴如法、去處如法、所要辦的事如法，三者都妥當，才准他去；只要其中一項有違，就不該放行。而同行的人必須明白通解律藏教法，持戒清楚確實，並且老少相互搭配，這樣才算合格，才准前往。\n《五分律》說：想要出行，要提前兩三天稟白師父，讓師父知道；唯有大小便和使用楊枝不必稟白。\n《十誦律》說：一切所作的事都必須稟白師父，唯有禮敬佛、法、僧，大小便，嚼楊枝這三種不必稟白。\n《僧祇律》說：不稟白師父，也可以取用或給人半條線、半份食物之類的東西；若達到一整條線而不稟白，就得罪。若不能一件一件稟白師父，作一次總括的稟白也可以。\n《善見論》說：弟子跟隨師父行走，不得離師父超過七步。\n《沙彌威儀》說：弟子跟隨師父行走，不得用腳踩師父的影子。又有五件事：一、不得挨家挨戶地走動閒逛；二、不得停在路上與人說話；三、不得左顧右盼；四、應當低著頭跟在師父後面；五、到了施主家，應當站在一旁，師父叫坐才坐。", "i": "u430", "n": 83, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第七、請經法者。此律云：彼清旦入和尚房中，受經問義。《沙彌經》云：若入師房，應三彈指。《見論》云：弟子參師應避六處：一、不得當前，二、不得當後，三、不得太遠，四、不得太逼，五、不得處高，六、不得上風立。", "t": "第七，請受經文之法。本律說：弟子應當在清晨進入和尚的房中，從和尚受誦經文、請問經中的義理。《沙彌經》說：若要進入師父房中，應先彈指三下。《善見論》說：弟子參見請問師父時，應避開六種位置：一、不可正站在師父的正前方；二、不可正站在師父的正後方；三、不可離得太遠；四、不可靠得太近；五、不可站在比師父高的地方；六、不可站在上風處。", "i": "u431", "n": 84, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第八、報恩者。此律云：清旦入和尚房內，除大小便器，白「時到」等；又日三時——朝、中、暮問訊和尚；又執作二事，勞苦不得辭託：一、修理房舍，二、為補浣衣服。師如法教事，盡當奉行；若遣往餘方，不得假託內緣而住。", "t": "第八是報恩。《四分律》說：清晨進入和尚房內，清理倒除大小便器，稟白「時候已到」等事。又每天三個時段——早晨、中午、傍晚——向和尚問訊請安。又要為和尚操辦兩件事，縱然勞累辛苦也不得推辭託故：一是修理房舍，二是縫補、洗滌衣服。和尚如法所教導的事，全都應當奉行。若和尚派遣前往其他地方，不得假託寺內事務或自身私事緣由而留住不去。", "i": "u432", "n": 85, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《僧祗》云：弟子應晨起，先右脚入和尚房已，頭面禮足，問安眠否。雖百歲比丘無智慧者，應依止十臘比丘，如弟子事師無異。《十誦》云：除禮足，餘盡應依師教。", "t": "《僧祇律》說：弟子應當早晨起床後，先邁右腳進入和尚房中，進房後頭面禮足，請問和尚是否安眠。即使是受戒百臘的比丘，若沒有智慧，也應當依止十臘的比丘，如同弟子奉事師父一樣，沒有差別。《十誦律》說：除了禮拜師足這一項之外，其餘一切都應依師父的教導去做。", "i": "u432-2", "n": 86, "s": "第19篇　師徒"}, {"v": "卷中", "o": "經云：一日三時，應參師和尚；若參師不見時，應持土塊、草木以為記驗；天時若熱，日別三時，以扇扇師。", "t": "經中說：一天三個時段應當參見師父和尚。若去參見時沒見到師父，應當拿土塊、草木留下，作為曾來參見的記號憑證。天氣炎熱時，每天三個時段用扇子為師父搧涼。", "i": "u432-3", "n": 87, "s": "第19篇　師徒"}, {"v": "卷中", "o": "若有比丘，於彼師所或和尚邊不敬信心，遂說長短，於將來世別有一小獄，名為搥撲，當墮是中；墮彼處已，一身四頭俱焦；於彼獄處復有諸蟲，名曰銅𭉨，常噉舌根。若從他聞一四句偈，各於千劫，取彼和尚、阿闍棃等荷擔肩上，或時背負頂戴，亦未能報也。", "t": "若有比丘在自己的師父或和尚那裡，沒有恭敬信心，反而議論他們的長短過失，來世另有一個小地獄名叫「搥撲」，他將墮入其中。墮到那裡之後，一個身體四個頭，全都被燒得焦爛；那地獄中又有名叫「銅𭉨」的各種蟲，常常啃食他的舌根。若從他人聽聞一首四句偈，即使各各經過一千劫，把那位和尚、阿闍梨等扛在肩上，或有時用背馱負、用頭頂戴，也仍不能報答其恩。", "i": "u432-4", "n": 88, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《地獄經》云：為人弟子說師僧過者，設師有實，命終入地獄，噉其舌根；若得好食、美果等，不與父母、師僧，先自食噉，生餓鬼中，後生為人貧窮；若人含毒向師長，入鐵鉞地獄，後生毒蛇中；若惡心學父母、師長語，入融銅地獄，後生為人謇吃。", "t": "《地獄經》說：作人家的弟子而宣說師父、僧眾過失的，即使師父確實有那些過失，命終之後也墮入地獄，舌根被啃食。若得到好食物、美味水果等，不給父母師僧而自己先吃，就生到餓鬼中，之後生為人時貧窮。若有人心懷毒害對向師長，就墮入鐵鉞地獄，之後生為毒蛇。若以惡心模仿父母師長的言語，就墮入融銅地獄，之後生為人時口吃。", "i": "u432-5", "n": 89, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《僧祇》云：有人問「汝和尚、阿闍棃字何等？」不得直道和尚、阿闍棃字，應告言：「義因緣故字某甲。」", "t": "《僧祇律》說：有人問「你的和尚、阿闍梨名叫什麼」時，不得直接說出和尚、阿闍梨的名字，應當回答說：「因有事由緣故，名叫某甲。」", "i": "u432-6", "n": 90, "s": "第19篇　師徒"}, {"v": "卷中", "o": "此律：若弟子見和尚四種非法，應懺謝而去，白和尚云：「一、我如法，和尚不知；二、我不如法，和尚亦不知；三、我犯戒，和尚捨不教訶；四、犯而懺者亦不知。", "t": "《四分律》說：若弟子見到和尚有四種非法，應當向和尚謝過辭別而離去，稟白和尚說：一、我如法而行，和尚卻不知道；二、我不如法而行，和尚也不知道；三、我犯了戒，和尚捨置而不教導訶責；四、我犯戒後懺悔，和尚也不知道。", "i": "u432-7", "n": 91, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第九、無師住時節者。此律開先洗足、飲水已，然後依止。《伽論》云：初至他處，不相諳委，二三日選擇師。《十誦》云：無好師者，聽五六夜；有好師者，乃至一夜不依止者，得罪。", "t": "第九、沒有依止師時可住的期限：《四分律》開許先洗腳、飲水完畢，然後才受依止。《摩得勒伽論》說：初到別的地方，對當地的人還不熟悉，可以用兩三天來選擇師父。《十誦律》說：沒有好師父時，聽許五、六夜不受依止；若有好師父，即使一夜不受依止，也得罪。", "i": "u433", "n": 92, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第十、簡師德者。此律，阿闍棃有五種：一、出家阿闍棃，謂依教受十戒者是；二、受戒阿闍棃，謂為受具足秉羯磨者是；三、教授阿闍棃，謂教授威儀者是；四、受經阿闍棃，謂所從受經者是；五、依止阿闍棃，謂受依止者是。義云：前四通名阿闍棃，今此所明，準論依止闍棃，以替和尚處故，必須諳究經律，圓解明白，方始得為。《僧祗》云：不得輒請依止，須成就五法：一、受念，二、恭敬，三、慚，四、愧，五、樂住。《伽論》云：凡欲依止人者，當好量宜能長善法者，及問餘人云：「此比丘尼戒德何似？能教誡否？眷屬復何似？無有諍訟否？」若都無者，然後依止。此律明二師德者有三：一、簡少取老，十二夏已上為和尚，至六夏已上為闍棃；二、夏數雖滿，必須智慧；三、雖具上二德，然要勤教詔弟子。闍棃亦七種共行法，如前和尚中說。", "t": "第十，揀擇師長的德行。本律說：阿闍棃有五種：一、出家阿闍棃，就是依從他的教導而受十戒的那位師父。二、受戒阿闍棃，就是為受具足戒的人秉羯磨作法的那位師父。三、教授阿闍棃，就是教授威儀的那位師父。四、受經阿闍棃，就是從他受學經法的那位師父。五、依止阿闍棃，就是接受弟子依止的那位師父。\n就義理上說：前四種只是通稱為阿闍棃；這裡所要說明的，依論典所說，是指依止闍棃。因為依止闍棃是替代和尚的位置，所以必須熟諳深究經律，理解圓滿透徹、明白無滯，才可以擔任。\n《僧祇》說：不可隨便請人作依止師，求依止者必須成就五法：一、受念〔疑作「愛念」〕，二、恭敬，三、慚，四、愧，五、樂住。\n《伽論》說：凡是想要依止他人的，應當好好衡量斟酌，選取能增長善法的人；並且要請問其他人：「這位比丘尼的戒德如何？能不能教誡弟子？她的徒眾又怎樣？有沒有諍訟？」如果這些缺失都沒有，然後才依止她。\n本律說明和尚、闍棃二師的德行，有三項：一、揀去戒臘淺者、取戒臘深者：戒臘滿十二夏以上的，才能作和尚；下至滿六夏以上的，可作闍棃。二、夏數雖然滿了，還必須具有智慧。三、雖然具足上面兩種德行，仍必須勤於教導、告誡弟子。闍棃也同樣有七種共行法，如前面和尚那一節所說。", "i": "u434", "n": 93, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第十一、請師法者。此律，由和尚命終，無人教授，故多壞威儀，佛令聽有依止闍棃，相依教訓，如和尚法，展轉相依，令佛法倍增益流布。請時具修威儀，至彼師所云。", "t": "第十一、請求依止師的方法：《四分律》說，由於和尚去世之後沒有人教導，弟子們大多敗壞了威儀，佛陀因此開許可以有依止阿闍梨，師徒彼此依靠、教導訓誨，一切都如同和尚與弟子之間的規制；這樣展轉相依，能使佛法加倍增長、流布開來。請求依止時，應具足整肅威儀，到那位師父的處所，說道：", "i": "u435", "n": 94, "s": "第19篇　師徒"}, {"v": "卷中", "o": "大姉一心念！我比丘尼某甲，今求大姉為依止阿闍棃，願大姉為我作依止阿闍棃，我依大姉故，得如法住。", "t": "請大姊專心聽我陳說：我比丘尼某甲，現在請求大姊作我的依止阿闍梨。祈願大姊為我擔任依止阿闍梨，我由於依止大姊的緣故，得以如法安住。", "i": "u436", "n": 95, "s": "第19篇　師徒"}, {"v": "卷中", "o": "彼師告云：「可爾，與汝依止，莫放逸。」《五分》云：若師不答許可者，不成依止法。", "t": "那位師父回答她說：「可以，我給你作依止，切莫放逸。」《五分律》說：如果師父沒有出言應允，依止法就不成立。", "i": "u437", "n": 96, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第十二、攝受法者。《僧祇》云：日別三時教三藏教法，不得廣者，下至略知戒經輕重、陰界入義，若受經時、共誦時、坐禪時，即名教授；若不爾者，下至云「莫放逸」。", "t": "第十二，攝受弟子的法則。《僧祇律》說：師父每天早、中、晚三個時段都要教導三藏教法；如果不能廣泛教授，至少也要讓弟子略知戒經中諸罪的輕重，以及五陰、十八界、十二入的義理。在弟子受經時、師生共同誦讀時、坐禪時加以教導，這就叫作教授；如果連這些也做不到，至少也要對弟子說一句「莫放逸」。", "i": "u438", "n": 97, "s": "第19篇　師徒"}, {"v": "卷中", "o": "義云：若請師，須具四意：一、作請，彼攝我、我當依彼慈念憐愍意；二、請取道法資神，令教授行成智立意；三、自申己意，我能依止、愛念恭敬如父母想意；四、彰己能依止而行，謂慚愧二心也。具此四法，方無過咎；若不爾者，徒自悠悠，終無成辦。", "t": "就義理而言：若要請師，必須具備四種心意：第一，作出請求：願師父攝受我、我當依止師父，願師父慈念憐愍我；第二，求取道法以資益心神，希望經由教授而修行成就、智慧建立；第三，自己申明我能依止，愛念恭敬、如對父母一般；第四，表明自己能依止而修行，也就是慚、愧二心。具備這四法，才沒有過失；不然的話，只是徒然悠悠度日，終究一無所成。", "i": "u438-2", "n": 98, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《五分》：受戒已，師應六年自攝，若教他攝，違者犯提；弟子亦應六年依承和尚。此律：受戒已，不得離和尚。", "t": "《五分律》說：受具足戒後，師父應當在六年內親自攝受弟子，或囑託他人代為攝受；若不這樣做，違反者犯波逸提罪。弟子也應當在六年內依止承事和尚。《四分律》說：受具足戒後，不得離開和尚。", "i": "u438-3", "n": 99, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《見論》云：和尚多有弟子，留一人供給，餘者隨意令讀誦。《僧祇》云：弟子為王難，師必經理；若賊抄掠等，覓錢救贖，否者犯罪。", "t": "《見論》說：和尚若有很多弟子，留一人在身邊供給侍奉，其餘的則讓他們隨意去讀誦經法。《僧祇律》說：弟子若遭王法之難，師父必須為他料理營救；若弟子被盜賊劫掠擄走等，要籌錢把他贖回，不這樣做，師父就犯罪。", "i": "u438-4", "n": 100, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《十誦》云：和尚有四種法，弟子應量宜：一、與法不與食，應住；二、與食不與法，不應住；三、法食俱與，應住；四、若法食俱不與者，不須問師，若晝若夜應捨去。闍梨亦然。《僧祇》云：苦住、樂住四句同前。《五百問事》云：其師無非法，而誘將他沙彌去，犯重。", "t": "《十誦律》說：和尚對弟子有四種情形，弟子應當衡量斟酌：一、教授佛法而不供給飲食，應當住下；二、供給飲食而不教授佛法，不應住下；三、佛法與飲食都供給，應當住下；四、佛法與飲食都不供給，不必向師父告辭，無論白天黑夜都應當捨離而去。對阿闍梨也是這樣。《僧祇律》所說苦住、樂住的四句，也與前面相同。《五百問事》說：那位師父並沒有非法之事，卻有人誘拐把他的沙彌帶走，這誘拐的人犯重罪。", "i": "u438-5", "n": 101, "s": "第19篇　師徒"}, {"v": "卷中", "o": "第十三、訶懺法者。凡弟子有過，必須以理訶責；訶責之法，事須出過，令彼伏首，依罪懺悔。此律云：師不出過，輒爾訶責，弟子云：「我何過訶責我？」《僧祗》：若師訶責，弟子不受者，當語知事斷食；若前兇惡者，師自遠去一宿，更還得住，無過。", "t": "第十三，訶責與懺悔之法。凡是弟子有了過失，師父必須依道理加以訶責。訶責的方法，一定要指出他的過失，使他心服低頭，依所犯的罪如法懺悔。本《四分律》說：師父不指出過失就任意訶責，弟子會說：「我犯了什麼過失，你要訶責我？」《僧祇律》說：如果師父訶責弟子而弟子不接受，就應當告知知事人，斷絕他的飲食；如果對方兇惡蠻橫，師父就自己遠離到別處過一夜，之後再回來住，沒有過失。", "i": "u439", "n": 102, "s": "第19篇　師徒"}, {"v": "卷中", "o": "《善戒經》云：師不驅謫弟子，重於屠兒、旃陀羅等，屠兒不壞正法，不定墮三惡道中，若畜惡弟子，必生惡道；又為名聞利養故畜徒眾，是邪見人，名魔弟子。《五百問事》云：有師不教弟子，弟子破戒故，便墮龍中，後因相遇，返來害師。", "t": "《善戒經》說：師父不驅逐、責罰弟子，罪過比屠夫、旃陀羅等人還重。屠夫不破壞正法，不一定墮入三惡道中；若是畜養惡弟子，就必定生於惡道。又，為了名聲利養而畜養徒眾的人，是邪見人，叫做魔的弟子。《五百問事經》說：有位師父不教導弟子，弟子因為破戒的緣故墮在龍中；後來彼此相遇，那弟子反而回來傷害師父。", "i": "u439-2", "n": 103, "s": "第19篇　師徒"}, {"v": "卷中", "o": "義云：若訶責弟子，先自量喜怒，次量前過輕重，外現威肅，內懷悲愍，苦言切勒，令息後犯。", "t": "依義理說：若要訶責弟子，先衡量自己是否夾雜著喜怒情緒，其次衡量對方過失的輕重；外表顯現威嚴肅穆，內心懷著悲憫，用嚴切的話語懇切地告誡約束，使他止息日後的再犯。", "i": "u439-3", "n": 104, "s": "第19篇　師徒"}, {"v": "卷中", "o": "又經中無有杖打弟子之法，數見僧尼每加杖捶，痛徹前人，於是遂引《涅槃》三子之喻，此未達教意：然彼並是住一子地，悲心無差別，得行此法罰；今時杖栲眾生，皆瞋怒猛熾，放暢心懷，加痛前人，豈同大悲一子之念？《地持論》云：上過罰黜，中犯折伏，下犯訶責，亦無杖打之法。", "t": "又，經中並沒有杖打弟子的作法。屢次見到僧尼動輒加以杖打，打得對方痛徹全身，於是便援引《涅槃經》中「三子」的譬喻，這是不通達聖教的本意。然而經中那些人都是安住於「一子地」，視一切眾生如同獨子、悲心平等沒有差別的，才能施行這樣的治罰。現今杖打拷治眾生的人，都是瞋怒猛烈熾盛，放縱暢快自己的心懷，把痛苦加在對方身上，哪裡等同於大悲視眾生如一子的心念呢？《地持論》說：上品過失就處罰黜退，中品過失就折伏，下品過失就訶責，也沒有杖打的作法。", "i": "u439-4", "n": 105, "s": "第19篇　師徒"}, {"v": "卷中", "o": "此律：或盡形責弟子，或夏初犯過，罷夏瞋猶不息，或不現前訶責，或設訶而受供給，此並非法，得罪。", "t": "本律中說：或者終身訶責弟子；或者弟子在夏安居之初犯了過失，直到安居結束，師父的瞋怒還不停息；或者不當面訶責；或者雖然訶責了，卻仍接受弟子的供給服侍——這些都是非法，都要得罪。", "i": "u439-5", "n": 106, "s": "第19篇　師徒"}, {"v": "卷中", "o": "此律云：師訶弟子，命餘比丘尼將順，使向和尚、阿闍棃所調伏，令早懺悔；應觀折伏柔和，知時受懺。弟子應至二師所，具修威儀，合掌云：「大姉！我今懺悔，更不復作。」若不聽者，當日三時懺悔；和尚猶不許者，當下意隨順，求解其所犯。若求解其過，和尚、闍梨當受；不受，如法治。", "t": "本律又說：師父訶責弟子後，命其他比丘尼從旁帶領勸導，帶她到和尚尼、阿闍梨尼那裡接受調伏，使她早日懺悔。二師應觀察她已被折伏、心意柔和，知道時機合適才接受她的懺悔。弟子應到二師處，完整具足威儀，合掌說：「大姊！我今懺悔，更不復作。」如果二師不聽許接受，當天就要分三個時段懺悔。和尚尼仍不允許的，就應當謙下心意、隨順師意，請求解除自己所犯的過罪。若弟子這樣請求解除過罪，和尚尼、阿闍梨尼就應當接受；不接受的，依律治罰。", "i": "u439-6", "n": 107, "s": "第19篇　師徒"}, {"v": "卷中", "o": "○致敬篇第二十", "t": "第二十篇：致敬。", "i": "u440", "n": 108, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此篇大門有十：一、敬寺，二、敬佛，三、敬法，四、敬僧，五、定尊，六、致拜，七、八敬，八、報恩，九、醫藥，十、殯終。", "t": "這一篇的大綱分為十門：一是敬寺，二是敬佛，三是敬法，四是敬僧，五是定尊卑，六是禮拜致敬，七是八敬法，八是報恩，九是醫藥，十是殯葬送終。", "i": "u441", "n": 109, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第一、敬寺者。", "t": "第一、敬寺", "i": "uGAP09-1", "n": 110, "s": "第20篇　致敬"}, {"v": "卷中", "o": "每惟佛法陵遲，出家僧尼道心疎略，至於眾行，觸事闕如，故令堂殿朽壞，舍屋崩摧，門牆凋弊，糞穢盈階，路絕人蹤，僧徒漂寄，不修不拭，日就衰隤，造罪造愆，無時暫捨。是以葷辛酒肉，競奉僧房；香華幡蓋，罕供佛宇；六時致拜，早自無心；三業虗譚，彌加蜂蠆；或將人共宿，飲醼同䬸；絲竹管絃，公然聚會。遂令惡人興毀，始擬便摧；颷火纔焚，終將煙滅。故使冥鬼効靈，善神捨衛；伽藍無故，直為尼戒有虧；招世譏嫌，亦由眾無綱紀。", "t": "每每思及佛法衰微，出家僧尼向道之心疏忽淡薄，至於僧眾的種種行事，往往事事缺漏，因而致使佛堂殿宇腐朽損壞，房舍屋宇崩塌摧毀，門戶圍牆凋敝殘破，糞穢堆滿臺階，道路上斷絕了人的足跡；僧徒四處漂泊寄居，既不修繕也不清掃擦拭，寺院日漸衰敗頹廢，造罪造過，沒有一刻停歇。\n因此，葷辛酒肉爭相送進僧房供奉，香花幡蓋卻極少用來供養佛殿；晝夜六時的禮拜，早已無心去行；身口意三業只是虛妄空談，毒害更甚於蜂蠍。甚至帶人一同住宿，一同飲宴用餐，絲竹管絃公然聚會作樂。\n於是使得惡人興起毀壞之心，剛一起意圖謀，寺院便遭摧毀；狂風烈火才剛焚燒，最終便化為煙灰而消滅。這就使得幽冥鬼神顯靈作祟，護法善神捨離守衛。伽藍（的衰敗）並非沒有緣故，正是因為比丘尼持戒有所虧缺；招致世人的譏諷嫌惡，也是由於僧眾沒有綱紀。", "i": "uGAP09-2", "n": 111, "s": "第20篇　致敬"}, {"v": "卷中", "o": "古德《寺誥》乃有十篇，略述三五，不備具錄：或云道場，或云寺，或云無生，或云停毒，或云息惡，或云寂滅，或云淨住，隨義七名，各有所表；今時居者，豈稱名者也？", "t": "古德所著的《寺誥》共有十篇，此處僅略述三五項，不全部詳細抄錄。有的稱為「道場」，有的稱為「寺」，有的稱為「無生」，有的稱為「停毒」，有的稱為「息惡」，有的稱為「寂滅」，有的稱為「淨住」。依循義理所立的這七種名稱，各自都有其所表顯的意涵；現今居住在寺裡的人，哪裡能與這些名稱相稱呢！", "i": "uGAP09-3", "n": 112, "s": "第20篇　致敬"}, {"v": "卷中", "o": "小法滅盡經》云：「劫火起時，曾作伽藍所，不為劫火燒，乃至金剛界為土臺也。」", "t": "《小法滅盡經》說：「當劫火生起時，凡是曾經建作伽藍的處所，都不會被劫火燒毀，甚至直至金剛界，都成為土臺。」", "i": "uGAP09-4", "n": 113, "s": "第20篇　致敬"}, {"v": "卷中", "o": "五百問》中：昔在婆羅門相一比丘，有天子相；時比丘入寺，持錫杖倚佛圖牆，禮佛已出，遂失貴相等。", "t": "《五百問》中記載：從前有一位婆羅門〔「在」疑作「有」〕，為一位比丘看相，看出他具有天子之相。當時這位比丘進入寺院，將錫杖靠在佛塔牆壁上，禮佛完畢出來後，便失去了尊貴之相等。", "i": "uGAP09-5", "n": 114, "s": "第20篇　致敬"}, {"v": "卷中", "o": "僧祇》云：「佛寺惡壞，更好作得。」", "t": "《僧祇律》說：「佛寺如果粗陋毀壞，重新建造得更好是可以的。」", "i": "uGAP09-6", "n": 115, "s": "第20篇　致敬"}, {"v": "卷中", "o": "尼乾經》云：「或嫌塔寺及諸形像妨礙，除滅、送置餘處者，如是惡人，攝在逆眾生數分中，上品治之。」", "t": "《尼乾經》說：「如果有人嫌棄佛塔、寺院以及各種形像造成妨礙，而將它們拆毀除滅或移置到其他地方，像這樣的惡人，歸屬於背逆眾生一類當中，應當以上品重刑來懲治他。」", "i": "uGAP09-7", "n": 116, "s": "第20篇　致敬"}, {"v": "卷中", "o": "十輪經》云：「若破寺、殺害比丘，其人欲終，支節皆疼，多日不語，死墮阿鼻地獄，具受諸苦。」", "t": "《十輪經》說：「如果破壞寺院、殺害比丘，這個人臨命終時，四肢關節都會疼痛，多日不能說話，死後墮入阿鼻地獄，受盡種種痛苦。」", "i": "uGAP09-8", "n": 117, "s": "第20篇　致敬"}, {"v": "卷中", "o": "地持論》云：「支提者名塔。」", "t": "《地持論》說：「『支提』的意思就是塔。」", "i": "uGAP09-9", "n": 118, "s": "第20篇　致敬"}, {"v": "卷中", "o": "雜心論》云：「有舍利名塔，無者名支提，或名塔婆，或名偷婆；支提者，此云廟。」", "t": "《雜心論》說：「有舍利的稱為塔，沒有舍利的稱為支提；塔或稱為『塔婆』，或稱為『偷婆』。至於支提，此地稱為『廟』。」", "i": "uGAP09-10", "n": 119, "s": "第20篇　致敬"}, {"v": "卷中", "o": "耶舍傳》云：「提婆鼻阿羅」者，天謂國王，遊謂僧處，其處王立，故名「天遊」；舊來以「寺」代之，寺乃此土公院，謂是司也、嗣也。", "t": "《耶舍傳》說：「所謂『提婆鼻阿羅』，『天』指的是國王，『遊』指的是僧人住處，那處所是由國王所建立的，所以稱為『天遊』。向來都用『寺』來代替它；『寺』原是此地官府公院的名稱，也就是所謂的『司』與『嗣』。」", "i": "uGAP09-11", "n": 120, "s": "第20篇　致敬"}, {"v": "卷中", "o": "柘鬪提奢」者，舊「招提」者，訛略也；昔人去鬪除奢，柘復誤作，以「柘」、「招」兩字形濫相似，致久來誤矣。", "t": "至於「柘鬪提奢」，過去所稱的「招提」，其實是訛誤簡略的說法。從前的人刪去了「鬪」字、除去了「奢」字，「柘」又誤寫成〔「招」〕；因為「柘」與「招」兩字的字形混雜相似，導致長久以來一直沿用這個錯誤。", "i": "uGAP09-12", "n": 121, "s": "第20篇　致敬"}, {"v": "卷中", "o": "增一經》云：「作房施僧，名招提。」", "t": "《增一經》說：「建造房舍布施給僧眾，稱為『招提』。」", "i": "uGAP09-13", "n": 122, "s": "第20篇　致敬"}, {"v": "卷中", "o": "十誦》云：「有檀越施比丘僧房，轉施比丘尼僧者，是名非法施、非法受、非法用。」", "t": "《十誦律》說：「有施主布施給比丘僧的房舍，若轉施給比丘尼僧，這稱為非法布施、非法領受、非法受用。」", "i": "uGAP09-14", "n": 123, "s": "第20篇　致敬"}, {"v": "卷中", "o": "僧祇》云：「若有檀越施比丘尼房舍等，應讓比丘僧；若不讓而受者，佛言：『此違敬法。", "t": "《僧祇律》說：「如果有施主布施給比丘尼房舍等物，應當禮讓給比丘僧；如果不禮讓而接受，佛說：『這違背了敬法。』」", "i": "uGAP09-15", "n": 124, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第二、敬佛者。惟今道俗，虔誠寡薄，慢怠逾強，輕懱聖容，傲物自廣，遂令故像豐多，盈堂滿室，趺光墮落，手足縱橫，泥木雜汙，糞土狼藉；於是青蓮之座數傾，白毫之相屢危，寶塔自摧，嚴容聳峙。", "t": "第二是敬佛。想到當今出家與在家二眾，虔誠之心稀薄，輕慢懈怠卻越來越盛，輕蔑聖像尊容，對人傲慢而自高自大，於是使舊佛像積得眾多，堆滿堂室：蓮座與背光脫落，手腳斷落橫陳，泥塑木像混雜在污穢之中，糞穢塵土雜亂遍地。因此青蓮花座屢屢傾塌，白毫尊相一再瀕危；寶塔自行崩摧，莊嚴的尊容卻仍高聳矗立。", "i": "u442", "n": 125, "s": "第20篇　致敬"}, {"v": "卷中", "o": "設有與心造作，鎔鑄不圓，相好尊儀，至多疎漏；或爭價高下，增減靈相，逐賤省功，將為稱意，致使形儀換改，不類西華，隨情造作，乃同糞土；遂使國君有破壞之心，臣民存不敬之意，善惡無徵，羣邪競起，至聖不加，反招自辱，靜思己過，豈不然乎？", "t": "即使有人發心造像，熔鑄也不圓滿，尊像的相好極多缺漏。有人計較工價高低，便增減佛像的靈妙相好，只求價賤、省工，還自以為稱心如意；致使佛像的形貌樣式被改換，不像西國華妙的相好，任隨己意造作，竟與糞土無異。於是使國君起了破壞之心，臣民懷著不敬之意，善惡報應看不見徵驗，種種邪見紛紛興起，至聖不再加被護佑，反而招來自身的羞辱。靜下來想想自己的過失，難道不是這樣嗎？", "i": "u442-2", "n": 126, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《阿含經》云：無恭敬心，於佛法中當墮龍蛇中，以過去從中來，今猶無敬，故多睡也。", "t": "《阿含經》說：對佛法沒有恭敬心的人，將來會墮在龍蛇之中；因為過去世從龍蛇中來，如今仍無恭敬心，所以多睡。", "i": "u442-3", "n": 127, "s": "第20篇　致敬"}, {"v": "卷中", "o": "又，佛昇忉利天，優填王請目連：「為我等將巧師看世尊形，下來造之。」三上、三審、三下，始得真相；世尊下來，此像迎佛，佛為摩頂，記當來利益於我。", "t": "又，佛上昇忉利天時，優填王請求目連：「請為我們帶巧匠上去看世尊的形貌，再下來造像。」三度上去、三度審視、三度下來，才得到真實的相好。世尊從天上下來時，這尊像前去迎佛，佛為它摩頂，授記它將來能利益我的教法。", "i": "u442-4", "n": 128, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《敬福經》云：「經像主莫論道，雇經像之匠莫云客作。造佛布施，二人獲福不可度量，欲說其福，窮劫不盡；受吾約制，是佛真子，如是精誠，造少福多。」", "t": "《敬福經》說：造經造像的施主不要說這是雇人做工，寫經造像的工匠不要自稱是受雇做工的傭工；這樣造佛像來布施，二人所得的福德不可計量，要說他們的福德，窮盡一劫也說不完。能接受我的約制規範，才是佛的真子。像這樣精誠造像，所造雖少，得福卻多。", "i": "u442-5", "n": 129, "s": "第20篇　致敬"}, {"v": "卷中", "o": "問：「居士之中作經像師，合取直否？」答：「不得取價直！如賣父母取財者，逆過三千，直是天魔，離吾佛法，非我眷屬。", "t": "問：居士當中擔任寫經造像的匠師，可以收取工錢嗎？答：不可以收取酬價。這就像出賣父母來取財的人，悖逆的罪過超過三千，簡直就是天魔，遠離我的佛法，不是我的眷屬。", "i": "u442-6", "n": 130, "s": "第20篇　致敬"}, {"v": "卷中", "o": "飲酒、食肉、五辛之徒，不依聖教，雖造經像數如微塵，其福甚少，蓋不足言；劫燒之時，不入海龍王藏，勞而少功，不敬之罪，死入地獄，主匠無益，諸天不祐；不如不造，直心禮拜，得福無量。如向所列，造多福少；像師作像不具足相，五百世諸根不具。第一盡心為上，妙果先昇。", "t": "那些飲酒、吃肉、食五辛的人，不依聖教，雖然所造經像多如微塵，福德卻極少，不值一提；劫火燒起之時，這些經像不能進入海龍王的寶藏，徒勞而功效甚少；又因不恭敬的罪，死後墮入地獄，施主與工匠都得不到利益，諸天也不護佑，不如不造。以正直真誠之心禮拜，得福無量。如前面所列，造得雖多，福德卻少。造像師所作的像若相好不具足，五百世中諸根都不具足。首要的是以竭盡心力為上，這樣的人便能先昇獲殊妙的果報。", "i": "u442-7", "n": 131, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第三、敬法者。今時像季，法逐人訛，道俗相濫，傳謬背真，祈求邪道，隨順邪師，法受惡友，不親善友，不修內典，專翫俗書；或淫讀莊、老，躭著孔經，解奏鬼神，呪詛吉凶；或琴棊歌戲，將為正業，講經律論，用為非要；", "t": "第三是敬法。如今正值像法末季，正法隨著人的訛謬而變質，出家與在家混濫不分，輾轉相傳的都是謬誤，背離了真實。有人向邪道祈求，隨順邪師；從惡友那裡領受教法，卻不親近善友；不研習佛典，專門玩習世俗書籍。有的毫無節制地誦讀《莊子》《老子》，沉迷於儒家經書；向鬼神上章奏告、祈解災厄，用咒詛之術為人求福或致禍。有的把彈琴、下棋、歌唱、戲樂當成正業，卻把講說經、律、論看作不要緊的事。", "i": "u443", "n": 132, "s": "第20篇　致敬"}, {"v": "卷中", "o": "或無錢請讀，則舌卷愁開，聞財雇誦，則憂不聲暢；或有抄寫聖文，多豐升錯，既不勘治，又不護淨；或將共同宿，處在門簷，風零雨滴，蟲噉爛滅；", "t": "有的若沒有錢財請他誦讀，就捲舌不念、滿臉愁惱；一聽說有財物雇請誦經，就只担心自己的誦聲不夠響亮流暢。有的抄寫聖典，錯訛極多，既不校勘訂正，也不愛護、保持潔淨；或把經卷帶到自己睡臥之處一同過夜，或放置在門簷底下，任憑風吹、雨水滴落，被蟲蛀咬而爛壞消失。", "i": "u443-2", "n": 133, "s": "第20篇　致敬"}, {"v": "卷中", "o": "或增削經論，加添俗語，科題品目，混濁聖文，致使西河之亂孔子，獻鼠之疑玉璞，經無靈驗之功，誦無救苦之効，招世譏謗，指佛無徵，福不贖過，罪益彌天！", "t": "有的任意增刪經論，攙入世俗語句，自行安立科段標題與品目，把聖典本文弄得混雜不清，以致像西河之人把子夏誤認作孔子、所獻之鼠被誤當作玉璞那樣混淆錯亂。如此一來，經卷沒有靈驗的功效，誦持也沒有救苦的效驗，招致世人譏嫌毀謗，指責佛法沒有徵驗；所造之福不足以贖補過失，罪業卻愈積愈大，彌滿天際。", "i": "u443-3", "n": 134, "s": "第20篇　致敬"}, {"v": "卷中", "o": "故《敬福經》云：「善男子！經生之法，不得一字顛倒、重著、點汙，五百世中墮迷惑道中，不聞正法。」此律云：「若比丘敬佛、僧、戒者，正法不滅；若不敬者，疾滅正法也。」", "t": "所以《敬福經》說：善男子！抄經之法，一個字也不許顛倒、重複贅加或點畫污損，違者五百世中墮在迷惑之道，聽不到正法。本律說：若比丘恭敬佛、僧與戒，正法就不滅；若不恭敬，正法便迅速滅亡。", "i": "u443-4", "n": 135, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《大蓮華經》云：「受佛禁戒，不護將來，各言我是；於大乘法，亦如冥夜，各自說言『我得佛法』，受鐵鏘地獄苦，事難述；從地獄出，瘖瘂聾盲，不見正法。」《摩耶經》云：「若年少比丘，親於眾中毀呰毗尼，當知法滅，不久住。", "t": "《大蓮華經》說：受了佛的禁戒卻不加守護，不顧將來的果報，各人都自稱「我是對的」；對於大乘法也如同處在黑夜之中，各自宣稱「我已得佛法」，結果遭受鐵鏘地獄之苦，苦事難以盡述；從地獄出來以後，又是啞、又是聾、又是盲，見不到正法。《摩耶經》說：若年少比丘當著大眾的面毀謗毗尼，應知正法將滅，不能久住於世。", "i": "u443-5", "n": 136, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第四、敬僧者：", "t": "第四、敬僧：", "i": "uGAP10-1", "n": 137, "s": "第20篇　致敬"}, {"v": "卷中", "o": "惟末世僧尼，諳究既微，積罪尤大，服玩乖於內典，舉動同於外俗，知解類若管窺，升駮剩為大匠，更相扇動，共作愆瑕，互求長短，諍情難息。", "t": "只見末世的比丘與比丘尼，對教理與律制諳習探究既少，所累積的罪業卻尤其深重；日常的服飾與器用違背佛教經典，舉止行為與世俗外人無異。他們的見解如同從竹管中窺天般狹隘，學養錯謬駁雜〔疑作舛駁〕卻妄自充當大師，彼此互相煽動，一同造作過失瑕疵，互相挑剔彼此的長短，爭執之心難以平息。", "i": "uGAP10-2", "n": 138, "s": "第20篇　致敬"}, {"v": "卷中", "o": "或有縱蕩六情，馳騁三毒，明黨癡惡，思厭清眾，恃官形勢，枉厭良善，枷禁囹圄，退令歸俗，自作好人，獨標眾首。", "t": "其中有些人放縱六根的情欲，任由貪、瞋、癡三毒奔馳肆虐，結黨〔疑作朋黨〕營私、愚癡作惡，企圖壓制清淨的大眾；依仗官府的勢力，冤枉欺壓良善的僧尼，甚至給他們戴上刑具關進監獄，逼退他們還俗，自己卻裝作好人，獨自標榜居於大眾之首。", "i": "uGAP10-3", "n": 139, "s": "第20篇　致敬"}, {"v": "卷中", "o": "或有共一伽藍，兩處結界，大院、禪院，不同布薩；法服名利，苟自貪榮；佛制聽戒，便推認惡。", "t": "又有些人同在一座伽藍之中，卻劃分兩處各自結界，大院與禪院不在一起舉行布薩；對於法服、名聲與利益，苟且只顧為自己貪求榮耀，而對於佛陀所制定的聽戒之法，便推卸迴避、視為惡事；", "i": "uGAP10-4", "n": 140, "s": "第20篇　致敬"}, {"v": "卷中", "o": "或有兩處鳴鐘，各集徒眾，諍為多少，致成忿諍，", "t": "又有人在兩處各自敲鐘，分別召集徒眾，互爭誰的人數多、誰的人數少，以致引發忿恨爭執。", "i": "uGAP10-5", "n": 141, "s": "第20篇　致敬"}, {"v": "卷中", "o": "遂使道俗有向背之心，伽藍有不和之相。", "t": "於是使得出家僧尼與在俗信眾產生偏袒向背之心，伽藍之中呈現出不和合的景象。", "i": "uGAP10-6", "n": 142, "s": "第20篇　致敬"}, {"v": "卷中", "o": "佛藏》有鳥鼠之喻，《大集》有獼猴之況。昔者學步耶鄲，不謂匍匐而歸；鷄欲朝鳴，何期反成烏調！", "t": "正因如此，《佛藏經》中有鳥鼠的譬喻，《大集經》中有獼猴的比況。過去有人去耶鄲〔疑作邯鄲〕學步，不料竟爬著回來；雞本想在清晨啼鳴，哪裡料到反而發出烏鴉的叫聲。", "i": "uGAP10-7", "n": 143, "s": "第20篇　致敬"}, {"v": "卷中", "o": "哀哉！哀哉！痛傷難忍！永惟期理，深可慎歟！", "t": "可悲啊，可悲啊！實在痛心傷懷、難以忍受！深長思惟這個道理〔疑作斯理〕，真是應當深深戒慎啊！", "i": "uGAP10-8", "n": 144, "s": "第20篇　致敬"}, {"v": "卷中", "o": "故《大寶積經》云：出家有二種縛：一、見縛，二、利養縛；又二種癰瘡：一、求見他過，二、自覆己罪。", "t": "因此《大寶積經》說：「出家有兩種束縛：一是見縛，二是利養縛；又有兩種癰瘡：一是尋求挑剔他人的過失，二是掩蓋自己的罪過。」", "i": "uGAP10-9", "n": 145, "s": "第20篇　致敬"}, {"v": "卷中", "o": "像法決疑經》云：諸比丘自稱：「我是法師，我是律師，我是禪師。」此三種學人，能滅我法，更非他人，迭相毀呰。", "t": "《像法決疑經》說：「諸位比丘自稱『我是法師』、『我是律師』、『我是禪師』，這三種學人能毀滅我的正法，更沒有其他的人；這三種人彼此互相毀謗。」", "i": "uGAP10-10", "n": 146, "s": "第20篇　致敬"}, {"v": "卷中", "o": "正法念經》云：為求財利說法，名為下施；為名聞勝他說法，名為中施；為增長眾生智慧而為說法，名為上施。或有比丘，不樂禪誦，賣樂求財，於他病者不相應治，生於黑繩地獄。", "t": "《正法念經》說：「為了求取財利而說法，名為下施；為了名聞、勝過他人而說法，名為中施；為了增長眾生智慧而說法，名為上施。有些比丘不喜歡坐禪誦經，賣樂〔疑作藥〕求財，對患病的人不給與適當相應的治療，因而墮生於黑繩地獄。」", "i": "uGAP10-11", "n": 147, "s": "第20篇　致敬"}, {"v": "卷中", "o": "五百問事》云：比丘志樂衣服，晝夜染著，因病致死，後生蛇中，還來纏衣。眾僧葬亡比丘訖，取衣鉢作法，蛇延頸吐毒，僧共看之。有得道者勸蛇令去，遂入草中，毒盛火出，燒身命終，死入地獄。", "t": "《五百問事》說：「曾有比丘心中貪愛衣服，日夜染著不捨，因病而死後，轉生為蛇，又回來纏繞那些衣服。眾僧埋葬完亡故的比丘後，拿取他的衣鉢依律作法，這條蛇便伸長脖子吐出毒氣，眾僧都看著牠。當時有證道的聖者勸導這條蛇離去，蛇於是爬入草叢中，因瞋毒熾盛而發出烈火，燒死自身，命終後墮入地獄。」", "i": "uGAP10-12", "n": 148, "s": "第20篇　致敬"}, {"v": "卷中", "o": "大悲經》云：佛過去時見一切人，故無不傾側謙下禮敬；以是義故，成佛已來，山林人畜見佛行時，無不傾側低頭禮拜。", "t": "《大悲經》說：「佛陀在過去世時，凡遇見任何人，無不傾身側立、謙卑低下地行禮致敬；由於這個緣故，自從成佛以來，山林中的人與禽獸，見到佛陀行走時，無不側身低頭禮拜。」", "i": "uGAP10-13", "n": 149, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律云：其敬長老者，是人能護法，現世有名譽，將來生善道。", "t": "本律說：「凡是恭敬長老的人，這個人就能護持正法，現世獲得好名譽，來世投生於善道。」", "i": "uGAP10-14", "n": 150, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第五、定尊者：《母論》云：下座稱上座為「尊者」，上座稱下座為「慧命」。又，無夏至九夏是下座，十夏至十九夏名中座，二十夏至四十九夏名上座，五十夏已上者，一切沙門、國王之所尊敬，是名耆舊長老。《五分》云：上無人者，即名上座。《婆論》云：內道一切皆是上座，外道一切皆是年少。《僧祇》云：無歲比丘得共三歲坐，乃至七歲得共十歲坐；若臥牀得三人坐，坐牀得二人坐。《伽論》云：地敷得共未受具人坐。", "t": "第五、定尊。《母論》說：下座稱上座為「尊者」，上座稱下座為「慧命」。又說：夏，也就是夏臘，指受具足戒後所經夏安居的年數；從無夏到九夏的是下座；十夏到十九夏稱為中座；二十夏到四十九夏稱為上座；五十夏以上的，為一切沙門與國王所尊敬，稱為耆舊長老。《五分》說：在自己之上沒有更尊長的人，就稱為上座。《婆論》說：佛法內道的一切人都是上座，外道的一切人都算是年少晚輩。《僧祇》說：沒有夏臘的比丘可以與三夏的比丘同坐，乃至七夏的比丘可以與十夏的比丘同坐；若是臥床，可以三人同坐；若是坐床，可以二人同坐。《伽論》說：鋪在地面上的褥墊上，可以與未受具足戒的人同坐。", "i": "u444", "n": 151, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第六、致拜和南者：《出要律儀》云：和南者，恭敬也。《聲論》云：槃那寐者，此翻為禮。《智度論》云：禮有三法：一、口禮，二、屈膝，三、頭至地，是為上禮。又有三禮：下者揖，中者跪，上者稽首。菩薩禮佛有三品：一者、悔過品，二者、隨喜品，三者、請佛品。", "t": "第六是致拜和南。《出要律儀》說：「和南」就是恭敬的意思。《聲論》說：「槃那寐」這個詞，這裡翻譯為「禮」。\n《智度論》說：禮拜有三種作法：一是口禮，只以言語致敬；二是屈膝；三是頭至地，這是最上等的禮。又有三種禮：下等的是作揖，中等的是下跪，上等的是稽首，頭叩至地。菩薩禮佛有三品：一是悔過品，二是隨喜品，三是請佛品。", "i": "u445", "n": 152, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《地持論》云：當五輪至地作禮。《阿含經》云：二肘、兩膝及頂，名五輪。《五分》云：若人多，但別禮師，總禮餘人而去。", "t": "《地持論》說：應當以五輪著地作禮。《阿含經》說：兩肘、兩膝以及頭頂，稱為五輪。\n《五分律》說：如果在場人眾很多，只須個別禮拜自己的師父，對其餘的人總作一禮便離去。", "i": "u445-2", "n": 153, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《三千威儀經》云：繞塔有五：一、低頭視地，二、不得蹈蟲，三、不得左右視，四、不唾地，五、不與人語；又當念佛、法、僧恩。", "t": "《三千威儀經》說：繞塔有五件事：一、低頭看著地面；二、不得踩踏蟲子；三、不得左右張望；四、不得往地上吐痰；五、不得與人說話。又應當憶念佛、法、僧的恩德。", "i": "u445-3", "n": 154, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《梵網經》云：出家人法，不向國王禮拜，亦不應向父母禮拜。《五百問事》云：弟子得禮師塚，以報恩故。律：沙小此彌尼、沙彌、式叉摩那、比丘尼、比丘、如來及塔，如是展轉從下向上，乃至大比丘得禮如來及塔。", "t": "《梵網經》說：出家人的法則，是不向國王禮拜，也不應向父母禮拜。\n《五百問事》說：弟子可以禮拜師父的墳塚，因為要報恩的緣故。\n《四分律》說：小沙彌尼、沙彌、式叉摩那、比丘尼、比丘、如來及塔，這樣依次由下位向上位禮拜，乃至大比丘得以禮拜如來與塔。", "i": "u445-4", "n": 155, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《五百問事》云：繞塔不得女眾隨，有優婆塞者不犯。《見論》云：辭佛法，繞佛三帀，四方作禮而去；合十指爪掌，叉手於頂上却行，絕不見如來，更復作禮，迴前而去。", "t": "《五百問事》說：繞塔時不得讓女眾跟隨；若有優婆塞同行，就不犯。\n《善見論》說：辭別佛的儀法是：繞佛三圈，向四方作禮後離去；十指與手掌相合，將合攏的雙手舉到頭頂上，倒退著走，直到完全看不見如來，再作一次禮，然後轉身向前而去。", "i": "u445-5", "n": 156, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《增一》云：塔前不得禮餘人。《十誦》云：佛塔、聲聞塔前，自他不得禮。《五百問事》云：佛塔前禮比丘，犯墮。", "t": "《增一阿含》說：塔前不得禮拜其餘的人。《十誦律》說：在佛塔、聲聞塔前，不論是禮拜自己的師長或禮拜其他的人，都不可以。《五百問事》說：在佛塔前禮拜比丘，犯墮罪。", "i": "u445-6", "n": 157, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律云：大小便、裸身、剃髮、說法、嚼楊枝、洗口、飯食、噉果等，皆不應禮。《五百問事》云：淨潔鞾、鞋、履，亦得著禮拜。", "t": "《四分律》說：凡在大小便、裸身、剃髮、說法、嚼楊枝、漱口、吃飯、吃果子等情況下，都不應禮拜。\n《五百問事》說：乾淨的靴、鞋，也可以穿著禮拜。", "i": "u445-7", "n": 158, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《僧祇》：不得如瘂羊不語，當相問訊：「少病少惱、安樂否？道路不疲苦否？」", "t": "《僧祇律》說：不得像啞羊那樣默不開口，應當彼此問訊：「少病少惱、安樂嗎？路上不疲勞辛苦嗎？」", "i": "u445-8", "n": 159, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《寶梁經》云：破戒比丘受他持戒者恭敬禮拜，得八輕法：一、作愚癡；二、口瘖瘂；三、顏貌醜陋；四、其面側戾，見者蚩笑；五、轉受女身，作貧窮婢使；六、形體羸瘦，夭損壽命；七、人所不敬，常有惡名；八、不值佛世。此破戒者，乃至大地無涕唾處。", "t": "《寶梁經》說：破戒比丘接受持戒者的恭敬禮拜，會招得八種「輕法」，即卑劣而受人輕賤的果報：一、成為愚癡；二、口啞不能言語；三、容貌醜陋；四、面孔歪斜不正，見到的人都嗤笑他；五、轉而受女身，做貧窮人家的婢女僕役；六、身體瘦弱，壽命短折；七、不受人尊敬，常揹惡名；八、遇不到佛出世的時代。這樣的破戒者，乃至整個大地上，連一處可供他涕唾的地方都沒有。", "i": "u445-9", "n": 160, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第七、八敬者：《五分》云：瞿曇彌白佛言：「願聽女人出家受戒。」佛言：「止！止！莫作是語！所以者何？往古諸佛皆不聽女人出家，諸人皆自依於佛，在家剃髮著袈裟，勤行精進，獲得果證；未來諸佛亦復如是。我今聽汝以此為法。」如是三請，佛亦不聽。瞿曇彌便大啼哭，自剃髮等，乃至佛為說八敬，方聽出家。", "t": "第七是八敬法。《五分律》說：瞿曇彌對佛說：「願佛聽許女人出家受戒。」佛說：「止，止，不要說這樣的話。為什麼呢？過去諸佛都不聽許女人出家，那些女人都各自依止於佛，在家剃髮、穿著袈裟，勤行精進，因而證得道果；未來諸佛也是這樣。我如今聽許你們就以這樣的方式作為修行之法。」瞿曇彌這樣三次請求，佛也都不答應。瞿曇彌便放聲大哭，自己剃髮等等，乃至後來佛為她宣說八敬法，才聽許女人出家。", "i": "uGAP11-1", "n": 161, "s": "第20篇　致敬"}, {"v": "卷中", "o": "母論》云：阿難為女人求出家，迦葉謫罰阿難十事：一者、若女人不出家者，諸檀越等常應各各器盛食，在道側互跪授與沙門；二者、常應與衣服臥具，於道中求沙門受用；三者、常應乘象馬車乘在於道側，以五體投地求沙門而蹈過；四者、常於路中以髮布地，求沙門蹈上而過；五者、常應恭敬心請諸沙門到舍供養；六者、常應生恭敬心，淨掃其地，脫身衣服布地，命沙門坐；七者、乃至脫體上衣，掃比丘足上塵；八者、乃至常應舒髮拂比丘足上塵；九者、乃至沙門威德過於日月，況諸外道，豈能正視於沙門乎？十者、女人不出家者，佛之正法應住千年，今減五百：一百年中得堅固解脫，一百年中得堅固定，一百年得堅固持戒，一百年得堅固多聞，一百年得堅固布施。", "t": "《毘尼母論》說：阿難替女人請求出家，迦葉便以十件事責罰阿難：第一，如果女人不出家，諸施主常應各自用器皿盛著食物，在路旁跪下來，親手奉給沙門；第二，常應布施衣服、臥具，在路上求請沙門接受使用；第三，常應乘著象、馬、車乘，在路旁五體投地，求沙門從自己身上踩踏而過；第四，常應在路上把頭髮鋪在地上，求沙門踏在上面走過；第五，常應以恭敬心請諸沙門到自己家中供養。\n第六，常應生起恭敬心，把地面打掃乾淨，脫下身上的衣服鋪在地上，請沙門坐下；第七，乃至脫下身上所穿的上衣，用它掃去比丘腳上的塵土；第八，乃至常應鋪開自己的頭髮，拂去比丘腳上的塵土；第九，乃至沙門的威德超過日月，何況那些外道，哪裡敢正眼看沙門呢？第十，如果女人不出家，佛的正法本應住世一千年，如今卻減少了五百年：一百年中得堅固的解脫，一百年中得堅固的禪定，一百年中得堅固的持戒，一百年中得堅固的多聞，一百年中得堅固的布施。", "i": "uGAP11-2", "n": 162, "s": "第20篇　致敬"}, {"v": "卷中", "o": "見論》云：所以不聽女人出家者，為敬法故；若度女人出家，正法五百歲不住；由世尊制比丘尼行八敬故，正法還得千年。", "t": "《善見論》說：佛之所以不聽許女人出家，是為了敬重正法的緣故。如果度女人出家，正法就只有五百年，五百年過後便不能住世；由於世尊制定比丘尼奉行八敬法，正法才仍然得以住世滿一千年。", "i": "uGAP11-3", "n": 163, "s": "第20篇　致敬"}, {"v": "卷中", "o": "摩耶經》云：千一百歲已，諸比丘等如世俗人嫁娶行媒，於大眾中毀謗毗尼。", "t": "《摩耶經》說：一千一百歲以後，諸比丘就像世俗人一樣嫁娶、當媒人，在大眾之中毀謗毗尼。", "i": "uGAP11-4", "n": 164, "s": "第20篇　致敬"}, {"v": "卷中", "o": "義云：今時尼眾順教行媒，受俗馳使，街衢路首，輕突大僧，不避尊儀，陵辱上下；或獨行無侶，孤遊聚落，出入行來，類同賤俗。滅法之原，特由於此！然法眾多，不能具述；今但逐要，不過八敬。今列八名，幸願依行，冀正法長存，千齡弗墜耳。", "t": "依義理來說：現今的尼眾順從世俗的教令替人做媒，被俗人差遣奔走；在街頭路口輕慢冒犯比丘，不肯避讓應敬的尊長，對上座下座都欺凌侮辱；有的獨行而無伴侶，孤身遊走聚落，出入來往的樣子與低賤的俗人相同。滅法的根源，正在於此。然而這類敬法眾多，無法一一詳述，現在只擇取要點，不外乎八敬法。如今列出這八條名目，希望大家依教奉行，期望正法長存千年而不墜失。", "i": "uGAP11-5", "n": 165, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律云：一者、百歲比丘尼見初受戒比丘僧，當迎逆禮拜、問訊，請令坐；二者、比丘尼不得罵謗比丘；三者、不得與比丘罪、說比丘過失，比丘得說尼過失；四者、式叉摩那已學於戒，應從眾僧求受大戒；五者、尼犯僧殘，應半月在二部僧中行摩那埵；六者、尼於半月從僧中求請教授人；七者、不應在無比丘處住；八者、夏安居訖，當詣僧中求自恣人。如是八法，並應尊重、恭敬、讚歎，盡形壽不應違之。", "t": "《四分律》說：第一，受戒已滿百歲的比丘尼，見到剛受具足戒的比丘，應當迎接、禮拜、問訊，請他就座。第二，比丘尼不得罵詈、謗毀比丘。第三，不得舉發比丘的罪、宣說比丘的過失；比丘卻可以說比丘尼的過失。第四，式叉摩那學戒已滿，應從僧眾求受具足大戒。第五，比丘尼犯了僧殘罪，應於比丘、比丘尼二部僧中行滿半月的摩那埵法。第六，比丘尼每半月應從比丘僧中求請教授的人。第七，不應住在沒有比丘的地方。第八，夏安居結束後，應到比丘僧中求請自恣的人。這八法都應尊重、恭敬、讚歎，盡此一生都不應違越。", "i": "uGAP11-6", "n": 166, "s": "第20篇　致敬"}, {"v": "卷中", "o": "中含經》云：若比丘聽尼問經、律、毗曇，然後得問；不聽者，犯第五尊師法。", "t": "《中阿含經》說：比丘尼須經比丘允許，才能請問經、律、毗曇；若比丘不允許，尼仍請問，尼便違犯第五尊師法。", "i": "uGAP11-7", "n": 167, "s": "第20篇　致敬"}, {"v": "卷中", "o": "僧祇》云：尼入大僧寺中，應頭面一一禮一切比丘足；若老病不堪，隨力多少，恐不徧者，得就總禮，應云：「我尼某甲，頭面禮一切僧足。」若比丘入尼寺，應須禮，不得罵云：「是犯戒，是醫師，是摩訶羅，無所知。」乃至實罪皆不得說；比丘得說尼實罪。尼若憍慢，不恭敬迎逆禮足者，犯越敬法。", "t": "《僧祇律》說：比丘尼進入比丘寺中，應以頭面一一頂禮一切比丘的雙足；若年老病弱做不到，就隨自己的能力禮多少；恐怕無法周遍的，可以總禮，應當說：「我比丘尼某甲，以頭面頂禮一切僧眾的雙足。」若比丘進入比丘尼寺，尼眾也應禮拜他；不得譏罵說「這是犯戒的」、「這是做醫師的」、「這是摩訶羅，一無所知」，乃至即使是真實的罪過也不得宣說，而比丘可以說比丘尼真實的罪過。比丘尼若憍慢、不恭敬迎接頂禮比丘足，就犯越敬法之罪。", "i": "uGAP11-8", "n": 168, "s": "第20篇　致敬"}, {"v": "卷中", "o": "大愛道尼經》云：若比丘舉比丘尼過，尼應自省，不得高聲大語；又比丘尼敬比丘僧，視之如佛。", "t": "《大愛道比丘尼經》說：若比丘舉發比丘尼的過失，尼應自我反省，不得高聲大聲地說話。又，比丘尼恭敬比丘僧，看待他們如同佛一般。", "i": "uGAP11-9", "n": 169, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律云：比丘尼、式叉摩那、沙彌尼等觸犯諸比丘者，佛言：「應喚來謫罰；若不改悔，應作捨教授羯磨。」", "t": "《四分律》說：比丘尼、式叉摩那、沙彌尼等冒犯諸比丘的，佛說：應把她們叫來責罰；若不悔改，比丘僧就應作捨教授羯磨。", "i": "uGAP11-10", "n": 170, "s": "第20篇　致敬"}, {"v": "卷中", "o": "僧祇》云：若比丘犯過，親里尼得輭語語，不得訶責。", "t": "《僧祇律》說：若比丘犯了過失，作為他俗家親屬的比丘尼可以用柔和的言語勸說，不得訶責。", "i": "uGAP11-11", "n": 171, "s": "第20篇　致敬"}, {"v": "卷中", "o": "十誦》云：尼見大僧不起，提。", "t": "《十誦律》說：比丘尼見到比丘而不起身，犯波逸提罪。", "i": "uGAP11-12", "n": 172, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律：若一比丘喚一比丘尼，乃至眾多比丘尼，應往；若不往，如法治。", "t": "《四分律》說：若一位比丘召喚一位比丘尼，乃至召喚眾多比丘尼，都應前往；若不前往，依律治罪。", "i": "uGAP11-13", "n": 173, "s": "第20篇　致敬"}, {"v": "卷中", "o": "問：「何故制尼依僧耶？」答：《愛道尼經》云：「女人但欲惑色益壽，畜弟子亦不欲學問，但知須臾之事，故依僧也。", "t": "問：為什麼制定比丘尼必須依止比丘僧呢？\n答：《大愛道比丘尼經》說：女人只想貪著自身容色、求長壽、蓄養弟子，也不想學習請問，只知道眼前片刻之事，所以必須依止比丘僧。", "i": "uGAP11-14", "n": 174, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第八、報恩者：《五分》：畢陵伽父母貧窮，以衣食供養。佛言：「若人百年之中，右肩擔父，左肩荷母，於上大小便利，極世珍奇衣服供養，猶不能報須臾之恩。從今聽比丘盡心供養父母，否者得重罪。」《僧祇》云：父母不信三寶者，應少經理；若有信者，得自恣與無乏。父母貧賤，將至寺中，自手與食，一切皆得。《母論》云：父母若貧者，先授三歸、五戒、十善，然後施與；若不貧者，雖受戒不合與。《增一經》云：孝順供養父母，功德果報，與一生補處菩薩功德一等；又云：教二人作善，不可得報恩，謂父母也。是故比丘常當孝順供養父母，不失時節，當如是學。", "t": "第八是報恩。《五分律》說：畢陵伽的父母貧窮，他便以衣食供養父母。佛說：「即使有人在一百年當中，用右肩擔著父親、左肩扛著母親，父母就在他肩上大小便，又用世間最珍奇的衣服供養他們，這樣仍不能報答父母須臾之間的恩德。從今以後，聽許比丘盡心供養父母；若不供養，就得重罪。」\n《僧祇律》說：父母不信三寶的，只應稍加供給照料；若父母已有信心，就可以隨意給與，不使他們匱乏。父母若是貧賤，可以帶到寺院中，親手拿食物給他們，這一切都是開許的。\n《毘尼母論》說：父母若是貧窮，應先為他們授三歸、五戒、十善，然後才布施給他們；若父母並不貧窮，即使他們受了戒，也不應給與。\n《增一阿含經》說：孝順供養父母的功德果報，與一生補處菩薩的功德同等。又說：即使教導這兩人修善，也無法報答他們的恩德，這兩人就是父親與母親。所以比丘應當常常孝順供養父母，不使供養失了時節；應當這樣修學。", "i": "u446", "n": 175, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第九、醫藥者：此律：老病比丘不堪步涉，聽作步挽車、若轝、若乘，除牸牛、草馬等，尼應例前。", "t": "第九是醫藥方面。《四分律》說：年老生病的比丘無法步行跋涉，聽許造人力挽拉的步挽車，或用轎輿抬乘，或騎乘牲畜，但要排除母牛、母馬等母畜。比丘尼應比照前面比丘的規定辦理。", "i": "u447", "n": 176, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《見論》云：作醫師，得突吉羅；若為出家五眾合藥者，得；若和尚、父母在寺疾病，弟子亦得為合藥；", "t": "《善見論》說：作醫師行醫，犯突吉羅；若是為出家五眾調合藥物，就可以。如果和尚或父母在寺中生病，弟子也可以為他們合藥。", "i": "u447-2", "n": 177, "s": "第20篇　致敬"}, {"v": "卷中", "o": "又父母貧賤，在寺內供養，淨人、兄弟、姉妹、叔伯及姨舅等，並得為合藥；無者，自有得借用，不還者勿索，如是乃至七世。", "t": "又如父母貧窮卑賤，接來寺內供養的，以及淨人、兄弟、姊妹、叔伯和姨、舅等，也都可以為他們合藥。若他們沒有藥物或所需的用具，可以把自己所有的借給他們用；他們不歸還，也不要追討。這樣乃至七世的親屬都是如此。", "i": "u447-3", "n": 178, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《五百問事》云：若道人慈心作醫治，不得取物自入己；前人強與，應取。若病、不病，不得服氣唾腫，同外道故。", "t": "《五百問事》說：道人以慈心行醫治病，不得收取財物歸為自己所有；但病人硬要給，就應當收下。無論有病或沒病，都不許修習吐納服氣之術，也不許用唾液唾塗腫瘡，因為這與外道相同。", "i": "u447-4", "n": 179, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《五分》云：為知差次會等，聽學書，不得為好廢業，不聽卜相、問他吉凶。", "t": "《五分律》說：為了知道差派赴會的次序等事，聽許學習書寫記事；但不得為了把字寫得漂亮而荒廢道業。也不許占卜看相，或向人請問吉凶。", "i": "u447-5", "n": 180, "s": "第20篇　致敬"}, {"v": "卷中", "o": "此律：不得賣卜、誦呪、處方治病等，由事容不實，謗毀好人；開學誦書及學世論，為伏外道故。新學比丘開學筭術，尼學呪術醫等得提。", "t": "《四分律》說：不得賣卜、誦咒、開處方治病等，因為這類事可能不確實，反而謗毀了好人。開許學習誦讀與書寫，以及學習世俗的論說，那是為了降伏外道的緣故；新學比丘開許學習算術。比丘尼學習咒術、醫術等，得波逸提罪。", "i": "u447-6", "n": 181, "s": "第20篇　致敬"}, {"v": "卷中", "o": "患吐，用髮燒作灰，以水和漉服；患熱，用旃檀塗、沈水治；患毒，用腐爛藥、田中泥治，亦須水和受服。", "t": "患嘔吐的，用頭髮燒成灰，和水調勻、過濾後服用；患熱病的，用旃檀塗抹，用沈水香治療；中毒的，用「腐爛藥」和田中的泥治療，也必須用水調和，如法受過後才服用。", "i": "u447-7", "n": 182, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《五分》云：青木香著衣中辟蟲。誦呪時，不噉鹽、不眠牀，佛聽神呪法耳。", "t": "《五分律》說：把青木香放在衣服裡可以驅蟲。至於誦咒時不吃鹽、不睡在床上這類禁忌，佛並不聽許，佛只是聽許神咒法本身罷了。", "i": "u447-8", "n": 183, "s": "第20篇　致敬"}, {"v": "卷中", "o": "《僧祇》云：生癰癤，用小麥研塗之。《十誦》云：不淨脂鹽得服。此律：不淨蘇用灌鼻。", "t": "《僧祇律》說：長癰、癤的，把小麥研碎塗敷。《十誦律》說：不淨的脂和鹽可以服用。《四分律》說：不淨的酥可以用來灌鼻。", "i": "u447-9", "n": 184, "s": "第20篇　致敬"}, {"v": "卷中", "o": "第十、殯終者：此律云：白衣來寺中，應方便喻遣；若稱譽佛、法、僧者，隨能為之；若死，為淨伽藍故，擔棄之。《僧祇》云：比丘不得喚爺孃、兄弟等名字，乃至姨姑等，止得稱優婆塞、優婆夷。《增一經》云：佛告阿難：「自今已後，諸比丘稱卿僕射，向大稱尊，向小稱賢，相視當如兄弟；自今已後，不得稱父母所作字。」又小比丘向大比丘稱長老，大比丘稱小比丘為好學。《五分》云：不得展轉作俗人相喚阿婆、阿母、阿兄、阿弟；喚師僧，應言和尚、阿闍梨。《增一經》云：四姓入佛法中，同名為釋迦種子，不得依俗姓。《見論》云：喚婢為大姉，不得云婢。", "t": "第十是殯終。《四分律》說：在家人來到寺院中，應當以善巧方便勸喻，請他們離開；如果是稱揚讚歎佛、法、僧的人，就隨自己的能力為他們做事；如果在家人死在寺裡，為了保持伽藍清淨的緣故，要把遺體抬出去棄置。《僧祇律》說：比丘不得呼喚父母、兄弟等的名字，乃至姨母、姑母等也一樣，只能稱他們為「優婆塞」「優婆夷」。《增一阿含經》說：佛告訴阿難：「從今以後，諸比丘彼此以『卿』『僕射』相稱，對戒臘高的稱『尊』，對戒臘低的稱『賢』，彼此相待應如同兄弟。從今以後，不得稱呼父母所取的名字。」又，戒臘淺的比丘對戒臘深的比丘稱「長老」，戒臘深的比丘稱戒臘淺的比丘為「好學」。《五分律》說：不得像世俗人那樣彼此互稱「阿婆」「阿母」「阿兄」「阿弟」；稱呼師長時應說「和尚」「阿闍梨」。《增一阿含經》說：四種姓的人進入佛法中，一律同名為「釋迦種子」，不得沿用世俗的姓氏。《善見論》說：稱呼婢女要叫「大姊」，不得叫「婢」。", "i": "u448", "n": 185, "s": "第20篇　致敬"}, {"v": "卷中", "o": "○隨戒篇第二十一", "t": "第二十一篇　隨戒篇", "i": "u449", "n": 186, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第一、波羅夷，簡要釋五。尼總有三百四十八：第一篇有八，第二篇有十七，第三篇有二百八，第四篇有八，第五篇有一百及七滅諍，合有三百四十八戒。世人妄傳五百戒者，非也；亦有經律尼戒五百，此但有總數而無實名也。", "t": "第一、波羅夷。先簡要說明五篇：比丘尼總共有三百四十八條戒——第一篇有八條，第二篇有十七條，第三篇有二百零八條，第四篇有八條，第五篇有一百條，再加上七滅諍法，合計共三百四十八戒。世人流傳說比丘尼有五百戒，這是錯誤的。雖然也有經、律說比丘尼戒是五百條，但那只是舉一個總數，並沒有實際的戒條名目。", "i": "u450", "n": 187, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "婬戒，具四緣犯：一、是正道，大小便及口是；二、有染心；三、興方便；四、與境合。但使正道三處，入如毛頭，皆犯。此律：有將小兒根內口中弄，雖本無婬心，但使入時受樂便犯。《十誦》：口中要過齒犯。此律：若為怨家、賊等緣，強持男根令入三處，自無婬心，但使始入、入已、出時無有一念受樂心者，皆不犯；若隨有一時受樂，便犯。若比丘及尼互教，前人作者，偷蘭；前人不作，教者吉羅；下三眾相教，作及不作俱吉，仍作滅擯。不犯者：若睡眠無所覺知，不受樂，一切無有婬意。", "t": "淫戒要具備四個條件才構成犯戒：一是正道，也就是大便道、小便道與口這三處；二是有染污的淫欲心；三是發起方便，動身造作；四是根與境相合。只要在這三處正道中的任何一處，進入的深度哪怕只有毫毛尖端那麼淺，都犯波羅夷。\n《四分律》中有人把小兒的男根放進自己口中玩弄的事例，雖然原本沒有淫欲心，但只要放入時領受到快感，就犯波羅夷。《十誦律》則說：在口道行淫，須入過牙齒才犯波羅夷。\n《四分律》又說：若因怨家、盜賊等緣故，遭人強行捉持男根，令它進入自己的三處，而自己並沒有淫欲心，只要在剛進入時、進入之後、退出時這三個時段中，沒有一念領受快感的心，就都不犯；如果其中任何一個時段領受了快感，便犯波羅夷。\n若比丘與比丘尼彼此教唆對方去做，對方照做了，教的人犯偷蘭遮；對方沒有照做，教的人犯突吉羅。至於式叉摩那、沙彌、沙彌尼這下三眾互相教唆，無論對方做或不做，教唆的人都犯突吉羅；但若實際去做了，就要滅擯，逐出僧團。\n不犯的情形是：在睡眠中毫無覺知；不領受快感；以及一切沒有淫意的情況。", "i": "u451", "n": 188, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "盜戒，具六緣：一、有主物，二、有主想，三、有盜心，四、重物，五、興方便，六、離本處，犯。此中約境判盜，開為十三重：一、佛，二、法，三、僧，四、三寶互用，五、當體互，六、像共寶互，七、即物自互，八、出貸，九、賓客，十、人物，十一、非人物，十二、畜生物，十三、雜明盜業。", "t": "盜戒須具足六個條件才成犯：一、所取的是有主人的物品；二、心裡認定它是有主之物；三、懷有偷盜之心；四、所盜是重物，即價值滿五錢之物；五、發起方便，著手實行竊取；六、使物品離開了原來的位置。\n這裡依所對的物境來判別偷盜，分為十三類：一是盜佛物，二是盜法物，三是盜僧物，四是三寶物之間互相挪用，五是當體互用，即同一類三寶物彼此挪用，如本為某佛所造之物改作另一佛之用，六是像與寶互用，即住持三寶之物與理體三寶之物之間的挪用，七是即物自互，即佛、法、僧三寶各自所屬的物，於同一寶之內，堂宇等受用物、田園等施屬物、香燈等供養物、飲食等獻物這四類，於一一物中彼此挪用，八是出貸財物，九是接待賓客，十是盜人的物品，十一是盜非人的物品，十二是盜畜生的物品，十三是雜明其餘種種偷盜的業相。", "i": "u452", "n": 189, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第一、盜佛物者：《十誦》云：盜佛圖物、精舍中供養具，若有守護主，計直犯重。《毗柰耶律》云：盜佛物等，望本主結重，由斷彼福故。《十誦》偷舍利、《婆論》盜佛，並為淨心供養，自念云：「彼亦弟子，我亦弟子。」如是者不犯。《伽論》云：盜佛舍利，不滿五，偷蘭遮；滿五，犯重。", "t": "第一，盜取佛物。《十誦律》說：偷盜佛塔的物品、精舍中的供養器具，如果有守護管理的主人，就按所盜物的價值計結，值滿五錢便犯波羅夷重罪。《毗奈耶律》說：偷盜佛物等，是就原來的施主這一邊結成重罪，因為斷絕了他供佛所得的福德。《十誦律》所說的偷取舍利、《薩婆多論》所說的盜取佛像，都是為了以清淨心供養，自己心裡想：「他也是弟子，我也是弟子」，像這樣就不犯。《摩得勒伽論》說：偷盜佛的舍利，價值不滿五錢的犯偷蘭遮，滿五錢的犯波羅夷重罪。", "i": "u453", "n": 190, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第二、盜法物者：此律云：時有盜他經卷，佛言：「佛語無價，計紙墨犯重。」《十誦》云：借他經，拒逆不還，令主生疑，犯蘭。《正法念經》云：盜他秘方，犯重。《五百問事》云：地中伏藏物，若為三寶齋堂設會，得取無罪。不得口吹經上塵，亦不得燒故經，得重罪，如燒父母；不知有罪者，不犯。義云：如前盜舍利不犯者，為施主情通；若局不通，亦應得重。造經通塞亦然。", "t": "第二，盜取法物。《四分律》說：當時有人偷盜他人的經卷，佛說：佛語是無價的，只按紙、墨的價值計算，值滿五錢即犯重罪。《十誦律》說：借了他人的經卷，卻違拒不肯歸還，使經主對能否收回心生疑慮，犯偷蘭遮罪。《正法念處經》說：偷盜他人的秘方，犯重罪。《五百問事》說：地中埋藏的財物，若是為三寶、為齋堂、為設齋會而取用，可以取，沒有罪；不可以用口吹去經卷上的灰塵；也不可以焚燒破舊的經卷，燒了得重罪，如同焚燒自己的父母一樣；不知道這樣做有罪的人，不犯。依義理判定說：前面所說盜取舍利而不犯的情形，是因為施主的施心通泛、不加限定；如果施心有所局限而不通泛，取用也應當得重罪。至於施造經卷，施心是通泛還是局限，判罪也是同樣的道理。", "i": "u454", "n": 191, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第三、盜僧物者：若有守護主，望守護人犯重；若主掌自盜，準《善見論》，盜僧物犯重。《僧祇》云：若將長食還房，偷蘭遮。《婆論》云：不打鐘食者，犯盜；又空寺中見食盜噉，隨多少犯罪。《善生經》云：盜亡比丘物，若未羯磨，從十方僧得罪輕；若已羯磨，望現前僧得重；若臨終時隨亡人囑物，盜者隨約所與人結罪。《五分》云：盜心貿僧好物，直五錢犯重，一錢已上蘭。", "t": "第三，盜僧物。僧物若有人守護掌管，就望這位守護人結罪，犯波羅夷重罪；若是主管掌物的人自己偷盜，依《善見論》判定，盜僧物同樣犯波羅夷重罪。《僧祇律》說：把超出自己份額的僧食帶回自己房中，犯偷蘭遮。《薩婆多論》說：不打鐘就吃僧食的，犯盜罪；又若在空無人的寺院中見到食物，以盜心取來吃，隨所取價值多少而結罪。《善生經》說：盜取亡故比丘的遺物，如果還沒有作分配遺物的羯磨，就從十方僧這邊結罪，所得的罪較輕；如果已經作了羯磨，便望現前僧結罪，得重罪。若是臨終時亡人囑咐要給某人的物品，盜取的人就依囑授所指定的那位受贈人來結罪。《五分律》說：以盜心交易僧眾的好物品，價值滿五錢犯波羅夷重罪，一錢以上犯偷蘭遮。", "i": "u455", "n": 192, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第四、三寶互用者：《僧祇》云：寺主摩摩帝互用佛、法、僧物，謂之不犯，佛言：「彼羅夷！」義云：今時僧尼掌三寶物，取僧粮食，乘僧驢馬，使僧家人為佛法營使者，並依律滿五犯重。", "t": "第四，三寶物互相挪用的情形。《僧祇律》說：寺主摩摩帝把佛物、法物、僧物互相挪用，自認為不犯；佛卻判定說：這是波羅夷重罪。依義而言：現今僧尼掌管三寶物的，取用僧眾的糧食、騎乘僧眾的驢馬、差使僧家的僕役，拿去為佛事、法事營辦差遣，這些都依律計算，價值滿五錢就犯重罪。", "i": "u456", "n": 193, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《寶梁經》云：佛、法二物不得互用，由無人與佛、法物作主，復無可諮白，不同僧物。常住、招提互有所須，營事比丘和僧索欲，行籌和合者，得用。僧物修治佛塔，依法取僧和合者，得用；不和者，勸俗修治。", "t": "《寶梁經》說：佛物與法物這兩種不得互相挪用，因為沒有人能替佛物、法物作主，也沒有可以稟白請示的對象；僧物則與此不同。常住僧物與招提（四方）僧物之間彼此有需要時，營辦事務的比丘集合僧眾、索取未到場者的與欲同意、行籌表決，僧眾和合同意的就可以取用。若要用僧物修治佛塔，依法取得僧眾和合同意的才可以用；僧眾不和合的，就勸俗人來修治。", "i": "u456-2", "n": 194, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若佛塔有物，乃至一錢，以施主重心故，捨諸天及人，於此物中應生佛想、塔想，乃至風吹雨爛，不得貿寶供養，以如來塔物無人作價。", "t": "佛塔所有的物品，哪怕只是一錢，由於是施主以殷重之心施捨的緣故，諸天與人都應對這些物品生起「這是佛物、這是塔物」的想法；乃至被風吹壞、被雨淋爛，也不得變賣換取財寶來作供養，因為如來塔物沒有人能作主估定它的價值。", "i": "u456-3", "n": 195, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《五百問事》云：本非佛堂，設像在中，比丘如法共宿，作隔障不犯，由佛在世亦與弟子同房宿故。《婆論》：四方僧地，不和合者，不得作佛塔、為佛種華果。《十誦》云：僧園中樹華，聽取供養佛塔。《僧祇》云：院內樹薪，應取少多溫室、食厨、別房用，不得過取；若無分限者，隨意多少，應取乾枯者。《十誦》云：樹皮葉等，隨比丘用。", "t": "《五百問事經》說：本來不是佛堂的房舍，在其中安設了佛像，比丘依法與之同房共宿，只要作了隔障就不犯，因為佛在世時也曾與弟子同房而宿的緣故。《薩婆多論》說：四方僧的土地，僧眾不和合同意的，不得在上面建佛塔，也不得為佛種植花果。《十誦律》說：僧園中的樹花，聽許摘取來供養佛塔。《僧祇律》說：院內的樹木柴薪，應酌量取用，供溫室（浴室）、食堂廚房及別房使用，不得過量取用；若沒有規定限量的，就隨需要多少取用，但應取乾枯的枝木。《十誦律》說：樹皮、樹葉等，隨比丘取用。", "i": "u456-4", "n": 196, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "義云：雖有此開，亦復省己用之。損僧物者，其業甚重，隨盜一毫，則望十方凡聖結罪。故《方等經》中華嚴聚菩薩云：「五逆四重，我亦能救；盜僧物者，我所不救。」《大集經》云：盜僧物者，罪同五逆。《觀佛三昧經》云：用僧祇物者，過殺八萬四千父母等罪。並違戒律，故受斯殃；是故行者，宜急深訪。", "t": "依義而言：雖然有這些開許，也仍須自我省察、節制地使用。損耗僧物的人，所造的業極重，只要盜取一毫，就對十方凡夫與聖眾結罪。所以《方等經》中華嚴聚菩薩〔疑作華聚菩薩〕說：五逆與四重罪，我還能救；盜僧物的人，我救不了。《大集經》說：盜僧物的人，罪等同五逆。《觀佛三昧經》說：使用僧祇（僧眾）之物的人，罪過超過殺害八萬四千父母等罪。這都是因為違犯戒律，才遭受這樣的殃報。因此，修行的人應當急切地深入訪求此中律義。", "i": "u456-5", "n": 197, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第五、當體互用：謂本作釋迦，改為彌勒；本作《大品》，改充《涅槃》；本作僧房，改供僧食，皆是違反施心，並得互用罪。", "t": "第五種是「當體互用」，也就是在同一類三寶物之內彼此挪用。例如：施主原本要造釋迦佛像，卻改造成彌勒佛像；原本要造《大品般若經》，卻改拿去充作《涅槃經》；原本要造僧房，卻改拿去供給僧眾飲食。這些都違背了施主布施的本意，一律犯互用之罪。", "i": "u457", "n": 198, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《五百問事》云：用佛彩色作鳥獸形，得罪，除在佛前為供養故不犯。", "t": "《五百問事經》說：拿供佛用的彩色顏料去製作鳥獸的形像，犯罪；除非是在佛前作為供養之用，才不犯。", "i": "u457-2", "n": 199, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《見論》云：若施主奉施園果，擬為衣服、湯藥，盜心迴分食者，計直得重；若擬作僧房，迴作僧食，犯蘭；若住處乏少粮食，各欲散去，無人守護者，得和僧減用其園果等重物作食守之；若賊亂世，聽持去，賊止還本處；欲供養此像，乃供養彼像，得小罪。", "t": "《善見論》說：如果施主布施園林果實，本意是要用來供給衣服、湯藥，卻以盜心把它改挪過來分給大家喫，就計算其價值而犯重罪。如果本意是要造僧房，卻改挪作僧眾的飲食，犯偷蘭遮。如果住處缺乏糧食，僧眾各自想要散去，沒有人守護寺院，這時可以和合僧眾、取得同意，酌量挪用那些園果等重物做成飲食，讓僧眾留下來守護住處。若遇盜賊擾亂的亂世，聽許把這些財物帶走；盜賊平息之後，就要歸還本處。本來要供養這尊佛像，卻拿去供養那尊佛像，犯小罪。", "i": "u457-3", "n": 200, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《十誦》云：僧房壞，持僧臥具等物賣治房舍。", "t": "《十誦律》說：僧房損壞時，可以拿僧眾的臥具等物去變賣，用來修治房舍。", "i": "u457-4", "n": 201, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《伽論》云：持此四方僧物，盜心度與餘寺，得小罪，以還為僧用故，不得重。", "t": "《摩得勒伽論》說：把此處四方僧的財物，以盜心轉送給其他寺院，犯小罪；因為終究還是給僧眾使用，所以不犯重罪。", "i": "u457-5", "n": 202, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "義云：若為僧使，路無乞食處，聽和僧持食，在道得食，準前《善見》守寺之文；在寺莊田碾磑，為知事者，鳴鐘得食。若知事人為僧撿挍，將僧淨人畜生，至餘寺莊田食僧粮草豆，準前《伽論》得吉；若私為己知識相看，縱是僧家淨人畜生，計直犯重。", "t": "依義判說：如果是為僧眾出差辦事，路上沒有可以乞食的地方，聽許在和合僧眾之後，帶著僧食在路上食用，這是依準前面《善見論》守護寺院的文意。在本寺的莊田、碾磨作坊擔任知事辦事的人，打鐘時便可以喫食。如果知事人是為了僧眾的事務去檢核督辦，帶著僧家的淨人、畜生到其他寺院的莊田，食用那裡的僧糧、草料、豆子，依準前面《摩得勒伽論》所說，犯突吉羅。如果是私下為了探望自己的親友相識而去，縱然帶的是僧家的淨人、畜生，也要計算所消耗的價值而犯重罪。", "i": "u457-6", "n": 203, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：若國土荒壞，住處無人，得持此寺物，將向餘寺；若國土還靜，本住處有人，還持此物歸本寺，否者如法治。", "t": "《四分律》說：如果國土荒亂破壞，住處沒有人，可以把這間寺院的財物帶到其他寺院去；等到國土恢復安寧，原本的住處又有人了，就要把這些財物帶回本寺，不這樣做的，依律治罪。", "i": "u457-7", "n": 204, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第六、像共寶互：謂住持三寶與埋寶互用，還得罪。", "t": "第六是「像共寶互」，也就是住持三寶的財物與理體三寶的財物彼此挪用，這也同樣要結罪。", "i": "u458", "n": 205, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第七、佛物自互者：《五百問事》云：佛物買取供養具供養，不得賣佛身上繒與佛作衣；又佛堂柱壞，換訖，故柱施僧，僧不得用。《十誦》云：以佛塔物出貸，佛言：「聽。」《僧祇》云：供養佛物，華多，聽轉賣買香燈供養，猶故多者，轉賣著無盡財中。《五百問事》云：先上佛幡，得取作餘佛事用，若施主不聽，不得用。", "t": "第七、佛物自身的互用：《五百問事》說：佛物可以拿去購買供養器具來供養佛；但不得賣掉佛像身上披掛的繒帛，拿去為佛做衣服。又，佛堂的柱子壞了，更換之後，舊柱即使布施給僧眾，僧眾也不得使用。《十誦律》說：把佛塔的財物拿出去放貸生息，佛說：允許。《僧祇律》說：供養佛的物品中花太多，允許轉賣，買香和燈來供養；如果還是太多，就轉賣，把所得歸入無盡財中。《五百問事》說：先前獻掛給佛的幡，可以取下來作其他佛事之用；但如果施主不允許，就不得使用。", "i": "u459", "n": 206, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第八、出貸者：《僧祇》云：塔、僧二物互貸，分明券記某時貸、某時還；若知事交代，當於眾中讀疏分明唱記，付囑後人，違者結罪。《十誦》云：別人貸塔、僧物，若死，計直還。《見論》云：亦得貸借財物作私舍。《善生經》云：病人貸三寶物，十倍還之；餘不病者，良恐不開。", "t": "第八類是出貸。《僧祇律》說：佛塔物與僧物這兩類財物可以互相借貸，但要清楚地立下契券記錄，載明何時借出、何時歸還。如果知事僧交接職務，應當在大眾當中宣讀帳目文書，明白地唱說並記錄下來，交付囑咐給後任的人；違反的人要結罪。《十誦律》說：個人可以借貸佛塔或僧團的財物；若借貸的人死了，要折算價值償還。《善見論》說：也可以借貸僧團的財物來建造私人房舍。《善生經》說：病人可以借貸三寶物，要以十倍償還。其餘沒有生病的人，恐怕就不開許了。", "i": "u460", "n": 207, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第九、賓客等者：此律云：若知法律者，凡所至處，迎逆供給飲食。《十誦》：以此人替補我處，故須供給。《僧祇》云：若惡賊、愚夫、工匠、國王、大臣，有力能損益者，應與飲食。《五分》：若白衣入寺，不與食，起嫌心，佛言：「應與。」持惡器與，又嫌，佛言：「以好器與。」《十誦》云：病人索僧貴藥，與兩錢半價。《見論》云：若淨人分番上下者，上者與衣食，下者不得與；長使者，供給衣食。《十誦》云：客作人，若雇得一日使，卒遇風雨難緣不得作者，佛令量功與價。", "t": "第九類是賓客等。《四分律》說：若是通曉法與律的人，凡是他所到之處，都應當迎接、供給飲食。《十誦律》說：因為這樣的人能代替我、補上我的位子，所以必須供給。《僧祇律》說：凶惡的盜賊、愚昧的人、工匠，以及國王、大臣等，凡是有勢力、能造成損害或帶來利益的，都應該給與飲食。《五分律》說：有在家人進入寺院，僧眾不給他食物，他便心生嫌恨；佛說：應該給。於是拿粗劣的器皿盛食給他，他又嫌棄；佛說：要用好的器皿給。《十誦律》說：病人索取僧眾的貴重藥品，給與價值兩錢半的藥。《善見論》說：如果淨人是分班輪值的，上來當值的給與衣服飲食，下去不值勤的不得給；若是長期固定役使的淨人，則供給衣服飲食。《十誦律》說：受雇的工人，如果已雇定一天，在使令他做工時突然遇到風雨等障難而無法工作，佛令衡量他實際做成的工作量來給與工錢。", "i": "u461", "n": 208, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第十、盜人物者：", "t": "第十、盜人財物", "i": "uGAP12-1", "n": 209, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "見論》云：比丘為他別人乃至三寶守護財物，若謹慎掌護，堅鎖藏戶，而賊或從孔中、屋中竊取、逼迫取，非守護主能禁限者，但望本主結罪，皆不合徵；若主掌懈慢，不勤掌錄，為賊所偷者，守物比丘須償之，以望守護主結罪。", "t": "《善見論》說：比丘替其他個別人士乃至三寶看守財物，如果已經謹慎掌管防護，將庫房門戶鎖牢，而賊人仍從孔洞中或屋內竊取，或者以強暴威逼手段奪取，這並非看守者所能防範制止的範圍，對賊人只依原本的物主來判定盜罪，對看守人一概不應責令賠償。如果看守人怠惰疏慢，不勤勉掌管登記，以致財物被賊人偷走，看守財物的比丘就必須賠償，因為這時是依看守者作為守護主來判定盜罪的。", "i": "uGAP12-2", "n": 210, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "十誦》：遠處受他寄物，在道損破者，好心投破者不應償，惡心投破者須償；借他物，不問好心，若破，一切須償。", "t": "《十誦律》說：在遠處接受他人託付寄帶的物品，途中有所損壞打破的，若出於好心而失手摔破，不應賠償；若懷著惡意摔破，就必須賠償。至於借用他人的物品，不論是不是出於好心，只要打破了，一概都必須賠償。", "i": "uGAP12-3", "n": 211, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "義云：今多有好心為他洗治鉢器，好心損破，準此不合償；主索，計錢犯重。", "t": "依律義來說：如今多有人好心替別人清洗整理鉢具器皿，在好心之下不慎損壞打破，準照上述律文是不應賠償的；如果原物主強行索賠，依所索賠的錢財價值計算，就犯重罪。", "i": "uGAP12-4", "n": 212, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "有人不現前盜得物，雖本心不捨，後見不得奪，犯重。故此律、《十誦律》：時有比丘奪劫者物，佛言：「波羅夷。」若現前盜者，賊心猶豫，本主不捨，護心義強，得取故。", "t": "如果有人在物主不在場時偷得了物品，原物主雖然本心並未捨棄該物，但事後再見到時，仍不得強行奪回，若奪回就犯重罪。因此《四分律》與《十誦律》都記載：當時有比丘奪取搶劫者所劫得的物品，佛陀判定犯波羅夷罪。若是當著物主的面偷搶，賊人的佔有心意尚在猶豫，原物主也沒有捨棄，守護己物的心意較強，因此可以奪回。", "i": "uGAP12-5", "n": 213, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：逐賊和喻得、恐嚇得，無犯；或因他逐，恐怖故施，得取，以成物主故，但使不從賊乞，他自與者，得；取已，染壞色著，若有主識認者應還。若賊比丘尼邊認得衣，本主見者不得直奪，應還本直。", "t": "《僧祇律》說：追趕賊人時，無論是好言勸喻而取回，還是威嚇迫使交出，都不犯戒。或者賊人因被他人追趕而心生恐懼，因此把贓物布施出來，這時可以收受，因為賊人已經成為該物的物主了；只要不是向賊人乞討，而是他自己主動給與的，就可以拿取。拿取之後，要染成壞色再穿著；如果有原物主認出來，就應當歸還。\n若是在偷盜的比丘尼那裡認出自己的衣服，原物主見到了也不得直接強行奪回，而應由那位比丘尼償還原物本來的價值。", "i": "uGAP12-6", "n": 214, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：若人被官收錄，未抄物名，寄付比丘者，得取；若已抄錄者，不得取；若施佛、塔、僧者，得取，應露現持出，不得覆藏；若問「是何物」，應答言：「佛、法、僧物。」不許者還。", "t": "《僧祇律》說：如果有人被官府拘捕收押，在官府還沒有登記財物名稱造冊之前，把財物寄託給比丘，比丘可以收受；如果官府已經登記造冊了，就不得收受。如果布施給佛、塔或僧眾，可以收受，但應當公開顯露地拿出去，不得偷偷遮藏；如果有人盤問這是什麼東西，應當回答說是「佛、法、僧之物」；倘若不准許帶走，就退還回去。", "i": "uGAP12-7", "n": 215, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "婆論》云：持國禁物出界，罪入死者得重，又違王教吉羅；王民合死，盜持出得重；自外不聽、無盜心者，不犯。", "t": "《薩婆多論》說：攜帶國家禁止輸出的物品出境，若依王法該當死罪，比丘就犯重罪；同時又因違背國王的教令而犯突吉羅罪。國王的百姓若依法應處死刑，比丘以盜心把他帶出境，也犯重罪。除此以外，雖然國王不准許，但只要沒有盜心，就不犯戒。", "i": "uGAP12-8", "n": 216, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：官稅比丘物，方便自免，不犯重：一、我不共要，二、非理稅我故。", "t": "《僧祇律》說：官府對比丘的物品徵稅時，比丘設法自行免除繳稅，不犯重罪，原因有二：一是我不曾與官府立約繳稅，二是官府不合道理地向我徵稅。", "i": "uGAP12-9", "n": 217, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律云：比丘無輸稅法，不同白衣；官須稅物，比丘為他隱認者，得重。", "t": "《四分律》說：比丘沒有繳納賦稅的規定，不同於在俗的白衣；但對於官府應當徵稅的物品，如果比丘替他人隱匿冒認，就犯重罪。", "i": "uGAP12-10", "n": 218, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "義云：今時僧尼多為俗人影認車牛人物免稅，計直犯重。", "t": "依律義來說：如今僧尼往往替俗人假冒認領車乘、牛隻、人口、財物來逃避賦稅，依價值計算就犯重罪。", "i": "uGAP12-11", "n": 219, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "伽論》云：若狂人自持物施，不知父母眷屬者，比丘得取；若父母可知，不自手與，不得取。", "t": "《摩得勒伽論》說：如果精神狂亂的人自己拿著財物來布施，而查不到他的父母、眷屬是誰，比丘可以收受；如果他的父母、眷屬可以查知，又不是他親手交與的，就不得收受。", "i": "uGAP12-12", "n": 220, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第十一、盜非人物者：《五分》云：盜他覆塚幡蓋、神廟中衣、他所守護物，計直犯重。《僧祇》云：盜外道塔物、神祀物，得重。《十誦》：盜天神像衣及華鬘等物，偷蘭。《婆論》云：取非人物，五錢已上重蘭，四錢已下輕蘭。《見論》云：取諸鬼神物、繫樹物，無守護者無罪。", "t": "第十一類是盜取天神、鬼神等非人之物。《五分律》說：盜取他人覆蓋墳塚的幡蓋、神廟中的衣物，以及他人所守護的財物，計算所盜物的價值，滿五錢便犯重罪。《僧祇律》說：盜取外道塔中的物品、祭祀神祇的物品，犯重罪。《十誦律》說：盜取天神像身上的衣服及花鬘等物，犯偷蘭遮罪。《薩婆多論》說：取非人之物，價值五錢以上犯重偷蘭遮，四錢以下犯輕偷蘭遮。《善見論》說：取諸鬼神之物、繫掛在樹上的物品，若沒有人守護，取之無罪。", "i": "u462", "n": 221, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第十二、盜畜生物：《十誦》：盜虎殘者吉，由不斷望故；取師子殘者不犯，由斷望故。《婆論》云：一切鳥獸食殘，取者吉。", "t": "第十二類，偷盜畜生的財物。《十誦律》說：偷取老虎吃剩的食物，犯突吉羅罪，因為老虎還沒有斷絕回來吃食的指望；拿取獅子吃剩的食物，不犯，因為獅子已經斷絕了回來吃食的指望。《薩婆多論》說：一切鳥獸吃剩的食物，凡拿取的人都犯突吉羅罪。", "i": "u463", "n": 222, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第十三、雜明盜業者：《善見》云：貴賤處所等，謂此土直減五，彼土直過五；或此土直過五，彼土直減五，並依本處斷。若盜心唱地云：「定是我地。」地主生疑者，犯蘭；決失心者，重。若來問僧，僧答同者，皆重。若共諍園田，違理判與，乃至口斷多端，偷夏、唱大等，得物滿五，皆重；舉一標時重，乃至一髮一麥許皆重，以地深無價故。《十誦》云：或樗蒲、轉齒、圍棊、移子等，皆重。不犯者：律中與想取、己有想取、糞掃取、暫取想、親友意想取等，皆不犯。親友者要具七法：一、難作能作，二、難與能與，三、難忍能忍，四、密事相告，五、互相覆藏，六、遭苦不捨，七、貧賤不輕；如是七法能行者，是善親友，應附之。殺、妄略如大僧辨。", "t": "第十三、雜明盜業：《善見論》說到物價貴賤的地區差別等情形：某物在此地價值不滿五錢，在彼地卻超過五錢；或在此地超過五錢，在彼地卻不滿五錢——一律依財物本處的價值來判罪。若以盜心宣稱某塊地說：「這決定是我的地。」使地主心生懷疑，犯偷蘭遮；若地主因而斷定自己已失去這塊地，就犯波羅夷。若地主前來詢問僧眾，僧眾答話與盜者所說相同，都犯波羅夷。若他人共同爭訟園林田地，負責裁斷者違背正理而判給一方；乃至以口頭非理曲斷的種種手段、虛報夏臘、自稱高臘上位等，只要所得之物價值滿五錢，都犯波羅夷。盜取土地時，移動一根量地的界標，就犯波羅夷；乃至只取得一根毛髮、一粒麥子那麼大的地面，也都犯重罪，因為土地深入地底，價值無法計量。《十誦律》說：如在樗蒲賭博中偷轉骰子、圍棋中偷移棋子以作弊詐取所賭財物等，都犯波羅夷。不犯的情形：《四分律》中說，以為對方已給與而取、以為是自己所有而取、以為是被丟棄的無主糞掃物而取、以為只是暫時借用而取、以為彼此親厚、對方必會同意而取等，都不犯。所謂親友，必須具備七法：一、難作能作，難做的事能為他做；二、難與能與，難捨的東西能給他；三、難忍能忍，難忍的事能為他忍；四、密事相告，私密之事彼此告知；五、互相覆藏，彼此遮掩私隱過失；六、遭苦不捨，對方遭遇苦難時不捨棄他；七、貧賤不輕，對方貧窮低賤時不輕視他。能實行這七法的，才是善親友，應當親近依附他。至於殺戒與妄語戒，這裡從略，如同大僧比丘部分所辨明的。", "i": "u464", "n": 223, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "摩觸戒，六緣成犯：一、是人男，二、人男子想，三、彼此有染心，四、腋已下、膝已上、腕已後，五、身相觸，六、受樂便犯。若尼以輕境觸男子重境，男以輕境觸尼重境，此二皆重，不要二重境相觸。此律云：一有衣、一無衣相觸，蘭；二共有衣，吉。尼隨觸男子多少，一一波羅夷。《僧祇》：若共男子捉器、捉繩、捉杖木等，皆非威儀，欲心動物，偷蘭遮。城門道狹閙，待稀得過。若輕處有瘡癰者，得使男子治，先令兩女人急捉，令覺女人、不覺男子；若重處瘡者，使女師治。《見論》云：比丘觸尼，尼身不動受樂，隨處得罪。《十誦》云：不犯者：若父母、兒想，或水、火、刀、杖惡緣等觸，一切無染心故，不犯，仍有吉罪。義云：今時齋會處，數有尼自行水香等事，終不善，宜令男子行者最好；若自行時，宜可懸放，勿令觸著男子手，諸器物等亦然。", "t": "摩觸戒，具足六個條件便成犯：一、對方是人道男子；二、作人道男子想；三、彼此都有染污心；四、所觸部位在腋以下、膝以上、腕以後，即不含手掌的重境；五、兩身相觸；六、領受觸樂，便成犯。若比丘尼用重境以外的輕境碰觸男子的重境，或男子用輕境碰觸比丘尼的重境，這兩種情況都結波羅夷重罪，不必雙方的重境互相碰觸才成重。《四分律》說：一方有衣、一方無衣而相觸，犯偷蘭遮；雙方都有衣而相觸，犯突吉羅。比丘尼隨她碰觸的男子有多少，每觸一人就各犯一個波羅夷。《僧祇律》說：若與男子共同捉持器物、共同捉繩、共同捉杖木等，都犯非威儀的突吉羅罪；若以欲心去動那些物品，犯偷蘭遮。城門通道狹窄擁擠時，要等到人稀少了才可以通過。若輕境處長了瘡或癰，可以讓男子醫治；但要先叫兩個女人緊緊捉住她，讓她只感覺到女人的捉持，感覺不到男子的碰觸。若重境處有瘡，就讓女師來醫治。《善見論》說：比丘碰觸比丘尼，比丘尼身體雖然不動，只要領受觸樂，就隨所觸的部位結罪。《十誦律》說不犯的情形：若作父母想、兒子想而碰觸，或遇水、火、刀、杖等危難因緣而碰觸，這一切都因沒有染心而不犯重罪，但仍犯突吉羅罪。依義理說：現今齋會的場合，常有比丘尼親自做行水、行香等事，這終究不妥；最好讓男子來擔任行送的人。若必須自己行送，應當先放下讓對方自取，不要碰到男子的手；其他各種器物也同樣如此。", "i": "u465", "n": 224, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "八事成重戒，具五緣成：一、是男子，二、男子想，三、有染心，四、七事未懺悔，五、作八事，便犯。", "t": "八事成重戒，具備五項因緣才構成犯戒：一、對方是男子；二、對對方作男子想；三、懷有染心；四、前七件事未曾懺悔；五、作完這八件事，便構成犯戒。", "i": "uGAP13-1", "n": 225, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：捉手者輕，腕已後重；捉衣者，身上衣；入屏處者，謂離伴見聞處；共立、共語、共行者，亦離見聞處也；身相倚者，二身相及處；共期者，共行婬處。", "t": "依本律，握住手屬於輕罪，觸及手腕以後的部位則屬於重罪；抓住衣服，是指穿在身上的衣服；進入隱蔽處，是指離開同伴看得見、聽得到的地方；共同站立、共同談話、共同行走，同樣是指離開同伴看得見、聽得到的地方；身體互相倚靠，是指兩人的身體彼此觸及之處；共同約定去處，是指約定一同前往行婬的地方。", "i": "uGAP13-2", "n": 226, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若尼及男子二俱染心，犯前七事者，偷蘭；若不懺悔，犯第八事竟，波羅夷。", "t": "如果比丘尼與男子雙方都懷有染心，犯下前面七件事，都犯偷蘭遮罪；如果未曾懺悔，進而犯完第八件事，便犯波羅夷罪。", "i": "uGAP13-3", "n": 227, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若準此，犯八捉手不成重，以事是一。文", "t": "如果依這個道理推論，即使捉手八次，也不構成重罪，因為八次都是同一件事（並非八種各別不同的事）。以上為引文。", "i": "uGAP13-4", "n": 228, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若一男犯八，或一時犯八，八年犯八，八男成八，俱犯重罪，亦無次第，《僧祇》亦然。", "t": "如果對同一名男子犯滿八事，或者在同一時間內犯滿八事，或者歷經八年才犯滿八事，或者對八名男子分別犯下而湊成八事，以上全都構成重罪，而且也不拘發生的先後次序；《摩訶僧祇律》也是這樣規定。", "i": "uGAP13-5", "n": 229, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不犯者：此律云：若有所與、禮拜、悔過、受法，屏處不作惡事，不犯，俱無染心故。下文暗室者提，以招機故。", "t": "至於不犯戒的情況，本律說：「如果是為了交付物品、禮拜、悔過或受學法義，在隱蔽處而不做惡事，都不構成犯戒。」這是因為雙方都沒有染心的緣故。至於下文提到在暗室中的情形則犯波逸提罪，是因為容易招致嫌疑〔疑作譏〕的緣故。", "i": "uGAP13-6", "n": 230, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "覆藏他重罪戒，具六緣成：一、是大比丘尼，二、犯重罪，三、知他犯重，四、作覆藏心，五、不發露，六、明相出，便犯。", "t": "覆藏他重罪戒，具備六項因緣才構成犯戒：一、對方是大比丘尼；二、對方犯了重罪；三、自己知道對方犯了重罪；四、生起覆藏之心；五、不加發露；六、直到天亮明相出現，便構成犯戒。", "i": "uGAP13-7", "n": 231, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "十誦》云：若尼被舉，狂亂心覆者，不犯；若狂止覆者，便犯。", "t": "《十誦律》說：「如果比丘尼已經被舉罪，或者處於神智狂亂的狀態而覆藏，都不犯戒；如果狂亂平息之後仍然覆藏，便構成犯戒。」", "i": "uGAP13-8", "n": 232, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：知尼犯，應向人說；若犯罪人兇惡、有勢力者，恐有命、梵等難，應作念言：「彼業行罪報自當知。」喻如失火燒舍，但自救身，焉知他事？得心相應便罷。", "t": "《摩訶僧祇律》說：「知道有比丘尼犯了重罪，應當向他人舉說；如果犯罪的人兇惡又有勢力，恐怕會招來命難、梵行難等災難，就應當在心中作這樣的念頭：『她所造的業行與罪報，她自己應當知道；就像失火燒到屋舍時，只顧自救其身，哪裡還顧得上別人的事？』只要心中這樣作念、心念與此相應，這件事便可以作罷（不必再向人舉說）。」", "i": "uGAP13-9", "n": 233, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "義云：若欲發露，故不成者，為非清淨者；若對先知不肯發露人，二俱有過，以各須發露故，如向有犯者，不成懺悔。", "t": "就律義而言，如果想要發露卻仍無法成立發露的原因，是因為所告知的對象並非清淨持戒之人。如果是向事先已經知道此事卻不肯發露的人訴說，那麼兩個人都有過失，因為兩個人各自都必須去發露才行；這就像對著同樣犯戒在身的人懺悔，是不能構成懺悔的一樣。", "i": "uGAP13-10", "n": 234, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若欲發露，稱犯重人名，各各說罪名、種，方成發露；若不得人名、罪名，無覆藏過。", "t": "如果想要發露，必須稱說犯重罪之人的名字，並一一說出她所犯的罪名與種類，這才構成發露。如果無法得知犯戒者的名字或所犯的罪名，就不構成覆藏的過失。", "i": "uGAP13-11", "n": 235, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若前人受他發露竟，不須更說；若說，則有無窮之過。若彼犯人自發露竟，餘人作覆藏心皆不成，以根本已發露竟。", "t": "如果對方已經聽受了他人的發露，就不必再去向別人重說；如果還要再說，就會有無窮無盡的過失。如果那位犯罪者自己已經發露完畢，其餘的人縱使起心想要覆藏，也都不構成犯戒，因為根本的罪事已經發露出來了。", "i": "uGAP13-12", "n": 236, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "十誦》云：尼不得比丘前發露麤過，還向尼前懺悔；若不識罪相，至比丘所汎問取解，還至尼邊懺悔。", "t": "《十誦律》說：「比丘尼不得在比丘面前發露麤重過失，應當回到比丘尼面前懺悔；如果辨識不清罪相，可以到比丘處寬泛地請教以求理解，之後再回到比丘尼這邊來懺悔。」", "i": "uGAP13-13", "n": 237, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：若知尼犯重，前食時知，後食時說，蘭；乃至初中後夜，時時並蘭；明相出，重。", "t": "本律說：「如果知道有比丘尼犯重罪，在前食時知道而拖到後食時才說，犯偷蘭遮罪；乃至拖延到初夜、中夜、後夜才說，每過一個時段都犯偷蘭遮罪；直到天亮明相出現，便犯重罪。」", "i": "uGAP13-14", "n": 238, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不犯者：若無人可向說，意欲說而未說明相出，或命、梵等難不說，皆不犯。", "t": "至於不犯戒的情況，如果無人可以向其訴說，或者心中想要說出卻還沒來得及說、天亮明相就已經出現，或者因為怕遭遇命難、梵行難等災難而不說，以上情況都不構成犯戒。", "i": "uGAP13-15", "n": 239, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第二篇，十七僧伽婆尸沙，簡要釋七。", "t": "第二篇：十七條僧伽婆尸沙戒，即僧殘，簡要解釋其中七條。", "i": "u466", "n": 240, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "媒嫁戒，具六緣犯：一、人男女，二、人男想，三、為媒嫁事，四、媒嫁想，五、言章了，六、受語往還報，便犯。此律：若一念頃，乃至須臾暫時和合媒嫁，竝犯僧殘；受男家語時，吉羅；報女家時，蘭；許還報，殘。若作券書，言非我婦，猶未唱出，和者蘭；若婦禮已斷，不復往還，和合者殘。《僧祗》云：若主人畜多婦妾，不均鬬諍，一婦私成，比丘即為和平，或夫婦不和，勸和合者，蘭；若婦人及女還家，比丘到舍便勸早還者，蘭。《五分》云：若為男倩女、為女倩男，長使者，蘭。此律云：知事白僧媒嫁淨人，供給婚具，問僧和可者，一切殘；若非理用物，犯重。《伽論》云：若指腹作媒嫁及自媒身者，蘭。《僧祇》云：乃至為他求好馬種和合者，蘭；餘畜生，吉。《毗柰耶》：得僧殘。", "t": "媒嫁戒具備六項條件便成犯：一、對象是人類的男女；二、心中認定對方是人間的男子（人男想）；三、所做的是媒嫁之事；四、自己認知這是媒嫁之事；五、話說得清楚明白；六、接受一方的託語、前往另一方傳達、再回來回報，這樣就成犯。\n《四分律》說：即使只是一念之間，乃至須臾片刻的短暫和合，凡替他們作媒嫁的，都犯僧殘。接受男家託語時，犯突吉羅；轉告女家時，犯偷蘭遮；女家應允後再回去回報男家，就犯僧殘。\n《四分律》又說：若丈夫已寫下休妻的文書，聲明「她不是我的妻子」，但還沒有公開宣告將她休出，這時去為他們和合的，犯偷蘭遮；若夫婦的名分已經斷絕、彼此不再往來，這時去為他們和合的，犯僧殘。\n《僧祇律》說：若主人畜養了許多妻妾，對待不均而引起爭鬥，其中一婦私下與人成事，比丘便為他們調解和好；或者夫婦不和而勸他們和合——都犯偷蘭遮。若婦人和女兒回到娘家，比丘到那家中就勸她們早點回夫家去，犯偷蘭遮。\n《五分律》說：若為男方請託女方、為女方請託男方，長久充當雙方往來的使者，犯偷蘭遮。\n《四分律》說：知事人向僧眾稟白，要為淨人作媒婚娶，並供給婚禮所需的物品，問過僧眾而僧眾和同許可的，一切都犯僧殘。若不依正理動用僧眾的財物，就犯重罪。\n《伽論》說：若為尚在母腹中的胎兒作媒，以及為自己作媒，都犯偷蘭遮。\n《僧祇律》說：乃至為他人尋求良種馬匹、使牠們和合配種，也犯偷蘭遮；為其餘畜生作和合，犯突吉羅。《毘奈耶》則判得僧殘。", "i": "u467", "n": 241, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "言人戒，具四緣：一、往俗官所言，二、言白衣居士，三、詞列其事，四、下手疏，便犯。此律：相言，謂詣官共諍曲直，若斷官下手疏者，僧殘；說不道名目者，偷蘭。《見論》云：至官言人，令官罰物，隨多少犯罪，物應償之；若被奪物，得就官乞護身，不得道名字，官目訪得治罰，無犯。若人入寺斫伐樹木，不得奪刀斧，應還直。《五分》云：若為人輕陵，得語父母、親里有力者援護。《十誦》云：尼在斷事人前瞋恨訶罵本所打人，僧殘；若向餘人訶罵本所打人，蘭。", "t": "到官府控告他人的「言人戒」，須具足四緣才成犯：一、前往世俗官員的處所陳告；二、所控告的是在家的白衣居士；三、言詞中陳述列舉所告的事；四、斷事官下手疏，寫成書面判文，便犯僧殘。《四分律》說：所謂「相言」，就是到官府與人爭訟是非曲直；如果斷事官下手疏、寫成書面判文，犯僧殘；只是口頭陳說而沒有指出對方姓名的，犯偷蘭遮。《善見論》說：到官府控告他人，使官府罰沒那人的財物，就依所罰財物的多少而結罪，所罰的財物應由比丘尼償還。若是自己的財物被人奪走，可以到官府請求保護自身，但不得說出對方的名字；官府自行查訪查出而加以懲罰的，不犯。若有人進入寺院砍伐樹木，不得奪取他的刀斧；若已奪取，應償還刀斧的價值。《五分律》說：若被人欺凌，可以告訴父母、親族鄉里中有勢力的人，請他們援助保護。《十誦律》說：比丘尼在審理訴訟的斷事人面前，以瞋恨心呵罵先前打她的人，犯僧殘；若是向其他人呵罵那先前打她的人，犯偷蘭遮。", "i": "u468", "n": 242, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "度賊女戒，具五緣：一、是賊人罪應死者，二、知是賊女，三、不問王、大臣，四、輒便受具，五、羯磨竟，便犯。《十誦》云：賊有二種：一、偷財物，犯王法，王欲殺之；二、偷身，犯夫，欲殺之。是中犯者：和尚知，殘；闍梨知，蘭；尼僧知，吉；都不知，無犯。《五分》：若發心度賊女，方便乃至集僧，三羯磨未竟，皆吉；三羯磨竟，和尚殘，餘師皆蘭。《僧祇》云：與出家，越；與學戒，蘭；受具戒，殘。", "t": "度賊女戒，須具備五項條件：一、對方是犯了罪、依法應處死的賊人；二、明知她是這樣的賊女；三、沒有先向國王、大臣請問；四、就擅自為她授具足戒；五、羯磨一完成，便犯僧殘。\n《十誦律》說：賊有兩種：一是偷盜財物而觸犯王法，國王要殺她；二是「偷身」，得罪了丈夫，丈夫要殺她。這當中結犯的情形是：和尚尼明知她是賊女仍為她作和尚，犯僧殘；阿闍梨尼明知，犯偷蘭遮；尼僧大眾明知，犯突吉羅；如果全都不知情，就不犯。\n《五分律》說：從發起要度賊女的心念起，種種前方便乃至集合僧眾，只要三次羯磨還沒有做完，都犯突吉羅；三次羯磨做完，和尚尼犯僧殘，其餘諸師都犯偷蘭遮。\n《僧祇律》說：度她出家，犯越毘尼罪；授她式叉摩那的學法戒，犯偷蘭遮；為她授具足戒，犯僧殘。", "i": "u469", "n": 243, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "四獨戒，此戒有四合成一戒。", "t": "四獨戒：這條戒包含四項，合成為一條戒。", "i": "uGAP14-1", "n": 244, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "先明獨渡河，具四緣：一、是河水。此律：水獨不能渡，亦不論深廣；今準道行戒，但使褰衣渡水，異於陸路，皆殘；大界中亦犯，以難同故；如界中有村，獨入亦犯，若有橋者如常開之。", "t": "先說明「獨渡河」，具備四個條件便成犯。第一是河水。《四分律》只說獨自一人無法渡過的水，並沒有論及水的深淺廣狹。現在比照「獨在道行戒」的標準，只要是提起衣裳渡水，與走陸路的情形不同，都犯僧殘。在大界之內也犯，因為所遇的危難相同；就如大界之中有村落，獨自進入也犯。若有橋，就照平常的開緣處理，不犯。", "i": "uGAP14-2", "n": 245, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "二者、獨自渡。如前尼疾疾入水，蘭；雙脚上岸，僧殘；後尼獨入水，蘭，上岸時得前尼為伴，不犯；若乘車、舟等不犯。此律云：彼尼當求一尼共渡，入水時隨入水深淺褰衣，至彼岸時漸下衣已，然後上岸；若不待後伴，犯蘭。", "t": "第二是獨自渡河。例如前面那位比丘尼急急忙忙下水，犯偷蘭遮；雙腳登上對岸，犯僧殘。後面那位比丘尼獨自下水，犯偷蘭遮；上岸時若有前一位比丘尼作伴，就不犯。若乘車、乘船等渡過，都不犯。《四分律》說：那位比丘尼應當尋求一位比丘尼一同渡河；入水時隨水的深淺提起衣裳，到對岸時先把衣裳漸漸放下，然後才上岸；如果不等後面的同伴，犯偷蘭遮。", "i": "uGAP14-3", "n": 246, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "三者、無因緣。除命、梵等難及伴命終，皆不犯。四、獨越至岸，便犯，謂伴中無相援義。", "t": "第三是沒有開緣。若有命難、梵行難等危難，以及同伴命終的情形，都不犯。第四是獨自越水到達對岸便成犯，這是說已無同伴可以互相救援。", "i": "uGAP14-4", "n": 247, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "獨入村，具四緣成：一、是人村，莫問大界內村，獨入皆犯。此律云：尼獨行詣村，隨所至村殘；若空野無道處行，一皷聲間，亦僧殘；村中獨行一界者，吉。《僧祇》云：若共伴至城邑界，當相去在伸手內共入界；若在伸手外獨過界者，蘭。", "t": "「獨入村」具備四緣成犯。第一是俗人的村落。不論是不是大界之內的村落，獨自進入都犯。《四分律》說：比丘尼獨自行走到村落，隨所到的村落，一一犯僧殘；若在空曠野外沒有道路的地方行走，滿一鼓聲間的距離，也犯僧殘；在村中獨行走過一界，犯突吉羅。《摩訶僧祇律》說：若與同伴同行到城邑的界線，應當彼此相距在伸手可及之內，一同入界；若在伸手可及之外獨自越過界線，犯偷蘭遮。", "i": "uGAP14-5", "n": 248, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "二者、獨行。三者、無因緣。四者、越界，便犯。故此律：若無界獨行，一鼓聲間離伴見聞方犯；若至門不待後伴，雙足入門限，僧殘；村中先有尼者不犯，以前尼為伴故；若出村，亦越門限方犯。", "t": "第二是獨行。第三是沒有開緣。第四是越過界線便成犯。所以《四分律》說：若在沒有界的地方獨行，要滿一鼓聲間的距離、離開同伴能見能聞的範圍，才成犯。若到了村門，不等後面的同伴，雙腳跨入門限，犯僧殘。村中若原先已有比丘尼在，就不犯，因為以先到的那位比丘尼為伴。若出村，也是越過門限才成犯。", "i": "uGAP14-6", "n": 249, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "獨宿，具三緣犯：一、離伸手外宿，莫問寺中、村內，牀別、席別竝犯，應在伸手內更相撿挍，方能離過；若本在伸手內，後因睡重忽相離者，不犯；木作離意，隨轉側多少便犯。故律云：共宿者，若舒手不相及，隨轉一一僧殘。《僧祇》云：當在伸手內，一夜中三度以手相尋看，不得一時頓三度看，當初中後夜各一時相尋覓，知其在無。《五分》：若不相及處，初中後夜偷蘭，明相出僧殘。", "t": "「獨宿」具備三緣成犯。第一是離開伸手可及之外而宿。不論在寺院中或村落內，床鋪各自分開、坐席各自分開，都犯。應當在伸手可及的範圍內，彼此互相檢查看顧，才能免除過失。若原本在伸手可及之內，後來因為睡得太沉而忽然相離，就不犯。若本來就存心要離開同伴，那麼隨她翻身轉側多少次，就犯多少次。所以《四分律》說：共宿的比丘尼，若伸手不能互相觸及，每轉側一次，就犯一次僧殘。《摩訶僧祇律》說：應當睡在伸手可及的範圍內，一夜之中要三次用手互相探尋查看；不可在同一時間一口氣連看三次，應當在初夜、中夜、後夜各探尋一次，確認同伴還在不在。《五分律》說：若睡在伸手不相及的地方，初夜、中夜、後夜各犯偷蘭遮，到天亮明相出現時，犯僧殘。", "i": "uGAP14-7", "n": 250, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "二者、無因緣，除命、梵等難、樂靜等不犯。三者、隨臥一一結罪。", "t": "第二緣是沒有正當因緣；若有命難、梵行難等危難，或為喜愛寂靜獨處等，則不犯。第三、隨每次躺臥，各別結一罪。", "i": "uGAP14-8", "n": 251, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "獨在後行戒者：根本、中間故作離伴見聞處行，犯；又伴無難緣，亦犯。此律：見聞俱離，僧殘；見聞互離，偷蘭。", "t": "獨在後行戒：不論在最初出發時或中途，故意走在離開同伴能見能聞範圍的地方，便犯。並且在同伴沒有危難等因緣的情況下如此離伴獨行，也成犯。《四分律》說：見與聞都離開的，犯僧殘；只見、聞其中一項離開的，犯偷蘭遮。", "i": "uGAP14-9", "n": 252, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "次明渡水不犯者：若共伴漸渡，不失威儀，乘船渡、橋上渡、躡梁渡，或同伴死、休道、遠行及諸難等，皆不犯。《五分》云：水狹淺無畏男子處，不犯。", "t": "接著說明獨渡水的不犯情形：若與同伴一起漸漸渡過，不失威儀；或乘船渡過、從橋上渡過、踩踏橋梁渡過；或同伴死亡、罷道還俗、遠行，以及種種危難等，都不犯。《五分律》說：水域狹窄而淺、沒有可畏懼的男子之處，不犯。", "i": "uGAP14-10", "n": 253, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "入村不犯者：如前闕緣便是。獨宿不犯者：此律云：共二尼宿，舒手相及處，若一尼出大小便，或出受經、誦經，若樂靜獨處經行，或為病尼煑羮粥作飯，乃至餘難緣等，不犯。《僧祇》云：若病尼、賊亂圍城，獨宿不犯。", "t": "獨入村的不犯：如前面所說，缺少成犯的緣，便是不犯。獨宿的不犯：《四分律》說，兩位比丘尼一同住宿，彼此睡在伸手可及之處；若其中一位比丘尼出去大小便，或出去受經、誦經，或因喜愛寂靜而獨處經行，或為生病的比丘尼煮羹粥、做飯，乃至其餘危難因緣等，都不犯。《摩訶僧祇律》說：若是生病的比丘尼，或遇賊亂、圍城等情況，獨宿不犯。", "i": "uGAP14-11", "n": 254, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "獨行不犯者：在不離見聞處，若一尼大小便、為諸難等，竝不犯。《僧祇》云：不得出聚落界，除道行便利、邂逅失伴未及中間，不犯；病亦如是。《五分》云：若恐怖走時，老病不及伴者，無犯。", "t": "獨在後行的不犯：處在不離同伴見聞的範圍內；若其中一位比丘尼去大小便，或遇種種危難等，都不犯。《摩訶僧祇律》說：不得走出聚落界；除了在道路上大小便，偶然與同伴失散，在尚未趕上同伴的這段期間不犯，生病的情形也是這樣。《五分律》說：若因恐怖而奔逃時，年老、生病跟不上同伴的，無犯。", "i": "uGAP14-12", "n": 255, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "受染心男子衣食戒，具五緣犯：一、是男，二、男子想，三、染心施衣食，四、知他染心施衣食，五、受得入手，便犯。《僧祇》云：若尼無染心，男子授衣食湯藥，殘；若人與衣盋所須，口雖不語，現身相、畫地作字，知有欲心受者，皆蘭，謂勸受故。《十誦》云：因是尼，與僧設食，偏與所愛尼，兩受者，蘭。", "t": "接受染心男子衣食戒，具備五個條件便結犯：一、對方是男子；二、對他作男子想；三、他以染污心布施衣服、飲食；四、自己明知他是以染污心布施衣服、飲食；五、接受到手，便結犯。\n《摩訶僧祇律》說：即使比丘尼自己沒有染污心，男子以染心授給她衣服、飲食、湯藥而她接受，也犯僧殘。若有人給她衣、缽等所需之物，口中雖然不說，卻以身體動作示意、或在地上寫字表示，她明知對方對自己有欲心而接受的，都犯偷蘭遮——這是因為男子勸她納受的緣故。\n《十誦律》說：男子因這位比丘尼的緣故而設食供養僧眾，卻特別偏給他所愛樂的那位比丘尼；這兩種納受都犯偷蘭遮。", "i": "u470", "n": 256, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "勸受染心男子衣食戒，具五緣犯：一、是人男子，二、染心施食，三、知他染心施食，四、發言激切勸令受之，五、言了，使犯。《五分》：勸受，語語殘。", "t": "勸他尼接受染污心男子衣食戒，須具足五個條件才結犯：一、對方是人間的男子；二、這男子以染污心布施衣食；三、明知他是帶著染污心布施衣食；四、說出急切懇激的言語，勸另一位比丘尼接受；五、勸說的話表達得清楚明白，就犯僧殘。《五分律》說：勸人接受時，每說一句勸受的話，就犯一次僧殘。", "i": "u471", "n": 257, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "汙家擯謗違諫戒，具六緣犯：一、汙家惡行事，二、心未悔改，三、作白驅擯，四、違理謗僧，五、僧如法設諫，六、三諫竟，便犯。此律：汙家但得吉羅，後時擯謗違諫，始得僧殘。於中有四汙家：一、依家汙家，二、依利養汙家，三、依親友汙家，四、依僧伽藍汙家。《婆論》云：作種種惡業，破彼信敬善心，是名汙家；作惡行者，作此不清淨穢汙垢濁，又得惡果故。若以少物贈遺白衣，縱使因此起七寶塔，種種莊嚴，建立精舍，猶如祇桓，四事供養滿閻浮提一切眾聖，不如靜坐清淨持戒，即供養真實法身。不犯者：此律云：若與父母、病人、繫閉獄囚及寺中客作，不犯。", "t": "污家擯謗違諫戒，須具足六個條件才結犯：一、有污家、行惡行的事實；二、內心仍未悔改；三、僧眾作羯磨宣告，將她驅擯；四、她違背事理誹謗僧眾；五、僧眾如法施設勸諫；六、三次勸諫完畢仍不捨棄，便結犯。\n依《四分律》，單是污家只結突吉羅輕罪；要到後來被僧驅擯時誹謗僧眾、違拒勸諫，才結僧殘罪。其中污家有四種：一、依家污家（把某一家的物品偏給另一家，物主生瞋、得物者歡喜，內心標榜名利，招致世俗譏謗）；二、依利養污家（以如法所得的利養，不合理地授給俗人，得到的人報恩、得不到的人懷瞋，退失對方的善心，違背平等布施）；三、依親友污家（依恃國王、大臣等世俗勢力，所為不公平，令俗人生瞋或歡喜）；四、依僧伽藍污家（把僧園中的華果餽贈白衣，使俗人心中常希求僧物恩惠，以非為是，所以叫作污家）。\n《婆論》說：造作種種惡業，破壞對方信仰恭敬的善心，這就叫作「污家」。所謂「作惡行」，是指造作這種不清淨、穢污垢濁的事，而且又會招得惡果的緣故。\n若拿少許物品贈送白衣，縱使對方因此造起七寶塔，以種種莊嚴建立精舍，猶如祇桓精舍一般，並以四事供養遍滿閻浮提的一切聖眾，也比不上自己靜坐、清淨持戒；清淨持戒，就是供養真實法身。\n不犯的情形：《四分律》說，若是給與父母、病人、被囚繫在牢獄中的囚犯，以及寺中僱用的工人，都不犯。", "i": "u472", "n": 258, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第三篇，尼薩耆，簡要釋九。", "t": "第三篇是尼薩耆（捨墮）戒，以下簡要解釋九條戒。", "i": "u473", "n": 259, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "離衣宿戒，具六緣：一、是己五衣，二、受法，三、人衣異處，四、不捨會，五、無因緣，六、明相出，犯。人衣異有四種不同：一者、染礙：謂同界有男子者，名為染礙。故律云：諸比丘脫衣服人家形露，佛言：「除村、村外界。」故知村不攝衣，名為染礙。二者、隔礙：此律：若水陸道斷等，離衣不犯。三者、情礙：此律：若失奪想、惡獸、命梵難緣等，失衣無犯。《婆論》云：王來入界住宿，大小行、在近處，並非衣界，以情隔故。", "t": "「離衣宿戒」具備六項因緣才成犯：一、是自己的五衣；二、已依法受持；三、人與衣分離異處；四、沒有作捨衣法，也未在天明前與衣會合；五、沒有開許離衣的特殊因緣；六、明相出現，即構成違犯。\n「人與衣異處」有四種不同。第一是「染礙」：同一界內若有男子，就名為染礙。所以《四分律》說：諸比丘脫下衣服，在俗人家中形體裸露。佛說：「除去村落以及村落外界（這些地方都不攝衣）。」由此可知村落不攝衣，這就名為染礙。\n第二是「隔礙」：依本律，若水路、陸路交通斷絕等情況，離衣過夜不犯。\n第三是「情礙」：依本律，若生起遺失想、被奪想，或遇到惡獸、危及性命與梵行的障難因緣等，失衣無犯。《婆論》說：國王進入界內住宿，以及大小便處，雖然就在近處，卻都不算作衣界，這是因為心意上有所隔礙（不敢自在前往取衣）的緣故。", "i": "uBLIND-G01-1", "n": 260, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "四者、界礙：此律：自然衣界有十一種：一、伽藍，二、村界，三、樹界，四、場界，五、車界，六、船界，七、舍界，八、堂界，九、庫界，十、倉界，十一、蘭若界。前中伽藍及村二界各有四相成者，不名多界，為僧、村二界義強，襵前九界，便成一界；若此四相不圓者，諸界並生，便有十一界起。故律云：若干界四相：一、周帀垣墻，二、籬柵不周，三、籬牆不周，四、四周有屋。此律云：十一界各加勢分，更有十三步。故律云：以中人擲石所及處是。《見論》云：中人者，取不徤不羸人，盡力擲至落處，不取轉處。若置衣在十一種界內，身在界外宿，若不捨會，不至擲石所及處，明相出，一一犯捨墮。若界內有男子，持衣須近身；不爾，明相出犯捨，以無勢分故。", "t": "第四是「界礙」。《四分律》說：自然衣界共有十一種：一、伽藍界，二、村界，三、樹界，四、場界，五、車界，六、船界，七、舍界，八、堂界，九、庫界，十、倉界，十一、蘭若界。前述之中，伽藍與村落這兩種界，若各自具備四相而成立，就不名為多界；因為僧界、村界二者的義勢較強，能攝收其餘九界，合成一界。如果這四相不圓滿具備，諸界便並立而生，就有十一種界生起。所以律中說「若干界」（這是說界內有三種礙生起）。四相是：一、四周環繞的垣牆；二、有籬柵但不周全；三、有籬與牆但不周全；四、四周都有屋舍。\n依本律，這十一種界各自還要加上「勢分」，即界外另有十三步的範圍。所以律中說：「以中等人擲石所及之處為準。」《見論》說：所謂中人，是取不強健也不瘦弱的人，盡力擲石，以石頭落地之處為準，不取石頭滾轉後的位置（諸師依義理評定，計為十三步）。\n如果把衣放在這十一種界之內，而自身在界外住宿，既不作捨衣或會衣，又不到擲石所及的範圍內，明相出現時，一一衣都犯捨墮。如果界內有男子，持衣就必須貼近自身；否則明相出現時即犯捨墮，因為（有男子在的界）沒有勢分的緣故。", "i": "uBLIND-G01-2", "n": 261, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "又餘部衣界有四：一、道行者：《十誦》云：與師持衣道中行，前後四十九尋內不失衣；《婆論》云：縱橫四十九尋內不失衣。二、洲上界者：《見論》云：水洲上十四肘內不失衣；若有人來往，衣須近身，不爾失衣。三、水界者：《見論》云：比丘在阿蘭若處，夜入池中浴，未竟明相出，犯捨；《母論》云：一脚在岸，一脚入水，雖經明相，不失衣。四、井界者：《僧祇》云：道行露地井闌旁宿，諸衣在二十五肘內，身在外宿者失衣；或置衣井內，身在上宿，不以繩連，或不垂手脚，經明相出，皆犯。《明了》云：道行夜宿，錯持衣去，他衣不失，己衣失也。", "t": "此外，其他部派律論所說的衣界有四種：一、「道行界」：《十誦律》說：「隨同師長、為師持衣在道路上行走，在前後四十九尋的範圍內都不算失衣。」《薩婆多論》說：「在縱橫四十九尋的範圍內都不算失衣。」二、「洲上界」：《善見律毗婆沙》說：「在水中沙洲上十四肘的範圍內不算失衣；如果有人往來經過，衣服就必須靠近自身，否則算失衣。」三、「水界」：《善見律毗婆沙》說：「比丘住在阿蘭若處，夜晚走入池水中沐浴，還未洗完就逢明相出現，這樣會犯捨墮罪。」《毗尼母論》說：「如果一隻腳踩在岸上、一隻腳踏入水中，即使經過明相出現，也不算失衣。」四、「井界」：《摩訶僧祇律》說：「在道路行走而露宿空地，睡在井欄旁邊時，如果衣服放在二十五肘之內，而自身在（此範圍）之外住宿，就算失衣；或者將衣服放在井裡面，而自身在井上方住宿，如果不以繩索相連，或者不垂下手腳（與井界相接），經過明相出現，都算犯戒。」《明了論》說：「在道路行走而夜間住宿，離去時錯拿了別人的衣服走，別人的衣服不算失，而是自己的衣服算失衣了。」", "i": "uBLIND-G01-3", "n": 262, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "畜寶戒，具四緣犯：一、是錢寶，二、知是，三、為己，四、受取，犯。", "t": "蓄積錢寶戒須具足四個條件才犯：一、是錢財珍寶；二、知道它是錢寶；三、為自己而蓄；四、接受取納，便犯。", "i": "uGAP15B-1", "n": 263, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "寶是八不淨財中一數。盛辨八不淨物名，通經論：一、是田宅，二、種植園林，三、畜積鹽粟，四、畜奴婢，五、養羣畜，六、貯金銀錢，七、為金銀鏤牀、錦褥、氍毹，八、銅鐵釜鑊。若畜此八，皆長貪壞道，汙染梵行，又得穢果，故名不淨。", "t": "錢寶是八不淨財中的一項。這裡廣泛辨明八不淨物，其名目通見於經、論之中：一、田地房宅；二、種植的園林；三、積蓄鹽與穀粟；四、畜養奴婢；五、飼養成群的牲畜；六、貯藏金銀錢財；七、造作金銀雕鏤的床、錦褥、氍毹；八、銅鐵製的釜鑊等鍋具。若蓄積這八類，都會增長貪欲、敗壞道業、污染梵行，又招得穢惡的果報，所以稱為「不淨」。", "i": "uGAP15B-2", "n": 264, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "次明開畜得否者：第一、田宅：一向無開，唯小房一口資身長道，別人開不犯。《五分》云：有人施僧田宅、店肆，佛言：「聽受，使淨人知。」", "t": "其次說明開許蓄積與否：\n第一，田地房宅：一概沒有開許，唯有一間小房，用來資養色身、長養道業，這是對個人開許的，不犯。《五分律》說：有人布施僧眾田地、房宅、店鋪，佛說：聽許接受，派淨人掌管。", "i": "uGAP15B-3", "n": 265, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第二、園池者：別人不許受。《見論》云：居士以池施僧，供給浣灌及眾生飲用，得受。", "t": "第二，園林水池：個人不許接受。《善見律毘婆沙》說：居士把水池布施給僧眾，供給洗滌、灌溉，以及眾生飲用，可以接受。", "i": "uGAP15B-4", "n": 266, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第三、畜積鹽粟者：《僧祇》云：若比丘糴時作是念：「此後時恐貴，今糴此粟，當依是得誦經、坐禪、行道」者，得。", "t": "第三，積蓄鹽與穀粟：《摩訶僧祇律》說：比丘買入穀米時若這樣想：「這穀米以後恐怕會漲價，我現在買下這些粟，依靠它得以誦經、坐禪、行道」——有這樣想法的，就開許。", "i": "uGAP15B-5", "n": 267, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "婆論》云：若比丘得穀米等，即日應作淨；若無白衣時，四眾邊作淨；若不作淨，至地了時作吉懺。", "t": "《薩婆多毘尼毘婆沙》說：比丘得到穀米等，當天就應作淨；如果沒有白衣在場，就在四眾面前作淨；若不作淨，到了天亮明相現時，就犯突吉羅罪，須懺悔。", "i": "uGAP15B-6", "n": 268, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第四、畜奴婢者：《僧祇》云：若人施僧供給女淨人，聽受；若施別人，一切不得；若施淨人為料理僧故，別人得受。", "t": "第四，畜養奴婢：《摩訶僧祇律》說：若有人布施給僧眾從事供役的女淨人，聽許接受；若布施給個人，一律不得接受；若布施淨人是為了替僧眾料理事務，個人可以接受。", "i": "uGAP15B-7", "n": 269, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第五、養羣畜者：《僧祇》云：一切眾生不應受。自餘野鳥獸等，若「不受者，我當殺之」，語言：「汝自求水草，守護勿令傷害。」不得剪翅羽籠繫；若能飛行自活者，放去莫拘縶之。", "t": "第五，飼養成群的牲畜：《摩訶僧祇律》說：一切眾生都不應接受。至於其餘的野鳥野獸等，若施主說「不接受的話，我就把牠們殺了」，就對他說：「你自己去給牠們找水草，守護牠們，不要讓牠們受到傷害。」不得剪去牠們的翅羽、把牠們關籠繫縛；若能飛行、自己謀生的，就放牠們走，不要拘禁繫縛牠們。", "i": "uGAP15B-8", "n": 270, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "日藏分經》云：佛言：「大王！於我法中，有諸比丘假令如法，始從一人乃至四人，我不聽受田宅、園林、象馬、奴婢等常住僧物；若滿五人，乃可得受。」", "t": "《日藏分經》說：佛說：「大王！在我的教法中有諸位比丘，即使他們如法，從一人乃至四人，我不聽許他們接受田宅、園林、象、馬、奴婢等作為常住僧物；如果僧眾滿五人，才可以接受。」", "i": "uGAP15B-9", "n": 271, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "遺教法律》云：騎乘車馬，一日除五百日齋福，一歲三百六十日乘，除十八萬日齋福。", "t": "《遺教法律經》說：騎乘車馬一天，就扣除五百日的齋福；一年三百六十天都騎乘，便扣除十八萬日的齋福。", "i": "uGAP15B-10", "n": 272, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "舍利弗問經》：何故比丘乘騎除五百日齋福者？佛言：「比丘知禁律人，他見生謗，令他得罪。」除老弱暫乘得。", "t": "《舍利弗問經》中問：為什麼比丘騎乘要扣除五百日的齋福？佛答：比丘是懂得禁律的人，別人見了會生起譏謗，使那些人得罪；除了年老、體弱者暫時騎乘，這才開許。", "i": "uGAP15B-11", "n": 273, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第六、畜金銀錢者：《僧祇》云：若居士施金銀為衣直，得受；不得自手取，使淨人知；無淨人者，指脚邊地語言：「是中知。」著地己，自用草葉、甎瓦等遙擲覆上，將人令知持去。若知佛有金銀欲舉者，若是生地，應教淨人知己，作坑內錢置中；若散落者，得自提甎瓦擲錢使入，得自填上。", "t": "第六，畜積金銀錢：《摩訶僧祇律》說：若居士布施金銀作為衣價，可以接受，但不得親手取，要讓淨人知情經手。若沒有淨人，就指著腳邊的地面，對施主說：「在此處掌領這錢。」等對方把金銀放在地上後，自己可以用草、葉、磚、瓦等遠遠地丟過去蓋住，之後帶淨人來，讓他知情，由淨人把錢拿走。掌管佛事的比丘若有金銀想要收藏時：如果是生地，應先教淨人知道，由淨人挖坑，再把錢放進坑中；若有錢散落在坑邊，可以自己拿磚瓦丟擲，把錢撥入坑裡，也可以自己把土填上。", "i": "uGAP15B-12", "n": 274, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》、《十誦》、《善見》云：若病兒得金銀錢，令淨人畜，為貿藥故；若多人與藥直，得置氈褥底，眼暗求時手觸無犯。", "t": "《僧祇律》《十誦律》《善見律毘婆沙》說：病人得到金銀錢，可以令淨人保管，因為要用來換藥的緣故；若許多人給藥錢，可以放在氈褥底下，在昏暗看不清時摸索尋找，手觸碰到，不犯。", "i": "uGAP15B-13", "n": 275, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第七、金銀鏤牀、錦褥、氍毹者：《母論》云：別人聽受刻鏤大牀，唯除金銀，不犯。此律：氍毹廣三肘、長五肘、毛長三指，聽受，應淨施畜。", "t": "第七，金銀雕鏤的床、錦褥、氍毹：《毘尼母論》說：個人可以接受雕鏤的大床，唯獨除去金銀裝飾才不犯。《四分律》說：氍毹寬三肘、長五肘、毛長三指的，聽許接受，但應先作淨施，然後才可畜存。", "i": "uGAP15B-14", "n": 276, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第八、銅鐵釜鑊者：《母論》云：瓦缾、銅盆、銅盔種種等器，佛聽別人得受。《是論》云：若施器，使僧應打壞，不得賣；若樂器，不得捉，得賣。", "t": "第八，銅鐵釜鑊：《毘尼母論》說：瓦瓶、銅盆、銅盔等種種器具，佛聽許個人接受。該論又說：若布施兵器給僧眾，僧眾應把它打壞，不得變賣；若是樂器，不得捉持，但可以變賣。", "i": "uGAP15B-15", "n": 277, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：若四月八日大會供養時，金銀塔及菩薩像、幢、供養具等有金銀塗者，使淨人捉；若倒地者，助捉無金銀處；若塗徧者，以物裹手捉，不得先提後放。", "t": "《僧祇律》說：四月八日大法會供養時，金銀塔、菩薩像、幢、供養具等，凡有金銀塗飾的，都讓淨人拿；若倒在地上，可以幫忙扶捉沒有金銀的地方；若整件都塗滿金銀，就用東西裹住手再拿；不得先提起後又放下。", "i": "uGAP15B-16", "n": 278, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：受寶物者，若身分乃至手脚、繫僧伽梨、鉢中，皆犯。", "t": "《僧祇律》又說：接受寶物時，不論是用手、腳等身體部位去接，乃至繫在僧伽梨上、放在缽中，都犯。", "i": "uGAP15B-17", "n": 279, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：若受金銀者，決定非我沙門釋子法。", "t": "《四分律》說：接受金銀的人，決定不合於我沙門釋子之法。", "i": "uGAP15B-18", "n": 280, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "五分》云：當知是人必定不信我之法律。", "t": "《五分律》說：應知此人必定不信我的法與律。", "i": "uGAP15B-19", "n": 281, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "貿寶戒，具五緣犯：一、是錢寶，二、相易，三、決價，四、為己，五、領受，便犯。此律：以財物易錢寶故犯，不論衣食也。此戒貿易便犯，不同販賣為利故，買以還賣故。得與白衣、淨人，不得與沙彌，以同犯故。", "t": "貿寶戒，具備五個條件就犯：一、所涉及的是錢財寶物；二、彼此互相交換；三、議定價錢；四、為了自己；五、領受到手，便犯。本律是因為拿財物去換取錢寶而犯，不論拿去換的財物是衣還是食。這條戒一經交易就犯，不同於販賣戒——販賣是為了求利而買進、再轉賣出去才犯。所貿得的錢寶可以給與白衣、淨人，不得給與沙彌，因為沙彌畜積錢寶也同樣犯戒的緣故。", "i": "u474", "n": 282, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "販賣戒。具六緣犯：一、在俗家人，二、共相交貿，三、決價，四、為己，五、自貿易，六、領受便犯。", "t": "販賣戒具備六個條件便構成犯戒：一、對象是在俗的在家眾；二、彼此互相交易；三、商定價格；四、為了自己；五、親自交易；六、領受所得之物，便構成犯戒。", "i": "uGAP16-1", "n": 283, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "十誦》云：若可捨物，食噉口口吉，作衣著，著提。若須是物，審思言：「我以爾所物買。」若彼不肯，更應再語；若復不肯，應三語索；不得者，覓淨人使買。淨人不知市易，當教「以爾所物買是物」，應好量議教買，得者無犯。若買得物，此賤彼貴，有利不犯。", "t": "《十誦律》說：「若是應當捨棄（尼薩耆）的物品，拿來食用，每吃一口犯突吉羅；做成衣服來穿，穿著時犯波逸提。如果確實需要這件物品，應仔細思量後說：『我用這麼多財物買這件東西。』如果對方不肯，應當再說一次；如果還是不肯，應當第三次索求；若仍得不到，就找淨人替自己去買。如果淨人不懂得市場交易，應當教他：『用這麼多財物買這件物品。』並且要好好地估量、商議之後再教他去買，這樣買得的，沒有犯戒。如果買得的物品，在此處便宜、在他處昂貴，從中有利潤，也不犯戒。」", "i": "uGAP16-2", "n": 284, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：市肆上衣，先有價定，比丘持價來買，置地時語言：「此直知是衣。」若不語默持去者，越毗尼罪。有國土買物常法，先有價定，齎直來著物邊，物主搖頭，當知與相，比丘亦應語言：「此直知是物。」前人若解，要須語己持去；若默持去者，越毗尼罪。若賈客物直五十而索百錢，比丘以五十知者，不犯。", "t": "《僧祇律》說：「市集店鋪上的衣服，事先已定好價格，比丘帶著錢來買，把錢放在地上時要說：『這些錢是買這件衣服的，請你知道。』如果不說話就默默拿走，犯越毗尼罪。有的地方買東西有一套慣例：事先定好價格，買方帶著錢來到貨物旁邊，物主搖頭，應當知道這就是同意給與的表示；比丘也應當說：『這些錢是買這件物品的，請你知道。』對方即使已經明白，也必須先開口說過〔己疑作已〕之後才可拿走；如果默默拿走，犯越毗尼罪。如果商人的貨物只值五十錢，卻索價一百錢，比丘只以五十錢的實值告知對方，不犯戒。」", "i": "uGAP16-3", "n": 285, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "十誦》云：若私賣買，前人悔取本物，七日內聽還；若過，不應。", "t": "《十誦律》說：「如果是私下買賣，對方反悔想要取回原物，七天之內准許歸還；如果超過七天，就不應歸還。」", "i": "uGAP16-4", "n": 286, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "婆論》云：若眾僧衣未三唱，得益價；若三唱已，不應悔；設悔，不應還。", "t": "《薩婆多論》說：「如果是眾僧的衣物，尚未唱價滿三遍前，可以加價競買；如果已經唱價滿三遍，就不應反悔，假使反悔，也不應退還。」", "i": "uGAP16-5", "n": 287, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "五分》云：使淨人易時，應心念：「寧使彼得我利，我不得彼利。」", "t": "《五分律》說：「差遣淨人前去交易時，應當心中默念：『寧可讓他從我這裡得到利益，也不要我從他那裡得到利益。』」", "i": "uGAP16-6", "n": 288, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "三千威儀》云：教人入市買物，有五事：一、當教莫與人諍，二、當教買淨者，三、莫使侵人，四、不得走促人，五、當護人意。", "t": "《三千威儀》說：「教人到市場買東西有五件事：一、應當教導他不要與人爭執；二、應當教導他買清淨如法的物品；三、不要讓他侵佔欺壓別人；四、不得奔走催促他人；五、應當顧護他人的心意。」", "i": "uGAP16-7", "n": 289, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "五百問事》云：有求利者販賣作福，此人尚不免地獄，何況得福？由不隨佛語故，非供養。請他食者，受人犯墮。窮厄無食處，彼應使白衣作食治生；尼白僧云：「是白衣物。」若爾，可食；二、三人亦白，得食；不白，犯墮。使人言「非我物」，亦可食。", "t": "《五百問事》說：「有貪求利益的人從事販賣，再拿所得去修福，這種人連地獄都免不了，更何況能得到福報呢？因為他不隨順佛陀的教誡，所以這根本不算供養。若拿這樣的食物請別人吃，接受飲食的人犯墮罪。在貧窮困厄、沒有食物的地方，那裡應當讓白衣（在家人）備辦飲食、經營生計；比丘尼向僧眾稟白說：『這是白衣的物品。』這樣便可以吃；只有兩三個人時，也同樣向他們稟白，就可以吃；不稟白就吃，犯墮罪。或者叫人說『這不是我的物品』〔非疑作是〕，也可以吃。」", "i": "uGAP16-8", "n": 290, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "婆論》云：此販賣戒，一切提中最重，寧作屠兒，不作販賣。何以故？屠兒止害一生，販賣者一切俱害，不問道俗、賢愚、持戒、毀戒，無往不欺，常懷惡心。設若居穀，恒希天下荒儉、霜雹災變；若居鹽及餘物，欲使四遠反亂、王路隔塞，故重於屠兒。此物作塔、作像，皆不得向禮。設與僧作食、若作僧房，持戒比丘不應食用，住中得罪；中問若死，得羯磨分。", "t": "《薩婆多論》說：「這條販賣戒在所有的波逸提罪中是最重的，寧可做屠夫，也不要從事販賣。為什麼呢？屠夫只傷害一條性命，販賣的人卻是傷害一切眾生，不論出家在俗、賢明愚昧、持戒破戒，沒有一處不去欺騙，心中總是懷著惡念。假使囤積穀物，便總是希望天下發生饑荒歉收、降下霜雹災變；如果囤積食鹽以及其他貨物，便希望四方遠處發生叛亂、官道交通阻斷。因此罪過比屠夫還重。用這種財物所建造的佛塔、所製作的佛像，一概不得向著它禮拜。假使拿來給僧眾做食物，或者建造僧房，持戒的比丘不應當食用，住在裡面也會得罪；如果在這期間〔中問疑作中間〕死了，就可以作羯磨法來分配這些財物。」", "i": "uGAP16-9", "n": 291, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：一切九十六種出家人邊，不諍語買，無罪。", "t": "《僧祇律》說：「在一切九十六種出家人那裡，只要不用爭價的言語購買物品，就沒有罪。」", "i": "uGAP16-10", "n": 292, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律雖許出家五眾互易，仍不得如市道法許價上下。", "t": "本律雖然允許出家五眾之間互相交換物品，但仍然不得像世俗市場買賣的做法那樣爭論價錢的高低〔許疑作諍〕。", "i": "uGAP16-11", "n": 293, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "迴僧物入己戒。具四緣：一、是通與僧物，二、許想，三、迴入己，四、入手便犯。此律云：僧物有三：一、已許僧物，謂通明僧物，未分僧別，此迴犯捨；二、未許僧物，迴入己無犯，何意得知？故律未許想尚得吉，故知未許還作未許想，何容得罪？三、已捨與僧，此定屬僧物，勸迴入已犯重。《五分》云：迴向餘人者，犯提；向餘僧、眾多人者，越；此彼畜生物迴者，越心悔。《見論》云：欲供養此像，迴與彼像，吉。此律：若許僧物迴與塔，許現前僧物迴與四方僧，許僧物迴與尼，並吉，故文言「許異處」也。若入塔，不應還取，即屬塔用，以福同故；乃至入尼亦爾。《十誦》、《婆論》云：若檀越施此自恣僧物，迴與彼自恣僧者，物應此分，其比丘作吉懺；若不還此僧，計錢犯重；乃至此彼一人物迴，亦重。《僧祇》云：尼眾乞供，乃至偏心曲受者，重；為眾乞物與餘眾眷屬者，重。此律：迴僧物者，還竟得互用罪。", "t": "迴僧物入己戒，須具足四緣才成犯：一、是通施給僧團的財物；二、作已許給僧團之想；三、轉施給自己；四、財物一到手便成犯。\n《四分律》說：僧物有三種。第一，已許給僧團的財物：指已泛泛表明是僧團的財物，尚未分別確定是歸僧團還是歸個人；迴轉這種財物，犯捨墮罪。第二，尚未許給僧團的財物：轉給自己，不犯。怎麼知道呢？因為律中說：財物尚未許僧，卻作已許想，尚且只犯突吉羅；由此可知，財物本未許、又如實作未許想時，哪裡會得罪呢？第三，已捨施給僧團的財物：這已確定屬於僧團，若勸施主轉施給自己，犯重罪。\n《五分律》說：把已許給僧團的財物轉給其他個人，犯波逸提；轉給其他由四人以上組成的僧團，或僅由二、三人組成的眾多人，犯突吉羅罪。把許給這隻畜生的財物轉給那隻畜生，犯突吉羅罪，須責心懺悔。\n《善見論》說：本想供養這尊佛像，卻把供物轉給那尊佛像，犯突吉羅罪。\n《四分律》說：把已許給僧團的財物轉給佛塔，把已許給現前僧的財物轉給四方僧，把已許給比丘僧的財物轉給尼眾，都犯突吉羅罪。所以律文說「許異處」，即已許給此處卻轉給別處。財物若已入塔，就不應再取回，即歸塔所用，因為福田相同的緣故；乃至已入尼眾的財物，也是一樣。\n《十誦律》與《薩婆多論》說：若施主布施給這一處自恣僧的財物，被轉給另一處自恣僧，財物應仍由這一處僧眾分配，那位比丘須作突吉羅懺悔；若不歸還給這一處僧眾，按財物價值計錢，犯重罪。乃至把這一人的財物轉給另一人，也同樣犯重罪。\n《僧祇律》說：比丘尼為僧眾乞求供養，乃至以偏私之心違背施主本意、不正而收受歸己的，犯重罪；為僧眾乞得的財物，卻轉給其他僧眾或眷屬的，犯重罪。\n《四分律》說：迴轉僧物的人，歸還之後，仍得互用之罪。", "i": "u475", "n": 294, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "乞蘇油戒。具五緣犯：一、是非親里居士，二、當前索蘇，三、不用重還，四、更索異物，五、得異物入手便犯。義云：若乞蘇，得無提舍尼罪？罪由食生，既不食還主，可有罪耶？蓋有患及四開緣——長請、更請、盡形請、聽乞醫藥，無直乞之愆；若有直乞罪時，何須結彼互索之過。", "t": "乞酥油戒具備五個條件便犯捨墮：一、對方是非親屬的居士；二、先前已向他索求酥；三、沒有食用而把酥歸還施主；四、又改索其他物品；五、得到所改索的物品，一入手便犯。\n《義鈔》說：若只是乞求酥而得到，是不是就沒有提舍尼罪呢？罪是由食用才產生的；既然沒有食用就把酥歸還施主，哪裡會有罪呢？這是因為有患病，以及長請、更請、盡形請、聽許乞求醫藥這四種開緣，所以沒有直接乞求的過失；如果直接乞求本身就有罪，又何必另外結定那互索（先索此物、退還後改索他物）的過失呢？", "i": "u476", "n": 295, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "迴現前僧食直作五衣戒。具緣可解。若居士虗心施作食，或自乞得食直，迴異用，皆犯過。", "t": "把現前僧眾的飲食錢挪去縫製五衣這一戒，所具的犯戒條件不難理解。如果是居士誠心布施、要拿來備辦飲食的錢，或是比丘尼自行為僧乞求所得的飲食錢，卻把它迴轉挪作別的用途，都犯戒有過失。", "i": "u477", "n": 296, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "畜長鉢戒。具五緣犯：一、先有受持鉢，二、更得器，三、不說淨，四、無顛狂等因緣，五、過明相便犯。十六枚器者：大釜、釜蓋、大盆、大杓、小釜、釜蓋、小盆及杓、水缾、缾蓋、貯水大盆及杓、洗缾、缾蓋、小盆及杓，總有二釜、四盆、二缾、杓四、四蓋，合有十六；過長不說淨，並犯捨墮。《母論》云：十六枚中各畜長者，即日施人及施尼。", "t": "畜長缽戒具備五個條件便犯：一、原本已有受持的缽；二、又得到其他器具；三、沒有作說淨；四、沒有癲狂等開緣；五、超過十日限期，天亮明相出現時便犯。\n所謂十六枚器，是指：大釜即大鍋、釜蓋、大盆、大杓即大勺；小釜、釜蓋、小盆和杓；水瓶、瓶蓋、貯水的大盆和杓；洗瓶、瓶蓋、小盆和杓。總共有兩口釜、四個盆、兩個瓶、四把杓、四個蓋，合計十六枚。超過長畜期限而不說淨的，都犯捨墮罪。《毘尼母論》說：十六枚器中，每一種若畜有多餘的，應當日就布施給他人，以及布施給其他比丘尼。", "i": "u478", "n": 297, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "貿衣已後強奪戒。具五緣犯：一、共相貿易，二、決價直，三、相當，四、瞋心強奪，五、得物便犯。《十誦》云：尼共大僧貿衣竟，還悔者，尼薩耆。《僧祇》云：尼棄故僧伽棃，有人捨取補治，還奪，犯捨墮；自餘小雜物，捨與他人還奪者，越。", "t": "「貿衣已後強奪戒」，即與人交換衣服之後又強行奪回，須具足五個條件才構成犯戒：一、雙方互相貿易交換；二、已議定價值；三、所交換的物品價值相當；四、以瞋恨心強行奪回；五、奪得物品，便犯。\n《十誦律》說：比丘尼與比丘交換衣服完畢後，又反悔、要求換回原衣的，犯尼薩耆罪，即捨墮罪。\n《摩訶僧祇律》說：比丘尼丟棄舊的僧伽梨大衣，有人撿去縫補整治，她又強行奪回的，犯捨墮罪。其餘小件雜物，捨給他人後又強行奪回的，犯越毗尼罪。", "i": "u479", "n": 298, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第四篇一百七十八波逸提者，今簡要釋一百一。", "t": "第四篇（波逸提篇）共一百七十八條，現在簡要解釋其中的一百零一條。", "i": "u480", "n": 299, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "小妄語戒。具六緣犯：一、是人，二、作人想，三、違想說，四、知違想，五、言了，六、聞解便犯。《婆論》云：妄語、兩舌、惡口，相歷作四句：一、是妄語，非兩舌、惡口，傳他此語向彼說，以不實故名妄語，以無分離心故非兩舌，輭語說故非惡口；餘句類上，有無可知。《成實論》云：餘口三業，或合或離；綺語一種，必不相離。《婆論》云：不妄語者，若說法、議論、傳語一切是非，莫自稱為是，常令推寄有本，則無過也；不爾，是斧有口中。此律：若僧說戒時，三問，憶念有罪而不說，吉；若異說者，前人不解；若顛倒說；若發大聲不了；若有所說，前人不解，並犯。《十誦》云：若語高姓云「是下姓」，提；若語兩眼人云「汝是一眼人」，得妄語提，又輕惱比丘故提；語一眼人云「汝是瞎眼人」，得惱他提。", "t": "小妄語戒須具足六個條件才成犯：一、對方是人；二、自己認定對方是人；三、說出違背內心認知的話；四、明知這話違背自己的認知；五、話已說完；六、對方聽見並且理解了，便成犯。\n《婆論》說：妄語、兩舌、惡口三者互相交錯配對，可作成四句分別。第一句是「是妄語而不是兩舌、惡口」：把這邊這人的話傳到那邊向人說，因為內容不實，所以名為妄語；因為沒有要使雙方分離的心，所以不是兩舌；因為是用柔軟語說出，所以不是惡口。其餘各句比照上面類推，是有是無便可明白。《成實論》說：其餘三種口業或合併而起、或單獨而起，唯獨綺語這一種，必定與其餘口業不相分離。\n《婆論》又說：所謂不妄語，就是不論說法、議論、替人傳話，凡涉及一切是非，都不可自稱自己所說為對，總要讓所說的話推歸依託於有所根據的來源，這樣就沒有過失；不這樣，就如同口中含著一把斧頭。\n《四分律》說：僧眾說戒、三次詢問時，憶念到自己有罪卻不說出來，犯突吉羅。若改用別的語音說法而使對方不能理解、或顛倒錯亂地說、或發出大聲卻說不清楚、或凡有所說而對方不能理解，這些都同樣犯罪。\n《十誦律》說：對高種姓的人說他是低種姓，犯波逸提。對雙眼完好的人說「你是一隻眼的人」，得妄語波逸提；又因輕慢惱亂比丘的緣故，另犯一個波逸提。對只有一隻眼的人說「你是瞎眼的人」，得惱他波逸提。", "i": "u481", "n": 300, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "惡罵戒。具六緣犯：一、是比丘尼（《十誦》、《五分》：罵下三眾吉），二、自毀呰語（《伽論》云：傳他語罵吉），三、知是毀呰，四、作折辱彼意，五、言了，六、前人聞知便犯。此律云：種類毀呰語者，卑姓家生，行業亦卑，技術工巧亦卑；若言「汝是犯過人」，依實亦犯。《僧祇》云：若以上惡法毀尼及父母，言「汝父母是」者，提；「汝和尚、闍棃是」，蘭；「汝同友是」，越毗尼。《成實論》云：雖是實語，以非時故，即得綺語。", "t": "惡罵戒，具足六個條件便結犯：一、所罵的對象是比丘尼（《十誦律》《五分律》說：辱罵下三眾，只犯突吉羅）；二、自己親口說出毀辱貶斥的話（《伽論》說：轉述他人的話去辱罵，犯突吉羅）；三、自己知道所說的是毀辱貶斥之語；四、懷著折挫羞辱對方的心意；五、話已說完；六、對方聽到並明白所說的意思，便結犯。\n《四分律》說：所謂「種類毀呰語」，就是說對方出生在卑賤的種姓之家，說他所從事的行業也卑下，說他的技術工巧也卑下；或說「你是犯過戒的人」——縱使所說符合事實，也同樣結犯。\n《僧祇律》說：若用上述惡事毀辱比丘尼以及她的父母——說「你父母就是這類人」，犯波逸提；說「你的和尚、阿闍梨是這類人」，犯偷蘭遮；說「你的同伴道友是這類人」，犯越毗尼罪。\n《成實論》說：雖然說的是真實的話，但因為不合時宜而說，就構成綺語。", "i": "u482", "n": 301, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "兩舌戒。具六緣犯：一、是尼，二、說鄙惡事，三、知是惡事，四、傳於彼此，五、言了，六、聞知便犯。此律：兩舌者，彼此鬬亂令他破也。《僧祇》云：以惡法告言：「某甲說汝是。」無有上、中、下法，欲令他離向己，若彼離不離，皆提。《婆論》云：說已更說，提；若不傳此語，兩邊令離散者，一切皆吉。", "t": "兩舌戒具足六個條件便成犯：一、對象是比丘尼；二、所說的是鄙劣惡穢之事；三、自己知道所說的是鄙惡之事；四、在彼此雙方之間傳述；五、話說得清楚明白；六、對方聽聞並了解意思，就構成犯罪。《四分律》說：所謂兩舌，就是在彼此之間挑撥鬪亂，使雙方破裂。《僧祇律》說：用惡劣的言語告訴對方：「某甲說你沒有上、中、下任何一品的法。」想使對方疏離某甲而歸向自己；不論對方是否因此離散，都犯波逸提。《薩婆多論》說：說過之後又再說，犯波逸提；若不是互相傳述彼此的話，只是自己在兩邊說話而使雙方離散，一切都只犯突吉羅。", "i": "u483", "n": 302, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共男子同室宿戒。具五緣犯：一、是男子，二、室相成，三、共同宿，四、知同室宿，五、隨轉側便犯。此律：室相有四：一、四周有障，上亦有覆；二、前敞無壁；三、雖覆而不徧；四、雖覆徧而有開處。此之四室，尼共男子同宿，無問先、後、具至，但隨脇轉側，一一皆提。若共畜生、黃門、二根人等宿，吉。比丘尼晝日臥，男子立者，吉；男子若坐，便犯屏坐提。《婆論》云：若都集堂同障內，設使堂中有諸小房，雖各各別，以室同故，猶是一房；若多房共一戶，亦犯。覆者，乃至以衣縵作屋；壁者，乃至高一肘半，共宿，皆犯。若共十男子同宿，十提；隨一一起更臥，一一得十提；隨一一轉側，得十提。若白衣舍有男子，並房不閉戶，吉。", "t": "與男子同室共宿戒，具備五項成犯條件：一、對方是男子；二、室相成立；三、共同宿臥；四、知道同室共宿；五、隨著身體轉側，便構成犯戒。本律所說的室相有四種：一、四周有遮障，上方也有覆蓋；二、前方敞開而沒有牆壁；三、雖有覆蓋而不周遍；四、雖覆蓋周遍而有開口處。在這四種房室中，比丘尼與男子共同宿臥，不論哪一方先到、後到，或雙方一同到達，只要隨著脅部轉側，每一次都犯波逸提。若是與畜生、黃門、二根人等共同宿臥，犯突吉羅。比丘尼白天躺臥而男子站立時，犯突吉羅；男子若是坐下，便犯屏坐波逸提。《婆論》說：「若在集會堂的同一遮障之內，即使堂中有許多小房間，雖然各自分隔，因為同屬一室的緣故，仍然算作一間房；若多個房間共用同一個門戶，也犯戒。覆蓋方面，甚至是以衣物布幔搭成屋舍；牆壁方面，甚至只高一肘半，在內共同宿臥都犯戒。比丘尼若與十名男子共同宿臥，犯十個波逸提；自己每起身再躺臥一次，每一次都得十個波逸提；每轉側一次，也得十個波逸提。若在俗人的房舍中，有男子住在相鄰房間，而比丘尼不關上房門，犯突吉羅。」", "i": "u484", "n": 303, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共未受具人同宿過三夜戒。具五緣犯：一、是未受具人（男女），二、室相成，三、共同宿，四、知同宿，五、過三夜犯。《伽論》云：已二夜共沙彌尼宿，第三夜共男子宿，得二提。《僧祇》云：三夜犯竟，若未懺悔，後共宿者，轉增長罪，更無二夜開；悔過已，當別房宿，後更得二夜也。此律：若更無宿處，至第三夜明相未出前，遣沙彌、白衣出，或自出護明相，亦得；至第四宿，若自去、若使彼去，更無開法。", "t": "與未受具足戒的人同室住宿超過三夜戒，具足五緣便犯：一、對方是未受具足戒的人，不論男女；二、所宿之處室相成立，構成同一房間；三、彼此共同住宿；四、明知是同室共宿；五、超過三夜，便犯。\n《伽論》說：已經和沙彌尼同宿了兩夜，第三夜又和男子同宿，得兩個波逸提罪。\n《僧祇律》說：三夜期滿犯了罪之後，如果還沒有懺悔，之後又繼續同宿，罪便輾轉增長，不再有兩夜的開許；懺悔完畢後，應當改到別的房間住宿，此後才重新獲得兩夜的開許。\n本律說：如果再也沒有別的住宿處所，那麼到第三夜、天亮明相還未出現之前，打發沙彌或白衣出去，或者自己出去，趕在明相出現之前避開而護持不犯，這樣也可以。若到了第四夜，就必須自己離去，或叫對方離去，再也沒有開許繼續同宿的辦法了。", "i": "u485", "n": 304, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與未受具人同誦戒。具五緣犯：一、佛所說法，二、字句味，三、未受具人，四、齊聲誦，五、言說了便犯。《婆論》云：若同聲句齊者，提；聲齊句異者，吉。", "t": "「與未受具足戒的人同誦」這條戒，具備五個條件就成犯：一、所誦的是佛所說的法；二、所誦的是字、句、味；三、對方是未受具足戒的人；四、彼此齊聲同誦；五、誦說的言詞了了分明，便犯。\n《婆論》說：如果彼此同聲、所誦的句子也齊同，犯波逸提；若只是聲音齊同而所誦的句子不同，則犯突吉羅。", "i": "u486", "n": 305, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "向未受具說他人麤罪戒。具七緣犯：一、是比丘及尼，二、犯初二篇罪，三、知，四、無僧法開，五、向未受具人，六、言詞了，七、前人知解便犯。《五分》云：尼向白衣說比丘汎爾小過，提。《婆論》云：寧破塔壞像，不說他人麤罪；若說，則破法身。不問前人有罪無罪，說者皆提。此律云：若說名字，若種姓，若相貌，若衣服，若房舍，及自說己罪，皆提。", "t": "向未受具足戒的人說他人粗重罪這一條戒，具備七個條件就犯：一、被說罪的人是比丘或比丘尼；二、他所犯的是初篇波羅夷與第二篇僧殘的罪；三、自己明知他犯了這樣的粗重罪；四、沒有僧團羯磨法的開許；五、向未受具足戒的人說；六、言詞說得完整明白；七、對方聽懂了解，就犯波逸提。\n《五分律》說：比丘尼向在家人說比丘尋常的小過失，犯波逸提。《薩婆多論》說：寧可毀壞佛塔、破壞佛像，也不說他人的粗重罪；若說了，就是破壞法身。不論那個人實際上是有罪還是無罪，說的人都犯波逸提。《四分律》說：說出犯者的名字、種姓、相貌、衣服或房舍，以及向未受具足戒的人說自己所犯的罪，都犯波逸提。", "i": "u487", "n": 306, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與男子說法過五六語戒。具六緣犯：一、是人（男子），二、知是，三、不請，四、無有智俗女人，五、言章了，六、過五六語便犯。此律：請者聽齊五六語；若他不請說，隨義多少皆提。五語者，謂「色、受、想、行、識無我」也；六語者，謂「眼、耳、鼻、舌、身、意無常」也；更增一句使犯。《僧祇》云：說六句已，語云「使汝速盡若」，得提。《婆論》云：有智女人者，要解人情語，可作證明，無犯；若為小男說者，吉。《僧祇》云：若盲、若聾，亦名無人；一盲、一聾，此二人當一人；若眠，亦名無人；若為父、兄弟說者，亦犯。《五分》云：若自誦經，男子來聽，或問要義，為解，過者不犯。", "t": "與男子說法過五六語戒，具足六個條件就犯：一、對方是人趣的男子；二、明知對方是人趣男子；三、對方並沒有請求說法；四、現場沒有有智慧的在家女人；五、所說的語句已經清楚地說完；六、超過五語、六語，便犯。《四分律》說：若是對方請求而說，允許說到五、六語為限；若對方沒有請求就說，不論所說義理多少，都犯波逸提。所謂「五語」，是指說色無我、受無我、想無我、行無我、識無我；所謂「六語」，是指說眼無常、耳無常、鼻無常、舌無常、身無常、意無常。若再多加一句，就犯。《僧祇律》說：說完六句之後，又說一句「使你速盡苦惱」，就得波逸提。《婆論》說：所謂有智女人，必須能聽懂人情的言語、可以充當見證，有這樣的人在場就不犯；若對年幼的男孩說超過五六語，犯突吉羅。《僧祇律》說：若那有智女人是盲者或是聾者，也叫做「無人」；一人盲、一人聾，這兩個人合起來算作一人；若是睡著的人，也叫做「無人」；即使為自己的父親、兄弟說，超過五六語也一樣犯。《五分律》說：若是自己誦經，有男子前來聽；或是男子請問法要而為他解說，這樣超過五六語也不犯。", "i": "u488", "n": 307, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "掘地戒。具五緣犯：一、是生地，二、作生地想，三、自掘，四、使人掘時不作知淨語，五、傷如蚊脚便犯。此律：但使教人不作知淨，不問現前不現前，掘掘皆提。若自方便掘，一提；若中間止住，一一提。若使前人多掘，一提；若重語「疾疾掘」，語語提。《僧祗》云：走來走去欲令地壞，乃至擲物令傷如蚊脚者，一切提；釘房內壁損傷人功者，得越毗尼罪；先有孔者，不犯；地有沙石者，不犯。《見論》云：若野火來近寺，為護住處，得剗草掘地以斷火；若把火燒手，擲地不犯。《僧祇》云：覆處地不犯。", "t": "掘地戒具備五個條件就犯：一、所掘的是生地；二、對它作生地想；三、自己動手掘；四、教人掘時不說「汝知是」一類的知淨語；五、地面受損，傷痕哪怕只有蚊子腳那樣細小，便犯波逸提。\n《四分律》說：只要是教人去掘而不說知淨語，不論是當面教或不在當場教，每掘一下都犯波逸提。自己動手掘，一連掘下只犯一個波逸提；若中間停住、之後再掘，就一一各犯一個波逸提。若使喚他人去掘，那人掘了許多下，只犯一個波逸提；若一再催促說「疾疾掘」，也就是快掘、快掘，則每說一句各犯一個波逸提。\n《僧祇律》說：走來走去想讓地面損壞，乃至丟擲物品，使地面傷如蚊子腳那般細小，一切都犯波逸提。在房內把釘子釘入牆壁，損壞了人工修成的壁面，得越毘尼罪，即突吉羅；若原先已有舊孔，就不犯。地裡有沙石的，掘了不犯。\n《善見論》說：若野火燒近寺院，為了保護住處，可以割草、掘地來截斷火勢；若手裡拿的火燒到手，把火扔在地上，也不犯。《僧祇律》說：屋舍覆蓋之處的地，掘了不犯。", "i": "u489", "n": 308, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "壞生種子戒。具五緣犯：一、是五生種，二、作生種想，三、自壞，四、不作知淨語，五、傷物便犯。", "t": "壞生種子戒，具備五種因緣便犯戒：一、確屬五種生種；二、心裡作生種想；三、親自損壞；四、不說知淨語；五、傷損到該物，這樣就犯戒。", "i": "uGAP17-1", "n": 309, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：生種有五：一、根，二、枝，三、節，四、覆羅，五、子子種；淨法亦有五：一、火，二、刀，三、瘡，四、鳥破，五、不中種。", "t": "本律所說的生種有五種：一、根種，二、枝種，三、節種，四、覆羅種，五、子子種。作淨的方法也有五種：一、火，二、刀，三、瘡傷，四、鳥啄破，五、不堪作種子。", "i": "uGAP17-2", "n": 310, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧祇》云：根、莖種者，以刀中破淨；節種者，以刀破或以摘去芽目淨；心種者，如蘿勤、蓼等是，應揉𫝽淨；子種者，如穀、麥等是，脫皮淨；若總用火淨，便通上五種。", "t": "《摩訶僧祇律》說：根種與莖種，用刀從中間破開來作淨；節種，用刀破開，或者摘去芽眼來作淨；心種，像蘿勤〔疑作勒〕、蓼草等就是這類，應當用雙手揉搓作淨；子種，像稻穀、麥子等就是這類，脫去外皮作淨；如果統統用火作淨，上述這五種都可以通用。", "i": "uGAP17-3", "n": 311, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "五果中，裹核種者，如棗、杏等是，應掐破淨，得去核食，火淨者得合核食；膚果種者，如蓽茇、棃、柰等是，皆須火淨，若一切熟果自然落下，觸木石傷如蚊脚者，成淨，應去子食；殻果種者，椰子、胡桃、石榴等是，皆須火淨；𥢶果種者，如香葇、蘇、荏等是，無子應揉𫝽淨，有子應火淨；角果種子，如大、小豆是，子未成應揉𫝽淨，子成應火淨。", "t": "在五種果實中，裹核種，像棗、杏等就是這類，應當掐破作淨，可以去掉果核再吃；若是經過火淨的，就可以連核一起吃。膚果種，像蓽茇、梨、柰等就是這類，都必須用火作淨；如果是一切成熟的果實，自然從樹上掉落，碰撞到樹木或石頭而損傷有如蚊子腳大小，這就成淨，應當去掉種子再吃。殼果種，椰子、胡桃、石榴等就是這類，都必須用火作淨。𥢶果種，像香葇、蘇、荏等就是這類，沒有結子時應當揉搓作淨，有子時應當用火作淨。角果種子，像大豆、小豆就是這類，種子還沒長成時應當揉搓作淨，種子長成後應當用火作淨。", "i": "uGAP17-4", "n": 312, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "摩摩帝有穀倉未淨，畏年少尼不知法，應使人火淨，乃至後時恒言「舂去」，不犯。", "t": "摩摩帝遇到穀倉裡的穀物還沒作淨，擔心年少的比丘尼不懂律法，應當派人用火作淨，這樣直到日後經常說「拿去舂」，都不會犯戒。", "i": "uGAP17-5", "n": 313, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若以五生種擲著池中、井水中、大小便中、糞掃中，越毗尼罪；死者，提。草木中行，欲使死者，越毗尼罪；傷如蚊子脚，提。石上生衣、餅上生毛，皆須淨人知，不爾犯罪；若日乾，得剝却。", "t": "如果把五種生種丟進池塘中、井水中、大小便中或垃圾堆裡，犯越毗尼罪；如果導致生種死亡，犯波逸提罪。在草木叢中行走，存心想踩死草木，犯越毗尼罪；如果使草木受傷有如蚊子腳大小，犯波逸提罪。石頭上長出青苔、餅上長出黴毛，都必須讓淨人知淨處理，否則就會犯戒；如果經太陽曬乾了，就可以自己剝除。", "i": "uGAP17-6", "n": 314, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "水中浮萍，不得手撥，有牛、馬行處，得取水用；若無行處，捉土塊若石，仰擲，言：「至梵天上去！」若下時打水開處，即得用；水中翻覆浮萍，越毗尼罪；若著岸上，提。若入水洗時，水草著身者，以水復澆令入水。若斷朝菌，越毗尼罪。", "t": "水中的浮萍，不可以用手撥開；如果有牛馬走過而分開的地方，可以從那裡取水使用；如果沒有牛馬走過的地方，就拿土塊或石頭朝天上拋擲，口中說「到梵天上去」，等它落下時打中水面而讓浮萍散開的地方，就可以取水使用。如果在水中翻動傾覆浮萍，犯越毗尼罪；如果將浮萍撈到岸上，犯波逸提罪。如果下水洗浴時，有水草黏在身上，應當再用水澆淋，讓水草回到水中。如果折斷朝菌，犯越毗尼罪。", "i": "uGAP17-7", "n": 315, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "見論》云：若須華果，得自攀枝下，使淨人取；亦得抱淨人取。", "t": "《善見論》說：如果需要花果，可以自己把樹枝拉下來讓淨人採摘，也可以抱起淨人讓他採摘。", "i": "uGAP17-8", "n": 316, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "五分》云：凡諸草木，若有所須，語淨人言：「汝知是。」若不解，復語言：「汝看是。」若不解，復語言：「我須是。」", "t": "《五分律》說：凡是各種草木，如果有需要用到的，就對淨人說：「你知曉這個。」如果對方不明白，再對他說：「你看著這個。」如果對方還不明白，再對他說：「我需要這個。」", "i": "uGAP17-9", "n": 317, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "此律：不言「看是」，吉；壞地亦然。草生覆道，徧繫開路，枝折葉落者，無犯，以不故為也。", "t": "依本律，若不說「看是」這樣的淨語，犯突吉羅罪；損壞土地的情形也是一樣。若雜草生長覆蓋了道路，把草撥繫到一旁以開出道路，因而造成枝折葉落的，不算犯戒，因為並不是故意去折損草木的。", "i": "uGAP17-10", "n": 318, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "露處敷僧臥具戒。具六緣犯：一、是四方僧牀，二、知，三、是露處，四、自敷、使人敷，五、去不自舉、不使人舉，六、出門便犯。《五分》：以不坐臥而不舉，佛言亦提；若白衣家借僧臥具，食訖不舉，亦提；若知事人暴曬僧臥具，在邊若坐禪、若眠者，吉。《僧祇》云：若僧牀上安像，比丘禮拜，手觸不舉者，亦提；若多人禮拜，悉皆手觸，屬最後者。此律：出門犯。", "t": "在露天處鋪敷僧眾臥具戒，具足六個條件便成犯：一、所敷的是屬於四方僧眾的床；二、明知那是僧眾之物；三、地點是在露天處；四、自己鋪敷，或教人鋪敷；五、離去時不自己收舉，也不教人收舉；六、一走出門外，就犯波逸提。\n《五分律》說：因為自己沒有在上面坐過、臥過，就不收舉臥具，佛說這樣也犯波逸提。若在白衣（在家居士）家中借用僧眾的臥具，用齋完畢後不收舉，也犯波逸提。若是知事人曝曬僧眾的臥具，有人在旁邊坐禪或睡覺，離去時不收舉，犯突吉羅。\n《僧祇律》說：如果在僧眾的床上安放佛像，比丘禮拜時用手觸碰了床，事後卻不收舉，也犯波逸提；如果多人禮拜，人人都用手觸碰過，就歸最後那一人負責收舉。本律（《四分律》）則是走出門外便結犯。", "i": "u490", "n": 319, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "屏處敷僧臥具戒。具六緣犯：一、是僧物，二、知僧物，三、屏處，四、為己用，五、不自舉、不教人舉，六、或出界或過三夜便犯。", "t": "屏處敷僧臥具戒：具備六個條件就犯戒。第一，是僧團的物品；第二，知道它是僧物；第三，在屏處，即屋內等有遮蓋的地方；第四，是為了自己使用；第五，自己不收拾，也不教別人收拾；第六，或者走出住處界外，或者過了三夜，便犯戒。", "i": "u491", "n": 320, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "強敷僧臥具惱他戒。具五緣犯：一、先借得住處安上已定，二、知他先住，三、作惱亂彼意，四、強於中間敷，五、隨坐臥便犯。《十誦》云：若為惱他故，開戶、閑戶、開響、閉響、然火、然燈、呪詛、續經、說法，隨他不樂，皆提。", "t": "強行鋪敷僧眾臥具惱亂他人戒，具足五個條件便犯：一、他人先前已借得住處，並已安頓停當；二、明知對方是先住的人；三、生起惱亂對方的意念；四、硬是在他中間鋪敷臥具；五、隨著坐下去或臥下去，便犯。《十誦律》說：若為了惱亂他人而開門關門、開也弄得作響關也弄得作響、生火點燈、詛咒、不斷誦經、說法，凡是隨對方所不樂意的事去做，都犯波逸提。", "i": "u492", "n": 321, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "用蟲水戒。具四緣犯：一、是蟲水，二、知有蟲，三、不作漉法，四、隨所用便犯。《僧祇》云：若蟲細者，應作三重漉囊；猶有蟲者，更別造井；諦視有蟲者，應捨所住處去。若用蟲水方便澆者，一息一提，隨息多少皆提；若使人澆，一語一提；若使人疾疾澆，語語提。蟲生無常，或先有今無，或先無今有，是故日日諦看，無蟲便用。", "t": "用蟲水戒，具足四個條件就成犯：一、所用的水裡有蟲；二、明知水裡有蟲；三、沒有依律作漉水過濾之法；四、隨著任何一種使用方式，一用就犯。《摩訶僧祇律》說：如果蟲身細小，應當製作三重的漉水囊來過濾；過濾之後仍然有蟲的，就另外開鑿新井；若仔細察看新井的水仍舊有蟲，就應當捨棄這個住處離去。若是自己起方便、親手用有蟲的水澆灌，每停息一次、之後再澆，就結一個波逸提罪，隨著停息的次數有多少，都各結波逸提。若是教別人去澆，每吩咐一句就結一個波逸提；若催促對方「快快澆、快快澆」，那麼每說一句就各結一個波逸提。蟲的滋生沒有定準，有時先前有蟲、現在卻沒有了，有時先前沒有蟲、現在卻生出來了，因此每天都必須仔細察看，確定沒有蟲才可以使用。", "i": "u493", "n": 322, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "別眾食戒。具七緣犯：一、是有施主，二、僧次請及別請、別乞，三、五正食在時中，四、食處成眾，五、知界內有比丘尼不集，六、無因緣，七、咽咽犯提。此律：無問道俗，皆成施主。《見論》云：要別請四人俱受，成眾；即座上一人覆鉢不食，待餘三人食竟，一人後食，不犯，故知俱受成眾。此律云：若二、三人隨意食；四人已上，應分作二部，更互入食。《婆論》云：若大界內有二處僧祇，一日中俱有檀越食，布薩處無過；不布薩處，不請布薩處一人、不送一分食者，此僧犯提。此律：病者不犯，下至脚跟躄故不犯。《見論》云：謂沙土入中，不能行也。", "t": "別眾食戒，具足七個條件就犯：一、有施主。二、食物由僧次請、別請或別乞而得，即依僧團次序受請、施主特別指定邀請，或不依僧次而另行乞食。三、是五種正食，而且是在明相出至正午的時中食用。四、進食之處形成四人以上的眾。五、知道界內還有比丘尼沒有集合同食。六、沒有開許的因緣。七、每吞一口，就犯一個波逸提。《四分律》中，不論出家人或在家人，都能成為施主。《善見論》說：必須是別請的四個人一同受食，才構成「眾」。座上有一人把缽倒扣著不受食，等其餘三人吃完後，這一人才吃，就不犯。由此可知，要四人一同受食才構成眾。《四分律》說：若是二、三人，可以隨意進食；四人以上，就應分成兩部，輪流進去進食。《婆論》說：若一個大界內有兩處僧眾住處，同一天都有檀越供食，在布薩處的那一眾沒有過失；不在布薩處的那一眾，若不請布薩處的一人來同食、也不送一分食給布薩處，這一處的僧眾就犯波逸提。《四分律》說：生病的人不犯，乃至下至腳跟破裂這樣的病也不犯。《善見論》解釋說：這是指沙土進入腳跟裂口中，以致不能行走。", "i": "u494", "n": 323, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "非時食戒。具四緣犯：一、是非時，二、非時想，三、時食，四、咽咽便犯。此律云：「時」者，明相出，乃至日中，按此時為法，四天下亦爾。《毗羅三昧經》云：佛為法慧菩薩說食四種：旦起，天食時；午時，法食時；暮時，畜生食時；夜，鬼神食時。後二種食，多生病疾；其出家人，應作天食、法食，故曰「時食」；過午已後，非上二時，故曰「非時」。《見論》云：吐食未出咽喉，還咽無犯；若出咽者，提。《十誦》云：阿那律弟子病，服吐下藥，中後心悶。佛言：「稻稗、竹笋汁，囊盛米粥絞汁與。」猶不差，佛聽屏處食米粥。食殘宿食戒。具三緣犯：一、是殘宿食，二、知是，三、咽便犯。此律：今日受食，自貯界內，留至明日，自煑食者，咽咽得七罪，謂三提、四吉：一、不受，二、非時，三、殘宿，四、內煑，五、內宿，六、自煑，七、惡觸。", "t": "非時食戒，具足四緣就成犯：一、確實是非時；二、心中作非時想；三、所吃的是「時食」，即只許在時內吃的食物；四、每吞下一口就犯一次波逸提。《四分律》說：所謂「時」，是從明相出現、天色破曉起，一直到正午；就以這段時間為準則，四大洲也都各自如此。《毗羅三昧經》說：佛為法慧菩薩開示進食的四種時間——清晨是諸天進食之時，中午是法食之時，傍晚是畜生進食之時，夜裡是鬼神進食之時。在後兩種時間進食，多會招致病痛；出家人應當依照天食、法食這兩時而食，所以稱為「時食」；過了正午以後，已不屬於上面這兩種時，所以稱為「非時」。《善見論》說：吐出的食物若還沒有出咽喉，再吞回去，不犯；若已經出了咽喉又吞下去，就犯波逸提。《十誦律》說：阿那律的弟子生病，服了催吐與瀉下的藥，過了中午之後心中悶亂，佛說：可給他喝稻、稗、竹筍的汁，或用布袋裝米粥絞出汁來給他喝；這樣仍不見好，佛便聽許他在屏蔽隱密處吃米粥。\n食殘宿食戒，具足三緣就成犯：一、是殘宿食，即經過一夜的食物；二、明知是殘宿食；三、一吞嚥就犯波逸提。本律說：今天接受的食物，自己貯放在結界範圍內，留到第二天又自己煮來吃的人，每吞一口就得七種罪，也就是三個波逸提、四個突吉羅：一是不受食，二是非時食，三是殘宿食，四是內煮，五是內宿，六是自煮，七是惡觸。", "i": "u495", "n": 324, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不受食戒。具緣可解。《見論》云：天、人、鬼神、畜生、飛鳥皆成受食。《婆論》云：為作證明故，非人、畜生及無知小兒悉不成受。此律：除水及楊枝，不須受。《僧祇》云：若風吹塵、午駝振身塵來，乃至眾鳥、女人行衣曳地塵來，如是一切塵坌鉢下草，不坌食者，成；若及食者，一切更須受；唯畜生振身作意受者，得；自餘一切不作意受者，應更從他受。若行麨時，抖擻麨器迸落鉢中，作意者得名為受，不作意者不名為受；餘食亦爾。《五分》云：眼暗比丘得按萆受食。《見論》云：額汗流入鉢，更須受；臂中汗流入手，不須受，得食無罪。《十誦》云：行食時，淨人觸比丘手，若特輕故觸比丘手，不應受。《婆論》云：手不淨受食，犯吉。《僧祇》云：淨人行果菜時，應語云「懸空放」；果墮草上即去，不名為受；小停者，得為受。《見論》云：遙擲從地轉來落比丘上，成受。《僧祇》云：大會時淨人難得，比丘受取行之；若鎗鑊。", "t": "不受食戒的成犯條件，容易明白。《善見論》說：天、人、鬼神、畜生、飛鳥，從他們受食都能成立。《薩婆多論》說：因為授受食物是要作為證明的緣故，所以非人、畜生以及無知的小兒，全都不能成就受食。依本律，除了水和楊枝不必受之外，其餘都須受食。《僧祇律》說：不論是風吹來的塵土、牛與駱駝抖動身體揚起的塵土，乃至眾鳥揚起的塵土、女人行走時衣裙拖地揚起的塵土，這一切塵土只落在缽下的草上、沒有落到食物上的，受食仍然成立；如果沾及食物，就一切都須重新受。唯有畜生抖動身體揚塵這一種，比丘作意受取的，就算得受；其餘一切情形，沒有作意受取的，應重新從他人受食。又如分送炒熟的穀粉時，抖動盛粉的器具，使粉迸散落進缽中，作意受取的就名為受，不作意的就不名為受；其餘食物也是這樣。《五分律》說：眼睛昏花的比丘，可以用手按住草葉來受食。《善見論》說：額頭的汗流進缽裡，就須重新受食；手臂上的汗流到手上，則不必重受，吃那食物無罪。《十誦律》說：行食時淨人碰到比丘的手；若是輕慢比丘而故意去碰比丘的手，那食物就不應接受。《薩婆多論》說：手不乾淨而受食，犯突吉羅。《僧祇律》說：淨人分送水果、蔬菜時，應告訴他：「懸空放」。果子落到草上隨即滾走的，不名為受；稍作停留的，才算成就受食。《善見論》說：從遠處擲來、沿著地面滾過來而落到比丘手上的食物，也成就受食。《僧祇律》說：大集會時淨人難得，比丘可以自己受取食物後，拿去巡行分送；若是鍋釜……", "i": "u496", "n": 325, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不得受者，當下以兩木橫置地，比丘脚躡上，言「受，受」，得成。此律下文：欲受油，錯受蘇等，不成受，必令心境相當，得成受。此律：受食已有三失：一、任運失，謂受得已，食時既過，故云任運失也；二、遇緣失，謂淨人觸失受也；三、自變生為熟失也。《見論》云：受生薑後，生芽，不失受；火淨已，生芽處更淨，非生芽處得食；鹽變成水，得食。", "t": "若鍋釜無法受取，就在地上橫放兩根木頭，比丘用腳踩在木頭上，口中說「受、受」，這樣受食便成立。《四分律》下文說：本想受油，卻錯受成酥等，這不算成受；必須心裡所想的與實際所受的食物相符，受食才成立。依《四分律》，受食之後有三種失去受法的情形：一是任運失，就是受食以後，聽許進食的時間已經過去，受法自然失效，所以稱為任運失。二是遇緣失，就是被淨人碰觸而失去受法。三是食物自己由生變熟，因而失去受法。《善見論》說：受了生薑之後，生薑長出芽來，並不失去受法；已用火燒觸作過火淨的，長芽的部位要再作一次淨，沒有長芽的部位可以吃；鹽化成水，也可以吃。", "i": "u497", "n": 326, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共俗男子屏坐戒。具四緣犯：一、是俗男子，二、屏處坐，三、無第三人，四、伸手不及戶處坐便犯。《僧祇》云：若母、姉妹、淨人等睡眠、癡狂、心亂、嬰兒、非人、畜生，雖有是人，亦名為獨。竟日坐，一提；中間更起，一一提。若淨人作務來往不斷，門向道中有人行如食頃不斷，若閣上、閣下淨人遙見者，並不犯。此律：若舒手及戶坐，使乞食尼見，若二尼為伴，若有識別人在邊，及有難緣等，並不犯。", "t": "「與世俗男子在屏隱處共坐」這條戒，具足四個條件便成犯：一是對方為世俗男子；二是在屏隱處共坐；三是沒有第三人在場；四是坐在伸出手也搆不到門戶的地方。\n《僧祇律》說：即使有母親、姊妹、淨人等在場，但若他們正在睡眠，或在場的是癡狂心亂的人、嬰兒，乃至是非人、畜生，雖然有這些人在，仍然算是獨處。整天坐著，犯一條波逸提；中途若起身後又再坐下，隨每一次坐，各犯一條波逸提。若淨人正在做事，來來往往沒有間斷；或門朝著道路，路上有人行走，約一頓飯那麼久的時間都不間斷；或樓上、樓下的淨人遠遠能看見——這些情況都不犯。\n《四分律》說：若坐在伸手就搆得到門戶的地方，讓來乞食的比丘尼能看見；或有兩位比丘尼作伴；或旁邊有能辨識事理的人；以及遇到危難等因緣——都不犯。", "i": "u498", "n": 327, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共男子露坐戒。具四緣犯：一、是俗男子，二、露處坐，三、無第三人，四、伸手內共坐便犯。《十誦》云：與男子露地坐，隨起還坐，隨得爾數提；相去半尋，提；相去一尋半，吉；二尋若過，無犯。", "t": "與男子在露處共坐戒：具足四個條件便犯——一是對方為俗家男子，二是在露天無遮蔽的地方坐，三是沒有第三人在場，四是兩人在伸手可及的範圍內共坐，這樣就犯。《十誦律》說：比丘尼與男子在露地共坐，起身之後又再坐下，每起已還坐一次，她本人就犯一個波逸提罪；起坐幾次，就累計犯幾個波逸提罪。兩人相距半尋，犯波逸提；相距一尋半，犯突吉羅；相距二尋或超過二尋，就不犯。", "i": "u499", "n": 328, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "觀軍陣戒。具四緣犯：一、是軍陣，二、故往，三、無因緣，四、往見使犯。《僧祇》云：若入聚落城邑，道中逢軍陣，不作意見，無犯；若作意舉頭、下頭窺望欲使見者，提。《十誦》云：若軍陣發行為鬬，彼賊殺死，因觀無常故，不犯。《婆論》云：道由中過，無犯；若立住看，犯；左右反顧，壞威儀故，吉羅。", "t": "觀軍陣戒具足四緣便成犯：一、所對的確實是軍隊陣列；二、故意前往；三、沒有開許的因緣；四、前往而且見到了，就犯。\n《僧祇律》說：比丘尼進入村落、城邑，途中遇到軍隊陣列，不是存心去看而見到的，無犯；若是存心抬頭低頭、窺伺張望，想要見到而見到了，就犯波逸提。\n《十誦律》說：若軍隊開拔出動去交戰，那些賊人被殺死，比丘尼藉此觀察無常而觀看，不犯。\n《薩婆多毘尼毘婆沙》說：若道路從軍陣中間穿過，只是循路經過，無犯；若停下站著觀看，就犯波逸提；至於左右回頭張望，則因破壞威儀的緣故，犯突吉羅。", "i": "u500", "n": 329, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "飲酒戒。具三緣犯：一、是酒，二、無重病緣，三、飲便犯。此律：體雖是酒，而非酒色、非酒香、非酒味，不應飲；體非是酒，然有酒色、酒香、酒味，得飲。若飲甜味酒、若飲酸味酒、若食酒糟、若食麴等，並吉羅。「自今已去，以我為師者，乃至不得以草木頭內酒中滴入口。」餘藥治不差，以酒為藥者，不犯。《五百問事》云：若醫師言必差，得和藥服，不得空服。強勸人，不飲吉，飲提。《婆論》云：此戒極重，能作四逆，唯除破僧，又能破一切戒及餘眾惡故。", "t": "飲酒戒具備三個條件便成犯：一、是酒；二、沒有重病的因緣；三、一飲下就犯。本律說：本體雖然是酒，卻沒有酒的顏色、沒有酒的氣味、沒有酒的味道，仍然不應飲；本體不是酒，卻有酒的顏色、酒的氣味、酒的味道，可以飲。若飲甜味的酒、飲酸味的酒、吃酒糟、吃酒麴等，都犯突吉羅。從今以後，凡是尊我為師的人，乃至不得把草尖或木枝的末端浸入酒中，再滴入口裡。用其他藥物治療而病不痊癒，以酒作為藥用的，不犯。《五百問事》說：如果醫師說必定能治好，可以把酒摻和藥物服用，不得未與藥摻和而純飲酒。強行勸人飲酒，對方不飲，勸的人犯突吉羅；對方飲了，勸的人犯波逸提。《薩婆多論》說：這條戒極為嚴重，因為飲酒能使人造作四種逆罪，只有破和合僧除外；又能使人毀破一切戒，以及造作其餘種種惡業。", "i": "u501", "n": 330, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "水中嬉戲戒。具三緣犯：一、是水，二、無因緣，三、入水便犯。此律：戲者，放意自恣，或以手畵水相澆，乃至以鉢盛水弄，一切皆提；除水，弄餘苦酒等，吉。《僧祇》云：水陸互澆灒，越；俱水中者，提。《五分》：持雪乃至草頭露弄者，吉。此律：若道行渡水者，不犯。", "t": "水中嬉戲戒，具備三個條件便成犯：第一，是水；第二，沒有正當因緣；第三，一進入水中便成犯。《四分律》說：所謂「戲」，就是放縱心意、任意嬉玩，或者用手在水中劃撥、彼此潑水相濺，乃至用缽盛了水來玩弄，這一切都得波逸提罪。除了水以外，玩弄醋等其他液體，得突吉羅罪。《僧祇律》說：一人在水中、一人在陸地上，這樣互相潑水濺灑，得越毘尼罪；如果雙方都在水中，就得波逸提罪。《五分律》說：拿雪來玩弄，乃至玩弄草尖上的露水，都得突吉羅罪。《四分律》說：如果是行路途中要渡水而下水的，不犯。", "i": "u502", "n": 331, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "擊攊他戒。具四緣犯：一、是比丘尼，二、作惱意，三、手脚十指，四、觸著便犯。《僧祇》云：以指指比丘亦提，五指指五提，乃至差會指某甲去者亦提。《五分》云：若擊攊沙彌、畜生等，亦吉。此律：若以餘物擊攊者，吉；若不故作意，或睡眠令覺，不犯。", "t": "「擊攊他戒」，即以指搔癢逗弄他人之戒，須具足四緣才成犯：一、對方是比丘尼；二、懷著惱亂對方的心意；三、用的是手腳十指，即手指與腳趾；四、一觸著對方便犯。《僧祇律》說：用手指指向比丘，也犯波逸提；用五根手指去指，隨指結五個波逸提；乃至在差派赴會時，指著某人說「某甲，你去」，也犯波逸提。《五分律》說：若搔癢逗弄沙彌、畜生等，也犯突吉羅。本《四分律》說：若用其餘物件搔癢逗弄，犯突吉羅；若不是故意這麼作，或是為了叫醒睡著的人而碰觸他，都不犯。", "i": "u503", "n": 332, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不受諫戒。具五緣犯：一、自作非法事，二、他如法諫，三、知己所作非、前人諫者是，四、拒諫不受，五、隨所作犯根本，違諫得提。此諫作犯，雖發言拒諫，未是作犯，要待作事，違諫義成，故得提罪。此戒最益，制欲犯者，恐有業行之過，不可一一集僧而諫，故令一人處處行諫，違便得罪。《婆論》云：前諫人有六種不應從：一、心有愛憎，二、若鈍根無智，三、若少聞見，四、為利養名聞，五、為現法樂、但欲自攝，六、若新出家、愛戀妻子；如是六人，諫則有損。", "t": "不受諫戒，具備五個條件就犯：一、自己作不合律法的事；二、他人依律如法地勸諫；三、自己明知所作的事不對，而現前這位勸諫的人所說的是對的；四、抗拒勸諫而不接受；五、仍舊去做那件事，犯了該事的根本罪，如此違抗勸諫，就得波逸提。這一戒所勸諫的是實際去作而犯的「作犯」，所以雖然開口說出拒絕勸諫的話，還不算構成作犯；必須等到真的去作了那件事，「違諫」的意義才算成立，因此才得波逸提罪。這條戒最有利益，是用來制止那些將要犯戒的人：恐怕他們造業行事而有過失，卻又不可能一一都集合僧眾來作法勸諫，所以就讓一個人隨處進行勸諫，違抗勸諫便結罪。《薩婆多毘尼毘婆沙》說：前來勸諫的人有六種，不應聽從：一、內心懷有偏愛偏憎的；二、根性遲鈍而沒有智慧的；三、見聞淺少的；四、為了利養與名聲的；五、為求現世安樂、只想攝持自身的；六、剛出家而仍貪戀妻子兒女的。這六種人的勸諫，聽從了反而有害。", "i": "u504", "n": 333, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "恐怖尼戒。具五緣犯：一、是比丘尼，二、作恐彼意，三、以六塵等事示說，四、現相言了，五、見聞便犯，不待前怖與不怖。", "t": "恐怖比丘尼戒，須具足五緣才成犯：一、對方是比丘尼；二、存有要使她恐怖的心意；三、用六塵等事來示現或言說；四、所示現的相狀已經顯現、所說的話也說得清楚明白；五、對方見到或聽到，便成犯，不必論她實際上恐怖或不恐怖。", "i": "u505", "n": 334, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "減半月洗浴戒。具五緣犯：一、曾前洗浴，二、未滿半月，三、無因緣，四、更洗浴，五、洗過半身便犯。《僧祇》云：隨數滿十五日，皆名半月。此律：六緣不犯：一、熱時者，春後四十五日、夏初一月亦得；二、病時者，下至身體臭穢；三、作時者，下至掃屋前地；四、風時者，下至一旋風；五、雨時者，下至一滴雨著身；六、道行時者，下至半由旬來往；皆開不犯。《五分》云：共白衣浴室中浴者，偷蘭遮。露地然火戒。具四緣犯：一、是露地，二、無因緣，三、然草木有𦦨者，四、然便犯。《僧祇》云：旋火作輪，或火中有草木，比丘撥聚，一切皆犯；若然生種，二提：一、壞生，二、然火。《五分》云：雲𦦨高四指。此律：若病須火便身，得自然、教人，不犯。", "t": "減半月洗浴戒，具足五個條件便成犯：一是先前曾經洗浴過；二是距上次洗浴還不滿半月；三是沒有開許的因緣；四是又再洗浴；五是洗超過半個身體，便成犯。《僧祇律》說：不論從哪一天起算，只要數滿十五天，都叫做「半月」。《四分律》中有六種情況不犯：一是熱時，指春季後段的四十五天，夏季的第一個月也算在內。二是病時，即使只是身體臭穢，也算病時。三是作務時，即使只是打掃屋前的地面，也算。四是颳風時，即使只有一陣旋風，也算。五是下雨時，即使只有一滴雨落到身上，也算。六是行路時，即使只走了半由旬的路，不論是去或是回，都開許不犯。《五分律》說：與在家人同在一間浴室裡洗浴身體，犯偷蘭遮。\n露地然火戒，具足四個條件便成犯：一是處在露天的地方；二是沒有開許的因緣；三是所點燃的是草木之類會起火焰的東西；四是一點燃便成犯。《僧祇律》說：把火揮旋成輪狀，或火堆中有草木而比丘去撥弄、聚攏它們，這一切都犯。若所燃的是有生機的草木，就得兩個波逸提：一是壞生，二是然火。《五分律》說：火焰高達四指即成犯。《四分律》中說：若有病，需要火來使身體安適，可以自己燃火，也可以教人燃，不犯。", "i": "u506", "n": 335, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "藏他衣鉢戒。具三緣犯：一、比丘尼衣鉢，二、驚動彼意，三、取藏便犯。此律：不犯者，若在露地，恐風雨漂漬舉之；若物主為性慢墮，衣物狼藉，為誡勒藏，不犯。", "t": "藏匿他人衣缽這條戒，具足三個條件就構成犯戒：一、所藏的是比丘尼的衣和缽；二、心裡存著要使她驚慌著急的意圖；三、把衣缽取走藏起來，便犯戒。《四分律》所說不犯的情形是：衣缽放在露天空地上，怕被風吹走、被雨淋濕浸泡，而把它收起來；或者物主生性怠慢懶惰，衣物散亂四處狼藉，為了告誡督促她而替她收起藏放——這些都不犯。", "i": "u507", "n": 336, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "著白色衣戒。具四緣犯：一、是五衣，二、是己物，三、不染壞，四、著便犯。", "t": "「著白色衣戒」：具備四項條件就犯：一、是五衣之一；二、是自己的衣物；三、沒有染成壞色；四、一穿上就犯。", "i": "u508", "n": 337, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "故斷畜生命戒。具五緣犯：一、是畜，二、知是，三、有殺心，四、起方便，五、命斷便犯。", "t": "故意斷絕畜生生命的這條戒，須具足五個條件才成犯：一、對方是畜生；二、明知牠是畜生；三、存有殺害的心；四、發起殺害的行動手段；五、牠的生命一斷絕，便成犯。", "i": "u509", "n": 338, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "飲蟲水戒。具五緣犯：一、是蟲水，二、作蟲想，三、不作漉法，四、飲用，五、隨咽得提。《僧祇》云：比丘受具已，要畜漉囊、應法澡罐，無者用袈裟角漉；同伴中都無者，舉眾有罪。《十誦》云：不持漉袋行二十里，犯罪。《僧祇》云：若漉水得已，使能見掌中細文者看，看時如大象載竹車迴頃，知無，應用。若施主請比丘食，應問：「漉水未？」若自看漉，或使可信人教漉；否者自漉，不得語，莫殺傷；蟲水著器中，還送水來處；來處遠，近有池七日不消者，以蟲著中。若知水有蟲者，不得持器繩借人。若池汪水有蟲，不得唱云「此水有蟲」；若問者，答云「長老自看」；若知友同師者，語云：「此中有蟲，當漉用。", "t": "飲蟲水戒，須具足五個條件才構成犯戒：一、確實是有蟲的水；二、心裡認為水中有蟲；三、沒有依漉水法過濾；四、喝飲或使用；五、每吞嚥一口，即得一波逸提罪。\n《僧祇律》說：比丘受具足戒之後，必須蓄備漉水囊和如法的盛水澡罐；沒有漉水囊的，就用袈裟的一角來過濾。同行同伴中若全都沒有漉水用具，整個同伴眾都有罪。\n《十誦律》說：不攜帶漉水袋行走二十里，便犯罪。\n《僧祇律》又說：水過濾好之後，要讓能看清手掌中細紋的人來察看；察看的時間，大約如大象拉著竹車轉身迴轉一圈所需的那麼久，確認沒有蟲，才可使用。若有施主請比丘吃飯，應先問：「水過濾了沒有？」若施主自己察看、過濾，或叫可信賴的人來過濾，那就可以；若施主沒有這樣做，比丘就自己過濾，但不得說「不要殺傷蟲」這類的話。把濾出的蟲連水盛在容器裡，送回原來取水的地方；若取水處遙遠，而附近有七天之內不會乾涸的水池，就把蟲放進池中。若知道水中有蟲，不得把盛水的容器和繩索借給別人。若池塘或積水窪裡有蟲，不得揚聲宣說「這水有蟲」；若有人問起，就回答「長老，請自己察看」；若是知交好友或同師的同伴，就告訴他「這裡面有蟲，應當過濾後再用」。", "i": "u510", "n": 339, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與賊期同道行戒。具六緣犯：一、是賊，二、知是，三、是與期，四、同一道行，五、不離見聞處，六、越界便犯。與負債人同行，越毗尼罪。", "t": "與賊約定同道而行戒，具足六緣便犯：一、對方確實是賊；二、明知對方是賊；三、與賊作了同行的約定；四、與賊走同一條道路；五、彼此不離開眼見耳聞所及的範圍；六、越過界畔，就犯此戒。若是與負債的人同行，則犯越毗尼罪。", "i": "u511", "n": 340, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "拒勸學戒。具五緣犯：一、作止不學意，二、前人如法勸學，三、知已作非、前人諫者是，四、作不受勸意，五、言了便犯。", "t": "拒勸學戒，須具足五個條件才成犯：一、生起「就此停住、不再學習」的心意；二、對方依律如法地勸他學習；三、明知自己所作的有過失，而對方的勸諫是對的；四、生起不接受勸諫的心意；五、拒絕的話一說完，便成犯。", "i": "u512", "n": 341, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "毀毗尼戒。具五緣犯：一、是毗尼，二、前比丘尼誦戒時，三、作滅法意不令久住，四、發言毀呰，五、言了便犯。《僧祇》云：僧未說戒時訶，越；說時訶，提；說已訶，越心悔。《五分》云：發心作念令人遠離毗尼，不誦而毀呰，提；若作念木叉令不久住，蘭。此律：若毀阿毗曇、契經等，犯吉。不攝耳聽戒。具四緣犯：一、是廣誦戒時，二、在眾中坐，三、作不聽意，四、說過五篇犯一提。《僧祇》云：從序至篇，吉；隨中間戒，一一吉；一切不聽，止一提。此提不得向人悔，當於眾中持戒、威德敬難者前悔，前人應訶治。同羯磨賞知事後悔謗僧戒。此希，故不述具緣。《婆論》云：凡僧和合，若執苦人、大德及貧匱人，和合賞已，訶者，提；若外來訶者，吉。", "t": "毀呰毗尼戒，具足五個條件便犯：一是所毀呰的對象確實是毗尼；二是面前的比丘尼正在誦戒的時候；三是懷著滅除戒法的心意，不願讓戒法久住於世；四是開口說出毀謗譏嫌的話；五是話一說完就犯。《僧祇律》說：僧眾還沒開始說戒時加以譏訶，犯越毗尼罪；正在說戒時譏訶，犯波逸提；說戒結束後才譏訶，犯越毗尼罪，須責心懺悔。《五分律》說：起心動念要使他人遠離毗尼、不誦毗尼，因而加以毀呰，犯波逸提；若起念要使波羅提木叉不能久住於世，犯偷蘭遮。依《四分律》，若毀呰阿毗曇、契經等，犯突吉羅。\n不攝耳聽戒，具足四個條件便犯：一是正當廣誦戒本的時候；二是自己坐在說戒的大眾之中；三是心裡存著不聽的意圖；四是說戒已誦過五篇，便犯一條波逸提。《僧祇律》說：從戒序到篇首標目這一段不聽，犯突吉羅；中間隨每一條戒不聽，一一各犯突吉羅；整部都不聽，只犯一條波逸提。這一條波逸提不得向單獨一人懺悔，應當在大眾之中，於持戒、有威德、為眾敬重畏服的人面前懺悔；接受懺悔的那個人應當訶責治罰他。\n同作羯磨賞知事人、事後反悔謗僧戒：這種情形稀少，所以不敘述它的犯緣。《婆論》說：凡是僧眾和合，不論是為僧執勞苦辦事的人、大德，或是貧乏不足的人，大眾和合賞與之後，同預其事的人事後又加以訶責的，犯波逸提；若是外來的人訶責，犯突吉羅。", "i": "u513", "n": 342, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "屏聽四諍戒。希故不述其緣。《僧祇》云：若聞他怨欲相殺害，或聞賊來，非法比丘尼惡計欲偷僧物，知事人聞，即白僧言：「當自警備，我聞惡聲。」若師日暮竊來按行諸房，聞弟子說法語，不得對面讚毀，後時得若來，然後歎責。此律：二人在暗地語，若在道行共語，應先彈指、謦欬，否者吉羅。", "t": "關於屏處偷聽四種諍事的戒，由於這種情形稀少，就不敘述它的成犯諸緣了。《摩訶僧祇律》說：如果聽到他人心懷怨嫌、想要互相殺害，或聽到有盜賊要來，或聽到行非法的比丘尼心懷惡計、想要偷取僧團財物，知事人一聽到這些，就應立即稟白大眾說：「大家應當各自警戒防備，我聽到了不善的言談。」如果師父在傍晚時悄悄前來巡視各房，聽到弟子們講說佛法的話語，不得當場面對面地稱讚或指責，要等到日後見面時，才可以稱歎或責備。《四分律》說：若有兩人在暗處談話，或兩人在路上同行交談，走近的人應當先彈指或咳嗽出聲，讓他們察覺；不這樣做，就犯突吉羅。", "i": "u514", "n": 343, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "瞋心打比丘尼戒。具四緣犯：一、是比丘尼，二、生瞋心，三、作打意，四、打著便犯。《十誦》云：一把沙豆散眾多比丘，隨著一一提。《伽論》云：瞋心、欲心打女人，殘。《大集經》云：若道俗等打破戒比丘，罪重出萬億佛身血；何以故？能示人出要道乃至涅槃故。《僧祇》云：若畜生入寺，觸突塔舍、形像、壞華果樹等，得以杖打木石鳴地等恐怖令去，不得杖擬畜生。", "t": "懷瞋恨心毆打比丘尼這條戒，須具足四緣才成犯：一、對方是比丘尼；二、生起瞋恨心；三、存有要打的意思；四、打到對方身上，便犯。\n《十誦律》說：抓一把沙、豆撒向眾多比丘，隨著沙豆所打中的人，一一各結一波逸提。《薩婆多部毘尼摩得勒伽》說：以瞋恨心或淫欲心打女人，得僧殘罪。《大集經》說：無論出家、在家等人，若毆打破戒比丘，所犯的罪比使萬億佛的身體出血還要重。為什麼呢？因為破戒比丘仍能為人指示出離生死的要道，乃至涅槃之道。《摩訶僧祇律》說：若有畜生跑進寺院，衝撞佛塔、房舍、佛像，或損壞花樹、果樹等，可以用杖敲打木頭、石頭，或敲擊地面作聲等方式，使牠驚怕而離去；但不可拿杖對著畜生作勢要打。", "i": "u515", "n": 344, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "搏比丘尼戒。具緣可辨。《伽論》云：若舉手刀向眾多比丘，一一提。", "t": "舉手作勢擬打比丘尼戒：構成犯戒的諸緣可以辨明。《摩得勒伽論》說：若把手掌側立如刀舉起，朝向眾多比丘作勢要打，對所向的每一位，各犯一個波逸提。", "i": "u516", "n": 345, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "捉遺落寶戒。具五緣犯：一、是重寶（通及自他），二、并諸莊飾具，三、非住處及宿處，四、無心盜取、擬還本主，五、捉著便犯。", "t": "「捉遺落寶戒」須具足五個條件才成犯：一、是貴重的寶物，自己的、他人的都通攝在內；二、各種莊嚴飾具也一併在內；三、拾得之處不在僧伽藍內，也不是寄宿之處；四、沒有盜取之心，打算歸還原主；五、手一捉到便成犯。", "i": "u517", "n": 346, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《婆論》云：因拾遺寶為緣起，正犯但明捉寶便犯。此律：供養塔寺莊嚴具，堅固收舉不犯。", "t": "《薩婆多論》說：這條戒是以拾取遺落的寶物為制戒緣起，但正式的犯相只明「捉寶便犯」。《四分律》說：供養塔寺的莊嚴飾具，為了堅牢不失而收取保管，不犯。", "i": "u517-2", "n": 347, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《僧祇》云：若見遺物者，當唱令之；無主者，應懸著高顯處令人見。若人言「是我物」，應問言：「汝物何處失？」答相應者與；若無識者，應停至三月已，若塔園中得者，即作塔用，僧園中得者，作四方僧用。", "t": "《僧祇律》說：若見到他人遺落的物品，應當公開唱告招領；無人認領的，應懸掛在高而顯眼的地方，讓人看見。若有人說「這是我的東西」，應問他：「你的東西在哪裡遺失的？」回答相符的才交給他。若無人認得，應保留到滿三個月；在塔園中拾得的，就作佛塔之用；在僧園中拾得的，就作四方僧之用。", "i": "u517-3", "n": 348, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若貴價物者、瓔珞金銀，不得露現唱令；得寶比丘應審數諦看有何相貌，然後舉之，來認時相應者與，對眾多人與，不得屏處還，教授三歸，語言：「佛不制戒者，汝眼看不得。」若無人來認者，停至三年，如前處當界用之。", "t": "若是貴價之物，如瓔珞、金銀，不得公開展示著唱告招領；拾得寶物的比丘應仔細清點、詳看它有什麼特徵相貌，然後收藏起來。有人來認領時，所述相符的才給他，而且要當著眾多人的面交還，不得在隱蔽處歸還；並教他受三歸依，對他說：「若不是佛制了這條戒，你連親眼見到它都不可能了。」若一直無人來認領，就保留到滿三年，之後依前面所說的方式，就在拾得之處所屬的界內使用。", "i": "u517-4", "n": 349, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若治故塔掘地得寶藏者，淨人不可信者，當白王知；淨人可信者，停至二年已，應作塔用。若王覺，問比丘言：「汝此中有寶藏耶？」答言：「得已，用作此塔。」王言：「已作者止，此功德屬我，在者還我。」", "t": "若修整舊塔，掘地得到埋藏的寶藏：淨人不可信賴的，應稟白國王讓他知道；淨人可信賴的，保留滿二年之後，應作佛塔之用。若國王察覺了，問比丘說：「你們這裡有寶藏嗎？」比丘答說：「已經得到，並且用來修這座塔了。」國王說：「已經用掉的就罷了，這份功德歸我；還剩下的，還給我。」", "i": "u517-5", "n": 350, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "若王言：「汝不知地中寶藏屬我耶？」問：「何以用？盡還我來！」比丘應以塔物還；若塔無物，應為塔乞還。若王問言：「佛戒中云何？」比丘答言：「塔地得物，即在塔用；僧地亦然。」王言：「從佛、僧用，無罪。」", "t": "若國王說：「你難道不知道地中的寶藏屬於我嗎？」並責問為什麼擅自使用他的寶藏，要比丘全部交還，連已用掉的也要一併歸還，比丘就應用塔的財物償還；若塔沒有財物，應為塔乞化財物來償還。若國王問：「佛的戒律中怎麼說？」比丘答說：「在塔地上得到的物品，就用在塔上；僧地上得到的也一樣。」國王說：「那就依佛所制，供佛塔與僧眾使用，沒有罪。」", "i": "u517-6", "n": 351, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《僧祇》云：入聚落中有遺落物，不得取；有人取與比丘者，得，即是施主。聚落中風吹衣，不得作糞掃衣想取；若曠路無人處，得取，若衣有寶，以脚躡斷，露捉使人見；至住處始見有寶者，與淨人掌，作衣藥價直。", "t": "《僧祇律》又說：進入聚落中，有他人遺落的物品，不得拾取；若有人拾取了拿來給比丘，則可以接受，那人就是施主。聚落中被風吹來的衣服，不得當作糞掃衣而拾取；若在空曠無人的道路上，則可以拾取。若衣上有寶物，要用腳踩踏使寶物與衣分離，再公開拿著衣讓人看見；若回到住處才發現有寶物，就交給淨人掌管，折算成衣、藥的價值使用。", "i": "u517-7", "n": 352, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《五分》云：若比丘寄衣，經十二年不還，欲取者，集僧評價，作四方僧用；若彼後還，以僧物償，不受者善。", "t": "《五分律》說：若有比丘寄存的衣，經過十二年本人仍不回來領取，想要取用的人，應集合僧眾評定它的價值，作四方僧之用。若那位比丘後來回來了，就用僧物償還他；若他不肯接受，那很好。", "i": "u517-8", "n": 353, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "非時入聚落戒。具五緣犯：一、非時分，二、無啟白、喚緣，三、不囑授，四、向俗人舍，五、入門便犯。《十誦》云：若蘭若處，白比丘來入聚落，還至蘭若處，即以先白入聚落者，提；若白入聚落，從聚落出至本僧坊，還入聚落，即以先白入，提。同一界善比丘，不白入，提。不白比丘，隨所經過大巷、小巷，得爾所吉羅；隨入白衣家，隨一一提。若入蘭若、近聚落僧坊，不白，無罪。《婆論》云：若總白入聚落，後到隨意所至處，無犯。《僧祇》云：若多人道行，欲入聚落，展轉相白，然後當入；已到宿處，復欲出外取薪、草木者，若從本道出者，無犯，若更從餘道出者，不白，提。《智度論》云：一切白衣舍，皆名聚落。《見論》云：有市名聚落，無市名村界。此律：若有啟白、請喚、路由聚落過，無犯。", "t": "非時入聚落戒，具足五個條件便成犯：一、時分屬於非時；二、沒有自己有事須前往稟白告知，或是他人召喚、邀請的因緣；三、沒有事先向同住的比丘尼囑授交代；四、所前往的是俗人的房舍；五、一進門就結犯。《十誦律》說：在阿蘭若處已向比丘作白而來入聚落，之後又回到阿蘭若處，若仍憑先前那一次作白再入聚落，犯波逸提。若已作白而入聚落，從聚落出來回到原本的僧坊，又要再入聚落，仍憑先前的作白而入，犯波逸提。同一界內有清淨如法的比丘，卻不向他作白就入聚落，犯波逸提。不向比丘作白而入聚落的，隨所經過的大巷小巷，經過幾條就得幾個突吉羅；隨進入白衣家，每入一家各犯一個波逸提。若進入阿蘭若處，或進入鄰近聚落的僧坊，不作白也無罪。《薩婆多論》說：若作總相的稟白而入聚落，之後隨自己的意思前往所要到的處所，都無犯。《僧祇律》說：若多人在路上同行，想要進入聚落，應彼此輾轉作白，然後才進入。已經到了住宿處，又想外出取柴薪草木的，若從原來那條路出去，無犯；若改從別條路出去，不作白就犯波逸提。《大智度論》說：一切白衣的房舍都名為聚落。《善見論》說：有市集的稱為聚落，沒有市集的稱為村界。《四分律》說：若自己有事須前往稟白告知，或是有他人召喚、邀請，或是道路經由聚落而過，都無犯。", "i": "u518", "n": 354, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "過量造牀戒。具五緣犯：一、是牀，二、僧牀及口牀，三、過量，四、自作、使人作，五、作成便犯。《僧祗》云：僧牀亦犯。此律：為截者不犯。《僧祇》云：得過量牀，欲截，恐檀越不喜者，應埋脚用；乃至截脚木還越牀脚，亦犯。若終日，一坐；提起已還坐，隨一一提。他牀，越；若福德舍高牀，無犯，乃至不截者，越。此律：足高如來八指者，《十誦》云：佛一指二寸，謂高一尺六寸，如法。", "t": "過量造床戒，具足五緣就犯：第一，所做的是床；第二，不論是僧眾的床或自己的床；第三，超過規定的量；第四，自己作或教人作；第五，一作成就犯。\n《摩訶僧祇律》說：僧眾的床也一樣犯。本律說：若是為了截短而作的，不犯。\n《僧祇律》說：得到過量的床，想要截短，又怕施主見了不高興，就應把床腳埋入地中來使用；乃至把截下的腳木再墊回去撐高床腳，也同樣犯戒。若整天就這樣坐著，只犯一個波逸提；起身之後又再坐下，則隨每一次坐下，各犯一個波逸提。坐別人的過量床，得越毘尼罪。若是福德舍裡的高床，坐了無犯；乃至不截短床腳的，得越毘尼罪。\n本律說床腳的高度是「如來八指」；《十誦律》說：佛的一指是二寸，八指便是高一尺六寸，這樣的高度才如法。", "i": "u519", "n": 355, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "食䔉戒。具三緣：一、是䔉（餘辛犯輕），二、無重病緣，三、食用，咽咽犯提。所以䔉重餘輕者：一、美味，尼多憙食，二、臭，故重餘辛也。《五分》云：食生䔉，提；熟者，吉。《五辛報應經》云：比丘尼等飲酒、食肉、葷辛，續經、誦論等得提，五辛得重吉；唯除僧伽藍外白衣家，限四十九日，香湯澡浴竟，讀誦無犯；故噉穢物，見不訶者，亦犯。《僧祇》、《十誦》、《五分》等：更無餘治者，開病比丘服䔉，聽七日在一邊小房內，不得臥僧牀褥，大小便處、講堂皆不得至，又不得受請及僧中食，不得就佛禮拜，得在下風處遙禮。七日滿已，澡浴重衣，方得入眾。若用香塗病者，先供養佛已，然後塗身，還在屏處，一同前法。", "t": "食蒜戒，須具足三個條件才成犯：一、所吃的是蒜；若是蒜以外的其他辛菜，只犯輕罪。二、沒有重病可開許的因緣。三、食用嚥下，每吞一嚥就犯一個波逸提。\n之所以蒜罪重、其餘辛菜罪輕，原因有二：一是蒜味美，比丘尼大多愛吃；二是因其臭穢，所以罪重於其餘的辛菜。\n《五分律》說：吃生蒜犯波逸提，吃熟蒜犯突吉羅。\n《五辛報應經》說：比丘尼等飲酒、吃肉、吃葷辛之物，卻仍照常讀經誦論等，犯波逸提；食五辛則得重突吉羅罪。唯有在僧伽藍以外的白衣家中食用，才屬例外，以四十九日為期限，期滿用香湯沐浴完畢，讀誦經論就不犯罪。若有人故意吃這類污穢之物，見到而不加以呵責的人，也同樣犯罪。\n《僧祇律》《十誦律》《五分律》等說：若再沒有其他治法可治，才開許病比丘服蒜，准他七天之內住在偏僻處的一間小房中：不得睡臥僧眾的床褥，廁所與講堂都不准去，也不得接受施主的請供以及在僧眾中進食；不得走近佛前禮拜，只能站在下風處遠遠禮拜。七天期滿之後，沐浴、重新換過衣服，才可以回到僧眾之中。若是用香藥塗敷治病的人，要先供養佛，然後才塗在身上，塗後仍須住在隱蔽的別處，一切都與前面服蒜的做法相同。", "i": "u520", "n": 356, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "剃三處毛戒。具緣可解。《母論》云：剃髮者，但除頭毛及鬚，餘毛一切不聽却。所以剃髮者，為除憍慢自恃心，不聽利木刀刮汗却毛；若斷一一毛，一一吉羅，除頭上毛不犯；若斷餘毛，一一偷蘭。剃髮有四種次第：一、上座，二、髮長，三、先洗頭，四、有緣欲行。《五分》云：尼過半月不剃髮，提。《涅槃》云：髮爪長利，破戒之相。此律：不得為白衣剃髮驅使，提；除欲出家者，不犯。頭髮極長，若兩月，若廣二指，一剃；爪極長，如一麥，即剪。髮不得用剪刀剪，半月應剃髮、一剪爪，違者吉羅；聽畜盛髮器。《十誦》云：髮當埋坑中；若髮長者，開畜剃刀及鞘；若刀卷者，手上波，石上磨，其石內刀囊中。", "t": "剃三處毛戒（三處指大便處、小便處及腋下）：結罪的犯緣容易明白。《母論》說：剃髮只除去頭上的毛和鬍鬚，其餘部位的毛一律不許去除。之所以要剃髮，是為了除去憍慢自負的心。不許用鋒利的木刀刮汗除毛；若刮斷一根毛，就犯一個突吉羅。剃除頭上的毛不犯；若剃斷其餘部位的毛，一根犯一個偷蘭遮。剃髮有四種先後次第：一是上座，二是頭髮長了，三是先洗頭的人，四是有事緣要出行的人。\n《五分律》說：比丘尼超過半個月不剃髮，犯波逸提。《涅槃經》說：頭髮、指甲長而尖利，是破戒的相狀。本律（《四分律》）規定：不得為在家人剃髮、受他們驅使，犯波逸提；除非對方是想要出家的人，為他剃髮則不犯（如今多有僧尼以諂媚之心求取利養，受俗人驅使，敗壞善法、增長惡業，過失沒有比這更嚴重的了）。\n頭髮最長不超過兩個月，或長到二指寬，就該剃一次；指甲最長長到如一粒麥，就該剪掉。頭髮不得用剪刀剪。每半個月應剃髮一次、剪指甲一次，違者犯突吉羅。開許蓄存盛頭髮的器具。\n《十誦律》說：剃下的頭髮應當埋在坑中；頭髮長的人，開許蓄存剃刀及刀鞘；刀刃捲了，先在手掌上揩磨，再用磨石磨；那塊磨石就收放在刀囊裡。", "i": "u521", "n": 357, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "洗淨過分戒。具緣可辨。《僧祇》云：大小行已，不用水而用僧坐具、牀褥者，越。《十誦》：不洗大小行處，不得坐臥僧臥具上，若坐者，吉。《伽論》云：不洗大小便處，不得禮拜、受人禮；除無水，若為非人相瞋、水神所瞋，或服藥等，皆不犯。《三千威儀經》云：不洗淨禮佛者，設禮拜無功德。", "t": "「洗淨過分」戒：構成犯戒的諸緣不難辨明。《僧祇律》說：大便、小便之後不用水洗淨，卻使用僧眾的坐具、床褥的人，犯越毘尼罪。《十誦律》說：沒有洗淨下身的，不得坐臥在僧眾的臥具上；若坐上去，犯突吉羅罪。《摩得勒伽論》說：沒有洗淨大小便處，不得禮拜，也不得接受他人禮拜；除了沒有水的地方，或者遭到非人瞋怒、水神瞋怒，或者服藥等情形，都不犯。《三千威儀經》說：不洗淨就禮佛的人，縱使禮拜，也沒有功德。", "i": "u522", "n": 358, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "供僧水扇戒。具緣可辨。僧與尼男女相別，供給水扇，容生染習，迹涉譏醜，故犯。《僧祇》：水、扇互給，越；水、扇俱給，提。眾多比丘，互有兄弟，供給水扇，無犯。《十誦》云：比丘食時，尼立侍者，提；與食已還坐，若別處，無犯。", "t": "供僧水扇戒：構成犯罪的諸緣可以辨明。比丘僧與比丘尼眾，男女身分有別，尼眾供給水與扇，可能生起染愛習氣，行迹上又牽涉世人的譏嫌與醜議，所以犯戒。《摩訶僧祇律》說：水與扇只供給其中一樣，犯越毘尼罪；水與扇兩者都供給，犯波逸提罪。若是供給眾多比丘，或眾中有自己的兄弟，供給水扇就不犯。《十誦律》說：比丘吃飯時，比丘尼站在前面侍候的，犯波逸提；若把飯食給比丘之後就回到座位坐下，或是到別處去，就不犯。", "i": "u523", "n": 359, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "乞生五糓戒。具緣可辨。出家之人理宜乞食資身，無事修道；今乃躬乞穀米，事務煩雜，廢修道業，長己貪結，惱亂施主，過實不輕，故制提罪。《見論》云：乞豆、瓜、果，為造僧房舍乞穀米等，一切無犯。", "t": "「乞生五穀戒」：構成犯戒的諸緣可以自行辨明。出家之人按理應當以乞食來資養自身，不營雜務而專心修道；如今卻親自去乞求穀米，事務繁雜，荒廢了修道的功業，增長自己的貪欲結縛，又惱亂施主，過失實在不輕，所以制定波逸提罪。《善見論》說：乞求豆類、瓜、果，以及為了建造僧眾房舍而乞求穀米等，這一切都無犯。", "i": "u524", "n": 360, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "觀伎樂戒。具緣可辨。觀看伎樂，令心蕩逸，廢修道業，動越威儀，汙辱僧眾，損己不輕，故制往看見便犯提。《見論》云：下至猨猴、孔雀共言好，往看得提。", "t": "觀看伎樂戒：構成犯戒的諸緣，可以自行辨明。觀看歌舞音樂等表演，會使內心放蕩縱逸，荒廢修道的功業，動輒違越威儀，玷污羞辱僧眾，對自身的損害不輕，所以制定此戒：前往觀看，一看見就犯波逸提。《善見論》說：下至猿猴、孔雀的嬉戲，眾人一同稱說「好看」，比丘尼前往觀看，也犯波逸提。", "i": "u525", "n": 361, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共男子入屏障處共語戒。具緣可解。然男子有別，體無參涉，今入屏處，容生染習，遠成大過，招世譏醜，清白難分，故所以制。若離見聞屏，又無染心，而非共語，但犯吉羅；要假共語，方犯於提；若有染心，落在八事戒；坐，不犯。此「共男子屏處」，前離見聞屏復語犯，此是露障屏，不假語犯；不云「立住吉」者，以不行故犯輕。「遣伴遠去與男子屏處立行耳語」，此是離見聞屏，唯遣伴遠去耳語為異。", "t": "「與男子共入屏障處共語戒」，犯緣容易理解。男子與尼眾形體有別，本不應相互參雜交涉；如今進入屏處，可能滋生染污習氣，最終釀成大過，招致世人譏嫌醜評，清白難以辨明，所以制定此戒。若在他人看不見、聽不到的離見聞屏處，又沒有染污心，而且沒有共語，只犯突吉羅；必須共語，才犯波逸提。若有染污心，就落入八事戒。若只是坐著，就不犯這條與男子共在屏處的戒。前一條戒是離見聞屏，還須共語才犯；這一條戒是露障屏，即只有遮障而無覆蓋的隱蔽處，不必共語，共同進入即犯波逸提。戒本沒有明說「站立、停留犯突吉羅」，那是因為沒有行走入內，所犯較輕的緣故。至於「遣伴遠去，與男子在屏處站立、行走、附耳低語」這一戒，這是離見聞屏，只是以遣伴遠去、附耳低語這兩點與前戒不同。", "i": "u526", "n": 362, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "入白衣舍坐已不辭主人去戒。具四緣犯：一、是白衣舍，二、主人請在好牀席坐已，三、不辭輒去，四、出一足便犯。", "t": "「入白衣舍坐已不辭主人去」這條戒，具備四個條件便構成犯戒：一、是在家人的房舍；二、主人請她在好的床座、坐席上坐下了；三、不向主人告辭就擅自離去；四、一隻腳跨出門外，便犯。", "i": "u527", "n": 363, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "輒坐他牀戒。具四緣犯：一、白衣舍，二、是牀座，三、不語主人，四、輒坐便犯。", "t": "擅自坐他人床座戒：具備四個條件便構成犯戒：一、地點是在家白衣的房舍；二、所坐的是床或座位；三、沒有告知主人；四、擅自坐下，便犯波逸提。", "i": "u528", "n": 364, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "共男子入暗室戒。前是覆障屏，有窻牖光明，無第三人犯；今以其暗室故，生患處重，雖有多人猶犯，以此為異，故別制也。《五分》云：共男子入暗室，語語提；若恐怖處，若卒燈滅，不犯。義云：不問親與非親，須有燈明。惡心呪詛戒。具三緣犯：一、有瞋心，二、作惡呪詛，三、言詞了了便犯。此律云：立誓者，令稱「南無佛」。《提謂經》云：「南」者歸，「無」者命，「佛」者覺；又「南」者禮，「無」者大，「佛」者壽。", "t": "共男子入暗室戒：前一戒指的是有覆蓋遮障、但有窗戶透光的屏處，沒有第三人在場才犯。如今因為是暗室，滋生過患的情形更嚴重，即使有多人在場仍然犯；以此與前戒不同，所以另外制定這一戒。《五分律》說：與男子一同進入暗室，每說一句話就犯一個波逸提。若是在恐怖危險的處所，或燈忽然熄滅，就不犯。依義理說：不論親屬或非親屬，都必須有燈光照明。\n惡心咒詛戒：具足三個條件就犯——一、有瞋恨心；二、作惡咒詛；三、話說得清楚明白。本律說：若要立誓，應教她稱念「南無佛」為誓。《提謂經》說：「南」是歸，「無」是命，「佛」是覺；又「南」是禮，「無」是大，「佛」是壽。", "i": "u529", "n": 365, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "因瞋心推𦙄哭戒。具四緣犯：一、同於諍事，不善憶持，二、內瞋恨，三、推𦙄哭已，四、隨便淚墮，一一提。《僧祇》云：若尼自打不啼、啼而不打、亦打亦啼，俱提。", "t": "因瞋心而搥胸哭泣戒，須具足四項條件才犯：一、對於同一件諍論之事，不能好好地憶持記住；二、內心懷有瞋恨；三、已作出搥胸哭泣的舉動；四、隨後淚水滴落，每一次淚落都各犯一個波逸提罪。《僧祇律》說：若比丘尼自己打身而不哭，或只哭而不打身，或又打身又哭，這三種情形都犯波逸提。", "i": "u530", "n": 366, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "覆身同牀戒。具四緣犯：一、同牀臥，二、覆身，三、無病緣，四、隨臥便犯。同被褥臥，同牀不同被褥，同牀同被褥，不同牀在地上臥，亦犯。", "t": "「覆身同牀戒」具足四個條件就犯：一是二人同床躺臥；二是以衣被覆蓋身體；三是沒有生病的因緣；四是一躺臥下去就犯。此外，共用同一被褥而臥、同床而被褥各別、同床又共用被褥，以及不在同一床上而是一起臥在地上，這些情形也都犯。", "i": "u531", "n": 367, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "故惱客舊戒。具四緣犯：一、知他比丘尼先住、後至，二、作故惱心，三、在前誦經問義，四、言詞了便犯。", "t": "故意惱亂客、舊比丘尼這條戒，具足四個條件便構成犯戒：一、明知對方比丘尼是先住的舊住者，或是後到的客尼；二、生起故意惱亂她的心；三、在她面前誦讀經文、詢問義理；四、言詞說得清楚明白，便犯戒。", "i": "u532", "n": 368, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "同活病不看戒。具四緣犯：一、是比丘尼病，二、是同活，三、無因緣，四、不看便犯。《五分》云：同學病不看，提；同學者，謂同和尚、阿闍棃及常共伴，若止住不同，無犯。", "t": "「同活病不看戒」：具足四個條件便犯——一、對方是生病的比丘尼；二、對方是與自己「同活」、共同生活的同伴；三、自己沒有可不看顧的正當因緣；四、不去看顧照護，便犯。\n《五分律》說：同學生病而不看顧，犯波逸提。所謂「同學」，是指同依一位和尚、阿闍梨的人，以及平常經常在一起作伴的人；如果彼此不住在同一處，就不犯。", "i": "u533", "n": 369, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "安居中牽他出房戒。具五緣犯：一、是僧房分得入已，二、先聽在彼房住，三、瞋心牽出，四、無因緣，五、出戶便犯。《僧祇》云：牽他出時，彼若抱柱、捉戶、倚壁，隨離一一處皆提；若口訶叱，隨語離處亦提。此律：驅下二眾，吉。《僧祗》云：若尼出行，不付房舍、牀褥與知事人，閉戶而去者，提。《十誦》、《伽論》云：若鼾眠，應起經行；不能經行，應起屏處，不應惱他。", "t": "「安居中牽他出房戒」，具足五個條件便成犯：一、是僧房，且是自己分得、已經入住的房舍；二、先前曾聽許對方在那間房裡安住；三、起瞋恚心把她牽出去；四、沒有正當因緣；五、對方一出房門就成犯。\n《僧祇律》說：牽她出去的時候，對方若抱住柱子、抓住門扇、倚靠牆壁，隨著她被拉離的每一處，都各犯一個波逸提；若是開口訶斥驅趕，隨著她聽了這些話而離開的每一處，也各犯波逸提。本《四分律》說：驅趕下二眾出房，犯突吉羅。\n《僧祇律》又說：比丘尼外出時，不把房舍、床褥交付給管事的人，就關上房門離去的，犯波逸提。\n《十誦律》與《伽論》說：睡覺打鼾的，應當起身經行；不能經行的，也應起身到屏避之處去，不該惱亂他人。", "i": "u534", "n": 370, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "三時無事遊行戒。具三緣犯：一、春、夏、冬遊無因緣，二、除受日及春、夏、冬有利益因緣故不犯，三、隨所越界便犯。此律：春、夏、冬遊行，隨村界俱提。義云：不同舊解破安居行提、春冬犯吉。聽為羯磨、塔事、僧事遊行，不言春冬受請。", "t": "三時無事遊行戒，具足三緣便犯：一、在春、夏、冬三時出外遊行，卻沒有正當因緣；二、若已依「受日」法於安居中請假出界，或春、夏、冬三時另有能得利益的因緣，就不在此限，不犯；三、隨所越過的每一道界，便結一罪。本部《四分律》說：春、夏、冬三時遊行，隨所越過的村界，一一都犯波逸提。依義理判定：這與舊有的解釋不同——舊解認為破壞安居而出行才犯波逸提，春、冬二時遊行只犯突吉羅；律中只聽許為了作羯磨、營辦佛塔事、營辦僧事而遊行，並沒有說春、冬二時受請就可以出遊。", "i": "u535", "n": 371, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "安居竟不知請戒。具四緣犯：一、是檀越安居請，二、夏限已滿，三、無因緣，四、不去便犯。《母論》云：若安居竟，應移餘處，若有緣不得去，不犯；若無緣者，出界一日還來，不犯。《五分》云：若不限請，若更受請處，無犯。", "t": "安居結束後不知施主請限戒：具足四緣就犯。一、施主的邀請只限於安居期間；二、夏安居的期限已滿；三、沒有可留住的因緣；四、不離去，便犯。《毗尼母論》說：安居結束後，應當遷移到別處去；如果有因緣而不能離去，不犯；如果沒有因緣，只要走出界外一天再回來，也不犯。《五分律》說：如果施主的邀請沒有設定期限，或者在該處又再次受到邀請，就不犯。", "i": "u536", "n": 372, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "泉渠水中露身洗浴戒。具三緣犯：一、是河渠水，二、露身洗浴，三、洗身徧便犯。《僧祇》云：尼入俗人室浴，有年少入身懷妊，壞其淨行，因制不聽尼入浴室；病者在房然火，油塗揩，不如是者，越毗尼。《十誦》云：男子洗處前浴，皆提。", "t": "「在泉水、溝渠中裸露身體洗浴」這一戒，具足三個條件便犯：一、是河流、溝渠中的水；二、裸露身體洗浴；三、洗遍全身，便犯波逸提。\n《僧祇律》說：有比丘尼進入在家人的浴室洗澡，有年輕男子進來，使她懷了孕，毀壞了她的淨行，因此佛制不許比丘尼進入浴室洗澡。生病的尼，可在房中生火，用油塗抹搓揉身體；不這樣做而進入浴室的，犯越毗尼罪。\n《十誦律》說：在男子洗浴的地方洗澡、在男子面前洗澡，都犯波逸提。", "i": "u537", "n": 373, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "過五日不看僧伽棃戒。具三緣犯：一、是僧伽梨，二、舉處不堅密，三、過五日不看便犯。《十誦》云：故意不看五衣，俱提。", "t": "「超過五天不查看僧伽梨大衣」這條戒，具備三個條件便犯：一、是僧伽梨大衣；二、收藏大衣的地方不堅固密實；三、超過五天不去查看，就犯。《十誦律》說：若是故意不查看，對比丘尼的五衣，每一種都犯波逸提。", "i": "u538", "n": 374, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與僧衣作留難戒。具四緣犯：一、是檀那許施衣，二、知許施衣，三、作方便勸彼不令施衣，四、施主息心施便犯。", "t": "對布施僧眾衣服一事加以阻難的戒，具足四項條件便構成犯戒：一、施主已許諾要布施衣服；二、比丘尼知道施主已許諾布施衣服；三、想方設法勸說施主，使他不布施衣服；四、施主因此打消了布施的念頭，便犯此戒。", "i": "u539", "n": 375, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "輙著他衣戒。具三緣犯：一、是他衣，二、不問輒著，三、入村乞食便犯。", "t": "未經詢問便擅自穿著他人衣服這條戒，須具備三個條件才構成犯戒：第一，那是他人的衣服；第二，不先問過衣主就擅自穿上；第三，就這樣穿著進入村落乞食，便成犯。", "i": "u540", "n": 376, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與俗人外道衣戒。具四緣犯：一、是非親里白衣、外道，二、是袈裟一衣，三、持與彼，四、前人領受便犯。《十誦》：與外道、與白衣，皆提。義云：今數見尼僧往道士觀求治病，交涉來往，供結衣食，因染俗情，壞其梵行，招世譏謗，損辱佛僧；非但師無綱紀，亦因前無法度。若有力罰令歸俗者，此人為護法因緣故，當來之世，必獲淨土之報。《僧祇》云：若尼有德，聽女人為兒乞小小破衣以禳災者，不得與大者，不得自手與，應遣人與。", "t": "「與俗人外道衣戒」，即把衣施給俗人與外道的戒，具足四個條件便犯：一、對方是非親屬的在家人或外道；二、所給的是袈裟法衣中的一件；三、拿衣給對方；四、對方領受，便犯波逸提。\n《十誦律》說：給外道衣、給在家人衣，都犯波逸提。\n鈔主依義評論說：如今屢見尼眾前往道士的宮觀求醫治病，與他們交涉往來，供送衣食以締結交情，因而沾染世俗情執，敗壞自己的梵行，招來世人的譏嫌毀謗，損害羞辱佛陀與僧團。這不只是師長沒有綱紀，也是因為這些尼眾本身沒有法度。若有力量懲治她們、令她們還俗的人，此人由於護法的因緣，來世必獲往生淨土的果報。\n《僧祇律》說：若比丘尼有戒德，女人為孩子向她乞討小小的破衣片來消災解厄時，聽許給與；但不得給大片的，不得親手給，應當派人拿去給。", "i": "u541", "n": 377, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧如法分衣遮不令分戒。具四緣犯：一、是僧作法分，二、恐弟子不得，三、遮令不分，四、僧不分便犯。", "t": "僧眾如法分衣，比丘尼卻加以遮阻、不讓分配的這一戒，須具足四項條件才構成犯戒：一是僧眾正在作法分配衣物；二是比丘尼擔心自己的弟子分不到衣；三是遮阻，使僧眾不分配；四是僧眾因此果真沒有分衣，便犯此戒。", "i": "u542", "n": 378, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與白衣外道食戒。具五緣犯：一、是在家、出家外道俱犯，二、知是，三、是食，四、自手與，非置地、使人與，五、彼領受便犯。《五分》云：若外道來乞，應以己分一團別著一處與，不得以僧食與。汎汎男子自手與食，提；親里者，不犯。義云：比見邊方僧尼寺內設會及僧施，每喚道士同僧受施，滅法之原，無過此等；自惟高邁人天，重逾金玉，忽然下墜邪流，無辜自辱，豈不痛心。", "t": "給白衣、外道食物戒，具足五個條件便犯：一、對方是在家白衣，或是出家外道，給這兩類人都犯；二、明知對方是白衣或外道；三、所給的是食物；四、親手交給他，而不是放在地上給、或差使人代給；五、對方領受，便犯。\n《五分律》說：如果外道前來乞食，應當從自己那一分食物中取出一團，另外放在一處給他，不得拿僧眾的食物給他。若是一般非親屬的男子，親手把食物給他，犯波逸提；若是親屬，就不犯。\n依義評說：近來見到邊遠地區的僧尼，在寺院內舉辦齋會、設供僧的布施時，每每召請道士來，與僧眾一同接受布施。滅法的根源，沒有比這類事更嚴重的了。自己想想，本是高超出於人天之上、尊貴過於金玉的，卻忽然向下墜入外道邪異之流類，平白無故地自取其辱，怎能不令人痛心！", "i": "u543", "n": 379, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "與白衣作使戒。具四緣犯：一、是白衣，二、無病因緣，三、非時為作使，四、隨使便犯。", "t": "為在家人充當使役這一條戒，須具足四個條件才構成違犯：一、所服務的對象是在家人；二、沒有對方患病等開許因緣；三、在不恰當的時機為對方作使役；四、只要受人差遣去做，便構成犯戒。", "i": "u544", "n": 380, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "自手紡績戒，具三緣犯：一、是麻縷，二、自手紡績，三、隨手一一犯提。《十誦》云：「若紡、縈、績，若織，若擗，若抖擻，若纏手，隨動手一一犯提；纏線開，不犯。」《五分》云：「尼自織作衣，提；若刺鞾法張衣先刺，吉羅；衣差縮，聽安相。」義云：「今時尼眾，慕道者希；專事機帚，紡績是常；作務精勤，經教多忘。貧者貪美不休，富則轉生紛擾，還復倣習，惡法愈興，荏苒流行，致乖常式。敬尋捨俗入道，冀免業因；入道被纏，反同累俗。靜慮推事，深可悲乎。", "t": "自手紡績戒，具足三緣便犯：第一，所用的是麻縷，即麻線；第二，自己親手紡績；第三，隨著手的每一次動作，各各犯一個波逸提。\n《十誦律》說：不論是紡、是縈繞卷絡、是績撚麻成線，或是織，或是擘分纖維，或是抖動，或是把尚未紡成的麻縷纏在手上繼續紡績，隨著每一次動手，一一都犯波逸提；若只是把已紡成的線纏繞收卷，則是開許，不犯。\n《五分律》說：比丘尼自己織布做衣，犯波逸提；若以縫靴之法，把衣料繃張起來先行刺孔，犯突吉羅；衣料參差皺縮時，聽許安上記號。\n依義評論說：現今的尼眾，仰慕道業的人很少，專門從事織機、灑掃這類家務，紡紗績麻成了日常慣事，對這些作務精勤不懈，經教法義卻大多忘失。貧窮的貪求美好而無休止，富有的反而輾轉滋生紛擾；又再彼此仿效學習，惡法愈來愈興盛，因循遷延地流行開來，以致違背了正常的法式規範。恭謹地推究：捨俗入道，本是希望免除業因；如今入了道，卻仍被這些事務纏縛，反而等同於世俗的牽累。靜下心來思慮、推究此事，實在深可悲嘆啊！", "i": "u545", "n": 381, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "著俗服輒在白衣牀臥戒，具三緣犯：一、是白衣舍，二、是他夫婦常居止宿牀，三、隨臥便犯。", "t": "穿著俗人衣服、擅自在在家人床上躺臥的這條戒，具足三個條件就構成犯戒：一、地點是在家人的房舍；二、那張床是那戶人家夫婦平常起居、過夜睡臥所用的床；三、每躺臥一次，就犯一次。", "i": "u546", "n": 382, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "經宿不辭主人去戒，具四緣犯：一、語主人在他舍內宿，二、不辭主去，三、無因緣，四、出門便犯。", "t": "住宿過夜後不向主人告辭就離去戒，須具足四個條件才成犯：一、已先告知主人，而在他人屋舍內住宿過夜；二、不向主人告辭就離去；三、沒有特殊因緣；四、一走出門外便成犯。", "i": "u547", "n": 383, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "度妊身女人戒，具四緣犯：一、妊身，二、知，三、受具戒，四、三羯磨竟便犯。", "t": "度懷孕的女人受具足戒這一戒，具備四個條件便犯：一是對方確實懷孕；二是明知她懷孕；三是為她授具足戒；四是三番羯磨一結束，就犯。", "i": "u548", "n": 384, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《十誦》：掘多尼生男兒，作是念：「佛說比丘尼不得獨房。」乃至佛言：「告諸尼等，與掘多尼作獨房宿羯磨。」是尼應與，從僧三乞，牒乞而作。未離乳，聽母觸，餘尼觸吉；離乳，母觸吉，餘尼觸提；離母共宿吉，辭去後提。", "t": "《十誦律》說：掘多比丘尼生了一個男孩，她心裡想：佛說過比丘尼不得獨自在一間房裡過夜。乃至佛說：告訴眾比丘尼，為掘多比丘尼作獨房宿羯磨，即由僧眾作法聽許她獨自宿於一房。此法應當給與這位比丘尼：由她向僧眾三次乞請，作法者再牒舉她的乞請之詞而作羯磨。孩子還沒斷奶時，聽許母親觸碰他，其他比丘尼觸碰得突吉羅；斷奶之後，母親觸碰得突吉羅，其他比丘尼觸碰得波逸提。孩子斷奶離母之後，與他同宿得突吉羅；若孩子已被遣離（辭去）之後再與他同宿，就得波逸提。", "i": "u548-2", "n": 385, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《五分》云：「聽白二羯磨差一尼伴之，被差尼得羯磨故，不犯。自今已後，欲受戒時，先看乳相；若無乳相，不犯。」", "t": "《五分律》說：聽許以白二羯磨差派一位比丘尼陪伴她；被差派的比丘尼因為已得僧羯磨差遣的緣故，不犯。從今以後，要為人授戒時，應先查看她的乳相，確認有無乳汁；若沒有乳相，就不犯。", "i": "u548-3", "n": 386, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "《僧祇》云：「不知在白衣時姙，已度者，未應與受戒，待㝃身已；若生女者，出草蓐已，與受具戒；若生男者，離乳已後與受具；若有親里將養，即與受具。", "t": "《摩訶僧祇律》說：不知道她在家時就已懷孕而已經度她出家的，不應隨即給她授具足戒，要等到她分娩之後。若生的是女孩，等她出草蓐，即產褥期滿、離開生產時所臥的草褥之後，再給她授具足戒；若生的是男孩，要等孩子斷奶以後，才給她授具足戒。若有親屬願意領去撫養，就可以立刻給她授具足戒。", "i": "u548-4", "n": 387, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "度童女年不滿受具戒，具四緣犯：一、是年未滿二十，二、知年未滿，三、與受具，四、羯磨竟便犯。《婆論》云：「六十已去，不得受大戒，設師僧強授，亦不得戒，以不堪任苦行道故；心智鈍弱，聽為沙彌。七歲已下，亦不許度。未滿二十不得受具者，以其輕躁，不堪忍受寒苦；若受大戒，人多訶責，若是沙彌，人則不訶。」《母論》：年不滿者，聽數胎中；年又不滿者，聽數閏月；復不滿者，聽數十四日布薩；復不滿者，佛言：「實得羅漢果者，此是上法，受具雖不滿二十，得戒無犯。", "t": "度年齡未滿二十歲的童女受具足戒，這條戒具備四個條件便犯：一是年齡未滿二十歲；二是知道她年齡未滿；三是為她授具足戒；四是羯磨作法一完成，便犯。\n《薩婆多毘尼毘婆沙》說：六十歲以上的人不得受具足大戒，即使師長與僧眾勉強為他授戒，他也得不到戒，因為他已不堪承當苦行修道，心智遲鈍衰弱，只允許他做沙彌；七歲以下的孩童，也同樣不許度他出家。至於未滿二十歲不得受具足戒，是因為年少輕浮躁動，不能忍受寒冷困苦；若受了大戒，人們多半會加以訶責；若只是沙彌，人們就不會訶責。\n《毘尼母論》說：年齡不滿二十的，允許把在母胎中的年月也算入年齡；若還不滿，允許把閏月算進去；若仍不滿，允許計數十四日布薩；若這樣算來仍舊不滿，佛說：確實已證得羅漢果的人，這屬於上法受具，雖然未滿二十歲，受者也得戒而無犯。", "i": "u549", "n": 388, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不與二歲學戒羯磨戒，具五緣犯：一、是十八已上童女，二、不與學戒羯磨，三、年滿二十，四、與受具戒，五、三羯磨竟犯。", "t": "「不給予兩年學戒羯磨」戒，具足五個條件便構成犯戒：一、對方是十八歲以上的童女；二、沒有為她作學戒羯磨；三、她年滿二十歲；四、為她授具足戒；五、三番羯磨一結束，便結犯。", "i": "u550", "n": 389, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不說六法名字戒，具六緣犯：一、是十八童女，二、與學羯磨，三、不說六法，四、年滿二十，五、受具戒，六、羯磨竟便犯。", "t": "不宣說六法名稱戒：這一戒須具足六項條件才構成犯戒：一、對象是十八歲的童女；二、已為她作過學戒羯磨；三、卻沒有向她宣說六法的名稱；四、她年滿二十歲；五、為她授具足戒；六、授戒羯磨一完成，便犯此戒。", "i": "u551", "n": 390, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "度受諸遮童女戒，具四緣犯：一、是諸根不具，二、知不具，三、與受具戒，四、三羯磨竟便犯。", "t": "度有各種遮難的童女出家受具足戒這一條戒，具備四個條件便構成犯戒：一是這名童女身體諸根殘缺不全；二是明知她諸根殘缺；三是仍為她授具足戒；四是三次羯磨作法完成，便犯此戒。", "i": "u552", "n": 391, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不以二事攝弟子戒，具四緣犯：一、是清淨弟子，二、恒隨和尚，三、師有法及衣食，四、不以此二事攝便犯。", "t": "「不以二事攝弟子」這條戒，具足四個條件便犯：一、弟子是清淨的；二、弟子恒常跟隨和尚尼；三、師父有法可教導、也有衣食可供給；四、師父不以法與衣食這兩件事攝受弟子，便犯。", "i": "u553", "n": 392, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "受戒已離和尚戒，具五緣犯：一、是和尚，二、有夏堪攝，三、師不聽去，四、未滿六夏尼，五、離去便犯。", "t": "受具足戒之後離開和尚尼的戒，具足五緣便犯：一、所離開的是自己的和尚尼；二、和尚尼有足夠夏臘，堪能攝受弟子；三、和尚尼不允許弟子離去；四、弟子是受具足戒未滿六夏的比丘尼；五、弟子一旦離去，便犯此戒。", "i": "u554", "n": 393, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "未滿十二夏度人戒，具三緣犯：一、內無實夏，二、與受具戒，三、羯磨竟便犯。", "t": "「未滿十二夏度人」這條戒，是指自身戒臘未滿十二夏便度弟子、為人授具足戒。此戒具足三個條件便成犯：一、自身實際的戒臘未滿十二夏；二、為他人授具足戒；三、授戒的羯磨作法一完成，便犯此戒。", "i": "u555", "n": 394, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "僧不聽度人謗僧戒，具四緣犯：一、內無實夏，二、僧不聽，三、非理謗僧，四、言詞了了便犯。", "t": "「僧眾不聽許度人而毀謗僧眾戒」：此戒具足四緣便犯——一、自身實際戒臘未滿十二夏（內無真實足夠之夏臘）；二、僧眾不聽許她度人；三、無理地毀謗僧眾；四、言詞說得清楚明白，便犯。", "i": "u556", "n": 395, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "父母夫主不聽輙度人戒，具四緣犯：一、有父母夫主，二、不聽，三、輙與受具戒，四、三羯磨竟便犯。", "t": "「父母或丈夫不許可，卻擅自度人受具足戒」這條戒，具足四個條件便成犯：一、要受戒的女子有父母或丈夫；二、父母或丈夫不許可；三、未經許可，就擅自為她授具足戒；四、三番羯磨作法一結束，便成犯。", "i": "u557", "n": 396, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不與學戒尼受具戒，具四緣犯：一、是學戒清淨，二、滿二年，三、無因緣，四、作心不與受具便犯。", "t": "不給學法女授具足戒這一條戒，須具足四個條件才成犯：一、對方是學戒清淨的學法女；二、她學戒已滿二年；三、並沒有障礙授戒的特殊因緣；四、自己故意不為她授具足戒——如此便犯。", "i": "u558", "n": 397, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "多度弟子戒，具四緣犯：一、是曾前度人，二、未滿十二月，三、更度人受具，四、三羯磨竟便犯。《僧祇》云：「若年年與弟子受具者，提，應停一年。若尼有多弟子，若一年與受學法，一年與受具戒，雖年年，不犯。」古德光師云：「若寬解者，一年間與一人受具，一人依止，一人六法，一人沙彌尼，令得四人；若急解者，一年止得度一人。」準此應然，據前《僧祇》提。《母論》云：「受一人具足，一年教授一切大道人所作法竟，然後更一人。若沙彌尼受學戒已，二年不得度沙彌尼；式叉尼受具已，得度沙彌尼。", "t": "「多度弟子戒」具備四個條件便成犯：一、先前已曾度人受具；二、距前一次尚未滿十二個月；三、又再度為他人授具足戒；四、三番羯磨作完，就成犯。\n《僧祇律》說：若年年都給弟子授具足戒，犯波逸提，應當停隔一年。若一位比丘尼有多位弟子，可以這一年給弟子授學法，下一年給弟子授具足戒；如此雖然年年都在授，也不犯。\n古德光師說：若從寬解釋，一年之內可以為一人授具足戒、為一人作依止師、為一人授六法、為一人授沙彌尼戒，總共可度得四人；若從嚴解釋，一年只能度一人。照此看來，應當是這樣才對，所依據的就是前面《僧祇律》所判的波逸提。\n《毘尼母論》說：給一人授了具足戒，須在一年之中把這位已受具戒者（大道人）所應作的一切法都教授完畢，然後才可以再度另一人。若沙彌尼已受了學戒（六法），師父在此後二年內不得再度沙彌尼；等到式叉摩那尼受了具足戒之後，才可以再度沙彌尼。", "i": "u559", "n": 398, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不半月請教授師戒，具三緣犯：一、僧尼眾各各五人已上（四人已下但犯吉羅），二、無因緣，三、不差人往請便犯。", "t": "「不半月請教授師」戒，須具足三個條件才成犯：一、比丘僧眾與比丘尼眾各自都有五人以上；若任何一方只有四人以下，就只犯突吉羅。二、沒有特殊因緣。三、不派人前往比丘僧中求請教授師，便成犯。", "i": "u560", "n": 399, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不詣大僧自恣戒，具四緣犯：一、是夏安居竟，二、五人已上成眾，三、無因緣，四、不差人往自恣便犯。《五分》云：「若尼聚落無比丘，自恣無請處，蘭若有比丘，道路險難，彼比丘為尼入聚落自恣；尼先自眾中自恣已，後差人往比丘中，教誡語同。", "t": "不前往比丘僧中自恣戒，具備四個條件便犯：一是夏安居已經結束；二是尼眾五人以上，已構成僧眾；三是沒有可開許的因緣；四是不差派人前往比丘僧中自恣，如此便犯此戒。\n《五分律》說：如果比丘尼所住的聚落裡沒有比丘，自恣時沒有可前往請求的處所；而阿蘭若荒野處雖有比丘，道路卻艱險難行，那麼那些比丘應為了比丘尼而進入聚落作自恣。比丘尼先在自己的僧眾中作完自恣，之後再差派人前往比丘僧中。關於教誡的規定，律文的說法與此相同。", "i": "u561", "n": 400, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不依大僧安居戒，具三緣犯：一、在無比丘處，二、不作依止心，三、結安居竟便犯。", "t": "「不依大僧安居戒」，即不依止比丘僧團而結夏安居的戒，具備三個條件便犯：一、住在沒有比丘的地方；二、沒有生起依止大僧的心念；三、結安居的作法一旦完成，便構成犯戒。", "i": "u562", "n": 401, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不白入大僧寺戒，具四緣犯：一、是有比丘寺，二、不白比丘，三、無因緣，四、入門便犯。《僧祇》云：「尼不白大僧入伽藍者，最初入者提，後入者無犯。」《五分》云：「若立，不見比丘，不得不白而入，須見比丘，應往前白比丘，籌量可聽、不可聽者。若人不見及不聽而入，提。", "t": "不稟白就進入比丘僧寺這條戒，具足四緣便犯：一、那是有比丘的寺院；二、不稟白比丘；三、沒有開緣；四、一進門就犯。《僧祇律》說：比丘尼不稟白比丘僧就進入僧園的，最先進入的那位犯波逸提，隨後進入的則不犯。《五分律》說：如果站在門口看不見比丘，仍不可以不稟白就進入；必須見到比丘，應當上前稟白，由比丘斟酌考量可以聽許或不可以聽許；如果不見比丘，或是未獲聽許就進入，犯波逸提。", "i": "u563", "n": 402, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "訶罵比丘戒，具三緣犯：一、是大比丘，二、以惡言罵彼，三、言詞了了便犯。《十誦》云：「喑嗌向比丘者，提。", "t": "呵罵比丘戒：具足三個條件便犯——一、對方是已受具足戒的比丘；二、用惡毒的言語辱罵他；三、言語清楚、對方領解，如此便犯波逸提。《十誦律》說：「喑嗌向比丘者，提。」喑嗌，指瞋怒時發出的哼叱、怒喝之聲；這是說，對比丘發出這樣的怒聲，就犯波逸提。", "i": "u564", "n": 403, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "罵尼眾戒，具四緣犯：一、是尼眾，二、因諍事瞋怨，三、以惡言罵辱，四、言詞了了便犯。", "t": "罵尼眾戒，具備四個條件便構成犯戒：一、所罵的對象是比丘尼眾；二、因為鬪諍之事而心懷瞋恨怨惱；三、用粗惡的言語辱罵對方；四、辱罵的言詞說得清楚明白，便構成犯戒。", "i": "u565", "n": 404, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不白眾使男子治癰戒，具緣可解。然男女形別，理無交對，聽彼破癰，容生染習，自壞心行，所以制也。《五分》云：「若令男子治癰，打鐘集僧，來往病人前，然後衣裹身，唯留可治處治之。", "t": "不先向尼眾稟白就讓男子醫治癰瘡戒：構成犯戒的各項條件容易明白。然而男女身形有別，按理不應彼此直接面對接觸；若聽任男子切開癰瘡，可能滋生染污的習氣，敗壞自己的心念與行持，所以才制定這條戒。《五分律》說：如果要讓男子醫治癰瘡，應打鐘集合尼眾，大眾來到病人跟前（在場作證），然後用衣服裹住病人的身體，只露出可以施治的患處，再讓男子醫治。", "i": "u566", "n": 405, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "背請戒，具緣可解。若受非正食請及正食不足，背之無犯。《十誦》云：「從今聽尼數數食。何以故？女憙數數食故。」乃至「若尼能受請都不食者，提；是中犯者，乃至食一口，隨受請不食，一一提。", "t": "背請戒的成犯因緣，容易了解。如果所受的是非正食的邀請，或者正食不足，背棄該邀請，都無犯。《十誦律》說：從今以後，聽許比丘尼數數食，就是一處受食之後又轉往他處食，這就是本段背請戒的異名。為什麼呢？因為女人喜歡一處受食之後又轉往他處食的緣故。乃至說：若比丘尼堪能赴請受食，卻在受請之處完全不吃，就得波逸提。其中犯的情形是：在改赴的他處乃至只吃一口，也就成犯；隨著她所接受卻不吃的邀請，一一各得一波逸提。", "i": "u567", "n": 406, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "於家生嫉妬戒，具四緣犯：一、施主好心供養於師，二、見師得利，內生嫉妬，三、發言嫉師，四、言詞了了便犯。《十誦》云：「護惜他家者，人取覓，代他言無，提。」《五分》云：「嫉妬他人得利，欲專我得，犯提。", "t": "「於家生嫉妒戒」：具足四個條件便構成違犯——一、施主出於好心供養師父；二、見到師父獲得利養，內心產生嫉妒；三、開口說出嫉妒師父的話；四、話說得清楚明白，便犯波逸提。《十誦律》說：「護惜他家」——即對施主之家慳惜守護：當有人要向那家求索時，她卻代替那家人回答說「沒有」，如此便犯波逸提。《五分律》說：嫉妒別人獲得利養，想要利養專歸自己一人所得，便犯波逸提。", "i": "u568", "n": 407, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "用香塗身戒，具緣可解。凡出家修道，理宜觀身不淨，特生厭離；反用香氣潤澤塗身，令形香潔，耽著己體，情存放逸，患累之深，所以制也。", "t": "「用香塗身戒」：構成犯戒的各項條件容易明白。凡是出家修道的人，按理應當觀想身體是不淨的，尤其要生起厭離之心；如今反而用芳香潤澤之物塗抹身體，使身形芳香潔淨，這是耽溺執著自己的身體，內心存著放逸，過患與拖累如此深重，所以佛陀制定此戒。", "i": "u569", "n": 408, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "著婦人嚴身具戒，具緣可解。既畜著俗人嚴身之具，多生染習，障道深故，故須聖制。", "t": "「穿戴婦女嚴飾身體物品」這條戒，構成犯戒的各項條件依戒文即可明白。既然收藏又穿戴世俗人用來妝飾身體的物品，大多會滋生貪染的習氣，對修道的障礙極深，所以必須由佛陀制定此戒。", "i": "u570", "n": 409, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "乘乘行戒，具緣可解。《五分》云：「乘乘行戒者，車、轝、象、馬乃至著屐，皆名乘；若老病、若行路乃至脚指病，無犯。」《僧祇》云：「若病人不能行，乘雌乘，無罪。", "t": "乘乘行戒的成犯諸緣，依戒文即可了解。《五分律》說：乘乘行戒所說的「乘」，舉凡車輛、轎輿、大象、馬匹，乃至脚上穿著木屐，都叫作「乘」。若是年老、生病，或是行路遠行，乃至脚指患病，都不犯。《僧祇律》說：若是病人無法步行，乘坐雌乘，即雌性的牲畜坐騎，沒有罪。", "i": "u571", "n": 410, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不著祇支入村戒，具三緣犯：一、有祗支，二、不著，三、入村門便犯。", "t": "不穿祇支這種掩腋內衣進入村中這一條戒：具足三項條件便犯——一、自己備有祇支；二、沒有穿上；三、一進入村門，便犯此戒。", "i": "u572", "n": 411, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "不安居戒，具三緣犯：一、是後安居日，二、不結安居，三、過後安居日便犯。", "t": "不安居戒：具足三個條件便犯——一、已到了後安居日，即最晚可結安居的五月十六日；二、沒有作法結安居；三、過了後安居日這一天，便犯此戒。", "i": "u573", "n": 412, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "誦呪為活命戒，具三緣犯：一、是世間呪術，二、為活命，三、言詞了了便犯。《十誦》云：「以外書聲誦佛經者，吉。」《五分》云：「學迷人呪、起死人呪，蘭；尼自使人卜，提。」此律：以世俗呪術教授白衣，亦提。", "t": "誦咒謀生這條戒，具備三個條件便犯波逸提：一、所誦的是世間的咒術；二、是為了謀生；三、話說得清楚明白。《十誦律》說：用世俗外書的音調來讀誦佛經，犯突吉羅。《五分律》說：學習迷惑人的咒術、使死人復活的咒術，犯偷蘭遮；比丘尼自己占卜或使人占卜，犯波逸提。本《四分律》中，把世俗咒術教授給在家人，也犯波逸提。", "i": "u574", "n": 413, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "先不請比丘輙問義戒，制意者，輙問即慢法輕人，遞相窮詰，令彼惱，特非所宜故，所以制之。若二人習一部，不解，轉問無犯。", "t": "「先不請比丘輒問義戒」，即不先向比丘請求許可便逕自請問法義這條戒，其制戒用意是：不先請求就發問，便是輕慢佛法、輕視對方；如此往復追問、窮加詰難，使對方惱亂，尤其不合宜，所以制定此戒。若是兩人共同研習同一部教典，因不了解而轉相請問，就不犯。", "i": "u575", "n": 414, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "百夏尼不敬比丘戒，具緣可解。若不禮敬，便有三過：一、違八敬教，二、違本受戒奉行之心，三、慢法輕人。情過是重故，所以制也。", "t": "即使是受戒已滿一百夏的比丘尼，也不得不恭敬新受戒的比丘——這條戒的犯緣，依戒文就能明白。如果不禮拜恭敬比丘，便有三種過失：一是違背八敬法的教制；二是違背當初受戒時誓願奉行的本心；三是輕慢正法、輕視他人。這種心態上的過失很重，所以才制定這條戒。", "i": "u576", "n": 415, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第四篇，八提舍尼。", "t": "第四篇是八條提舍尼戒。", "i": "u577", "n": 416, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "第五篇，眾學戒。", "t": "第五篇是「眾學戒」，也就是眾多應當學習的戒條。", "i": "u578", "n": 417, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "七滅諍，亦僧尼同有。", "t": "七滅諍法，也是比丘與比丘尼同樣都有的。", "i": "u579", "n": 418, "s": "第21篇　隨戒"}, {"v": "卷中", "o": "上來所列諸戒者，逐尼數犯者述之；餘不盡者，非無異相，或文繁寡要，或事希難犯，或其相易明，或其理幽隱。若欲廣陳，恐盈卷軸，冀後博學依文取決。", "t": "以上所列舉的各項戒條，是依著比丘尼時常違犯的部分來敘述的。其餘沒有詳盡說明的，並不是沒有各別不同的相狀可說，只是有的文句繁冗而少有關要，有的事情罕見、難以違犯，有的相狀容易明白，有的義理幽深隱微。若要一一廣泛鋪陳，恐怕會塞滿卷軸；希望後世博學之人，依據律文自行裁決判斷。", "i": "u580", "n": 419, "s": "第21篇　隨戒"}, {"v": "卷下", "o": "終南山沙門釋　道宣　述", "t": "終南山的沙門釋道宣撰述。", "i": "u581", "n": 1, "s": "第21篇　隨戒（續）"}, {"v": "卷下", "o": "○匡眾篇第二十二", "t": "第二十二篇：匡正僧團大眾。", "i": "u582", "n": 2, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "此篇大門有五：一、教有興廢，二、簡知事德，三、秉教通塞，四、僧食通局，五、入眾服儀。", "t": "本篇的大綱分為五門：第一，教法有興盛與衰廢；第二，揀選寺院知事者應具備的德行；第三，秉持律教行事時的通行與壅塞；第四，僧眾飲食普同十方或局限一處；第五，進入大眾之中應有的服飾與威儀。", "i": "u583", "n": 3, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "第一、教有興廢者：夫軌範一界，統攝徒眾，必須德行內充，威儀外肅，律教一宗，必先諳究，不憚勞苦，不存聲譽，令遠域異僧，欣心有所，界中行者，䇿神進業，此之御眾，何事不行？故律云：「非制不制，是制即行，如是漸漸，令法久住。」若法出恒情，言無規矩，翻同鄙俗，何成匡眾？宜自私退息，用慈懷。故律云：「非制而制，是制便斷，如是漸漸，令法速滅也。", "t": "第一門是「教有興廢」。凡要在一界之內作為大眾的軌範、統領攝受徒眾的人，必須德行充實於內、威儀整肅於外，對於律教這一宗，一定要先熟諳窮究，既不辭勞苦，也不存求取名聲的心。這樣就能使遠方異地而來的僧人欣然嚮往、心有歸投之處，界內的修行人也振奮心神、精進道業。像這樣統領大眾，還有什麼事不能推行呢？所以《四分律》說：「非制不制，是制即行，如是漸漸令法久住。」意思是：不是佛所制的，就不擅自制立；是佛所制的，就依教奉行，如此漸漸使正法久住於世。如果所立的規約出於凡常情見，言語沒有規矩法度，反倒與鄙陋的世俗一樣，那還怎能匡正大眾？這樣的人應當自己退下來，止息不再領眾，以慈悲為懷。所以《四分律》說：「非制而制，是制便斷，如是漸漸令法速滅。」意思是：不是佛所制的卻擅自制立，是佛所制的反而廢斷不行，如此漸漸使正法迅速滅亡。", "i": "u584", "n": 4, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "第二、簡知事德者：今此一門，總述諸德。若能綱紀，量過而行；償違斯法，舉不知時，諍事由生，惡法難息。故律云：「汝等數數舉他罪，恐壞正法故。」必具此德，恕而不治，正法亦滅。", "t": "第二、揀擇掌管僧務的知事人的德行。現在這一門，是總述擔任知事者所應具備的種種德行。若能統理綱紀、酌量過失的輕重而後施行；反之，倘若違背這個法則，舉發他人罪過卻不知時機，諍事便由此生起，惡法難以止息。所以《四分律》說：「你們屢屢舉發別人的罪過，恐怕會破壞正法。」因此必須具備這些德行；但若一味寬縱而不加治理，正法也同樣會滅亡。", "i": "u585", "n": 5, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "律云：能舉罪人，當具五德：一、知時，不以非時；二、真實，不以虗妄；三、利益，不以損減；四、柔輭，不以麤獷；五、慈心，不以瞋恚。", "t": "《四分律》說：能舉發他人罪過的人，應當具備五德：一、知道時機，不在不恰當的時候舉罪；二、依於真實，不憑虛妄；三、為了利益對方，不是為了損減對方；四、柔和，而不粗暴獷惡；五、以慈心，不以瞋恚。", "i": "u585-2", "n": 6, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "能斷事人，亦具五德：一、持戒清淨；二、多聞；三、廣誦二部戒律；四、能問能答；五、如法教訶及作滅擯。", "t": "能裁斷諍事的人，也要具備五德：一、持戒清淨；二、多聞；三、廣泛誦習比丘、比丘尼二部戒律；四、能問能答；五、能如法地教誡訶責，以及作逐出僧團的滅擯處置。", "i": "u585-3", "n": 7, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "今五德，善能滅鬬諍事，治斷非業，亦具五德：一、觀前事是實否；二、觀合是時宜否；三、觀僧不令生塵垢否；四、觀有利益否；五、觀得善伴否。", "t": "現在說到能善巧息滅鬪諍之事、治理裁斷不如法行為的人，也同樣須具備五德：一、觀察眼前這件事是否屬實；二、觀察是否合乎時宜；三、觀察能否不使僧眾生起煩惱塵垢；四、觀察是否有利益；五、觀察能否得到善伴。", "i": "u585-4", "n": 8, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "處判他事，亦具五德：一、善知不犯；二、善知犯；三、善知輕；四、善知重；五、善知決斷無疑。", "t": "處斷他人的事，也要具備五德：一、善知什麼是不犯；二、善知什麼是犯；三、善知罪輕；四、善知罪重；五、善於決斷而無疑惑。", "i": "u585-5", "n": 9, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "《毗尼母論》云：「能諫之人無五法，不須受：一、無慚愧，二、不廣學，三、常覓人過，四、憙鬬諍，五、欲捨道。」", "t": "《毗尼母論》說：前來勸諫的人若有這五種缺失，就不必接受他的勸諫：一、沒有慚愧；二、不曾廣學；三、常找別人的過失；四、喜好鬪諍；五、想要捨道還俗。", "i": "u585-6", "n": 10, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "《寶梁經》云：「二種人得為知事：一、阿羅漢，二、須陀洹人。所以爾者？餘諸比丘，戒不具足，心不平等，是人不合為知事也。復有二人得當知事：一、能淨持戒，識知業報；二、畏後世罪，有諸慚愧及以悔心。如是二人，自無瘡疣，亦護他人。」", "t": "《寶梁經》說：有兩種人可以擔任知事：一是阿羅漢，二是初果須陀洹人。為什麼如此？因為其餘的比丘戒不具足、心不平等，這些人不適合擔任知事。又有兩種人可以擔任知事：一是能清淨持戒、明了業報的人；二是畏懼後世罪報、懷有慚愧與悔改之心的人。這兩種人自身沒有如瘡疣般的過失，也能護持他人。", "i": "u585-7", "n": 11, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "若不具此德，率以庸情，輙處判他，反成自累，何匡益他也？故律云：「我說此人，愚癡故犯波羅夷。」謂不諳教綱，冥犯大罪。既知不易，誠為大誡，宜詳聖意，省己為人也。", "t": "如果不具備這些德行，輕率地憑著平庸的凡情，動輒處斷他人的事，反而成了自己的罪累，哪裡還能匡正、利益他人呢？所以《四分律》說：「我說這個人是因愚癡而犯波羅夷。」這就是說：不通達教法的綱要，糊裡糊塗地犯了大罪。既然知道這件事並不容易，實在是一大誡訓；應當詳審佛陀制教的本意，先省察自己，然後才去為人處事。", "i": "u585-8", "n": 12, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "第三、乘教通塞者：", "t": "第三、秉持律教的通與塞。", "i": "uGAP18-1", "n": 13, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "大集》云：「若未來世有諸王、四姓，為護法故，能捨身命，寧護一如法比丘，不護無量諸惡比丘，是王捨身生淨土中；若隨惡者，是王無量世中不復人身。王等不治，則斷三寶種，奪眾生眼，雖無量世修戒施惠，則為滅失。又，犯過比丘應須治者，一月、兩月苦使，或不與語，不與共坐、共住，或滅擯出一國乃至四國有佛法處。治如是等惡比丘已，諸善比丘安樂受法，故使佛法久住不滅。」", "t": "《大集經》說：未來世若有諸位國王和四種姓的人，為了護法的緣故，能夠捨棄自身性命，寧可護持一位如法的比丘，也不護持無量的眾多惡比丘，這位國王捨身之後便得往生淨土。反之，若是隨順惡比丘，這位國王在無量世中都不能再得到人身。國王等人若不加以治罰，就是斷絕三寶的種子、奪去眾生的眼目；縱使他無量世來持戒、布施，這些功德也會因此滅失。又說：犯了過失而必須治罰的比丘，或罰他服一個月、兩個月的苦役，或不與他說話、不與他同坐、不與他同住，或將他滅擯除名，趕出一國，乃至趕出四國之中凡是有佛法的地方。這樣治罰了這些惡比丘之後，眾多善比丘便能安穩快樂地領受佛法，因此使佛法久住而不滅。", "i": "uGAP18-2", "n": 14, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "婆論》云：「違王制故，得吉羅。」", "t": "《薩婆多論》說：違背國王所立的法制，因此犯突吉羅罪。", "i": "uGAP18-3", "n": 15, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "涅槃經》云：「若善比丘置不訶責，當知是人佛法中冤；若能驅遣治罰，是我弟子真聲聞也。」", "t": "《涅槃經》說：若有善比丘，對敗壞正法的人放任不加訶責，應知這人就是佛法中的怨家；若能加以驅逐治罰，才是我的弟子、真正的聲聞。", "i": "uGAP18-4", "n": 16, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "勝鬘經》云：「世尊！應折伏者而折伏之，應攝受者而攝受之。何以故？以折伏攝受者，令正法久住，天人充滿，惡道減少，於如來所轉法輪而得隨轉。」", "t": "《勝鬘經》說：世尊！應當折伏的就折伏他，應當攝受的就攝受他。為什麼呢？因為藉著折伏與攝受，能使正法久住，天人充滿，惡道減少，並且對如來所轉的法輪能夠隨之而轉。", "i": "uGAP18-5", "n": 17, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "十輪》云：「若鈍根眾生欲發善根，懈怠少智，忘失正念，貪著住處、四事供養，離善知識；如此眾生，令勸化料理僧事，及以佛、法、和尚、闍梨，是為安置營事福處。」", "t": "《十輪經》說：若有根性鈍劣的眾生，想要發起善根，卻又懈怠、智慧淺少、忘失正念，貪著住處以及衣服、飲食等四事供養，遠離善知識；對這樣的眾生，就讓他去勸募教化，料理僧眾的事務，以及為佛、為法、為和尚、阿闍梨辦事，這就是把他們安置在營辦事務的修福之處。", "i": "uGAP18-6", "n": 18, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "遺教三昧經》云：「若罪小者，罰令治塔寺；若中罪者，罰掃除寺；若上罪者，僧使。若十日、二十日、三十日竟無缺失，當於眾僧中懺悔。」", "t": "《遺教三昧經》說：罪輕的，罰他修治佛塔寺院；罪中等的，罰他清掃寺院；罪重的，罰他供僧眾役使。經過十日、二十日、三十日期滿，都沒有缺失過犯，就應當在大眾僧中懺悔。", "i": "uGAP18-7", "n": 19, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "夫惟尼眾，現居凡位，孰能無犯？遇緣成犯，宜依篇聚順教治罰。或飲酒相打，令輸財物，當時同和唱制，已後便即自違，又藏匿不還；由犯財故，因茲犯重，易輕翻成自累；雖知非法，猶共立制，同和故爾，此豈不由非法立制，能令正法不行，致有斯繆？", "t": "想來尼眾現今都還居於凡夫之位，誰能沒有違犯？遇到因緣而構成犯戒，就應當依五篇七聚的罪類，順隨律教加以治罰。例如飲酒、互相毆打，便令她們繳出財物；當時尼眾一同和合、唱告立制，此後自己卻隨即違犯所立的制約。又把這些財物藏匿起來不肯歸還；由於在財物上犯罪的緣故，就此把原本的輕罪換成了重罪，反而成了自己的罪累。雖然明知是非法，卻仍舊一同立制，就因為彼此同心和合的緣故而如此。這難道不是由於以非法立制，使正法無法推行，才導致這樣的錯謬嗎？", "i": "uGAP18-8", "n": 20, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "或小小之過，暫違治擯，求懺不受，緜歷歲月，益罪尤深，退道歸俗，將由此起。或令尼等收刈穀麥、斬伐草木、種植根裁；或行醫鍼灸，順方治病，求貪俗利，苟自潤身；或躬在店肆，販賣治生，搆斂酒肉，公然聚會；或受俗使役，往來媒嫁，行非犯重，和同共住；或獨行無侶，輕觸尊儀，染俗成風，不依內律。如是非法，眾宜詳可！滅法之原，無過此等，有知解者，並不合隨。\n若非法人多不許違者，好人當作自脫之法。", "t": "或者只是偶然犯了小小的過失，就被治罰擯斥，請求懺悔卻不被接受，拖延經年累月，罪過越積越深，退失道心而還俗，往往就從這裡引起。或者驅使尼眾去收割穀麥、砍伐草木、種植根苗；或者行醫針灸，依著藥方替人治病，貪求世俗的利養，苟且地圖利自身；或者親身在店鋪裡販賣營生，聚斂酒肉，公然聚會；或者接受世俗人的差遣役使，往來替人做媒婚嫁，行非法而犯了重罪，大眾卻仍與這樣的人和合共住；或者獨自行路沒有同伴，輕率地觸犯尊嚴的儀法，沾染世俗成了風氣，不依循佛法的內律。像這樣的種種非法，大眾應當詳加審察；能使正法滅亡的根源，沒有超過這些的。凡是有知見理解的人，都不應當隨順。如果行非法的人勢力眾多，不許他人違抗，如法的好人就應當採取自我脫免的做法。", "i": "uGAP18-9", "n": 21, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "僧祇》云：若非法制，應訶令止，不肯者，當說「如法欲」已起去。若眾中有力者，訶令止；否者，聽去，當語傍人言：「此非法制，我不忍可。」止得三人作，不得至四，恐彼成僧，破僧事起；故律云「不得僧舉僧」也，仍須向同意人邊說。若不作，應說「見不欲」與「護心」相應，當作是言：「彼作非法，自有業報，何關我事？譬如失火燒舍，但自脫身，焉知他事！」", "t": "《摩訶僧祇律》說：如果僧眾立了非法的制約，應當訶責使它停止；他們不肯聽從，就應當聲明「如法欲」——我只對如法的事與欲（表示同意），非法的事不與欲——說完便起身離去。如果僧眾中有具德望勢力的人，就應訶責制止；若無力訶止，便聽許自己離去，並應當對身旁的人說：「這是非法的制約，我不能認可。」但這樣表明不認可的，只許三個人作，不可達到四人，恐怕人數滿四就成了僧眾，破僧的事便由此生起；所以《四分律》說「不得僧舉僧」，不可以一個僧眾去舉治另一個僧眾。而且必須向與自己見解相同的人說。如果不這樣作，就應當說「見不欲」，表明自己見此非法而不認同，並且所說要與守護自心、但求自脫的心念相應。應當這樣說：「他們作非法的事，自有他們的業報，關我什麼事？譬如失火燒了房屋，只顧自己脫身，哪裡管得了別人的事。」", "i": "uGAP18-10", "n": 22, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "五分》云：「若作非法羯磨時，不能轉者，默然不訶，後言不可者，無犯；若作非法羯磨，不與欲而起者，無犯。」", "t": "《五分律》說：僧眾作非法羯磨時，若自己無力扭轉，當下沉默沒有訶止，事後才說不認可，不犯。若僧眾作非法羯磨，自己沒有託付同意就起身離去，也不犯。", "i": "uGAP18-11", "n": 23, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "自大聖西隱，正教東流，時經像季，日就衰羸，持犯憲章，俄爾將盡，故略而不述，指在天本。若聞說者，反被陵辱，點污淨心；兼恃勢力，害清淨人，其懷轉惡，實難挫伏，致使大教息用，遺風訛替。故律云：「應制不制，令戒毀壞，速滅法矣。」", "t": "自從大聖佛陀在西方隱滅、正教東傳以來，時代已入像法末季，日漸衰弱，持犯的法規章程，眼看就要滅盡，所以這裡省略而不敘述，其內容已指明在大本之中。若向人宣說這些，反而遭到欺凌侮辱，清淨心被玷污；對方又依仗勢力，加害清淨的人，心懷越來越兇惡，實在難以折伏。以致佛陀的大教失去作用，遺留下來的風範訛誤衰替。所以《四分律》說：應當制約的卻不制約，使得戒律毀壞，正法迅速滅亡。", "i": "uGAP18-12", "n": 24, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "然將欲治擯，今依律文，便有九種；餘八事希，兼復難行，故隱不述，默擯一種，持犯中要，應略出之。故《智論》云：「如梵天治之，色界不語為樂，欲界不愛，故違情立治，制故不共語也。", "t": "然而，若要加以治罰擯斥，依律文便有九種。其餘八種因緣稀少，而且又難以實行，所以隱略不述；只有默擯一種，是持犯中的要法，應當簡略地提出來。所以《大智度論》說：如同梵天的治罰之法——色界眾生以沉默不語為樂，欲界眾生卻不喜歡不語——因此特意違逆其情所好而建立治罰，規定不與他交談。", "i": "uGAP18-13", "n": 25, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "第四、僧食通局者：", "t": "第四門，僧食的通用與侷限。", "i": "uGAP18-14", "n": 26, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "夫身為大患，待形須濟，畜服是同，教無偏局；十方同遵，理無乖背，無主無客，是所常儀。其中飲食，凡聖共有，鳴鐘雲集，遐邇同飱。今時諸寒，屢斷僧食，苟自壅己，不兼於客；人情忌局，用心不等；傷一時眾情，塞十方僧路；傳謬後生，斯害甚矣！慳貪獨潤，惡業愈深。", "t": "這個身體本就是大患，而要維持這個身形，就必須有所資濟。蓄存衣服的規定是彼此相同的，教制上並沒有偏私與侷限；十方僧眾一同遵行，道理上不容違背；不分主人、不分客人，這才是恆常的軌則。其中的飲食，更是凡夫僧與聖者僧所共有的：鐘聲一響，大眾如雲般聚集，無論遠處近處來的都一同用餐。如今各〔寺〕卻屢屢斷絕僧食，苟且地把食物壅塞起來留給自己，不兼顧客僧。人心猜忌偏狹，存心不平等，傷害了一時大眾的情感，堵塞了十方僧人前來的道路，還把這種謬誤傳給後輩，這禍害實在太大了！慳吝貪婪，只圖滋潤自己，惡業也就愈來愈深。", "i": "uGAP18-15", "n": 27, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "報恩經》云：「知事人與客僧惜食，十九億劫生屎尿中，其形似人，無有手足。」", "t": "《報恩經》說：知事人對客僧吝惜飲食，十九億劫中投生在屎尿裡，身形像人，卻沒有手腳。", "i": "uGAP18-16", "n": 28, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "付法藏經》云：「有僧伽耶奢，大海邊見堂閣嚴飾，滿中僧眾，經行禪思，鳴稚集食，食將欲訖，爾時餚饍變成膿血，便以鉢器共相打擲，頭面破損，血流污身，而作是言：『何為惜食，今受此苦？』於迦葉佛時，同止一處，客此丘來，咸共瞋恚，藏惜飲食而不共分，以此因緣，今受斯苦。」", "t": "《付法藏經》說：有位僧伽耶奢，在大海邊看見一座堂閣裝飾莊嚴，裡面滿是僧眾，正在經行、禪思；敲響犍稚集合用餐，眼看飯食將要吃完時，那些餚饌忽然變成膿血，於是他們就拿缽器互相擲打，頭臉破裂損傷，鮮血流出沾污全身，並且說道：「當初為什麼要吝惜飲食，如今受這樣的苦！」原來在迦葉佛時，他們同住在一個地方，有客比丘來，大家都起瞋恚，把飲食藏起來吝惜，不肯一同分食；由於這個因緣，如今受這樣的苦。", "i": "uGAP18-17", "n": 29, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "僧護經》云：「是諸比丘不打犍稚，默然受用，客比丘來，不與飲食，還空鉢出，以是因緣，受火牀苦，筋肉銷盡，骨如焦炷，從迦葉佛來，受苦不息。又不打犍稚，默飲僧甜漿，恐外僧來，以惜因緣故，入地獄中飲噉融銅。」", "t": "《僧護經》說：那些比丘不打犍稚，靜悄悄地受用僧食；客比丘來了，也不給飲食，客比丘只得空著缽出去。由於這個因緣，遭受火床之苦，筋肉銷熔淨盡，骨頭像燒焦的燈炷；從迦葉佛以來，受苦不曾停息。又有不打犍稚、暗中飲用僧眾甜漿的，唯恐外來的僧人到來；因為這樣慳惜的因緣，墮入地獄之中，飲吞熔化的銅汁。", "i": "uGAP18-18", "n": 30, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "初獻佛時，上、中、下座必教白衣奉佛及僧，獻佛竟，行與僧食，不犯；若不爾者，食佛物故，千億歲墮阿鼻地獄；檀越不受前教，亦招前報，若生人間，九百萬歲墮下賤生，何以故？佛物無人能評價故。", "t": "最初獻食供佛的時候，上座、中座、下座都必須教導在家人，要一併奉上佛與僧；供佛完畢後，再將食物分給僧眾食用，這樣就不犯。若不這樣做，由於是吃了佛物的緣故，千億歲墮在阿鼻地獄；施主若不接受前面這樣的教導，也招同樣的果報；縱使生到人間，九百萬歲之中也要淪為下賤之身。為什麼呢？因為佛物沒有人能夠估定它的價值。", "i": "uGAP18-19", "n": 31, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "義問：「今時七月十五日，四輩道俗造盆獻供，隨盆衣物，未審屬誰？」\n答：「隨本主意。若將入佛法，依施主本心；若標別者，眾主尼等明解律人依經律斷，並入安居現前尼，取一比丘尼分，一分入佛。所以然者，此為安居有勞，修道有益，故佛及現前尼各得一分。故經云：『目連雖得六通，非一人力之所柰何，仰藉十方佛僧濟魂拔親，冀生善道。』獻佛及僧，意存救苦，故須僧分，不得餘人。", "t": "依義設問：現今七月十五日，出家、在家的四眾弟子造盂蘭盆獻供，隨同盆供一併布施的衣物，不知該歸誰所有？答：隨施主本來的意思。若施主是要把它歸入佛、法二寶，就依施主的本心處理；若施主另有標示指定，就由擔任眾主的比丘尼等明解律藏的人，依經律來裁斷：全部歸入在此安居的現前尼眾，再從中取出相當於一位比丘尼應得的一份，把這一份歸入佛。為什麼這樣判定？因為安居有其辛勞，修道有其利益，所以佛與現前尼眾各得一份。所以經中說：目連雖然證得六神通，這件事仍不是靠他一個人的力量就能辦成的，必須仰仗十方佛與僧的力量，救濟亡魂、拔度親人，希望他們得生善道。獻佛與供僧，本意在於救苦，所以必須有僧的一份，不能給其餘的人。", "i": "uGAP18-20", "n": 32, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "此律下文：時諸比丘分夏安居食及衣，佛言：『不應分食，聽分夏衣。』此時通兼時僧，現前施名為賞善夏勞之物，故定入佛及僧，不得隨情曲判，併入佛法及常住僧。」", "t": "《四分律》下文說：當時諸比丘分夏安居所得的食物與衣物，佛說：「不應當分食物，准許分夏安居所得的衣。」這裡的「時」通兼時僧得施與時現前施二類，都名為酬賞夏安居善行辛勞的物品，所以必定歸入佛與僧，不得隨順自己的情見曲意裁斷，把它全部併入佛物、法物以及常住僧物。", "i": "uGAP18-21", "n": 33, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "今時數見僧尼情識闇短，諳究非長，昏於聖教，親附白衣，巧詐多端，諂心求利；雖得獻物，還將入己；或有主人隱匿施物，私背客僧，屏處共分，不均夏客；如是自垢本心，來生定墮惡道，又結無知不學之罪。\n故《僧護經》云：「檀越施食，現前僧應分；持客去方分，入地獄中噉食糞尿。」\n《寶梁經》云：「佛告迦葉：營事比丘數得僧物，慳惜藏舉，或非時與，或有不與者，營事比丘以此不善根，當墮穢惡鬼中，常食糞丸。」佛告迦葉：「營事比丘寧噉身肉，終不得用三寶之物。」又云：「若有比丘或作寺主、維那，與檀越食，向白衣讒說眾僧過惡，順白衣情，不肯教詔，苟貪利養，或以隨親逐近，共相招致，不依年夏，所得之物計錢犯重。又有比丘或為寺主、維那，典掌物事，以自在力故，將眾僧飲食與曰衣賢者，自不依眾僧食，輒取僧食自食，以損僧物，死墮下賤，以力償之。」", "t": "現今常見僧尼見解昏昧淺短，不擅長研習教律，對聖教糊塗不明，卻親近依附白衣，巧詐多端，以諂媚之心求取利養；雖然得到獻供之物，卻又拿去據為己有。也有舊住的主人隱匿施物，私下背著客僧，在隱蔽處私自共分，不與夏中來到的客眾均分。這樣自己染污了本心，來生必定墮入惡道，另外還結下不學、無知的罪。\n所以《僧護經》說：檀越布施的食物，現前僧應當分；若扣著等客僧走了才分，就墮入地獄中吞食糞尿。\n《寶梁經》說：佛告訴迦葉：營辦僧事的比丘屢次得到僧物，卻慳吝愛惜，收藏起來，或不按時給與，或竟完全不給；這樣的營事比丘以此不善根，將墮在穢惡鬼之中，常吃糞球。佛又告訴迦葉：營事比丘寧可吃自己身上的肉，也絕不得使用三寶之物。\n又說：若有比丘擔任寺主或維那，把僧食拿給檀越施主，向白衣讒毀眾僧的過惡，順著白衣的心意不肯加以教導勸誡，只是苟且貪圖利養；或者隨順親厚、追逐親近的人，彼此互相招引聚攏，不按戒臘年夏的次第分物，這樣所得的東西折算成錢值，就犯重罪。又有比丘擔任寺主、維那，掌管財物事務，憑著自在支配的權力，把眾僧的飲食拿去給在家的白衣賢者，自己不依僧眾的常規受食，擅自取僧食自己吃，因此損耗僧物，死後墮為下賤之身，用勞力償還所欠。", "i": "uGAP18-22", "n": 34, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "本行集經》云：「一念之惡能開五不善門：一、惡能燒人善根，二、從惡更生惡，三、為聖人所訶，四、退失道果，五、死入惡道。」", "t": "《佛本行集經》說：一念之惡能開啟五種不善之門：一是惡能燒毀人的善根；二是從惡又再生出惡；三是被聖人所訶責；四是退失道果；五是死後墮入惡道。", "i": "uGAP18-23", "n": 35, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "佛藏經》云：「當一心行道，隨順法行，勿念衣食；有所須者，如來白毫相中一分，供諸末代一切出家弟子，亦不能盡。」", "t": "《佛藏經》說：應當一心行道，隨順正法而行，不要掛念衣食；凡有所需，如來白毫相中的一分福德，用來供給末法時代一切出家弟子，也用不完。", "i": "uGAP18-24", "n": 36, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "五分》云：「十方眾僧自有食分，依時而來，不須召喚。白衣及中，能齋亦得與食。」", "t": "《五分律》說：十方眾僧各自本有受食的一份，依食時而來即可，不必另行召喚；白衣在家人當中能持齋的，也可以給他們飲食。", "i": "uGAP18-25", "n": 37, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "十誦》、《婆論》云：「若外道來，眾僧與食，不犯，止不得自手與，以外道常伺比丘短故，開與之。若不打犍稚，名盜食。」", "t": "《十誦律》與《薩婆多論》說：若有外道來，眾僧給他食物不犯，只是不得親手遞給他；因為外道常常伺察比丘的短處，所以才作這樣的開許給食。若不敲犍稚就受食，便名為盜食。", "i": "uGAP18-26", "n": 38, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "僧祇》：「若作相已不來，無犯；雖復打鐘，而遮閉戶不通客者，亦犯。若大界內有二、三伽藍同一布薩，食時各打錘，一切莫遮，清淨無過。」", "t": "《摩訶僧祇律》說：若住眾已經作了集眾的信號，客僧不來，住眾受食就無犯；雖然打了鐘，卻遮攔緊閉門戶、不讓客僧通行的，也同樣犯盜食之罪。若一個大界內有二三座寺院，同在一處作布薩，用餐時各自敲椎集眾，對一切來者都不遮阻，這樣就清淨無過。", "i": "uGAP18-27", "n": 39, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "大集》云：「若一寺、一村，五法師住，鳴稚集僧，次第賦給，無有恡惜，不訟彼短，是名如法住大功德海。若無量破戒僧，但五人清淨如法護持佛法，愍諸眾生，功不可計。」", "t": "《大集經》說：若在一寺、一村之中有五位法師安住，鳴犍稚集合僧眾，按次第分配供給，沒有慳吝捨不得，也不議論別人的短處，這就名為如法安住於大功德海。若有無量的破戒僧，只要其中五人清淨，如法護持佛法、憐愍眾生，功德就不可計量。", "i": "uGAP18-28", "n": 40, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "此律：客比丘初至，先語僧制法式等，無過。", "t": "《四分律》說：客比丘剛到時，應先把僧團的規約法式等告訴他，這樣就沒有過失。", "i": "uGAP18-29", "n": 41, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "見論》：「若至空寺，見樹有果，應打犍稚，無者下至三拍手，然後取食，否者犯盜；飲食亦爾。若客比丘來，舊比丘不肯打磬者，客比丘應自打食者，無犯。」", "t": "《善見律毘婆沙》說：若到了空無人的寺院，見樹上有果實，應先敲犍稚；沒有犍稚的，至少拍三下手，然後才取來吃；不這樣做就犯盜。飲食也是同樣。若客比丘來了，舊住比丘不肯敲磬，客比丘應自己敲，然後受食，無犯。", "i": "uGAP18-30", "n": 42, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "僧祗》云：「若行食時，滿杓與上座，上座應斟量得徧當取，不得偏饒上座；若沙彌、淨人偏與師僧、大德者，知事人應語言平等與僧食，無高下。」", "t": "《摩訶僧祇律》說：分發飲食時，若滿滿一杓給了上座，上座應當斟酌估量，使食物足夠遍及大眾，才取自己應得的分量，不得偏私多給上座。若沙彌、淨人偏多給自己的師長、大德，知事人應告訴他：「飲食要平等地分給僧眾，不可有高下差別。」", "i": "uGAP18-31", "n": 43, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "婆論》云：「若眾僧行餅，錯得一番不還僧者，犯盜。」", "t": "《薩婆多論》說：眾僧分餅時，若錯多得了一份而不歸還僧眾，就犯盜罪。", "i": "uGAP18-32", "n": 44, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "五百問》云：「上座貪心偏食，犯墮；不病稱病，索好食得，犯重。", "t": "《五百問經》說：上座起貪心，偏多取食僧食，犯墮罪；沒有病卻謊稱有病，索求好飲食，得到了就犯重罪。", "i": "uGAP18-33", "n": 45, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "第五、入眾服儀者：此律云：「入眾當具五法：一、應以慈心；二、應自卑下，似拭塵巾；三、應知坐起法，若見上座不應安座，若見下座不應起立；四、彼至僧中不為雜說世俗事，若自說法，若請他說；五、若見僧中有不安忍，應作默然住之。」\n《智度論》云：「佛聖弟子住和合故，有二種法：一者賢聖說法，二者賢聖默然。」", "t": "第五、入眾的服飾儀則。《四分律》說：進入僧眾之中，應當具備五法：一、應以慈心相待；二、應自處卑下，如同擦拭塵土的抹布；三、應懂得坐與起的規矩——見到上座時不應安然坐著不動，見到下座時不應起身站立；四、到了僧眾中，不夾雜談論世俗之事，或自己說法，或請他人說法；五、若見僧團中有令人心中無法安忍的事，應當保持沉默而住。《智度論》說：佛的聖弟子因為安住於和合，所以有兩種法：一是賢聖說法，二是賢聖默然。", "i": "u586", "n": 46, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "夫論眾法，軌用形儀，若清淨可觀，則物生善，天龍歡喜；威儀濫惡，便辱佛法，何所巨益？故《十誦》云：「比丘衣服不淨，非人所訶。」又《涅槃》云：「譬如破戒比丘，身無威儀也。」《華嚴》云：「具足受持威儀眾法，是故能令三寶不斷，法得久住。」", "t": "說到處眾的行法，其軌則的運用與形貌威儀，如果清淨而可觀可仰，就能使眾人生起善心，天龍也歡喜；威儀若是雜濫醜惡，便辱沒了佛法，哪裡還談得上有什麼大利益？所以《十誦律》說：比丘衣服不潔淨，會被非人鬼神訶責。《涅槃經》也說：就好比破戒比丘身上沒有威儀一樣。《華嚴經》說：具足受持威儀等眾法，因此能使三寶不斷、正法久住。", "i": "u586-2", "n": 47, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "惟佛教東流，年經六百，至於自行，猶成鄙俗；又華、夷方隔，經律未學，雖剃髮似尼，無妨風俗仍在，容畜非法之服，為佛法瑕疵，荏苒流行，致成常式。", "t": "然而佛教東傳以來，已歷經六百年，說到自身的行持，卻仍然粗鄙世俗；又因華夏與外域地域相隔，經律未曾好好學習，雖然剃了髮、外表像是尼眾，世俗風習卻照舊存在。竟容許蓄存不合律制的衣服，成為佛法的瑕疵，因循流傳，以致成了慣常的樣式：", "i": "u586-3", "n": 48, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "或著俗人袍襖、褌袴、斜鞾；或髮爪鋒長，衣多聚膩；或𦘕眉假飾，雕唇注口；或脂粉塗面，志染俗情；或歌舞醼會，公然放逸；或黑白同居，緇素混雜；或食座高聲，不敬耆宿；或眾僧未出，預走爭門。列席寒心，觀徒啟齒，以此推之，豈成高尼之謂也！", "t": "有的穿著俗人的長袍、襖衣、貼身褲、套褲、斜口靴；有的頭髮、指甲留得又尖又長，衣服上積滿油垢；有的描畫眉毛作假裝飾，修飾唇形、塗點口脂；有的用脂粉塗臉，心志染著世俗情態；有的歌舞宴飲聚會，公然放縱逸樂；有的出家人與在家人同住，僧俗混雜；有的在用餐的座位上高聲喧嘩，不敬重耆老宿德；有的在大眾僧還沒出來時，就搶先奔跑、爭著出門，使同列在座的人寒心，讓旁觀的人開口譏笑。由此推究，哪裡還稱得上是高德的尼眾呢？", "i": "u586-4", "n": 49, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "《見論》云：「若多聞弟子知禁律者，見餘所用不當如法，即須打破，無損物主，不得索償。此佛勑比丘破檀尼迦非法瓦屋，亦無有罪。」義云：「恐惡法流行，染及清眾也。", "t": "《善見論》說：若是多聞的弟子、通達禁律的人，見到別人所用的物品不如法，就應當把它打破；打破的人不犯毀損他人物品的罪過，物主不得索取賠償。這就如佛敕令比丘打破檀尼迦不合律制的瓦屋，同樣沒有罪過。以義推釋說：這是恐怕惡法流行開來，連清淨大眾也被染污。", "i": "u586-5", "n": 50, "s": "第22篇　匡眾"}, {"v": "卷下", "o": "○翻淨篇第二十三", "t": "○第二十三篇 翻穢成淨", "i": "u587", "n": 51, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "此篇大門有九：一、制意，二、淨處，三、加法，四、辨過，五、翻淨，六、對緣，七、互墮，八、儉開，九、淨生。", "t": "這一篇的大綱共有九門：一、制意，制立淨地開許的用意；二、淨處，淨地的處所；三、加法，結淨地的羯磨作法；四、辨過，辨明過失；五、翻淨，翻穢成淨之法；六、對緣，面對各種因緣情況的處理；七、互墮，果實交互墮落於淨地與不淨地時的判定；八、儉開，饑荒時的開許；九、淨生，生種作淨之法。", "i": "u588", "n": 52, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第一、制意者：良由尼眾報有優劣，上、中、下差，三種區別。居上達之徒，志力精強，制令分衛，以乞自活，情標方外，不居畜積；若中、下之流，抑同上士，資力不逮，容生退道。是以大聖慈愍，見飢喪命，方開同界別結儲積，食不生罪，名之為淨；若違別就同，長己貪結，業因不淨，名之為穢。從改正名，目之為淨也。", "t": "第一，制定淨地法的用意：實在是由於尼眾的果報有優有劣，分為上、中、下三等，各有區別。居於上等通達的一類人，志向與體力精進強健，佛便制令他們行「分衛」，靠乞食養活自己；他們的心志超然於世俗之外，不從事蓄積飲食。至於中、下等的一類人，若勉強要求他們與上士相同，他們的資力有所不及，便可能退失道心。因此大聖慈悲憐愍，見到有人因飢餓而喪命，才開許在同一大界內另外結淨地，在其中儲存積聚飲食而不生罪，這就稱為「淨」。如果違背「別結」而混同於尼眾共住之處儲存飲食，增長自己的貪欲結縛，所造的業因不清淨，就稱為「穢」。由於改正了前面所說的穢而得此名，所以稱之為「淨」。", "i": "u589", "n": 53, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第二、淨地處，此門有四：一、籬牆不周淨：此律云：「半有籬障，多無籬障，都無籬障，垣牆壍柵亦如是。」二、檀越淨：一、食具是他物，故律云：「自今已去，應作檀越食，食淨人掌舉，不得自受，若有所須，隨意索取。」二、處所是他物，故律云：「若為僧作伽藍，未施與僧，雖食在中，不名有犯。」三、食及處俱是他物，不屬僧用。三、處分淨者：此律云：「若檀越、若經營比丘為僧作伽藍時，處分如是言：『某處僧作淨地。』是名處分淨。」四、白二羯磨結淨地者：義云：「謂伽藍院相周帀，比丘尼在中有宿煑過，無問久近，隨處結之，除去比丘尼然後結之。」《母論》云：「大界內無淨廚者，一切宿煑不得食，乃至藥草亦爾。」此律云：「因比丘餓死故，聽在伽藍內邊房靜處結作淨地。」《五分》云：「諸比丘欲羯磨，一房、一角、半房、半角，或中庭，通結坊內作淨地，並聽。", "t": "第二，淨地的處所。這一門分為四種：\n一、「籬牆不周淨」。《四分律》說：住處半邊有籬笆遮障、大半沒有籬笆遮障、完全沒有籬笆遮障；用土垣、牆壁、壕溝、木柵作圍障的，情形也是一樣。\n二、「檀越淨」，其中又分三種。第一種，食物本身是他人之物。所以《四分律》說：從今以後，食物應當作仍屬施主所有的「檀越食」，由淨人掌管收藏，不得自己領受、收歸己有；有所需要時，隨意索取。第二種，處所是他人之物。所以律中說：若是為僧眾建造的伽藍，還沒有布施給僧眾，即使食物放在裡面，也不算有犯。第三種，食物與處所都是他人之物，不屬於僧眾所用。\n三、「處分淨」。《四分律》說：檀越或負責營建的比丘，在為僧眾建造伽藍的時候，就這樣指定說：「某處要給僧眾作淨地。」這就叫作處分淨。\n四、「白二羯磨結淨地」。依義理說：伽藍的院牆四周圍繞完整，比丘尼住在裡面，就有食物與尼眾同處隔夜存放、在界內炊煮的宿煮過失；不論住的時間久或短，都可以隨選一處結為淨地，但要先讓比丘尼離開該處，然後才作法結淨地。《毘尼母論》說：大界之內如果沒有淨廚，凡是隔夜存放、在界內炊煮過的食物都不得食用，乃至藥草也是一樣。《四分律》說：因為有比丘餓死的緣故，才聽許在伽藍內的邊房、僻靜之處結作淨地。《五分律》說：比丘們想用羯磨結一間房、一個角落、半間房、半個角落，或中庭，乃至通結整個僧坊之內作淨地，都聽許。", "i": "u590", "n": 54, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第三、加法者：若欲作法，一切尼眾並集大界內，遙指結之，不得坐淨地中結。所以然者？以食望僧，是攝是障；以僧望僧，非攝非障。上座令一舊住比丘尼起立唱云。", "t": "第三、加法：如果要進行結淨地的作法，所有尼眾都應集合在大界之內，從遠處指著該處結淨地，不得坐在淨地當中進行結法。為什麼呢？因為以食物（淨地）對僧眾而言，淨地能攝藏食物，也能障隔僧眾（僧眾不宜坐在其中）；而以僧眾的住處對僧眾而言，既不攝藏食物，也不障隔僧眾（所以可在其中集會作法）。上座命一位舊住比丘尼起立唱言：", "i": "u591", "n": 55, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "大姉僧聽！舊住比丘尼為僧唱淨地處：於某處房內為僧作淨地。」律師問云：「僧今和合，何所作為？」答：「白二羯磨為僧作淨地。", "t": "「大姊們，僧眾請聽！我這舊住比丘尼，為僧眾唱說淨地的處所：就在某處的房舍之內，為僧眾作淨地。」\n律師問：「僧眾如今和合集會，是要作什麼事？」答：「白二羯磨，為僧眾作淨地。」", "i": "u592", "n": 56, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "大姉僧聽！若僧時到，僧忍聽，僧今於某處結淨地。白如是。", "t": "諸位大姊，僧眾請聽！若僧團的時機已到，請僧眾聽許：僧團現在要在某處結作淨地。以上的白告就是這樣。", "i": "u593", "n": 57, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "大姉僧聽！今結某處作淨地。誰諸大姉忍僧結某處作淨地者，默然；誰不忍者，說。僧已忍僧結某處作淨地竟，僧忍默然故，是事如是持。", "t": "諸位大姊，僧眾請聽：現在要把某處結為淨地。諸位大姊當中，凡是同意僧團把某處結為淨地的，就默然不作聲；不同意的，就說出來。僧眾已經同意，僧團把某處結為淨地的事已經完成。由於僧眾同意而默然的緣故，這件事就這樣確定，依此奉行。", "i": "u594", "n": 58, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "若後改轉須解劫者，律無解文，義準反結即成。", "t": "如果日後有所改動，需要解除原先所結的淨地界，《四分律》中並沒有解淨地的羯磨文；依義理推準，把結淨地的羯磨文反過來作，解界就成立了。", "i": "u595", "n": 59, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "問：「僧今和合，何所作為？」答：「解淨地羯磨。", "t": "問：僧眾現在和合集會，是要辦什麼事？答：作解除淨地的羯磨。", "i": "u596", "n": 60, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "大姉僧聽！若僧時到，僧忍聽，僧今解某處淨地。白如是。", "t": "各位大姊，請僧眾聽著：如果僧眾時機已到、僧眾認可聽許，僧眾現在解除某處的淨地。以上這樣白告。", "i": "u597", "n": 61, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "大姉僧聽！僧今解某處淨地。誰諸大姉忍僧解某處淨地者，默然；誰不忍者，說。僧已忍解某處淨地竟，僧忍默然故，是事如是持。", "t": "各位大姊，僧眾請聽：僧團現在要解除某處的淨地。諸位大姊當中，誰贊成僧團解除某處淨地的，就保持沉默；誰不贊成的，請說出來。僧團已經認可，解除某處淨地的事已經辦妥。由於僧眾認可而默然的緣故，這件事就這樣確定、依此奉行。", "i": "u598", "n": 62, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第四、辨過者：其檀越、不周二淨，無內外，晝夜同宿、內煑無過，但不得觸。若處分、羯磨二淨，通尼在內撿校，唯護明相；若共同宿，便壞食具，更須翻淨，兼有內煑。", "t": "第四、辨明過失：其中檀越淨與不周淨這兩種淨地，不分內界外界，無論白天或夜間與食物同宿、或在界內烹煮，都沒有過失，只是不得觸碰食物（否則犯惡觸）。至於處分淨與羯磨淨這兩種淨地，容許比丘尼在界內檢校照管，只須護好明相（明相出現時不得與食物同宿）；若與食物共同過夜，就壞了飲食與食具，必須重新作翻淨，而且還兼有內煮的過失。", "i": "uGAP19-1", "n": 63, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第五、翻淨者：《五分》云：「有諸木器膩不淨，以瓦石揩洗，恐破者，用沸湯淨洗。」\n《僧祇》云：「淨人行食，淨器墮比丘鉢中，尋即却者，名淨；停須臾者，不淨。若是銅器，洗淨用；木器若膩入中者，削剝却之，不可用，當棄之。」", "t": "第五、翻淨：《五分律》說，有各種木製器具油膩不淨，若用瓦片、石塊擦洗又怕弄破的，就用滾水洗淨。《僧祇律》說，淨人分送飲食時，淨器掉進比丘的鉢中，隨即取出的稱為淨，停留片刻的稱為不淨；如果是銅器，洗淨後即可使用；木器若是油膩滲入木中的，要削刮去除，若已無法再用，就應當丟棄。", "i": "uGAP19-2", "n": 64, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "《十誦》云：「若比丘尼有膩器，二、三度用澡豆洗，故不淨者，當以木刮却，然後澡豆二、三徧洗，是淨。餘有未盡者，如米、麵、油、醬等，於大僧寺及俗人家、沙彌尼、淨人處，隨多少更互博取，雖得本物，已入手，兩相捨意，故不犯。」", "t": "《十誦律》說，如果比丘尼有油膩的器具，用澡豆清洗兩三次仍然不淨的，應當用木片刮除，然後再用澡豆洗兩三遍，這樣就清淨了。其餘還有剩下未用完的東西，像是米、麵、油、醬等，可到大僧寺院以及俗人家、沙彌尼、淨人那裡，隨數量多少互相交換取用；即使後來換回原本的物品，但因為已經入手，雙方都有捨棄原物的心意，所以不犯戒。", "i": "uGAP19-2-2", "n": 65, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "故《見論》：「多比丘共一沙彌行，各自擔食，至時自分已，沙彌語比丘言：『今持我食與大德易。』得已，復展轉乃至下座；若不解者，教之亦得。」\n義準翻淨，共僧博等亦然。", "t": "因此《善見論》說，有多位比丘與一位沙彌同行，各自挑著食物；到了用餐的時候，各自把食物分好後，沙彌對比丘說：「現在拿我的食物與大德交換。」交換之後，再如此輾轉交換，直到最後一位下座比丘；如果沙彌不懂得這樣做，教導他做也可以。依此義理比照，翻淨以及與大僧等互相交換等事，也同樣如此。", "i": "uGAP19-2-3", "n": 66, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "若盆甕等器有食膩者，釜上蒸之，內外熱徹，膩出即淨；一切銅器，磨之即淨；鐵器，以火燒內，趣令膩盡；木倉櫃等，削刨泥拭；土倉窖等，隨有更拭；石器者，或以水洗，或以鎸治，亦得無殘膩。此律：得捉僧角杓、銅杓、浴牀等，則無觸淨。", "t": "如果盆、甕等器皿沾有食物油膩的，就放在鍋上蒸，待內外熱透、油膩逼出，就清淨了；一切銅製器具，加以打磨就清淨了；鐵製器具用火燒烤內部，務必使油膩除盡；木造的糧倉、櫃子等，要加以削刨並用泥擦拭；土造的倉庫、地窖等，隨其實際情況再加擦拭；至於石製器具，或者用水清洗，或者加以鑿治，也能做到沒有殘留油膩。本律中說，可以拿取僧眾的角杓、銅杓、浴床等，這樣就不會有觸污淨物的過失。", "i": "uGAP19-2-4", "n": 67, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "問：「比丘不護淨，何過耶？」\n答：依《護淨經》云：「由比丘觸僧淨食不淨故，五百歲墮餓鬼中，復五百歲墮狗中，復五百歲墮𧏙蜋中，復得人身，衣不蓋形，食不充口。」因說知事比丘觸僧器故，墮餓鬼中五百餘年，不見漿水；正欲趣廁，護廁神鬼打，不得近。《智度論》云：「沙門福田食，以不淨手觸，或先噉，或以五不淨物著中，入沸屎地獄中。」《五百問事》云：「精進知事人，以指挃僧淨器，入噉糞鬼中，恒在廁上，不能得食。」如是因緣至多，不可具述，行者慎之，不得自誤。", "t": "問：比丘不守護淨法，會有什麼過失呢？答：依據《護淨經》所說，由於比丘觸碰僧眾淨食而致不淨的緣故，將五百歲墮在餓鬼道中，再五百歲墮在狗中，再五百歲墮在蜣螂之中；之後重新獲得人身，也是衣不蔽體、食不果腹。經中接著說，知事比丘因為觸碰僧眾的器具，墮入餓鬼道中，五百多年見不到一點漿水；正想前往廁所時，遭護廁的神鬼毆打而無法靠近。《智度論》說，對於沙門福田食，若用不淨的手觸碰，或者自己先吃，或將五種不淨物放進裡面，就會墮入沸屎地獄之中。《五百問事》說，有位精進的知事人，因為用手指點觸僧眾的淨器，墮入噉糞鬼中，常待在廁所裡卻吃不到食物。像這樣的因果事緣極多，無法一一詳述。修行人應當謹慎，不可自誤。", "i": "uGAP19-3", "n": 68, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第六、對緣者：初、明惡觸者：《十誦》云：「比丘食竟，以不淨鉢及食與沙彌、白衣，洗鉢竟，還著僧器中，是名淨，一心過與，則無惡觸。」", "t": "第六、對緣。先說明惡觸：《十誦律》說：比丘用完餐後，把沾有食垢的不淨缽與剩餘食物一併交給沙彌或白衣，沙彌或白衣將缽洗淨後，放回僧團的器具當中，這就稱為清淨；只要當時一心徹底交付給對方，就沒有惡觸的過失。", "i": "uGAP19-4", "n": 69, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "僧祇》云：「若曬穀時，比丘在上行者，當脚處使淨人扟却；難事急，雖蹈無罪。必天雨無淨人時，得自遙擲物覆，捉淨甎石鎮之；忘覆食器亦爾。比丘錯把淨麨者，非故，名淨；若還放缾中，即為不淨。槃緣沒𪍿麥，為器；船在水中非器，岸上為器；車駕牛時非器，無牛者為器。若食時，或甘蔗、蘿蔔束、豆囊上，令比丘坐，不動身，亦不得問；若動、問者，一切不淨。若船、車上載諸穀，覆者，比丘得坐上，下不得名字。若小車有淨物，若取衣鉢時動車者，一切不淨，當令淨人取。應令淨人先上，比丘尼後上；若下時，比丘尼先下。", "t": "《摩訶僧祇律》說：在曬穀的時候，如果比丘要從上面走過，應當讓淨人把落腳處的穀物撥開；如果遇到危難急事，即使踩踏過去也沒有罪；若遇下雨而又沒有淨人時，可以自己從遠處拋擲覆蓋物蓋上，並拿乾淨的磚石壓住；忘記遮蓋盛食的器具時，也照這樣處理。比丘誤抓起淨麨，因為不是故意的，仍算清淨；如果又放回瓶中，就成為不淨。盤子的邊緣深到能沒過穬麥的，算作器皿。船在水中時不算器皿，在岸上時算作器皿；車輛套駕著牛時不算器皿，沒有套牛時算作器皿。如果在用餐時，有人讓比丘坐在甘蔗、蘿蔔束或豆袋上，比丘不可移動身體，也不得發問；如果移動身體或發問，一切都成為不淨。如果船或車上載著各類穀物並且已經覆蓋好，比丘可以坐在上面，但不能說出下面所載物品的名稱。如果小車上載有淨物，拿取衣缽時若使車子動搖，車上的一切淨物都成為不淨，應當讓淨人來拿取；上車時應讓淨人先上，比丘尼後上，下車時則比丘尼先下。", "i": "uGAP19-5", "n": 70, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "若在載物車中，忽即車翻，離牛者，一切不淨；若牛繩尾未離車者，名淨。」", "t": "如果在載物的車中，忽然車子翻覆而脫離了牛隻，車上的一切淨物都成為不淨；如果繫牛繩索的末端還沒有脫離車子（牛仍與車相連），就仍算清淨。", "i": "uGAP19-5-2", "n": 71, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "十誦》云：「比丘與沙彌擔食，道中食時與沙彌，沙彌還與比丘者，先不共要，得食；反此不得。飯、粥、羮器傾側，聽佐淨人，正已，不得復觸；若佐搘釜亦爾；人、驢、車、牛等負食傾側亦爾。」", "t": "《十誦律》說：比丘替沙彌挑著食物在路上走，到了吃飯時把食物交給沙彌，沙彌再轉給比丘，如果雙方事先沒有約定好，比丘就可以吃；反之則不可以。盛裝飯、粥或羹湯的器具傾斜時，聽許協助淨人扶正，扶正之後不可再觸碰；如果協助支撐鍋釜，也是如此；人、驢、車、牛等馱運食物發生傾斜時，也是如此。", "i": "uGAP19-6", "n": 72, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "此律：「若蘇油缾不覆，無淨人覆者，自手捉蓋遙擲置上。若居士持食寄比丘掌舉，後索還，與比丘者，得洗手受之。」", "t": "《四分律》說：如果酥油瓶沒有加蓋，又沒有淨人可以覆蓋時，可以親手拿著瓶蓋從遠處拋擲覆蓋在瓶上。如果居士拿食物寄放在比丘處保管，之後索回再轉送給比丘時，比丘可以洗淨雙手後領受食用。", "i": "uGAP19-7", "n": 73, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "五分》云：「若惡人以僧不淨米一把投淨米中，可分者除之，不可分者趣去一把。」", "t": "《五分律》說：如果有惡人拿一把僧團的不淨米投入淨米之中，能夠分辨的就挑除出來，無法分辨的就隨意取出一把除去。", "i": "uGAP19-8", "n": 74, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "二、自煑者：《僧祇》云：「薑湯不得自煑，以變生故；乞得冷食自溫者，不犯。若作食時，淨人小者，得捉其手，教淘、抒飯等。」", "t": "二、自煮：《摩訶僧祇律》說：薑湯不可以自己熬煮，因為會使生鮮變熟的緣故；如果乞食得來的冷食物自己加熱溫熱，不犯。製作食物時，如果淨人年紀還小，可以握著他的手教他淘米、盛飯等。", "i": "uGAP19-9", "n": 75, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "三、內宿者：《五分》云：「使淨人於不淨地洗菜，未竟，明相出者，犯。」此律：「有比丘持食來，覓淨地未得，明相出，不犯。」", "t": "三、內宿：《五分律》說：讓淨人在不淨地洗菜，還沒洗完，明相（天亮之相）就已出現，便犯（內宿）。《四分律》說：有比丘帶著食物前來，還沒找到淨地，明相就已出現，不犯。", "i": "uGAP19-10", "n": 76, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "四、內煑者：若在界內，為他者不礙私己，與他有餘，洗手受食，不犯。此律：「式叉尼得與大尼過食，不得同宿。", "t": "四、內煮：如果是在界內為他人烹煮，並不妨礙自己，給他人食用後若有剩餘，洗淨雙手後領受來吃，不犯。《四分律》說：式叉尼可以給大尼遞送食物，但不得與大尼同宿。", "i": "uGAP19-11", "n": 77, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第七、互墮者：此律云：安食具在樹上，並從根斷。若根在不淨地，枝覆淨地，果墮淨地；或為風吹、雨打、鳥獸墮者，但無人觸知，遇緣而墮，雖經明相，不成內宿，謂長足果也。若不淨地未長足來，運運重生，則無內宿，隨時而取，得入淨厨。若果菜已離本處者，隨經明相，比丘尼若知，即不得食。", "t": "第七、互墮，指果實在淨地與不淨地之間墮落的判定。《四分律》說：安放在樹上的食物，一律依樹根所在之處來判定屬淨地或不淨地。如果樹根長在不淨地，枝條卻覆蓋到淨地上方，果實掉落在淨地裡；或是被風吹、雨打、鳥獸碰落的，只要沒有人手觸碰、也沒有人知情，而是遇著因緣自然墮落，那麼即使經過明相、天色已亮，也不構成食物在不淨地過夜的內宿——這是就已經長成的果實而說的。\n若在不淨地上，果菜還沒長成以前，一直不斷地生長變易，就沒有內宿的問題，隨時採摘下來，都可以放進淨廚。至於果菜已經脫離原本生長之處的，一旦經過明相，比丘尼若知情（知道它已如此過了夜），就不得食用。", "i": "u599", "n": 78, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第八、儉開者：此律，為穀米勇貴，人民饑餓，乞食難得，為賊持去，佛憐愍故，開界內共食宿、內煑、自取食，僧俗二食，水陸兩界，並不作餘食法。舊解：尼無餘食法開；若據敬僧戒中，似尼犯足，有餘食法。今且論無者，若儉時應開七罪，謂內宿、內煑、自煑、惡觸、不受、足食、殘宿等三提四吉，兼壞生種，如水陸果子，不受而食，豈令淨耶？此律：「若時世還賤，故開食者，佛言：不得，如法治之。」《十誦》云：「若饑儉時，食竟得持殘去，語施主知。", "t": "第八，荒年饑儉時的開緣。《四分律》說：由於穀米價格騰貴，人民饑餓，乞食難得，乞到的食物又被盜賊奪走，佛憐愍的緣故，開許在界內與食物同宿過夜、在界內煮食、自己取食；不論是僧處、俗處得來的食物，或水中、陸上所生的兩類果子，都不必作餘食法。\n舊時的解釋說：比丘尼沒有「餘食法」這項開許。但若依「敬僧戒」中的文意看來，似乎比丘尼也有足食之犯，因而也有餘食法；這裡暫且依「尼眾沒有餘食法」這一說來討論。\n若遇饑儉之時，應當開許七種罪：內宿、內煮、自煮、惡觸、不受、足食、殘宿；這七罪之中，三種是波逸提，四種是突吉羅。此外還兼帶開許「壞生種」之罪：譬如水中、陸上的果子，既然可以不受而食，哪裡還要求作淨呢？\n《四分律》又說：如果時世穀價又回跌低廉，卻仍舊依這開緣而食的人，佛說：不可以，應如法治罰。《十誦律》說：饑儉之時，吃完後可以把剩餘的食物帶走，但要告知施主知道。", "i": "u600", "n": 79, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "第九、淨生者：《僧祇》云：「每食時，上座應問：『果菜淨未？無蟲否？』問答如法已，得食。維那亦爾。」", "t": "第九，淨生種的作淨法。《僧祇律》說：每次進食時，上座應當問：「果菜作淨了沒有？有沒有蟲？」問與答都如法之後，才可以吃。維那也同樣要這樣問。", "i": "u601", "n": 80, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "此律淨法有十：初五者，一、火淨，二、刀淨，三、瘡淨，四、鳥啄破淨，五、不中種淨；此五，刀、瘡、鳥三淨應去子食，不中種淨及火淨，皮子都食。", "t": "《四分律》中作淨的方法有十種。最前五種：一是火淨，二是刀淨，三是瘡淨，四是鳥啄破淨，五是不中種淨。這五種當中，刀淨、瘡淨、鳥啄破淨這三種，應當去掉種子才吃；不中種淨與火淨，則皮和子都可以吃。", "i": "u601-2", "n": 81, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "次五者，一、皮剝淨，二、㓟皮淨，三、腐淨，四、破淨，五、瘀燥淨；此五淨根種法。故律云：「水洗連根菜，即名淨。」火淨便通五種。", "t": "其次五種：一是皮剝淨，二是㓟皮淨，三是腐淨，四是破淨，五是瘀燥淨。這五種是淨根種的方法，所以律中說：用水洗連根的菜，就名為淨。而火淨這一法，則通用於五種生種。", "i": "u601-3", "n": 82, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "《僧祇》：「多果同一器，一果作淨，餘者通淨；若別器者，一一別淨。甘蔗著葉，莖莖作淨；無葉者，和束淨。」", "t": "《僧祇律》說：許多果子同放在一個器皿裡，只要對其中一個作淨，其餘的都通同成淨；若分放在不同器皿，就得一一各別作淨。甘蔗若還帶著葉，要一根一根各別作淨；沒有葉的，可以整束一起作淨。", "i": "u601-4", "n": 83, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "《明了論》云：「加行所作，如一聚果子，若未作淨者，但食皮肉，一一吉羅；若食核，一一得提。今以火觸，止得一吉羅，令一聚果子俱淨，免於多罪，豈非利益？」", "t": "《明了論》說，作淨由加行作法而成：譬如一堆果子，若沒有作淨，只吃皮和果肉，一個一個都犯突吉羅；若吃果核，一個一個都犯波逸提。如今用火一觸，只犯一個突吉羅，卻使整堆果子都成淨，免除眾多罪過，難道不是利益嗎？", "i": "u601-5", "n": 84, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "《僧祇》云：「樹果野火所燒、灰圍穀聚恐非人偷，亦名為淨。若食果核者，火淨已，聽食；若皮淨、不火淨，食核得提。」", "t": "《僧祇律》說：樹上的果子被野火燒過，以及因怕非人偷竊而用灰圍繞的穀堆，也都名為淨。若要喫果核，作過火淨後就聽許食用；若只作皮淨而不作火淨，吃果核便犯波逸提。", "i": "u601-6", "n": 85, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "《明了疏》云：「此淨法不但約一物以成，如一聚桃、李，但火一觸，餘皆成淨。此作淨體，本以為法，非使物不生，故名沙門淨。」", "t": "《明了論疏》說：這種作淨法不只就單一物體才成立，例如一堆桃、李，只要用火一觸，其餘的都成淨。這作淨之體，本來只是為了成就作法，並不是要使東西不再生長，所以名為「沙門淨」。", "i": "u601-7", "n": 86, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "問：「種、相云何別耶？」\n答：「種者，謂根、莖可種植，或雖離地，從緣種之生者，亦名為種。相者，如諸果菜及餘食餅上有青華、白毛者，名生相。", "t": "問：「種」與「相」有什麼分別？\n答：「種」是指根、莖可以種植的；或者雖然已離開土地，但隨因緣種下去仍會生長的，也名為「種」。「相」是指各種果菜以及其餘食物、餅上生出青色黴花、白色絨毛的，這就名為「生相」。", "i": "u601-8", "n": 87, "s": "第23篇　翻淨"}, {"v": "卷下", "o": "○受藥篇第二十四", "t": "第二十四篇　受取藥物", "i": "u602", "n": 88, "s": "第24篇　受藥"}, {"v": "卷下", "o": "此篇大門有六：一、藥體，二、受意，三、受法，四、說淨，五、通塞，八、重受。", "t": "這一篇的大綱分為六門：一是藥體，二是受意，三是受法，四是說淨，五是通塞，六是重受。", "i": "u603", "n": 89, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第一、藥體者，此有四：\n一、時藥者：此律有十，謂餅、麨、乾飯、魚及肉、枝、葉、華、果、細末磨食等。", "t": "第一、藥體。這有四類：\n一、時藥。《四分律》中列有十種，就是餅、麨、乾飯、魚和肉，以及枝、葉、花、果、磨成細末的食物等。", "i": "u604", "n": 90, "s": "第24篇　受藥"}, {"v": "卷下", "o": "二、非時漿者：《僧祇》云：「謂一切穀、豆、麥煑不破者，取汁而飲。諸生果汁等，要以水作淨，若器底殘水、被雨濺等，亦為淨。」《十誦》云：「若蒲桃不以火淨，汁中不以水淨，及互不淨，不應飲；俱淨，得飲。」《見論》云：「舍樓伽漿者，謂藕根漿，澄汁使清淨，得飲。」《母論》：「種種果多，食不盡，聽破汁飲；若不至初夜，變成苦酒者，不得飲，以酒勢欲成故。」", "t": "二、非時漿。《摩訶僧祇律》說：一切穀、豆、麥，煮而不使顆粒破爛的，取它的汁來飲用；各種生果的汁等，必須用水作淨；若器皿底部還有殘留的水，或被雨水濺入等，也算作淨。《十誦律》說：葡萄若不以火作淨，汁中不以水作淨，以及二者只淨其一、另一未淨的，都不應飲用；兩者都作淨了才可以飲用。《善見論》說：舍樓伽漿，就是藕根漿，把汁澄清使它清淨，就可以飲用。《毘尼母論》說：種種水果太多吃不完，允許搗破取汁飲用；若還不到初夜就已變成苦酒的，不得飲用，因為酒的勢力將要形成。", "i": "u604-2", "n": 91, "s": "第24篇　受藥"}, {"v": "卷下", "o": "義云：「若作漿法，要須汁滓相分，漉澄水清，其狀如水，方得飲之；若有濁汁與時食和，咽咽犯提。」", "t": "依義理判定：作漿的方法，必須使汁與渣滓分離，過濾澄清，清澈得像水一樣的狀態，才可以飲用；若還帶有渾濁的汁，便是與時食相和雜，每吞一口就犯一個波逸提罪。", "i": "u604-3", "n": 92, "s": "第24篇　受藥"}, {"v": "卷下", "o": "三、七日藥者：此律：「蘇、油、生酥、蜜等五種，世人所識，當食、當藥，如食飯、乾飯，不令麤現，有病因緣得非時服。」《伽論》云：「沙糖漿亦得七日受。」《僧祇》云：「此藥清淨，無時食氣，一時受，取得七日服。人有四百四病：風病百一，用油脂治；火大熱病，用酥治之；水病，用蜜治之；雜病，用上三藥治之。」《十誦》云：「石蜜不得輙噉，除五種人得食，謂遠行人、病人、食少人、不得食人、若施水處和水得噉。」《五分》：「飢、渴二時，以水和飲。」", "t": "三、七日藥。《四分律》所說的酥、油、生酥、蜜等五種，是世間人所認識的，既可當食物，也可當藥物，如同吃飯、乾飯一般資養身體，不使身體枯瘦粗惡之相顯現出來；有病的因緣時，可以在非時服用。《摩得勒伽論》說：沙糖漿也可以作七日受。《摩訶僧祇律》說：這種藥清淨，沒有夾雜時食的氣分，一次受取，可以服用七天。人有四百零四種病：風病一百零一種，用油脂治療；火大的熱病，用酥治療；水病，用蜜治療；雜病，用上面三種藥治療。《十誦律》說：石蜜不得隨便吃，除了五種人可以吃，就是遠行的人、病人、吃得少的人、得不到食物的人，以及在布施飲水之處和水調和而吃。《五分律》說：飢、渴這兩種時候，可以和水調和飲用。", "i": "u604-4", "n": 93, "s": "第24篇　受藥"}, {"v": "卷下", "o": "四、盡形藥者：《僧祇》云：「胡椒、蓽茇、薑、呵梨勒等，此藥無時食和者，頓受，病比丘尼盡形服之。」此律云：「一切苦、辛、鹹、甘等不任為食者，聽盡形服。」《見論》云：「一切樹木及草根、莖、枝、葉不任為食，並得盡形受服。」", "t": "四、盡形藥。《摩訶僧祇律》說：胡椒、蓽茇、薑、呵梨勒等，這些藥若沒有攙和時食，可以一次總受，有病的比丘尼終身服用。《四分律》說：一切苦、辛、鹹、甘等味而不堪作為食物的，允許終身服用。《善見論》說：一切樹木以及草的根、莖、枝、葉，不堪作為食物的，都可以受持而終身服用。", "i": "u604-5", "n": 94, "s": "第24篇　受藥"}, {"v": "卷下", "o": "義云：「今時多有僧尼，非時分中食於時食，何者是耶？乾棗汁、生棗汁、乳酪清漿、生藕根，或諸生果搗破不以水和澄清、稠濁飲之，或食餲糖、清飯漿等，如是之類，非時而食，咽咽犯提。", "t": "依義理判定：現今有許多僧尼在非時的時分中吃時食，哪些是呢？乾棗汁、生棗汁、乳酪的清漿、生藕根，或把各種生果搗破，不加水調和澄清，就濃稠渾濁地飲下，或吃餲糖、澄清的飯汁等。像這一類的東西在非時吃，每吞一口就犯一個波逸提罪。", "i": "u604-6", "n": 95, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第二、受意者：此門有二：一、手受，二、口受。初、手受意，《婆論》云：「有五義故制：一、為斷盜竊因緣故；二、為作證明故；三、為止誹謗故；四、為成少欲知足故；五、為生他信敬心故。」次、口受意，為防手受故，若無口受，過牛便失手受；由有此法，乃至限滿，方始法謝。又為防非時、不受、殘宿、惡觸、內煑、自煑等七罪；手受但防不受、惡觸二罪也。", "t": "第二是受藥的用意。這一門分為兩部分：一是手受，二是口受。\n先說手受的用意。《婆論》說，制定手受有五種意義：一、為了斷除盜竊的因緣；二、為了作為證明；三、為了止息誹謗；四、為了成就少欲知足；五、為了使別人生起信心與恭敬心。\n其次說口受的用意，是為了防護手受。如果不作口受，一過正午，手受就失效了；由於有口受這個法，要一直到期限屆滿，受的效力才消失。又，口受也是為了防範非時食、不受食、殘宿食、惡觸、內煮、自煮等七種罪；而手受只能防範不受食與惡觸這兩種罪。", "i": "u605", "n": 96, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第三、受法：初、受時食者：未受已前，要須識知食體，兼作普受之意，方得成受。故律云：「欲受油，錯受蘇等，並不成受。」皆須心境相當，方得名受；唯除眼暗及不喜見沙門，得置地受。\n二、受非時漿口法者：諸律雖制受服，而無受法，自下受法及說淨等，並準文義出，依行彌善。手執湯漿至一比丘尼前云。", "t": "第三是受法。首先受時食：在還沒有受之前，必須先認清所受食物的體類，並且要作普遍領受的心意，這樣受法才能成就。所以律中說：本想受油，卻錯受成酥之類，都不成受。凡是受食，都必須心中所想與實際所受的對象相符，才能稱為受。唯有眼睛昏盲看不清，以及授食的人不喜見到沙門的情形，才開許把食物放在地上領受。\n第二，受非時漿的口作法：各部律雖然規定必須先受才能服飲，卻沒有明說受的作法。自此以下所列的受法與說淨等作法文，都是依準律文的義理撰出的，依著去行就更好。手裡拿著湯飲、果漿，走到一位比丘尼面前，說道：", "i": "u606", "n": 97, "s": "第24篇　受藥"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今為渴病因緣故，此是薑蜜湯，為欲夜分已來服故，今於大姉邊受。", "t": "「大姊，請專心聽我說：我比丘尼某甲，現在因為渴病的緣故，這是薑蜜湯，為了要從現在起直到明相未出以前服用的緣故，現在在大姊面前接受。」", "i": "u607", "n": 98, "s": "第24篇　受藥"}, {"v": "卷下", "o": "若蒱桃、棃、奈諸果漿等，隨其病緣，類牒說之。若頓受，不過須臾飲盡者，不勞加法。\n三、受七日藥者。", "t": "如果是葡萄、梨、柰等各種果汁，就依照各自的病因，比照上面的受法文句，把病名、漿名替換進去而說。如果是一次受取後不超過須臾就全部喝完的，就不必再加作口受之法。第三，受七日藥的方法。", "i": "u608", "n": 99, "s": "第24篇　受藥"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今為熱病因緣故，此是酥七日藥分，為欲七日共宿服故，今於大姉邊受。」如是風病服油，冷病服蜜，雜病服石蜜等，類牒可知。\n四、受盡形藥者。", "t": "「大姊請專心憶念：我比丘尼某甲，現在因為熱病的因緣，這是酥，屬於七日藥這一類。為了要在七日之內留存過夜而服用的緣故，現在在大姊這邊受取。」其餘如風病服油、冷病服蜜、雜病服石蜜等，都比照這個格式，把病因和藥名替換進去念誦，依此類推就可以知道。\n四、受盡形壽藥：", "i": "u609", "n": 100, "s": "第24篇　受藥"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今為氣病因緣故，此是薯蕷丸盡形壽藥，為欲共宿長服故，今於大姉邊受。", "t": "大姊，請專一心念：我比丘尼某甲，現在因為患氣病的緣故，這是薯蕷丸，是盡形壽藥；為了要隔夜留存、長期服用的緣故，現在從大姊這裡領受。", "i": "u610", "n": 101, "s": "第24篇　受藥"}, {"v": "卷下", "o": "如是薑、桂及餘丸、散等，隨病因緣，類牒可解。若買藥，令俗人斷價定已，比丘尼自選，今多於本分買竟，然後遣稱已，受取，不得置地，即須對同伴尼加其口法；如其不爾，停過須臾，失受，惡觸罪生。不能如是之時，令俗人受取，持歸和搗竟，然後口受，最善。", "t": "像這樣，薑、桂以及其餘的丸藥、散藥等，都隨著各自所對治的病因，比照前面的受法文句替換藥名來念誦，可以類推而知。\n如果要買藥，先讓俗人把價錢議定；價錢定好之後，由比丘尼自己挑選，並且要比本來所需的分量多買一些；買好之後再叫人秤量，秤完了才親手受取，不可以放在地上，並且必須立刻對著同伴比丘尼加上口受之法。如果不這樣做，藥擱置超過須臾，手受就失效，惡觸的罪便隨之產生。若是無法這樣做的時候，就讓俗人把藥收下帶回去，等調和搗製完成之後再作口受，這樣最好。", "i": "u611", "n": 102, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第四、說淨者：此七日藥一種，作口法竟，偏心屬己，故須說淨，以藥體是貴，資身力強，過畜延時，無變動義；若不說淨，越過七日，便犯捨墮。餘之三藥，不具前意，不須說淨。說淨方法，如長衣法，唯云「長藥」為異。若初受藥，忘不說淨者，不成惡觸。故律下文云：「受得生薑，忘不說淨，佛言：『應放地，使淨人作淨已，自應洗手更受。』」故知忘受不成惡觸。", "t": "第四，說淨。單單七日藥這一種，作完口法之後，這藥便偏局而專屬於自己，所以必須說淨。因為這類藥本體貴重，滋養身體的效力強，而且超期畜存、時日久延也不會變質。如果不說淨，一超過七日就犯捨墮罪。其餘三種藥未能兼具前面這些條件，所以不必說淨。說淨的方法與長衣的說淨法相同，只是把詞中的「長衣」改說成「長藥」這一點差別而已。如果最初受藥時忘了說淨，並不構成惡觸罪。所以《四分律》後文說：受得生薑卻忘了說淨，佛說：應當把藥放在地上，讓淨人作淨之後，自己洗手再重新受取。由此可知，受藥時忘了說淨，並不構成惡觸罪。", "i": "u612", "n": 103, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第五、通塞者：手受為防其盜，一人受竟，通餘尼共食無罪；論其口法，亦通餘人，由其口法加他二通之藥（一者味通，二者手通），故捨與前人，受法不失。", "t": "第五、通塞：手受，即親手領受，是為了防範盜取，一位比丘尼受取完成之後，其餘比丘尼一起吃用也不犯罪。說到口受之法，同樣也通及其他人，因為口法所加的，是具備兩種「通」的藥：一是藥味相通，二是手受相通。所以把藥捨給對方之後，原有的受法並不失效。", "i": "u613", "n": 104, "s": "第24篇　受藥"}, {"v": "卷下", "o": "第六、重受者：義云：「論其手受，觸失本受，即須更受，雖重無過。若論口法，依《婆論》云：五日已還，淨人來觸，更餘不受藥來雜，更加七日法，不作二日法，正從法論，不從藥勢；六日已去，不得重加，以藥物入淨故，便隨藥勢，更不加法。若藥眾多，不知何者是本藥，應手、口二受，然後服之。若病重尼不得口受，傍人直爾為受與服，亦得。設看病尼為手、口二受，稱病人名，亦得成受。盡形壽藥，若淨人來觸，直爾手受，不須作法，以口法不失；若餘藥來雜，更口法受之。", "t": "第六，重受。依義理來說：就手受而言，藥被淨人觸碰，原先的受便失效，必須重新受取；即使一再重受，也沒有過失。就口法而言，依《薩婆多論》所說：第五日以內，若淨人來觸碰，或又攙入其他未經受取的藥，就重新加作七日法，而不是加作剩餘二日的法——這是純依所加的法來判定，不是依藥物原有的期限來算。從第六日起便不得重加，因為藥物即將轉入說淨，只能順著藥物原有的期限走完，不再加法。如果藥很多，分不清哪一味才是原本已作法的那分藥，就應重新作手受、口受兩種受，然後才服用。若病重的比丘尼無法自己作口受，旁邊的人直接替她受取、給她服用，也是可以的；即使由看病的比丘尼代作手受與口受兩種受，只要稱念病人的名字，也能成就受法。至於盡形壽藥，若淨人來觸碰，直接再作手受即可，不必重新作法，因為口法並未失效；若有其他未經受取的藥攙雜進來，就要再作口法受取。", "i": "u614", "n": 105, "s": "第24篇　受藥"}, {"v": "卷下", "o": "○訃請篇第二十五", "t": "第二十五篇　應施主之請前往受食", "i": "u615", "n": 106, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此篇大門有十一：一、簡請，二、釋非，三、訃會，四、至家，五、就座，六、淨食，七、香願，八、受食，九、食儀，十、噠嚫，十一、還法。", "t": "這一篇的大綱共有十一門：一是簡別請法，二是解釋其中的過非，三是前往赴會，四是到達施主家，五是就座，六是淨食，七是行香與咒願，八是受食，九是飲食的儀則，十是『噠嚫』，十一是返回的方法。", "i": "u616", "n": 107, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第一、簡請。此律請有二種：一、僧次，二、別請。雖開別請，然諸經律禁約者多，故《梵網》、《仁王》並廣訶不為；", "t": "第一、簡別請法\n依本律，延請有兩種：一是依僧眾次第的僧次，二是個別指定的別請。本律雖然開許別請，但諸多經律對此多有限制與禁約，因此《梵網經》、《仁王經》都廣加呵責，禁止這樣做。", "i": "uGAP20-1", "n": 108, "s": "第25篇　訃請"}, {"v": "卷下", "o": "十誦》、《善生》：雖別請五百羅漢，猶故不得名請僧福田，若能僧中請一似像惡比丘，猶得無量果報；", "t": "《十誦律》與《善生經》說：即使別請五百位阿羅漢，仍然不能稱為「請僧福田」；如果能在僧團中延請一位僅具沙門形相的惡比丘，尚且能獲得無量果報。", "i": "uGAP20-2", "n": 109, "s": "第25篇　訃請"}, {"v": "卷下", "o": "增一經》、《成論》云：「如飲海水，即飲眾流。」僧次亦爾。", "t": "《增一阿含經》與《成實論》說：「就像喝大海的水，便等於喝盡一切江河之水。」僧次請也是如此。", "i": "uGAP20-3", "n": 110, "s": "第25篇　訃請"}, {"v": "卷下", "o": "比丘應供經》云：「若我弟子有受別請，定失四果，不名比丘、道人，不名受檀越供養人，是人不得國王地上行，不得飲國王水。有五百大鬼常遮其前，是比丘七劫不見佛，不為授手，不得檀越之物；五百大神常隨其後，言：『佛法中大賊！』」佛言：「莫如外道，親近知識、國王、大臣前自唱言：『我得真道，欲受別請。』若我弟子受別請者，非佛弟子，非求道人，是空作是計，名為畜生、地獄中人，不見千佛。」", "t": "《比丘應供經》說：「如果我的弟子之中有接受別請的，必定失去四果，不能稱為比丘、道人，也不能稱為受施主供養的人。這個人不能在國王的土地上行走，不能飲用國王的水，有五百個大鬼時常擋在他前面；這位比丘七劫見不到佛，佛也不為他伸手接引，他也不能獲得施主的供物；五百位大神時常跟在他背後，稱他是佛法中的大賊。」佛又在經中說：「不要像外道那樣，在親近的熟識者及國王、大臣面前，自稱『我證得了真道』，想要接受別請。如果我的弟子接受別請，就不是佛弟子，也不是求道之人；這是徒然作這種盤算，名為畜生、地獄中人，見不到千佛。」", "i": "uGAP20-4", "n": 111, "s": "第25篇　訃請"}, {"v": "卷下", "o": "五分》：但為解脫出家者，得為僧次請，唯除犯惡戒人。", "t": "《五分律》說：凡是為了求解脫而出家的人，都可以列入僧次請中，唯獨觸犯惡戒的人除外。", "i": "uGAP20-5", "n": 112, "s": "第25篇　訃請"}, {"v": "卷下", "o": "正法念經》云：「心常念他請喚與食，此是放逸因緣。」", "t": "《正法念經》說：「心中時常掛念著別人來請喚供食，這就是放逸的因緣。」", "i": "uGAP20-6", "n": 113, "s": "第25篇　訃請"}, {"v": "卷下", "o": "十誦》云：別請有二處：一、寺上，二、施主門外。又別請人有四種：一、別請有德，二、別請耆年，三、別請親屬，四、別請主人。", "t": "《十誦律》說：別請有兩處場所：一是在寺院裡，二是在施主家門外。此外，別請的對象有四種：一是別請有德行的人，二是別請年長者，三是別請親屬，四是別請主人。", "i": "uGAP20-7", "n": 114, "s": "第25篇　訃請"}, {"v": "卷下", "o": "又僧次對別請四句：一、初僧次後成別請，謂寺上僧次差來，是僧次；至施主家，語言：「今有德師來。」稱某甲請意，即答言：「實爾！」便成別請。二、初別請後成僧次，謂寺上別請；至施主家，毀訾別請，讚歎僧次，後無別請心，故成僧次。三、前後俱別。四、俱不別。初及第三犯別眾提，二、四不犯。", "t": "又，將僧次與別請相對照，有四句分別：一、起初是僧次，後來變成別請：是指在寺院裡依僧次指派前來，這原本是僧次；到了施主家後，對方對她說「現在有德之師來了」，道出某甲想要延請的心意，受請者隨即回答「確實如此」，這就變成了別請。二、起初是別請，後來變成僧次：是指在寺院裡受到別請，到了施主家後，批評別請、讚歎僧次，使此後不再存有別請之心，因此就變成了僧次。三、前後都是別請。四、前後都不是別請。第一句與第三句犯別眾波逸提，第二句與第四句不犯。", "i": "uGAP20-8", "n": 115, "s": "第25篇　訃請"}, {"v": "卷下", "o": "別請對別眾亦有四句：一、別請非別眾，謂寺上別請來，是別請；施主門外無人可別，非別眾食。二、非別請是別眾，謂施主門外有人可別，是別眾食；謂寺上僧次請來，非別請。三、二俱別。四、二俱不別。二、三犯提，初、四不犯。", "t": "將別請與別眾相對照，也有四句分別：一、是別請，但不是別眾：是指從寺院裡受別請前來，這屬於別請；但施主家門外沒有其他人可被別開，所以不是別眾食。二、不是別請，但是別眾：是指施主家門外還有其他人可被別開，這就構成別眾食；而她們是從寺院裡依僧次請來的，所以不是別請。三、既是別請，也是別眾。四、既非別請，也非別眾。第二句與第三句犯波逸提，第一句與第四句不犯。", "i": "uGAP20-9", "n": 116, "s": "第25篇　訃請"}, {"v": "卷下", "o": "門外別者，謂施主家內先有三人，後別請門外一人，門外更有人可別，故是別請，亦是別眾食。若施主家先無比丘尼，要門外別請四人，更有人可請，別眾食。", "t": "所謂「門外別」，是指施主家裡原先已有三人，後來又個別延請門外一人，因為門外還有其他人可被別開，所以既是別請，也是別眾食。如果施主家裡原先沒有比丘尼，則必須從門外別請滿四人，且還有其他人可以延請，這才構成別眾食。", "i": "uGAP20-10", "n": 117, "s": "第25篇　訃請"}, {"v": "卷下", "o": "婆論》云：「若聚落界內無眾僧，有施主請四人已上，聽打犍稚。若不打者，設知此中乃至一比丘尼不來者，得別眾食罪；若疑有比丘尼者，不集亦犯。若打犍稚，不問有無，一切無罪。」", "t": "《婆論》說：如果聚落界內沒有眾僧，有施主延請四人以上，允許敲打犍稚；如果不敲打犍稚，假使知道這裡面哪怕只有一位比丘尼沒有來，就犯別眾食罪；如果懷疑有比丘尼而沒讓她來聚集，同樣犯罪；如果敲打了犍稚，那麼無論有沒有其他比丘尼，一概無罪。", "i": "uGAP20-11", "n": 118, "s": "第25篇　訃請"}, {"v": "卷下", "o": "又《僧祇》云：「食應作四種相：一、打犍稚，二、吹貝，三、打鼓，四、唱令。若不作四相而食僧祇食，名不清淨，名盜食僧祇食。不問界內有比丘尼、無比丘尼，不作四相，皆犯盜僧祇也。", "t": "又，《僧祇律》說：受食應當作四種相：一、敲打犍稚，二、吹螺貝，三、打鼓，四、唱令。如果不作這四種相就吃僧祇食，就稱為不清淨，稱為盜食僧祇食。無論界內有沒有比丘尼，只要不作這四種相，都犯盜僧祇罪。", "i": "uGAP20-12", "n": 119, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第二、釋非。《五百問》云：「作佛得物請比丘尼，不合食。沽酒家內，一切不得入；更有餘門者，得入；若請比丘，當持一日戒，一日不沽酒。屠兒家亦爾。」", "t": "第二，辨明不如法的情形。《五百問》說：用造佛像所得的財物設齋邀請比丘尼，比丘尼不應該吃。賣酒人家的裡面一律不得進入；如果另有別的門戶可以出入，就可以進入。若賣酒的人要請比丘應供，他自己應當持一日戒，那一天不賣酒；屠戶家也是這樣。", "i": "u617", "n": 120, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：「若來請比丘尼明日食，不得定答云『決去』，應語云：『若無緣事，當訃之。』若有請僧，應問姓名、客人舊住、巷陌，不得輙往；應先令一人，若月直、園民、沙彌在前訪問，恐試弄比丘及有留難，恐僧失食故。」", "t": "《僧祇》說：有人來請比丘尼明天吃飯，不可以肯定地答覆說「一定去」，應當說：「如果沒有其他因緣事故，就會前往應供。」若是邀請整個僧眾，應問清楚施主的姓名、他是客居還是舊住、住在哪條街巷，不可貿然前往；應先派一個人，或當月輪值的執事、或寺園的淨人、或沙彌，先到那裡查訪，因為怕有人戲弄比丘，或遇上阻留為難的事，怕僧眾因此吃不到飯的緣故。", "i": "u617-2", "n": 121, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《十誦》云：為知請故，須立維那。《出要律儀》翻為寺護，又云悅眾，本音婆羅，此云次第也。", "t": "《十誦》說：為了掌管受請的事務，必須設立維那一職；《出要律儀》把它譯為「寺護」，又譯作「悅眾」；原音是「婆羅」，這裡的意思是「次第」。", "i": "u617-3", "n": 122, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《五百問事》云：「受別請已，遣人代去，主人意無在者得，若嫌者墮。」《婆論》云：「被請人與僧同去，不白先入者墮；經營知事人在僧後到者墮；食未嚫去者墮；餘人私行，直報同伴得。」", "t": "《五百問事》說：已經接受了別請，卻派人代替自己去，若施主心裡不介意，就可以；若施主嫌責不滿，就犯墮罪。《婆論》說：受請的人與僧眾一同前往，不先稟白就自己先進施主家門的，犯墮罪；營辦事務的知事人落在僧眾之後才到的，犯墮罪；齋食之後，施主還沒有行嚫施、僧眾還沒有作咒願就先離去的，犯墮罪；其餘的人若要私自先行，只要直接告知同伴，就可以。", "i": "u617-4", "n": 123, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：「若念至精舍當食，若過餘處食，悔過；若值彼僧受請隨去，無犯。」", "t": "《僧祇》說：心裡打算到某精舍才吃飯，若走過了那精舍而在別處吃，就犯悔過罪；若正好遇到那精舍的僧眾受請，隨著他們同去，無犯。", "i": "u617-5", "n": 124, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《十誦》、《婆論》云：「檀越請僧食，僧次未到，自云『我應去』，故妄語提；若得食，計食犯重。」《十誦》云：「不請自來，吉羅。」", "t": "《十誦》《婆論》說：施主請僧眾吃飯，依僧中次第輪請還沒輪到自己，卻自稱「應該我去」，這是故意妄語，犯波逸提；若因此得到飲食，就按所受飲食的價值計算，犯重罪。《十誦》說：沒有受請而自己前來受食，犯突吉羅。", "i": "u617-6", "n": 125, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《鼻奈耶》云：「因饑儉請一二人故，多人惱亂施主，提；為病僧事、作衣事故，不犯。」", "t": "《鼻奈耶》說：因為饑荒歉收，施主只請一二人，若多人前往惱亂施主，犯波逸提；若是為了病僧的事、作衣的事而去，就不犯。", "i": "u617-7", "n": 126, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：「得為俗家設會、張幔及設供具，唯不得與男子共舉物。」《五分》云：「白衣應借僧臥具。」", "t": "《僧祇》說：比丘尼可以為在家人家辦齋會而張掛帷幔、擺設供具，只是不得與男子共同抬舉物品。《五分》說：在家人設會時，應向僧眾借用臥具。", "i": "u617-8", "n": 127, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《見論》云：「沙彌雖未受具，亦入比丘數。」《涅槃經》云：「乃至未受十戒，亦得受請。", "t": "《見論》說：沙彌雖然還沒受具足戒，也算入比丘的人數之內。《涅槃經》說：乃至連十戒都還沒受的人，也可以受請。", "i": "u617-9", "n": 128, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第三、訃會者。此律云：「若欲受請，應往眾僧常小食、大食處住。若檀越白時到者，上座應在前行，如鴈行而去，諸比丘應偏露右肩在後行。若有佛、法、僧、病比丘事者，當白上座在前去。必於眾中有命、梵等難，若問不問，聽去。若上座道行大小便，應待來，然後如前去也。", "t": "第三是赴會。《四分律》說：如果想要接受邀請，應先到僧眾平常用早粥、正餐的地方停留等候。施主前來禀告時間已到時，上座應走在前面，大眾像雁群飛行那樣依次成列而行；諸比丘應偏袒右肩，跟在後面走。若有佛事、法事、僧事或病比丘的事務要辦，應禀白上座後，走在前面先行前往。倘若在大眾中遇到危害生命、危害梵行等危難，不論有沒有禀告上座，都聽許離去。如果上座在途中去大小便，應等他回來，然後照原先的次序前往。", "i": "u618", "n": 129, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第四、至請家者。《十誦》云：「到食處，應默然一心，淨持威儀，生他善心，當除入坐。」", "t": "第四、到了施主家。《十誦律》說：到了受食的地方，應當默然專心，清淨地守持威儀，使旁人生起善心，應當緩緩進入、緩緩坐下。", "i": "u619", "n": 130, "s": "第25篇　訃請"}, {"v": "卷下", "o": "義云：若至請家，未安佛座及聖僧座，尼眾不得在先坐，當令先安諸經像在高顯處，極使清淨，後鋪聖僧座。其法乃有五卷，即梁武帝對中國三藏出之，文廣不錄。今依《請賓頭盧經》云：「預宿請，在高顯處敷設虗輭物為座，我若來時，坐處有相。」今時僧尼多慢此法，輕辱聖儀，特乖佛教，既自無敬，亦令俗士不虔三寶，滅法之原，由今上座。", "t": "依義理說：到了施主家，若還未安好佛座與聖僧座，尼眾不得先坐。應先讓人在高而顯眼的地方安放經卷與佛像，務必使那裡極為清潔，然後才鋪設聖僧座。安設聖僧座的儀法共有五卷之多，是梁武帝與中國三藏法師當面問答而撰出的，文字繁廣，這裡不錄。現今依《請賓頭盧經》所說：要預先在前一晚啟請，在高顯處鋪設鬆軟之物作為座位；「我若來時，坐處有相」——我若前來，座位上會有相狀顯現。現今的僧尼大多輕慢這個法式，輕辱聖者的儀軌，極為違背佛的教敕；自己既無恭敬，也使世俗人對三寶不虔誠。滅法的根源，正出在現今的上座身上。", "i": "u619-2", "n": 131, "s": "第25篇　訃請"}, {"v": "卷下", "o": "從此已下，更採經律補闕前文，文雖不次，於理弗乖。若敷聖僧座時，堪容一人大坐處，亦令施主依時宿請，其座上必須淨潔，勝於僧座。仍不得刺華、散華在上，又不得彩𦘕雕飾，相同於佛。其座高卑，不得越過尺六，還如凡座無異。亦不得用常住僧槃椀盛食置前，此唯得獻華而已；若用鉢盂、銅椀，通及化、報，於理如法。", "t": "從這裡以下，又另外採集經律來補足前文的缺漏；文句雖不依原有次第，但於義理並無違背。鋪設聖僧座時，要寬大到足以容一人舒展而坐，也要讓施主按時在前一晚預先啟請。座位上必須潔淨，勝過一般僧眾的座位；仍不得在座上刺繡花紋、散落花朵，也不得彩繪雕飾，弄得與佛座相同。座位的高低不得超過一尺六寸，就與一般凡僧的座位沒有兩樣。也不得拿常住僧的盤、碗盛食物擺在座前，那些器皿只能用來獻花而已。若改用缽盂、銅碗盛食，則化身（佛像）與報身（聖僧）都通用，在道理上是如法的。", "i": "u619-3", "n": 132, "s": "第25篇　訃請"}, {"v": "卷下", "o": "所以同凡者，此賓頭盧雖是聖僧，報身猶存，佛制令三天下每日訃供，又持戒之時同凡僧無異，豈得破戒處高，兼觸僧淨器？", "t": "之所以與凡僧同等看待，是因為這位賓頭盧雖是聖僧，報身卻仍然存在，佛制令他每天到三天下（東、南、西三洲）赴供；而且他持戒時也與凡僧無異，怎能違背戒制而處身高座，又動用僧眾的淨器呢？", "i": "u619-4", "n": 133, "s": "第25篇　訃請"}, {"v": "卷下", "o": "聖僧錢還入聖僧用，若有餘長，將入作聖座、鉢盂、銅椀、匙筯、食巾、廟屋、燈燭等諸雜供養；但不得將入常住僧，及入私己用。亦不得造聖僧形像，置上座食堂頭；儻賓頭盧報身自來訃供，豈得推却素形而坐？亦不得將聖僧物，作餘聖僧阿難、迦葉等形。何以故？以別屬物，不得互用故。故律云：「許此處，不得異用也。", "t": "屬於聖僧的錢，仍要用在聖僧身上。若有剩餘，就拿去製作聖僧座、缽盂、銅碗、湯匙、筷子、食巾、廟宇房舍、燈燭等種種供養之物，但不得挪給常住僧，也不得挪作私己之用。也不得造聖僧的形像，安放在食堂上首的座位處；倘若賓頭盧以報身親自前來赴供，難道要他推開那尊塑像才坐嗎？也不得拿聖僧的財物，去造其他聖僧如阿難、迦葉等的形像。為什麼呢？因為各別有所歸屬的財物，不得互相挪用。所以律中說：「許此處不得異用」——許給此處的物，不得挪作別處之用。", "i": "u619-5", "n": 134, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第五、就座者。此律云：菩提王子請佛，從於階下布衣，令佛蹈上過，世尊不受，令却之，為未來比丘故。", "t": "第五，就座。\n《四分律》說：菩提王子請佛應供，從臺階下鋪設衣布，要讓佛踏著布走過去；世尊不接受，叫人把布撤去，這是為了將來比丘的緣故。", "i": "u620", "n": 135, "s": "第25篇　訃請"}, {"v": "卷下", "o": "又往食處，不應雜亂叢聚而住，應隨次坐；上座入座已，應看中座、下座，勿令不如法、不善覆身，若有者，彈指令覺，若遣人語知，好如法坐；中、下座以去，互看亦爾。", "t": "又，前往受食之處時，不應雜亂地成群聚站，應依次第就座。上座入座之後，應察看中座、下座的人，不讓他們坐得不如法、或沒有把身體遮覆好。若有這種情形，就彈指使他察覺；或派人告知，要他好好如法地坐。中座、下座以下，也同樣彼此互相察看。", "i": "u620-2", "n": 136, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：「不好覆身坐者，謂著細生疎衣，形體露現，摩訶羅坐。尼坐不正，不待語，恐其慚恥，應作方便，遣令取物；若婬女故作者，當自避去。」", "t": "《摩訶僧祇律》說：所謂坐時沒有把身體遮覆好，是指穿著細薄而織紋稀疏的衣服，使身形顯露出來。若是年老愚鈍的摩訶羅比丘坐〔不正〕，應直接出言糾正；若是尼眾坐姿不正，則不必當面直說，怕她羞愧難堪，應設個方便，差她去取東西，使她起身。若是淫女故意如此的，就應自己避開離去。", "i": "u620-3", "n": 137, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律：至請家，彼此相問年歲大小訖坐；若恐日時欲過，聽上座八人尼次第坐，餘者隨坐。", "t": "《四分律》說：到了施主家，彼此互問戒臘長幼，問完才就座；如果擔心過午時限將至，就開許上座八位比丘尼依次第而坐，其餘的人隨意就座。", "i": "u620-4", "n": 138, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《五百問事》云：「若共師並坐，更無別處者得，不得同槃食。」《沙彌威儀經》云：「若共師連坐飯，當離師六尺。」", "t": "《五百問事》說：若與師父並肩同坐，再沒有別的地方可坐，是可以的；但不得與師父同一盤器進食。《沙彌威儀經》說：若與師父連席而坐吃飯，應當距離師父六尺。", "i": "u620-5", "n": 139, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律云：不應故在後往食上，令諸比丘起；見來亦不須起。若未來者，比坐開處。", "t": "《四分律》說：不應故意晚到用餐之處，讓眾比丘起身；已坐的人見他來了，也不必起身；對於還沒到的人，鄰座應空出位置。", "i": "u620-6", "n": 140, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：「若有可笑事，上座應語言：『云何聖毗尼中，出齗現齒，呵呵而笑？當忍之，起無常、苦、空、無我、死想！』若不可止，當以衣角遮口，徐徐制止；身不定者，當動手足，乃至折草，漸漸自制。」", "t": "《摩訶僧祇律》說：若遇到可笑的事，上座應說：「怎麼可以在聖律之中露出牙齦牙齒、呵呵大笑呢？」應當忍住，生起無常、苦、空、無我與死亡之想。若止不住，就用衣角遮住口，慢慢地制止。身體安定不下來的，應當動動手足，乃至折弄草莖，漸漸自我克制。", "i": "u620-7", "n": 141, "s": "第25篇　訃請"}, {"v": "卷下", "o": "義云：若至死亡之家，禁慎諠笑，不得妄談世論，致俗譏訶。", "t": "依義理說：若到有死喪的人家，要嚴禁喧嘩嬉笑，不得胡亂談論世俗言論，招致世俗人的譏嫌訶責。", "i": "u620-8", "n": 142, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《五分》云：「若至請處，外有客比丘，不得入，語主人聽入；不許者，語云：『與我食分，自共等食。』又不許者，應自語委知，僧坊有食，可往彼去，然後乃食。」", "t": "《五分律》說：到了受請的地方，若門外有客比丘不得進入，應告訴主人讓他們進來；主人不答應的，就說：「把我的那分食物給我，我自己與他們平分共食。」若還是不答應，就應親自告知那些客比丘，讓他們清楚知道僧坊裡有飯食，可以到那裡去；然後自己才進食。", "i": "u620-9", "n": 143, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《婆論》云：「通集門外比丘一處，喚一大者入，更餘不集者亦喚入之；雖打楗稚，終須不遮，方得清淨。」", "t": "《薩婆多論》說：應把門外的比丘全部集合到一處，喚一位戒長者進去；其餘沒有集合到的，也要喚他們進來。雖然已經打過集僧的楗稚，終究必須不加遮擋排除，才算清淨。", "i": "u620-10", "n": 144, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《長阿含經》云：「世尊計會，常在眾中坐，左面比丘，右面清淨士也。", "t": "《長阿含經》說：世尊赴齋會時，總是坐在大眾當中，左面是比丘，右面是清淨的信士。", "i": "u620-11", "n": 145, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第六、淨食者。此律云：上座應問云：「果菜淨未？」若言未淨，令淨。《僧祇》云：上座當知誰看房、看病等，應語與食；若檀越惜者，應語：「長壽，法應與，不得不與。」若日晚者，應先發遣令去也。", "t": "第六、淨食：《四分律》說：上座應當問：「果菜作淨了沒有？」如果回答說還沒有作淨，就讓人作淨。《摩訶僧祇律》說：上座應當知道有哪些人因為看管房舍、照顧病人等而未能來赴供，應該告訴施主分給他們食物。如果施主捨不得，應當對他說：「長壽（對施主的稱呼）！依法應當給，不能不給。」如果天色已晚，怕過了用餐時限，就應先打發人把食物送回去給他們。", "i": "u621", "n": 146, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第七、行香呪願。《增一》云：有設供者，手執香鑪而白時至，佛言：「香為佛使，故須之也。」《五百問事》、《三千威儀經》云：「不得立受香。」因比丘受香，女觸其手，欲心發退道，佛言：「若立受，吉羅。」《十誦》云：「為諸天聞唄喜故，開唄。」此律：佛受賈客麨已，然後呪願。《辯意長者子經》云：食前呪願。《僧祇》云：「上座應知前人所施，當為應時呪願；若不能者，次座應說；又不能者，乃至下座；都無者，並得罪。」《雜寶藏經》云：「諸比丘若說法呪願，當解時宜憂悲喜樂，知得，不得妄說。", "t": "第七、行香與咒願。\n《增一阿含經》說：有設供齋的人，手執香爐稟白「時至」，也就是宣告供食的時間已到。佛說：香是佛的使者，所以設供時必須用香。\n《五百問事經》與《三千威儀經》說：不可以站著接受行來的香。起因是有比丘受香時，女人碰觸到他的手，他欲心生起，因而退失道心。佛說：若站著受香，犯突吉羅罪。\n《十誦律》說：因為諸天聽聞唄讚會歡喜，所以開許唱唄。\n《四分律》記載：佛陀接受商人供養的炒麥粉之後，才作咒願。《辯意長者子經》則說：在進食之前作咒願。\n《摩訶僧祇律》說：上座應當明白施主所布施的是什麼，為他作契合當時情境的咒願；上座若不能作，就應由次座來說；次座又不能作，就依次往下直到下座；若全眾都沒有人能作，大眾都得罪。\n《雜寶藏經》說：眾比丘若要說法、作咒願，應當懂得切合時宜，分辨場合是憂悲還是喜樂，知道什麼該說、什麼不該說，不可胡亂妄說。", "i": "u622", "n": 147, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第八、受食者。若欲受食，先量己身德行優劣，然後受食，不得自大，為施所墮。《婆論》云：「如農夫作者，是功用果，非威勢果；食其子肉者，是威勢果，非功用果。」", "t": "第八是受食。想要接受飲食供養時，應先衡量自身的德行修持是優是劣，然後才受食；不可自高自大，反而被布施所拖累而墮落。《婆論》說：就像農夫耕種勞作，所得的是功用果，不是威勢果；而吃用他所種穀實的人，所得的是威勢果，不是功用果。", "i": "uGAP21-1", "n": 148, "s": "第25篇　訃請"}, {"v": "卷下", "o": "僧祇》云：「告諸比丘，計此一粒米，百工乃成，奪其妻兒之分，求福故施，云何棄之？」《十誦》云：「應觀是食難消、難辦。」《母論》云：「每得食時，應生厭心，為存身命故。又受人信施，不如法用，入三塗中受大重苦；若不受苦報者，食他信施，即破腹出，衣即離身。若前人無善而施者，能施、所施二俱為施所墮。」《智度論》：食為行道，不為益身，如養馬、養猪無異。《伽論》云：「若得食時，口口作念；得衣時，著著作念；入房時，入入作念。若鈍根者，初得衣食房舍，總作一念。」", "t": "《僧祇律》說：佛告訴眾比丘，算來這一粒米，要經過百般工夫才能成就；施主是減奪妻子兒女的分額，為了求福才拿來布施，怎麼可以隨意丟棄呢？《十誦律》說：應當觀察這飲食難以消受，也難以備辦。《毗尼母論》說：每次得到飲食時，都應生起厭離之心，只是為了維持身命才吃。又說：接受了他人的信施卻不如法使用，就會墮入三惡道中，受極重的苦；假使不受這樣的苦報，吃了別人的信施，食物也會破腹而出，衣服也會離身而去。如果對方沒有善德，卻仍布施給他，那麼能布施的人與受布施的人，兩者都被這布施所拖累而墮落。《大智度論》說：飲食是為了行道，不是為了滋益身體；若只為養身而吃，就和養馬養豬沒有兩樣。《摩得勒伽論》說：得到飲食時，每一口都作念；得到衣服時，每一次穿著都作念；進入房舍時，每一次進入都作念。若是根機遲鈍的人，就在最初得到衣食房舍時，總合起來作一次念。", "i": "uGAP21-2", "n": 149, "s": "第25篇　訃請"}, {"v": "卷下", "o": "義云：初欲食時，先奉三寶、六道眾生，已後當食。口口作念，攝受作三歸之意：初下一匙飯時，願斷一切惡盡；入第二匙時，願修一切善法滿足；入第三匙醬菜時，所作功德迴施羣生，普共成佛。此則口口受得菩薩三聚淨戒，豈非大益耶？若不能口口作念，前總作一念已，然後食之，亦得。", "t": "依義理說：起初要吃的時候，先供奉三寶以及六道眾生，之後才吃。每一口都作念攝受，其中含有作三歸依的意思。最初將第一匙飯送入口中時，願斷盡一切惡；送入第二匙時，願修一切善法圓滿具足；送入第三匙醬菜時，將所作的功德迴施給一切眾生，願彼此共同成佛。這樣每一口都受得菩薩的三聚淨戒，難道不是極大的利益嗎？如果不能每一口都作念，先在前面總合作一次念，然後再吃，也是可以的。", "i": "uGAP21-3", "n": 150, "s": "第25篇　訃請"}, {"v": "卷下", "o": "見論》云：「若人施佛食，誰合得食？若有侍佛僧，得食；無僧，白衣侍佛亦得食。」此律云：「供養佛塔，治塔人得食。」《增一》云：「施中上者，不過法施；業中上者，不過法業；恩中上者，不過法恩。又施畜生獲福百倍，施犯戒人獲福千倍。」", "t": "《善見律毗婆沙》說：有人布施供佛的食物，誰有資格吃呢？如果有侍奉佛的僧眾，就由僧眾吃；沒有僧眾時，侍奉佛的白衣也可以吃。《四分律》說：供養佛塔的食物，修治佛塔的人可以吃。《增一阿含經》說：布施之中最上等的，沒有超過法施的；事業之中最上等的，沒有超過法業的；恩德之中最上等的，沒有超過法的恩德。又，布施給畜生，能獲得百倍的福報；布施給犯戒的人，能獲得千倍的福報。", "i": "uGAP21-4", "n": 151, "s": "第25篇　訃請"}, {"v": "卷下", "o": "涅槃經》云：因曠野鬼，為受不殺戒已，告鬼言：「我今當勅聲聞弟子，隨有佛法處，悉施汝食；若有住處不能施者，即是天魔徒黨，非我弟子。」", "t": "《涅槃經》說：佛因曠野鬼的因緣，為牠授了不殺生戒之後，告訴鬼說：「我現在應當敕令聲聞弟子，凡是有佛法的地方，都要布施食物給你。若有住處不能布施的，那就是天魔的徒黨，不是我的弟子。」", "i": "uGAP21-5", "n": 152, "s": "第25篇　訃請"}, {"v": "卷下", "o": "五分》云：「若與乞兒、鳥、狗等，應量己分內減與，不得取外施。」《愛道尼經》云：「出眾生食，如指甲大。」《智度論》云：「鬼神得人一口食，而千萬倍出也。」", "t": "《五分律》說：若要給乞丐、鳥、狗等食物，應當酌量從自己分內的食物中減出一些來布施，不得取用分外的施物。《愛道尼經》說：拿出來施給眾生的食物，應如指甲般大小。《大智度論》說：鬼神得到人布施的一口食物，就能增廣為千萬倍。", "i": "uGAP21-6", "n": 153, "s": "第25篇　訃請"}, {"v": "卷下", "o": "中阿含經》云：「若死人布施祭祀者，若生入處餓鬼中者得，餘趣不得，由各有活命食故。若親族不生入處中者，但施自得其福，乃至施主生六趣中，施福常隨。以持戒但得人身，必須餘福助報。」《往生經》云：「以亡人衣物作福，死者七分獲一。」", "t": "《中阿含經》說：為死人布施祭祀，如果亡者投生到餓鬼趣中，就能得到所祭的食物；投生在其餘諸趣的則得不到，因為各趣都有各自維生的食物。若親族沒有投生到餓鬼趣中，那就只是布施者自己得到這份福報。乃至施主將來投生到六趣之中，布施的福報也常隨不離。因為持戒只能感得人身，必須另有其餘的福德來資助果報。《往生經》說：用亡人的衣物來修福，死者在七分之中只獲得一分。", "i": "uGAP21-7", "n": 154, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律云：比丘得食便食，為俗譏責，佛令唱等供已，然後食。《僧祇》：待唱等供，然後食；若時欲過，隨食無罪。《十誦》云：「從今上座待唱，徧聞等供聲，一切僧共食。」《五分》云：「尼至請處，未唱隨意食，口口提，下二眾吉。」", "t": "《四分律》說：比丘得到食物就吃，被世俗人譏嫌責備，佛便規定要先唱「等供」，然後才進食。《僧祇律》說：要等唱過「等供」才吃；若日中時限將過，隨各人先吃也沒有罪。《十誦律》說：從今以後，上座要等待唱「等供」，等到「等供」的聲音各處都聽到了，一切僧眾才一同進食。《五分律》說：比丘尼到了受請的地方，還未唱「隨意食」就吃，每一口犯波逸提；下二眾犯突吉羅。", "i": "uGAP21-8", "n": 155, "s": "第25篇　訃請"}, {"v": "卷下", "o": "增一經》云：諸王設供，自手行食，庶士同之。此律：若請二部僧，先與比丘，恐日過者，一時與之。", "t": "《增一阿含經》說：諸王設供時親手行食，一般士庶百姓也同樣如此。《四分律》說：若施主請二部僧，本應先給比丘；若怕日中時限將過，來不及先後供食，就同時給兩眾。", "i": "uGAP21-9", "n": 156, "s": "第25篇　訃請"}, {"v": "卷下", "o": "僧祇》云：「食時應護右手，當以左手受飲食器，注唇，不得深含椀緣，又不得觸著額鼻；及飲盡，留少許，於口飯處潟棄之，次與下座沙彌。食上閙亂，恐壞俗信，以水浣灑者，不犯弄水罪。」《十誦》云：「食著手，不得振卻，應拾取之。」《僧祗》云：「不得㗘㗱作聲食。」《鼻奈耶律》云：「不得縮鼻食。", "t": "《僧祇律》說：進食時應當護好右手，要用左手接取盛飯食與飲水的器皿；飲器就著嘴唇，不得深深含住碗緣，碗緣也不得碰到額頭和鼻子；喝到將盡時應留下少許水，在就口飲過之處倒棄掉，然後依次傳給下座和沙彌。不得在食桌上喧鬧擾亂，以免破壞俗人的信心；用水沖洗潑灑的，不犯弄水的罪。《十誦律》說：食物黏在手上，不得抖甩掉，應當把它拾起來。《僧祇律》說：不得咂嘴嚼食出聲。《鼻奈耶律》說：不得皺縮著鼻子吃東西。", "i": "uGAP21-10", "n": 157, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第九、食法者。《僧祇》云：「上座應徐徐食，不得速竟，住看年少，勿令狼狽、食不飽滿，應相望看之，乃至待行水、隨順呪願已，然後乃止。」又云：「居士飯僧訖，遺餘食料理與比舍。」《婆論》云：「出家僧尼、白衣等，齋訖不用澡豆、末灰、巨摩等漱口，皆不成齋法。如過去有比丘，字蓮提，六十歲持齋戒不闕，唯一日用巨摩、豆屑等成齋，若不爾者，皆不成齋。」若依此律，但云「知住時、知坐時、知臥時」，於四威儀中，隨一時食五正食足，便成齋，不論澡豆。", "t": "第九，食法。《摩訶僧祇律》說：上座應當慢慢地吃，不可自己很快吃完，就停在那裡看著年少比丘，使他們倉促窘迫、吃不飽。上座應留意看顧年少者進食的情形，乃至一路相待，直到行水洗手、隨順作完咒願之後，才可停止相待而離席。\n《摩訶僧祇律》又說：居士供僧飯食完畢，所剩下的食物，應收拾料理好，送給鄰居。\n《薩婆多論》說：出家的比丘、比丘尼以及在家人等，齋食完畢後，若不用澡豆、末灰、巨摩（牛糞）等漱口，都不算成就齋法。例如過去有一位名叫蓮提的比丘，六十年持齋戒不曾缺漏，卻只有用牛糞、豆屑等漱口的那一天才算成齋；若不這樣做，就都不算成齋。\n若依本《四分律》，只說「知住時、知坐時、知臥時」——知道站立、坐、躺臥各自的適當時宜；在行、住、坐、臥四威儀中，隨於任何一種威儀吃五種正食（飯、麨、乾飯、魚、肉）而飽足，便算成齋，並不講究用澡豆漱口。", "i": "u623", "n": 158, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第十、噠嚫者。《雜阿含經》云：佛及比丘食已默去，檀越生疑；佛令上座為說大嚫，乃至一偈云：「若為利故施，此利必當得；若為樂故施，後必得快樂。」", "t": "第十，噠嚫，即食後的咒願說法。《雜阿含經》說：佛陀與比丘們應供食畢，默默離去，施主因此心生疑慮；佛便令上座為施主宣說大嚫，乃至只說一首偈也好，偈中說：如果是為了求得利益而布施，這利益必定能獲得；如果是為了求得安樂而布施，日後必定得到安樂。", "i": "u624", "n": 159, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律：粥初出釜，畫不成字者無犯，厚便是正食，食足已後更食者，僧提、尼吉。又施粥得五事善：一、除飢，二、除渴，三、消宿食，四、大小便調適，五、除風患。", "t": "《四分律》說：粥剛從鍋裡取出時，稀得在上面畫不成字跡的，喝了無犯；濃厚的粥便屬於正食，已經足食之後再吃，比丘犯波逸提，比丘尼犯突吉羅。又說布施粥有五種好事：一是除飢，二是除渴，三是消化宿食，四是大小便調適，五是除去風患。", "i": "u624-2", "n": 160, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《僧祇》云：施粥得十利益：「持戒清淨人所奉，恭敬隨時以粥施；十利饒益於行者，色力壽樂辭清辨；宿食風除飢渴消，是名良藥佛所說；欲得人天長壽樂，應當以粥施眾僧。」", "t": "《摩訶僧祇律》說：布施粥能得十種利益。偈說：持戒清淨的僧眾為人們所尊奉，應當隨時恭敬地以粥布施他們；有十種利益饒益修行的人，就是氣色、體力、壽命、安樂、言辭清晰、辯才，以及消除宿食、除去風患、消除飢餓、止息口渴。這是佛所說的良藥；想獲得人天長壽安樂的人，應當以粥布施眾僧。", "i": "u624-3", "n": 161, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律：若上座不能為檀越說法呪願，語能說者作；若不語、不受，並結有罪。若說大嚫時，上座四人相待，餘者聽去。", "t": "《四分律》說：上座若不能為施主說法咒願，應告知能說的人，讓他去做；若上座不告知，或能說的人不肯接受，兩者都結罪。宣說大嚫時，上座四人應留下相待，其餘的人聽許先離去。", "i": "u624-4", "n": 162, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《三千威儀經》云：「未飯不得為人說法。」《婆論》云：要食後說法，有四種益：一、為消信施故，二、為報恩故，三、令生歡喜心、善根成就故，四、為在家人應行財施、出家人宜行法施故。", "t": "《三千威儀經》說：尚未吃飯時，不得為人說法。《薩婆多論》說：必須食後才說法，有四種利益：一是為了消化信施的緣故；二是為了報恩的緣故；三是使施主生起歡喜心、善根成就的緣故；四是因為在家人應行財施，出家人宜行法施的緣故。", "i": "u624-5", "n": 163, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《見論》云：聽說義時，要撮諸文。《五分》云：諸比丘請破戒、邪見、諸根不具者歎唄說法，因此惡人得勢，又能辱僧，佛言：「請法師、三藏、諸根具足者說。」", "t": "《善見律毘婆沙》說：聽許講說經義時，撮取諸文的要義來說。《五分律》說：諸比丘請破戒、邪見、諸根不具的人來讚唄說法，惡人因此得勢，又能辱沒僧眾。佛說：應請通達三藏、諸根具足的法師來說。", "i": "u624-6", "n": 164, "s": "第25篇　訃請"}, {"v": "卷下", "o": "《伽論》云：「若無能誦唄者，當次第差；若都無者，各誦一偈。能者不受，偷蘭。」", "t": "《毘尼摩得勒伽論》說：若沒有能誦唄的人，應依戒臘次第差派；若全都不能，就各誦一首偈；有能力卻不接受差派的，犯偷蘭遮。", "i": "u624-7", "n": 165, "s": "第25篇　訃請"}, {"v": "卷下", "o": "此律令說「諸惡莫作」一偈。《增一經》云：「『諸惡莫作』者，謂戒具足，清白之行；『諸善奉行』者，謂心意清淨；『自淨其意』者，謂除邪倒；『是諸佛教』者，謂愚惑想滅。戒淨故意淨，意淨故無倒，無倒故惑想滅也。", "t": "《四分律》令說「諸惡莫作，諸善奉行，自淨其意，是諸佛教」這一首偈。《增一阿含經》解釋說：「諸惡莫作」，是指戒行具足、清白的行持；「諸善奉行」，是指心意清淨；「自淨其意」，是指除去邪見顛倒；「是諸佛教」，是指愚癡迷惑之想滅除。戒清淨的緣故，心意就清淨；心意清淨的緣故，就沒有顛倒；沒有顛倒的緣故，愚惑之想便滅除了。", "i": "u624-8", "n": 166, "s": "第25篇　訃請"}, {"v": "卷下", "o": "第十一、還寺者。《五分》云：「還寺去時，上座八人相待，餘人前去。」《雜阿含經》云：「諸比丘食竟，皆入禪室坐禪，晡從禪起而說法也。", "t": "第十一，飯後返回寺院。《五分律》說：飯食用畢、要離開施主家回寺院時，最上座的八人應彼此等候，一同離去，其餘的人可以先行。《雜阿含經》說：眾比丘吃完飯後，都進入禪室坐禪；到了下午晡時，才從禪定中起座說法。", "i": "u625", "n": 167, "s": "第25篇　訃請"}, {"v": "卷下", "o": "○屆寺篇第二十六", "t": "第二十六篇　到達寺院", "i": "u626", "n": 168, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "此篇大門有二：第一、入寺，第二、儀式。", "t": "本篇的大綱分為兩門：第一是入寺，第二是儀式。", "i": "u627", "n": 169, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "第一、入寺者。此律云：舊比丘聞客來，應出外迎，為受衣鉢，安置溫室、重閣及經行處，供給水器等。", "t": "第一，入寺之法。《四分律》說：舊住比丘聽說客比丘來了，應當出去迎接，替他接過衣缽，把他安置在暖房、樓閣或經行處，並供給水器等物。", "i": "u628", "n": 170, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "問舊比丘：「我若干歲，有房分否？」答言：「有。」問：「有人住否？」若無人者，應問：「有臥具、利養器物、房衣等否？」有者當取，至房受已。", "t": "客比丘應問舊住比丘：「我有這樣的夏臘，依臘次有分給我的房舍嗎？」對方答說有，就再問：「那房裡有人住嗎？」如果沒人住，應問：「有臥具、利養器物、房衣等嗎？」若有，就應當領取，然後到那房中接受下來。", "i": "u628-2", "n": 171, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "又問何處大小行、淨地、佛塔、聲聞塔、第一上座房乃至第四上座房等，一一別問；若不問者，主人一一示語。", "t": "又要問：哪裡是大便處、小便處？哪裡是淨地？哪裡是佛塔、哪裡是聲聞塔？第一上座房乃至第四上座房各在何處？這些都要一一分別問明；如果客比丘不問，主人也應一一指示告知。", "i": "u628-3", "n": 172, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "客受房、問主人已，應禮佛塔，次禮聲聞塔，後禮第一上座乃至第四上座，應偏袒右肩，脫革屣，右膝著地，捉兩脚，如是言：「大德，我禮。」第四上座房內思惟，應隨座次禮，房主人一一示語。\n《十誦》云：「若上座時見，應禮；難見、遠者，則止。」", "t": "客比丘領受房舍、問過主人之後，應先禮佛塔，其次禮聲聞塔，然後禮第一上座乃至第四上座。禮拜時應袒露右肩、脫下皮鞋，右膝跪地，握住上座的兩腳，這樣說：「大德，我向您禮拜。」第四上座以下在房內坐禪思惟的比丘，就依座次（戒臘先後）次第禮拜，由房主人一一指示告知。《十誦律》說：如果當時能見到上座，就應當禮拜；若上座難以見到或住處遙遠，就不必前往。", "i": "u628-4", "n": 173, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "《三千威儀經》云：「若入他房，具五法：一、於外彈指，二、當脫帽，三、作禮，四、正住，教坐乃坐，五、不應經行。」《五分》：住處迮，不相識者，聽同牀坐，不得眠。", "t": "《三千威儀經》說：進入別人的房間，要具足五法：一、在門外彈指；二、應當脫帽；三、作禮；四、端正站住，主人請坐才坐；五、不應在房內經行走動。《五分律》說：住處狹窄時，彼此不相識的人可以同坐一床，但不得同床睡臥。", "i": "u628-5", "n": 174, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "《僧祗》云：「舊比丘應語客僧一切僧家制限。若伴已去者，不得語令知，云『不及伴』，應語：『可小停息，更應有伴。』必有急去者，應給粮食，囑累行伴。」", "t": "《摩訶僧祇律》說：舊住比丘應把僧家的一切規約限制告訴客僧。如果客僧的同伴已經離去，不可說「你趕不上同伴了」讓他知道；應當說：「你可以稍作休息，後面應該還會有同行的伴。」若他有急事一定要走，就應給他糧食，並把他託付給路上的行伴。", "i": "u628-6", "n": 175, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "《五分》云：「白衣入寺，應借臥具受用。」《三千威儀經》云：「新至比丘，以十事與之：一、當避與房，二、當給所須，三、朝暮問訊，四、語以習俗，五、當教避諱，六、當語請到處，七、語僧教令，八、當某事可食，九、示縣官禁忌，十、語以賊盜處所也。", "t": "《五分律》說：白衣進入寺院，應借給臥具供他使用。《三千威儀經》說：對新到的比丘，要以十件事給他：一、應當騰讓房舍給他；二、應當供給他所須的物品；三、早晚向他問訊；四、把當地習俗告訴他；五、教他應當避的諱忌；六、告訴他施主請供所到的處所；七、告訴他僧團的教令；八、告訴他哪些東西可以吃；九、指明官府的禁忌；十、告訴他有賊盜出沒的地方。", "i": "u628-7", "n": 176, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "第二、儀式者。《五分》：「若四威儀不如法者，非為於世而作大明。」", "t": "第二、威儀法式：《五分律》說，如果行、住、坐、臥四威儀不合乎法度，就不能為世間作大光明。", "i": "uGAP22-1", "n": 177, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "僧祇》云：「若行平視，迴時合身迴。」", "t": "《摩訶僧祇律》說：行走時要平視前方；轉身時要全身一起轉過去。", "i": "uGAP22-2", "n": 178, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "中阿含經》云：若朝乞食，守攝諸根，乞食已，收舉衣鉢，澡洗手足，以尼師壇著於肩上，至無事處，或經行、坐禪，淨心障已，於中夜時入室臥，四褺憂多羅敷牀上，褺僧伽梨作枕，右脇而，當頭面向佛像處，足足相累，意想明相；至後夜時速起，如初夜法。", "t": "《中阿含經》說：早晨如果前往乞食，應守護收攝諸根；乞食結束後，收起放好衣與鉢，洗淨手和腳，將尼師壇搭在肩上，前往清淨無事的地方，或經行，或坐禪；清淨了心中的障礙之後，在中夜時分進入房室躺臥。將憂多羅衣摺疊成四層鋪在床上，又摺疊僧伽梨作為枕頭，右脅〔側臥〕，頭臉朝向佛像所在的方位，雙腳上下相疊，心中繫念光明之相；到了後夜時分迅速起身，依照初夜的法式修行。", "i": "uGAP22-3", "n": 179, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "僧祇》云：「頭向袈裟及和尚、長老比丘，初夜思惟自業，至中夜，右脇著下，累兩脚，合口，舌柱上齗，枕右手，舒左手順身上，不捨念慧，思惟起想。」", "t": "《摩訶僧祇律》說：睡臥時頭部應朝向袈裟以及和尚、長老比丘所在的方向。初夜應思惟自己的業行；到了中夜才以右側脅部貼床躺臥，兩腳交疊，閉合嘴唇，舌頭頂住上牙齦，頭枕著右手，左手伸直順著身體平放，不捨棄正念與智慧，心中持續思惟起床之想。", "i": "uGAP22-4", "n": 180, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "義云：一切天人龍鬼，是出家修道之緣，於彼幽顯，不得輕有犯觸，雖居暗室，常當自照。《十誦》云：「燈明中不得眠。」", "t": "從義理上來說，一切天人、龍神與鬼神，都是出家人修道的助緣；對於那些無論在幽暗處或顯明處的眾生，不得輕率有所冒犯觸惱。即使處在幽暗的屋室之中，也應當常常自我省察照見。\n《十誦律》說：在點著燈火明亮的環境中不得睡眠。", "i": "uGAP22-5", "n": 181, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "母論》云：「若過十臘，有法事必能利益者，雖師不聽，自往無過。」", "t": "《毘尼母論》說：如果受戒已超過十戒臘，遇有如法之事且確定能夠產生利益時，即使師長不允許，自己前往也沒有過失。", "i": "uGAP22-6", "n": 182, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "僧祇》云：「行時先下脚跟，後下脚指。在道行欲宿，遣二年少比丘前覓宿處，索前食、後食，當白非時入聚落，得已還報，應展轉相白入。」", "t": "《摩訶僧祇律》說：行走時應先落下腳跟，再落下腳趾。在路上行走將要投宿時，應派遣兩位年少比丘先行尋找宿處，並乞求前食與後食；去前應當稟白非時入聚落之事，尋得與乞得之後回來稟報，大眾應展轉相互稟告後再行進入。", "i": "uGAP22-7", "n": 183, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "智論》云：「出入來去，安庠一心，舉足下足，觀地而行，避亂心，為護眾生故，是名不退菩薩相。」", "t": "《大智度論》說：出入往來應舉止安詳、心念專一，抬腳落腳都看著地面行走，以避開散亂心，並為了護念眾生之故，這就叫做不退轉菩薩的相貌。", "i": "uGAP22-8", "n": 184, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "僧祇》云：「不得作駱駝坐，應加趺坐，若疲極者，當互舒一脚。」", "t": "《摩訶僧祇律》說：不可以作駱駝坐，應當結跏趺坐；如果坐得非常疲累，應當兩腳輪流交替伸直一隻腳。", "i": "uGAP22-9", "n": 185, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "增一經》云：「今聽比丘先以手憑座後坐，此是我教。」", "t": "《增一阿含經》說：現在允許比丘先用手按憑座位然後再坐下，這是我的教誡。", "i": "uGAP22-10", "n": 186, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "十誦》云：「無病不得晝臥，若憙眠，應起經行。」", "t": "《十誦律》說：沒有生病不得在白天躺臥；如果容易犯困嗜睡，應當起身經行。", "i": "uGAP22-11", "n": 187, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "見論》云：臨欲眠時，先思於六念也。", "t": "《善見論》說：臨近想要睡眠的時候，應當先思惟六念。", "i": "uGAP22-12", "n": 188, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "三千威儀經》云：「不得於上座處坐，亦不得與三師並坐。」", "t": "《三千威儀經》說：不可以在上座的座位處坐，也不可以與三師並坐。", "i": "uGAP22-13", "n": 189, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "十誦》云：「聽法時，上座來，不應起，起者吉羅；若和尚、阿闍梨，恭敬故，自起，不得令他起，吉羅。乃至聽法，不得與沙彌同牀坐；沙彌得與白衣同牀坐，大比丘三夏亦同牀坐。」", "t": "《十誦律》說：聽法時若有上座前來，自己不應該起身（迎接），起身的人犯突吉羅；若來的是自己的和尚或阿闍梨，為了恭敬的緣故，可以自己起身，但不得令他人也起身，令他人起身者犯突吉羅。乃至於聽法時，不得與沙彌同床而坐；沙彌可以與白衣同床而坐；戒臘相差在三夏以內的大比丘，也可以同床而坐。", "i": "uGAP22-14", "n": 190, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "三千威儀經》云：「欲上牀時，當具七法：一、當徐却踞，二、不得匍匐上，三、不得使牀有聲，四、不得大拂牀有聲，五、不得大欠、大吒、歎息、思惟世事，六、不得羣狗臥，七、起以時節，心走不定，當自責本起。」", "t": "《三千威儀經》說：將要上床時應當具備七種法則：一、應當緩慢地退身坐上床沿；二、不得俯伏爬行上床；三、不得使床鋪發出聲響；四、不得大力拂拭床鋪發出聲響；五、不得大聲打呵欠、大聲嘆氣、歎息或思慮世俗之事；六、不得像群狗那樣聚集躺臥；七、應當依照時節起身，若心念馳散不安定，應當自我責省最初的起心。", "i": "uGAP22-15", "n": 191, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "母論》云：比丘貪著睡眠，廢捨三業，不復行道，金剛力士訶責。佛言：「食人信施，不應懈怠；夜二時中，應坐禪、誦經、經行，一時，以自消息，是名臥法。」", "t": "《毘尼母論》說：比丘貪著睡眠，荒廢捨棄三業，不再行道，金剛力士便加以呵責。佛說：「受食他人出於信心而布施的食物，不應當懈怠；在夜晚的兩個時段中，應當坐禪、誦經、經行，一個時段用來調養休息，這就稱為臥法。」", "i": "uGAP22-16", "n": 192, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "僧祇》：臥法如師子王，不得眠至日出，應於後夜，當起正思惟已業。又仰臥者，修羅；覆者，餓鬼；臥左脇，貪欲人臥也。", "t": "《摩訶僧祇律》說：睡臥的法式應如同獅子王一般，不得一直睡到太陽出來，應當在後夜時起身，端正思惟自己的業行。又，仰面而臥是修羅的臥姿，俯伏而臥是餓鬼的臥姿，向左側脅部而臥則是貪欲之人的臥姿。", "i": "uGAP22-17", "n": 193, "s": "第26篇　屆寺"}, {"v": "卷下", "o": "○懺悔篇第二十七", "t": "第二十七篇　懺悔", "i": "u629", "n": 194, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "此篇大門有六：一、懺波羅夷法，二、懺僧伽婆尸沙法，三、懺偷蘭遮法，四、懺波逸提法，五、懺波羅提提舍尼法，六、懺突吉羅法。", "t": "這一篇大分為六門：一、懺悔波羅夷罪的方法；二、懺悔僧伽婆尸沙罪的方法；三、懺悔偷蘭遮罪的方法；四、懺悔波逸提罪的方法；五、懺悔波羅提提舍尼罪的方法；六、懺悔突吉羅罪的方法。", "i": "u630", "n": 195, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第一、懺波羅夷法者。此有三種：一、懺儀，二、懺法，三、行法。", "t": "第一、懺波羅夷法，這當中有三種：一、懺儀，二、懺法，三、行法。", "i": "uGAP23-1", "n": 196, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第一、懺儀者。此律：比丘、比丘尼犯波羅夷已，都無覆藏心，令如法懺。", "t": "第一、懺儀：本律說，比丘、比丘尼犯了波羅夷罪以後，完全沒有隱瞞覆藏的心意，應令其如法懺悔。", "i": "uGAP23-2", "n": 197, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧祇》云：「若犯罪已，啼哭不欲脫去袈裟，深樂佛法，令與學悔羯磨。比丘不淨食，彼亦不淨食。得與比丘授食，除火淨、五生種及捉餘金銀等。應從沙彌尼受食。」", "t": "《僧祇律》說：如果犯了罪之後，痛哭流涕、不願脫去袈裟，深切愛樂佛法，就應為其授與學悔羯磨。對比丘而言屬於不淨的食物，對學悔者而言也同樣是不淨的食物；學悔者可以為比丘授食，但作火淨、處理五生種以及拿取其餘金銀等事除外；其自身應當從沙彌尼手中受食。", "i": "uGAP23-3", "n": 198, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "十誦》云：「若有犯此重戒者，如法乞羯磨，佛所結戒，一切受行；在大比丘尼下坐，不得與大比丘尼過三夜宿，自不得與白衣、沙彌尼過三夜宿；得為僧作布薩、自恣二種羯磨，仍不得自足僧數，餘一切羯磨皆不得作；得受夏也。」", "t": "《十誦律》說：如果有人犯了這種重戒，如法乞求羯磨之後，佛陀所制定的一切戒律都要全數受持奉行；坐在大比丘尼的下座；不得與大比丘尼同宿超過三夜，自己也不得與在家人、沙彌尼同宿超過三夜；可以為僧團作布薩、自恣這兩種羯磨，但仍不能充足僧團作法所需的人數；其餘一切羯磨全都不得作；可以受夏（仍得受取夏臘）。", "i": "uGAP23-4", "n": 199, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "伽論》云：「謂無能作者，得作前二種法。」", "t": "《伽論》說：這是指在沒有能作羯磨者時，才可以作前面那兩種法事。", "i": "uGAP23-5", "n": 200, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大唐波頗三藏云：「縱自言犯重，及有三根，自他相對，並成說淨、受衣等。」", "t": "大唐波頗三藏說：即使自己承認犯了重罪，以及具有三根舉罪的情況，自己與他人彼此相對作法，說淨、受衣等事都一律成就。", "i": "uGAP23-6", "n": 201, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "阿毗䟦律》云：有比丘名僧伽婆藪，遂犯婬，便自覺悟，捨鍚杖、法衣，著小舍勒，出入大唱云：「我是十方三世佛賊！」徧求自悔，至持律所；知其犯重，即化作一大火坑，僧伽婆藪便束身走投火，火即變成涼池。律云：「汝心如是，戒還得之，無破戒罪。」即得羅漢。如僧伽婆，四事皆爾。", "t": "《阿毗䟦律》說：有一位名叫僧伽婆藪的比丘，竟犯了婬戒，隨即自己覺察悔悟，於是捨棄錫杖與法衣，只穿著小舍勒，出入時大聲呼喊說：「我是十方三世佛賊！」他四處尋求自我懺悔的方法，來到持律者所在之處。持律者知道他犯了重戒，便化現出一座大火坑。僧伽婆藪便收束身體奔投火中，大火隨即變成清涼的水池。該律說：「你的心既然如此，戒體仍然還復歸你，沒有破戒之罪。」他當即證得阿羅漢果。如同僧伽婆藪這樣，四種重事也都是如此。", "i": "uGAP23-7", "n": 202, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "母論》云：「與白四悔法已，名清淨持戒，但此一身不得超生離死，然障不入地獄。」", "t": "《母論》說：為其授與白四懺悔法之後，就稱為清淨持戒；只是這一生無法超脫生死，然而能夠遮障惡報、不墮入地獄。", "i": "uGAP23-8", "n": 203, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "治禪病經》云：「犯重比丘將欲懺悔者，脫去僧伽梨，著安陀會，五體投地，如泰山崩，心生慚愧，供僧苦役，掃廁擔糞；如是經八百日已後，香湯洗浴，著僧伽梨，入塔觀像，見好瑞應有證後，為僧誦戒滿八百徧，方得清淨也。」", "t": "《治禪病經》說：犯了重戒的比丘將要懺悔時，應脫去僧伽梨，穿上安陀會，五體投地如同泰山崩塌一般，內心生起慚愧，為僧眾承擔苦役，打掃廁所、挑運糞便。像這樣經過八百天之後，以香湯洗浴，穿上僧伽梨，進入佛塔瞻仰佛像，見到美好的瑞應並有了憑證之後，再為僧眾誦戒滿八百遍，這才得以清淨。", "i": "uGAP23-9", "n": 204, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "虗空藏經》、《佛名》等經：若比丘、比丘尼犯四重、五逆，悉許得懺。", "t": "《虛空藏經》、《佛名》等經說：如果比丘、比丘尼犯了四重罪、五逆罪，全都允許懺悔。", "i": "uGAP23-10", "n": 205, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "然此諸經並是大乘，若欲捨懺，特須自驗根性，審看經意，然後得悔，不得見有斯經，便慢律教。", "t": "然而這些經典全都是大乘經典，如果想要依此捨罪修懺，特別必須自我檢驗根性，仔細審察經典的意旨，然後才可以懺悔；絕不可因為看見有這類經典，就輕慢律藏的教誡。", "i": "uGAP23-11", "n": 206, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、懺法者。犯尼應具威儀，脫新衣，著故五條，至心懇惻，來至僧中，五體投地，舉聲大哭，如泰山崩，自發露云：「我是佛法中大賊，偷形出家，行非犯重，冐霑清眾，自非他懺，罪中之極，惡中之大。省己患過，誰逾於我？污辱凡聖，壞滅佛法，恨不碎身如塵，歷劫重謝；苟貪性命，但延朝夕。蒙世尊慈訓懺法，携誘罪人，冀免來報。願大眾慈悲，布施悔法。」作如是已，然後請云。", "t": "第二是懺法：犯了重罪的比丘尼應當具足威儀，脫下新衣，換上舊的五條衣，以極其誠懇悲痛的心來到僧眾當中，五體投地，放聲大哭，如同泰山崩塌一般，自己發露說：「我是佛法中的大賊，竊取出家人的形相而冒充出家，行為非法、犯了重罪，冒濫地混入清淨的僧眾之中。若不是仰仗他人（僧眾）為我作懺悔之法，此罪便無從除滅；這是罪中最極重的、惡中最重大的。省察自己的過患罪業，有誰超過我呢？我污辱了凡夫與聖者，破壞毀滅了佛法。恨不能把此身碎為微塵，歷經多劫重重謝罪；卻苟且貪惜性命，只是苟延朝夕而已。承蒙世尊慈悲訓示懺悔之法，提攜引導罪人，使我希望能免除來世的苦報。願大眾慈悲，布施我懺悔之法。」這樣陳說之後，接著乞請說：", "i": "u631", "n": 207, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉僧聽！我比丘尼某甲，犯不淨行，不憶數；或互用三寶物，盜滿五錢，不憶數；或共男子互相摩觸，不憶數；或犯八事成重，不憶數；或知他犯重，故作覆心，不憶數。此等諸罪犯已，都無覆心，今從眾僧，乞波羅夷戒，願僧與我波羅夷戒，慈愍故。", "t": "諸位大姊僧，請聽！我比丘尼某甲，犯了行淫的不淨行，次數已記不清；或是把佛、法、僧三寶的財物彼此挪用，偷盜滿五錢，次數也記不清；或是與男子互相摩觸身體，次數記不清；或是犯了八事而構成重罪，次數記不清；或是明知他人犯了重罪，卻故意存心覆藏，次數記不清。這些罪犯了之後，我都沒有覆藏隱瞞的心。現在向僧團乞求「波羅夷戒」，願僧團授予我「波羅夷戒」，因為僧團慈悲憐愍的緣故。", "i": "u632", "n": 208, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "上座問云。", "t": "上座問道：", "i": "u633", "n": 209, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧今和合，何所作為？」答云：「與波羅夷戒羯磨。", "t": "「僧眾現在和合集會，要作什麼事呢？」回答說：「作授予波羅夷戒的羯磨。」", "i": "u634", "n": 210, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉僧聽！此比丘尼某甲，犯不淨行，不憶數；或互用三寶物，盜滿五錢，不憶數；或共男子互相摩觸，不憶數；或犯八事成重，不憶數；或知他犯重，故作覆心，不憶數。此等諸罪犯已，都無覆藏心，今從眾僧，乞波羅夷戒。若僧時到，僧忍聽，僧今與某甲比丘尼波羅夷戒。白如是。", "t": "各位大姊，僧眾請聽：這位某甲比丘尼犯了不淨行，不記得犯了多少次；或者互用佛、法、僧三寶的財物，盜取滿五錢，不記得多少次；或者與男子彼此摩觸身體，不記得多少次；或者犯了「八事」而構成波羅夷重罪，不記得多少次；或者明知他人犯了重罪，卻故意存心覆藏，不記得多少次。犯了這些罪之後，完全沒有覆藏的心念，現在向僧眾乞求授予「波羅夷戒」。如果僧眾認為時機已到，請僧眾聽許：僧眾現在授予某甲比丘尼「波羅夷戒」。以上是這樣的稟白。", "i": "u635", "n": 211, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉僧聽！此比丘尼某甲，犯不淨行，不憶數；或互用三寶物，盜滿五錢，不憶數；或共男子互相摩觸，不憶數；或犯八事成重，不憶數；或知他犯重，故作覆心，不憶數。此等諸罪犯已，都無覆藏心，今從眾僧，乞波羅夷戒，僧今與某甲比丘尼波羅夷戒。誰諸大姉忍僧與比丘尼某甲波羅夷戒者，默然；誰不忍者，說。」「僧已忍，與比丘尼某甲波羅夷戒竟。僧忍默然故，是事如是持。", "t": "諸位大姊，僧團請聽：這位比丘尼某甲，犯了不淨行，次數已記不清；或者互用三寶之物而盜取滿五錢，次數記不清；或者與男子互相摩觸，次數記不清；或者犯了八事成重之罪，次數記不清；或者明知他人犯了重罪，卻故意生起覆藏之心，次數記不清。犯了這些罪之後，完全沒有覆藏的心，現在向眾僧乞求授予波羅夷戒。僧團現在要授予某甲比丘尼波羅夷戒。諸位大姊當中，誰認可僧團授予比丘尼某甲波羅夷戒的，就請默然；不認可的，就請說出來。僧團已經認可，授予比丘尼某甲波羅夷戒完畢。由於僧團認可而默然的緣故，這件事就這樣受持。", "i": "u636", "n": 212, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第三、行法者。此律云：犯波羅夷戒已，當奪三十五事：一、不應授人大戒；二、不應受人依止；三、不應畜沙彌尼；四、不應受僧差教授比丘尼；五、若僧差，不應往教授；六、不應說戒；七、若僧中問答毗尼義，不應答；八、若眾僧作羯磨，不應作；九、僧中揀集智慧者評論眾事，不得在列；十、若僧差作信命，不應作；", "t": "第三、行法：《四分律》說，犯了波羅夷戒之後，應當奪除三十五件事：\n一、不應為他人授具足戒。\n二、不應接受他人來依止自己。\n三、不應收畜沙彌尼弟子。\n四、不應接受僧團差派去教授比丘尼。\n五、即使僧團差派了，也不應前去教授。\n六、不應說戒。\n七、若在僧中問答毘尼的義理，不應作答。\n八、眾僧作羯磨時，不應由她來作羯磨。\n九、僧中揀選集聚有智慧的人共同評議眾事時，不得列在其中。\n十、若僧團差派她作傳信的使者，不應擔任。", "i": "u637", "n": 213, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "十一、不得早入聚落；十二、不得逼暮還；十三、不應親近比丘；十四、不應親近白衣、外道；十五、應好順從諸比丘尼教，不應作異語；", "t": "十一、不得過早進入村落。\n十二、不得遲至傍晚才回來。\n十三、不應親近比丘。\n十四、不應親近在家人與外道。\n十五、應好好順從各位比丘尼的教導，不應說違逆的話。", "i": "u637-2", "n": 214, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "十六、眾僧隨所犯為作訶責羯磨已，不應復更犯此罪，餘亦不應犯；十七、若相似，若從此生；十八、若復重於此；十九、不應嫌羯磨；二十、不應嫌羯磨人；", "t": "十六、僧眾依她所犯的罪為她作了訶責羯磨之後，不應再犯這條罪，其餘的罪也不應犯。\n十七、若是與此相似的罪、或由此衍生的罪，也不應犯。\n十八、若是比這更重的罪，也不應犯。\n十九、不應嫌恨所作的羯磨。\n二十、不應嫌恨作羯磨的人。", "i": "u637-3", "n": 215, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "二十一、善比丘尼為敷坐具供養，不應受；二十二、不應受他洗足；二十三、不應受他安洗足物；二十四、不應受他拭革屣；二十五、不應受他揩摩身；二十六、不應受他善比丘尼禮拜；二十七、不得受他合掌；二十八、不得受他問訊；二十九、不得受他迎逆；三十、不得受他持衣鉢；", "t": "二十一、清淨比丘尼為她敷設坐具、供養她，不應接受。\n二十二、不應接受他人為她洗腳。\n二十三、不應接受他人為她安置洗腳的用具。\n二十四、不應接受他人替她擦拭皮鞋。\n二十五、不應接受他人替她揩摩身體。\n二十六、不應接受其他清淨比丘尼向她禮拜。\n二十七、不得接受他人向她合掌。\n二十八、不得接受他人向她問訊。\n二十九、不得接受他人前來迎接。\n三十、不得接受他人替她持拿衣缽。", "i": "u637-4", "n": 216, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "三十一、不應舉善比丘尼為作憶念、作自言；三十二、不應證他事；三十三、不應遮布薩；三十四、不應遮自恣；三十五、不應共善比丘尼諍。", "t": "三十一、不應檢舉清淨比丘尼的罪，令僧為她作憶念羯磨、作自言治。\n三十二、不應為他人的事作證。\n三十三、不應遮止他人的布薩。\n三十四、不應遮止他人的自恣。\n三十五、不應與清淨比丘尼共諍。", "i": "u637-5", "n": 217, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "又不得眾中誦律，無能者聽。與波羅夷戒已，僧說戒及羯磨時，來與不來俱不犯。若重犯婬戒，應當滅擯；若犯餘篇，依聚得懺。", "t": "此外，不得在僧眾中誦律；若僧中沒有能誦律的人，則開許她誦。僧團為她作了與波羅夷戒羯磨之後，僧中說戒及作羯磨時，她來參加或不來參加，眾僧都不犯別眾之罪。若再犯淫戒，就應當滅擯，逐出僧團；若犯的是其餘各篇的罪，則依所屬的罪聚如法懺悔。", "i": "u637-6", "n": 218, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、懺僧伽婆尸沙法者。此有六種：一、釋名，二、乞懺，三、奪事，四、雜行，五、出罪，六、誡勗。", "t": "第二，懺悔僧伽婆尸沙（僧殘）罪的方法。這一部分又分為六項：一是解釋名稱，二是乞求懺法，三是奪事，四是雜行，五是出罪，六是告誡勉勵。", "i": "u638", "n": 219, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第一、釋名者。《婆論》云：「僧伽者名僧，婆尸沙者名殘。若犯此罪，垢纏行人，非全淨用，有殘之罪，須僧除滅，故名僧殘。」摩那埵者，《見論》云：「秦言意喜，謂比丘犯僧殘，行覆藏已，前雖自意歡喜，亦生慚愧，亦使僧喜；由前喜故，與其少日故，始得喜名。眾僧歎言：『此人因茲改悔，更不起犯，戒得清淨。』故名意喜。」阿浮呵那，此名出罪羯磨，《見論》名為喚入眾，亦名拔除罪法。《母論》云：「謂清淨戒生，得淨解脫，善持起去，故名阿浮呵那。", "t": "第一、解釋名稱。《婆論》說：「僧伽」是「僧」的意思，「婆尸沙」是「殘」的意思。若犯了這種罪，罪垢就纏縛著修行人，使他不再具有完全清淨的僧用，罪尚有殘餘，必須由僧眾為他除滅，所以稱為「僧殘」。\n「摩那埵」：《善見論》說，秦地漢語譯為「意喜」。這是說比丘犯了僧殘罪，行完覆藏別住之法以後，先前雖然自己心裡歡喜，卻也生起慚愧，也使僧眾歡喜；由於前面這樣的歡喜，就給與他較少的日數；因這少日的緣故，才得到「喜」的名稱。眾僧讚歎說：這人因此而改悔，不再犯戒，得到清淨，所以叫做「意喜」。\n「阿浮呵那」：這裡譯為「出罪羯磨」。《善見論》稱它為「喚入眾」，也叫做「拔除罪法」。《母論》說：這是說清淨的戒生起，獲得清淨的解脫，能善加持守淨戒而起身離去，所以叫做「阿浮呵那」。", "i": "u639", "n": 220, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、乞懺者。若欲懺此罪，無問有覆、無覆，制在二部僧中半月行之，數各滿四人已上；若作出罪，僧尼兩眾數各二十，不得減少。然請僧之時，須請耆年明解律者，令尼生敬，不起慢意，下至四僧，多則彌善。安置尼寺別院不生譏嫌處，僧尼二眾各須結界，懺竟僧却解之。懺尼來至二部僧中，具修威儀，脫去七條已，偏露右肩，塗跣合掌，曲身低頭，自慨此罪垂入重處，曲蒙慈愍，特賜懺法，自惟我身，佛法中賊，詐被法服，冐霑清眾，恃己高行，望他尊敬，惡中之惡，無過我等，舉聲悲泣，盡心自責。如是誡已，四向禮僧竟，來至羯磨師前，長跪合掌住，傍人取其犯名教乞，羯磨師教亦得。", "t": "第二是乞懺。若要懺悔這個僧殘罪，不論犯後有覆藏、沒有覆藏，律制都規定要在比丘、比丘尼二部僧中行半個月，二部僧的人數各自須滿四人以上；如果要作出罪，比丘、比丘尼兩眾的人數便各須二十人，不得減少。而請僧的時候，必須請年高、明達律法的比丘，使比丘尼生起恭敬心，不起輕慢之意；最少下至四位比丘，人多則更好。把他們安置在尼寺的別院、不會招致譏嫌的地方，比丘、比丘尼二眾各自都須結界，懺法結束後，比丘僧再把界解除。要懺悔的比丘尼來到二部僧中，具足如法的威儀，脫下七條衣後，袒露右肩，赤足合掌，彎身低頭，自己悲慨犯了此罪，幾乎就要落入重罪之中，如今承蒙僧眾慈悲憐愍，特地賜給懺悔之法；又自己思惟：「我這個身是佛法中的賊，詐偽地披著法服，冒充混入清淨僧眾之列，還仗恃自己的高行，指望別人尊敬；惡中之惡，沒有超過我們這些人的。」於是放聲悲泣，竭盡心力自我責備。這樣自我誡責之後，向四面的僧眾禮拜完畢，再來到羯磨師面前長跪合掌而住，由旁邊的人取出她所犯的罪名，教她乞懺的說法；由羯磨師來教也可以。", "i": "u640", "n": 221, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！我比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。今從眾僧，乞十五夜摩那埵，願僧與我十五夜摩那埵，慈愍故。」\n羯磨師問云。", "t": "大德僧眾請聽：我比丘尼某甲，故意為男女作媒撮合，犯了僧殘罪，犯了多少次已記不清；或者犯了到官府控告他人的「言人」戒，得僧殘罪，次數記不清；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自落在同伴後面行走，得僧殘罪，次數記不清；或者接受了心懷染欲的男子所給的衣服、飲食，得僧殘罪，次數記不清。如今我向僧眾乞求十五夜的摩那埵，願僧眾出於慈悲憐愍，賜給我十五夜的摩那埵。乞辭說完，羯磨師便問道：", "i": "u641", "n": 222, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧今和合，何所作為？」答：「作十五夜摩那埵羯磨。", "t": "羯磨師問：「僧眾現在已經和合集會，要做什麼事呢？」答：「作十五夜摩那埵的羯磨。」", "i": "u642", "n": 223, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。今從眾僧，乞十五夜摩那埵。若僧時到，僧忍聽，僧與比丘尼某甲十五夜摩那埵。白如是。", "t": "諸位大德僧眾，請聽：比丘尼某甲，故意作媒撮合男女婚嫁，犯了僧殘罪，記不清犯了多少次；或者犯了向官府控告他人的言人戒，得僧殘罪，記不清次數；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自一人落在後面行走，得僧殘罪，記不清次數；或者接受懷有染愛之心的男子所施的衣服、飲食，得僧殘罪，記不清次數。她現在向僧眾乞求十五夜的摩那埵。如果僧眾作法的時機已到，請僧眾聽許：僧眾授予比丘尼某甲十五夜的摩那埵。以上是這樣白告。", "i": "u643", "n": 224, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！此比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。今從眾僧，乞十五夜摩那埵，僧今與比丘尼某甲十五夜摩那埵。誰諸長老忍僧與比丘尼某甲十五夜摩那埵者，默然；誰不忍者，說。」「僧已忍，與比丘尼某甲十五夜摩那埵竟。僧忍默然故，是事如是持。", "t": "諸位大德僧眾請聽：這位比丘尼某甲，故意作媒撮合男女婚嫁，犯了僧殘罪，記不清次數；或者犯了到官府控告他人的「言人」僧殘罪，記不清次數；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自在後面行走的僧殘罪，記不清次數；或者接受了有淫欲染污心的男子所施的衣服飲食，犯了僧殘罪，記不清次數。她現在向僧眾乞求十五夜的摩那埵，僧眾現在就給與比丘尼某甲十五夜的摩那埵。諸位長老中，誰贊同僧眾給與比丘尼某甲十五夜摩那埵的，請保持默然；誰不贊同的，請說出來。僧眾已經認可，給與比丘尼某甲十五夜摩那埵的事已經完成。由於僧眾默然認可的緣故，這件事就如此認定奉行。", "i": "u644", "n": 225, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第三、奪事者。羯磨師作法已，當誡勑云：「善女人聽！是白四羯磨，是聖教良藥，遵之在心；奪三十五事，是折伏法，勿得有違；執眾勞苦，更奉淨尼，是調伏法，一一順行；白等八事，是發露法，宜加省愧，深自慨責，憶念依行；日日作白，勿令違闕，闕者失宿，自慢慢他。」既示誨已，因僧集時，即作白云。", "t": "第三、奪事：羯磨師作完羯磨法之後，應當這樣告誡她：「善女人，妳聽著！這白四羯磨，是佛陀聖教中的良藥，要遵奉在心。褫奪三十五事，是折伏之法，不得有所違犯；承擔僧眾的勞苦事務，更要奉事清淨的比丘尼，這是調伏之法，每一項都要順從去做；作白稟告等八件事，是發露罪過之法，應當多加反省慚愧，深深地自我慨歎責備。要憶念不忘、依教而行，每天作白，不要有違失缺漏；一旦缺漏，那一夜就不計入所行的夜數，這是自己輕慢了所受的行法，也輕慢了他人。」這樣開示教誨之後，犯罪的比丘尼就趁僧眾集會的時候，作白說：", "i": "u645", "n": 226, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！我比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。已從僧乞十五夜摩那埵，僧已與我十五夜摩那埵，我比丘尼某甲，從今日行摩那埵，白二部僧，令知我行摩那埵。", "t": "大德僧眾請聽：我比丘尼某甲，故意替男女作媒、撮合嫁娶，犯了僧殘罪，記不清次數；或者犯了到官府控告他人的「言人」罪而得僧殘罪，記不清次數；或者獨自渡水、獨自進村、獨自住宿、獨自落在後面行走，犯了僧殘罪，記不清次數；或者接受了心懷染污欲念的男子所給的衣服飲食，犯了僧殘罪，記不清次數。我先前已向僧眾乞求十五夜的摩那埵，僧眾也已經給了我十五夜的摩那埵。我比丘尼某甲，從今天起開始行摩那埵，特此稟白比丘、比丘尼二部僧眾，讓大眾知道我正在行摩那埵。", "i": "u646", "n": 227, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若已行一夜者，餘詞同上，乃至云。", "t": "如果是已經行過一夜摩那埵的，其餘的白詞都與上面相同，略去相同處，直到這樣說：", "i": "u647", "n": 228, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧已與我十五夜摩那埵，我比丘尼某甲，已行一夜竟，餘十四夜在，白二部僧，令知我行摩那埵。", "t": "僧團已經給了我十五夜的摩那埵。我比丘尼某甲，已經行完一夜，還剩下十四夜。我稟白比丘、比丘尼二部僧眾，讓大眾知道我正在行摩那埵。", "i": "u648", "n": 229, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若外客僧尼來入界時，皆應作白云：「令知我行摩那埵。」若外客多時，應白云：「諸大一心念」等，餘亦同上。若外客僧尼年耆宿老者，待至房內安置坐已，然後作白亦得。作白之時，恒生慚愧，悲慨自責，不生戲笑；外客受白，亦生慚愧，不得輕弄。如是行法，客、主應教外生物善。", "t": "如果有外來的客比丘、比丘尼進入界內，行摩那埵的比丘尼都應向他們作白，讓他們知道作白的比丘尼正在行摩那埵。如果外來的客眾人很多，作白時就應改稱「諸大一心念」等，也就是請諸位大德一心憶念，聽我稟白，其餘白詞也和前面相同。如果外來的客比丘、比丘尼是年老臘高的尊宿，那就等他們到了房內、安頓坐定之後再作白，也是可以的。作白的時候，要始終心懷慚愧，悲傷感慨、責備自己，不可嬉戲談笑；外來的客眾接受她的稟白時，也應生起慚愧之心，不得輕慢戲弄。像這樣的行法，對客眾與主眾雙方都應如此教導，使外人生起善心。", "i": "u649", "n": 230, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第四、雜行者。此律云：「得摩那埵時，亦同行覆法，唯僧中宿、日日白僧為異。」", "t": "第四是雜行。《四分律》說：比丘尼得摩那埵之後，所應行的種種事也與行覆藏法相同，只有必須在僧眾中住宿、每日向僧眾稟白這兩點有所不同。", "i": "u650", "n": 231, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "應日三時見清淨僧，一切如法作，不應違逆。至布薩日，應掃灑布薩處，供給水器、具舍羅等。", "t": "每天三個時段都應去見清淨僧，一切都應如法去作，不應違逆。到了布薩日，應清掃灑淨布薩的處所，供給水器，備辦舍羅（籌條）等物。", "i": "u650-2", "n": 232, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "在小房中住，不應二人共宿。若眾僧衣物，得隨次取之。在大比丘尼下、式叉尼上坐。不得與清淨比丘尼共經行、同一牀一版，應作隔斷已，然後坐。", "t": "應住在小房中，不應兩人共宿一室。若是僧眾的衣物，她可以隨次第領取；座位則在大比丘尼之下、式叉尼之上。不得與清淨比丘尼一起經行，也不得同坐一張床、同一塊板，應先作好隔斷，然後才坐。", "i": "u650-3", "n": 233, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "應供給清淨二部僧；見有客來，代擔衣鉢，乃至洗除圊廁，勿令慢惰。不得在屏房內，以客來不見故，應至小屋繩牀，居在門首，伺侯外客，勿令默入不知。", "t": "應供給服侍清淨的二部僧；見有客人來，要代為擔持衣缽，乃至清洗廁所，不可傲慢懈怠。不得待在隱蔽的房內，因為客人來時會見不到她；應到門首小屋的繩床上坐著，守候外來的客人，不讓他們悄悄進來而自己不知道。", "i": "u650-4", "n": 234, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若大眾難集，若不欲行，若彼人軟弱、多有差愧，應至僧所白云。", "t": "如果大眾難以集合，或者不想行這些法，或者那人性情軟弱、多有羞愧，就應到僧眾那裡稟白說：", "i": "u650-5", "n": 235, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德，我今日捨勑不行。", "t": "「大德！我今天暫且捨置所受的教敕，不依教奉行。」", "i": "u651", "n": 236, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若欲行時，還至僧所白云。", "t": "若想恢復行法時，要再回到僧眾處稟白說：", "i": "u652", "n": 237, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德，我今日隨所教勑當作。", "t": "大德！我今天應當隨順僧眾所教敕的去做。", "i": "u653", "n": 238, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "見論》云：「行別住人，有人請喚，或與人受戒，得停行法，事罷續行。若寺中多有比丘尼，來去難白，晝日得捨行法，明相未出，還須白行。」《十誦》云：「乃至夜法，白僧停，得二十五夜。」此律云：「其懺尼得更互作使、禮拜、迎逆，亦得受沙彌等禮拜。」有八事失夜法，應當慎護：一、往餘寺不白；二、有客比丘尼來不白；三、有緣事自出界外不白；四、界內徐行者不白；五、病不遣信曰；六、大僧不得二人同室宿；七、在無比丘尼處住；八、不半月半月說戒時白。此之八事，不得違闕，隨違一事，即失一宿。", "t": "《善見律》說：正在行別住法的人，若有人邀請，或要為人授戒，可以暫停行法；事情結束後，再繼續行法。若寺中有很多比丘尼來來去去，難以一一白告，白天可以暫捨行法；但在天亮之前，仍須白告恢復行法。《十誦律》說：乃至行夜之法，向僧眾白告後暫停，最多可停二十五夜。《四分律》說：行懺悔的比丘尼之間，可以互相服勞役使、禮拜、迎接，也可以接受沙彌等人的禮拜。有八件事會導致失夜，即該夜不計入行法夜數，應當謹慎防護：一、前往其他寺院而不白告；二、有客比丘尼來而不白告；三、有因緣事務，自己走出界外而不白告；四、界內有緩步而行的比丘尼，卻不向她白告；五、生病而不遣人帶信去白告；六、不獨自住宿，而與已受具足戒的清淨比丘尼二人同室共宿；七、住在沒有比丘尼的地方；八、每半月說戒時不白告。這八件事不得違犯或缺漏，只要違犯其中任何一件，就失去一夜。", "i": "u654", "n": 239, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第五、出罪者。此懺尼次第具行十五夜法已，應淨剃髮、著受七條、被覆肩衣、著淨革屣，具修威儀，來至二部僧中，四向禮僧足，殷勤虔懇，責悔先罪。自惟罪釁，生女人中，汙染僧眾，其過甚多；今蒙大德等慈悲示誨，得免諸障，不勝喜躍。如是謝已，後乞出罪云。", "t": "第五是出罪。這位懺悔的比丘尼依次第圓滿行完十五夜的行法之後，應當把頭髮剃淨，穿上已受持的七條衣，披上覆肩衣，穿上乾淨的革屣，整飭具足威儀，來到比丘、比丘尼二部僧眾之中，朝四方一一頂禮僧眾之足，殷勤虔誠懇切地自責懺悔先前所犯的罪，自己省思罪愆：受生為女人，又染污了僧眾，過失實在很多；如今承蒙諸位大德慈悲開示教誨，得以脫免種種罪障，歡喜踴躍之情難以自勝。這樣致謝之後，接著乞求出罪，說道：", "i": "u655", "n": 240, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！我比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。已從眾僧，乞十五夜摩那埵，僧已與我十五夜摩那埵，我比丘尼某甲，行十五夜摩那埵竟，今從眾僧，乞出罪羯磨，願僧與我出罪羯磨，慈愍故。", "t": "大德僧眾請聽我說：我比丘尼某甲，故意為人作媒、撮合男女婚嫁，犯了僧殘罪，次數已記不清；或者犯了到官府控告他人的言人戒，得了僧殘罪，次數也記不清；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自落在後頭行走，得了僧殘罪，次數記不清；或者接受懷有染污淫欲心的男子所布施的衣服、飲食，犯了僧殘罪，次數記不清。我先前已向僧眾乞求十五夜的摩那埵，僧眾也已給了我十五夜的摩那埵。我比丘尼某甲已將十五夜的摩那埵行法執行完畢，現在向僧眾乞求出罪羯磨。祈願僧眾為我作出罪羯磨，慈悲憐愍我的緣故。", "i": "u656", "n": 241, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "羯磨者問僧云。", "t": "主持羯磨的人問僧眾說：", "i": "u657", "n": 242, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧今和合，何所作為？」答：「作出罪羯磨。", "t": "問：僧眾現在和合集會，要做什麼事？答：作出罪羯磨。", "i": "u658", "n": 243, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！此比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。已從眾僧，乞十五夜摩那埵，僧已與比丘尼某甲十五夜摩那埵，此比丘尼某甲已行十五夜摩那埵竟，今從眾僧，乞出罪羯磨。若僧時到，僧忍聽，僧今為比丘尼某甲作出罪羯磨。白如是。", "t": "各位大德僧眾請聽：這位比丘尼某甲，故意替男女作媒、撮合婚嫁，犯了僧殘罪，次數記不清；或者犯了到官府告發他人的「言人」僧殘罪，次數記不清；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自落在後面行走的僧殘罪，次數記不清；或者接受了心懷淫欲染污的男子所給的衣服、飲食，犯了僧殘罪，次數記不清。她先前已向僧眾乞求十五夜的摩那埵，僧眾也已給了比丘尼某甲十五夜的摩那埵；這位比丘尼某甲已經把十五夜的摩那埵行完了，現在向僧眾乞求出罪羯磨。如果僧眾認為時機已到，就請僧眾聽許：僧眾現在為比丘尼某甲作出罪羯磨。白告就是這樣。", "i": "u659", "n": 244, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大德僧聽！此比丘尼某甲，故犯媒嫁男女，得僧殘罪，不憶數；或犯言人，得僧殘罪，不憶數；或犯獨渡水、獨入村、獨宿、獨在後行，得僧殘罪，不憶數；或受染心男子衣食，得僧殘罪，不憶數。已從眾僧，乞十五夜摩那埵，僧已與比丘尼某甲十五夜摩那埵，此比丘尼某甲已行十五夜摩那埵竟，今從眾僧，乞出罪羯磨，誰諸長老忍僧與比丘尼某甲出罪羯磨者，默然；誰不忍者，說。」「僧已忍，與比丘尼某甲出罪羯磨竟。僧忍默然故，是事如是持。", "t": "大德僧團請聽：這位某甲比丘尼，故意為男女作媒、撮合婚嫁，犯了僧殘罪，已記不清次數；或者犯了到官府控告俗人的「言人」僧殘罪，也記不清次數；或者犯了獨自渡水、獨自進入村落、獨自住宿、獨自在後面行走的僧殘罪，也記不清次數；或者接受了心懷染欲的男子所給的衣服與飲食，犯了僧殘罪，也記不清次數。她已向僧團乞求十五夜的摩那埵，僧團也已給予某甲比丘尼十五夜的摩那埵；這位某甲比丘尼已行完十五夜的摩那埵，如今向僧團乞求出罪羯磨。諸位長老中，誰認可僧團為某甲比丘尼作出罪羯磨的，請默然；誰不認可，請說出來。僧團已經認可，為某甲比丘尼所作的出罪羯磨已經完成。由於僧團認可而默然的緣故，這件事就這樣認定奉行。", "i": "u660", "n": 245, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第六、誡勗者。律師作羯磨已，當誡勑云：「諸姉等諦聽！今時經像季，法逐人訛，犯者競興，悔意轉姦，雖樂剃髮染衣，俗情猶在；是以能受能破，厭戒厭持，不欣懺犯，好入地獄，苟求資蔭，不希出世。今既犯戒，類同斯禍，賴蒙改悔，䇿勵前非，懺於先罪，誠為大誡。故論云：『若有二十清淨比丘出僧殘罪者，我法不滅。』今善女人等已興隆正法，令不斷絕，則是真佛子，能報三寶重恩，復使凡聖欣慶、道俗欽仰。自今已後，願更莫犯，如護鵝珠、草繫比丘無異。假令興懺，因緣難辨，今末法中惡比丘尼多，尚不欲聞其名，況當聽汝懺悔？」如是誡約，令息後犯。諸懺尼等一時合掌答言：「頂戴奉持，願盡未來際，終不敢犯。", "t": "第六是誡勗，即告誡勸勉。律師作完羯磨之後，應當這樣告誡說：「各位姊妹，仔細聽著！如今時代已走到像法的末季，正法隨著人而訛變衰替，犯戒的人競相湧現，懺悔的心意反而變得奸巧虛偽。雖然喜歡剃髮、穿染色衣出家，世俗的情態卻依然存在，因此既能受戒、也能破戒，厭惡戒法、厭惡持守，不樂於懺悔所犯，卻喜好走向地獄，只苟且求取衣食資養與蔭庇，不希求出離世間。如今你們既已犯戒，就與這類招禍的人同類；幸而得以改悔，鞭策自己改正先前的過錯，懺除以前所犯的罪，這實在是一大警誡。所以論中說：『如果有二十位清淨比丘能為人出僧殘罪，我的正法就不會滅亡。』如今你們這些善女人已經使正法興隆，讓它不致斷絕，這就是真正的佛子，能報答三寶的深重恩德，又使凡夫與聖者都歡欣慶悅、出家與在家都欽敬仰慕。從今以後，但願不要再犯，要像護鵝珠的比丘、被草繫縛的比丘那樣，寧捨身命也不犯戒，沒有兩樣。假使想要再發起懺悔，所需的因緣也難以湊齊——如今末法之中惡比丘尼很多，人們連她們的名字都不願聽聞，何況會來聽你們懺悔呢？」這樣告誡約束，使她們止息日後的過犯。諸位求懺的比丘尼等同時合掌，回答說：「我們恭敬領受奉行，願從今直到盡未來際，始終不敢再犯。」", "i": "u661", "n": 246, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第三、懺偷蘭遮罪者。別有兩種：一、出罪輕重，二、出懺儀式。", "t": "第三、懺悔偷蘭遮罪，另外分為兩部分：一是列出所犯罪過的輕重，二是列出懺悔的儀式。", "i": "u662", "n": 247, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第一、出罪輕重。復有二節：一、初篇下從生方便偷蘭遮，二、不從篇下生者，名為獨頭偷蘭遮。第一、從生方便。復有三品：一、上，二、中，三、下。故《十誦》云：「從初篇下生重，此近方便蘭，應一切僧中懺；若初篇下生輕、二篇下生重者，應界外四比丘眾懺；若二篇下生輕者，應界內一比丘前懺。」上來雖分輕重，然未識罪名，自下具顯出之，後時興懺，令識易行。", "t": "第一，說明罪的輕重，其中又分兩節：一是從初篇之下所生的方便偷蘭遮；二是不從篇下所生的，名為獨頭偷蘭遮。第一類從生方便偷蘭遮又分三品：一是上品，二是中品，三是下品。所以《十誦律》說：從初篇下所生的重偷蘭遮（這是近方便偷蘭遮），應在一切僧眾當中懺悔；若是從初篇下所生的輕偷蘭遮，以及從二篇下所生的重偷蘭遮，應出到界外，向四位比丘的眾中懺悔；若是從二篇下所生的輕偷蘭遮，應在界內向一位比丘面前懺悔。以上雖然分出了輕重，卻還不能認識各罪的罪名，以下就一一詳細列出，使日後發起懺悔時，能認清罪名而容易實行。", "i": "u663", "n": 248, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "初篇生重者，就尼八重中，且逐數犯者，述其三五：如欲犯婬，共男子身口交觸，未得暢遂，得初篇方便重偷蘭遮；或欲盜五錢，已捉物著，因緣不遂，得重偷蘭遮；或受男子摩觸腕已前、膝已下，隣近重境，得重偷蘭遮；或欲犯八事，已犯前七，垂犯第八，遇緣不遂，時重偷蘭遮；或知他犯重，故作心覆，未經明相，臨曉悔露，得重偷蘭遮。如是等罪，並依《十誦》，一切僧中悔。", "t": "從初篇波羅夷所生的重偷蘭遮：在比丘尼的八條重戒當中，姑且舉出常犯的三五條犯相來說。例如想要行淫，已與男子的身、口交接相觸，卻還沒能暢遂成事，這就得初篇方便的重偷蘭遮。或者想盜五錢，已經捉住了物品，卻遇緣阻礙而未能成事，得重偷蘭遮。或者被男子摩觸手腕以前的手掌、手指與膝蓋以下的部位，這些部位緊鄰於結成重罪的範圍，得重偷蘭遮。或者想犯「八事」戒，已犯了前七事，將要犯第八事時遇緣阻礙而不成，這時得重偷蘭遮。或者知道他人犯了重罪，故意起心覆藏，還沒經過明相，在天將亮時悔過發露，得重偷蘭遮。以上這些罪，都依《十誦律》在全體僧眾中悔過。", "i": "u664", "n": 249, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若從初篇生輕者，如欲犯婬、犯盜等，已隣近人物者，因緣不遂，得初篇方便輕偷蘭遮。", "t": "至於從初篇所生的輕偷蘭遮：例如想行淫、想偷盜等，已經鄰近所對的人或物，卻因緣阻礙而未能成事，得初篇方便的輕偷蘭遮。", "i": "u664-2", "n": 250, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "二篇生重者，如欲媒嫁，受男家語將報女家，受女家語還男家，臨報還悔，得重偷蘭遮；或言人，口說至官，欲道名字，方便還悔，得重偷蘭遮；或獨入水待後伴，欲雙脚上岸，方便還悔，得重偷蘭遮；或獨行至村，臨越村界，方便還悔，得重偷蘭遮；或獨宿離伴，伸手外意，臨至明相，方便悔露，得重偷蘭遮；或獨在後行，欲俱離見聞，垂離還悔，得重偷蘭遮。上來兩篇輕重二位，依《十誦》，界外四比丘前懺。", "t": "從第二篇僧殘所生的重偷蘭遮：例如想做媒嫁，接受了男家的話要傳報女家，或接受女家的話要回傳男家，臨到傳報時反悔而止，得重偷蘭遮。或者犯「言人」戒，口中已對官府陳說，正要道出所告之人的名字，在這方便階段反悔而止，得重偷蘭遮。或者獨自入水，等待後面的同伴，將要雙腳上岸時，在方便階段反悔而止，得重偷蘭遮。或者獨自行走到村落，將要越過村界時，在方便階段反悔而止，得重偷蘭遮。或者獨自住宿，有意離開同伴、隔在伸手不及之處，臨到明相將現時，在方便階段悔過發露，得重偷蘭遮。或者獨自落在後面走，將要與同伴完全脫離見、聞的範圍，在快要脫離之際反悔而止，得重偷蘭遮。以上初篇所生的輕偷蘭遮與第二篇所生的重偷蘭遮這兩類，依《十誦律》應在界外四位比丘前懺悔。", "i": "u664-3", "n": 251, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二篇生輕者：如欲媒嫁，受男家語，將報女家，未至還悔，得第二篇方便輕偷蘭遮；或言人，口說未道名字，方便還悔，得輕偷蘭遮；或疾疾入水，待後伴，方便還悔，得輕偷蘭遮；或獨入至村，未入村界，方便還悔，得輕偷蘭遮；或獨宿離伴去，明相猶遠，方便還悔，得輕偷蘭遮；或獨在後行，欲離見聞處，方便還悔，得輕偷蘭遮；或欲受染汙心男子衣食，未得入手，方便還悔，得輕偷蘭遮。並依《十誦》，界內對一比丘前懺。", "t": "從第二篇僧殘生起的輕品偷蘭遮：例如想要替人做媒，已經接受了男方家的話，準備去轉告女方家，還沒到女方家就回頭悔改，得第二篇方便的輕偷蘭遮；或者要向官府告發人（詣官言人），話已出口，還沒說出對方的名字，就在方便階段回頭悔改，得輕偷蘭遮；或者急急忙忙先下水，等著落在後面的同伴，在方便階段就回頭悔改，得輕偷蘭遮；或者獨自走向村莊，還沒進入村界，就在方便階段回頭悔改，得輕偷蘭遮；或者獨自住宿，已離開了同伴，離天亮（明相出現）還很遠，就在方便階段回頭悔改，得輕偷蘭遮；或者獨自落在後面走，將要離開同伴看得見、聽得見的範圍，就在方便階段回頭悔改，得輕偷蘭遮；或者想要接受有染污心的男子所給的衣服、飲食，東西還沒到手，就在方便階段回頭悔改，得輕偷蘭遮。以上這些，都依《十誦律》，在界內對著一位比丘面前懺悔。", "i": "u665", "n": 252, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、獨頭偷蘭遮者：準《十誦》，有三品：若受用石鉢、慎心裂破五衣、著外道衣、灌下部、露身行、畜用人髮、食生肉、盜一二錢等，並對一人前懺；若破羯磨僧、盜得三錢、共男子摩觸，一有衣、一無衣等，並對四人前懺；若盜得四錢、盜僧食、共男子摩觸腕已前、膝已下，並界內對一切僧前懺。", "t": "第二、獨頭偷蘭遮：依《十誦律》分為三品。下品，如接受使用石缽、以瞋恨心撕破五衣、穿著外道的衣服、以水灌注下體、裸露身體行走、蓄存使用人的頭髮、吃生肉、偷盜一錢二錢等，都在一人面前懺悔。中品，如破壞羯磨僧的和合、偷得三錢、與男子摩觸而一方有衣、一方無衣等，都在四人面前懺悔。上品，如偷得四錢、偷盜僧團的食物、與男子摩觸手腕以前或膝蓋以下的部位，都要在界內全體僧眾面前懺悔。", "i": "u665-2", "n": 253, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "此律別眾戒中大眾者，若過四人；若據此文，縱犯中品罪，亦名大眾懺。小眾者，下〈滅諍犍度〉中，若二三人，名為小眾；若據此文，《十誦》對二人懺者，亦名小眾也。此律教二人行婬，成者偷蘭遮，不成者突吉羅，亦是自性偷蘭遮，應對小眾懺。", "t": "本律〈別眾食戒〉中所說的「大眾」，是指超過四人（五人以上）；但若依這段《十誦》的文來看，縱使犯的是中品罪（對四人懺），也稱為大眾懺。至於「小眾」，本律下文〈滅諍犍度〉中說：二人、三人名為小眾；依這段文，《十誦律》所說對二人懺悔的，也稱為小眾。本律又說：教唆男女二人行淫，若二人真的做成了，教唆者得偷蘭遮；若沒有做成，教唆者得突吉羅。這也是自性（獨頭）偷蘭遮，應當對小眾懺悔。", "i": "u665-3", "n": 254, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、出懺儀式者，別有三節：一、大眾法，二、小眾法，三、一人法。", "t": "第二，說明懺悔的儀式，其中又分為三節：一是大眾法，二是小眾法，三是一人法。", "i": "u666", "n": 255, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第一、大眾法：若欲懺悔，要五人已上，得受他懺，懺主作單白和僧羯磨，不落僧數。又依《婆論》，無問輕重，悉從僧三乞已，然後請懺主，對首三說，如懺波逸提法。犯尼具修威儀，來至僧中，問訊、長跪云。", "t": "第一、大眾法：如果想要懺悔，在場必須共有五人以上，才可以接受他人的懺悔；其中四人組成接受懺悔的僧眾，另一人是對首的懺悔主。懺悔主須作單白羯磨，向僧眾宣告、取得僧眾的和合認可，而懺悔主自己不算在僧數之內。又依《婆論》所說，不論所犯是輕是重，都要先向僧眾三次乞求懺悔，之後才請懺悔主，面對懺悔主三說懺罪之詞，如同懺波逸提的方法一樣。犯罪的比丘尼應整肅威儀，來到僧眾當中，問訊之後長跪著說：", "i": "u667", "n": 256, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉僧聽！比丘尼某甲，故犯不淨行，已共男子身口交觸，未得暢遂，犯初篇方便重偷蘭遮罪，不憶數；或犯盜用四錢，得獨頭偷蘭遮罪，不憶數。今從眾僧乞懺悔，願僧聽我懺悔，慈愍故。", "t": "「諸位大姊僧眾請聽：比丘尼某甲，故意違犯不淨行，已與男子身體、口部交相接觸，但未能完成婬事，犯了初篇波羅夷方便的重偷蘭遮罪，不記得犯了多少次；或者犯了盜用四錢，得獨頭偷蘭遮罪，也不記得犯了多少次。現在向眾僧乞求懺悔，願僧眾聽許我懺悔，慈悲憐愍的緣故。」", "i": "u668", "n": 257, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次至懺悔主邊，禮已，請云。", "t": "接著走到懺悔主面前，禮拜完畢後，啟請說：", "i": "u669", "n": 258, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今請大姉為偷蘭遮懺悔主，願大姉為我作偷蘭遮懺悔主，慈愍故。", "t": "大姊請專心一意地憶念：我比丘尼某甲，現在恭請大姊擔任偷蘭遮罪的懺悔主。懇願大姊為我作偷蘭遮罪的懺悔主，慈悲憐憫我的緣故。", "i": "u670", "n": 259, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次懺主尼先作單白和僧云。", "t": "接著，擔任懺悔主的比丘尼要先作單白羯磨，向僧眾稟白、使大眾和合知悉，這樣說：", "i": "u671", "n": 260, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "僧今和合，何所作為？」答：「單白懺重偷蘭遮羯磨。", "t": "「僧眾現在已經和合集會，要辦什麼事呢？」答：「作單白懺悔重偷蘭遮罪的羯磨。」", "i": "u672", "n": 261, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉僧聽！比丘尼某甲，故犯不淨行，己共男子身口交觸，未得暢遂，犯初篇方便重偷蘭遮罪，不憶數；或犯盜用四錢，得獨頭重偷蘭遮罪，不憶數。今從眾僧乞懺悔。若僧時到，僧忍聽，我受比丘尼某甲懺悔。白如是。", "t": "各位大姊，請僧眾聽著：比丘尼某甲故意違犯不淨行，已經和男子身體、口部交相接觸，但未能遂意完成，所犯的是初篇的方便罪，即重偷蘭遮罪，犯了幾次已記不清；或者犯了盜用四錢，所得的是獨頭重偷蘭遮罪，次數也記不清。她現在向眾僧乞求懺悔。如果僧眾時機已到、僧眾認可聽許，我作為懺悔主，接受比丘尼某甲的懺悔。以上就是這樣的白告。", "i": "u673", "n": 262, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "白已，廣為說罪相，語云：「大姉！今依《婆論》云，犯戒有三：一、犯業道罪，二、犯惡行罪，三、犯戒罪。又懺法有四：一、更相易脫懺，是凡愚懺；二、永斷相續懺，是凡智懺；三、焦業懺，是賢人懺；四、滅業懺，是聖人懺。汝既出家為尼，雖非賢聖，亦應作上品凡智永斷相續懺。既居凡位，孰能無犯？犯已能悔，是第二健人。佛制禁戒，寧死不犯，如護鵝珠、草繫比丘，此是第一健人。汝已破佛淨戒，今生懺悔，即是第二健人。若不懺者，便是地獄之人，虗受信施，如熱鐵纏身，冐受他食，如咽熱鐵丸，出入行來，猶如獵師，內懷腐爛，外現完淨，詐霑清眾，望人師敬，心無慚耻，畜生無異。」如是方便誨責，令永斷前罪，兼息後犯。懺尼聞法已，發大慚愧，起殷重心，然後捨罪云。", "t": "單白作完之後，懺悔主便廣泛地為她解說罪相，說道：「大姊！現在依《婆論》所說，犯戒有三種：一是犯業道罪，二是犯惡行罪，三是犯戒罪。再者，懺悔之法有四種：一是『更相易脫懺』，這是凡夫愚人的懺悔；二是『永斷相續懺』，這是凡夫智者的懺悔；三是『焦業懺』，這是賢人的懺悔；四是『滅業懺』，這是聖人的懺悔。你既然出家為尼，雖然還不是賢人聖人，也應該作上品凡智的『永斷相續懺』。既然處在凡夫之位，誰能沒有過犯呢？犯了之後能夠懺悔，就是第二種勇健的人。佛陀所制的禁戒，寧可捨命也不毀犯，就像護鵝珠的比丘、被草繫縛的比丘那樣，這是第一種勇健的人。你已經破了佛的淨戒，如今生起懺悔，就是第二種勇健的人。若不懺悔，便是地獄中人：白白領受信施，猶如熱鐵纏裹身體；冒受他人的飲食，猶如吞咽燒熱的鐵丸；進出往來猶如獵人一般，內心懷著腐爛，外表卻現出完好清淨的樣子；欺詐地混在清淨僧眾之中，還指望別人像恭敬師長那樣敬重自己；心中毫無慚愧羞恥，與畜生沒有兩樣。」就這樣以種種方便教誨呵責，使她永遠斷絕先前的罪過，同時止息日後的毀犯。前來懺悔的比丘尼聽了這番法語之後，生起大慚愧，發起殷重之心，然後說出捨罪之辭：\n---\n（出處：06a_卷下之下，第 14–14 段）", "i": "u674", "n": 263, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故犯不淨行，己共男子身口交觸，未得暢遂，犯初篇方便重偷蘭遮罪，不憶數；或犯盜用四錢，獨頭重偷蘭遮罪，不憶數。今向大姉發露懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不覆藏。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "大姊，請專心憶念。我比丘尼某甲，故意犯了不淨行，已經和男子以身體、口相互接觸，卻未能暢遂成事，犯了初篇方便的重偷蘭遮罪，次數已記不清；或者犯了盜用四錢，構成獨頭的重偷蘭遮罪，次數也記不清。如今向大姊發露懺悔，不敢覆藏。懺悔就得安樂，不懺悔就不得安樂。我憶念所犯的罪而發露，明知有罪而不覆藏。願大姊憶念我清淨、戒身具足，能清淨地作布薩。", "i": "u675", "n": 264, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次懺主訶責，問云：「汝識是罪否？」答言：「識。」又懺主語云：「毀犯甚易，懺悔極難，自責汝心，當生厭離，乃至形枯命終，更莫毀犯。」答言：「頂戴持，不敢更犯。", "t": "接著，懺悔主加以訶責，問道：「你知道這是罪嗎？」懺悔的比丘尼回答：「知道。」懺悔主又說：「毀犯禁戒很容易，懺悔卻極難。你應當責備自己的內心，生起厭離之心，乃至身形枯槁、壽命終結，也不可以再毀犯。」比丘尼回答：「我恭敬領受奉行，不敢再犯。」", "i": "u676", "n": 265, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、小眾懺者：《十誦》云：若四人受他懺，則無單白和僧之儀，止得迴問邊人。受懺尼問邊人云：「諸大姉等，聽我受此比丘尼某甲懺悔否？」諸尼答云：「姉，好。", "t": "第二種是在小眾中懺悔。《十誦律》說：如果是由四人接受他人的懺悔，就沒有作單白向僧眾告白、取得僧眾和合同意的儀式，只能轉過來詢問身旁的人。接受懺悔的尼便問身旁的人說：「各位大姊請聽，我接受這位比丘尼某甲的懺悔，可以嗎？」眾尼回答說：「大姊，可以。」", "i": "u677", "n": 266, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故犯婬、盜滿五錢，己鄰近人物，因緣不遂，犯初篇方便輕偷蘭遮罪，不憶數；或犯媒嫁，受男家語，將報女家，受女家語，欲報男家，臨報還悔，犯第二篇方便重偷蘭遮罪，不憶數；或盜用三錢，得獨頭中品偷蘭遮罪，不憶數。不敢覆藏，懺悔則安樂，不懺不安樂，憶念犯發露，知而不敢覆。願大姉憶我清淨，戒身具足，清淨布薩。」\n第三、一人法者。", "t": "大姊一心憶念：我比丘尼某甲，故意犯淫戒與盜滿五錢戒，已經接近行淫的對象或所盜的財物，但因緣不具足，未能完成，犯了初篇波羅夷方便的輕偷蘭遮罪，不記得次數。或者犯了媒嫁戒：接受男家的話語，將要轉告女家；接受女家的話語，將要轉告男家；臨到轉告時卻又反悔作罷，犯了第二篇僧殘方便的重偷蘭遮罪，不記得次數。或者盜用三錢，犯了獨頭中品偷蘭遮罪，不記得次數。不敢覆藏；懺悔就安樂，不懺悔就不安樂；記得所犯就發露，明知有罪就不敢覆藏。願大姊憶念我清淨，戒身具足，清淨布薩。\n第三、向一人懺悔之法：", "i": "u678", "n": 267, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故犯媒嫁，受男家語，將報女家，受女家語，欲報男家，未至還悔，犯第二篇方便輕偷蘭遮罪，不憶數。今向大姉發露懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不覆藏。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "大姊請一心憶念。我比丘尼某甲，故意犯了媒嫁戒：接受男方家的話，準備轉告女方家；接受女方家的話，想要轉告男方家，還沒走到對方那裡就後悔而中止。這樣犯了第二篇僧殘的方便罪——輕偷蘭遮罪，次數已記不清。現在向大姊發露懺悔，不敢覆藏。懺悔就得安樂，不懺悔就不得安樂。憶念起所犯的罪便發露，明知有罪而不覆藏。願大姊憶念證知我已清淨、戒身具足，能清淨地參加布薩。", "i": "u679", "n": 268, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "此方便、獨頭偷蘭遮，並還有方便、獨頭吉羅。如欲犯初、二篇罪，欲動身口，遇緣還止，得方便吉羅；如欲盜四錢、媒嫁等，闕緣不果，得獨頭吉羅。此之兩品，各有經夜、隨夜展轉覆。", "t": "上面所說的方便偷蘭遮與獨頭偷蘭遮，都還各自另有方便突吉羅與獨頭突吉羅。例如想要毀犯初篇的波羅夷罪、第二篇的僧殘罪，將要發動身、口之際，遇到因緣阻礙而中止，便結得方便突吉羅；又如想要盜取四錢、或做媒撮合嫁娶等事，因條件不具足而未能成辦，便結得獨頭突吉羅。這兩品突吉羅，各自都有「經夜覆藏」的罪（覆藏經過一夜所結的罪），以及「隨夜展轉覆藏」的罪（此後每過一夜，又逐夜輾轉各結一罪）。", "i": "u680", "n": 269, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第四、懺波逸提法者，此有兩重：一、懺三十捨墮，二、悔波逸提罪。就初又二：一、眾法難行，略而不述；二、明對首易懺，別有七重：一、簡財，二、捨財，三、捨罪，四、還衣，五、忘物，六、捨寶，七、雜法。", "t": "第四，懺悔波逸提罪的方法。這當中分為兩層：一是懺悔三十條捨墮罪，二是悔除其餘的波逸提罪。就第一層捨墮的懺法，又分兩部分：一是僧中集體作法的眾法難以實行，所以省略不加敘述；二是說明面對一人作法、容易實行的對首懺法。對首懺中又別分七層：一是揀別財物，二是捨出財物，三是懺除罪過，四是歸還衣物，五是遺忘未捨之物的處理，六是捨出金銀錢寶，七是雜項作法。", "i": "u681", "n": 270, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "一、簡財者：若犯長中，除八不淨財，餘一切須說淨者，無問輕重，皆須說淨。如尼十六枚器，有長不說淨，並制有罪，豈非重？", "t": "一、揀別財物：在犯畜長罪的財物當中，除了八不淨財以外，其餘一切應當說淨的東西，不論是輕物還是重物，都必須說淨。例如比丘尼的十六枚器，有多餘的而不作說淨，律中一律結罪——這些難道不正是重物嗎（可見重物也須說淨）？", "i": "u682", "n": 271, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若是長財未被說淨者，唯除負債未入手，或他寄來，或買得他物斷價已定，先未入手，皆不須捨；已曾入手，令寄他邊，此須索捨。", "t": "至於那些還沒有作過說淨的長財，只有以下幾種不必捨：他人所欠的債物尚未到手；他人寄存過來而尚未到手的；或向他人買物、價錢已議定而東西尚未到手的——這些都不必捨。若東西曾經到手，之後才把它寄放在別人那裡，這就必須索回來捨。", "i": "u682-2", "n": 272, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若已入手中，除共物未分、捨與三寶、決屬乞他，或香案、巾帊、窻戶、簾幕、牀帷、席等，並不合捨。《十誦》云：牀褥、薦席、鉢囊、氍氀、衣帳等，悉屬房物，不須說淨。經巾、鉢囊、臥具非身著用者，皆不犯長。", "t": "若財物已經在手中，除了以下幾種：與他人共有而尚未分配的、已捨給三寶的、已決定歸屬他人或已施給他人的，以及香案、巾帕、窗戶、簾幕、床帷、蓆子等，這些都不應捨。《十誦律》說：床褥、草薦、蓆子、缽袋、毛氈地毯、衣帳等，全都屬於房舍之物，不必說淨。包經的巾、缽袋、臥具，凡不是隨身穿戴使用的，都不犯畜長罪。", "i": "u682-3", "n": 273, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若著用中，鞋、鞾、履、韈非衣所攝者，不須集捨；自外供身之具，無問氈、被，皆須集捨。五衣之中，隨多少離宿犯捨者，至時文中一一別稱。", "t": "隨身著用的物品當中，鞋、靴、履、襪等不屬於衣類所攝的，不必聚集起來捨；除此之外，供給自身使用的資具，不論是氈是被，都必須聚集起來捨。五衣之中，不論有多少件因離衣過夜而犯捨墮，到作法時都要在文句中一一各別稱名。", "i": "u682-4", "n": 274, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次販賣捨中，謂自手於俗人邊買衣食具、一切鉢器、瓶椀、鞋韈等，無問輕重、多少，雖非犯長，無非自口斷決，爭價上下，乃至增減一錢，即成賣買，皆犯捨墮。", "t": "其次，關於販賣而須捨的部分：是指親手從俗人那邊買入衣服與食器，一切缽、器皿、瓶、碗、鞋、襪等，不論輕重多少；雖然不是犯畜長罪，但無不是自己開口議定成交、爭論價錢高低，乃至增減一文錢，就成了買賣，都犯捨墮。", "i": "u682-5", "n": 275, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "自外田宅、奴婢、車乘、机案等，同八不淨財，不須集捨，但作吉羅懺，以體是重物，不能隨身修道用故。若生活至多，散在餘處，財當別捨，其罪同懺；懺竟，諸處次弟還衣亦得。", "t": "除此以外，田地房宅、奴婢、車乘、几案等，等同八不淨財，不必聚集起來捨，只作突吉羅的懺悔即可，因為這些東西體性屬於重物，不能隨身帶著供修道之用。如果資生之物太多，分散存放在其他地方，財物應當就各別所在之處分別捨，罪則可以一同懺；懺完之後，再到各處依次第還衣，也是可以的。", "i": "u682-6", "n": 276, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、捨財者：應將合捨之物，來向自然界中，或至白衣家，或作法界內無僧、唯有二尼已下，並得對首捨衣。總束此物，至懺主尼前放地已，具修威儀，四向禮佛竟，次禮懺主尼三拜竟，然後近衣物邊，長跪，手執衣物，捨云。", "t": "第二、捨財：應當把該捨的物品帶到未經作法結界的自然界中，或帶到在家人家中，或身處作法界內而沒有四人以上的僧眾、只有兩位比丘尼以下的情形，這些都可以用對首法捨衣。把這些物品全部收攏在一起，送到擔任懺主的比丘尼面前放在地上之後，整肅威儀，向四方禮佛完畢，接著向懺主比丘尼頂禮三拜完畢，然後靠近衣物旁長跪，手裡拿著衣物，這樣作捨財的陳說：", "i": "u683", "n": 277, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故畜多長財，過十日不說淨，犯捨墮；離五衣宿，犯捨墮；販賣得財，犯捨墮；迴僧物，犯捨墮；互乞蘇、油，犯捨墮；迴現前僧食直作衣，犯捨墮；過畜長鉢，經宿不說淨，犯捨墮；過畜十六枚器，經宿不說淨，犯捨墮；共貿衣已，後強奪得，犯捨墮。如是眾多衣物，犯捨墮，不憶數。今持此衣物，捨與大姉。", "t": "大姊請專心聽我陳說：我比丘尼某甲，故意蓄存許多長財，超過十天沒有作說淨，犯了捨墮罪；離開五衣而過夜，犯了捨墮罪；因販賣而獲得財物，犯了捨墮罪；把僧眾的物品挪轉給自己，犯了捨墮罪；所乞的酥、油互相換乞（乞得酥後又改乞油等），犯了捨墮罪；把供養現前僧眾飲食的財物挪轉來作衣，犯了捨墮罪；蓄存長缽，經過一夜沒有作說淨，犯了捨墮罪；多畜十六枚器（超過允許的數量），經過一夜沒有作說淨，犯了捨墮罪；與人交換衣之後又強行奪回，奪到手便犯了捨墮罪。像這樣眾多的衣物，都犯了捨墮罪，我不記得數目。現在我拿這些衣物，捨給大姊。", "i": "u684", "n": 278, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第三、捨罪者：先請一清淨比丘尼為懺主。謂不犯八重、十三難，若犯下四篇已經懺悔者，三根清淨，得為懺悔主；不爾，反成自累，何成益物？故律云：「有犯者，不得受他懺悔，不得向有犯者解罪。」既知此已，省己行之。", "t": "第三、捨罪，也就是懺除罪過：先請一位清淨的比丘尼擔任懺悔主。所謂清淨，是指沒有犯過比丘尼的八條波羅夷重罪，也沒有十三難之事；若曾犯第一篇以下的僧殘、波逸提、提舍尼、突吉羅四篇之罪，但已經懺悔過，在見、聞、疑三根上都清淨，這樣也可以擔任懺悔主。不然，反而連累了自己，哪裡能利益他人呢？所以律中說：「有犯戒的人，不得接受別人的懺悔；也不得向有犯戒的人懺悔除罪。」明白這個道理之後，就應省察自己的行持，然後依此而行。", "i": "u685", "n": 279, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今請大姉為波逸提懺悔主，願大姉為我作波逸提懺悔主，慈愍故。", "t": "大姊，請您一心專注聽我陳說：我比丘尼某甲，現在敦請大姊擔任我波逸提罪的懺悔主。祈願大姊為我作波逸提罪的懺悔主，因為慈悲憐愍我的緣故，懇請大姊垂聽應允。", "i": "u686", "n": 280, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次懺悔主先問傍尼云：「大姉等，聽我受此比丘尼懺悔否？」傍尼答云：「好。」次受懺為尼答云：「受汝懺悔。」然後廣說罪惡果報云：", "t": "接著，懺悔主先問旁邊的比丘尼說：「各位大姉，允許我接受這位比丘尼的懺悔嗎？」旁邊的尼眾答說：「好。」接著懺悔主接受懺悔，向這位比丘尼答說：「我接受你的懺悔。」然後廣泛宣說罪惡與果報，說：", "i": "u687", "n": 281, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "「大姉，既是佛弟子，依佛出家，行佛淨戒，今故毀破，何名尼也？佛制禁戒，寧死不犯，令衣鉢隨身，長衣說淨。今違聖教，名破戒人，心無慚耻，受他信施。若受他食，即是洋銅灌口；著他施衣，便是熱鐵鍱身。若死入地獄，飢吞熱鐵丸，渴飲沸銅汁，無量歲中，受諸苦惱。後生為蟲，常在廁中，以食不淨故；或生寒鴞無毛身中，或生裸國中，常無衣服，以離五衣宿故。受苦如是！姉，姉，今可發大慚愧，自向佛、僧求哀懺悔。」", "t": "大姉你既然是佛弟子，依佛出家，奉行佛的淨戒，如今卻故意毀壞破犯，哪裡還稱得上是比丘尼呢？佛所制定的禁戒，寧可捨命也不違犯；佛規定衣缽必須隨身，長衣必須作說淨。如今違背聖教，就叫做破戒人，心裡沒有慚愧羞恥，卻接受他人的信心布施。若接受他人的飲食，就等於把熔化的銅汁灌進口中；穿他人布施的衣服，就等於用燒熱的鐵片裹身。死後若墮入地獄，飢餓時吞熱鐵丸，口渴時飲沸騰的銅汁，在無量歲月中受種種苦惱。之後投生為蟲，常住在廁所裡，這是因為食用不淨的緣故；或者投生在寒鴞無毛的身體中；或者生在裸人之國，常常沒有衣服可穿，這是因為離五衣而宿的緣故。所受的苦就是這樣。姉啊，姉啊！如今應當發起大慚愧，親自向佛與僧求哀懺悔。", "i": "u687-2", "n": 282, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "如是憶悔已，先懺吉羅，後悔提罪。如犯長衣，曾經著用，兼聽說戒，隱覆不懺，便生八罪：謂覆提有二、著妄有二、覆隨著妄有四。此之八品，並號吉羅。若計犯數，乃有無量，皆入懺中，應云不憶數；或無覆者，則不須此。乃至七聚，亦有覆隨吉羅，準說可知。懺此八，應對一人悔。", "t": "這樣憶念罪過而悔責之後，先懺突吉羅罪，後懺波逸提罪。例如犯了畜長衣的罪，又曾經穿著使用這件長衣，也曾參與布薩、聽誦戒本，並且對這些罪全都隱藏覆藏而不發露懺悔，便產生八個罪：所謂覆藏波逸提罪，連同隨後的展轉覆藏，有二個；著用長衣與說戒時默然妄語，有二個；覆藏這著用與默妄二罪、以及隨之展轉覆藏，又有四個。這八品都叫做突吉羅。若計算所犯的數目，乃有無量，全都攝入懺悔之中，所以應當說「不憶數」。如果沒有覆藏，就不需要這些。乃至七聚罪也都有覆藏、隨覆藏的突吉羅，依此類推即可明白。\n懺這八個罪，應當對一個人悔過。", "i": "u687-3", "n": 283, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "問：何以得知此八得對一人悔？答：準論云，故作者對一人悔，誤作者自責心懺。《明了》、《婆論》並云，輕者責心，重者對人，此則文順理通，於義不乖。比來諸師，多引律文「又有小罪，不從人懺」，依此一教，遂即雷同，總判責心，良恐非法。然律「不從人懺」者，謂誤作也；論「對人」者，謂故作也。此則律、論各談一見，會通皆得。今犯此八，並隱而不說，豈得誤輕耶？", "t": "問：怎麼知道這八個罪可以對一人悔過呢？\n答：依據論典所說：故意造的，對一人悔過；誤犯的，自己責心懺悔。《明了論》與《薩婆多論》也都說：輕的責心懺，重的對人懺。這樣就文句通順、道理通達，於義理並無乖違。近來諸位律師大多引律文「又有小罪不從人懺」，依這一處教文便不加區別地一概判為責心懺，實在恐怕不合於法。然而律中說不從人懺的，是指誤作；論中說對人懺的，是指故作。這樣律與論各自闡述一邊，會通起來兩者都能成立。如今所犯這八個罪都是隱藏而不發露，怎能算是誤犯的輕罪呢？", "i": "u687-4", "n": 284, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若欲懺者，應請一清淨比丘尼為懺悔主，具修威儀，至懺悔主前云。", "t": "若要懺悔，應當請一位清淨的比丘尼作懺悔主，整肅威儀，到懺悔主前說：", "i": "u687-5", "n": 285, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今請大姉為突吉羅懺悔主，願大姉為我作突吉羅懺悔主，慈愍故。", "t": "大姊，請專心聽我說：我比丘尼某甲，現在請求大姊擔任我突吉羅罪的懺悔主。懇願大姊慈悲憐愍，為我作突吉羅罪的懺悔主。", "i": "u688", "n": 286, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次捨罪云。", "t": "接下來懺除所犯的罪過，這樣說：", "i": "u689", "n": 287, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故畜長衣，經十日不說淨，犯捨墮，不憶數。識知是罪，故作心經夜覆藏，得突吉羅罪，不憶數；第二夜已去，乃至多夜，隨展轉覆藏，得突吉羅罪，不憶數。經僧說戒時，尼八處三問，犯默妄語，得突吉羅罪，不憶數；識知此罪，故經夜覆藏，得突吉羅罪，不憶數。今向大姉發露懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不覆藏。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "請大姊專心憶念。我比丘尼某甲，故意蓄存五衣以外的長衣，經過十天沒有作說淨，犯了捨墮罪，犯了幾次已記不清。我明知這是罪，卻故意存心，經過一夜加以覆藏，得突吉羅罪，次數記不清；從第二夜以後，乃至經過許多夜，隨著夜夜輾轉相續的覆藏，每夜各得突吉羅罪，次數記不清。遇到僧中說戒時，比丘尼戒本有八處、每處三次詢問「是中清淨不」，我默然不發露，犯了默然妄語，得突吉羅罪，次數記不清；又明知此罪，故意經過一夜覆藏，得突吉羅罪，次數記不清。現在向大姊發露懺悔，不敢再覆藏。懺悔就得安樂，不懺悔就不得安樂。今後一憶念起所犯便發露，明知有罪便不再覆藏。願大姊憶念證知我是清淨的，戒身具足，能清淨地參加布薩說戒。", "i": "u690", "n": 288, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次懺提罪云。", "t": "接著懺悔波逸提罪，應當這樣說：", "i": "u691", "n": 289, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故畜眾多長衣，過十日不說淨，犯捨墮；故離五衣宿，犯捨墮；販賣得財，犯捨墮，各不憶數。是諸衣物，已捨與大姉，是中各犯根本波逸提罪，不憶數；又犯捨衣財，已用壞盡，是中亦犯根本波逸提罪，不憶數。今向大姉發露懺罪，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不敢覆。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "大姊，請專心憶念：我比丘尼某甲，故意積蓄眾多長衣，超過十天沒有作說淨，犯了捨墮罪；又故意離開五衣而過夜，犯了捨墮罪；又因販賣而得財物，犯了捨墮罪。以上各類的犯罪次數，都記不清楚了。這些衣物，已經捨給了大姊，在其中各各犯了根本的波逸提罪，次數也記不清楚。另外，那些因犯捨墮而本應捨出的衣財，已經被使用、損壞、耗盡，在這上面也犯了根本的波逸提罪，次數同樣記不清楚。現在向大姊發露、懺悔這些罪，不敢覆藏。懺悔就得安樂，不懺悔就不得安樂；憶念起所犯的罪而發露，明知是罪而不敢覆藏。願大姊憶念我為清淨、戒身具足，能清淨地參加布薩。", "i": "u692", "n": 290, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "懺主語云：「汝識是罪否？」答云：「識。」又語云：「自責汝心，生厭離意，乃至形枯命終，更不得犯，如護鵝珠、草繫比丘無異。」答：「頂戴持，不敢更犯。", "t": "懺悔主對她說：「你認識這是罪嗎？」她回答：「認識。」懺悔主又對她說：「你要自己責備內心，生起厭離的心意，乃至身形枯槁、壽命終了，都不得再犯，要像護鵝珠比丘、草繫比丘那樣，沒有差別。」她回答：「我恭敬地領受奉持，不敢再犯。」", "i": "u693", "n": 291, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第四、還衣者：若捨長衣、長藥、十六枚器等，並由貪心過畜不說故，必須經宿還，為斷相續故；若捨離衣宿、販賣得諸物，並須當座還之。若犯長衣等，有遠行因緣不得經宿者，懺主尼即座展轉付彼知識尼，得衣已，屏處與之亦得。", "t": "第四、還衣：如果所捨的是長衣、畜存超過七日時限的長藥、十六枚器等物品，都是由於貪心而超過時限畜存、又不作說淨而犯的，所以必須經過一夜之後才歸還，為的是截斷貪心的相續。如果所捨的是離衣過夜所犯的衣，以及販賣所得的種種物品，就都必須當場歸還。若犯長衣等罪的人有遠行的因緣、不能等到隔夜的，懺主尼便當場把衣轉手交付給與犯者相識的那位尼；那位尼拿到衣後，在避人的隱蔽處把衣交還給犯者，這樣也可以。", "i": "u694", "n": 292, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第五、忘捨衣財者：謂捨衣已，或還衣竟，而未說淨，忽見本捨之財，即生己想，還成相染，一切不成，更將總捨。若衣已說淨，後見本忘物，前捨並成，淨法不失，後忘元物，或別捨。若衣已捨未還主者，見本忘物，即須別捨，共本捨衣總還其主，令同說淨。既知捨財不易，未捨物前，應總作念云，現集之財，今並將捨，已外忘財不集者，決定捨與三寶、同學、知識之意。如是念已，後見本忘物，無問早脫，前捨並成。若捨已還，未得說淨，見本忘物，方生捨念者，不成；由染意前生，捨心後起故。此謂長財捨竟，還見長財等，故有相染；若見本忘物是販賣財者，無相染義。若捨墮還竟，見本長財過十日者，此入相染之例，便作長犯捨之，以販賣財罪已捨懺竟，同是長財也。", "t": "第五、關於遺忘未捨的衣財。這是說：已經把衣捨了，或者衣已歸還而還沒作說淨的時候，忽然看見原本該捨卻遺忘未捨的財物，立刻生起「這是我的」的念頭，這樣反而造成相染，先前所作的一切捨法都不成就，必須再把它們全部一起捨。如果衣已經作了說淨，之後才見到原先遺忘的財物，那麼先前的捨法都成立，說淨之法也不失去；至於後來才見到的那件原先遺忘之物，就另外單獨捨。如果衣已捨出而尚未歸還衣主，這時見到原先遺忘的財物，就必須另外單獨捨它，然後連同先前所捨的衣一併歸還衣主，讓衣主把它們一起作說淨。既然知道捨財不容易，在還沒捨物之前，應當總括地作這樣的念：「現在聚集在此的財物，我現在一併都要捨；除此以外，那些遺忘而沒有聚集來的財物，我也決定捨給三寶、同學與相識的人。」這樣作念之後，日後見到原先遺忘的財物，不論早晚，先前的捨都成立。但如果衣已捨出、也已歸還，卻還沒作說淨，見到原先遺忘的財物才生起要捨的念頭，這就不成立，因為執為己有的染污心先生起，捨心後生起的緣故。以上是就長財捨完之後又見到長財等類的情況而說，所以有相染。如果見到的原先遺忘之物是販賣所得的財物，就沒有相染的道理。但若是販賣財已依捨墮法捨出、也已歸還完畢，之後才見到原先遺忘而超過十日的長財，這就落入相染的例中，便依畜長財犯捨墮的方式來捨它；因為販賣財的罪已經捨財、懺悔完畢，那些財物同樣成了長財。", "i": "u695", "n": 293, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第六、捨寶者：當取所畜錢寶、金銀等，捨與知法白衣、淨人云：「此是我所不應畜，汝當知之。」捨已，其罪對尼懺。懺主未捨罪前，應問：「所畜錢寶，並捨與白衣、淨人未？」答：「已捨。」若未捨者，教如法捨已，然後罪同前懺。自餘穀米等，並同前〈說淨篇〉述。", "t": "第六、捨寶：應當把自己所畜積的錢財、寶物、金銀等，捨給懂得律法的白衣（在家居士）或淨人，並對他說：「這是我不應該畜存的東西，你應當知道。」捨掉之後，所犯的罪要向比丘尼懺悔。懺主尼在還沒有為她除罪之前，應先問：「所畜的錢財寶物，都捨給白衣、淨人了沒有？」答：「已經捨了。」如果還沒有捨，就教她先如法捨掉，然後再依前面所說的方式懺除此罪。其餘穀、米等物，都同前面〈說淨篇〉所說的一樣。", "i": "u696", "n": 294, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第七、雜法者：此別對首法。若能、所滿四人已下，但使無僧，不問作法、自然界中，並成對首；若能、所滿五人已上，作法界內及戒場上，不合對首，應作眾法捨之，縱自然界及白衣舍，亦不合對首捨。以正懺悔時，尼唯是所懺，不落僧攝，餘尼展轉懺竟，還墮僧數；又餘懺尼雖未捨懺，以體是大尼，豈非僧攝？既成僧故，何得對首捨懺？若知不易，眾法復難，欲得受多尼捨懺之時，令諸懺悔尼總向大界內坐，懺主尼一一喚來，入自然界內，如是展轉作法，乃受無量，皆成如法。不爾之時，徒自費功，財還不淨，虗為獨善。數見僧尼共行此法，別疏記之。", "t": "第七、雜法。這是特別說明對首法的部分。能懺與所懺雙方合計在四人以下，只要不構成僧數，不論是在作法界中或自然界中，對首作法都能成立。若能懺與所懺合計滿五人以上，在作法界內以及戒場上，就不合用對首，應當改用眾法來捨財；縱使在自然界中或白衣家中，也不合用對首來捨。因為正在懺悔的時候，受懺的那位尼只是所對懺悔的對象，不列入僧數；其餘的尼一一輪流懺悔完畢，又回到僧數之中；而且其餘要懺悔的尼雖然還沒有捨財懺罪，但她們的身分本就是比丘尼，怎能不算在僧數之內？既然已構成僧，怎麼還可以用對首來捨財懺罪呢？\n如果知道對首法不容易成就，而作眾法又困難，那麼想要接受眾多尼捨財懺罪的時候，就讓所有要懺悔的尼都到大界內坐著，由受懺的尼一一叫她們過來，進入自然界內，這樣輪流作法，即使接受無量數人的捨懺，也都能如法。不這樣做的話，只是白費功夫，財物交還回來仍舊不清淨，徒然自以為一人清淨罷了。我多次見到僧眾、尼眾都行用這種作法，另有疏記加以記載。", "i": "u697", "n": 295, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第二、單懺百七十八單提法。此中分二：一、若有覆藏突吉羅，亦有輕重兩位，謂輕者責心、重者對人，此二法下〈懺突吉羅〉中具說；二、若犯提吉不覆藏者，則不須此。今且懺根本捨罪法：具修威儀，請清淨比丘尼懺悔已，傍尼答云：「好。」受尼語懺悔尼云：「某甲身器豈得清淨，非行者良緣？大姉既犯佛戒，還須向佛懺悔，譬如因地而倒，還須託地而起，如是生殷重心，請十方諸佛同時加被，為我證明。」兼說利養難消、出家難得，種種方便，隨時誨責，大同捨墮中說。廣誡勑已，告言：「罪相如是，何得隱藏？若欲懺悔，具須陳說，除疑不識，後當決了。」《見論》云：「若生時惡罵彼人，彼已入涅槃，能罵者求懺悔，當於涅槃處作懺悔。懺悔已，天道門不閉。」如是語已，次教捨罪云。", "t": "第二、只須懺罪、不須捨財的一百七十八條單提罪懺法。這當中分為兩部分：一、如果有覆藏而結成的突吉羅罪，也分輕、重兩等：輕的責心懺悔，重的向人懺悔；這兩種作法，在下面「懺突吉羅」一門中會詳細說明。二、如果犯了波逸提、突吉羅而沒有覆藏，就不需要這一道程序。\n現在先懺根本罪。捨罪的作法是：具足整肅威儀，請一位清淨的比丘尼，向她懺悔。請完之後，旁側的比丘尼回答說：「好。」這位聽受懺悔的懺主尼便對懺悔的比丘尼說：「某甲！妳這個身心之器哪裡稱得上清淨？這可不是修行人的良好助緣。大姊既然犯了佛所制的戒，還是必須向佛懺悔。譬如因地而跌倒的人，還得靠著地才能站起來。要這樣生起殷重懇切的心，祈請十方諸佛同時加持覆護，為自己作證明。」\n並且還要說利養難以消受、出家難得，以種種方便隨當時的情況加以教誨呵責，大體與捨墮一門中所說的相同。詳加告誡敕責之後，告訴她說：「罪相既是如此，怎麼可以隱藏？若想懺悔，就必須全部陳述出來；除了有疑惑、不清楚的部分，那些之後再作判定。」\n《善見律毘婆沙》說：「若在對方活著的時候惡口辱罵了他，而那人已經入涅槃，罵人的人想求懺悔，應當到那人入涅槃的地方作懺悔；懺悔之後，通往天道之門就不會關閉。」這樣說完之後，接著教她捨罪說：", "i": "u698", "n": 296, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，犯故妄語、毀呰語、兩舌語、共男子同室宿、共未受具戒人同室宿過三夜、與未受具人同誦、向未受具戒人說他尼麤罪、", "t": "大姊，請一心憶念：我比丘尼某甲，犯了故意說謊、毀辱語、兩舌離間語、與男子同室住宿、與未受具足戒的人同室住宿超過三夜、與未受具足戒的人一同誦經、向未受具足戒的人說其他比丘尼的重罪、", "i": "uGAP24", "n": 297, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "自手掘地、壞生種、露處敷僧臥具、不舉屏處敷僧臥具、強敷僧臥具、惱他比丘尼、用蟲水、", "t": "親手掘地、損壞能生長的草木、在露天鋪設僧團的臥具而離去時不收拾、在屋內鋪設僧團的臥具而離去時不收拾、在他人先已住下的處所強行鋪設僧團的臥具、故意惱亂其他比丘尼、使用有蟲的水、", "i": "uGAP24-2", "n": 298, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "別眾食、非時食、食殘宿食、不受食、共男子屏坐、共男子露坐、觀軍陣、飲酒、水中戲、擊攊他、不受諫、恐怖他、減半月洗浴、露地然火、藏他衣鉢、著白色三衣、", "t": "四人以上別離僧眾受食、非時進食、吃隔宿留存的食物、吃未經如法授與的食物、與男子在隱蔽處共坐、與男子在露天無障蔽處共坐、觀看軍陣、飲酒、在水中嬉戲、搔癢戲弄他人、不接受他人如法的勸諫、恐嚇他人、未滿半月就洗浴、在露地生火、藏匿他人的衣缽、穿著白色的三衣、", "i": "uGAP24-3", "n": 299, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "故斷畜生命、飲蟲水、不攝耳聽戒、瞋心打比丘尼、手搏比丘尼、捉遺落寶、非時入聚落、過量造牀、食蒜、剃三處毛、洗淨過分、", "t": "故意殺害畜生、飲用有蟲的水、說戒時不專心聽戒、以瞋恨心打比丘尼、舉手作勢要打比丘尼、拾取他人遺落的寶物、非時進入村落、製作超過規定尺寸的床、吃蒜、剃除大小便處及腋下這三處的毛、便後洗淨超過規定的分寸。", "i": "uGAP24-4", "n": 300, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "乞生五穀、觀伎樂、共男子入屏障處立語、共男子入屏處、輒坐白衣牀、共男子入暗室、瞋心呪詛、一槌𮌎露身、共尼同牀、口惱他、同活尼病不看、三時無事遊行、泉渠水中露身洗浴、", "t": "乞求生的五穀、觀看歌舞伎樂、與男子一同進入有屏障遮蔽的地方站著說話、與男子一同進入隱蔽處、擅自坐在在家人的床上、與男子一同進入暗室、以瞋恨心咒詛、捶打胸口而裸露身體、與另一位比丘尼同睡一張床、用言語惱亂他人、同住共活的比丘尼生病卻不去看護、在春、夏、冬三時沒有事緣卻到處遊行、在泉水溝渠的水中裸露身體洗浴、", "i": "uGAP24-5", "n": 301, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "輒著他衣、與白衣作使、自手紡績、度諸遮童女、不以二事輒授弟子、受戒已離和尚出去、多度弟子、不半月請教誡、不詣僧自恣、不依僧安居、不白僧入寺、訶罵比丘眾、不白眾使男子治癰、", "t": "擅自穿著他人的衣服、替在家人作使者奔走、親手紡紗績麻、度有遮難的童女受具足戒、不以二事攝授弟子、受戒之後就離開和尚尼出去、度弟子過多、不每半月向比丘僧請求教誡、不前往比丘僧中作自恣、不依比丘僧安居、不先稟白比丘僧就進入僧寺、訶責辱罵比丘眾、不先稟白尼眾就讓男子來醫治癰瘡、", "i": "uGAP24-6", "n": 302, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "背請、於家生嫉妬、用香塗身、乘行、不著祇支入村、不安居、輒問大僧義、百夏尼不禮小比丘，如是等並犯波逸提罪，不憶數。", "t": "背棄已受的齋請、對檀越家生起嫉妒心、用香塗抹身體、乘坐車乘等行路、不穿僧祇支就進入村落、不結夏安居、未經允許就擅自向比丘請問義理、受戒一百夏的比丘尼不禮拜剛受戒的小比丘。以上這些，我都犯了波逸提罪，已記不清犯了多少次。", "i": "uGAP24-7", "n": 303, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "今向大姉發露懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不覆藏。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "現在向大姊發露懺悔，不敢覆藏。懺悔就得安樂，不懺悔就不得安樂。憶念起所犯的罪就發露，知道了就不覆藏。願大姊憶念我清淨、戒身具足，得以清淨布薩。", "i": "uGAP24-8", "n": 304, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "懺已，語云：「汝識是罪否？」答：「識。」又語云。", "t": "懺悔說完之後，懺主尼對她說：「妳知道這是罪嗎？」她回答：「知道。」懺主尼又對她說：", "i": "u699", "n": 305, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "自責汝心，生厭離意，自今已去，更莫重犯，如護鵝珠、草繫比丘無異。」答云：「頂戴持，不敢重犯。", "t": "懺主尼說：「妳要自己責備己心，生起厭離罪過的心意；從今以後，再也不要重犯，要像『護鵝珠』的比丘與『草繫比丘』那樣護持淨戒，沒有兩樣。」懺悔尼回答說：「我恭敬領受奉持，不敢再犯。」", "i": "u700", "n": 306, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第五、懺波羅提提舍尼者：此門先請懺悔主云。", "t": "第五、懺悔波羅提提舍尼罪：這一門中，先要迎請懺悔主，說道：", "i": "u701", "n": 307, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今請大姉為波羅提提舍尼懺悔主，願大姉為我作波羅提提舍尼懺悔主，慈愍故。", "t": "大姊，請專心憶念。我比丘尼某甲，現在請求大姊作我懺悔波羅提提舍尼罪的懺悔主。願大姊為我擔任波羅提提舍尼罪的懺悔主，因為慈悲憐愍我的緣故。", "i": "u702", "n": 308, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，無病經居士家，自乞蘇、油等，不憶數。", "t": "大姊，請專心聽我陳說：我比丘尼某甲，在沒有生病的情況下，行經居士家時，為自己乞求酥、油等，犯的次數已記不清楚。", "i": "u703", "n": 309, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉！我犯可訶法，所不應為，今向大姉發露悔過，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不覆藏。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "大姊！我犯了應受呵責的「可訶法」，這是不該做的事。如今向大姊發露、悔改自己的過失，不敢加以覆藏。懺悔就得安樂，不懺悔就不得安樂。凡憶念起所犯的罪便發露，明知有罪就不覆藏。願大姊憶念我已清淨、戒身具足，能清淨地作布薩。", "i": "u704", "n": 310, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "誡責要期，並如前說。", "t": "懺悔主對懺悔者的告誡責備，以及懺悔者立誓今後不再違犯的承諾，都如同前面所說的一樣。", "i": "u705", "n": 311, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "第六、懺突吉羅者：此律有二：一則故作，犯根本突吉羅，又重犯非威儀突吉羅；二、不故作，直犯非威儀突吉羅。", "t": "第六、懺突吉羅。《四分律》中把突吉羅分成兩種：一是故意造作而犯，結成根本的突吉羅，另外又再犯一條非威儀突吉羅；二是不是故意造作，只犯非威儀突吉羅。", "i": "u706", "n": 312, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "此中亦有從生、獨頭二罪。如從諸篇下生者，無問輕重，以發心不善，欲動身口，並入故作攝。如婬戒，發心動身口，而未起方便色等，乃至突吉羅中，發心欲令身不齊整，著五衣等，不簡輕重，並須對人一說悔。若獨頭吉羅，如眾學百戒等，不從諸篇後生者，亦有故、誤兩罪：故作者對人，誤作者責心。", "t": "這裡面又有「從生」與「獨頭」兩類罪。凡是從其他各篇之下派生出來的，不論輕重，由於發起的心是不善的、想要發動身業口業，所以全都歸入「故作」一類。例如淫戒中，只是發起想要動身、動口的心，還沒有生起方便的身口造作；乃至在突吉羅當中，發起想讓身上五衣穿著不齊整的心等等。這些都不揀別輕重，一律必須對一個人一說懺悔。至於獨頭突吉羅，例如眾學一百條戒等不是從其他各篇派生出來的，也同樣有故意與誤失兩種罪：故意犯的對人懺，誤犯的自責其心而懺。", "i": "u706-2", "n": 313, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "今先對故作重者，有二：先懺覆吉，後悔根本，不得以名同故共根本合懺。故下律云：「若犯僧殘，作僧殘意覆藏，應教作突吉羅懺已，與覆藏羯磨；犯波逸提，乃至突吉羅、惡說，亦如是。」", "t": "現在先就故意造作而屬重的突吉羅來說，這裡有兩個步驟：先懺覆藏所結的突吉羅，再悔根本罪；不可因為名稱同樣叫突吉羅，就把覆藏罪和根本罪合在一起懺。所以下面引律文說：如果犯了僧殘罪，明知是僧殘而加以覆藏，就應先教他作突吉羅的懺悔，懺完之後再給他覆藏羯磨；犯波逸提乃至突吉羅、惡說的情形，也都是這樣。", "i": "u706-3", "n": 314, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "問：如初篇方便重吉，乃至第五篇，輕重既殊，云何齊一說懺？", "t": "問：像初篇波羅夷的方便所結的重突吉羅，乃至第五篇突吉羅的輕突吉羅，輕重既然有差別，為什麼一律都用對人一說的方式懺悔呢？", "i": "u706-4", "n": 315, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "答：悔罪雖齊，業報大異。若約諸篇方便、獨頭犯，乃至無量，今且約婬方便，又更約著衣不齊整獨頭吉羅各一罪作法。竝有經夜、隨覆二吉，通前根本，各有三品吉羅，皆先懺覆罪，後悔根本。並以故心犯戒，此吉是重，齊須對一人說懺。更有餘犯，類牒可知。具修威儀，請一清淨尼云。", "t": "答：懺悔的方法雖然相同，業報卻大有差異。若要把各篇的方便罪與獨頭罪一一列舉，數量乃至無量。現在姑且就淫戒的方便罪，再就穿著衣服不齊整的獨頭突吉羅，各取一罪來示範作法：這兩罪都各有「經夜覆藏」與隨後逐夜展轉覆藏這兩種突吉羅，連同前面的根本罪，就各成三品突吉羅。都要先懺覆藏之罪，再悔根本之罪。因為都是以故意之心違犯戒律，這種突吉羅屬於重的一類，一律必須對一個人陳說懺悔。其餘的犯相，比照這樣逐條牒列就能明白。懺者具整威儀，請一位清淨的比丘尼，這樣說：", "i": "u706-5", "n": 316, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，今請大姉為突吉羅懺悔主，願大姉為我作突吉羅懺悔主，慈愍故。", "t": "大姊，請專一心念。我比丘尼某甲，現在恭請大姊作突吉羅罪的懺悔主。願大姊慈悲憐愍，為我作突吉羅罪的懺悔主。", "i": "u707", "n": 317, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次捨罪云。", "t": "接著是捨罪的陳詞：", "i": "u708", "n": 318, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，故犯婬戒，未動身口前方便，得突吉羅罪，不憶數。識知是罪，故經夜覆藏，得突吉羅罪，不憶數；第二夜已去，乃至多夜隨展轉覆藏，得突吉羅罪，不憶數。又犯著用衣不齊整，得獨頭突吉羅罪，不憶數。識知是罪，故經夜覆藏，得突吉羅罪，不憶數；第二夜已去，乃至多夜，隨展轉覆藏，得突吉羅罪，不憶數。犯此根本方便、獨頭，得突吉羅罪，不憶數。今向大姉懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不敢覆。願大姉憶我清淨，戒身具足，清淨布薩。", "t": "大姊，請一心憶念：我比丘尼某甲，故意違犯淫戒，在身、口尚未發動以前的方便階段，得了突吉羅罪，記不清次數。明知這是罪，卻故意讓它經過一夜而覆藏不說，又得突吉羅罪，記不清次數；從第二夜以後，乃至經過多夜，隨著一夜接一夜輾轉覆藏，又得突吉羅罪，記不清次數。\n又犯了穿著衣服不整齊，得獨頭突吉羅罪，記不清次數；明知這是罪，卻故意讓它經過一夜而覆藏不說，得突吉羅罪，記不清次數；從第二夜以後，乃至經過多夜，隨著一夜接一夜輾轉覆藏，又得突吉羅罪，記不清次數。\n以上所犯的根本罪之方便罪，以及獨頭罪，所得的突吉羅罪，都記不清次數。如今向大姊懺悔，不敢再覆藏。懺悔就得安樂，不懺悔就不得安樂。憶念所犯的罪而發露，明知是罪而不敢覆藏。願大姊憶念我清淨，戒身具足，能清淨地布薩。", "i": "u709", "n": 319, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次明誤犯者：謂不繫念遇緣，豈非外生不善？理須改悔。如著五衣，心不審諦顧看齊整，或戲笑犯妄語等，並由先無攝念，後起諸過。故律云：「若入若出，屈伸俯仰，攝持衣鉢，常爾一心。」若欲懺此，亦先懺覆，後悔根本。具修威儀，禮十方佛竟，然後長跪住，合掌口云。", "t": "其次說明誤犯的情形：這是指沒有繫心守住正念，遇到境緣便生起過非；這難道不是在外在身口威儀上生起的不善嗎？按理仍須改過懺悔。例如穿著五衣時，心裡沒有仔細審察、顧看是否齊整；或因為嬉戲玩笑而犯了妄語等，這些都是由於先前沒有收攝心念，之後才生起種種過失。所以《四分律》說：「若入若出，屈伸俯仰，攝持衣鉢，常爾一心。」意思是：不論進去或出來、屈身伸手、低頭抬頭、收攝持守衣缽，都要恆常保持這樣專注的一心。若要懺悔這類罪，也同樣要先懺除覆藏之罪，然後再懺除根本罪。應當具足威儀，禮拜十方諸佛完畢之後，長跪合掌而住，口中這樣說：", "i": "u710", "n": 320, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "我比丘尼某甲，敬白十方諸佛，證知弟子某甲，不慎威儀，坐起不如法，著衣不齊整，或犯戲笑、妄語等。識知是罪，經夜覆藏，得突吉羅罪，不憶數；第二夜已去，乃至多夜，隨展轉覆藏，得突吉羅罪，不憶數。又犯根本壞非威儀，得突吉羅罪，不憶數。今向十方諸佛發露懺悔，不敢覆藏。懺悔則安樂，不懺不安樂。憶念犯發露，知而不敢覆。願十方諸佛憶我清淨，戒身具足，清淨布薩。", "t": "我比丘尼某甲，恭敬地稟白十方諸佛，請證知弟子某甲：沒有謹慎守護威儀，坐下、起身不如法，穿衣不齊整，或犯了戲笑妄語等。明知這些是罪，卻經過一夜覆藏，得了突吉羅罪，不記得次數；從第二夜以後，乃至多夜，隨著展轉覆藏，得了突吉羅罪，不記得次數。又犯了根本罪，即毀壞威儀而得的非威儀突吉羅罪，不記得次數。如今向十方諸佛發露懺悔，不敢覆藏。懺悔就安樂，不懺悔就不安樂。憶念所犯的罪而發露，明知而不敢覆藏。願十方諸佛憶念我清淨，戒身具足，清淨布薩。", "i": "u711", "n": 321, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "若犯罪未經明相出，或識犯，或疑犯，逼說戒日，未即懺者，應至一清淨尼所發露。先憶得罪云。", "t": "如果犯了罪，明相尚未出現、還未隔夜，無論是確定知道自己已犯，或是懷疑自己有犯，遇到說戒日逼近而來不及立即懺悔的情況，就應當到一位清淨比丘尼那裡發露。先就自己確定記得所犯的罪，這樣說：", "i": "u712", "n": 322, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，犯某罪，未得懺悔，今向大姉發露，後當如法懺悔。", "t": "大姊，請專心聽我說：我比丘尼某甲，犯了某罪，還未能懺悔。現在向大姊坦白披露所犯的罪，之後當如法懺悔。", "i": "u713", "n": 323, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "次發露疑罪云。", "t": "其次，發露尚有疑惑、未確定是否犯戒之罪時，這樣說：", "i": "u714", "n": 324, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "大姉一心念！我比丘尼某甲，於某事上生疑，未得決了，今向大姉發露，後無疑時，當如法懺悔。", "t": "大姊，請專心聽我陳說。我比丘尼某甲，在某件事上起了疑心，還未能判定明白。現在向大姊發露表白，等到日後不再有疑時，定當依律懺悔。", "i": "u715", "n": 325, "s": "第27篇　懺悔"}, {"v": "卷下", "o": "○送終篇第二十八", "t": "第二十八篇：送終。", "i": "u716", "n": 326, "s": "第28篇　送終"}, {"v": "卷下", "o": "此篇大門有六：一、制看，二、簡人，三、供侍，四、安置，五、誡法，六、殯終。", "t": "本篇的大綱分為六門：第一是「制看」，即制定看護病人的規制；第二是「簡人」，即揀選擔任看病的人；第三是「供侍」，即供給所需、侍奉病人；第四是「安置」，即安置病人的處所；第五是「誡法」，即對病人教誡說法的方法；第六是「殯終」，即殯殮送終的事宜。", "i": "u717", "n": 327, "s": "第28篇　送終"}, {"v": "卷下", "o": "第一、制看者：夫人之形，多諸嬰累，四大互反，六腑難調，若不互看，命無所寄。是故律云：「汝曹不相看視，誰當應為？」乃至世尊為病人說法、洗除大小便已，便立制云：「自今已去，應看病比丘，應作瞻病人；若供養我者，應供養病人。」世尊是極果之人，猶親自看病，況同法義重，如何相棄。", "t": "第一，制定看護病人的規制：人的這個身形，有許多苦患纏累，四大相互乖違，六腑難以調適；如果不彼此看護，性命就沒有依托。所以《四分律》中佛說：「汝曹不相看視，誰當應為？」意思是：你們若不互相看護，那該由誰來做這件事呢？乃至世尊為病人說法、替他洗除大小便之後，便立下規制說：「自今已去，應看病比丘，應作瞻病人；若供養我者，應供養病人。」意思是：從今以後，應當看護生病的比丘，應當擔任瞻視病人的人；若要供養我，就應當供養病人。世尊是已證究竟極果的人，尚且親自看護病人，何況同修一法的人彼此情義深重，怎能互相棄捨不顧呢？", "i": "u718", "n": 328, "s": "第28篇　送終"}, {"v": "卷下", "o": "第二、簡人者：此律云：若病者，聽和尚、阿闍棃，乃至同和尚、同闍棃，若弟子等，從親至疎看；若都無者，眾僧應與瞻病人；而不肯看，應次第差；又不肯者，如法治。準若無者，乃至七眾、優婆夷等應看，不應觸比丘。《僧祇》云：當隨病人多少差往，若不看者，一切僧得罪。若道逢比丘乃至病，應覓車乘䭾載令歸，如法供養；乃至死時，應闍維殯埋，不得捨棄，下二眾亦然。", "t": "第二，揀擇看病的人。《四分律》說：若有病人，聽許由和尚、阿闍梨，乃至同和尚、同阿闍梨，或弟子等人，依從親到疏的次序去看護。如果這些人都沒有，僧團就應當為病人指派瞻病人；若被指派的人不肯看護，應依次第輪流差派；差派後仍不肯的，就依律處治。依準此律，若沒有前面這些人，乃至七眾中的優婆夷等也都應當看護，只是不應觸碰比丘。\n《僧祇律》說：應當隨病人數目的多少差派人前往看護；若不看護，全僧都得罪。如果在路上遇到生病的比丘，應尋找車輛或馱畜把他載回來，如法地供給照顧；乃至他去世時，也應為他火化、埋葬，不得捨棄不顧。位次較下的二眾也是這樣。", "i": "u719", "n": 329, "s": "第28篇　送終"}, {"v": "卷下", "o": "第三、供侍者：《僧祇》云：若病人衣鉢外有醫藥直者，取之供給；無者，眾僧應與；若僧無者，彼有貴價衣鉢，當貿賤者受持，餘者供給；若病人惜者，應白僧云：「此病人不知無常，慳惜衣鉢，不肯貨易。」白僧已，輭語說，使得開解，然後為貨易；若復無者，應外求覓與之。若僧中取好食與看病人，不得愛惜自業而不瞻視。", "t": "第三，供給侍病。《僧祇律》說：如果病人在衣缽之外另有買醫藥的錢財，就取來供給他治病；沒有的話，僧眾應當供給；如果僧眾也沒有，而病人有貴重的衣缽，就應當換成便宜的衣缽來受持，多出來的價值拿去供給病人。如果病人捨不得，應當向僧眾稟白說：「這位病人不知無常，慳吝愛惜衣缽，不肯變賣交易。」稟白僧眾之後，再用柔和的言語勸說，使他心開意解，然後才替他變賣交易。如果這樣仍舊沒有，就應當到外面求覓來給他。若從僧眾的食物中取，就取好的食物給看病人。也不得顧惜自己的事務，就不去瞻視照護。", "i": "u720", "n": 330, "s": "第28篇　送終"}, {"v": "卷下", "o": "《五分》云：無淨人處，聽比丘自洗燒器、看水，令淨人淘米著中，比丘然火使熟，更從淨人受取，持與病人，不犯。", "t": "《五分律》說：沒有淨人的地方，聽許比丘自己清洗燒煮的器具、察看鍋中的水，讓淨人淘米放進器具中，比丘再燃火把它煮熟；煮熟之後，還要再從淨人手中受取，然後拿去給病人，這樣不犯。", "i": "u720-2", "n": 331, "s": "第28篇　送終"}, {"v": "卷下", "o": "《五分》云：每僧行粥時，應問別有病人粥否？若無，應先與病人，然後行與僧。", "t": "《五分律》又說：每次僧眾行粥時，應當問：「另外有病人的粥嗎？」如果沒有，應當先給病人，然後才行給僧眾。", "i": "u720-3", "n": 332, "s": "第28篇　送終"}, {"v": "卷下", "o": "《十誦》云：當隨病所須，問病因緣，覓師求藥，日別到僧厨，問有病人食否？若無，取僧所供給庫中物；無者，當為外求，應從善好名聞福德比丘索。又病人得藥差者，但是僧中不淨、殘宿、惡捉、不受、內宿，並得服之。", "t": "《十誦律》說：應當隨病人所需，詢問發病的因緣，尋找醫師、求取藥物；每天到僧眾的廚房問：「有病人的食物嗎？」如果沒有，就取僧眾庫房中供給用的物品；再沒有，就應當替他到外面求取，應向良善、有名望、有福德的比丘索求。又，病人若得到某種藥物便能病癒，那麼凡是僧團中不淨的、隔宿殘存的、惡觸的、未受的、內宿的飲食藥物，都因病開許，可以服用。", "i": "u720-4", "n": 333, "s": "第28篇　送終"}, {"v": "卷下", "o": "《善生》云：瞻病人不應生厭，若自無物，出外求之，不得者，貸三寶物，差已，依法十倍償之。", "t": "《善生》說：瞻視病人的人不應生起厭倦；如果自己沒有財物，就到外面求取；求不到，就借貸三寶的物品；病人病癒之後，依法十倍償還。", "i": "u720-5", "n": 334, "s": "第28篇　送終"}, {"v": "卷下", "o": "《五百問事》云：看病人將病人物，為病人所須供給，不問病者，或問起嫌，並不得用；若已取，應償，不還者犯重。比丘病困，不得闕衣鉢而作功德，若不即有故弊衣鉢受持者，犯墮。", "t": "《五百問事》說：看病人拿病人的財物，為病人供給所需，若不先問過病人，或雖然問了而病人心生嫌恨，這兩種情形都不得使用；如果已經取用，應當償還；不償還就犯重罪。比丘病重困頓時，不得讓自己缺少衣缽，卻把衣缽布施出去作功德；如果不能立即另有舊的弊衣缽可以受持，就犯墮罪。", "i": "u720-6", "n": 335, "s": "第28篇　送終"}, {"v": "卷下", "o": "此律：當問病人持何等衣。彼病人又受不好衣鉢及送與他，恐看病人得，佛言：「不應爾。", "t": "《四分律》說：應當問病人受持的是什麼衣。那位病人卻又受持不好的衣缽，而把好的衣缽送給他人，這是怕看病人得到。佛說：「不應該這樣。」", "i": "u720-7", "n": 336, "s": "第28篇　送終"}, {"v": "卷下", "o": "第四、安置者：《僧祇》：若大德，應在露處上好房中，擬道俗問訊生善；瞻病人每須燒香、然燈、香水塗地，供待人客。《見論》：看病人讚病者言：「長老持戒具足，莫戀著住處及衣物、知識、明友，但存念三寶及念身不淨，於三界中慎莫懈怠，隨命長短而作。」如西國《祗桓圖》云：寺西北角日光沒處為無常院，若有病者，安置在中。堂號「無常」，多生厭背，去者極多，還唯一二。其堂內安一立形像，金色塗之，面向西方；其像右手舉，左手中繫一五色綵幡，令病人手執幡脚，作往生淨土之意。雖有便利，世尊不以為惡。原其此土本是雜惡之處，猶降靈俯接下類羣生，令度苦海；況今信心將命投佛，而棄捨之？隨病者所緣何境，或作彌勒、阿閦等形，如前安置，燒香、散華，種種莊嚴，生病者善心。", "t": "第四、安置病人的處所。《僧祇律》說：若是大德，應安置在顯露易見的地方、上好的房舍中，以便出家、在家二眾前來問訊探視時生起善心。瞻病的人須時常燒香、點燈、用香水塗灑地面，以接待前來探病的人客。\n《善見論》說：看病的人應這樣讚勉病人：「長老持戒具足，不要貪戀住處、衣物以及善知識朋友，只應一心繫念三寶，並觀念自身不淨；在三界之中千萬不可懈怠，要隨自己壽命的長短而努力修善。」\n如西國《祇桓圖》所說：寺院西北角太陽沉沒的方位，設為「無常院」，若有病人，就安置在其中。這堂名為「無常」，住進去的人大多能生起厭離背捨之心；送去的病人極多，能回來的只有一兩個。堂內安設一尊立佛像，塗上金色，面向西方；佛像右手高舉，左手中繫著一條五色綵幡，讓病人用手握住幡的下端垂脚，作往生淨土的意念。即使有大小便的穢污，世尊也不以為嫌惡。推究起來：這個國土本來就是種種穢惡混雜之處，佛尚且降靈垂迹、俯身接引下劣的眾生，使他們度過生死苦海；何況如今病人以信心將性命歸投於佛，佛豈會棄捨他呢？又隨病人心中所攀緣的是哪一佛境，或造彌勒、阿閦等佛像，依照前面所說的方式安置，燒香散花，種種莊嚴，以此引生病人的善心。", "i": "u721", "n": 337, "s": "第28篇　送終"}, {"v": "卷下", "o": "第五、誡法者：《十誦》云：看病人應隨病者先所習學，阿練若、誦經、持律、法師、阿毗曇、佐事，隨其行解而讚歎之，不得毀訾，退彼善心。故律云：「為病人說法，令其歡喜。」《母論》云：病人不用看病人語，看病人違病者意，並得吉羅。", "t": "第五、教誡之法。《十誦律》說：看病的人應當順著病人先前所修學的行業——或是住阿蘭若寂靜處修行的、或是誦經的、或是持律的、或是講說佛法的法師、或是研習阿毗曇論藏的、或是佐助僧眾辦事的——依他各自的行持與理解而加以讚歎，不可毀謗譏嫌而使他退失善心。所以《四分律》說：為病人說法，使他心生歡喜。《毘尼母論》說：病人不聽受看病人的話，以及看病人違逆病人的心意，這兩種情形都犯突吉羅罪。", "i": "u722", "n": 338, "s": "第28篇　送終"}, {"v": "卷下", "o": "第六、殯終者：《五百問事》云：師亡，不得舉聲大啼，應小泣淚耳。此律：尼槌𮌎啼哭泣淚，一一墮。義云：以愛染不亡，俗情弗捨；若高節清居，不著世情，為生物善，哭亦何咎？故雙林終後，比丘等宛轉在地，猶如圓木，搥𮌎大叫，淚下如雨，雖未離欲，然不招世譏。", "t": "第六、殯葬送終。\n《五百問事》說：師父去世時，不可以放聲大哭，只能低聲小哭流淚罷了。《四分律》說：比丘尼搥胸、啼哭、哭泣流淚，一一都犯墮罪（波逸提）。依義理說：這是因為愛染之心未亡、世俗之情未捨的緣故。若是節操高尚、清淨自處、不貪著世情的人，為了生起他人的善心而哭，又有什麼過失呢？所以佛在娑羅雙林入滅之後，諸比丘宛轉滾倒在地，如同圓木一般，搥胸大叫，淚下如雨；他們雖然尚未離欲，卻也不招致世人的譏嫌。", "i": "u723", "n": 339, "s": "第28篇　送終"}, {"v": "卷下", "o": "若外來弔人小於亡人，至於屍所，如常設禮，先執孝子手，默慰弔云云，後至大德所，具展哀情，弔問拜之。《五百問事》、《四分律》等：若見亡人塚塔大於己者，並令禮敬。", "t": "若外來弔唁的人戒臘比亡者小，到了停放遺體的地方，依常規行禮；先握住孝子（亡者的弟子）的手，默默慰問弔唁等等，之後再到大德那裡，充分表達哀傷之情，弔問並向他禮拜。《五百問事》、《四分律》等都說：若見到亡者的墳塚或塔，而亡者戒臘比自己大的，都應當禮敬。", "i": "u723-2", "n": 340, "s": "第28篇　送終"}, {"v": "卷下", "o": "《五百問》云：應先白僧，以亡人泥洹僧、僧祇支覆屍而送，不得埋過五錢，犯重。師、弟子、同學當求財殯送；若無物可送，眾僧、別人斂少財，供養舍利；若全無者，應貸亡人物權將殯之，還來倍償，羯磨竟，從現前僧乞取亦得。", "t": "《五百問事》說：應當先稟白僧眾，用亡者的泥洹僧（內衣、下裙）和僧祇支（覆肩衣）覆蓋遺體再送葬；不得將亡者的財物隨屍埋葬，若所埋財物價值超過五錢，就犯重罪（波羅夷）。應由亡者的師長、弟子、同學籌措財物來殯送。若沒有財物可以辦理喪送，就由僧眾或個別的人各自斂集少許財物，供養舍利（即亡者的遺體）。若完全沒有，就應借用亡者的遺物，暫時拿來辦理殯葬，事後加倍償還；等到（處理亡物的）羯磨結束後，向現前僧乞求取用也可以。", "i": "u723-3", "n": 341, "s": "第28篇　送終"}, {"v": "卷下", "o": "《五分》云：亡屍以衣覆根。《見論》云：不得送喪，除為觀無常，不犯；若手執母屍殯斂，無罪。《增一經》云：如來共阿難、羅云自舉母牀，不令人代，為報恩故。", "t": "《五分律》說：亡者的遺體要用衣服遮蓋下體（男女根）。《善見律毘婆沙》說：不得去送喪，除非是為了觀無常而送，才不犯；若親手執持母親的遺體辦理殯斂，無罪。《增一阿含經》說：如來與阿難、羅云親自抬舉母（佛的姨母大愛道）的靈床，不讓別人代替，是為了報恩的緣故。", "i": "u723-4", "n": 342, "s": "第28篇　送終"}, {"v": "卷下", "o": "義云：和尚、闍梨長養我法身，父母、兄弟長養我生身，恩德既重，躬自擔送，想亦無過，但不得變服。比見邊野僧尼，孝服袈裟，麤布絕白，相同於俗，滅法之原，無過於此！故《摩耶經》云：「佛去世後一千三百秊，諸比丘衣服變白，不受染色，當知法滅不久。」", "t": "依義理說：和尚、阿闍梨長養我的法身，父母兄弟長養我的生身，恩德既然深重，親自擔抬送葬，想來也沒有過失，只是不可以改換僧服。近來見到邊遠荒野地區的僧尼，用粗布做成純白的袈裟當孝服，外相與俗人相同；滅法的根源，沒有比這更嚴重的了。所以《摩耶經》說：佛去世後一千三百年，諸比丘的衣服變成白色，不接受染色，由此應知正法滅亡已不遠了。", "i": "u723-5", "n": 343, "s": "第28篇　送終"}, {"v": "卷下", "o": "西國葬法有四：一、水，二、火，三、土，四、林。《五分》云：屍應埋之，若火燒，在石上，不得草上安。此律：如來、輪王二人火葬。《五百問事》云：得為亡師立形像。《僧祇》云：持律、法師、營事比丘、德望比丘，應起塔相輪，懸施幡蓋，在屏處安置，不得在經行處、多人行處；若違，結罪。若眾僧不許者，教令和合作之。", "t": "西國（印度）的葬法有四種：一是水葬，二是火葬，三是土葬，四是林葬（棄屍於林野）。《五分律》說：屍體應當埋葬；若用火焚燒，要放在石頭上，不可安放在草上。《四分律》說：如來與轉輪聖王這二種人用火葬。《五百問事》說：可以為亡故的師父造立形像。《摩訶僧祇律》說：對持律比丘、法師、營辦僧事的比丘、有德行聲望的比丘，應當為他們起塔，塔上安立相輪（塔頂聳出的圓輪）、懸掛幡蓋；塔要安置在隱蔽處，不得設在經行處或多人來往的地方，若違反就結罪。若僧眾不許可，應勸導大眾和合一致之後再作。", "i": "u723-6", "n": 344, "s": "第28篇　送終"}, {"v": "卷下", "o": "○二衣篇第二十九", "t": "第二十九篇——二衣篇。", "i": "u724", "n": 345, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此篇大門有十：一、制意，二、簡物，三、共財，四、囑授，五、輕重，六、負債，七、賞勞，八、時節，九、分法，十、雜法。", "t": "本篇的大綱共有十門：一是「制意」；二是「簡物」；三是「共財」；四是「囑授」；五是「輕重」；六是「負債」；七是「賞勞」；八是「時節」；九是「分法」；十是「雜法」。", "i": "u725", "n": 346, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第一、制意者：問：所以五眾身亡，物皆入僧？又依三寶出家，何為不兼入佛、法耶？答：以生存之日，因僧受施，身行所為，僧寶所攝；縱施佛、法，僧亦無分。是以身亡之後，追物入僧，佛、法無分，親俗亦不合得。故《十誦》云：難陀死後，諸親白衣競來諍物，佛判不與。欲使三寶位別，無招互用之咎；道俗形殊，又無債索之諍。", "t": "第一，制立本篇的用意。\n問：為什麼出家五眾身故之後，遺物全都歸入僧眾？再者，他們是依於三寶而出家的，為什麼不同時也分歸佛、法二寶呢？\n答：因為在存活之日，是依於僧眾而接受布施，一身所作所為都攝屬於僧寶；縱使布施給佛、法的財物，僧眾也沒有分。所以身故之後，追收遺物歸入僧眾，佛、法二寶沒有分，俗家親屬也不應當取得。因此《十誦律》說：難陀死後，他的諸位在家親屬爭相前來爭奪遺物，佛判定不給他們。這是要使三寶的位分各別，不招致互用三寶物的過失；又因道俗形相有別，也就不會有索債追討的爭執。", "i": "u726", "n": 347, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第二、簡物者：此門有四：一、糞掃想取，《五分》云：界中水漂死人，挂樹枝上，隨前見者得衣；《四分》：無人，得取，若二人已上，便須作法分。二、入二部僧想取，《五分》：獨住死；《婆論》云：二界中間死；此律：無住處白衣家死，隨五眾先來見者得取。三、入俗人親想取，《婆論》云：滅擯死，將衣鉢付生緣，以生時不同僧法故。四、入同和尚僧想取，《十誦》云：沙彌死，所有內外衣，白二羯磨與看病人，輕物入僧，重物不應分；《五分》亦同。此律無文，依彼部斷。", "t": "第二是簡別遺物。這一門有四種：一是作無主糞掃物想而取。《五分律》說：界內被水漂走的死人的衣掛在樹枝上，誰先看見，衣就歸誰。《四分律》說：界內沒有其他人時，先見者就可以取走；若有二人以上，就必須作法分配。二是作歸入比丘、比丘尼二部僧想而取。《五分律》說獨自居住而死的情形，《薩婆多毘尼毘婆沙》說死在兩界中間的情形，本律說在沒有僧人住處的地方、於白衣家中死亡的情形，都任由五眾中先來見到的人取走。三是作歸入俗人親屬想而取。《薩婆多毘尼毘婆沙》說：遭滅擯、被永久逐出僧團的人死了，就把他的衣缽交給俗家的親屬，因為他生前就不與僧眾同法的緣故。四是作歸入同一和尚的僧眾想而取。《十誦律》說：沙彌死了，他所有的內衣、外衣，用白二羯磨給與看病的人；輕物歸入僧眾，重物不應分配。《五分律》也相同。本律沒有明文，就依那些部律來裁斷。", "i": "u727", "n": 348, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第三、共財者：義云：若師本意，唯與弟子衣食，自外餘財不共同者，已給者得，未與者，師亡，以師物悉皆屬僧；實非同生，假冐同生取僧物者，犯重。若師本言，所有財物，決心同共，看如兒想，終無分別者，若當別活、還俗及死者，悉共分半，自著衣服、現用器物各屬其身，未用之財衣或取半，是名共活。不同活妄言而取，能與之僧、所受之人，皆犯二罪：謂重物入常住，準《僧祇》犯重；輕物入現前，準《善生》犯蘭。", "t": "第三是共財的情形。依義理判說：如果師父的本意只是供給弟子衣服與飲食，除此之外的其餘財物並不與弟子共有，那麼已經給了的，弟子就可以取得；還沒給的，師父去世以後，師父的財物全都歸屬僧團。實際上並非師徒共同生活、財物共有的同活關係，卻假冒同活的名義去取僧物的，犯波羅夷重罪。\n如果師父本來就說過，所有財物都決心與弟子共同享有，看待弟子如同兒子一般，始終不作彼此分別，那麼日後師徒之中若有人分開另住、還俗，或者死亡，財物都要平分，各得一半；各自穿著的衣服、當下使用的器物，各歸本人所有；尚未動用的財物與衣物，或可各取一半——這才叫做共活。\n若並非同活，卻謊稱同活而取分僧物，給與的僧人和領受的人，都犯二罪：也就是重物應歸常住僧，依《僧祇律》判犯波羅夷重罪；輕物應歸現前僧，依《優婆塞戒經》判犯偷蘭遮。", "i": "u728", "n": 349, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第四、囑授者：此門有三節：一、囑通善惡，二、囑通前後，三、囑通成否。", "t": "第四是囑授。這一門分為三節：一、囑授通於善與不善；二、囑授有前後的分別；三、囑授通於成就與不成就。", "i": "u729", "n": 350, "s": "第29篇　二衣"}, {"v": "卷下", "o": "初節有四：一、囑授善者，謂自知昔來非法儲積，唯是不善，今好心既發，捨物為福，破己慳貪，此囑名善也。二、囑名不善者，恐此儲財，死後屬僧，慳心便妄囑俗人，此囑名不善也。", "t": "第一節有四種。一是囑授而善的：自己知道一向以來以非法的方式積蓄財物，純是不善；如今善心既已發起，捨出財物來造福，破除自己的慳貪，這樣的囑授叫作善。二是囑授而不善的：怕這些積蓄的財物在自己死後歸屬僧團，慳心一起，就胡亂囑咐給俗人，這樣的囑授叫作不善。", "i": "u729-2", "n": 351, "s": "第29篇　二衣"}, {"v": "卷下", "o": "三、不囑善者，謂病篤之時，惟此偽財，能生不善，佛有誠判，何預我分？先自理心，正念三寶，心心相續，念念不絕，忽爾命終，此不囑名善也。四、不囑名不善者，謂前心欲捨，後心慳惜，恐慮還活，資身無備，恡情愈固，不開惠施，便則命終，此不囑名不善。", "t": "三是不囑授而善的：病重的時候，想到唯有這些虛偽不實的財物能引生不善，佛對此早有明確的判斷，這些財物與我何干，哪還是我分內之物？先自己調理心念，正念繫於三寶，心心相續、念念不斷，忽然就此命終，這樣的不囑授叫作善。四是不囑授而不善的：先前心裡想捨，後來心裡又慳惜，顧慮萬一自己還活過來，資養身命的東西沒有著落，慳吝之情更加牢固，不肯布施，就這樣命終，這樣的不囑授叫作不善。", "i": "u729-3", "n": 352, "s": "第29篇　二衣"}, {"v": "卷下", "o": "二、囑通前後者：《僧祇》云：「囑與眾多人，最後人得；授與眾多人，在前者得。」義準此文犯重：如判決與他，出自我口，後遇緣差，慳惜不與，或轉付別人，便乖本意，如盜得來，轉以施人，是得偷罪。", "t": "第二，囑授有前後的分別。《摩訶僧祇律》說：囑咐給許多人，最後受囑的人得；實際交付給許多人，最先受交付的人得。依這段文義推準，若事後反悔不與，便犯重罪：例如已經決定判給某人，話也從我口中說出去了，後來因緣有了變化，慳惜而不給，或者轉交給別人，就違背了原先的本意；這如同把已屬他人的財物盜取過來，再轉施給別人，得偷盜罪。", "i": "u729-4", "n": 353, "s": "第29篇　二衣"}, {"v": "卷下", "o": "三、囑通成否：《明了論》云：「決心捨已，不犯長。」明知前捨已成，俱不悔者。或病人臨終，遣造經像、供養眾僧，使我眼見，忽即命終者，成；若云死後與我抄經、𦘕像、立墳棺者，不成。", "t": "第三，囑授通於成就與不成就。《明了論》說：「決心捨已，不犯長。」意思是下了決心捨出之後，就不犯畜長衣的罪。由此明知先前的捨施已經成就。凡是前後都不反悔的，囑授便成就：或者病人臨終時派人去造經、造像、供養僧眾，要讓自己生前親眼見到，隨即就命終的，這囑授成就；若說「等我死後，替我抄經、畫像、造墳、備棺」的，囑授不成就。", "i": "u729-5", "n": 354, "s": "第29篇　二衣"}, {"v": "卷下", "o": "故律云：若臨終時，囑與佛、法、僧，若我死後與者，佛言：「一切屬僧。」故知心不決絕，不成囑授。", "t": "所以《四分律》說：若臨終時囑咐把財物給佛、給法、給僧，而說「等我死後再給」之類的話，佛說：一切都歸僧所有。由此可知，心意不決斷徹底，囑授就不成就。", "i": "u729-6", "n": 355, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第五、輕重者：準此亡人衣物，諸部緩急不同，此域諸師各懷異見，或有意親常住，方便入重；或與現前，曲引從輕，倒說乖理，事不合教，爭事由伴，實難消息。", "t": "第五是輕重的判定。就此亡者的衣物而言，諸部律的寬嚴各不相同，此土諸位律師也各懷異見：有的心偏常住，便設方便把物品判入重物；有的要給現前僧，便歪曲引據，判從輕物。顛倒說法，違背道理；處事不合教法。爭端由同侶而起，實在難以斟酌裁斷。", "i": "u730", "n": 356, "s": "第29篇　二衣"}, {"v": "卷下", "o": "既知不易，當問何宗受戒；若渺漠不原，又問此寺何律行事，使始終楷定，大教區分，不得互易，自聒心懷。", "t": "既然知道此事不易，就應問明亡者依哪一部律受戒；若渺茫而無從查明，再問這座寺院依哪一部律行事，使從始至終都有定準。各部律教自有區分，不得互相混用，以免自擾心懷。", "i": "u730-2", "n": 357, "s": "第29篇　二衣"}, {"v": "卷下", "o": "又且邊夷荒鄙，風俗漸殊，資具服章，形名不等，亦須輕重區分，種類非雜，疏條依教，用防紕繆。", "t": "又且邊遠荒僻鄙陋之地，風俗漸有殊異，資身用具與衣服，其形制、名稱都不相同，也須區分輕重，使種類不相混雜；梳理條目須依律教，用以防止錯謬。", "i": "u730-3", "n": 358, "s": "第29篇　二衣"}, {"v": "卷下", "o": "今立《四分》為本，此文不足，餘部補闕。此有三節：一、佛制畜物，如五衣、六物等，以資身道要故，佛判入輕；二、佛不聽畜物，田宅、奴婢、園池、雜畜，以招譏妨道，判入重收；", "t": "如今以《四分律》為根本，此律文有不足處，再以餘部補其闕缺。\n此中分三節：\n一、佛制必須蓄用的物品：如尼眾的五衣、六物等，因為是資養色身、修道的要需，所以佛判入輕物。\n二、佛不聽許蓄用的物品：田地、房宅、奴婢、園林、池沼、各種牲畜，因為會招致譏嫌、妨礙修道，判歸重物收攝。", "i": "u730-4", "n": 359, "s": "第29篇　二衣"}, {"v": "卷下", "o": "三、佛許畜物，如長衣、鉢、錢寶、金銀，以物雖妨道長貪，而道服資具，佛令說淨，畜用無過，而義含輕重，別有三支：", "t": "三、佛開許蓄用的物品：如長衣、缽，以及錢財寶物、金銀。因為這些物品雖然妨道長貪，但道服資具之類，佛令依說淨法淨施他人，蓄用便無過失；而其中義含輕重，另分三支：", "i": "u730-5", "n": 360, "s": "第29篇　二衣"}, {"v": "卷下", "o": "一、性重者，謂一切金銀、錢寶、木石、盆缾、釜鑊、車舉、十六枚器等，以體是重物，不堪隨道故，判入重；二、性輕者，謂一切百一之具，可得隨身，如布絹、絲綿等，莫問多少，佛判入輕；", "t": "（一）性重：指一切金銀、錢寶，木、石、盆、瓶、釜、鑊、車轝、十六枚器等。因為其體是重物，不能隨身攜帶行道，所以判入重物。\n（二）性輕：指一切可以隨身攜帶的百一之具，即六物之外開許蓄用的資身眾具，如布、絹、絲、綿等，不論多少，佛都判入輕物。", "i": "u730-6", "n": 361, "s": "第29篇　二衣"}, {"v": "卷下", "o": "三、從用輕重者，或事重從用輕者，如剃刀及石、盛鉢函、五衣箱、鍼筩、盌盞、匙筯，莫問鐵、瓦、木作者，皆判入輕；或事輕從用重者，如大小悵、步障、枕扇、氈褥、牀惟等，並判入重。", "t": "（三）從用輕重：有的物體本重，依用途則屬輕，如剃刀和磨刀石、盛缽的函匣、五衣箱、針筒、碗、杯、湯匙、筷子，不論是鐵、瓦、木所製，都判入輕物；有的物體本輕，依用途則屬重，如大小帳幔、出行遮擋用的步障、枕頭、扇子、氈毯、褥墊、床帷等，都判入重物。", "i": "u730-7", "n": 362, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此攝不盡，更七支收束，後定輕重，依此而判。", "t": "如此仍收攝不盡，再以七支收束歸納；後面所定的輕重，即依此而判。", "i": "u730-8", "n": 363, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第一、絲麻毛綿所成者：此律：坐臥褥入重；氍氀長五肘、廣三肘、毛長三指，佛判入輕。義準此文，被單亦判入輕，過前者入重。八尺已下輭薄應量氈，例入輕；過量䩕者入重，以不堪著用故。", "t": "第一類是絲、麻、毛、綿所製成的物品。《四分律》中，坐褥、臥褥判入重物；氍氀毛毯長五肘、寬三肘、毛長三指的，佛判入輕物。依這段律文的義意推準，被單也判入輕物，超過上述尺寸的則判入重物。八尺以下、柔軟輕薄、合乎量度的氈，依例判入輕物；超過量度而厚硬的判入重物，因為不堪披著使用的緣故。", "i": "u731", "n": 364, "s": "第29篇　二衣"}, {"v": "卷下", "o": "小氍氀、錦繡、綺色分明者，入重；自餘綾羅等，有鳥獸文者入重，非鳥獸文者入輕。自餘交梭、生絲布等，無問大小，義準入輕，故律開受大價疎衣、種種好衣也。", "t": "小的氍氀、錦繡，以及綺色紋彩鮮明的，判入重物。其餘綾、羅之類，有鳥獸紋樣的判入重物，沒有鳥獸紋樣的判入輕物。其餘交梭布、生絲布等，不論大小，依義理推準判入輕物，所以律中開許接受高價的疎衣以及種種好衣。", "i": "u731-2", "n": 365, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《僧祗》云：漉水囊、二種腰帶、臥具等入輕。《五分》：劫貝單敷、襯身衣、鍼線囊、鉢囊、革屣囊，佛判入輕；錦綺、毛𣯟氈及蚊厨等，入重。準此律，輭小者入輕，䩕大者入重。鍼線袋綵色成者入重。", "t": "《摩訶僧祇律》說：漉水囊、二種腰帶、臥具等，判入輕物。《五分律》說：劫貝（棉布）做的單敷、襯身衣、針線囊、缽囊、革屣囊，佛判入輕物；錦綺、毛𣯟氈以及蚊帳等，判入重物。依本律為準，柔軟而小的判入輕物，厚硬而大的判入重物。針線袋若是用彩色作成的，判入重物。", "i": "u731-3", "n": 366, "s": "第29篇　二衣"}, {"v": "卷下", "o": "纑縷、絲綿等，無問多少，以親成衣故，入輕；縈緝、綟麻等，以非親，入重。盛三衣袋，依《五分》入輕；自外雜用袋等，入重。", "t": "練治好的麻線（纑縷）、絲綿等，不論多少，因為是直接用來成衣的材料，判入輕物；縈緝、綟麻等，因為不是直接成衣的材料，判入重物。裝三衣的袋子，依《五分律》判入輕物；其餘雜用的袋子等判入重物。", "i": "u731-4", "n": 367, "s": "第29篇　二衣"}, {"v": "卷下", "o": "白衣雜線鞾、韈等，及男女衣服，綺色成者入重，非綵色者入輕，為受持入衣財故。", "t": "俗人用雜線作的靴、襪等，以及男女衣服，用彩色作成的判入重物，不是彩色的判入輕物，因為可以受持而納入衣財（作衣的材料）的緣故。", "i": "u731-5", "n": 368, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此律下文：「自今已去，一切俗人衣服，不應著。」義準：今時有尼，故作俗人袍襖、下領、通肩長袖衣等，正判入重。若俗人衣已摘壞者，無問是色、非色，入輕；錦繡雖壞，以色綺故，入重；已染壞者，入輕。", "t": "本律下文說：從今以後，一切俗人的衣服都不應穿著。依義理推準，現今有比丘尼故意做成俗人樣式的袍襖、下領、通肩長袖衣等，正判入重物。若俗人的衣服已經拆解改壞，不論有彩色或無彩色，都判入輕物；錦繡雖然拆解改壞，因為色彩綺麗的緣故仍判入重物，若已染成壞色則判入輕物。", "i": "u731-6", "n": 369, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第二銅鐵瓦木者，此律云：「銅缾、盆器、繩牀、水缾、澡罐、錫杖、扇、斧、鑿、燈臺、机案、車轝，及鐵、皮、竹、木、陶作器等。」此下五種作器，並是能造，判重；剃刀入輕，錢寶等入重。", "t": "第二類是銅、鐵、瓦、木所製的器物。《四分律》說：銅瓶、盆器、繩床、水瓶、澡罐、錫杖、扇子、斧頭鑿子、燈臺、几案、車輛，以及鐵、皮、竹、木、陶五類工匠的作具等。這五種作器都是能造作他物的器具，並非指所造成的成品，判歸重物。剃刀判入輕物，錢財珍寶等判入重物。", "i": "u732", "n": 370, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《十誦》云：「一切染色，若煑、未煑，不應分。」準諸作具，類從入重。《僧祗》：錢、七寶、珠、木槃、木盆、竹笤等入重。《見論》云：「鍼線入輕。」《楞伽經》云：「為割截袈裟故，畜四寸刀，頭如月刃。」義判入輕。過量白鐵、瓷、瓦鉢等，入重。", "t": "《十誦律》說：一切染料，不論已煮或未煮，都不應分；比照各種作具的類別，相從判入重物。《摩訶僧祇律》說：錢、七寶、珠、木盤、木盆、竹笤帚等，判入重物。《善見律毘婆沙》說：針、線判入輕物。《楞伽經》說：為了割截袈裟的緣故，聽許蓄用四寸長、刀頭形如月牙的刀；依義判入輕物。超過定量的白鐵缽、瓷缽、瓦缽等，判入重物。", "i": "u732-2", "n": 371, "s": "第29篇　二衣"}, {"v": "卷下", "o": "若生時造諸擬送終調度等，並判入重；若生存之日，為師僧、父母所造，隨入輕。亡人所屬鏡及屏風、障子、鎻等，以妨長故，義判重收。此律「俱夜羅器」者，相傳云銅盌是，入輕。《十誦》云：「鍵𨩲者，謂小盌也。」《出要律儀》云：「鍵𨩲者，為助食器，秦言淺鐵鉢也。」", "t": "若在生之時造作各種預擬送終用的器具等，都判入重物；若在生之日是為師僧、父母所造作的，就判入輕物。亡者所屬的鏡子，以及屏風、障子、鎖等，因為妨礙道業、增長貪心的緣故，依義判歸重物。《四分律》所說的「俱夜羅器」，相傳說是銅碗，判入輕物。《十誦律》說：「鍵𨩲」就是小碗。《出要律儀》說：「鍵𨩲」是輔助進食的器具，漢地稱為「淺鐵鉢」。", "i": "u732-3", "n": 372, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義準：供養具、經架、佛牀、机案、拂等，及襯香鑪、衣香鑪、經櫃等，若無心作，作時唯擬入佛法供養者，隨亡人意，入佛法用，不得追奪，以別屬故；", "t": "依義理比照供養具：經架、佛床、几案、拂子等，以及襯香爐、熏衣用的衣香爐、經櫃等，若造作時無心為自己畜用，作時只打算供養佛、法的，就隨亡者的心意歸入佛、法之用，不得追回奪取，因為已別有所屬的緣故。", "i": "u732-4", "n": 373, "s": "第29篇　二衣"}, {"v": "卷下", "o": "若生時是己物造作，或他人布施，無別的標者，香爐、經架準《十誦》入輕，《母論》隨能供養者與；若有寶物莊嚴，不可脫者入輕，寶物入重；其餘雜香案，隨香鑪斷。", "t": "若在生時是用自己的財物造作，或是他人布施而沒有明確指定歸屬的，香爐、經架依《十誦律》判入輕物；依《毘尼母論》則隨能供養的人給與他。若有寶物莊嚴，不可脫離的判入輕物，寶物判入重物；其餘雜用的香案，隨香爐的判法來斷定。", "i": "u732-5", "n": 374, "s": "第29篇　二衣"}, {"v": "卷下", "o": "自外佛牀、曲机、夾膝、如意、杖、案、拂、經櫃等，亡人生存不定屬佛法者，死後入重；若定入佛法者，隨亡者意。唾壺入重。木槵、木蘭、竹節數珠，澡豆麪、瓠𤬛，以隨身長道要故，入輕。", "t": "此外如佛床、曲几、夾膝、如意、杖、几案、拂子、經櫃等，亡人在生時若未確定歸屬佛法的，死後判入重物；若已確定歸入佛法的，就隨亡者的心意歸佛法用。唾壺判入重物。木槵子、木蘭、竹節所製的念珠，以及澡豆、麪粉、瓠瓢，因為是隨身攜帶、長途行路所需的要物，判入輕物。", "i": "u732-6", "n": 375, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義判：鐘錢殘物等，施主定屬鐘者，還入鐘用；若施主通者，殘物入常住僧。", "t": "依義判：鑄鐘的錢財與剩餘物料等，施主若指定歸屬鐘的，仍歸入鐘的用處；若施主是通施而無指定的，剩餘之物歸入常住僧。", "i": "u732-7", "n": 376, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第三田宅園林者，入重。《十誦》：赭土入重。義判：雌黃、白墡入重。", "t": "第三類是田地、房宅、園林，都判入重物。《十誦律》說赭土判入重物；依義類推，雌黃與白堊土也同樣判入重物。", "i": "u733", "n": 377, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第四皮物者，《十誦》云：「皮物者，謂盛油囊受半斗已下，及繫革屣韋等。」入輕。《僧祇》云：「聽分革屣。」準此，平鞾、屣、韈入輕，鈄鞾等入重，以相同俗故。此律云：「一切皮衣不得著。」入重。《母論》云：「經律先有付囑處，即依付彼；若無付囑，隨能受持者與。」義判：一切俗書、素𦘕絹等入重；如肇師《五論》、皎公《高僧傳》等兼有內語者，入輕，別人能讀亦得。", "t": "第四類是皮製品。《十誦律》說：所謂皮物，是指容量在半斗以下的盛油皮囊，以及繫縛革屣用的皮條等，這些判入輕物。《摩訶僧祇律》說：革屣聽許分給僧眾。依據這兩部律，平靴、鞋、襪判入輕物；鈄靴等則判入重物，因為它們的形相與俗人所穿的相同。《四分律》說：一切皮衣都不許穿著；依此判入重物。\n《毘尼母論》說：經書與律典，生前若已有付囑的去處，就依照付囑交付給那一方；若沒有付囑，就隨能受持讀誦的人給與他。依義判定：一切世俗書籍、素絹上的圖畫等判入重物；至於像僧肇法師的五篇論、慧皎法師的《高僧傳》等，兼含佛法內典言論的，就判入輕物，個人若能讀誦，也可以分給他。", "i": "u734", "n": 378, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第五畜生者，依《母論》入重。", "t": "第五類是牲畜：依《母論》所說，判入重物。", "i": "u735", "n": 379, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第六奴婢者，此律入重，所有私物莫問輕重，並入彼人。若常住僧奴婢死者，衣物與親里；若無親者，供常住僧用。若私奴婢死，同衣食者，所有資財入己分處；若不同財，直令輸課，或分番上下得功力者，所有資財入親；無親者，事同無主物。", "t": "第六類是奴婢：依《四分律》判入重物。奴婢自己私有的財物，不論是輕物還是重物，一律都歸奴婢本人所有。如果是屬於常住僧的奴婢死了，他的衣物就交給他的親屬；若沒有親屬，就供常住僧使用。如果是私人所有的奴婢死了：凡是與主人同衣同食、一起過活的，他所有的資財就由主人自己收取歸己，隨意處分；若是與主人財物各自分開，主人只是叫他繳納定額的租課，或者把他編成班次輪流上工、下工，只取他的勞力而已，這種奴婢死後，所有資財歸他的親屬；若沒有親屬，就比照無主之物處理。", "i": "u736", "n": 380, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第七四藥，時與非時、七日等，盡判入重。上來所列，且據大宗，其中未盡，準例可知。然《四分》澡罐、錫杖、鍼錐、刀子等雖判入重，依《十誦》、《五分》入輕，不爽大理，以隨身要用故，不同餘妨道等物。", "t": "第七類是四種藥：時藥與非時藥、七日藥等，全都判歸重物。以上所列舉的，只是就大體而言；其中沒能一一列盡的物品，比照這些例子便可以推知。不過，《四分律》雖把澡罐、錫杖、針、錐、刀子等判入重物，依《十誦律》、《五分律》卻判入輕物，這樣並不違背大體的原則，因為它們是隨身必用的東西，和其他妨礙修道的物品不同。", "i": "u737", "n": 381, "s": "第29篇　二衣"}, {"v": "卷下", "o": "六負債者，若佛法、別人負亡人，亡人負佛法、別人輕重物者，若有則相當還，無則交絡還。所以須索者，以重物入常住僧，輕物入現前僧。先負亡人輕物者，今索得重物，還須博輕物分；若先負亡人重物，今索得重物者入重；以本是重物者入重，以本是輕物令僧分。常住僧負亡人重物者，不須索取，以還入常住故；若負輕物，索取現前僧分。若別人負輕重二物，俱須索取，以重物入常住，輕物入現前。", "t": "第六、負債。不論是佛物、法物或個別僧人欠亡者的，或是亡者欠佛物、法物、個別僧人的，所欠都含輕物與重物：若有輕重同類相當之物，就同類相抵而還；沒有同類的，就輕重交互抵還。之所以必須追索，是因為重物要歸常住僧，輕物要歸現前僧。先前欠亡者輕物的，如今索回的卻是重物，還須換成輕物再分；先前欠亡者重物的，如今索回的也是重物，就判入重物而歸常住僧；因為本屬重物的就判入重物，本屬輕物的才交現前僧分。常住僧欠亡者重物的，不必追索，因為索回後仍舊歸入常住；若欠的是輕物，就要索回給現前僧分。個別僧人欠輕、重兩種物的，兩種都必須追索，因為重物歸常住僧，輕物歸現前僧。", "i": "u738", "n": 382, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《十誦》云：「生時負三寶物，應歸；若三寶貸亡人物，索取入現前。」故須並索，依本而斷，乃至四方現前、客舊互負之物，亦同上說。", "t": "《十誦律》說：亡者生前欠三寶的物，應當歸還；若三寶借了亡者的物，則要索回入現前僧。所以兩方面都必須追索，再依本物的輕重來判定歸屬。乃至四方僧與現前僧、客來者與舊住者之間互相欠負的物，也同上面所說。", "i": "u738-2", "n": 383, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《十誦》云：「生時賖取他酒，未還價便死。佛言：『取衣鉢還；若無物歸，應取僧物還，恐出諸比丘惡聲故。』」義準：若負餘物，不生譏過者，不還無罪，以亡人無物故；有物者應還。", "t": "《十誦律》說：生前向人賒酒，還沒付酒錢就死了，佛說：取他的衣缽去償還；若沒有財物可還，應取僧物來還，因為怕傳出諸比丘的壞名聲。依義理準此：若欠的是其他東西，不會引起譏嫌過失的，不償還也無罪，因為亡者已沒有財物的緣故；若還有財物，就應當償還。", "i": "u738-3", "n": 384, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《十誦》云：「先與他衣價，死時還索取；取他衣未與價，若死還本衣，無者賣衣鉢還。」", "t": "《十誦律》說：生前先把衣價付給了對方，死後僧眾應向對方索回；若是拿了對方的衣還未付價，死後就把原衣歸還；原衣已沒有的，就賣衣缽來償還。", "i": "u738-4", "n": 385, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《母論》云：「若有息物在外，遣淨人推求，取入此寺常住僧。」義準此文，若負物在白衣家，同《四分》無住處死，五眾先見者得；其重物隨前見者處分。", "t": "《毘尼母論》說：若有放債生息的財物在外，應派淨人追查索回，歸入本寺常住僧。依此文義理準斷：若所欠的財物在俗人家中，就比照《四分律》中在沒有僧寺住處之地命終的規定，由五眾出家人中最先見到的人取得該物；其中的重物，則隨最先見到者所在的住處來處置分配。", "i": "u738-5", "n": 386, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《五百問事》云：「比丘借人物，前人死，要須白僧，得取本物，不白得罪；若不與強取，或僧知而不還，自他二俱得罪。」", "t": "《五百問事經》說：比丘把東西借給別人，那人死了，比丘必須先向僧白告，才可以取回自己的原物；不白告就取，便得罪。若僧不給而強行取走，或僧明知卻不歸還，自己與僧雙方都得罪。", "i": "u738-6", "n": 387, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《僧祇》云：「若索債者，當看前人持戒可信者與，不可信者不應與；若可信人證明者應與，反此不得。", "t": "《僧祇律》說：有人來索債時，應當觀察對方：持戒而可信的，就給；不可信的，不應給；若有可信的人作證明，就應給；反之則不得給。", "i": "u738-7", "n": 388, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第七賞勞者，此律有二五德。初五德者，病人難看，表瞻病者德滿：一、病人所不應食而欲食，不肯服藥；二、看病人有至心而不如實語；三、應住不住等；四、身有苦痛而不能忍；五、身堪能而不作，抑他作，又不能靜坐止息內心。", "t": "第七、賞勞：本律中列有兩種「五德」。第一種五德，是說病人難以照護，以此彰顯看護者的德行圓滿：一、病人不該吃的卻想吃，又不肯服藥；二、看護者雖懷至誠之心，病人卻不據實相告；三、應當安住卻不安住等；四、身體有苦痛卻不能忍耐；五、身體尚能自己做事卻不肯做，反而要求別人代做，又不能靜坐止息內心。", "i": "uGAP25-1", "n": 389, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第二五德者，明看病人自行德滿：一、知病人可食不可食，可食應與；二、不惡賤病人大小便利、唾吐；三、有慈悲心，不為衣食故看；四、能經理湯藥，乃至差若命終；五、能為病人說法，令病人歡喜，己身於善法增長。", "t": "第二種五德，說明看護者自身的德行圓滿：一、知道病人什麼能吃、什麼不能吃，能吃的就給予；二、不嫌惡鄙視病人的大小便與痰唾、嘔吐物；三、心懷慈悲，不是為了貪圖衣食才去看護；四、能妥善調治湯藥，直到病人痊癒或命終；五、能為病人說法，使病人心生歡喜，自己也在善法上有所增長。", "i": "uGAP25-2", "n": 390, "s": "第29篇　二衣"}, {"v": "卷下", "o": "有二五德者，應與看病人衣物；若小瞻病，無好至心，佛判不與。", "t": "具備這兩種五德的人，應當把亡者的衣物給與這位看護病人者；如果只是稍微照料一下、沒有真誠懇切的心，佛陀判定不應給予賞物。", "i": "uGAP25-3", "n": 391, "s": "第29篇　二衣"}, {"v": "卷下", "o": "僧祇》云：「有四種看病不合賞物：一、暫作看，不懷久意；二、僧次差看；三、自樂福德，不憐愍；四、邪命而看，止為利養。並不合得。若欲饒益病者，欲令速差之意，下至然一燈見命終者，應得。」", "t": "《僧祇律》說，有四種看護不應當賞賜衣物：一、只是暫時看護，沒有長久照顧的心意；二、由僧眾依輪次指派看護；三、只圖自己積集福德，並不憐愍病人；四、心懷邪命而來看護，只為了求取利養。這四種都不應當獲得賞物。如果是出於想要利益病人、盼望病人早日痊癒的心意，哪怕才點燃一盞燈就遇上病人命終，也應當獲得賞物。", "i": "uGAP25-4", "n": 392, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此律莫問德之優劣，應與受持衣；若不知何者是受持衣，應量，瞻病人有上、中、下，若極上看病，與上三衣，中、下看者，與中、下三衣。", "t": "本律說：不必問看護者德行的優劣，應當將亡者生前受持的衣給予看護者。如果不知道哪些是受持衣，就應當衡量看護者的表現分為上、中、下三等：若是極為上等的看護者，給予上等的三衣；若是中等或下等的看護者，給予中等或下等的三衣。", "i": "uGAP25-5", "n": 393, "s": "第29篇　二衣"}, {"v": "卷下", "o": "十誦》：先問看病人受持何衣鉢，一一別問；或不知，或不信者，應與中六物。", "t": "《十誦律》說：應先向看護者詢問亡者生前受持哪些衣鉢，逐一分別問明；如果不知實情或不被採信，就應當給予中等的六物。", "i": "uGAP25-6", "n": 394, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此律賞勞六物者：三衣為三，鉢盂為四，坐具為五，鍼筩為六。又文加十，盛衣、貯器者：盛衣者，猶是盛衣袋及五衣襆；貯器者，猶是鉢袋及函等，此並通入賞勞也。", "t": "本律所說賞勞的六物，是指三衣算作三件，鉢盂為第四件，坐具為第五件，針筒為第六件。又律文中再加入盛衣與貯器而成為十物：所謂盛衣，就是盛衣袋及五條衣的包袱；所謂貯器，就是鉢袋及鉢盒等。這些都一併列入賞勞之中。", "i": "uGAP25-7", "n": 395, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義準：一、德物並具，二、德具物不具，此二合賞；三、物具德不具，四、德物俱不具，此二不合賞。", "t": "依義理推準，有四種情況：一、德行與物品都具備；二、德行具備而物品不齊全，這兩種情況應當賞賜；三、物品齊全而德行不具備；四、德行與物品都不具備，這兩種情況不應當賞賜。", "i": "uGAP25-8", "n": 396, "s": "第29篇　二衣"}, {"v": "卷下", "o": "而看病辛苦，而欲優饒者，束入現前，作羯磨訖後，量德優劣，三唱口和僧，隨多少賞之。", "t": "然而，若是看護辛苦而大眾想要優厚酬賞的，就將衣物總束歸入現前僧中，作完羯磨之後，衡量其德行優劣，口頭三唱徵得僧眾和合同意，隨多少酌量賞賜給他。", "i": "uGAP25-9", "n": 397, "s": "第29篇　二衣"}, {"v": "卷下", "o": "五分》、《十誦》：比丘病時，七眾應看，二眾合得衣，謂比丘及沙彌；雖父母、兄弟看而不應與，勞不滿德故。", "t": "《五分律》、《十誦律》說：比丘生病時，七眾都應當看護；但只有二眾應當獲得賞衣，就是比丘與沙彌。即使是父母、兄弟前來看護，也不應當給予，因為其辛勞未滿應得之德的緣故。", "i": "uGAP25-10", "n": 398, "s": "第29篇　二衣"}, {"v": "卷下", "o": "伽論》云：「白衣看，應與少許。」", "t": "《摩得伽論》說：在家人看護病人，應當給予少許。", "i": "uGAP25-11", "n": 399, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義準：若多尼、式叉、沙彌尼看病者，應與究竟者；若齊究竟者，應與一人已，屏處分等。", "t": "依義理推準：如果有多位比丘尼、式叉摩那、沙彌尼看護病人，應當給予看護至最終的那一位；如果是大家一齊看護到底的，應當先給予其中一人，之後再到私下處所平均分配。", "i": "uGAP25-12", "n": 400, "s": "第29篇　二衣"}, {"v": "卷下", "o": "十誦》云：「若看病者出行為病人乞衣藥，合得三衣者，應留待身還與。」亦可攝入現前唱和付，亦得。若餘處比丘來看病，亦與賞。", "t": "《十誦律》說：如果看護者外出為病人乞求衣物與湯藥，依法應當獲得三衣的，應當將衣物留存，等他本人回來再給予；也可以歸入現前僧中，經唱白徵得大眾和合同意後再行交付，這樣也可以。如果有其他住處的比丘前來看護病人，也應當給予賞勞。", "i": "uGAP25-13", "n": 401, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第八時節者，《僧祗》云：「若病人死，不應即開其戶。彼有弟子持戒可信者，與戶鈎；若不可信，持戶鈎付僧知事人已，先供養舍利，料理竟，弟子持戒可信者，使出衣物；若不可信，應使知事人出衣物，然後僧分。」《十誦》：就屍邊分衣，屍起護衣，佛言：「待屍去後，或在異處應分。", "t": "第八，分配的時節。《摩訶僧祇律》說：病人死了，不應該立刻打開他的房門。他若有持戒而可信賴的弟子，就把房門的鑰匙交給這個弟子；如果弟子不可信賴，就把鑰匙交給僧團裡掌事的知事人。先供養亡者的遺體，把後事料理完畢；弟子持戒而可信賴的，就讓他把衣物取出，若不可信賴，就應讓知事人取出衣物，然後才由僧眾分配。《十誦律》說：曾有比丘在屍體旁邊分衣，屍體竟起身護惜衣物。佛說：應等屍體移走之後，或者僧眾在別的地方，才可以分。", "i": "u739", "n": 402, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第九分法者，此門有三節：一、羯磨，二、對首，三、心念。", "t": "第九、分配的方法：這一門有三節：一是羯磨法；二是對首法；三是心念法。", "i": "u740", "n": 403, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第一羯磨中，五人得作賞勞分衣羯磨；若四人者，止得分衣，不成賞勞，以僧不滿故，寧可羯磨後，將衣物口和賞勞。《母論》云：「由四人中牒一人入羯磨，餘三不成僧故。」今立法者，令瞻病人將亡人輕重二物並集僧中；重物不可勝舉，多者知數已，直付僧庫亦得。晝日作法彌善，不得閉門限約客尼，以通十方，理無私背故。《婆論》云：「白日閉門已，不打鐘打鼓食者，名盜僧食罪。」又此分衣不成，而此物者，人人各有分，而有心限約客者，各犯微塵數偷蘭遮故。《善生經》云：「盜亡比丘衣物者，若未羯磨，望十方僧得罪；若羯磨已，望同羯磨僧。滿五得夷，不滿偷蘭。」看病人應近物邊，長跪執物捨之；若無看病尼，維那捨之亦得。", "t": "第一是羯磨法。有五位比丘尼，就能作賞勞與分衣兩種羯磨；若只有四位，只能作分衣羯磨，賞勞羯磨則不成就，因為僧數不足。這時寧可在分衣羯磨之後，把衣物拿出來，以口頭唱和的方式賞給看病人作為酬勞。《母論》說：因為四人當中要把受賞的看病人一人牒舉入羯磨文，剩下的三人就不成僧了。\n現在立此作法：讓瞻病人把亡者的輕物與重物兩類，一併集中到僧眾當中；重物無法全部搬舉、或數量太多的，只要點知數目，直接交付僧庫也可以。在白天作法更好，不得關起門來限制排斥客尼，因為這本通於十方僧，按理不容私自偏背。《婆論》說：白天關了門，又不打鐘打鼓招呼客僧，這樣進食的人就名為犯盜僧食之罪。而且這樣分衣也不成就。這些衣物人人都有分，若存心限制排斥客尼，就各各犯下如微塵數那樣多的偷蘭遮罪。所以《善生經》說：盜取亡比丘衣物的人，若還未作羯磨，是望十方僧結罪；若已作羯磨，則望同作羯磨的僧眾結罪——所盜滿五錢得波羅夷，不滿五錢得偷蘭遮。看病人應到衣物旁邊，雙膝長跪，手執衣物，將它捨給僧眾；若沒有看病尼，由維那來作捨也可以。", "i": "u741", "n": 404, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼於某住處命過，所有若衣若非衣，此住處現前僧應分。我比丘尼某甲，今捨與僧。", "t": "各位大姊，請僧眾聽我說：某甲比丘尼在某住處去世了，她所留下的東西，不論是衣類或非衣類，都應由這個住處現前的僧眾分取。我比丘尼某甲，現在把這些物品捨給僧眾。", "i": "u742", "n": 405, "s": "第29篇　二衣"}, {"v": "卷下", "o": "眾中明律者即決判云：先問僧中，誰知亡人負三寶、別人物？又誰知三寶、別人負亡人物？一一撿問有無竟，然後決定輕重，重物一處著，輕者一處著。并問看病人將亡人輕重物送死否？若有，索取輕物入羯磨分，重者入僧；若本盜心將送終者，不合索分，已成盜故；若權借用或無犯心者，應索分，不成盜故。具問前已，後量德賞勞。若五德不具，則不合賞。今行事者，直對僧問德具已否；若答不具者，極成鄙惡；具者合與，然有勞合得。既知如此，必看病有功合賞者，律師語云：「大姉，看病實有功勞，佛令優賞，若也不與，便違聖教，大姉宜可順教取之。」其看病尼又陳無德，僧復抑受；如是相讓，彼此生善，非直自行可觀，亦則眾儀生善。知此事已，然後問。", "t": "僧眾中明了律法的人，就當場裁決說：先問僧眾裡有誰知道亡者欠了三寶或個人的財物，又有誰知道三寶或個人欠了亡者的財物；這樣逐一查問有無之後，再判定財物的輕重，重物放在一處，輕物放在另一處。同時要問看病人：是否曾拿亡者的輕物、重物去辦喪事？如果有，就把它索回：輕物納入羯磨中分配，重物則歸入僧眾。如果看病人當初是以盜心拿去辦喪事的，他就不合索取賞勞的分物，因為盜罪已經成立；若是暫時借用，或沒有犯盜之心的，就應索取分物，因為並未構成盜。\n前面的事項都問清楚了，接著才衡量德行來賞勞。若五德不具足，就不合給予賞物。現今辦事的人，直接當著僧眾問看病者德行是否具足：若回答不具足，就顯得極為鄙陋難堪；回答具足的，固然合於給予，而且有辛勞就應該得賞。既然知道這個道理，對於看病確實有功、合當受賞的人，律師就對她說：「大姊！妳看病實在有功勞，佛制令要優厚地賞給；如果不給，就違背了聖教。大姊應當順從佛的教敕領受才是。」那位看病尼又謙稱自己無德，僧眾再強令她接受。像這樣彼此謙讓，雙方都生起善法；不但自己的行持值得稱許，僧眾的儀則也同樣從中生起善法。明白了這件事之後，才接著發問。", "i": "u743", "n": 406, "s": "第29篇　二衣"}, {"v": "卷下", "o": "僧今和合，何所作為？」答：「作賞勞羯磨。", "t": "問：僧眾現在已經和合集會，要做什麼事？答：作賞勞羯磨。", "i": "u744", "n": 407, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼命過，所有衣鉢、坐具、鍼筩、盛衣、貯器，此住處現前僧應分。若僧時到，僧忍聽，僧今與看病比丘尼某甲。白如是。", "t": "諸位大姊，請僧眾聽我說：某甲比丘尼已經去世，她所有的衣、缽、坐具、針筒，以及盛裝衣物的袋子、貯放缽的容器，這些本應由這個住處的現前僧眾來分配。如果僧眾認為時機已到，請僧眾聽許：僧眾現在把這些物品給與照顧病人的比丘尼某甲。以上的白告就是這樣。", "i": "u745", "n": 408, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼命過，所有衣鉢、坐具、鍼筩、盛衣、貯器，現前僧應分，今與看病比丘尼某甲。誰諸大姉忍，僧與看病比丘尼某甲衣鉢、坐具、鍼筩、盛衣、貯器者默然，誰不忍者說。僧已忍，與看病比丘尼某甲衣鉢、坐具、鍼筩、盛衣、貯器竟。僧忍默然故，是事如是持。", "t": "各位大姊，請僧眾聽著：某甲比丘尼已經去世，她所有的衣、缽、坐具、針筒，以及盛衣袋襆、貯物器具，應由現前的僧眾分取；現在要給與看護病人的比丘尼某甲。諸位大姊當中，誰贊同僧眾把衣、缽、坐具、針筒、盛衣袋襆、貯物器具給與看護病人的比丘尼某甲的，就保持沉默；不贊同的，請說出來。僧眾已經認可，把衣、缽、坐具、針筒、盛衣袋襆、貯物器具給與看護病人的比丘尼某甲，此事已經完畢。由於僧眾忍可而默然的緣故，這件事就這樣認定、這樣執行。", "i": "u746", "n": 409, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義云：應隨物多少稱，不得依文總誦，恐無事不稱，羯磨名為非法；羯磨雖成，仍獲小罪，如二沙彌一時受戒，一有難、一無難，無難者自成無妨，小罪乃得。《婆論》云：「三衣餘處索來此賞，若此德不具，即隨彼分。」若依《十誦》，沙彌死時羯磨應云。", "t": "依義理而言：應當隨實際物品的多少來稱說，不可照著羯磨文一概全部念誦，恐怕其中有些物品實際並不存在，念出來就與事實不符，這樣的羯磨便名叫「非法羯磨」；羯磨雖然成就，作法的人仍會犯小罪。譬如兩位沙彌同時受戒，一位有遮難，一位沒有遮難，沒有遮難的那位得戒自然成就、沒有妨礙，但作法的人仍得小罪。《婆論》說：亡者的三衣若放在別處，應索取回來，在此處賞給看病人；若此處看病人五德不具足，三衣就隨彼處僧眾去分配。若依《十誦律》，沙彌尼去世時，羯磨文應當這樣說：", "i": "u747", "n": 410, "s": "第29篇　二衣"}, {"v": "卷下", "o": "某甲沙彌尼命過，所有內外衣及非衣應分。", "t": "某甲沙彌尼已經去世，她所有的內衣、外衣以及衣類以外的物品，都應當分配。", "i": "u748", "n": 411, "s": "第29篇　二衣"}, {"v": "卷下", "o": "餘語同前僧也。次明分輕衣羯磨法，羯磨師問云。", "t": "其餘的文句都與前面僧眾的作法相同。接著說明分配輕衣的羯磨法。羯磨師問道：", "i": "u749", "n": 412, "s": "第29篇　二衣"}, {"v": "卷下", "o": "僧今和合，何所作為？」答：「分亡比丘尼輕衣物羯磨。", "t": "僧眾如今和合集會，是要辦什麼事呢？答：辦分配亡故比丘尼輕衣物的羯磨。", "i": "u750", "n": 413, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姊僧聽！某甲比丘尼命過，所有若衣若非衣，現前僧應分。若僧時到，僧忍聽，僧今持此衣物，與比丘尼某甲，比丘尼某甲當還與僧。白如是。", "t": "各位大姊僧眾請聽：某甲比丘尼已經去世，她所遺留的衣物，不論是衣類或非衣類的東西，都應由現前的僧眾分配。如果僧眾認為時機已到，請僧眾忍可聽許：僧眾現在把這些衣物交給比丘尼某甲，比丘尼某甲應當再交還給僧眾。以上的白告就是這樣。", "i": "u751", "n": 414, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼命過，所有若衣若非衣，現前僧應分，僧今持此衣物，與比丘尼某甲，比丘尼某甲當還與僧。誰諸大姉忍，某甲比丘尼命過，所有衣物，現前僧應分，僧今持此衣物，與比丘尼某甲，比丘尼某甲當還與僧者默然，誰不忍者說。僧已忍，持此衣物，與比丘尼某甲，比丘尼某甲當還與僧竟。僧忍默然故，是事如是持。", "t": "各位大姊僧眾請聽：某某比丘尼已經命終去世，她所遺留的衣類與非衣類物品，應由現前的僧眾分取。僧眾現在把這些衣物交給比丘尼某某，比丘尼某某應當再交還給僧眾。哪位大姊同意某某比丘尼命終去世、她所有的衣物應由現前僧眾分取、僧眾現在把這些衣物交給比丘尼某某、比丘尼某某應當再交還給僧眾的，就請默然；不同意的，請說出來。僧眾已經同意，把這些衣物交給比丘尼某某、比丘尼某某應當再交還給僧眾，這番羯磨已經作法完成。由於僧眾默然認可的緣故，這件事就這樣認定執行。", "i": "u752", "n": 415, "s": "第29篇　二衣"}, {"v": "卷下", "o": "五分》云：「若衣少不徧者，和僧與一無衣比丘。」若有一衣上好者，依《見論》云：「從上次第行之，須者直付，不須至下。」", "t": "《五分律》說：如果衣太少，不夠普遍分給每一個人，就徵得僧眾的和合同意，把它給一位沒有衣的比丘。如果其中有一件衣特別上好，依《善見律毘婆沙》所說：從上座開始，按次第往下輪，誰需要就直接交給他，不必再往下輪問。", "i": "u753", "n": 416, "s": "第29篇　二衣"}, {"v": "卷下", "o": "問：「作羯磨已，和僧為亡人乞修齊福得否？」答：「出家之士，以智德居懷，不要修福為業，依判入僧，最為殊勝；若外生物善，內捨貪心，隨將少多為亡人為福，此則二行俱益，存亡並利也。」", "t": "問：作完分物的羯磨之後，可以徵得僧眾同意，把亡者的遺物拿去為亡者設齋修福嗎？答：出家之士以智慧德行存心，不以修福為本業；依律所判，把遺物歸入僧眾最為殊勝。但若對外能生起他人的善心，對內能捨除自己的貪心，那麼隨意拿出或多或少的遺物為亡者修福，這樣兩種行持都得利益，在世者與亡故者同霑其利。", "i": "u753-2", "n": 417, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《僧祇》云：「或為病人求覓衣藥，或為僧勞事，雖當時不在，並應與分。」", "t": "《摩訶僧祇律》說：有人為病人出去尋求衣物湯藥，有人為僧眾操辦辛勞的事務，雖然分物當時他們不在場，也應該分給他們一份。", "i": "u753-3", "n": 418, "s": "第29篇　二衣"}, {"v": "卷下", "o": "問：「式叉尼、沙彌尼、家人、淨人等，合與分否？」答：「此律云：『若僧和合，應與沙彌等分；若不和合，乃至四分中與一分，淨人五分中與一分；若不得者，不應分，若分得罪。』」", "t": "問：式叉摩那尼、沙彌尼、家人、淨人等人，該不該分給他們一份？答：《四分律》說：若僧眾和合同意，應給沙彌等人與比丘尼同等的一份；若僧眾不同意給同等分，就減為一人分的四分之一給沙彌；淨人則只給一人分的五分之一。如果僧眾不允許給，就不應分給他們；若擅自分了，便得罪。", "i": "u753-4", "n": 419, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《母論》云：「若五人共住，一人死者，其衣鉢等，三人口和賞一看病人，餘之四人，但得作直分羯磨，不須展轉分之。」賞勞云。", "t": "《毘尼母論》說：若五人共住，其中一人死了，亡者的衣缽等物，由三人口頭和合同意，賞給那一位看病的人；其餘四人只須作直分（直接分配）的羯磨，不必再依展轉相付的方式來分。以下是講酬賞看病辛勞，文中說：", "i": "u753-5", "n": 420, "s": "第29篇　二衣"}, {"v": "卷下", "o": "諸大姉憶念！今持此亡某甲比丘尼衣鉢、坐具等，賞某甲看病比丘尼。」直分羯磨云。", "t": "「各位大姊請留意：現在把這位已故某甲比丘尼的衣、鉢、坐具等物，賞給照顧病人的某甲比丘尼。」直接分配的羯磨文如下：", "i": "u754", "n": 421, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼命過，所有若衣若非衣，現前僧應分。若僧時到，僧忍聽，僧今分此衣物。白如是。", "t": "各位大姊，請僧眾聽著：某甲比丘尼已經命終，她所有的物品，不論是衣物還是非衣類之物，都應由現前的僧眾分配。如果僧眾認為時機已到，請僧眾認可聽許：僧眾現在就分配這些衣物。以上的稟白就是這樣。", "i": "u755", "n": 422, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉僧聽！某甲比丘尼命過，所有若衣若非衣，現前僧應分。誰諸大姉忍，僧今分此衣物者默然，誰不忍者說。僧已忍，僧今分此衣物竟。僧忍默然故，是事如是持。", "t": "各位大姊，請僧眾聽著：某甲比丘尼已經命終，她所留下的物品，無論是衣類或非衣類，都應由現前的僧眾來分配。諸位大姊當中，凡是贊同僧眾現在分配這些衣物的，就請默然不語；不贊同的，請說出來。僧眾已經認可，僧眾現在分配這些衣物一事已經完成。僧眾既已認可、默然沒有異議，這件事就這樣確定下來，依此奉行。", "i": "u756", "n": 423, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第二對首者，《母論》云：四人共住一人死，三人應展轉相語云。", "t": "第二種是對首法。《毘尼母論》說：四人同住一處，其中一人死了，其餘三人應彼此輪流相對陳說，這樣說：", "i": "u757", "n": 424, "s": "第29篇　二衣"}, {"v": "卷下", "o": "二大姉憶念！此物應屬我。", "t": "「請兩位大姊憶念明記：這些物品應當歸屬於我。」", "i": "u758", "n": 425, "s": "第29篇　二衣"}, {"v": "卷下", "o": "三人共住一人死者，彼此相對互說云。", "t": "如果是三人同住而其中一人死了，剩下的兩人就彼此面對面，各自向對方說：", "i": "u759", "n": 426, "s": "第29篇　二衣"}, {"v": "卷下", "o": "大姉憶念！此物應屬我。", "t": "「大姊，請留意：這些物品應當歸我所有。」", "i": "u760", "n": 427, "s": "第29篇　二衣"}, {"v": "卷下", "o": "若有看病合賞勞者，二人和付衣鉢與亦得。", "t": "如果有看護病人而依律應當受酬賞的人，兩人一致同意，把衣缽交付給他，這樣也是可以的。", "i": "u761", "n": 428, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第三心念者，《母論》云：一相應法者，二人共住一人死者，心念口言。", "t": "第三種是心念法。《毘尼母論》說：所謂「一相應法」，就是兩人同住，其中一人死了，活著的那一人要在心裡憶念、口中說出。", "i": "u762", "n": 429, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此亡比丘尼物，應屬我。", "t": "「這是已故比丘尼的遺物，應當歸屬於我。」", "i": "u763", "n": 430, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此律云：若一人受施，應心念口言。", "t": "《四分律》說：如果只有一人受僧施，應當心裡作念、並在口中說出這樣的話。", "i": "u764", "n": 431, "s": "第29篇　二衣"}, {"v": "卷下", "o": "此是我分。」亦得。", "t": "「這是我應得的一份。」這樣說也可以。", "i": "u765", "n": 432, "s": "第29篇　二衣"}, {"v": "卷下", "o": "第十雜法者，若尼在莊園及私伽藍死者，應如寺法分之。云何名私伽藍？如在村坊聚落，俗人共造一院，唯三寶受用，白衣不通居止，兼有周帀籬牆等，即名伽藍，不要結界方號伽藍者。", "t": "第十是雜法：如果有比丘尼在莊園或私伽藍中去世，應當照寺院的辦法分配她的遺物。什麼叫私伽藍？例如在村坊聚落裡，俗人共同建造一處院落，只供三寶受用，白衣不許在其中居住，而且四周有籬笆、牆垣等圍繞，這就稱為伽藍，並不是要結了界才叫伽藍。", "i": "u766", "n": 433, "s": "第29篇　二衣"}, {"v": "卷下", "o": "若有看病尼，重物入尼本寺，輕物入現在寺。若有四人已上見亡人物者，則須羯磨分；若先無界，結已作法分；三人已下，對首分，以不同白衣家死故。", "t": "如果有為亡者看病的比丘尼，重物歸入亡者本來所屬的尼寺，輕物歸入她現在去世所在的寺院。如果有四人以上的尼眾見到亡者的遺物，就必須作羯磨來分配；如果先前沒有結界，就先結界，然後作法分配；三人以下，則用對首法分配。因為這與死在白衣家的情形不同。", "i": "u766-2", "n": 434, "s": "第29篇　二衣"}, {"v": "卷下", "o": "《十誦》：比丘衣鉢寄在尼寺者，還比丘索取分；尼寄比丘衣鉢，僧寺亦爾；若無人守掌者，事同白衣家法故。此律云：「若比丘尼無住處白衣家死，有信心檀越應掌錄此物；若有五眾出家人先來者，應與；若無來者，應送與近僧伽藍。」", "t": "《十誦律》說：比丘的衣缽寄放在尼寺，這位比丘去世後，仍由比丘索回分配；比丘尼把衣缽寄放在比丘僧寺的，也是一樣。如果沒有出家人看守掌管，事情就等同白衣家的處理辦法，所以《四分律》說：比丘尼沒有住處，在白衣家中去世，有信心的檀越應當掌管記錄這些遺物；如果有出家五眾先來，就應交給他們；如果沒有人來，就應送到鄰近的僧伽藍。", "i": "u766-3", "n": 435, "s": "第29篇　二衣"}, {"v": "卷下", "o": "義云：雖知白衣家有亡物，要須手捉目覩，作屬己之意，方得此物；反此不成，後來尼應共分。若俗人已攝屬己者，盜財義成，不得反奪；若白衣畏罪還尼者，得取。", "t": "依義理推論說：雖然知道白衣家中有亡者遺物，仍必須親手執取、親眼看見，並生起歸屬己有的心念，才算取得此物；不這樣做就不能成立，後來的比丘尼仍應共同分取。如果俗人已把遺物收歸自己所有，他盜取財物的罪就已成立，尼眾也不得反過來強行奪回；如果白衣畏懼罪業而把東西還給比丘尼，就可以接受。", "i": "u766-4", "n": 436, "s": "第29篇　二衣"}, {"v": "卷下", "o": "若僧尼一時共見亡物者，若是尼亡屬尼，僧亡屬僧，不得共攝，以各是知法人故，不須作法，直爾攝屬己意則得，不比莊寺，以彼閑預，要須作法。若僧尼前後來見者，屬先見者，得互攝取也。", "t": "如果比丘與比丘尼同時一起見到亡者遺物：是比丘尼去世的，就歸尼眾；是比丘去世的，就歸比丘僧，兩眾不得共同收取。因為僧尼各自都是懂得律法的人，所以不須作法，直接生起攝歸己有的心念就能取得。這不能與莊園、寺院相比，那裡閒暇從容，必須依法作法才行。如果比丘與比丘尼是先後來到而見到遺物，就歸先見到的一方，僧尼彼此可以互取亡者的遺物。", "i": "u766-5", "n": 437, "s": "第29篇　二衣"}, {"v": "卷下", "o": "○雜要篇第三十", "t": "第三十篇　雜項要務。", "i": "u767", "n": 438, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此篇大門有八：一、僧物，二、乞食，三、陞坐，四、就法，五、淨地，六、遇賊，七、濟生，八、雜事。", "t": "本篇大分為八門：一是僧物，二是乞食，三是陞座（升座），四是就法，五是淨地，六是遇到盜賊，七是濟生，八是雜事。", "i": "u768", "n": 439, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第一僧物者，此門有五：一、四方僧物，謂一切重物，上至羅漢，下至沙彌，盡皆有分，無有和合賣買、供給、私用，此約方為名也；二、常住僧物，謂常在此處，不可移動，四方僧來，即此處受用，此從用為名也；三、柘鬬提奢物〔舊云招提僧物是也〕，謂俗人地，別為現前僧各造私房，四方僧來，起立房舍，供給所須，此以處為名也；五、僧鬘物，謂園中華果貨得物來，此從鬘為名也。", "t": "第一，僧物。這一門分為五類：\n一、四方僧物：指一切重物（房舍、田地、園林、大型器具等粗重而不可分用的財物），上從阿羅漢、下至沙彌，人人都有分；即使僧眾和合議決，也不能買賣，不能挪作供給他人，也不能私自取用。這是約「方」而立名的。\n二、常住僧物：指恒常安置在此處、不可移動的物品，四方僧眾來了，就在這裡受用。這是從「用」而立名的。\n三、柘鬬提奢物（舊稱招提僧物）：指在俗人的土地上，另外為現前僧各別建造的私房；四方僧眾來時，也起立房舍，供給他們所須。這是就「處」而立名的。\n五、僧鬘物：指將園中的華果變賣所得的財物。這是從華鬘之「鬘」而立名的。", "i": "u769", "n": 440, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《五分》云：「僧有五種物，不可賣，不可分：一、地，二、房舍，三、須用物，四、果樹，五、華果。」", "t": "《五分律》說：僧有五種物不可出賣、不可分配：一是土地，二是房舍，三是日常需用的物品，四是果樹，五是華果。", "i": "u769-2", "n": 441, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《僧祇》云：「若僧地種果者有功，若一樹一園，聽與一熟；不能併取者，年取一枝，枝徧即止。若種瓜菜，聽與一剪。有比丘僧地作屋，上座來不與，持草木餘處去。」", "t": "《僧祇律》說：若在僧地上種植果樹，種植的人有功勞，不論是一棵樹還是一整園，都聽許給他一次成熟的果實；若不能一次全部採收，就每年採收一枝，各枝都採遍了便停止。若種的是瓜、菜，就聽許他剪收一次。又有比丘在僧地上造屋，上座來了，他不肯讓給上座，那就應該帶著草木材料遷到別處去。", "i": "u769-3", "n": 442, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第二乞食者，《見論》云：「分衛者，乞食也。三乘聖人，並皆乞食。」此律：若比丘入村乞食者，清旦洗手，著七條已，𧜼大衣著肩上，手執打露杖，在道行時常思惟善法；若見人，先問訊，言：「善來。」若近聚落，便著大衣；至於村門，應看巷陌第一門、第七門相，右手捉杖，左手持鉢，道側而行，次第乞食。若俗人送食，不得迎取，除喚往取；不得強乞，知得立待。若得食已，乃出村安鉢著地，採大衣如前進否而去。《僧祇》：若乞食時，不得語云：「與我食，得大富。」當在現處默然而立。《十誦》云：「乞食時，入三重門，至中庭三彈指，不得便去。」《僧祇》云：「迦葉發願乞食，初得施與僧尼，後得自食。」《寶梁經》云：「凡乞得食，分為四分：一分與同梵行，一分與窮不乞匃之者，第三分與諸鬼神，第四分自供身命，但念修道，於其食中不生貪染心。若乞食時，繫念威儀，終不輕躁，諦視目前，不過一尋，次第乞之。", "t": "第二、乞食。《善見律毘婆沙》說：「分衛」就是乞食，三乘的聖人都乞食。\n《四分律》說：比丘若要進村乞食，清晨先洗手，穿好七條衣，再把大衣摺疊起來搭在肩上，手裡拿著打露杖；在路上行走時，要常常思惟善法。見到人，先問訊說：「善來！」快走到村落時，就穿上大衣。到了村口，應當察看巷道，認明第一門乃至第七門的標相。右手拿杖，左手持缽，沿著路邊走，按次第挨家乞食。如果在家人送食物出來，不可以迎上前去接取，除非對方呼喚，才過去領取。不可以強行乞求；知道會得到食物，就站著等候。得到食物後，就走出村子，把缽放在地上，像先前一樣把大衣摺好搭在肩上，然後行止如法地離去。\n《摩訶僧祇律》說：乞食時，不可以說「給我食物，你就會得到大財富」這樣的話，應當在讓人看得見的地方默默地站著。《十誦律》說：乞食時，進入三重門，走到中庭，彈指三下，不可以就這樣立刻離去。《摩訶僧祇律》說：迦葉就乞食發願：最初乞得的食物，布施給僧眾和尼眾；之後乞得的，才自己吃。\n《寶梁經》說：凡是乞得的食物，分成四分：一分給同修梵行的人，一分給貧窮下賤、乞討為生的人，第三分給諸鬼神，第四分用來維持自己的身命。只一心念著修道，對這些食物不生貪婪染著的心。乞食的時候，要繫念威儀，始終不輕浮急躁，目光專注看著眼前不超過一尋的地方，按次第挨家乞食。", "i": "u770", "n": 443, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第三陞座者，《三千威儀經》云：「上座讀經，先禮佛，次禮經法及上座，後在座正坐，向上座，犍稚聲絕，先讚偈唄，如法而說。」此律不得二人同一高座說法，以相諍互求長短故。《五百問事》云：「若僧中說法，高座上無病，不得凭机。捉麈尾犯墮，非毛者得。」此律得麈尾拂開畜，不云得捉。《十誦》云：「𤛆牛尾拂，用拂佛塔故得受。」《僧祇》云：「自今已去，聽捉線拂、裂㲲、樹皮等作之，除𤛆牛尾、馬尾、金銀柄等，一切不聽捉；若白色，應染壞用，不得如婬女捉作姿作相，是名非法。」若為律師、法師敷師子座，散華著上，不拂却不得坐。《婆論》云：「不得以華香、瓔珞、莊嚴具著佛身上，得散地供養；眾僧亦爾，不得華香著漿飲食上供養眾僧。", "t": "第三是陞座。《三千威儀經》說：上座讀經時，先禮佛，其次禮經法以及上座，然後在座位上端身正坐，面向上座。集眾的犍稚聲停止後，先唱讚偈梵唄，再如法地宣說。本律規定：不得兩人同坐一個高座說法，因為會彼此諍論、互相挑剔對方的長短過失。《五百問事》說：在僧眾中說法，坐在高座上，沒有病就不得倚凭几案；手捉毛製的麈尾拂塵犯墮罪，不是毛做的才可以。本律說可得麈尾拂，那只是開許畜有，並沒有說可以執捉在手上。《十誦律》說：犛牛尾做的拂，因為用來拂拭佛塔，所以可以接受。《僧祇律》說：從今以後，聽許執捉用線、撕破的棉布、樹皮等做成的拂；至於犛牛尾、馬尾以及金銀柄等這一類，一概不許執捉；如果是白色，應當染成壞色再使用；不得像淫女那樣拿著拂擺姿作態，這樣就叫做非法。若為律師、法師鋪設師子座，座上散了花，不把花拂掉就不得坐下。《薩婆多論》說：不得把花、香、瓔珞等莊嚴具放在佛身上，可以散在地上作供養；對眾僧也是一樣（不得放在身上，只可散在地上供養），也不得把花香放在漿飲、食物上面來供養眾僧。", "i": "u771", "n": 444, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第四說法者，此律：為檀越說法，聽說契經及分別義，得不具說文句。", "t": "第四，說法。《四分律》說：為施主說法時，允許誦說契經以及分別解說其中的義理，可以不必把文句完整地說出。", "i": "u772", "n": 445, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《母論》云：「若大眾集文多，恐生疲厭者，聽諸比丘引經中要言妙詞，直顯其義，不犯。又佛法中，不貴浮華之言，語雖質朴，不失其義，令人易解者，是立意也。」", "t": "《毘尼母論》說：如果大眾集會，經文繁多，恐怕聽者生起疲倦厭煩，就聽許比丘們摘引經中的要言妙詞，直接顯明它的義理，這樣做不犯。又，佛法中不看重浮華的言語；雖然質樸，卻不失其義、令人容易理解的，這才是立言的本意。", "i": "u772-2", "n": 446, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《五分》云：「若眾樂淺不樂深，不益前人，名惡說；反此名善說。又應除貪心、不自輕心、不輕大眾心，應慈心、喜心、利益心、不動心，立此等心，乃至一四句，令前人如實解者，長夜安樂。」又諸比丘請破戒、根不具者說法，因此惡人得勢，又辱眾僧，佛言：「聽請法師、三藏者說。」", "t": "《五分律》說：如果聽眾喜歡淺顯而不喜歡深奧，卻為他們宣說深法，不能利益對方，就名為惡說；反過來，應機而說，就名為善說。又應除去貪心，不輕視自己、不輕慢大眾；應存慈心、喜心、利益心、不動心。確立這樣的心，乃至只說一個四句偈，能使對方如實理解的，就能令他在生死長夜中得到安樂。又，諸比丘請破戒、根不具足的人說法，因此惡人得勢，又羞辱了眾僧；佛說：聽許請通達三藏的法師來說法。", "i": "u772-3", "n": 447, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《涅槃經》云：「若比丘為利養故說法，所有徒眾亦傚是師，是人便自壞眾。」", "t": "《涅槃經》說：如果比丘為了利養而說法，他所有的徒眾也效法這樣的老師，這個人便自己敗壞了大眾。", "i": "u772-4", "n": 448, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《五百問事》云：「若希望心為讀經、說法得物，犯捨墮；無貪心不犯，無衣得取。」", "t": "《五百問事》說：若懷著希求貪得的心為人讀經說法，得到財物就犯捨墮；沒有貪心就不犯；沒有衣的，可以接受。", "i": "u772-5", "n": 449, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《雜阿含經》云：「一比丘得受六十新學比丘教誡、說法。」", "t": "《雜阿含經》說：一位比丘可以領受六十位新學比丘，為他們教誡說法。", "i": "u772-6", "n": 450, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《涅槃經》云：「若有受持、讀誦、書寫、宣說，莫非時、非國、不請而說，輕心、輕他、自歎、隨處而說，及滅佛法，乃至令無量人死墮地獄，則是眾生惡知識也。」", "t": "《涅槃經》說：凡有受持、讀誦、書寫、宣說的人，都不得在不合宜的時機、不合宜的國土、未經迎請的情況下宣說，也不得以輕慢心、輕視他人、自我讚歎、隨處任意而說，以及宣說滅壞佛法的話；這樣乃至使無量人死後墮入地獄，這種人就是眾生的惡知識。", "i": "u772-7", "n": 451, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《十誦》云：「有五種人問，不應為說毗尼：謂試問、無疑問、不為悔所犯故問、不受語問、詰故問，並不得答。」", "t": "《十誦律》說：有五種人來問，不應為他們說毘尼：一是試探而問，二是無疑而問，三是不為懺悔所犯而問，四是不接受勸語而問，五是故意詰難而問，這五種都不得回答。", "i": "u772-8", "n": 452, "s": "第30篇　雜要"}, {"v": "卷下", "o": "《寶梁經》云：「不教施主佛性、毗尼，此比丘賊行賊住，著衣、噉食、坐臥等皆是賊也。", "t": "《寶梁經》說：不教導施主佛性與毘尼的，這樣的比丘是賊行賊住，他的著衣、喫食、坐臥等，一切都是賊。", "i": "u772-9", "n": 453, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第五淨地者，《成實論》云：「若掃僧房一閻浮，不如掃佛塔一手掌。」《撰集百緣經》云：「掃地得五功德：一、自除心垢，二、去憍慢，三、調伏心，四、增長功德，五、得生善處。」《沙彌威儀經》云：「掃地有五法：一、不得背人，二、不得逆掃，三、即當令淨，四、不得有跡，五、當即棄却。」《無垢清淨女問經》云：「掃佛地得五福：一、自心清淨，他人見亦生淨心；二、為他愛；三、天心歡喜；四、集端正業；五、命終生善道天中。", "t": "第五門是淨地，即清掃地面。《成實論》說：即使清掃廣大如一個閻浮提的僧房地面，也比不上清掃佛塔僅一個手掌大小的地面。《撰集百緣經》說：掃地能得五種功德：一、自己除去心中的污垢；二、去除憍慢；三、調伏自心；四、增長功德；五、得以投生善處。《沙彌威儀經》說：掃地有五條法則：一、不得背對著人掃；二、不得逆向清掃；三、應當當下就把地面掃乾淨；四、不得留下痕跡；五、掃集的塵土應當立刻清除丟棄。《無垢清淨女問經》說：清掃佛地能得五種福報：一、自己內心清淨，別人見了也生起清淨心；二、被他人喜愛；三、天人心中歡喜；四、積集容貌端正的業因；五、命終之後投生善道，生於天中。", "i": "u773", "n": 454, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第六遇賊者，此律：比丘被剝，不得露身行，得罪，當以輭草、樹葉覆形，應取長衣著，知友僧中覓衣著，乞衣得已，應還本處，否者犯罪。《母論》云：「令虗發己聲，使賊去。」《僧祇》云：「若賊言『僧物何處』，不得示實處，又不得妄語，應示房舍、牀等；佛物指塔邊供具等。若道中行，有露，令年少在前；若有賊獸難，老僧在中央；欲令賊起慈心者，老僧前行。", "t": "第六、遇到盜賊。這部《四分律》說：比丘被賊剝去衣服，不可以裸露身體行走，否則犯罪；應當用軟草或樹葉遮蔽身形。應當取三衣之外多餘的長衣來穿，或向知友比丘、或到僧眾當中找衣來穿，或向人乞衣。乞得衣服之後，應把借用的衣歸還原處，不這樣做就犯罪。《毘尼母論》說：（遇賊時）應當虛張聲勢地發出喊聲，使盜賊離去。《摩訶僧祇律》說：如果賊問「僧眾的財物在哪裡？」不可以指出真正藏放的地方，但也不可以打妄語，應當指給他房舍、床座等；若問的是佛物，就指塔邊的供具等。在路上行走時若有露水，就讓年少的走在前面；若遇到盜賊、惡獸的危難，就讓老僧走在隊伍中央；若想讓賊生起慈心，就讓老僧走在前面。", "i": "u774", "n": 455, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第七濟畜生者，律中慈心解他被繫狗子、被溺豚子、解蘭若處賊繫牛等，不犯。《僧祗》云：「有神力奪賊劫人，放諸禽獸，皆慈心作者，不犯。」《十誦》云：「若悲壞羅網及獄，但犯吉羅。」《五百問事》云：「行路寄鬼神屋宿，不得有觸擾意，違者犯墮。", "t": "第七，救濟畜生。《四分律》中說：出於慈心而解開被他人拴繫的小狗、解救溺水的小豬，以及解開在阿蘭若處被盜賊拴綁的牛等，都不犯戒。《摩訶僧祇律》說：有神通力而從盜賊手中奪回被劫走的人，或放走各種飛禽走獸，凡是出於慈心而這樣做的，都不犯。《十誦律》說：若出於悲愍心而毀壞羅網與牢獄，只犯突吉羅輕罪。《五百問事》說：趕路途中借宿在鬼神的屋舍，不得存有觸犯擾亂鬼神的心意，違者犯波逸提罪。", "i": "u775", "n": 456, "s": "第30篇　雜要"}, {"v": "卷下", "o": "第八雜事者，《僧祗》云：「然火有七事無利：一、壞眼，二、壞色，三、身羸，四、衣垢，五、臥具壞，六、生犯戒緣，七、增世俗語。」", "t": "第八項是雜事。《僧祇律》說：燃火有七件事沒有利益：一是損壞眼睛，二是損壞容色，三是使身體羸弱，四是使衣服染上污垢，五是損壞臥具，六是生出犯戒的因緣，七是增長世俗雜話。", "i": "uGAP26-1", "n": 457, "s": "第30篇　雜要"}, {"v": "卷下", "o": "五百問事》云：「續佛光明，晝不得滅，佛無明暗，以本無言念齊限故，滅有罪。」大唐波頗三藏法師云：「佛前燈，以物傍取不損光者得。」", "t": "《五百問事》說：為接續佛前光明而點的燈，白天也不可以熄滅；對佛而言並沒有明與暗的分別，因為本來就沒有以言語或心念限定供燈的期限，所以熄滅它便有罪。大唐波頗三藏法師說：佛前的燈，用物件從旁邊引取燈火，只要不減損它的光明，是可以的。", "i": "uGAP26-2", "n": 458, "s": "第30篇　雜要"}, {"v": "卷下", "o": "僧祗云：「不得卒持燈入堂，唱言：『諸大德！燈欲入！』乃至滅亦爾，以手遮語之，不聽用口吹滅，應以手扇、衣角扇，當攲折頭焦。」", "t": "《僧祇律》說：不可以貿然持燈進入堂中，應當先出聲唱言：「諸大德，燈要拿進來了！」乃至熄燈時也一樣，先用手遮住燈光，出聲告知大眾。不許用口吹熄，應當用手搧或用衣角搧熄，並把燈炷燒焦的頭彎折去掉。", "i": "uGAP26-3", "n": 459, "s": "第30篇　雜要"}, {"v": "卷下", "o": "成實論》云：「出家之人，應捨五慳：一、財物慳，二、法慳，三、家慳，四、住處慳，五、稱歎慳。染著眷屬、愛樂住處故，墮迦陵伽等餓鬼中生。」", "t": "《成實論》說：出家人應當捨離五種慳吝：一是吝惜財物，二是吝惜佛法，三是吝惜施主之家，四是吝惜住處，五是吝於稱揚讚歎他人。由於染著眷屬、貪愛住處的緣故，便墮在迦陵伽等餓鬼之中受生。", "i": "uGAP26-4", "n": 460, "s": "第30篇　雜要"}, {"v": "卷下", "o": "阿含經》云：「四恩者，謂父母、師僧、國王、檀越。」四輩者，謂天、龍、人、鬼。", "t": "《阿含經》說：所謂四恩，就是父母、師長、國王、施主之恩；所謂四輩，就是天、龍、人、鬼四類。", "i": "uGAP26-5", "n": 461, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此律云：「非行來處，若有小便及洗手足時，聽著屐。」又不得裸身上廁。", "t": "《四分律》說：在不是人來往通行的僻隱之處，若要小便以及洗手洗腳時，聽許穿木屐；又不可以裸身進入廁所。", "i": "uGAP26-6", "n": 462, "s": "第30篇　雜要"}, {"v": "卷下", "o": "三千威儀經》云：「不洗大小便處，不得坐僧坐具上；上座、禮拜三寶，若禮無福，應脫袈裟、僧祇支大小便不洗大小便，不得臥僧臥具，若坐臥者吉羅。", "t": "《三千威儀經》說：凡未洗淨大小便處的人，不得坐在僧眾的坐具上，也不得禮拜上座與三寶；若禮拜，也沒有福德。應當脫下袈裟與僧祇支再大小便；不洗淨大小便處，不得躺臥僧眾的臥具，若坐若臥，都犯突吉羅。", "i": "uGAP26-7", "n": 463, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此律云：「不嚼楊枝有五過：一、口氣臰，二、不別味，三、熱陰不消，四、不別食，五、眼不明。」《五分》云：「嚼已應洗棄，以蟲食死故。又不忍辱人有五過失：一、兇惡不忍，二、後生悔恨，三、多人不愛，四、惡聲流布，五、死墮惡道。」", "t": "《四分律》說：不嚼楊枝有五種過失：一是口氣臭，二是不能辨別味道，三是熱痰不能消散，四是不能引發食慾，五是眼睛不明亮。《五分律》說：嚼完楊枝應當洗過再丟棄，因為蟲吃了它會死。又，不能忍辱的人有五種過失：一是兇惡而不能忍耐，二是事後生起悔恨，三是多數人不喜愛他，四是惡名聲四處流布，五是死後墮入惡道。", "i": "uGAP26-8", "n": 464, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此律云：「經行有五益：一、堪遠行，二、能思惟，三、少病，四、消飲食，五、得定久住。」", "t": "《四分律》說：經行有五種利益：一是能走遠路，二是能思惟，三是少病，四是消化飲食，五是所得的禪定能長久安住。", "i": "uGAP26-9", "n": 465, "s": "第30篇　雜要"}, {"v": "卷下", "o": "母論》云：「詣寺乞人無糧食者，嬰兒、獄囚、懷妊等類，施之無過。」", "t": "《毘尼母論》說：到寺院來乞求的人、沒有糧食的人、嬰兒、獄中的囚犯、懷孕的婦人等類，布施給他們並沒有過失。", "i": "uGAP26-10", "n": 466, "s": "第30篇　雜要"}, {"v": "卷下", "o": "僧祇》云：「作樂供養佛，有欲心者，即須捨去。」《增一》云：「阿闍世王信心後，無令事佛之家貲輸迎送。」《五百問事》云：「若施軍器，不須受。」", "t": "《僧祇律》說：奏伎樂供養佛時，若生起貪欲染著的心，就必須立刻捨離而去。《增一阿含經》說：阿闍世王生起信心以後，便不讓奉事佛的人家繳納賦稅、承擔迎送的差役。《五百問事》說：若有人布施兵器軍械，不須接受。", "i": "uGAP26-11", "n": 467, "s": "第30篇　雜要"}, {"v": "卷下", "o": "母論》云：「若為在家人作師，教化作福有五事：一、不應檀越舍止住，二、不繫念貪利，三、為別別說法、布施、持戒、八齋等，四、不與共娛樂，五、繫心貪利，常欲相見。又五事為檀越尊重恭敬：一、非親舊處不往反，二、不求形勢料理檀越家業，三、不共竊語令家中生疑，四、不教良時吉日祠祀鬼神，五、不過度所求。」", "t": "《毘尼母論》說：若為在家人作師父，教化他們修福，有五件事：一、不應住在施主家中；二、不繫念貪求利養；三、要為他們各別說法，講布施、持戒、八關齋等；四、不與他們一同嬉戲娛樂；五、不繫心貪求利養而常想與他們相見。另有五件事，能受到施主的尊重恭敬：一、不是親戚舊識的人家，不去往來；二、不謀求權勢去替施主打理家業；三、不與人私下竊語，使家中其他人生起猜疑；四、不教人擇良時吉日祭祀鬼神；五、不過分索求。", "i": "uGAP26-12", "n": 468, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此律：喜往白衣家有五過失：一、數見男子，二、既相見便附近，三、轉親友，四、便生欲意，五、為欲意故，或至死苦、若次死苦。", "t": "《四分律》說：喜歡常到在家人家中，有五種過失：一、常常見到男子；二、相見之後便去親近；三、漸漸成為親密的朋友；四、因而生起淫欲之心；五、為了這欲心的緣故，或招致喪命之苦，或招致僅次於喪命的苦。", "i": "uGAP26-13", "n": 469, "s": "第30篇　雜要"}, {"v": "卷下", "o": "地持》云：「若見眾生，當即慰問，舒顏先語，平視和色，正念在前。」此律：若白衣嚏者，呪願長壽。《僧祇》云：「聽畜甎瓦擬揩脚。」《母論》云：「寒處聽著俗人鞾。」《五分》云：「作鞾䩺太深，聽齊踝上。」《母論》云：「何以脫革屣遶佛行者？以生俗人訶言、起嫌慢心故。」", "t": "《菩薩地持經》說：見到眾生時，應當立即慰問，舒展面容先開口說話，目光平視、神色溫和，正念在前。《四分律》說：若在家人打噴嚏，應當為他咒願長壽。《僧祇律》說：聽許畜存磚塊瓦片，用來搓擦腳部。《毘尼母論》說：寒冷的地方，聽許穿俗人的靴子。《五分律》說：做靴子時，靴筒不可做得太深高，只聽許到腳踝之上。《毘尼母論》說：為什麼要脫下皮鞋才繞佛而行呢？因為穿著鞋繞佛會招來世俗人的譏呵言語，使他們生起嫌惡輕慢的心。", "i": "uGAP26-14", "n": 470, "s": "第30篇　雜要"}, {"v": "卷下", "o": "此律令僧畜斗、解、升、合及秤。若住房內臰者，以香泥，乃至以四角懸香。《僧祇》云：「浴時，不病人揩者，越。」《母論》云：「洗浴不為令嚴身淨潔故，但令除身中風冷，得安隱行道；當為厭患身法、調伏心法，應生慈心，為得少欲知足故。」此律：若營事人作房成就，莊嚴、香熏、所須具足者，與房住九十日一移，更不得受餘房；若人能治房者，白二與之。", "t": "《四分律》中，佛聽許僧眾畜有斗、斛、升、合等量器以及秤。若所住的房內有臭氣，可用香泥塗敷，乃至在房間四角懸掛香。《僧祇律》說：洗浴時，沒有病卻讓人替自己搓摩身體的，犯越毘尼罪。《毘尼母論》說：洗浴不是為了裝飾身體、使它潔淨美好，只是為了除去身中的風冷之患，使自己能安穩地行道；應當把洗浴當作厭患此身之法、調伏自心之法，並應生起慈心，為的是成就少欲知足。《四分律》說：負責營建事務的人把房舍建造完成，房舍莊嚴、用香熏過、所需之物一應齊全，就把這間房交給營事人居住，每九十天遷移一次，此外不得再領受其餘的房舍。若有人能修治房舍，就以白二羯磨把房舍交給他。", "i": "uGAP26-15", "n": 471, "s": "第30篇　雜要"}, {"v": "卷下", "o": "五分》云：「若月直監食人欲知生熟、酸鹹者，得貯掌中䑛甞之。」《齋法經》云不許甞，謂貪心甞也。", "t": "《五分律》說：當月輪值、監管飲食的人，若想知道食物是生是熟、是酸是鹹，可以把食物放在手掌中舔嚐。《齋法經》說不准嚐，那是指懷著貪心去嚐味而說的。", "i": "uGAP26-16", "n": 472, "s": "第30篇　雜要"}, {"v": "卷下", "o": "大五濁經》云：「佛涅槃後，當有五亂：一者，當來比丘從白衣學法，世之一亂；二者，白衣坐上，比丘處下，世之二亂；三者，比丘說法不行承受，白衣說法以為無上，世之三亂；四者，魔家比丘自生現在於世間，以為其道諦，自不明，詐為信，世之四亂；五者，當來比丘畜養妻子、奴僕、治生、販賣、諍訟，不承佛教，世之五亂", "t": "《大五濁經》說：佛涅槃之後，將出現五種亂象。第一，將來的比丘向在家人學法，這是世間第一種亂象。第二，在家人坐在上位，比丘反而處在下位，這是世間第二種亂象。第三，比丘說法，人們不肯奉行領受；在家人說法，卻被認為是無上的，這是世間第三種亂象。第四，魔家的比丘自行出現在當世，在世間自以為所行的就是道諦真理，自己其實並不明瞭，卻詐現為可信的樣子，這是世間第四種亂象。第五，將來的比丘畜養妻子、奴僕，經營生計、販賣牟利，起諍興訟，不遵承佛的教法，這是世間第五種亂象。", "i": "uGAP26-17", "n": 473, "s": "第30篇　雜要"}, {"v": "卷下", "o": "不得塔院內染、曬衣、著華屣、涕唾。", "t": "不得在塔院內染衣、曬衣、穿華美的鞋履，也不得在塔院內擤鼻涕、吐唾沫。", "i": "uGAP26-18", "n": 474, "s": "第30篇　雜要"}, {"v": "卷下", "o": "見論》云：「頭陁者，抖擻。」《智論》云：「以無生法忍為頭陀，菩薩住於煩惱，觀無上法忍，是上頭陀。」或有經云：「頭者少欲，陀者知足。」西云阿蘭若，東云空閑處。《雜心論》云：「知足於現在處起難，少欲於未來轉生易。」《涅槃經》云：「於未得之財不生貪，名少欲；於已得之財不生貪，名知足。知足是現在，少欲是未來。又少欲猶有欲，知足更無欲。", "t": "《善見律毘婆沙》說：「頭陀」的意思就是抖擻，即抖落去除煩惱。《大智度論》說：以無生法忍為頭陀；菩薩住在煩惱之中，卻能觀照無上法忍，這是上等的頭陀。有的經中說：「頭」是少欲，「陀」是知足。印度稱為「阿蘭若」，中國譯為「空閑處」。《雜心論》說：知足是緣於現前之境而生起的，難以生起；少欲是緣於未來之境而轉起的，容易生起。《涅槃經》說：對尚未得到的財物不生貪求，叫作少欲；對已經得到的財物不生貪求，叫作知足。知足是就現在而說，少欲是就未來而說。再者，少欲仍然有欲，知足則再也沒有欲求。", "i": "uGAP26-19", "n": 475, "s": "第30篇　雜要"}, {"v": "卷下", "o": "No. 724-B 䟦比丘尼鈔後", "t": "編號724-B：跋《比丘尼鈔》後", "i": "u776", "n": 476, "s": "第30篇　雜要"}, {"v": "卷下", "o": "葢夫佛教興行，則僧尼之異途不可不知，故我大師示僧撰《事鈔》等三大部，示尼撰此書三卷也。於是律燈稍熾，後世揭其焰者巍巍於宇內，所以祖訓之存也。雖然，不覩有此書，而尼眾之信油欲漏，戒光隨減。余自蚤游眼律部，纔覩此書之在，歡喜頂戴，攤是机上，卒多蠧損，首尾不全。頃日禮誦之間，考大部之文，茲補茲正，且傍加和訓，為便新學也。讀者乞子細覃研，僧尼別行，顯然易通。今鋟梓于書林某氏，以廣其傳，惟願開卷舉目，直入薩婆若海，續佛慧命無窮，斯余志願滿矣！或謂：「此《四分律比丘尼鈔》者，唐道世律師述也。」不然，彼知其題目之同，不知卷數之異也。", "t": "大凡佛教要興盛推行，僧眾與尼眾在行持上各有不同的途徑，這一點不能不知道。所以我們的大師為僧眾開示，撰成《行事鈔》等三大部；為尼眾開示，撰成這部三卷的書。從此律法的燈火漸漸熾盛，後世高舉這燈焰的人，巍然崇隆於天下之間——這就是祖師的訓誨得以存留的緣由。雖然如此，倘若見不到這部書流傳，尼眾信心的燈油就要漏失，戒行的光明也隨之減弱。我從早年就瀏覽律部典籍，才見到這部書仍然存在，歡喜地頂戴受持，把它攤放在書桌上，卻發現多有蟲蛀破損，開頭與結尾都殘缺不全。近來在禮佛誦經的空閒，我考察三大部的文句，就此加以補足、加以校正，並且在旁邊添上和訓，以便利初學的人。懇請讀者仔細深入研求，那麼僧眾與尼眾各自不同的行持規範，就清楚明白、容易通曉了。如今交付書肆某氏雕板刊印，使它廣為流傳。只願讀者開卷一看，便直入薩婆若之海，使佛的慧命延續無窮——這樣我的心願就圓滿了。有人說這部《四分律比丘尼鈔》是唐代道世律師所撰述的。其實不然：那些人只知道書名相同，卻不知道卷數有別。", "i": "u777", "n": 477, "s": "第30篇　雜要"}, {"v": "卷下", "o": "貞享改元甲子，覺皇降誕日，終南山末葉小比丘永雅操觚于京北密嚴律菴", "t": "貞享改元的甲子年，正值佛陀誕辰之日，終南山律宗後學的小比丘永雅，在京都北邊的密嚴律菴提筆寫成此文。", "i": "u778", "n": 478, "s": "第30篇　雜要"}]};